window.STEPS=Object.assign(window.STEPS||{},{"ns-16e15965cf78":{"길":"두 삼각형이 닮음임을 보이고 비례식을 세워 이차방정식으로 BE를 구한다","단계":[{"제목":"닮음 관계 찾기","힌트":"∠A=∠D=∠CPE이고 이등변삼각형이라면?","식":[],"설명":"삼각형 ABE와 PBA는 이등변삼각형이며 ∠PAB=∠AEB이므로 두 삼각형은 닮음이다.","확인":null,"스킬":"S1"},{"제목":"비례식 세우기","고비":true,"힌트":"BE=x, PA=x-2라 하면 비례식은?","식":["$x:2=2:(x-2)$"],"설명":"닮음비로 비례식을 세운다.","확인":null,"스킬":"S1"},{"제목":"이차방정식 풀기","힌트":"x²-2x-4=0을 근의 공식으로 풀면?","식":["$x^2-2x-4=0$","$x=1\\pm\\sqrt5$"],"설명":"근의 공식으로 풀면 x=1±√5이다.","확인":null,"스킬":"A6"},{"제목":"조건에 맞는 값 택하기","힌트":"x>0이므로 BE는?","식":["$x=1+\\sqrt5$"],"설명":"x>0이므로 BE=1+√5이다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-1f3ccc0140fc":{"길":"a1을 구하고 역수의 소수부분으로 a2를 구해 주기 2를 찾아 100개의 합을 계산한다","단계":[{"제목":"a1 구하기","힌트":"2<√6<3이므로 소수부분은?","식":["$a_{1}=\\sqrt{6}-2$"],"설명":"√6의 정수부분 2를 빼 소수부분을 구한다.","확인":null,"스킬":"N7"},{"제목":"a2 구하기","힌트":"1/a1을 유리화하면?","식":["$\\frac{1}{\\sqrt{6}-2}=\\frac{\\sqrt{6}+2}{2}$"],"설명":"유리화한 값의 소수부분 a2=(√6-2)/2를 얻는다.","확인":null,"스킬":"N6"},{"제목":"a3에서 주기 확인하기","고비":true,"힌트":"1/a2를 유리화하면 다시 a1이 나올까?","식":["$\\frac{2}{\\sqrt{6}-2}=\\sqrt{6}+2\\Rightarrow a_{3}=\\sqrt{6}-2$"],"설명":"a3=a1이 되어 항이 두 개씩 반복되는 주기가 확인된다.","확인":null,"스킬":"P7"},{"제목":"100개 항의 합 세우기","힌트":"a1과 a2가 각각 몇 번씩 나올까?","식":["$50(\\sqrt{6}-2)+50\\left(\\frac{\\sqrt{6}-2}{2}\\right)=-150+75\\sqrt{6}$"],"설명":"a1, a2가 각 50번씩 더해져 -150+75√6이 된다.","확인":null,"스킬":"P6"},{"제목":"q-p 계산하기","힌트":"p=-150, q=75라면?","식":["$q-p=75-(-150)=225$"],"설명":"q-p=225이다.","확인":"225","스킬":"A3"}],"fb":"fig/ns/"},"ns-85b61aa86371":{"길":"√6의 범위로 [x]를 구하고 분모를 유리화한 뒤 범위를 좁혀 가우스값을 구한다","단계":[{"제목":"[x] 구하기","힌트":"√6은 몇과 몇 사이일까?","식":["$2<\\sqrt6<3$","$1<x<2$"],"설명":"2²<6<3²이므로 2<√6<3이고 x=√6-1은 1과 2 사이이므로 [x]=1이다.","확인":"1","스킬":"N7"},{"제목":"분모 유리화하기","힌트":"1/(√6-2)의 분모를 유리화하면?","식":["$\\frac1{\\sqrt6-2}=\\frac{\\sqrt6+2}2$"],"설명":"분모, 분자에 √6+2를 곱해 유리화한다.","확인":null,"스킬":"N6"},{"제목":"범위를 좁혀 가우스값 구하기","고비":true,"힌트":"√6+2는 몇과 몇 사이일까?","식":["$4<\\sqrt6+2<5$","$2<\\frac{\\sqrt6+2}2<3$"],"설명":"2<√6<3이므로 4<√6+2<5이고 2로 나누면 2와 3 사이이므로 가우스값은 2이다.","확인":"2","스킬":"N7"}],"fb":"fig/ns/"},"ns-441425e4be31":{"길":"넓이가 최대가 되는 점 P의 위치를 기하학적으로 찾아 피타고라스로 BP를 구한다","단계":[{"제목":"넓이 최대 조건 찾기","고비":true,"힌트":"밑변 AB가 고정일 때 높이가 최대가 되려면 점 P는 어디에 있어야 할까?","식":[],"설명":"삼각형 ABP의 넓이가 최대가 되려면 점 P에서 직선 OA까지의 거리(높이)가 최대여야 하므로, 반지름 OP가 OA와 수직일 때이다.","확인":null,"스킬":"S2"},{"제목":"OP=4, ∠BOP=90° 확인하기","힌트":"원의 반지름은 모두 같으므로 OP는?","식":["$\\overline{OP}=4,\\ \\angle BOP=90^{\\circ}$"],"설명":"P는 원 위의 점이므로 OP=4이고, 이때 ∠BOP=90°이다.","확인":null,"스킬":"S13"},{"제목":"BP 구하기","힌트":"직각삼각형 OBP에서 피타고라스 정리를 쓰면?","식":["$\\overline{BP}^2=3^2+4^2=25$","$\\overline{BP}=5$"],"설명":"직각삼각형 OBP에서 BP²=OB²+OP²=25이므로 BP=5이다.","확인":"5","스킬":"S3"},{"제목":"cosθ 구하기","힌트":"cosθ=OB/BP는?","식":["$\\cos\\theta=\\frac{3}{5}$"],"설명":"직각삼각형 OBP에서 cosθ=OB/BP=3/5이다.","확인":"3/5","스킬":"S6"}],"fb":"fig/ns/"},"ns-462222fb033e":{"길":"반지름을 1로 두고 부채꼴 내접원의 반지름과 호·현의 중점을 잇는 원의 반지름을 각각 구해 비를 낸다","단계":[{"제목":"직각삼각형에서 삼각비 구하기","힌트":"AB가 지름이므로 ∠APB는?","식":["$\\overline{AP}=8,\\ \\overline{BP}=6$","$\\cos\\theta=\\frac{4}{5},\\ \\sin\\theta=\\frac{3}{5}$"],"설명":"AB가 지름이므로 ∠APB=90°이고, ∠BAP=θ라 하면 직각삼각형에서 cosθ, sinθ를 구한다.","확인":null,"스킬":"S6"},{"제목":"중심각을 원주각의 2배로 놓기","힌트":"∠BOP은 ∠BAP의 몇 배일까?","식":["$\\angle BOP=2\\theta$"],"설명":"호 BP에 대한 중심각은 원주각의 2배이므로 ∠BOP=2θ이다.","확인":null,"스킬":"S5"},{"제목":"부채꼴 내접원의 반지름 r1 구하기","고비":true,"힌트":"반지름을 1로 두면 내접원 중심까지 거리는 r1/sinθ, 이를 반지름 관계식에 넣으면?","식":["$r_{1}+\\frac{r_{1}}{\\sin\\theta}=1$","$r_{1}=\\frac{3}{8}$"],"설명":"반지름 1인 부채꼴 OBP에 내접하는 원의 중심까지 거리가 r1/sinθ이므로 r1+r1/sinθ=1에서 r1=3/8을 얻는다.","확인":null,"스킬":"S13"},{"제목":"현 AP까지의 거리 구하기","힌트":"중심 O에서 현 AP까지의 거리는 sinθ와 어떤 관계일까?","식":["$\\overline{OD}=\\sin\\theta=\\frac{3}{5}$"],"설명":"중심에서 현 AP에 내린 수선의 발을 D라 하면 OD=sinθ이다.","확인":null,"스킬":"S13"},{"제목":"r2 구하기","힌트":"호 AP의 중점과 현의 중점을 잇는 지름의 길이는?","식":["$2r_{2}=1-\\overline{OD}$","$r_{2}=\\frac{1}{5}$"],"설명":"호의 중점(중심에서 거리 1인 점)에서 현의 중점(중심에서 거리 sinθ인 점)까지가 지름이므로 2r2=1-sinθ에서 r2=1/5이다.","확인":null,"스킬":"S13"},{"제목":"비율 계산하기","힌트":"r1/r2를 계산하면?","식":["$\\frac{r_{1}}{r_{2}}=\\frac{3/8}{1/5}=\\frac{15}{8}$"],"설명":"두 값을 나누면 r1/r2=15/8이다.","확인":"15/8","스킬":"S13"}],"fb":"fig/ns/"},"ns-225671cb6141":{"길":"배달된 직육면체의 부피를 식으로 쓰고 전개해 부피 차를 구한 뒤 할인 규칙에 맞게 금액을 계산한다","단계":[{"제목":"부피의 차 구하기","힌트":"주문한 부피 $10a^{2}$ 와 가로 $(a+3)$, 세로 $(a-3)$ 인 직육면체의 부피를 비교하면 얼마나 차이 나는가?","식":["$10(a+3)(a-3)=10a^{2}-90$","$10a^{2}-(10a^{2}-90)=90\\ (\\mathrm{cm}^{3})$"],"설명":"배달된 케이크의 부피는 $10(a+3)(a-3)=10(a^{2}-9)$ 이므로 주문한 부피보다 $90\\mathrm{cm}^{3}$ 적다.","확인":"90","스킬":"C7","고비":true},{"제목":"할인 금액 구하기","힌트":"부피가 $90\\mathrm{cm}^{3}$ 적으면 $70\\mathrm{cm}^{3}$ 이상 차이 나는 경우에 해당하는가?","식":["$90\\times200=18000$","$18000+5000=23000$"],"설명":"$1\\mathrm{cm}^{3}$ 당 $200$ 원씩 할인하고, 차이가 $70\\mathrm{cm}^{3}$ 이상이므로 추가로 $5000$ 원을 더 할인한다.","확인":"23000","스킬":"C7","고비":false},{"제목":"지불 금액","힌트":"주문 금액에서 할인 금액을 빼면?","식":["$40000-23000=17000$"],"설명":"주문 금액은 $4$ 만원이다.","확인":"17000","스킬":"C7","고비":false}],"fb":"fig/ns/"},"ns-b3267ae65c01":{"길":"처음과 변경 후 면적을 가로와 세로의 곱의 합으로 세우고 빼서 남는 항만 모은다","단계":[{"제목":"처음 면적 세우기","힌트":"스탠딩석과 지정석의 가로는 같다. 관람석 전체의 넓이를 어떻게 쓸 수 있을까?","식":["$A=x(2y+3z)$","$A=2xy+3xz$"],"설명":"두 구역의 가로가 모두 $x$이므로 전체는 가로 $x$, 세로 $2y+3z$인 직사각형이다.","확인":null,"스킬":"C7"},{"제목":"변경 후 면적 세우기","힌트":"구역마다 바뀐 가로와 세로를 쓰고 두 직사각형의 넓이를 더하면?","식":["$B=(x+10)(2y-7)+x(3z+15)$","$B=2xy+8x+20y+3xz-70$"],"설명":"스탠딩석은 가로 $x+10$, 세로 $2y-7$이고 지정석은 가로 $x$, 세로 $3z+15$이다. 전개한 뒤 동류항끼리 합한다.","확인":null,"스킬":"C7","고비":true},{"제목":"$A-B$ 계산하기","힌트":"두 식을 빼면 어떤 항이 없어질까?","식":["$A-B=-8x-20y+70$"],"설명":"$xy$항과 $xz$항이 없어지고 $x$항, $y$항, 상수항만 남는다. 따라서 정답은 ③이다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-159a935b2614":{"길":"보기를 하나씩 곱셈공식으로 전개하거나 계산해 옳고 그름을 가른다","단계":[{"제목":"ㄱ과 ㄴ 판정","힌트":"ㄱ의 좌변을 완전제곱식 공식으로 전개하고, ㄴ의 두 변의 부호를 비교하면?","식":["$(2x-\\frac{1}{3})^2=4x^2-\\frac{4}{3}x+\\frac{1}{9}$","$(-x-1)^2=(x+1)^2$"],"설명":"ㄱ은 $(a-b)^2=a^2-2ab+b^2$으로 전개한 값과 같아 옳다. ㄴ의 우변 $(-x-1)^2$은 $(x+1)^2$이고 좌변은 $-(x+1)^2$이므로 부호가 반대라 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 판정","힌트":"$1+\\frac{1}{3}$ 앞에 $1-\\frac{1}{3}$을 곱하고 나누어 합차 공식을 반복하면 곱은 얼마일까?","식":["$(1-a)(1+a)=1-a^2$","$\\dfrac{3}{2}\\left(1-\\dfrac{1}{3^{16}}\\right)$"],"설명":"$\\left(1-\\dfrac{1}{3}\\right)$를 곱하면 합차 공식이 차례로 적용되어 $1-\\dfrac{1}{3^{16}}$이 된다. 곱한 만큼 $\\dfrac{3}{2}$를 곱해야 하므로 곱은 $\\dfrac{3}{2}\\left(1-\\dfrac{1}{3^{16}}\\right)$이다. 보기의 $\\dfrac{2}{3}$와 다르므로 옳지 않다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄹ과 ㅁ 판정","힌트":"ㄹ은 합차 공식을, ㅁ은 $x-1$을 한 문자로 보고 전개하면?","식":["$(1000+1)^2-(1000-1)^2=4\\times1000$","$(x-1+y)(x-1+2y)$"],"설명":"ㄹ은 $(a+b)^2-(a-b)^2=4ab$이므로 $4\\times1000=4000$이라 옳다. ㅁ은 $x-1=m$으로 놓으면 $m^2+3my+2y^2$이고, 이를 원래 식으로 되돌리면 보기의 전개식과 같아 옳다.","확인":null,"스킬":"C3"},{"제목":"옳은 보기의 개수","힌트":"옳은 보기를 모두 세면?","식":["$\\text{ㄱ, ㄹ, ㅁ}$"],"설명":"옳은 것은 ㄱ, ㄹ, ㅁ이므로 $3$개이다.","확인":"3","스킬":"C3"}],"fb":"fig/ns/"},"ns-00d4163e4f8a":{"길":"같은 길이의 호에 놓인 원주각을 a, b 로 두고 외각의 성질로 삼각형 CMN 이 이등변삼각형임을 보인다","단계":[{"제목":"같은 호의 원주각을 문자로 두기","힌트":"호 $\\overset{\\frown}{AD}$ 와 $\\overset{\\frown}{DC}$ 의 길이가 같으면 그 호에 대한 원주각은 어떤 관계일까?","식":["$\\angle ACD=\\angle CED=a$","$\\angle BCE=\\angle CDE=b$"],"설명":"호 $\\overset{\\frown}{AD}$ 와 $\\overset{\\frown}{DC}$ 의 길이가 같으므로 $\\angle ACD$ 와 $\\angle CED$ 의 크기가 같고, 호 $\\overset{\\frown}{BE}$ 와 $\\overset{\\frown}{EC}$ 의 길이가 같으므로 $\\angle BCE$ 와 $\\angle CDE$ 의 크기가 같다. 같은 길이의 호에 대한 원주각은 크기가 같다.","확인":null,"스킬":"S5"},{"제목":"삼각형 CDM 의 외각 구하기","고비":true,"힌트":"삼각형 CDM 에서 점 M 의 외각은 이웃하지 않는 두 내각과 어떤 관계일까?","식":["$\\angle CMN=\\angle MCD+\\angle CDM=a+b$"],"설명":"삼각형 CDM 에서 $\\angle MCD=a$, $\\angle CDM=b$ 이다. 세 점 D, M, N 이 한 직선 위에 있으므로 $\\angle CMN$ 은 점 M 의 외각이고, 외각의 크기는 이웃하지 않는 두 내각의 합이다.","확인":null,"스킬":"S10"},{"제목":"삼각형 CEN 의 외각 구하기","힌트":"삼각형 CEN 에서 점 N 의 외각도 같은 방법으로 나타내면?","식":["$\\angle CNM=\\angle CEN+\\angle NCE=a+b$","$\\angle CMN=\\angle CNM$"],"설명":"삼각형 CEN 에서 $\\angle CEN=a$, $\\angle NCE=b$ 이고 $\\angle CNM$ 은 점 N 의 외각이므로 두 내각의 합 $a+b$ 이다. 따라서 $\\angle CMN=\\angle CNM$ 이다.","확인":null,"스킬":"S10"},{"제목":"이등변삼각형의 밑각 구하기","힌트":"삼각형 CMN 의 두 밑각이 같다면 꼭지각 $41^{\\circ}$ 에서 밑각을 어떻게 구할까?","식":["$\\angle CNM=\\frac{1}{2}\\times(180^{\\circ}-41^{\\circ})=69.5^{\\circ}$"],"설명":"삼각형 CMN 은 $\\angle CMN=\\angle CNM$ 인 이등변삼각형이므로 세 각의 합 $180^{\\circ}$ 에서 꼭지각 $\\angle MCN=41^{\\circ}$ 를 뺀 값의 절반이 $\\angle CNM$ 이다.","확인":"69.5","스킬":"S10"}],"fb":"fig/ns/"},"ns-0285578506f8":{"길":"중점을 이은 정사각형의 넓이로 한 변의 길이를 구해 둘레가 유리수인 그림을 찾는다","단계":[{"제목":"중점을 이은 정사각형의 넓이","고비":true,"힌트":"정사각형 ABCD 의 네 모서리에서 잘려 나가는 삼각형 네 개의 넓이는 합쳐서 어떤 관계일까?","식":["$\\square ABCD=8$","$\\square EFGH=8\\times\\frac{1}{2}=4$"],"설명":"네 변의 중점을 이으면 모서리에서 합동인 직각이등변삼각형 네 개가 잘려 나가고, 이 삼각형들의 넓이의 합은 정사각형 ABCD 의 절반이다. 따라서 $\\square EFGH=4$ 이다.","확인":null,"스킬":"S12"},{"제목":"정사각형 EFGH 의 한 변","힌트":"넓이가 $4$ 인 정사각형의 한 변의 길이는?","식":["$\\overline{EH}=\\overline{EF}=2$"],"설명":"정사각형 EFGH 의 넓이가 $4$ 이므로 한 변의 길이는 $2$ 이다. 한 변의 길이가 자연수이므로 이 변으로만 둘러싸인 도형의 둘레는 유리수이다.","확인":"2","스킬":"N8"},{"제목":"그림 ② 의 둘레","힌트":"그림 ② 의 둘레는 정사각형 EFGH 의 변 몇 개로 이루어질까?","식":["$2\\times4=8$"],"설명":"그림 ② 는 정사각형 EFGH 모양이므로 둘레는 $2\\times4=8$ 이고 유리수이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-03f7a875318c":{"길":"삼각비로 두 변을 구하고 내심에서 나눈 세 삼각형의 넓이의 합으로 내접원의 반지름 식을 세운다","단계":[{"제목":"나머지 두 변 구하기","힌트":"각 B 가 $60^{\\circ}$ 이고 $\\overline{BC}$ 가 주어졌을 때 $\\overline{AC}$ 와 $\\overline{AB}$ 는 어떤 삼각비로 구할까?","식":["$\\overline{AC}=3\\tan60^{\\circ}=3\\sqrt{3}$","$\\overline{AB}=\\frac{3}{\\cos60^{\\circ}}=6$"],"설명":"직각삼각형에서 $\\tan$ 는 밑변에 대한 높이의 비이므로 $\\overline{AC}$ 는 $\\overline{BC}$ 에 $\\tan60^{\\circ}$ 를 곱한 값이다. $\\cos$ 는 빗변에 대한 밑변의 비이므로 $\\overline{AB}$ 는 $\\overline{BC}$ 를 $\\cos60^{\\circ}$ 로 나눈 값이다.","확인":null,"스킬":"S6"},{"제목":"넓이를 두 가지로 나타내기","고비":true,"힌트":"내심 I 에서 세 변에 내린 수선의 길이는 모두 $r$ 이다. 삼각형 ABC 의 넓이를 세 삼각형 IAB, IBC, IAC 로 나누어 쓰면?","식":["$\\frac{1}{2}\\times3\\times3\\sqrt{3}=\\frac{1}{2}r(6+3+3\\sqrt{3})$"],"설명":"내접원의 반지름 $r$ 은 내심에서 각 변에 내린 수선의 길이이므로 세 삼각형 IAB, IBC, IAC 의 높이가 된다. 삼각형 ABC 의 넓이를 밑변과 높이로 구한 값은 세 삼각형의 넓이의 합과 같다.","확인":null,"스킬":"S8"},{"제목":"r 에 대한 식 풀기","힌트":"양변에 $2$ 를 곱하고 $r$ 이 든 항을 한쪽으로 모으면?","식":["$(9+3\\sqrt{3})r=9\\sqrt{3}$","$r=\\frac{3\\sqrt{3}}{3+\\sqrt{3}}$"],"설명":"양변에 $2$ 를 곱하면 $(9+3\\sqrt{3})r=9\\sqrt{3}$ 이고, 양변을 $3$ 으로 나누면 $r=\\frac{3\\sqrt{3}}{3+\\sqrt{3}}$ 이다.","확인":null,"스킬":"S8"},{"제목":"분모 유리화","힌트":"분모에 근호가 있으니 어떤 수를 분모와 분자에 곱해 근호를 없앨까?","식":["$r=\\frac{\\sqrt{3}(3-\\sqrt{3})}{2}=\\frac{3\\sqrt{3}-3}{2}$"],"설명":"분모와 분자에 $3-\\sqrt{3}$ 을 곱해 분모를 유리화하면 $r=\\frac{3\\sqrt{3}-3}{2}$ 이다.","확인":null,"스킬":"S8"}],"fb":"fig/ns/"},"ns-061a926d20e9":{"길":"잘라 낸 사각뿔과 처음 사각뿔의 닮음비로 부피비를 구하고 처음 부피에서 남은 비율만큼 계산한다","단계":[{"제목":"닮음비와 부피비","고비":true,"힌트":"잘라 낸 뿔과 처음 뿔의 높이의 비가 $1:3$ 이면 부피의 비는 어떻게 될까?","식":["$1^{3}:3^{3}=1:27$"],"설명":"잘라 낸 사각뿔은 처음 사각뿔과 닮음이고 닮음비가 $1:3$ 이므로 부피의 비는 닮음비를 세제곱한 $1:27$ 이다.","확인":null,"스킬":"S1"},{"제목":"처음 사각뿔의 부피","힌트":"밑넓이와 높이로 뿔의 부피를 구하면?","식":["$\\frac{1}{3}\\times\\sqrt{18}\\times\\sqrt{20}\\times\\sqrt{45}=\\frac{1}{3}\\times3\\sqrt{2}\\times2\\sqrt{5}\\times3\\sqrt{5}=30\\sqrt{2}$"],"설명":"뿔의 부피는 밑넓이와 높이의 곱의 $\\frac{1}{3}$ 이다. $\\sqrt{18}=3\\sqrt{2}$, $\\sqrt{20}=2\\sqrt{5}$, $\\sqrt{45}=3\\sqrt{5}$ 로 바꿔 곱한다.","확인":null,"스킬":"S1"},{"제목":"남은 입체도형의 부피","힌트":"남은 부분은 처음 뿔 부피의 몇 분의 몇일까?","식":["$\\frac{26}{27}\\times30\\sqrt{2}=\\frac{260\\sqrt{2}}{9}$"],"설명":"처음 뿔의 부피를 $27$ 로 보면 잘라 낸 뿔이 $1$ 이므로 남은 부분은 $26$ 이다. 따라서 처음 부피의 $\\frac{26}{27}$ 이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-06b1e9ec39d3":{"길":"접기 대칭으로 중심에서 현까지의 거리를 구해 중심각을 정하고 색칠한 부분을 활꼴의 넓이로 계산한다","단계":[{"제목":"중심에서 현까지의 거리","고비":true,"힌트":"접힌 호가 중심 O 를 지나려면 O 에서 현 AB 까지의 거리는 반지름과 어떤 관계일까?","식":["$\\overline{OH}=\\frac{1}{2}\\times6=3$"],"설명":"O 에서 현 AB 에 내린 수선의 발을 H 라 한다. 현 AB 를 접는 선으로 접으면 O 와 겹치는 점은 접기 전 호 위에서 O 와 가장 멀리 떨어진 점으로 거리가 반지름 $6$ 이다. H 는 O 와 그 점의 가운데이므로 $\\overline{OH}$ 는 반지름의 절반인 $3$ 이다.","확인":null,"스킬":"S2"},{"제목":"중심각 구하기","힌트":"직각삼각형 OAH 에서 빗변과 한 변의 비가 $2:1$ 이면 $\\angle OAH$ 는?","식":["$\\overline{OA}:\\overline{OH}=2:1$","$\\angle OAH=30^{\\circ},\\ \\angle AOH=60^{\\circ}$","$\\angle AOB=2\\times60^{\\circ}=120^{\\circ}$"],"설명":"직각삼각형 OAH 에서 빗변이 한 변의 $2$ 배이므로 $\\angle OAH=30^{\\circ}$, $\\angle AOH=60^{\\circ}$ 이다. 삼각형 AOH 와 BOH 는 RHS 합동이라 $\\angle AOB$ 는 $\\angle AOH$ 의 $2$ 배인 $120^{\\circ}$ 이다.","확인":null,"스킬":"S6"},{"제목":"색칠한 부분의 모양 바꾸기","힌트":"접힌 부분은 접기 전 도형과 넓이가 같다. 접기 전에 색칠한 부분은 어떤 도형이었을까?","식":["$(\\text{색칠한 부분})=(\\text{부채꼴 }AOB)-\\triangle AOB$"],"설명":"색칠한 부분은 현 AB 와 접기 전 호 AB 로 둘러싸인 활꼴과 합동이다. 활꼴의 넓이는 부채꼴 AOB 의 넓이에서 삼각형 AOB 의 넓이를 뺀 것이다.","확인":null,"스킬":"S12"},{"제목":"넓이 계산","힌트":"부채꼴은 반지름과 중심각으로, 삼각형은 두 변과 끼인각으로 넓이를 구하면?","식":["$\\pi\\times6^{2}\\times\\frac{120^{\\circ}}{360^{\\circ}}=12\\pi$","$\\frac{1}{2}\\times6\\times6\\times\\sin(180^{\\circ}-120^{\\circ})=9\\sqrt{3}$","$12\\pi-9\\sqrt{3}$"],"설명":"부채꼴 AOB 의 넓이는 $12\\pi$ 이다. 삼각형 AOB 는 두 변이 $6$, $6$ 이고 끼인각이 $120^{\\circ}$ 이므로 $\\sin(180^{\\circ}-120^{\\circ})=\\sin60^{\\circ}$ 를 써서 넓이 $9\\sqrt{3}$ 을 얻는다. 따라서 색칠한 부분의 넓이는 $12\\pi-9\\sqrt{3}$ 이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-0e66b2a062a5":{"길":"원 O′ 의 내접사각형으로 각을 옮기고 원 O 의 접선과 현이 이루는 각으로 보기를 하나씩 가린다","단계":[{"제목":"내접사각형의 외각 구하기","힌트":"사각형 ABCD 가 원 $O'$ 에 내접할 때 점 A 의 외각 $\\angle BAP$ 는 어떤 내각과 같을까?","식":["$\\angle BAP=\\angle BCD=65^{\\circ}$","$\\angle ABP=\\angle ADC=75^{\\circ}$"],"설명":"원에 내접하는 사각형의 한 외각은 이웃하지 않는 내각과 크기가 같다. 점 A 의 외각 $\\angle BAP$ 는 $\\angle BCD$ 와, 점 B 의 외각 $\\angle ABP$ 는 $\\angle ADC$ 와 같다. 이로써 ㄷ 은 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"접선과 현이 이루는 각","고비":true,"힌트":"원 O 에서 접선 TS 와 현 PB, PA 가 이루는 각은 각각 어떤 원주각과 같을까?","식":["$\\angle BPS=\\angle BAP=65^{\\circ}$","$\\angle APT=\\angle ABP=75^{\\circ}$"],"설명":"원 O 에서 접선과 현이 이루는 각은 그 각 안에 있는 호에 대한 원주각과 크기가 같다. 따라서 ㄱ 은 옳고 ㄴ 은 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"ㄹ 평행 판별","힌트":"직선 PC 가 두 직선 TS 와 CD 를 지날 때 $\\angle BPS$ 와 $\\angle BCD$ 는 어떤 위치의 각일까?","식":["$\\angle BPS=\\angle BCD=65^{\\circ}$"],"설명":"직선 PC 에 대해 $\\angle BPS$ 와 $\\angle BCD$ 는 엇각이고 크기가 같으므로 $\\overline{TS}\\parallel\\overline{CD}$ 이다. 옳은 것은 ㄱ, ㄹ 이다.","확인":null,"스킬":"S10"}],"fb":"fig/ns/"},"ns-0ef8d88b1a95":{"길":"이동 방향에 따라 부호를 붙인 제곱의 합을 세운 뒤 제곱의 차끼리 묶어 인수분해로 계산한다","단계":[{"제목":"이동 거리를 부호 있는 식으로 쓰기","힌트":"오른쪽을 $+$, 왼쪽을 $-$ 로 하면 $19$ 일 동안의 합은 어떤 식일까?","식":["$1^{2}+2^{2}-3^{2}-4^{2}+5^{2}+6^{2}-7^{2}-8^{2}+\\cdots+17^{2}+18^{2}-19^{2}$"],"설명":"오른쪽으로 가는 날은 $+$, 왼쪽으로 가는 날은 $-$ 를 붙이면 부호가 $++--$ 로 반복된다. $19$ 일째는 왼쪽이므로 $-19^{2}$ 이다.","확인":null,"스킬":"P1"},{"제목":"제곱의 차로 묶기","고비":true,"힌트":"$+$ 인 제곱과 $-$ 인 제곱을 어떻게 짝지으면 인수분해할 수 있을까?","식":["$(1^{2}-3^{2})+(2^{2}-4^{2})+(5^{2}-7^{2})+(6^{2}-8^{2})+\\cdots+(17^{2}-19^{2})+18^{2}$"],"설명":"$+$ 가 붙은 제곱과 두 칸 뒤의 $-$ 제곱을 짝지으면 각 짝이 $a^{2}-b^{2}$ 꼴이 된다. 짝이 없는 $18^{2}$ 은 따로 둔다.","확인":null,"스킬":"P1"},{"제목":"각 묶음의 인수분해","힌트":"$a^{2}-b^{2}=(a+b)(a-b)$ 를 쓰면 각 묶음의 값은?","식":["$1^{2}-3^{2}=-2(1+3)$","$2^{2}-4^{2}=-2(2+4)$","$17^{2}-19^{2}=-2(17+19)$"],"설명":"묶음마다 두 수의 차가 $-2$ 이므로 각 묶음은 $-2$ 에 두 수의 합을 곱한 꼴이다.","확인":null,"스킬":"P1"},{"제목":"합 계산","힌트":"묶음에 쓰인 수를 모두 더한 값에 $-2$ 를 곱하고 $18^{2}$ 을 더하면?","식":["$-2(1+2+3+\\cdots+17+19)+18^{2}$","$=-344+324=-20$"],"설명":"묶음에 쓰인 수는 $1$ 부터 $17$ 까지와 $19$ 이므로 합이 $172$ 이고 $-2$ 를 곱하면 $-344$ 이다. 여기에 $18^{2}=324$ 를 더하면 $-20$ 이다. 음수이므로 처음 위치에서 왼쪽으로 $20\\,\\mathrm{m}$ 떨어져 있다.","확인":"20","스킬":"P1"}],"fb":"fig/ns/"},"ns-0f7c740dca32":{"길":"접어서 겹치는 선분의 길이를 a, b 로 나타낸 뒤 보기마다 길이, 합동, 넓이를 따진다","단계":[{"제목":"접은 선분의 길이를 a, b 로 나타내기","고비":true,"힌트":"접으면 겹치는 선분의 길이는 같다. $\\overline{AB}$ 와 $\\overline{EC}$ 를 $a$, $b$ 로 나타내면?","식":["$\\overline{AB}=\\overline{EB}=b$","$\\overline{EC}=\\overline{FG}=\\overline{DG}=a-b$","$\\overline{GC}=b-(a-b)=-a+2b$"],"설명":"접은 선분은 길이가 같으므로 $\\overline{AB}=\\overline{EB}=b$ 이고 $\\overline{EC}=a-b$ 이다. 사각형 FECG 는 직사각형이라 $\\overline{EC}=\\overline{FG}$ 이고, 접었으므로 $\\overline{FG}=\\overline{DG}$ 이다. 따라서 $\\overline{GC}=b-(a-b)=2b-a$ 이다. 또 $\\overline{FH}=\\overline{DH}=\\overline{EC}$ 이므로 ① 과 ② 는 옳다.","확인":null,"스킬":"S10"},{"제목":"합동 판별","힌트":"삼각형 ABH 와 EBH 에서 길이가 같은 변은 몇 쌍일까?","식":["$\\triangle ABH\\equiv\\triangle EBH\\ (SSS\\ \\text{합동})$"],"설명":"접기 전후의 변이므로 $\\overline{AB}=\\overline{EB}$, $\\overline{AH}=\\overline{EH}$ 이고 $\\overline{BH}$ 는 공통이다. 세 변의 길이가 같으므로 SSS 합동이고 ③ 은 옳다.","확인":null,"스킬":"S10"},{"제목":"사각형 FECG 의 넓이","힌트":"직사각형 FECG 의 가로와 세로를 곱하면?","식":["$\\square FECG=(a-b)(-a+2b)$","$=-a^{2}+3ab-2b^{2}$"],"설명":"사각형 FECG 는 가로가 $a-b$, 세로가 $2b-a$ 인 직사각형이므로 넓이는 두 길이의 곱이다. ④ 는 옳다.","확인":null,"스킬":"S12"},{"제목":"사각형 HBCG 의 넓이 비교","힌트":"직사각형 ABCD 에서 삼각형 ABH 와 삼각형 HDG 를 빼면?","식":["$\\square HBCG=ab-\\frac{1}{2}b^{2}-\\frac{1}{2}(a-b)^{2}$","$=-\\frac{1}{2}a^{2}+2ab-b^{2}$"],"설명":"직사각형 ABCD 에서 삼각형 ABH 와 삼각형 HDG 를 빼면 사각형 HBCG 이다. $\\square FECG$ 의 $3.5$ 배는 $-\\frac{7}{2}a^{2}+\\frac{21}{2}ab-7b^{2}$ 으로 위 식과 다르므로 ⑤ 는 옳지 않다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-175103613254":{"길":"조각을 붙여도 넓이가 같다는 점으로 남은 부분과 사다리꼴의 넓이를 같다고 놓고 인수분해로 높이를 구한다","단계":[{"제목":"남은 부분의 넓이","힌트":"직사각형의 넓이에서 (가) 와 (나) 의 넓이를 빼면?","식":["$4x\\times3x-\\frac{1}{2}\\times6\\times4-\\frac{1}{2}\\times(2x+3x)\\times4$","$=12x^{2}-12-10x$"],"설명":"(가) 는 두 변이 $6$, $4$ 인 직각삼각형이고, (나) 는 윗변 $2x$, 아랫변 $3x$, 높이 $4$ 인 사다리꼴이다. 직사각형의 넓이 $12x^{2}$ 에서 두 도형의 넓이를 뺀다.","확인":null,"스킬":"S12"},{"제목":"넓이가 같다는 식 세우기","고비":true,"힌트":"[그림 2] 의 사다리꼴 넓이를 평행한 두 변 사이의 거리 $d$ 로 나타내고 [그림 1] 의 남은 부분과 같다고 놓으면?","식":["$12x^{2}-10x-12=\\frac{1}{2}\\{(2x+1)+(x+1)\\}d$"],"설명":"조각을 겹치지 않게 붙였으므로 두 도형의 넓이가 같다. 사다리꼴의 넓이는 (윗변+아랫변)$\\times$(높이)$\\div2$ 이고 높이는 평행한 두 변 사이의 거리 $d$ 이다.","확인":null,"스킬":"S12"},{"제목":"좌변 인수분해","힌트":"$6x^{2}-5x-6$ 을 두 일차식의 곱으로 나타내면?","식":["$2(6x^{2}-5x-6)=\\frac{1}{2}(3x+2)d$","$2(2x-3)(3x+2)=\\frac{1}{2}(3x+2)d$"],"설명":"좌변을 $2$ 로 묶고 이차식을 인수분해하면 우변과 같은 인수 $3x+2$ 가 나온다.","확인":null,"스킬":"S12"},{"제목":"평행한 두 변 사이의 거리","힌트":"$x>3$ 이면 $3x+2$ 는 $0$ 이 아니다. 양변을 약분하면?","식":["$d=2\\times2(2x-3)=8x-12$"],"설명":"$x>3$ 이므로 $3x+2\\neq0$ 이라 양변을 $3x+2$ 로 약분할 수 있다. 약분하면 $d=4(2x-3)=8x-12$ 이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-1c4943453885":{"길":"접선의 성질로 각을 구하고 직각삼각형의 삼각비로 PO, OT 를 구해 보기마다 값을 맞춰 본다","단계":[{"제목":"접선의 성질로 각 구하기","고비":true,"힌트":"접선은 접점을 지나는 반지름과 어떤 각을 이룰까? 사각형 TPT′O 의 내각의 합을 쓰면?","식":["$\\angle TPT'=360^{\\circ}-(90^{\\circ}+120^{\\circ}+90^{\\circ})=60^{\\circ}$","$\\angle TPO=\\frac{1}{2}\\times60^{\\circ}=30^{\\circ}$"],"설명":"접선은 접점을 지나는 반지름과 수직이므로 $\\angle PTO=\\angle PT'O=90^{\\circ}$ 이고 접선의 길이는 같아 $\\overline{PT}=6$ 이다. 삼각형 TPO 와 T′PO 는 RHS 합동이라 $\\angle TPO$ 는 $\\angle TPT'$ 의 절반이다.","확인":null,"스킬":"S5"},{"제목":"삼각비로 PO, OT 구하기","힌트":"직각삼각형 TPO 에서 $\\overline{PT}=6$ 과 $\\angle TPO=30^{\\circ}$ 로 $\\overline{PO}$ 와 $\\overline{OT}$ 를 구하면?","식":["$\\overline{PO}=\\frac{6}{\\cos30^{\\circ}}=4\\sqrt{3}$","$\\overline{OT}=6\\tan30^{\\circ}=2\\sqrt{3}$"],"설명":"$\\cos$ 는 빗변에 대한 밑변의 비이고 $\\tan$ 는 밑변에 대한 높이의 비이다. 이로써 ③, ④ 가 옳음을 알 수 있다.","확인":null,"스킬":"S6"},{"제목":"부채꼴의 넓이 확인","힌트":"반지름 $\\overline{OT}$ 와 중심각 $120^{\\circ}$ 로 부채꼴의 넓이를 구하면?","식":["$\\pi\\times(2\\sqrt{3})^{2}\\times\\frac{120^{\\circ}}{360^{\\circ}}=4\\pi$"],"설명":"부채꼴의 넓이가 $4\\pi$ 이므로 ⑤ 의 $3\\pi$ 는 옳지 않다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-1f3664d95190":{"길":"주어진 그래프에서 a, b, c 의 부호를 정한 뒤 새 이차함수의 볼록 방향, 축, y 절편을 찾는다","단계":[{"제목":"a, b 의 부호 정하기","고비":true,"힌트":"축의 위치는 $x$ 의 계수의 부호와 어떤 관계일까? 이 식에서 $x$ 의 계수는 $-b$ 이다.","식":["$a>0$","$-ab>0$","$b<0$"],"설명":"그래프가 아래로 볼록하므로 $a>0$ 이다. 축이 $y$ 축의 왼쪽에 있으면 $a$ 와 $x$ 의 계수 $-b$ 의 부호가 같아 $-ab>0$ 이고, $a>0$ 이므로 $b<0$ 이다.","확인":null,"스킬":"A6"},{"제목":"c 의 값 구하기","힌트":"그래프가 원점을 지나면 $y$ 절편은?","식":["$-c=0$","$c=0$"],"설명":"그래프가 원점을 지나므로 $y$ 절편 $-c$ 가 $0$ 이다.","확인":null,"스킬":"A6"},{"제목":"새 이차함수의 그래프","힌트":"$y=bx^{2}+cx+a$ 에서 $b$ 의 부호, 축의 위치, $a$ 의 부호로 그래프의 모양을 정하면?","식":["$y=bx^{2}+a\\ (b<0,\\ a>0)$"],"설명":"$b<0$ 이므로 위로 볼록하고, $c=0$ 이므로 축이 $y$ 축이며, $a>0$ 이므로 $y$ 축과 원점보다 위쪽에서 만난다. 이런 그래프는 그림 ② 이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-1f94f7b7591e":{"길":"반지름이 1 인 직각삼각형에서 삼각비를 선분의 길이로 바꿔 보기마다 옳고 그름을 가린다","단계":[{"제목":"ㄱ, ㄴ 확인","힌트":"반지름이 $1$ 이므로 $\\overline{OA}=\\overline{OC}=1$ 이다. 삼각비의 정의로 $\\sin a^{\\circ}$ 와 $\\tan a^{\\circ}$ 를 선분으로 나타내면?","식":["$\\sin a^{\\circ}=\\frac{\\overline{AB}}{\\overline{OA}}=\\overline{AB}$","$\\tan a^{\\circ}=\\frac{\\overline{CD}}{\\overline{OC}}=\\overline{CD}$"],"설명":"직각삼각형 OAB 에서 $\\overline{OA}=1$ 이고 직각삼각형 OCD 에서 $\\overline{OC}=1$ 이므로 ㄱ, ㄴ 은 옳다.","확인":null,"스킬":"S6"},{"제목":"ㄷ 확인","힌트":"각 $b$ 는 직각삼각형 OAB 의 어느 꼭짓점의 각일까? 그 각에서 이웃한 변과 빗변은?","식":["$\\cos b^{\\circ}=\\frac{\\overline{AB}}{\\overline{OA}}=\\overline{AB}$"],"설명":"각 $b$ 는 점 A 의 각이므로 이웃한 변은 $\\overline{AB}$, 빗변은 $\\overline{OA}$ 이다. $\\cos b^{\\circ}=\\overline{AB}$ 이지 $\\overline{OB}$ 가 아니므로 ㄷ 은 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"ㄹ 확인과 개수 세기","고비":true,"힌트":"$\\overline{AB}$ 와 $\\overline{CD}$ 는 둘 다 $x$ 축에 수직이다. 각 $b$ 와 각 $c$ 는 어떤 관계일까?","식":["$c^{\\circ}=b^{\\circ}$","$\\sin c^{\\circ}=\\sin b^{\\circ}=\\frac{\\overline{OB}}{\\overline{OA}}=\\overline{OB}$"],"설명":"$\\overline{AB}\\parallel\\overline{CD}$ 이므로 각 $b$ 와 각 $c$ 는 동위각이라 크기가 같다. 직각삼각형 OAB 에서 $\\sin b^{\\circ}$ 는 $\\overline{OB}$ 와 $\\overline{OA}$ 의 비이므로 ㄹ 은 옳다. 옳은 것은 ㄱ, ㄴ, ㄹ 의 $3$ 개이다.","확인":"3","스킬":"S10"}],"fb":"fig/ns/"},"ns-203faa3059a0":{"길":"접선과 현이 이루는 각으로 닮은 삼각형을 찾고 대응하는 변의 비로 각 보기를 확인한다","단계":[{"제목":"닮은 삼각형 찾기","고비":true,"힌트":"삼각형 PTA 와 PBT 에서 공통인 각 말고, 접선 PT 와 현 TA 가 이루는 각은 어떤 원주각과 같을까?","식":["$\\angle PTA=\\angle PBT$","$\\triangle PTA\\sim\\triangle PBT$"],"설명":"$\\angle P$ 는 두 삼각형에 공통이다. 접선과 현이 이루는 각은 그 호에 대한 원주각과 같아 $\\angle PTA=\\angle PBT$ 이다. 두 각이 같으므로 AA 닮음이고 ① 은 옳다.","확인":null,"스킬":"S5"},{"제목":"닮음비로 비례식 세우기","힌트":"닮은 두 삼각형에서 대응하는 변의 길이의 비는?","식":["$\\overline{PA}:\\overline{PT}=\\overline{PT}:\\overline{PB}$"],"설명":"닮은 삼각형은 대응하는 변의 비가 같으므로 ④ 는 옳다.","확인":null,"스킬":"S1"},{"제목":"원 O′ 쪽 보기 확인","힌트":"원 $O'$ 에서도 같은 방법으로 삼각형 PT′A 와 PBT′ 를 비교하면?","식":["$\\triangle PT'A\\sim\\triangle PBT'$","$\\overline{PA}:\\overline{PT'}=\\overline{PT'}:\\overline{PB}$"],"설명":"원 $O'$ 에서도 $\\angle P$ 가 공통이고 $\\angle PT'A=\\angle PBT'$ 이므로 닮음이다. 대응하는 변의 비는 $\\overline{PA}:\\overline{PT'}=\\overline{PT'}:\\overline{PB}$ 이므로 ⑤ 의 비는 맞지 않다. 옳은 것은 ①, ④ 이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-216e818ef756":{"길":"평균은 계산으로 확인하고, 표준편차와 분산은 도수가 평균 가까이 몰린 정도로 견주어 보기를 하나씩 가린다.","단계":[{"제목":"세 모둠의 평균","힌트":"세 모둠의 평균을 각각 구하면 서로 어떻게 비교되는가?","식":["$A:\\ \\frac{3\\times 2+4\\times 2+5\\times 2+6\\times 2+7\\times 2}{10}=\\frac{50}{10}=5$","$B:\\ \\frac{3\\times 3+4\\times 1+5\\times 2+6\\times 1+7\\times 3}{10}=\\frac{50}{10}=5$","$C:\\ \\frac{3\\times 1+4\\times 2+5\\times 4+6\\times 2+7\\times 1}{10}=\\frac{50}{10}=5$"],"설명":"세 모둠 모두 시간의 합이 $50$, 인원이 $10$명이므로 평균은 $5$시간으로 같다. ㄱ은 옳다.","확인":"5","스킬":"C3"},{"제목":"편차의 합","힌트":"편차의 합은 자료의 모양에 따라 달라지는가?","식":["$\\sum (x_i-\\bar{x})=0$"],"설명":"편차는 각 값에서 평균을 뺀 값이고, 그 합은 어떤 자료에서도 $0$이다. 세 모둠의 편차의 합이 같으므로 ㄴ은 옳다.","확인":"0","스킬":"C3"},{"제목":"표준편차가 가장 작은 모둠","고비":true,"힌트":"표준편차가 가장 작은 모둠은 막대가 평균 근처에 어떻게 놓여 있는 모둠인가?","식":[],"설명":"자료가 평균 $5$ 근처에 모여 있을수록 표준편차가 작다. 막대가 평균 근처에 가장 많이 몰린 모둠은 C이므로 표준편차가 가장 작은 모둠은 C이고, A가 아니어서 ㄷ은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"B와 C의 분산 비교","힌트":"B와 C 중 평균에서 더 멀리 흩어져 있는 모둠은 어느 쪽인가?","식":[],"설명":"B는 양 끝인 $3$시간과 $7$시간에 각각 $3$명씩 있어 C보다 더 흩어져 있다. 따라서 B의 분산이 C의 분산보다 크고 ㄹ은 옳다. 옳은 것은 ㄱ, ㄴ, ㄹ이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-27b9b7778679":{"길":"대푯값을 먼저 모둠별로 구하고, 편차의 제곱을 도수와 곱해 분산을 구한 뒤 보기마다 참과 거짓을 가른다.","단계":[{"제목":"세 모둠의 평균","힌트":"세 모둠의 평균을 각각 구하면 서로 같은가 다른가?","식":["$A:\\ \\frac{4\\times4+5\\times2+6\\times3+7\\times2+8\\times4}{15}=\\frac{90}{15}=6$","$B:\\ \\frac{3(4+5+6+7+8)}{15}=\\frac{90}{15}=6$","$C:\\ \\frac{4\\times2+5\\times3+6\\times5+7\\times3+8\\times2}{15}=\\frac{90}{15}=6$"],"설명":"세 모둠 모두 평균이 $6$개로 같다. 따라서 ①은 옳지 않다.","확인":"6","스킬":"C3"},{"제목":"중앙값과 최빈값","힌트":"$15$명의 중앙값은 몇 번째 값이며, 도수가 가장 큰 값은 모둠마다 같은가?","식":[],"설명":"학생 수가 $15$명이므로 중앙값은 $8$번째 값이고 세 모둠 모두 $6$개이다. 최빈값은 A가 $4$개와 $8$개, B는 없음, C는 $6$개로 서로 다르다. ②는 옳고 ③은 옳지 않다.","확인":"6","스킬":"C3"},{"제목":"세 모둠의 분산","고비":true,"힌트":"편차를 제곱해 도수와 곱한 값의 합을 인원수로 나누면 가장 큰 분산은 어느 모둠인가?","식":["$A:\\ \\frac{(-2)^2\\times4+(-1)^2\\times2+0^2\\times3+1^2\\times2+2^2\\times4}{15}=\\frac{36}{15}=2.4$","$B:\\ \\frac{30}{15}=2$","$C:\\ \\frac{22}{15}$"],"설명":"분산이 가장 큰 모둠은 A이므로 ④는 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"표준편차와 선지 결정","힌트":"표준편차는 분산과 어떤 관계인가?","식":["$A:\\ \\sqrt{2.4},\\quad B:\\ \\sqrt{2},\\quad C:\\ \\sqrt{\\frac{22}{15}}$"],"설명":"표준편차는 분산의 양의 제곱근이므로 ⑤는 옳다. 따라서 옳은 것은 ②, ⑤이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-2a3abd4c45c1":{"길":"y절편과 x절편을 식에 대입해 a, b를 정하고, 그 값을 넣은 다항식을 인수분해한다.","단계":[{"제목":"y절편으로 b 구하기","힌트":"그래프가 $y$축과 만나는 점의 $y$좌표는 $y=ax-b$에서 무엇에 해당하는가?","식":["$-b=-4$","$b=4$"],"설명":"$x=0$일 때 $y=-b$이고 그래프가 $y$축과 $-4$에서 만나므로 $b=4$이다.","확인":"4","스킬":"G9"},{"제목":"x절편으로 a 구하기","고비":true,"힌트":"점 $(-2,\\,0)$이 직선 위에 있다는 것을 식으로 쓰면 어떻게 되는가?","식":["$0=-2a-4$","$a=-2$"],"설명":"그래프가 $x$축과 $-2$에서 만나므로 $(-2,\\,0)$을 $y=ax-4$에 대입하면 $a=-2$이다.","확인":"-2","스킬":"G9"},{"제목":"인수분해","힌트":"$a$, $b$를 대입한 식에서 최고차항의 계수가 음수이면 먼저 무엇을 하는가?","식":["$-2x^2-7x+4=-(2x^2+7x-4)$","$=-(2x-1)(x+4)$"],"설명":"최고차항의 계수가 음수이므로 $-1$로 묶은 뒤 인수분해한다. 결과는 $-(x+4)(2x-1)$이다.","확인":null,"스킬":"G9"}],"fb":"fig/ns/"},"ns-2b633fdaf4a3":{"길":"지름이 만드는 직각과 같은 호의 원주각이 같다는 성질로 보기를 하나씩 따져 틀린 보기를 찾는다.","단계":[{"제목":"지름이 만드는 직각","힌트":"$A$, $O$, $B$가 한 직선 위에 있으면 $\\angle ADB$와 $\\angle ACB$는 얼마인가?","식":["$\\angle ADB=\\angle ACB=90^{\\circ}$","$\\angle ABC=180^{\\circ}-90^{\\circ}-30^{\\circ}=60^{\\circ}$"],"설명":"$AB$가 원의 지름이므로 반원에 대한 원주각은 $90^{\\circ}$이다. 삼각형 $ABC$에서 $\\angle ABC=60^{\\circ}$이고 $\\angle ADC=\\angle ABC=60^{\\circ}$이다.","확인":null,"스킬":"S5"},{"제목":"같은 호의 원주각","고비":true,"힌트":"$\\overset{\\frown}{CB}$와 $\\overset{\\frown}{DA}$에 대한 원주각은 각각 어느 각과 같은가?","식":["$\\angle CDB=\\angle CAB=30^{\\circ}$","$\\angle DBA=\\angle DCA$","$\\angle BAD+\\angle DCA=\\angle BAD+\\angle DBA=90^{\\circ}$"],"설명":"같은 호에 대한 원주각의 크기는 같다. $\\angle ADB=90^{\\circ}$이므로 $\\angle BAD+\\angle DBA=90^{\\circ}$이다. ①과 ③은 옳다.","확인":null,"스킬":"S5"},{"제목":"삼각형의 외각 이용","힌트":"삼각형 $ADP$와 삼각형 $ACP$에서 각 $APD$는 어떤 각들의 합으로 나타나는가?","식":["$\\angle APD+\\angle DAB=120^{\\circ}$","$\\angle DAB=\\angle DCB$","$\\angle APD=30^{\\circ}+\\angle ACP=\\angle ABD+30^{\\circ}$"],"설명":"삼각형 $ADP$의 세 각의 합에서 $\\angle APD+\\angle DAB=120^{\\circ}$이고 $\\angle DAB=\\angle DCB$이므로 ④는 옳다. 삼각형 $ACP$의 외각으로 $\\angle APD=30^{\\circ}+\\angle ACP$이고 $\\angle ACP=\\angle ABD$이므로 ⑤도 옳다.","확인":null,"스킬":"S10"},{"제목":"옳지 않은 보기 고르기","힌트":"원주각과 중심각의 관계에서 $\\angle ACD$는 어느 각의 절반인가?","식":["$\\angle ACD=\\frac{1}{2}\\angle AOD$"],"설명":"$\\angle ACD$는 $\\overset{\\frown}{AD}$에 대한 원주각이므로 중심각 $\\angle AOD$의 절반이다. $P$는 원의 중심이 아니므로 $\\angle APD$의 절반이 아니다. 따라서 옳지 않은 것은 ②이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-2c0be01661df":{"길":"모눈에서 두 정사각형의 한 변을 피타고라스로 구한 뒤 P, Q의 대응하는 수를 구해 거리를 뺀다.","단계":[{"제목":"두 정사각형의 한 변","고비":true,"힌트":"모눈에서 $AD$와 $EF$를 빗변으로 하는 직각삼각형의 가로와 세로는 각각 얼마인가?","식":["$\\overline{AD}=\\overline{AP}=\\sqrt{2^2+3^2}=\\sqrt{13}$","$\\overline{EF}=\\overline{EQ}=\\sqrt{2^2+2^2}=2\\sqrt{2}$"],"설명":"$AD$는 가로 $2$, 세로 $3$만큼 이동한 선분이므로 피타고라스 정리로 $\\sqrt{13}$이고, $EF$는 가로 $2$, 세로 $2$이므로 $2\\sqrt{2}$이다.","확인":null,"스킬":"S3"},{"제목":"P와 Q에 대응하는 수","힌트":"$P$는 $A$에서 왼쪽으로, $Q$는 $E$에서 오른쪽으로 각각 얼마만큼 떨어져 있는가?","식":["$P=2-\\sqrt{13}$","$Q=4+2\\sqrt{2}$"],"설명":"점 $A$에 대응하는 수는 $2$, 점 $E$에 대응하는 수는 $4$이다. $P$는 $A$에서 $\\sqrt{13}$만큼 왼쪽, $Q$는 $E$에서 $2\\sqrt{2}$만큼 오른쪽에 있다.","확인":null,"스킬":"S3"},{"제목":"PQ의 길이","힌트":"$PQ$는 $Q$에 대응하는 수에서 $P$에 대응하는 수를 뺀 값인가?","식":["$\\overline{PQ}=(4+2\\sqrt{2})-(2-\\sqrt{13})=2+2\\sqrt{2}+\\sqrt{13}$"],"설명":"두 점에 대응하는 수의 차가 거리이므로 $PQ=2+2\\sqrt{2}+\\sqrt{13}$이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-2c0d5940ae69":{"길":"모눈 위 정사각형의 넓이를 바깥 정사각형에서 직각삼각형을 빼서 구해 한 변을 얻고, 중심에서 반지름만큼 떨어진 점의 수를 구한다.","단계":[{"제목":"작은 정사각형의 한 변","고비":true,"힌트":"기울어진 정사각형의 넓이는 바깥을 둘러싼 정사각형에서 무엇을 빼면 되는가?","식":["$3\\times3-4\\times\\left(\\frac{1}{2}\\times2\\times1\\right)=5$","$s=\\sqrt{5}$"],"설명":"바깥 정사각형의 넓이에서 합동인 직각삼각형 $4$개의 넓이를 빼면 $5$이므로 한 변의 길이는 $\\sqrt{5}$이다.","확인":null,"스킬":"S12"},{"제목":"점 A에 대응하는 수","힌트":"원의 중심에 대응하는 수에서 반지름만큼 왼쪽에 있는 점은 어디인가?","식":["$a=-4-\\sqrt{5}$"],"설명":"반지름이 $\\sqrt{5}$이고 중심에 대응하는 수가 $-4$이므로 $a=-4-\\sqrt{5}$이다.","확인":null,"스킬":"S3"},{"제목":"큰 정사각형과 점 D","힌트":"큰 정사각형의 넓이는 같은 방법으로 얼마인가?","식":["$4\\times4-4\\times\\left(\\frac{1}{2}\\times3\\times1\\right)=10$","$b=1+\\sqrt{10}$"],"설명":"큰 정사각형의 넓이는 $10$이므로 한 변의 길이가 $\\sqrt{10}$이고, 중심에 대응하는 수가 $1$이므로 $b=1+\\sqrt{10}$이다.","확인":null,"스킬":"S12"},{"제목":"a+2b 계산","힌트":"$a$와 $b$를 $a+2b$에 대입해 정리하면 어떻게 되는가?","식":["$a+2b=(-4-\\sqrt{5})+2(1+\\sqrt{10})=-2-\\sqrt{5}+2\\sqrt{10}$"],"설명":"상수항은 $-4+2=-2$이고 근호가 있는 항은 그대로 둔다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-2eb555586bbc":{"길":"정사각형의 넓이에서 한 변을 구해 원의 반지름으로 보고, 부채꼴의 중심각이 직각임을 써서 넓이를 계산한다.","단계":[{"제목":"정사각형의 한 변","고비":true,"힌트":"기울어진 정사각형의 넓이는 바깥 정사각형에서 무엇을 빼서 구하는가?","식":["$\\square ABCD=3\\times3-4\\times\\left(\\frac{1}{2}\\times2\\times1\\right)=5$","$\\overline{AB}=\\sqrt{5}$"],"설명":"바깥 정사각형의 넓이에서 직각삼각형 $4$개를 빼면 넓이가 $5$이므로 한 변은 $\\sqrt{5}$이다. 이 길이가 원의 반지름이다.","확인":null,"스킬":"S12"},{"제목":"부채꼴 ABC의 넓이","힌트":"정사각형의 한 각인 $\\angle ABC$의 크기는 몇 도이며 부채꼴의 넓이는 원의 몇 분의 몇인가?","식":["$\\frac{1}{4}\\pi\\times(\\sqrt{5})^2=\\frac{5}{4}\\pi$"],"설명":"$\\angle ABC=90^{\\circ}$이므로 부채꼴 $ABC$의 넓이는 원의 $\\frac{1}{4}$이다. $5\\pi$가 아니므로 ②가 옳지 않다.","확인":null,"스킬":"S3"},{"제목":"나머지 보기 확인","힌트":"반지름이 $\\sqrt{5}$일 때 원의 둘레와 수직선 위 $P$의 위치는 어떻게 되는가?","식":["$2\\pi\\times\\sqrt{5}=2\\sqrt{5}\\pi$","$P=-1-\\sqrt{5}$"],"설명":"원의 둘레는 $2\\sqrt{5}\\pi$이고, $B$에 대응하는 수가 $-1$이므로 $P$는 $-1-\\sqrt{5}$이다. ①, ③, ④, ⑤는 옳다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-2fbca7786674":{"길":"상자를 윗면과 밑면, 옆면으로 나누어 띠를 제외한 넓이를 각각 다항식으로 쓰고 더한다.","단계":[{"제목":"윗면과 밑면에서 남는 넓이","힌트":"띠가 십자로 지나는 면에서 남는 부분의 가로와 세로는 각각 얼마인가?","식":["$(3x-2)(2x+5-2)=(3x-2)(2x+3)$","$2(3x-2)(2x+3)=2(6x^2+5x-6)=12x^2+10x-12$"],"설명":"윗면과 밑면에는 폭 $2$인 띠가 서로 수직으로 지나므로 한 면에서 남는 부분은 가로 $3x-2$, 세로 $2x+3$인 직사각형이다. 두 면을 합해 $12x^2+10x-12$이다.","확인":null,"스킬":"S12"},{"제목":"옆면의 띠가 가린 폭","고비":true,"힌트":"옆면 네 개를 이어 붙이면 가로의 총 길이는 얼마이고 띠는 몇 곳을 가리는가?","식":["$2(3x+2x+5)=10x+10$","$10x+10-4\\times2=10x+2$"],"설명":"옆면을 이어 붙인 가로의 길이는 밑면의 둘레 $10x+10$이다. 띠가 옆면 $4$곳을 폭 $2$씩 가리므로 $8$을 뺀다.","확인":null,"스킬":"S12"},{"제목":"옆면에서 남는 넓이","힌트":"남은 가로의 길이에 높이를 곱하면 넓이는 얼마인가?","식":["$10(10x+2)=100x+20$"],"설명":"높이가 $10$이므로 옆면에서 남는 넓이는 $100x+20$이다.","확인":null,"스킬":"S12"},{"제목":"전체 넓이","힌트":"윗·밑면의 넓이와 옆면의 넓이를 더하면 어떻게 되는가?","식":["$(12x^2+10x-12)+(100x+20)=12x^2+110x+8$"],"설명":"두 넓이를 더하면 $12x^2+110x+8$이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-30be0b598413":{"길":"조각의 넓이 합을 인수분해하면 직사각형의 두 변이 나오고, 넓이가 $2$라는 조건으로 $x$를 구해 짧은 변에 대입한다.","단계":[{"제목":"조각의 넓이 합","힌트":"그림의 조각 $6$개를 종류별로 세면 넓이 합은 어떤 식이 되는가?","식":["$x^2\\times2+x\\times3+1\\times1=2x^2+3x+1$"],"설명":"넓이가 $x^2$인 조각 $2$개, $x$인 조각 $3$개, $1$인 조각 $1$개를 모두 이어 붙이므로 합이 직사각형의 넓이이다.","확인":null,"스킬":"S12"},{"제목":"두 변의 길이 읽기","고비":true,"힌트":"넓이를 인수분해하면 두 인수는 직사각형의 어떤 길이가 되는가?","식":["$2x^2+3x+1=(2x+1)(x+1)$"],"설명":"인수분해한 두 식이 직사각형의 두 변의 길이이다. $x>0$이므로 $x+1<2x+1$이고 짧은 변은 $x+1$이다.","확인":null,"스킬":"S12"},{"제목":"x 구하기","힌트":"직사각형의 넓이가 $2$라는 조건을 식으로 쓰면 어떤 이차방정식이 되는가?","식":["$2x^2+3x+1=2$","$2x^2+3x-1=0$","$x=\\frac{-3+\\sqrt{17}}{4}$"],"설명":"근의 공식으로 $x=\\frac{-3\\pm\\sqrt{17}}{4}$이고, $x>0$이므로 $x=\\frac{-3+\\sqrt{17}}{4}$이다.","확인":null,"스킬":"C7"},{"제목":"짧은 변의 길이","힌트":"구한 $x$를 짧은 변 $x+1$에 대입하면 어떻게 되는가?","식":["$x+1=\\frac{-3+\\sqrt{17}}{4}+1=\\frac{1+\\sqrt{17}}{4}$"],"설명":"짧은 변의 길이는 $\\frac{1+\\sqrt{17}}{4}$ cm이다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-311b05e71927":{"길":"삼각형 ABH에서 AH를, 삼각형 AHC에서 HC를 구한 뒤 각 x의 삼각비로 보기를 가린다.","단계":[{"제목":"AH의 길이","힌트":"삼각형 $ABH$에서 $\\angle BAH=30^{\\circ}$이고 빗변이 $6$이면 $AH$는 어느 삼각비로 구하는가?","식":["$\\overline{AH}=6\\cos30^{\\circ}=6\\times\\frac{\\sqrt{3}}{2}=3\\sqrt{3}$"],"설명":"$AH$는 각 $30^{\\circ}$에 이웃한 변이므로 코사인을 쓴다. ①은 옳다.","확인":null,"스킬":"S6"},{"제목":"HC의 길이와 sin x","고비":true,"힌트":"삼각형 $AHC$에서 빗변 $AC=9$와 $AH$를 알면 $HC$는 어떻게 구하는가?","식":["$\\overline{HC}=\\sqrt{9^2-(3\\sqrt{3})^2}=3\\sqrt{6}$","$\\sin x=\\frac{3\\sqrt{6}}{9}=\\frac{\\sqrt{6}}{3}$"],"설명":"피타고라스 정리로 $HC=3\\sqrt{6}$이다. 각 $x$의 대변이 $HC$이고 빗변이 $AC$이므로 $\\sin x=\\frac{\\sqrt{6}}{3}$이다. ②, ③은 옳다.","확인":null,"스킬":"S3"},{"제목":"tan x와 넓이","힌트":"각 $x$의 대변과 밑변은 $HC$와 $AH$ 중 어느 쪽인가?","식":["$\\tan x=\\frac{3\\sqrt{6}}{3\\sqrt{3}}=\\sqrt{2}$","$\\triangle AHC=\\frac{1}{2}\\times3\\sqrt{6}\\times3\\sqrt{3}=\\frac{27\\sqrt{2}}{2}$"],"설명":"$\\tan x=\\sqrt{2}$이므로 $\\sqrt{3}$이라고 한 ⑤가 옳지 않다. 삼각형 $AHC$의 넓이는 $\\frac{27\\sqrt{2}}{2}$이므로 ④는 옳다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-34b65cdabe80":{"길":"이차함수의 폭이 a에 따라 변하는 것을 이용해, 처음과 마지막으로 직사각형에 닿는 두 꼭짓점에서 a의 범위를 정한다.","단계":[{"제목":"경계가 되는 꼭짓점 찾기","고비":true,"힌트":"$a$가 커질수록 그래프의 폭은 어떻게 변하며, 직사각형과 두 점에서 만나는 범위의 양 끝은 어느 꼭짓점을 지날 때인가?","식":[],"설명":"$a$가 클수록 그래프의 폭이 좁아진다. 서로 다른 두 점에서 만나는 $a$의 범위는 꼭짓점 $C(4,\\,2)$를 지날 때보다 크고 꼭짓점 $A(1,\\,4)$를 지날 때보다 작은 구간이다.","확인":null,"스킬":"G1"},{"제목":"꼭짓점 A를 지날 때","힌트":"$A(1,\\,4)$를 $y=ax^2$에 대입하면 $a$는 얼마인가?","식":["$4=a\\times1^2$","$a=4$"],"설명":"$a=4$이면 그래프가 직사각형과 $A$ 한 점에서만 만나므로 이 값은 범위에서 제외된다.","확인":"4","스킬":"G1"},{"제목":"꼭짓점 C를 지날 때","힌트":"$C(4,\\,2)$를 $y=ax^2$에 대입하면 $a$는 얼마인가?","식":["$2=a\\times4^2$","$a=\\frac{1}{8}$"],"설명":"$a=\\frac{1}{8}$이면 그래프가 직사각형과 $C$ 한 점에서만 만나므로 이 값도 제외된다.","확인":"1/8","스킬":"G1"},{"제목":"a의 범위와 선지","힌트":"범위의 양 끝값이 선지에 있으면 두 점에서 만나는가?","식":["$\\frac{1}{8}<a<4$"],"설명":"$a$는 $\\frac{1}{8}$보다 크고 $4$보다 작아야 한다. 선지 중 $\\frac{1}{8}$만 범위 밖이므로 $a$가 될 수 없는 값은 $\\frac{1}{8}$이다.","확인":"1/8","스킬":"G1"}],"fb":"fig/ns/"},"ns-3a2bbe159bcc":{"길":"먼저 BH를 구하고, 같은 호의 원주각과 반원의 원주각으로 두 직각삼각형이 닮음임을 보여 BQ를 구한다.","단계":[{"제목":"BH의 길이","힌트":"직각삼각형 $ABH$에서 $AB=10$, $AH=5$이면 $BH$는 얼마인가?","식":["$\\overline{BH}=\\sqrt{10^2-5^2}=5\\sqrt{3}$"],"설명":"피타고라스 정리를 쓰면 $BH=5\\sqrt{3}$이다.","확인":null,"스킬":"S3"},{"제목":"닮은 삼각형 찾기","고비":true,"힌트":"$\\overset{\\frown}{BC}$에 대한 원주각과 지름에 대한 원주각은 각각 어느 각인가?","식":["$\\angle BAH=\\angle BQC$","$\\angle AHB=\\angle QCB=90^{\\circ}$","$\\triangle ABH\\backsim\\triangle QBC$"],"설명":"$\\overset{\\frown}{BC}$에 대한 원주각이므로 $\\angle BAH=\\angle BQC$이다. $BQ$가 지름이므로 $\\angle QCB=90^{\\circ}$이고 $\\angle AHB=90^{\\circ}$이다. 두 각이 각각 같으므로 $AA$ 닮음이다.","확인":null,"스킬":"S5"},{"제목":"비례식으로 BQ 구하기","힌트":"닮음인 두 삼각형에서 $AB$에 대응하는 변과 $BH$에 대응하는 변은 각각 무엇인가?","식":["$\\overline{AB}:\\overline{QB}=\\overline{BH}:\\overline{BC}$","$10:\\overline{QB}=5\\sqrt{3}:16$","$\\overline{QB}=\\frac{32\\sqrt{3}}{3}$"],"설명":"$AB$에 대응하는 변은 $QB$이고 $BH$에 대응하는 변은 $BC$이다. 비례식을 풀면 $QB=\\frac{32\\sqrt{3}}{3}$이다.","확인":null,"스킬":"S1"},{"제목":"원의 반지름","힌트":"$BQ$는 원 $O$의 무엇인가?","식":["$\\frac{1}{2}\\times\\frac{32\\sqrt{3}}{3}=\\frac{16\\sqrt{3}}{3}$"],"설명":"$BQ$가 지름이므로 반지름은 그 절반인 $\\frac{16\\sqrt{3}}{3}$이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-3c89fe8d8888":{"길":"세 변의 길이를 각각 삼각비와 피타고라스 정리로 구한 뒤 근삿값 범위로 크기를 견준다.","단계":[{"제목":"BC의 길이","고비":true,"힌트":"꼭짓점 $A$에서 $BC$에 내린 수선의 발 $P$를 잡으면 $BP$, $PC$는 각각 어느 삼각비로 구하는가?","식":["$\\overline{BP}=3\\sqrt{6}\\cos45^{\\circ}=3\\sqrt{3}$","$\\overline{PC}=6\\cos60^{\\circ}=3$","$\\overline{BC}=3\\sqrt{3}+3$"],"설명":"$A$에서 $BC$에 내린 수선의 발을 $P$라 하면 삼각형 $ABP$와 $ACP$가 모두 직각삼각형이다. $BC=BP+PC=3\\sqrt{3}+3$이다.","확인":null,"스킬":"S6"},{"제목":"EF의 길이","힌트":"꼭짓점 $E$에서 $DF$에 내린 수선의 발 $Q$를 잡으면 $EQ$, $DQ$, $QF$는 각각 얼마인가?","식":["$\\overline{EQ}=6\\sin60^{\\circ}=3\\sqrt{3}$","$\\overline{DQ}=6\\cos60^{\\circ}=3$","$\\overline{QF}=7-3=4$","$\\overline{EF}=\\sqrt{4^2+(3\\sqrt{3})^2}=\\sqrt{43}$"],"설명":"$E$에서 $DF$에 내린 수선의 발을 $Q$라 하면 삼각형 $DEQ$에서 $EQ$, $DQ$를 구하고 삼각형 $EFQ$에서 피타고라스 정리로 $EF$를 구한다.","확인":null,"스킬":"S6"},{"제목":"HI의 길이","힌트":"삼각형 $GHI$에서 $\\angle HGI$의 크기는 얼마이고 어느 두 변이 같은가?","식":["$\\angle HGI=180^{\\circ}-(30^{\\circ}+120^{\\circ})=30^{\\circ}$","$\\overline{HI}=\\overline{GI}=6$"],"설명":"$\\angle HGI=\\angle GHI=30^{\\circ}$이므로 삼각형 $GHI$는 이등변삼각형이다. 따라서 $HI=GI=6$이다.","확인":"6","스킬":"S6"},{"제목":"세 길이의 크기 비교","힌트":"$3\\sqrt{3}$과 $\\sqrt{43}$이 어느 두 정수 사이에 있는지 어림하면 어떻게 되는가?","식":["$8<3\\sqrt{3}+3<9$","$6<\\sqrt{43}<7$"],"설명":"$5<3\\sqrt{3}<6$이므로 $8<BC<9$이고, $\\sqrt{36}<\\sqrt{43}<\\sqrt{49}$이므로 $6<EF<7$이다. $HI=6$이므로 $HI<EF<BC$이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-3cb2f007cb1c":{"길":"직사각형이 되는 조건을 인수분해 가능성으로 바꾸고, 곱이 48인 두 자연수 쌍의 합을 모두 구해 보기와 비교한다.","단계":[{"제목":"직사각형이 되는 조건","고비":true,"힌트":"직사각형이 되려면 $x^2+kx+48$은 어떤 꼴로 인수분해되어야 하는가?","식":["$x^2+kx+48=(x+p)(x+q)$","$p+q=k,\\quad pq=48$"],"설명":"조각을 빈틈없이 직사각형으로 붙이면 가로와 세로가 $x+p$, $x+q$ 꼴이다. 따라서 $pq=48$이고 $p+q$가 추가하는 $x$ 조각의 수이다.","확인":null,"스킬":"A2"},{"제목":"곱이 48인 두 수의 합","힌트":"곱이 $48$인 두 자연수의 쌍을 모두 찾아 합을 구하면 어떻게 되는가?","식":["$1+48=49,\\ 2+24=26,\\ 3+16=19$","$4+12=16,\\ 6+8=14$"],"설명":"$48$의 약수의 쌍은 $(1,\\,48)$, $(2,\\,24)$, $(3,\\,16)$, $(4,\\,12)$, $(6,\\,8)$이고 합은 $49$, $26$, $19$, $16$, $14$이다.","확인":null,"스킬":"A2"},{"제목":"보기와 대조","힌트":"보기의 $12$, $14$, $16$, $26$, $49$ 중 위 합에 없는 수는 무엇인가?","식":[],"설명":"$14$, $16$, $26$, $49$는 합으로 나오므로 ㄴ, ㄷ, ㄹ, ㅁ은 옳다. $12$는 나오지 않으므로 ㄱ이 옳지 않다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-46b7b24aa9f3":{"길":"넓이의 비에서 두 정사각형의 변의 비를 구해 문자 a로 나타내고, 둘레 조건으로 a를 구한 뒤 GF를 계산한다.","단계":[{"제목":"변의 비","힌트":"두 정사각형의 넓이의 비가 $4:3$이면 한 변의 길이의 비는 어떻게 되는가?","식":["$\\overline{AB}:\\overline{ED}=2:\\sqrt{3}$","$\\overline{AB}=2a,\\quad \\overline{ED}=\\sqrt{3}a$"],"설명":"넓이의 비가 $4:3$이면 한 변의 길이의 비는 $2:\\sqrt{3}$이다. 따라서 $AB=2a$로 놓으면 $ED=\\sqrt{3}a$이다.","확인":null,"스킬":"A8"},{"제목":"둘레로 식 세우기","고비":true,"힌트":"직사각형 $ABCD$의 가로는 두 정사각형의 변의 길이로 어떻게 나타나는가?","식":["$\\overline{AD}=\\overline{AE}+\\overline{ED}=2a+\\sqrt{3}a$","$2\\{2a+(2+\\sqrt{3})a\\}=52$","$(4+\\sqrt{3})a=26$"],"설명":"$AE=AB=2a$이므로 $AD=(2+\\sqrt{3})a$이다. 둘레의 길이가 $52$라는 조건으로 식을 세운다.","확인":null,"스킬":"C7"},{"제목":"a의 값","힌트":"$a=\\frac{26}{4+\\sqrt{3}}$의 분모를 어떻게 없애는가?","식":["$a=\\frac{26}{4+\\sqrt{3}}=\\frac{26(4-\\sqrt{3})}{13}=2(4-\\sqrt{3})$"],"설명":"분모와 분자에 $4-\\sqrt{3}$을 곱해 분모를 유리화하면 $a=2(4-\\sqrt{3})$이다.","확인":null,"스킬":"A8"},{"제목":"GF의 길이","힌트":"$GF$는 $EF$에서 $EG$를 뺀 길이인가?","식":["$\\overline{GF}=2a-\\sqrt{3}a=(2-\\sqrt{3})a$","$=2(2-\\sqrt{3})(4-\\sqrt{3})=22-12\\sqrt{3}$"],"설명":"$EF=2a$, $EG=\\sqrt{3}a$이므로 $GF=(2-\\sqrt{3})a$이다. $a$를 대입해 전개하면 $22-12\\sqrt{3}$이다.","확인":null,"스킬":"A8"}],"fb":"fig/ns/"},"ns-4906458cba4c":{"길":"넓이 조건으로 꼭짓점의 높이를 구한 뒤 꼭짓점 꼴에 한 점을 대입해 식을 완성한다","단계":[{"제목":"꼭짓점의 y좌표 구하기","고비":true,"힌트":"축의 위치와 삼각형 $AOB$ 의 넓이로 꼭짓점의 높이를 구할 수 있을까?","식":["$\\frac{1}{2}\\times4\\times q=8$","$q=4$"],"설명":"$O$ 와 $B$ 는 $x$ 축 위의 점이므로 $\\overline{OB}=4$ 이다. 포물선의 축은 두 근 $0$, $4$ 의 한가운데인 $x=2$ 이므로 꼭짓점은 $A(2,\\,q)$ 이고, 밑변 $OB$ 에 대한 높이가 $q$ 이다.","확인":"4","스킬":"G10"},{"제목":"꼭짓점 꼴에 점 B 대입","힌트":"꼭짓점 $(2,\\,4)$ 를 쓰고 $B(4,\\,0)$ 을 대입하면 $a$ 는 어떻게 정해질까?","식":["$y=a(x-2)^2+4$","$4a+4=0$","$a=-1$"],"설명":"꼭짓점이 $(2,\\,4)$ 인 이차함수는 $y=a(x-2)^2+4$ 이고, 점 $(4,\\,0)$ 을 지나므로 대입해 $a$ 를 구한다.","확인":"-1","스킬":"A6"},{"제목":"a, b, c 읽어 합 구하기","힌트":"식을 전개했을 때 $a$, $b$, $c$ 는 각각 무엇일까?","식":["$y=-x^2+4x$","$a+b+c=-1+4+0$"],"설명":"$y=-(x-2)^2+4$ 를 전개하면 $-x^2+4x$ 이므로 $a=-1$, $b=4$, $c=0$ 이다.","확인":"3","스킬":"A6"}],"fb":"fig/ns/"},"ns-49d88b4e4bb4":{"길":"내접 조건을 먼저 모아 두고 보기를 하나씩 대어 해당하는 것만 센다","단계":[{"제목":"내접 조건 모으기","힌트":"사각형이 원에 내접한다고 말할 수 있는 조건에는 무엇이 있을까?","식":["$\\angle BAD+\\angle BCD=180^\\circ$","$\\angle BAC=\\angle BDC$","$\\overline{PA}\\cdot\\overline{PC}=\\overline{PB}\\cdot\\overline{PD}$"],"설명":"한 쌍의 대각의 크기의 합이 $180^\\circ$ 이면 내접한다. 같은 쪽에서 선분 $BC$ 를 바라보는 두 각이 같거나, 두 대각선이 만드는 선분의 곱이 같아도 네 점이 한 원 위에 있다.","확인":null,"스킬":"S15"},{"제목":"조건에 해당하는 보기 찾기","고비":true,"힌트":"일곱 개의 보기 가운데 위 조건과 똑같은 것은 어느 것일까?","식":["$\\text{ㄱ},\\ \\text{ㄹ},\\ \\text{ㅁ}$"],"설명":"ㄱ 은 대각의 합이 $180^\\circ$ 이다. ㄹ 은 선분 곱의 등식이다. ㅁ 은 호 $BC$ 에 대한 두 원주각이 같다는 것이다. 세 보기 모두 내접 조건이다.","확인":null,"스킬":"S15"},{"제목":"나머지 보기 확인","힌트":"ㄴ, ㄷ, ㅂ, ㅅ 은 위 조건 중 하나가 될까?","식":["$\\text{ㄴ},\\ \\text{ㄷ},\\ \\text{ㅂ},\\ \\text{ㅅ}$ 제외"],"설명":"ㄴ 과 ㅂ 은 한 쌍의 각이 같다는 것뿐이어서 대각의 합이 $180^\\circ$ 가 되지 않는다. ㄷ 은 두 대각선이 서로 이등분한다는 조건이라 평행사변형을 뜻한다. ㅅ 에서 외각 $\\angle DCE$ 와 같아야 하는 각은 $\\angle ABC$ 가 아니라 $\\angle BAD$ 이다.","확인":null,"스킬":"C3"},{"제목":"개수 세기","힌트":"내접하도록 하는 보기는 모두 몇 개일까?","식":["$3$"],"설명":"조건에 맞는 보기는 ㄱ, ㄹ, ㅁ 의 $3$ 개이다.","확인":"3","스킬":"S15"}],"fb":"fig/ns/"},"ns-4a5c8994373d":{"길":"선지를 중심각과 호, 현의 길이, 원주각의 성질에 하나씩 대어 성립하지 않는 것을 찾는다","단계":[{"제목":"중심각과 호","힌트":"중심각의 크기가 같은 두 호의 길이는 어떤 관계일까?","식":["$\\angle AOB=\\angle COD\\Rightarrow\\overset{\\frown}{AB}=\\overset{\\frown}{CD}$"],"설명":"한 원에서 중심각의 크기가 같으면 호의 길이도 같다. 따라서 ①은 성립한다.","확인":null,"스킬":"S5"},{"제목":"현의 길이와 중심각","고비":true,"힌트":"중심각이 두 배가 되면 현의 길이도 두 배가 될까?","식":["$\\angle COE=2\\angle AOB$","$\\overline{CE}<\\overline{CD}+\\overline{DE}=2\\overline{AB}$"],"설명":"중심각이 같은 현은 길이가 같으므로 $\\overline{CD}=\\overline{DE}=\\overline{AB}$ 이다. 삼각형 $CDE$ 에서 두 변의 길이의 합은 나머지 한 변보다 크므로 $\\overline{CE}<2\\overline{AB}$ 이고, $2\\overline{AB}=\\overline{CE}$ 는 성립하지 않는다.","확인":null,"스킬":"S5"},{"제목":"나머지 선지 확인","힌트":"③, ④, ⑤ 는 이등변삼각형과 원주각의 성질로 성립할까?","식":["$\\angle OAB=\\angle OED=\\frac{1}{2}(180^\\circ-\\angle AOB)$","$\\angle ADB=\\frac{1}{2}\\angle AOB=\\frac{1}{2}\\angle COD=\\angle DBC$","$\\angle AOB=2\\angle ACB$"],"설명":"삼각형 $OAB$ 와 $ODE$ 는 이등변삼각형이고 꼭지각이 같으므로 밑각이 같다. 한 호에 대한 원주각은 중심각의 $\\frac{1}{2}$ 이다. 세 선지 모두 성립한다.","확인":null,"스킬":"S10"}],"fb":"fig/ns/"},"ns-4cc5066cf26d":{"길":"마주 보는 면의 수에서 각 칸의 값을 정하고 부호에 따른 합을 모두 적어 보기에 없는 값을 찾는다","단계":[{"제목":"마주 보는 면 찾기","고비":true,"힌트":"전개도를 접으면 ⓐ, ⓑ, ⓒ 와 마주 보는 면에는 각각 어떤 수가 적혀 있을까?","식":["$16,\\ -\\sqrt{5},\\ 4$"],"설명":"한 줄로 놓인 세 면에서는 양 끝의 면이 서로 마주 본다. 윗줄에서 ⓐ 는 $16$ 과, 아랫줄에서 ⓒ 는 $4$ 와 마주 본다. 남은 ⓑ 는 $-\\sqrt{5}$ 와 마주 본다.","확인":null,"스킬":"S11"},{"제목":"ⓐ, ⓑ, ⓒ 의 값","힌트":"마주 보는 두 수 중 한 수가 다른 수의 제곱근일 때 ⓐ, ⓑ, ⓒ 는 각각 얼마일까?","식":["$\\pm\\sqrt{16}=\\pm4$","$(-\\sqrt{5})^2=5$","$\\pm\\sqrt{4}=\\pm2$"],"설명":"ⓐ 는 $16$ 의 제곱근이므로 $\\pm4$, ⓑ 는 $-\\sqrt{5}$ 를 제곱근으로 갖는 수이므로 $5$, ⓒ 는 $4$ 의 제곱근이므로 $\\pm2$ 이다. ⓐ 가 $256$ 이거나 ⓒ 가 $16$ 이 되는 경우는 $16$ 보다 작다는 조건에 맞지 않는다.","확인":null,"스킬":"C2"},{"제목":"합이 될 수 있는 값","힌트":"부호를 달리 고르면 세 수의 합은 어떤 값들이 될까?","식":["$\\pm4+5\\pm2$","$11,\\ 7,\\ 3,\\ -1$"],"설명":"ⓐ 와 ⓒ 의 부호를 각각 두 가지로 고르면 합은 $4+5+2$, $4+5-2$, $-4+5+2$, $-4+5-2$ 의 네 가지이다.","확인":null,"스킬":"C2"},{"제목":"될 수 없는 값 고르기","힌트":"보기 중 위 값에 없는 것은 무엇일까?","식":["$5$"],"설명":"보기 $-1$, $3$, $5$, $7$, $11$ 중 $5$ 는 네 가지 합에 들어 있지 않다.","확인":"5","스킬":"C2"}],"fb":"fig/ns/"},"ns-4e5382cd3156":{"길":"밑변이 같은 직각삼각형을 거듭 붙인 구조에서 빗변의 길이를 차례로 구해 삼각비를 읽는다","단계":[{"제목":"BD, BF 구하기","고비":true,"힌트":"정사각형의 한 변을 $a$ 라 하면 $\\overline{BD}$ 와 $\\overline{BF}$ 는 $a$ 로 어떻게 나타날까?","식":["$\\overline{BD}=\\sqrt{a^2+a^2}=\\sqrt{2}a$","$\\overline{BF}=\\sqrt{a^2+(\\sqrt{2}a)^2}=\\sqrt{3}a$"],"설명":"$E$, $G$, $I$ 에서 올린 수직 선분 $EF$, $GH$, $IJ$ 는 정사각형의 한 변과 같은 $a$ 이다. $\\overline{BE}=\\overline{BD}$ 이므로 한 변이 $a$ 인 직각삼각형이 빗변을 키우며 이어진다.","확인":null,"스킬":"S3"},{"제목":"BH, BJ 구하기","힌트":"같은 방식으로 $\\overline{BH}$ 와 $\\overline{BJ}$ 를 구하면?","식":["$\\overline{BH}=\\sqrt{a^2+(\\sqrt{3}a)^2}=2a$","$\\overline{BJ}=\\sqrt{a^2+(2a)^2}=\\sqrt{5}a$"],"설명":"$\\overline{BI}=\\overline{BH}=2a$ 이고, 직각삼각형 $BIJ$ 에서 $\\overline{IJ}=a$ 이다.","확인":null,"스킬":"S3"},{"제목":"sin B, cos B 구하기","힌트":"삼각형 $JBI$ 에서 $\\sin B$ 와 $\\cos B$ 는 각각 어느 두 변의 비일까?","식":["$\\sin B=\\frac{a}{\\sqrt{5}a}=\\frac{\\sqrt{5}}{5}$","$\\cos B=\\frac{2a}{\\sqrt{5}a}=\\frac{2\\sqrt{5}}{5}$"],"설명":"$\\sin B$ 는 빗변 $BJ$ 분의 높이 $JI$, $\\cos B$ 는 빗변 분의 밑변 $BI$ 이다.","확인":null,"스킬":"S6"},{"제목":"합 구하기","힌트":"두 값을 더하면?","식":["$\\sin B+\\cos B=\\frac{3\\sqrt{5}}{5}$"],"설명":"분모가 같으므로 분자끼리 더한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-5298d683dbc4":{"길":"원주각과 각의 이등분으로 같은 각을 찾아 BE 가 들어간 두 삼각형의 닮음을 만들고 비례식을 푼다","단계":[{"제목":"같은 크기의 각 찾기","고비":true,"힌트":"$\\angle EBD$ 와 크기가 같은 각은 어디에 있을까?","식":["$\\angle EBD=\\angle EAC=\\angle EAB$"],"설명":"$\\angle EBC$ 와 $\\angle EAC$ 는 호 $EC$ 에 대한 원주각이므로 같다. $AE$ 가 $\\angle A$ 를 이등분하므로 $\\angle EAC=\\angle EAB$ 이다.","확인":null,"스킬":"S5"},{"제목":"닮음인 삼각형 찾기","힌트":"$\\angle E$ 를 공유하는 두 삼각형 $EBD$ 와 $EAB$ 는 어떤 관계일까?","식":["$\\triangle EBD\\sim\\triangle EAB\\ (AA)$"],"설명":"$\\angle E$ 는 공통이고 $\\angle EBD=\\angle EAB$ 이므로 두 각이 같은 $AA$ 닮음이다.","확인":null,"스킬":"S1"},{"제목":"비례식 세우기","힌트":"닮음비로 $\\overline{EB}$ 가 들어간 비례식을 세우면?","식":["$\\overline{EB}:\\overline{EA}=\\overline{ED}:\\overline{EB}$","$\\overline{EB}^2=\\overline{EA}\\times\\overline{ED}$"],"설명":"$\\overline{EA}=\\overline{AD}+\\overline{DE}=12+4=16$ 이다. 닮은 두 삼각형에서 대응하는 변의 비가 같다.","확인":null,"스킬":"S1"},{"제목":"BE 구하기","힌트":"$\\overline{EA}=16$, $\\overline{ED}=4$ 를 대입하면?","식":["$\\overline{EB}^2=16\\times4=64$","$\\overline{EB}=8$"],"설명":"$\\overline{EB}>0$ 이므로 양의 제곱근을 택한다.","확인":"8","스킬":"S1"}],"fb":"fig/ns/"},"ns-5528f68f07c2":{"길":"정사각형의 변으로 남은 직사각형의 가로와 세로를 x, y 로 나타낸 뒤 곱해 전개한다","단계":[{"제목":"HD, FC 의 길이 구하기","고비":true,"힌트":"$ABEH$ 와 $HGFD$ 가 정사각형이면 $\\overline{HD}$ 와 $\\overline{FC}$ 는 $x$, $y$ 로 어떻게 쓸까?","식":["$\\overline{AH}=y$","$\\overline{HD}=\\overline{DF}=x-y$","$\\overline{FC}=y-(x-y)=-x+2y$"],"설명":"정사각형 $ABEH$ 의 한 변은 $\\overline{AB}=y$ 이므로 $\\overline{AH}=y$ 이다. $\\overline{AD}=x$ 이므로 $\\overline{HD}=x-y$ 이고, 정사각형 $HGFD$ 의 한 변도 $x-y$ 이다. $\\overline{DC}=y$ 에서 $\\overline{DF}$ 를 빼면 $\\overline{FC}$ 이다.","확인":null,"스킬":"S12"},{"제목":"넓이 전개하기","힌트":"직사각형 $GECF$ 의 가로와 세로를 곱해 전개하면?","식":["$(x-y)(-x+2y)$","$=-x^2+3xy-2y^2$"],"설명":"$\\overline{GF}=\\overline{HD}=x-y$ 이고 $\\overline{FC}=-x+2y$ 이다.","확인":null,"스킬":"S12"},{"제목":"계수의 합 구하기","힌트":"$a$, $b$, $c$ 를 읽어 더하면?","식":["$a=-1,\\ b=3,\\ c=-2$","$a+b+c=0$"],"설명":"$-x^2+3xy-2y^2$ 의 계수를 $ax^2+bxy+cy^2$ 과 비교한다.","확인":"0","스킬":"S12"}],"fb":"fig/ns/"},"ns-56ff2f12b906":{"길":"두 각이 같다는 조건에서 네 점이 한 원 위에 있음을 알아낸 뒤 선지를 원주각과 닮음으로 하나씩 확인한다","단계":[{"제목":"네 점이 한 원 위에 있음 알기","고비":true,"힌트":"$\\angle ACB=\\angle ADB$ 는 점 $A$, $B$, $C$, $D$ 에 대해 무엇을 뜻할까?","식":["$\\angle ACB=\\angle ADB$"],"설명":"같은 쪽에서 선분 $AB$ 를 바라보는 두 각이 같으므로 네 점 $A$, $B$, $C$, $D$ 는 한 원 위에 있다. 이제 원주각의 성질을 쓸 수 있다.","확인":null,"스킬":"S15"},{"제목":"①, ③ 확인","힌트":"같은 호에 대한 원주각은 어떤 관계일까?","식":["$\\angle ABD=\\angle ACD\\ (\\overset{\\frown}{AD})$","$\\angle BAC=\\angle BDC\\ (\\overset{\\frown}{BC})$"],"설명":"한 호에 대한 원주각의 크기는 모두 같으므로 ①과 ③은 성립한다.","확인":null,"스킬":"S5"},{"제목":"②, ⑤ 확인","힌트":"삼각형 $ABP$ 와 $DCP$ 에서 크기가 같은 각의 쌍은?","식":["$\\triangle ABP\\sim\\triangle DCP\\ (AA)$","$\\overline{PA}\\cdot\\overline{PC}=\\overline{PB}\\cdot\\overline{PD}$"],"설명":"$\\angle ABP=\\angle DCP$ (호 $AD$), $\\angle BAP=\\angle CDP$ (호 $BC$) 이므로 $AA$ 닮음이다. $\\overline{PA}:\\overline{PD}=\\overline{PB}:\\overline{PC}$ 에서 곱의 꼴이 나와 ②도 성립한다.","확인":null,"스킬":"S1"},{"제목":"④ 판별","힌트":"$\\angle DBC$ 는 어떤 각과 같다고 할 수 있을까?","식":["$\\angle DBC=\\angle DAC$"],"설명":"$\\angle DBC$ 는 호 $DC$ 에 대한 원주각이어서 $\\angle DAC$ 와 같다. $\\angle ADB$ 는 호 $AB$ 에 대한 원주각이라 $\\angle DBC$ 와 항상 같지는 않다. ④가 성립하지 않는다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-5822f65e8880":{"길":"x초 후 두 점이 움직인 거리로 삼각형의 밑변과 높이를 쓰고 넓이가 9 인 이차방정식을 푼다","단계":[{"제목":"PD, DQ 를 x 로 나타내기","고비":true,"힌트":"$x$초 후 두 점이 움직인 거리로 $\\overline{PD}$ 와 $\\overline{DQ}$ 를 쓰면?","식":["$\\overline{AP}=2x,\\ \\overline{DQ}=x$","$\\overline{PD}=15-2x$"],"설명":"$P$ 는 $A$ 에서 초속 $2\\,\\mathrm{cm}$, $Q$ 는 $D$ 에서 초속 $1\\,\\mathrm{cm}$ 로 움직인다. $\\overline{AD}=15$ 에서 $\\overline{AP}$ 를 빼면 $\\overline{PD}$ 이다.","확인":null,"스킬":"C7"},{"제목":"넓이 식 세우기","힌트":"삼각형 $PDQ$ 의 넓이를 $x$ 로 쓰고 $9$ 와 같다고 놓으면?","식":["$\\frac{1}{2}x(15-2x)=9$","$2x^2-15x+18=0$"],"설명":"$\\angle D=90^\\circ$ 이므로 $\\overline{PD}$ 와 $\\overline{DQ}$ 가 밑변과 높이이다.","확인":null,"스킬":"C7"},{"제목":"방정식 풀기","힌트":"인수분해해서 $x$ 를 구하면?","식":["$(2x-3)(x-6)=0$","$x=\\frac{3}{2},\\ 6$"],"설명":"$P$ 가 $AD$ 위에 있으려면 $0<x<7.5$ 이고 $Q$ 가 $DC$ 위에 있으려면 $0<x<10$ 이다. 두 값 모두 범위 안에 있다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-58d21918ce7d":{"길":"반지름이 1 이라는 점으로 각 삼각비를 선분의 길이로 바꾸어 곱을 약분한다","단계":[{"제목":"sin, cos 를 선분으로 쓰기","고비":true,"힌트":"$\\overline{OA}=1$ 인 직각삼각형 $OAB$ 에서 $\\sin x$, $\\cos x$, $\\sin y$, $\\cos y$ 를 선분의 길이로 쓰면?","식":["$\\sin x=\\overline{AB},\\ \\cos x=\\overline{OB}$","$\\sin y=\\overline{OB},\\ \\cos y=\\overline{AB}$"],"설명":"$\\overline{OA}$ 는 반지름이라 $1$ 이다. $y$ 는 $\\angle OAB$ 이므로 마주 보는 변이 $OB$, 이웃한 변이 $AB$ 이다.","확인":null,"스킬":"S6"},{"제목":"tan 을 선분으로 쓰기","힌트":"직각삼각형 $OCD$ 에서 $\\tan x$ 와 $\\tan z$ 는?","식":["$\\tan x=\\frac{\\overline{CD}}{\\overline{OC}}=\\overline{CD}$","$\\tan z=\\frac{\\overline{OC}}{\\overline{CD}}=\\frac{1}{\\overline{CD}}$"],"설명":"$\\overline{OC}$ 도 반지름이라 $1$ 이다. $z$ 는 $\\angle ODC$ 이므로 마주 보는 변이 $OC$ 이다.","확인":null,"스킬":"S6"},{"제목":"식 계산하기","힌트":"대입하면 어느 부분이 약분될까?","식":["$\\frac{\\overline{OB}}{\\overline{AB}}\\times\\frac{\\overline{AB}}{\\overline{OB}}+\\overline{CD}\\times\\frac{1}{\\overline{CD}}=1+1=2$"],"설명":"앞의 곱은 분자와 분모가 맞바뀐 두 분수의 곱이라 $1$ 이고, 뒤의 곱도 $1$ 이다.","확인":"2","스킬":"S6"}],"fb":"fig/ns/"},"ns-5cbf0db78cfc":{"길":"각 직각삼각형에서 h 를 삼각비로 나타내 선지의 식과 하나씩 맞춰 본다","단계":[{"제목":"나머지 각으로 h 쓰기","고비":true,"힌트":"$\\angle OBH=72^\\circ$ 이면 $\\angle BOH$ 는 몇 도이고, 이것으로 $h$ 를 어떻게 쓸까?","식":["$\\angle BOH=18^\\circ,\\ \\tan18^\\circ=\\frac{200}{h}$","$\\angle AOH=25^\\circ,\\ \\tan25^\\circ=\\frac{300}{h}$"],"설명":"$\\overline{AH}=\\overline{AB}+\\overline{BH}=300$ 이다. 직각삼각형의 나머지 한 예각은 $90^\\circ$ 에서 주어진 각을 뺀 값이고, $h$ 가 이웃한 변이라 $\\tan$ 의 분모에 들어간다.","확인":null,"스킬":"S6"},{"제목":"주어진 각으로 h 쓰기","힌트":"$\\angle A=65^\\circ$, $\\angle B=72^\\circ$ 를 쓰면 $h$ 는 어떻게 쓸까?","식":["$h=300\\tan65^\\circ$","$h=200\\tan72^\\circ$"],"설명":"$h$ 가 마주 보는 변이므로 $\\tan$ 의 값에 밑변의 길이를 곱한다.","확인":null,"스킬":"S6"},{"제목":"두 지점의 거리 차 이용","힌트":"$\\overline{AH}-\\overline{BH}=\\overline{AB}$ 를 $h$ 와 $\\tan$ 으로 쓰면?","식":["$h(\\tan25^\\circ-\\tan18^\\circ)=100$","$h=\\frac{100}{\\tan25^\\circ-\\tan18^\\circ}$"],"설명":"①, ②, ④, ⑤ 는 위의 식과 모두 같다. ③ 의 $100\\tan65^\\circ$ 는 $\\overline{AH}=300$ 이 아니라 $\\overline{AB}=100$ 을 곱한 것이어서 $h$ 와 같지 않다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-61621ade91fe":{"길":"작은 직각삼각형들로 BC 와 AC 를 구해 직각삼각형 ABC 에서 15° 와 75° 의 삼각비를 읽는다","단계":[{"제목":"BE, AB 구하기","힌트":"직각삼각형 $ABE$ 에서 $\\angle ABE=45^\\circ$ 이면 $\\overline{BE}$ 와 $\\overline{AB}$ 는?","식":["$\\overline{BE}=\\overline{AE}=2$","$\\overline{AB}=2\\sqrt{2}$"],"설명":"$\\angle AEB=90^\\circ$, $\\angle ABE=45^\\circ$ 이므로 직각이등변삼각형이고 $\\overline{AB}=\\overline{AE}\\div\\sin45^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"BD, DE 구하기","힌트":"직각삼각형 $BDE$ 에서 $\\angle BED=60^\\circ$ 이면 $\\overline{BD}$ 와 $\\overline{DE}$ 는?","식":["$\\overline{BD}=2\\sin60^\\circ=\\sqrt{3}$","$\\overline{DE}=2\\cos60^\\circ=1$"],"설명":"$\\overline{BE}=2$ 가 빗변이다.","확인":null,"스킬":"S6"},{"제목":"BC, AC 구하기","고비":true,"힌트":"직사각형 $CDEF$ 의 변과 $\\angle AEF$ 를 이용해 $\\overline{BC}$ 와 $\\overline{AC}$ 를 구하면?","식":["$\\overline{BC}=\\sqrt{3}-1$","$\\overline{AC}=\\sqrt{3}+1$"],"설명":"직사각형이므로 $\\overline{CD}=\\overline{EF}$, $\\overline{FC}=\\overline{DE}=1$ 이다. $\\angle AEF=90^\\circ+60^\\circ-90^\\circ=60^\\circ$ 이므로 $\\overline{AF}=2\\sin60^\\circ=\\sqrt{3}$, $\\overline{EF}=2\\cos60^\\circ=1$ 이다. 따라서 $\\overline{BC}=\\overline{BD}-\\overline{CD}=\\sqrt{3}-1$, $\\overline{AC}=\\overline{AF}+\\overline{FC}=\\sqrt{3}+1$ 이다.","확인":null,"스킬":"S3"},{"제목":"삼각형 ABC 의 각","힌트":"삼각형 $ABC$ 의 $\\angle B$ 와 $\\angle A$ 는 몇 도일까?","식":["$\\angle ABC=45^\\circ+30^\\circ=75^\\circ$","$\\angle BAC=15^\\circ$"],"설명":"직각삼각형 $BDE$ 에서 $\\angle EBD=30^\\circ$ 이므로 $\\angle ABC=\\angle ABE+\\angle EBD$ 이다.","확인":null,"스킬":"S10"},{"제목":"선지 판별","힌트":"직각삼각형 $ABC$ 의 변의 비로 ①~⑤ 의 값을 읽으면?","식":["$\\sin75^\\circ=\\frac{\\overline{AC}}{\\overline{AB}}=\\frac{\\sqrt{6}+\\sqrt{2}}{4}$"],"설명":"$\\angle B=75^\\circ$ 이므로 $\\sin75^\\circ$ 는 $\\frac{\\overline{AC}}{\\overline{AB}}$ 이다. ①, ②, ④, ⑤ 는 모두 성립한다. ③ 에 적힌 $\\frac{\\sqrt{6}-\\sqrt{2}}{4}$ 는 $\\cos75^\\circ$ 의 값이므로 ③ 이 옳지 않다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-64399e9f4edd":{"길":"근호 조건으로 a, b, c 의 부호를 정한 뒤 볼록 방향, 축의 위치, y절편에 맞는 그림을 고른다","단계":[{"제목":"a, b, c 의 부호 정하기","고비":true,"힌트":"$\\sqrt{a^2}=a$, $\\sqrt{b^2}=-b$, $\\sqrt{c^2}=-c$ 에서 $a$, $b$, $c$ 의 부호는?","식":["$\\sqrt{a^2}=|a|=a\\Rightarrow a>0$","$\\sqrt{b^2}=|b|=-b\\Rightarrow b<0$","$c<0$"],"설명":"$\\sqrt{x^2}=|x|$ 이다. $|x|=x$ 이면 $x\\ge0$, $|x|=-x$ 이면 $x\\le0$ 이고, $a$, $b$, $c$ 는 $0$ 이 아니므로 부호가 정해진다.","확인":null,"스킬":"C2"},{"제목":"그래프의 모양 정하기","힌트":"부호로 볼록한 방향, 축의 위치, $y$절편의 부호를 정하면?","식":["$a>0,\\ ab<0,\\ c<0$"],"설명":"$a>0$ 이므로 아래로 볼록하다. 축은 $x=-\\frac{b}{2a}$ 이고 $ab<0$ 이므로 $y$축의 오른쪽에 있다. $c<0$ 이므로 $y$축과 원점보다 아래에서 만난다.","확인":null,"스킬":"G7"},{"제목":"그림 고르기","힌트":"세 조건을 모두 만족하는 그림은?","식":["$a>0,\\ b<0,\\ c<0$"],"설명":"그림 ①, ② 는 위로 볼록하다. 그림 ④ 는 $y$절편이 양수이고, 그림 ⑤ 는 축이 왼쪽이고 $y$절편이 양수이다. 조건에 맞는 그림은 ③ 이다.","확인":null,"스킬":"G7"}],"fb":"fig/ns/"},"ns-655205942276":{"길":"수선의 발로 30° 를 찾고 접은 각과 엇각으로 삼각형 ABC 의 두 각을 정해 삼각비로 변과 넓이를 구한다","단계":[{"제목":"∠ACH 구하기","힌트":"점 $A$ 에서 직선 $BC$ 에 내린 수선의 발 $H$ 를 잡고 $\\overline{AH}:\\overline{AC}$ 를 보면?","식":["$\\overline{AH}:\\overline{AC}=5:10=1:2$","$\\angle ACH=30^\\circ$"],"설명":"점 $H$ 는 $A$ 에서 직선 $BC$ 에 내린 수선의 발이다. 종이의 폭이 $5$ 이므로 $\\overline{AH}=5$ 이다. 직각삼각형에서 빗변이 한 변의 $2$ 배이면 그 변과 마주 보는 각은 $30^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"삼각형 ABC 의 각 구하기","고비":true,"힌트":"접은 각과 평행선의 엇각으로 $\\angle CAB$ 와 $\\angle ACB$ 는 어떤 관계일까?","식":["$\\angle CAB=\\angle ACB=30^\\circ$","$\\angle ABH=60^\\circ$"],"설명":"종이의 위아래 변이 평행하므로 엇각이 같다. 접은 각도 같으므로 $\\angle CAB=\\angle ACB$ 이다. 점 $B$ 의 바깥각 $\\angle ABH$ 는 두 내각의 합이다.","확인":null,"스킬":"S10"},{"제목":"AB 구하기","힌트":"직각삼각형 $ABH$ 에서 $\\overline{AH}=5$ 와 $\\angle ABH$ 로 $\\overline{AB}$ 를 구하면?","식":["$\\overline{AB}=\\frac{5}{\\sin60^\\circ}=\\frac{10\\sqrt{3}}{3}$"],"설명":"$\\sin60^\\circ=\\frac{\\overline{AH}}{\\overline{AB}}$ 이다.","확인":null,"스킬":"S6"},{"제목":"넓이 구하기","힌트":"두 변 $AB$, $AC$ 와 끼인각 $\\angle CAB$ 로 넓이를 구하면?","식":["$\\triangle ABC=\\frac{1}{2}\\times\\frac{10\\sqrt{3}}{3}\\times10\\times\\sin30^\\circ=\\frac{25\\sqrt{3}}{3}$"],"설명":"두 변의 길이와 그 끼인각의 크기를 알면 넓이는 $\\frac{1}{2}\\times(\\text{두 변의 곱})\\times\\sin(\\text{끼인각})$ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-66b26511eba7":{"길":"세 삼각형의 넓이를 삼각비로 쓴 뒤 서로 같다고 놓아 a 와 b 를 c 의 배수로 나타낸다","단계":[{"제목":"넓이를 삼각비로 쓰기","힌트":"두 변과 끼인각을 알 때 삼각형의 넓이를 어떻게 쓸까?","식":["$S_A=\\frac{1}{2}ab\\sin30^\\circ=\\frac{1}{4}ab$","$S_B=\\frac{1}{2}ac\\sin60^\\circ=\\frac{\\sqrt{3}}{4}ac$","$S_C=\\frac{1}{2}bc\\sin45^\\circ=\\frac{\\sqrt{2}}{4}bc$"],"설명":"세 삼각형 $A$, $B$, $C$ 의 넓이를 각각 $S_A$, $S_B$, $S_C$ 라 한다. 삼각형 $A$ 는 변 $a$, $b$ 와 $30^\\circ$, 삼각형 $B$ 는 변 $a$, $c$ 와 $60^\\circ$, 삼각형 $C$ 는 변 $b$, $c$ 와 $45^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"a, b 를 c 로 나타내기","고비":true,"힌트":"$S_A=S_B$, $S_A=S_C$ 로 $b$ 와 $a$ 를 $c$ 에 대한 식으로 나타내면?","식":["$b=\\sqrt{3}c$","$a=\\sqrt{2}c$"],"설명":"$\\frac{1}{4}ab=\\frac{\\sqrt{3}}{4}ac$ 의 양변을 $\\frac{a}{4}$ 로 나누면 $b=\\sqrt{3}c$ 이다. $\\frac{1}{4}ab=\\frac{\\sqrt{2}}{4}bc$ 의 양변을 $\\frac{b}{4}$ 로 나누면 $a=\\sqrt{2}c$ 이다.","확인":null,"스킬":"A8"},{"제목":"비 구하기","힌트":"$a$, $b$, $c$ 를 모두 $c$ 에 대한 식으로 쓰고 비를 정리하면?","식":["$a:b:c=\\sqrt{2}c:\\sqrt{3}c:c=\\sqrt{2}:\\sqrt{3}:1$"],"설명":"세 항에 공통으로 들어 있는 $c$ 를 약분한다.","확인":null,"스킬":"A8"}],"fb":"fig/ns/"},"ns-6a0ab831a6ff":{"길":"볼록 방향, 축, y절편으로 a, b, c 의 부호를 읽고 선지의 식을 특정 x 의 함숫값으로 바꿔 부호를 본다","단계":[{"제목":"a, b, c 부호 읽기","힌트":"볼록한 방향, 축의 위치, $y$절편으로 $a$, $b$, $c$ 의 부호를 정하면?","식":["$a<0$","$ab<0\\Rightarrow b>0$","$c>0$"],"설명":"위로 볼록하므로 $a<0$ 이다. 축 $x=-\\frac{b}{2a}$ 가 $y$축의 오른쪽에 있어 $ab<0$ 이므로 $b>0$ 이다. $y$절편이 양수이므로 $c>0$ 이다.","확인":null,"스킬":"G7"},{"제목":"특정 x 의 함숫값 보기","고비":true,"힌트":"$4a+2b+c$ 와 $a-2b+4c$ 는 $x$ 가 얼마일 때의 함숫값과 관계가 있을까?","식":["$f(2)=4a+2b+c>0$","$f\\left(-\\frac{1}{2}\\right)=\\frac{1}{4}a-\\frac{1}{2}b+c<0$","$a-2b+4c=4f\\left(-\\frac{1}{2}\\right)<0$"],"설명":"$f(x)=ax^2+bx+c$ 라 한다. 그림에서 $x=2$ 일 때 그래프는 $x$축 위쪽에, $x=-\\frac{1}{2}$ 일 때 아래쪽에 있다.","확인":null,"스킬":"G6"},{"제목":"옳지 않은 선지 고르기","힌트":"①~⑤ 중 성립하지 않는 것은?","식":["$a-2b+4c<0$"],"설명":"①은 $b>0$, ②는 $a<0$ 이고 $b>0$ 이므로 $ab<0$, ③은 $b>0$, $c>0$ 이므로 $bc>0$, ④는 $f(2)>0$ 이어서 모두 옳다. ⑤ 는 부호가 반대이므로 옳지 않다.","확인":null,"스킬":"G6"}],"fb":"fig/ns/"},"ns-6e64d7ebf0a6":{"길":"수선을 그어 ∠ACB 를 구하고 접은 각의 성질로 삼각형 ABC 의 각을 정한 뒤 두 변과 끼인각으로 넓이를 구한다","단계":[{"제목":"보조선 AH 와 각 ACH","힌트":"점 A 에서 BC 의 연장선에 수선을 그으면 AC 를 빗변으로 하는 어떤 직각삼각형이 생기는가?","식":["$\\overline{AH}:\\overline{AC}=1:2$","$\\angle ACH=30^\\circ$"],"설명":"점 $A$ 에서 $BC$ 의 연장선 위에 내린 수선의 발을 $H$ 라 하면 $AH$ 는 종이의 폭 $6\\,cm$ 이다. 직각삼각형 $AHC$ 에서 $AH:AC=1:2$ 이므로 $\\angle ACH=30^\\circ$ 이다.","확인":null,"스킬":"S2"},{"제목":"접은 각과 엇각","힌트":"접은 각과 엇각의 성질로 ∠CAB 와 ∠ACB 의 관계를 찾으면?","식":["$\\angle ACB=\\angle CAB=30^\\circ$"],"설명":"$AC$ 를 접는 선으로 접었으므로 접은 각이 같고, 직사각형의 마주 보는 두 변이 평행하므로 엇각이 같다. 그러므로 $\\angle CAB=\\angle ACB$ 이고, 점 $B$ 가 $CH$ 위에 있으므로 $\\angle ACB=\\angle ACH=30^\\circ$ 이다.","확인":null,"스킬":"S10","고비":true},{"제목":"변 AB 의 길이","힌트":"삼각형 ABC 의 외각 ∠ABH 를 구한 뒤 직각삼각형 AHB 에서 AB 를 구하면?","식":["$\\angle ABH=60^\\circ$","$\\overline{AB}=\\frac{6}{\\sin60^\\circ}=6\\times\\frac{2}{\\sqrt3}=4\\sqrt3$"],"설명":"삼각형의 한 외각은 이웃하지 않는 두 내각의 합과 같으므로 $\\angle ABH=30^\\circ+30^\\circ=60^\\circ$ 이다. 직각삼각형 $AHB$ 에서 $\\sin60^\\circ=\\frac{AH}{AB}$ 이다.","확인":null,"스킬":"S6"},{"제목":"삼각형 ABC 의 넓이","힌트":"두 변의 길이와 그 끼인각을 알 때 삼각형의 넓이는 어떻게 구하는가?","식":["$\\triangle ABC=\\frac12\\times4\\sqrt3\\times12\\times\\sin30^\\circ=12\\sqrt3$"],"설명":"$AB=4\\sqrt3$, $AC=12$ 이고 끼인각 $\\angle BAC=30^\\circ$ 이므로 $\\sin30^\\circ=\\frac12$ 를 쓴다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-70a8ff236b0b":{"길":"접은 선과 OP 의 교점을 잡아 직각삼각형 OAM 의 각을 구한 뒤 삼각형 OAP 의 모양과 AB 의 길이를 확인한다","단계":[{"제목":"교점 M 과 OM 의 길이","힌트":"점 P 가 중심 O 와 겹치도록 접으면 접은 선 AB 는 선분 OP 에 대해 어떤 위치인가?","식":["$\\overline{OM}=\\frac12\\overline{OP}=\\frac12\\overline{OA}$","$\\overline{OA}:\\overline{OM}=2:1$"],"설명":"$AB$ 와 $OP$ 의 교점을 $M$ 이라 한다. 접으면 $P$ 가 $O$ 에 겹치므로 $AB$ 는 $OP$ 를 수직이등분하고 $OM=MP$ 이며, $OP=OA$(반지름)이다.","확인":null,"스킬":"S10","고비":true},{"제목":"직각삼각형 OAM 의 각","힌트":"빗변이 한 변의 두 배인 직각삼각형의 예각은 각각 얼마인가?","식":["$\\angle OAM=30^\\circ$, $\\angle AOM=60^\\circ$"],"설명":"직각삼각형 $OAM$ 에서 $OA:OM=2:1$ 이므로 세 각이 $30^\\circ$, $60^\\circ$, $90^\\circ$ 인 직각삼각형이다.","확인":null,"스킬":"S6"},{"제목":"삼각형 OAP 의 모양","힌트":"삼각형 OAP 에서 두 변의 길이와 그 끼인각은?","식":["$\\angle AOP=60^\\circ,\\ \\overline{OA}=\\overline{OP}$"],"설명":"$\\angle AOP=\\angle AOM=60^\\circ$ 이고 $OA=OP$ 이므로 삼각형 $OAP$ 는 정삼각형이다. 따라서 선지 ④ 의 '정삼각형이 아닐 수 있다' 가 옳지 않다.","확인":null,"스킬":"S10"},{"제목":"AB 의 길이 확인","힌트":"$OA=6$ 일 때 $AM$ 은 삼각비로 어떻게 구하는가?","식":["$\\overline{AM}=6\\sin60^\\circ=3\\sqrt3$","$\\overline{AB}=2\\overline{AM}=6\\sqrt3$"],"설명":"$M$ 은 현 $AB$ 의 중점이므로 $AB=2AM$ 이다. 선지 ⑤ 는 옳다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-7387714c13af":{"길":"직선에서 a 와 b 의 부호를 읽고 이차함수를 완전제곱식으로 고쳐 꼭짓점 좌표의 부호를 따진다","단계":[{"제목":"a, b 의 부호","힌트":"직선이 오른쪽 위로 향하는지, y절편이 양수인지 음수인지로 a, b 의 부호를 읽으면?","식":["$a>0,\\ -b>0$","$b<0$"],"설명":"그래프가 오른쪽 위로 향하므로 기울기 $a$ 는 양수이다. $y$ 축과 원점보다 위쪽에서 만나므로 $y$ 절편 $-b$ 가 양수이다.","확인":null,"스킬":"A6"},{"제목":"꼭짓점의 좌표","힌트":"$y=bx^2-ax$ 를 완전제곱 꼴로 고치면 꼭짓점은?","식":["$y=b\\left(x-\\frac{a}{2b}\\right)^2-\\frac{a^2}{4b}$","$\\left(\\frac{a}{2b},\\ -\\frac{a^2}{4b}\\right)$"],"설명":"$x^2$ 의 계수 $b$ 로 묶은 뒤 $x$ 의 계수의 절반의 제곱을 더하고 뺀다.","확인":null,"스킬":"A6","고비":true},{"제목":"꼭짓점의 사분면","힌트":"$a>0,\\ b<0$ 일 때 꼭짓점의 x좌표와 y좌표의 부호는?","식":["$\\frac{a}{2b}<0,\\ -\\frac{a^2}{4b}>0$"],"설명":"x좌표는 음수, y좌표는 양수이므로 꼭짓점은 제$2$사분면 위에 있다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-766a961f13a5":{"길":"점 B 의 좌표를 a 로 나타내 사다리꼴 넓이를 이차방정식으로 세우고 제2사분면 조건으로 근을 고른다","단계":[{"제목":"세 점의 좌표","힌트":"점 A, B, C 의 좌표를 a 로 나타내면?","식":["$A(0,\\,5),\\ B\\left(a,\\ \\frac12a+5\\right),\\ C(a,\\,0)$"],"설명":"$A$ 는 $x=0$ 일 때의 $y$ 값이고, $B$ 는 직선 위의 점이며, $C$ 는 $B$ 에서 $x$ 축에 내린 수선의 발이다.","확인":null,"스킬":"G10"},{"제목":"넓이로 식 세우기","힌트":"사각형 ABCO 의 평행한 두 변과 높이를 a 로 나타내 넓이를 쓰면?","식":["$\\frac12\\times\\left\\{\\left(\\frac12a+5\\right)+5\\right\\}\\times(-a)=16$"],"설명":"$AO$ 와 $BC$ 가 $y$ 축에 평행한 사다리꼴이고 높이는 $OC=-a$ 이다($a<0$).","확인":null,"스킬":"G10","고비":true},{"제목":"이차방정식 풀기","힌트":"식을 정리해 a 에 대한 이차방정식으로 풀면?","식":["$a^2+20a+64=0$","$(a+16)(a+4)=0$"],"설명":"양변에 $-4$ 를 곱해 정리한 뒤 인수분해한다. $a=-16$ 또는 $a=-4$ 이다.","확인":null,"스킬":"G10"},{"제목":"근 고르기","힌트":"점 B 가 제2사분면 위에 있다는 조건으로 두 근 중 하나를 고르면?","식":["$a=-4,\\ b=3$","$a+b=-1$"],"설명":"$a=-16$ 이면 $b=-3$, $a=-4$ 이면 $b=3$ 이다. 제$2$사분면에서는 $y$ 좌표가 양수이므로 $a=-4$ 이다.","확인":"-1","스킬":"C2"}],"fb":"fig/ns/"},"ns-774970434267":{"길":"주어진 그래프에서 a, b, c 의 부호를 읽고 새 식에서 볼록 방향·축·y절편이 어떻게 정해지는지 따진다","단계":[{"제목":"a, b, c 의 부호","힌트":"아래로 볼록한지, 축이 y축의 어느 쪽인지, y절편이 어디인지로 a, b, c 의 부호를 정하면?","식":["$a>0,\\ ab<0,\\ b<0,\\ c>0$"],"설명":"아래로 볼록하므로 $a>0$ 이다. 축이 $y$ 축의 오른쪽에 있으므로 $a$ 와 $b$ 의 부호가 다르고($ab<0$) $b<0$ 이다. $y$ 축과 원점보다 위쪽에서 만나므로 $c>0$ 이다.","확인":null,"스킬":"A6"},{"제목":"새 그래프의 조건","힌트":"$y=bx^2-ax+c$ 에서 볼록 방향, 축의 위치, y절편은 각각 어느 계수로 정해지는가?","식":["$b<0,\\ -ab>0,\\ c>0$"],"설명":"$x^2$ 의 계수 $b<0$ 이므로 위로 볼록하다. $x^2$ 의 계수와 $x$ 의 계수의 곱 $b\\times(-a)$ 가 양수이므로 축은 $y$ 축의 왼쪽에 있고, $c>0$ 이므로 $y$ 절편은 양수이다.","확인":null,"스킬":"A6","고비":true},{"제목":"그래프 고르기","힌트":"위로 볼록, 축이 y축의 왼쪽, y절편이 양수인 그래프는 어느 것인가?","식":["$\\text{그림 ④}$"],"설명":"세 조건을 모두 만족하는 그래프는 ④ 이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-77c3e93624ab":{"길":"직각삼각형 OEF 와 OAB 에서 tan x 와 sin x 를 각각 선분으로 읽고 두 선분의 차를 구한다","단계":[{"제목":"tan x 를 선분으로","힌트":"직각삼각형 OEF 에서 EF 의 길이는 반지름과 같다. tan x 는 어느 선분의 길이와 같은가?","식":["$\\tan x^\\circ=\\frac{\\overline{OF}}{\\overline{EF}}=\\frac{\\overline{OF}}{1}=\\overline{OF}$"],"설명":"$\\angle OEF=x^\\circ$ 이고 $EF=1$ 이다.","확인":null,"스킬":"S6"},{"제목":"sin x 를 선분으로","힌트":"삼각형 OAB 에서 ∠OAB 는 ∠OEF 와 어떤 관계인가? 그러면 sin x 는?","식":["$\\angle OAB=\\angle OEF=x^\\circ$","$\\sin x^\\circ=\\frac{\\overline{OB}}{\\overline{OA}}=\\overline{OB}$"],"설명":"$AB$ 와 $EF$ 가 모두 $OF$ 에 수직이므로 평행하고 동위각이 같다. $OA=1$ 이다.","확인":null,"스킬":"S10","고비":true},{"제목":"두 값의 차","힌트":"$\\overline{OF}$ 와 $\\overline{OB}$ 의 차는 어느 선분인가?","식":["$\\tan x^\\circ-\\sin x^\\circ=\\overline{OF}-\\overline{OB}=\\overline{BF}$"],"설명":"$O$, $B$, $F$ 는 한 직선 위에 있으므로 $OF-OB=BF$ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-78354c590568":{"길":"호의 비를 원주각의 비로 바꿔 각을 구하고 보기 ㄱ~ㄹ 을 차례로 확인한다","단계":[{"제목":"ㄱ 현과 호의 길이","힌트":"호의 길이가 두 배이면 현의 길이도 두 배가 되는가?","식":["$\\overset{\\frown}{BC}=2\\,\\overset{\\frown}{AB}$"],"설명":"호의 길이는 원주각에 정비례하지만 현의 길이는 정비례하지 않는다. 그러므로 $BC=2AB$ 라 할 수 없어 ㄱ 은 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"ㄴ 원주각의 비","힌트":"호의 길이의 비와 원주각의 크기의 비는 어떤 관계인가? ∠ADB 는?","식":["$\\angle AEB:\\angle BDC=1:2,\\ \\angle BDC=40^\\circ$","$\\angle ADC=20^\\circ+40^\\circ=60^\\circ$"],"설명":"호 $AB$ 와 호 $BC$ 의 길이의 비가 $1:2$ 이므로 원주각의 비도 $1:2$ 이다. 같은 호 $AB$ 에 대한 원주각이므로 $\\angle ADB=\\angle AEB=20^\\circ$ 이다. ㄴ 은 옳다.","확인":null,"스킬":"S5","고비":true},{"제목":"E 에서 본 각","힌트":"세 호 $AB$, $BC$, $CD$ 에 대한 원주각 $\\angle AEB$, $\\angle BEC$, $\\angle CED$ 는?","식":["$\\angle AEB:\\angle BEC:\\angle CED=1:2:3$","$\\angle BED=40^\\circ+60^\\circ=100^\\circ$"],"설명":"호의 길이의 비가 $1:2:3$ 이므로 원주각의 비도 같고, $\\angle AEB=20^\\circ$ 이므로 세 각은 $20^\\circ$, $40^\\circ$, $60^\\circ$ 이다.","확인":null,"스킬":"S5"},{"제목":"ㄷ 호의 비","힌트":"원에 내접하는 사각형 ACDE 에서 ∠ACD 는? 두 호의 비는 어느 두 원주각의 비와 같은가?","식":["$\\angle ACD=180^\\circ-(20^\\circ+100^\\circ)=60^\\circ$","$\\overset{\\frown}{DCB}:\\overset{\\frown}{ADC}=\\angle BED:\\angle ABC=100^\\circ:120^\\circ=5:6$"],"설명":"원에 내접하는 사각형은 마주 보는 두 각의 합이 $180^\\circ$ 이다. 호 $DCB$ 와 호 $ADC$ 의 길이의 비는 각 호에 대한 원주각 $\\angle BED$ 와 $\\angle ABC=60^\\circ+60^\\circ$ 의 비와 같다. ㄷ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄹ 내접사각형의 각","힌트":"원에 내접하는 사각형 BCDE 에서 ∠BCD 는?","식":["$\\angle BCD=180^\\circ-\\angle BED=180^\\circ-100^\\circ=80^\\circ$"],"설명":"마주 보는 두 각의 합이 $180^\\circ$ 이므로 ㄹ 은 옳다. 옳은 것은 ㄴ, ㄷ, ㄹ 이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-78987289fa7e":{"길":"색칠한 부분을 직사각형과 두 반원으로 나눠 반원이 서로 상쇄됨을 이용해 이차방정식을 세운다","단계":[{"제목":"넓이 식 세우기","힌트":"색칠한 부분을 직사각형과 반원으로 나누면 두 반원의 넓이는 어떻게 되는가?","식":["$\\frac12\\pi x^2+2x(x+3)-\\frac12\\pi x^2=36$"],"설명":"가로 $x+3$, 세로 $2x$ 인 직사각형에 오른쪽 반원이 더해지고 왼쪽 반원이 빠진다. 두 반원의 넓이는 같으므로 서로 없어진다.","확인":null,"스킬":"S12","고비":true},{"제목":"이차방정식 풀기","힌트":"반원이 없어진 식을 정리해 이차방정식으로 풀면?","식":["$x^2+3x-18=0$","$(x+6)(x-3)=0$"],"설명":"$2x(x+3)=36$ 에서 양변을 $2$ 로 나눈다.","확인":null,"스킬":"S12"},{"제목":"x 의 값","힌트":"반지름이 될 수 있는 근은 어느 것인가?","식":["$x=3$"],"설명":"반지름 $x$ 는 양수이므로 $x=-6$ 은 버린다.","확인":"3","스킬":"C2"}],"fb":"fig/ns/"},"ns-78e92fef61ab":{"길":"정오각형의 각으로 닮은 삼각형을 찾아 비례식을 세우고 이차방정식의 양의 근을 구한다","단계":[{"제목":"이등변삼각형의 밑각","힌트":"정오각형의 한 내각을 이용해 이등변삼각형 ABC 의 밑각을 구하면?","식":["$\\angle ABC=108^\\circ$","$\\angle BAC=\\angle BCA=\\frac12(180^\\circ-108^\\circ)=36^\\circ$"],"설명":"정오각형의 한 내각은 $108^\\circ$ 이고 $AB=BC$ 이므로 삼각형 $ABC$ 는 이등변삼각형이다.","확인":null,"스킬":"S10"},{"제목":"CF 의 길이","힌트":"$AC$ 와 $BE$ 의 교점 F 에 대해 삼각형 CBF 의 각을 구하면?","식":["$\\angle ABE=36^\\circ,\\ \\angle CFB=72^\\circ,\\ \\angle CBF=72^\\circ$","$\\overline{CF}=\\overline{CB}=4$"],"설명":"$\\triangle ABC\\equiv\\triangle EAB$ 이므로 $\\angle ABE=36^\\circ$ 이다. 삼각형 $AFB$ 의 외각 $\\angle CFB=36^\\circ+36^\\circ=72^\\circ$ 이고, 삼각형 $CBF$ 에서 $\\angle CBF=72^\\circ$ 이므로 $CB=CF$ 이다.","확인":null,"스킬":"S10"},{"제목":"닮음과 비례식","힌트":"공통인 각과 36° 로 서로 닮은 두 삼각형을 찾으면 대응하는 변의 비는?","식":["$\\triangle ABC\\sim\\triangle AFB$","$4:(x-4)=x:4$"],"설명":"$\\angle BAC$ 가 공통이고 $\\angle ACB=\\angle ABF=36^\\circ$ 이므로 두 삼각형은 $AA$ 닮음이다. $AF=AC-CF=x-4$ 이다.","확인":null,"스킬":"S1","고비":true},{"제목":"x 의 값","힌트":"비례식을 이차방정식으로 고쳐 근의 공식으로 풀면?","식":["$x^2-4x-16=0$","$x=2\\pm2\\sqrt5$","$x=2+2\\sqrt5$"],"설명":"$x$ 는 길이이므로 양수이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-79fa6f475611":{"길":"반지름과 접선의 수직으로 합동을 찾고 닮음의 비례식과 접선 길이 성질로 선지를 하나씩 확인한다","단계":[{"제목":"합동인 삼각형","힌트":"접점에서 반지름과 접선이 이루는 각과 OC=OE 를 써서 합동인 삼각형을 찾으면?","식":["$\\triangle COD\\equiv\\triangle EOD\\ (RHS)$","$\\triangle AOB\\equiv\\triangle EOB\\ (RHS)$","$\\angle ABO=\\angle EBO$"],"설명":"$OD$ 는 공통, $\\angle OCD=\\angle OED=90^\\circ$, $OC=OE$ 이므로 $RHS$ 합동이다. $\\triangle AOB$ 와 $\\triangle EOB$ 도 같은 방법으로 합동이다. ①, ② 는 옳다.","확인":null,"스킬":"S5"},{"제목":"각 BOD","힌트":"$\\angle COD=\\angle EOD=a$, $\\angle AOB=\\angle EOB=b$ 로 놓으면 $a+b$ 는?","식":["$2a+2b=180^\\circ$","$\\angle BOD=a+b=90^\\circ$"],"설명":"$AC$ 가 지름이므로 $\\angle AOC=180^\\circ$ 이다. ③ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"닮음과 비례식","힌트":"삼각형 BOE 와 ODE 가 닮은 이유와 대응하는 변의 비는?","식":["$\\triangle BOE\\sim\\triangle ODE\\ (AA)$","$\\overline{OB}:\\overline{OD}=\\overline{BE}:\\overline{OE}$"],"설명":"$\\angle BEO=\\angle OED=90^\\circ$ 이고 $\\angle BOE=b=90^\\circ-a=\\angle ODE$ 이므로 $AA$ 닮음이다. 선지 ④ 의 $\\overline{BE}:\\overline{ED}$ 와 다르므로 ④ 가 옳지 않다.","확인":null,"스킬":"S1","고비":true},{"제목":"접선의 길이","힌트":"한 점에서 원에 그은 두 접선의 길이는 어떤 관계인가? AB + CD 는?","식":["$\\overline{BA}=\\overline{BE},\\ \\overline{DC}=\\overline{DE}$","$\\overline{AB}+\\overline{CD}=\\overline{BE}+\\overline{DE}=\\overline{BD}$"],"설명":"한 점에서 원에 그은 두 접선의 길이는 같다. ⑤ 는 옳다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-79fd1ed93706":{"길":"같은 크기의 원주각이 같은 현과 호를 만든다는 성질로 보기 ㄱ~ㄹ 을 차례로 따진다","단계":[{"제목":"ㄱ 같은 원주각의 현","힌트":"크기가 같은 원주각에 대한 현의 길이는 어떤 관계인가?","식":["$\\angle ACB=\\angle DBE\\ \\Rightarrow\\ \\overline{AB}=\\overline{DE}$"],"설명":"한 원에서 크기가 같은 원주각에 대한 현의 길이는 같다. ㄱ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄴ 세 현의 관계","힌트":"AB, CD, DE 의 길이는 어떤 관계인가? 삼각형 CDE 에서 두 변의 합과 CE 는?","식":["$\\overline{AB}=\\overline{CD}=\\overline{DE}$","$2\\overline{AB}=\\overline{CD}+\\overline{DE}>\\overline{CE}$"],"설명":"$\\angle ACB=\\angle CBD$ 이므로 $AB=CD$ 이다. 삼각형에서 두 변의 길이의 합은 나머지 한 변의 길이보다 길다. ㄴ 은 옳다.","확인":null,"스킬":"S5","고비":true},{"제목":"ㄷ 호의 길이","힌트":"원주각의 크기와 호의 길이는 어떤 관계인가? ∠CBE 는 ∠ACB 의 몇 배인가?","식":["$\\overset{\\frown}{AB}:\\overset{\\frown}{CE}=\\angle ACB:\\angle CBE=1:2$","$\\overset{\\frown}{CE}=2\\,\\overset{\\frown}{AB}$"],"설명":"원주각의 크기는 호의 길이에 비례한다. ㄷ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄹ 합동 조건","힌트":"삼각형 CBA 와 BCD 가 합동이 되는 조건이 모두 주어졌는가?","식":["$\\triangle CBA\\equiv\\triangle BCD\\ \\text{를 알 수 없다}$"],"설명":"합동이 되기 위한 조건이 부족하므로 합동인지 알 수 없다. 옳은 것은 ㄱ, ㄴ, ㄷ 이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-7c5c4d6c66b1":{"길":"수선의 발 H 를 잡아 AH, EH 를 구하고 x 의 삼각비와 넓이로 보기를 하나씩 확인한다","단계":[{"제목":"DE 의 길이","힌트":"직각삼각형 DCE 에서 ∠DCE 와 CE 를 이용해 DE 를 구하면?","식":["$\\tan60^\\circ=\\frac{\\overline{DE}}{3}=\\sqrt3$","$\\overline{DE}=3\\sqrt3$"],"설명":"$E$ 는 $BC$ 의 중점이므로 $CE=3$ 이고 $\\angle DCE=60^\\circ$ 이다. ㄱ 은 옳다.","확인":null,"스킬":"S6"},{"제목":"수선의 발 H","힌트":"점 A 에서 DE 에 내린 수선의 발 H 는 삼각형 BCD 의 어떤 점인가?","식":["$\\overline{AE}=\\overline{DE}=3\\sqrt3$","$\\overline{EH}=\\frac13\\overline{DE}=\\sqrt3$","$\\overline{AH}=\\sqrt{(3\\sqrt3)^2-(\\sqrt3)^2}=2\\sqrt6$"],"설명":"점 $A$ 에서 $DE$ 에 내린 수선의 발을 $H$ 라 하면 $H$ 는 삼각형 $BCD$ 의 무게중심이다. 정삼각형 $ABC$ 의 높이도 $3\\sqrt3$ 이므로 $AE=DE$ 이다.","확인":null,"스킬":"S2","고비":true},{"제목":"x 의 삼각비","힌트":"직각삼각형 AEH 에서 sin x, cos x, tan x 는?","식":["$\\sin x=\\frac{2\\sqrt2}{3},\\ \\cos x=\\frac13,\\ \\tan x=2\\sqrt2$","$\\tan x-\\sin x=\\frac{4\\sqrt2}{3}$"],"설명":"$\\sin x=\\frac{AH}{AE}$, $\\cos x=\\frac{EH}{AE}$, $\\tan x=\\frac{AH}{EH}$ 이다. ㄴ, ㄷ 은 옳다.","확인":null,"스킬":"S6"},{"제목":"ㄹ, ㅁ 의 넓이","힌트":"두 변과 끼인각으로 삼각형 ABC 와 AED 의 넓이를 구하면?","식":["$\\triangle ABC=\\frac12\\times6\\times6\\times\\sin60^\\circ=9\\sqrt3$","$\\triangle AED=\\frac12\\times3\\sqrt3\\times3\\sqrt3\\times\\sin x=9\\sqrt2$"],"설명":"ㅁ 은 $18\\sqrt2$ 가 아니라 $9\\sqrt2$ 이므로 옳지 않다. 옳은 것은 ㄱ, ㄴ, ㄷ, ㄹ 의 $4$개이다.","확인":"4","스킬":"S6"}],"fb":"fig/ns/"},"ns-7e1fc6a97552":{"길":"접점까지 거리를 x 로 놓고 A 에서 E 까지 접선 길이를 차례로 구해 PE 에서 x 가 사라짐을 확인한다","단계":[{"제목":"접점 거리를 x 로 놓기","힌트":"네 내접원이 서로 닿는 점에서 P 까지의 거리는 어떻게 놓는가?","식":["$\\overline{PF}=\\overline{PK}=\\overline{PL}=\\overline{PM}=\\overline{PN}=x$"],"설명":"내접원 $O_1$ 이 $PA$, $AB$ 에 닿는 점을 $F$, $G$ 라 하고, 원 $O_2$, $O_3$, $O_4$ 가 $BC$, $CD$, $DE$ 에 닿는 점을 $H$, $I$, $J$, $PE$ 에 닿는 점을 $N$ 이라 한다. 이웃한 원이 $PB$, $PC$, $PD$ 위에서 닿는 점을 $K$, $L$, $M$ 이라 하면 한 점에서 그은 접선의 길이가 같으므로 $P$ 에서 이 점들까지의 거리가 모두 같다.","확인":null,"스킬":"C7","고비":true},{"제목":"AF 와 BG, CH","힌트":"한 점에서 원에 그은 두 접선의 길이가 같음을 써서 A 에서 C 쪽으로 차례로 구하면?","식":["$\\overline{AF}=\\overline{AG}=25-x$","$\\overline{BG}=\\overline{BK}=\\overline{BH}=20-(25-x)=x-5$","$\\overline{CH}=\\overline{CL}=\\overline{CI}=15-(x-5)=20-x$"],"설명":"$PA=25$, $AB=20$, $BC=15$ 에서 각 꼭짓점의 접선 길이를 이어 간다.","확인":null,"스킬":"S5"},{"제목":"DI 와 EJ","힌트":"같은 방법으로 D, E 쪽의 접선 길이를 구하면?","식":["$\\overline{DI}=\\overline{DM}=\\overline{DJ}=10-(20-x)=x-10$","$\\overline{EJ}=\\overline{EN}=5-(x-10)=15-x$"],"설명":"$CD=10$, $DE=5$ 에서 이어 간다.","확인":null,"스킬":"S5"},{"제목":"PE 의 길이","힌트":"PE 를 PN 과 EN 의 합으로 쓰면 x 는 어떻게 되는가?","식":["$\\overline{PE}=\\overline{PN}+\\overline{EN}=x+(15-x)=15$"],"설명":"$x$ 가 소거되어 $PE$ 가 정해진다.","확인":"15","스킬":"C7"}],"fb":"fig/ns/"},"ns-859957e2f9fe":{"길":"접선의 길이가 같음을 써서 CA 를 x 로 놓고 PA 와 PB 가 같다는 식을 세운다","단계":[{"제목":"식 세우기","힌트":"CA=CE=x 로 놓으면 DE, DB 는 어떻게 나타내는가? PA 와 PB 는?","식":["$\\overline{CA}=\\overline{CE}=x,\\ \\overline{DE}=\\overline{DB}=6-x$","$7+x=9+(6-x)$"],"설명":"그림에서 $PC=7$, $PD=9$, $CD=6$ 이다. 한 점에서 원에 그은 두 접선의 길이가 같으므로 $CA=CE$, $DE=DB$ 이고, $PA=PB$ 이다.","확인":null,"스킬":"S5","고비":true},{"제목":"x 와 DB","힌트":"식을 정리해 x 와 DB 를 구하면?","식":["$2x=8,\\ x=4$","$\\overline{DB}=6-4=2$"],"설명":"$AC=4$ 이므로 ① 은 옳지 않고, $DB=2$ 이므로 ② 도 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"삼각형 PDC 의 둘레","힌트":"삼각형 PDC 의 둘레를 접선 길이로 바꿔 PA, PB 로 나타내면?","식":["$\\overline{PC}+\\overline{CD}+\\overline{PD}=\\overline{PC}+\\overline{CA}+\\overline{DB}+\\overline{PD}=\\overline{PA}+\\overline{PB}=2\\overline{PA}$"],"설명":"$CD=CE+DE=CA+DB$ 이므로 둘레는 $PA+PB$ 가 된다. ⑤ 는 옳다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-8ba060befa8d":{"길":"굴러간 거리를 원의 둘레로 놓아 a 를 정한 뒤 보기를 하나씩 유리수와 무리수로 가른다","단계":[{"제목":"점 A 에 대응하는 수 a","힌트":"원을 한 바퀴 굴리면 수직선 위에서 움직인 거리는 원의 어느 부분의 길이와 같을까?","식":["$a=2\\pi\\times2=4\\pi$"],"설명":"한 바퀴 굴러 수직선과 다시 접하는 점 $\\mathrm{A}$ 는 원점에서 원의 둘레만큼 떨어져 있다. 반지름이 $2$ 인 원의 둘레는 $4\\pi$ 이므로 $a=4\\pi$ 이다.","확인":null,"스킬":"C7","고비":false},{"제목":"①~④ 의 판정","힌트":"$\\pi$ 가 무리수일 때 여기에 유리수를 더하거나 곱한 수는 어떤 수일까?","식":["$2a=8\\pi$","$4\\pi-a=0$","$a+\\sqrt{2}=4\\pi+\\sqrt{2}$"],"설명":"$8\\pi$ 와 $4\\pi$ 는 무리수이고 $4\\pi-a=0$ 은 유리수이다. $4\\pi+\\sqrt{2}$ 는 무리수이므로 순환하지 않는 무한소수이다. 따라서 ①~④ 는 옳다.","확인":null,"스킬":"N6","고비":true},{"제목":"⑤ 의 판정","힌트":"$\\frac{m}{n}$ 꼴로 나타낼 수 있는 수는 어떤 수일까?","식":["$a-3=4\\pi-3$"],"설명":"$\\frac{m}{n}$ ($m$, $n$ 은 정수, $n\\neq0$) 꼴로 나타낼 수 있는 수는 유리수이다. $4\\pi-3$ 은 무리수이므로 이 꼴로 나타낼 수 없고, 옳지 않은 것은 ⑤ 이다.","확인":null,"스킬":"N6","고비":false}],"fb":"fig/ns/"},"ns-8d234abf05e6":{"길":"평행이동으로 잘라 붙여 색칠한 넓이를 직사각형의 넓이로 바꾼 뒤 평행이동한 거리를 구한다","단계":[{"제목":"처음 포물선의 꼭짓점","힌트":"이차식을 완전제곱 꼴로 고치면 꼭짓점이 보일까?","식":["$y=(x-1)^{2}-4$","$\\mathrm{P}(1,\\,-4)$"],"설명":"$x^{2}-2x-3=(x^{2}-2x+1)-1-3=(x-1)^{2}-4$ 이므로 꼭짓점은 $\\mathrm{P}(1,\\,-4)$ 이다.","확인":null,"스킬":"A6","고비":false},{"제목":"평행이동한 포물선의 꼭짓점","힌트":"$x$ 축 방향으로 $p$ 만큼 옮기면 식의 $x$ 는 어떻게 바뀔까?","식":["$y=(x-1-p)^{2}-4$","$\\mathrm{Q}(1+p,\\,-4)$"],"설명":"$x$ 대신 $x-p$ 를 넣은 식이므로 꼭짓점도 $x$ 축 방향으로 $p$ 만큼 이동하여 $\\mathrm{Q}(1+p,\\,-4)$ 이다.","확인":null,"스킬":"G4","고비":false},{"제목":"색칠한 부분을 직사각형으로","힌트":"한 포물선을 평행이동하면 다른 포물선과 겹친다. 이를 이용해 색칠한 부분을 어떤 도형으로 바꿀 수 있을까?","식":["$\\square \\mathrm{PQBA}=20$"],"설명":"두 점 $\\mathrm{P}$, $\\mathrm{Q}$ 에서 $x$ 축에 내린 수선의 발을 각각 $\\mathrm{A}$, $\\mathrm{B}$ 라 한다. 두 포물선은 평행이동으로 겹치므로 색칠한 부분을 잘라 옮기면 직사각형 $\\mathrm{PQBA}$ 가 된다. 따라서 색칠한 부분의 넓이는 $\\square \\mathrm{PQBA}$ 의 넓이와 같다.","확인":null,"스킬":"S12","고비":true},{"제목":"p 의 값","힌트":"직사각형의 가로와 세로는 각각 얼마일까?","식":["$p\\times4=20$","$p=5$"],"설명":"$\\square \\mathrm{PQBA}$ 의 가로는 $\\overline{\\mathrm{PQ}}=p$, 세로는 꼭짓점의 $y$ 좌표의 절댓값 $4$ 이므로 넓이는 $4p$ 이다. $4p=20$ 에서 $p=5$ 이다.","확인":"5","스킬":"G10","고비":false},{"제목":"평행이동한 이차함수의 식","힌트":"구한 $p$ 의 값을 넣어 전개하면 어떤 식이 될까?","식":["$y=(x-6)^{2}-4$","$y=x^{2}-12x+32$"],"설명":"$y=(x-1-5)^{2}-4=(x-6)^{2}-4=x^{2}-12x+32$ 이므로 정답은 ⑤ 이다.","확인":null,"스킬":"G4","고비":false}],"fb":"fig/ns/"},"ns-8f638bfb67c8":{"길":"접선과 반지름이 수직임을 이용해 직각삼각형 PAO 의 변과 각을 구한 뒤 보기와 비교한다","단계":[{"제목":"PO 의 길이","힌트":"접선과 접점을 지나는 반지름이 이루는 각은 몇 도일까?","식":["$\\overline{\\mathrm{PO}}=\\sqrt{(2\\sqrt{3})^{2}+2^{2}}=4$"],"설명":"접선은 접점을 지나는 반지름과 수직이므로 $\\angle \\mathrm{PAO}=90^{\\circ}$ 이다. 직각삼각형 $\\mathrm{PAO}$ 에서 피타고라스 정리를 쓰면 $\\overline{\\mathrm{PO}}=4$ 이고 ① 은 옳다.","확인":"4","스킬":"S3","고비":false},{"제목":"∠APB 의 크기","힌트":"$\\overline{\\mathrm{PO}}$ 와 $\\overline{\\mathrm{AO}}$ 의 비로 $\\angle \\mathrm{APO}$ 를 알 수 있을까?","식":["$\\overline{\\mathrm{PO}}:\\overline{\\mathrm{AO}}=2:1$","$\\angle \\mathrm{APO}=30^{\\circ}$","$\\angle \\mathrm{APB}=2\\times30^{\\circ}=60^{\\circ}$"],"설명":"빗변과 한 변의 길이의 비가 $2:1$ 인 직각삼각형이므로 $\\angle \\mathrm{APO}=30^{\\circ}$ 이다. 두 접선에 대해 $\\overline{\\mathrm{PO}}$ 는 $\\angle \\mathrm{APB}$ 를 이등분하므로 $\\angle \\mathrm{APB}=60^{\\circ}$ 이고, ③ 은 옳지 않다.","확인":"60","스킬":"S10","고비":true},{"제목":"나머지 보기 확인","힌트":"합동 조건과 $\\angle \\mathrm{APB}$ 의 크기로 $\\triangle \\mathrm{PAB}$ 의 모양을 알 수 있을까?","식":["$\\triangle \\mathrm{PAO}\\equiv\\triangle \\mathrm{PBO}\\ (\\mathrm{RHS})$","$\\overline{\\mathrm{PA}}=\\overline{\\mathrm{AB}}$"],"설명":"$\\overline{\\mathrm{PO}}$ 는 공통, $\\overline{\\mathrm{AO}}=\\overline{\\mathrm{BO}}$, $\\angle \\mathrm{PAO}=\\angle \\mathrm{PBO}=90^{\\circ}$ 이므로 $\\mathrm{RHS}$ 합동이고 ④, ⑤ 는 옳다. $\\overline{\\mathrm{PA}}=\\overline{\\mathrm{PB}}$ 이고 $\\angle \\mathrm{APB}=60^{\\circ}$ 이므로 $\\triangle \\mathrm{PAB}$ 는 정삼각형이고 ② 도 옳다.","확인":null,"스킬":"S5","고비":false}],"fb":"fig/ns/"},"ns-8f9b4145522b":{"길":"원주각의 크기가 같음으로 각을 옮기고, 닮은 삼각형으로 길이의 곱을 비교한다","단계":[{"제목":"(ㄱ) 의 판정","힌트":"$\\angle \\mathrm{ABC}$ 와 $\\angle \\mathrm{AEC}$ 는 어느 호에 대한 원주각일까?","식":["$\\angle \\mathrm{ABC}=\\angle \\mathrm{AEC}$"],"설명":"두 각은 모두 호 $\\mathrm{AC}$ 에 대한 원주각이므로 크기가 같다. 따라서 (ㄱ) 은 옳다.","확인":null,"스킬":"S5","고비":false},{"제목":"(ㄴ) 의 판정","힌트":"$\\angle \\mathrm{CBE}$, $\\angle \\mathrm{BCE}$ 를 $\\angle \\mathrm{A}$ 의 두 부분과 연결할 수 있을까?","식":["$\\angle \\mathrm{CBE}=\\angle \\mathrm{CAE}$","$\\angle \\mathrm{BCE}=\\angle \\mathrm{BAE}$"],"설명":"각각 호 $\\mathrm{CE}$, 호 $\\mathrm{BE}$ 에 대한 원주각이다. $\\overline{\\mathrm{AE}}$ 는 $\\angle \\mathrm{A}$ 의 이등분선이므로 $\\angle \\mathrm{BAE}=\\angle \\mathrm{CAE}$ 이고, $\\angle \\mathrm{CBE}=\\angle \\mathrm{BCE}$ 이다.","확인":null,"스킬":"S5","고비":false},{"제목":"(ㄷ) 의 판정","힌트":"곱의 꼴로 된 등식을 비례식으로 바꾸려면 어느 두 삼각형이 닮아야 할까?","식":["$\\triangle \\mathrm{ABD}\\sim\\triangle \\mathrm{AEC}$","$\\overline{\\mathrm{AB}}\\times\\overline{\\mathrm{AC}}=\\overline{\\mathrm{AD}}\\times\\overline{\\mathrm{AE}}$"],"설명":"$\\angle \\mathrm{BAD}=\\angle \\mathrm{EAC}$, $\\angle \\mathrm{ABD}=\\angle \\mathrm{AEC}$ 이므로 $\\mathrm{AA}$ 닮음이다. 대응하는 변의 비에서 $\\overline{\\mathrm{AB}}\\times\\overline{\\mathrm{AC}}=\\overline{\\mathrm{AD}}\\times\\overline{\\mathrm{AE}}$ 이므로 (ㄷ) 은 옳지 않고, 답은 (ㄱ), (ㄴ) 이다.","확인":null,"스킬":"S5","고비":true}],"fb":"fig/ns/"},"ns-90c7f4425734":{"길":"점 P 에서 변 CD 에 수선을 그어 닮은 직각삼각형을 만들고 닮음비를 삼각비로 읽는다","단계":[{"제목":"QC 와 같은 선분","힌트":"점 $\\mathrm{P}$ 에서 $\\overline{\\mathrm{CD}}$ 위로 수선을 그으면 $\\overline{\\mathrm{QC}}$ 와 길이가 같은 선분이 생기지 않을까?","식":["$\\overline{\\mathrm{QC}}=\\overline{\\mathrm{PH}}$"],"설명":"점 $\\mathrm{P}$ 에서 $\\overline{\\mathrm{RC}}$ 에 내린 수선의 발을 $\\mathrm{H}$ 라 한다. $\\square \\mathrm{PQCH}$ 는 세 각이 직각인 직사각형이므로 $\\overline{\\mathrm{QC}}=\\overline{\\mathrm{PH}}$ 이다.","확인":null,"스킬":"S2","고비":false},{"제목":"닮은 삼각형 찾기","힌트":"$\\triangle \\mathrm{RPH}$ 와 닮은 삼각형은 어디에 있을까?","식":["$\\triangle \\mathrm{RPH}\\sim\\triangle \\mathrm{PBQ}$"],"설명":"$\\triangle \\mathrm{BCR}$ 에서 $\\angle \\mathrm{BRC}=90^{\\circ}-50^{\\circ}=40^{\\circ}$ 이고, $\\triangle \\mathrm{PBQ}$ 에서 $\\angle \\mathrm{BPQ}=90^{\\circ}-50^{\\circ}=40^{\\circ}$ 이다. $\\angle \\mathrm{PHR}=\\angle \\mathrm{BQP}=90^{\\circ}$ 와 함께 두 각이 같으므로 $\\mathrm{AA}$ 닮음이다.","확인":null,"스킬":"S1","고비":true},{"제목":"비로 바꾸기","힌트":"닮음에서 $\\overline{\\mathrm{PH}}:\\overline{\\mathrm{PR}}$ 에 대응하는 비는 무엇일까?","식":["$\\frac{\\overline{\\mathrm{QC}}}{\\overline{\\mathrm{PR}}}=\\frac{\\overline{\\mathrm{PH}}}{\\overline{\\mathrm{PR}}}=\\frac{\\overline{\\mathrm{BQ}}}{\\overline{\\mathrm{BP}}}$"],"설명":"$\\angle \\mathrm{R}$ 의 대변과 빗변의 비가 $\\angle \\mathrm{P}$ 의 대변과 빗변의 비와 같으므로 $\\overline{\\mathrm{PH}}:\\overline{\\mathrm{PR}}=\\overline{\\mathrm{BQ}}:\\overline{\\mathrm{BP}}$ 이다.","확인":null,"스킬":"S1","고비":false},{"제목":"삼각비 읽기","힌트":"직각삼각형 $\\mathrm{PBQ}$ 에서 $\\overline{\\mathrm{BQ}}$ 와 $\\overline{\\mathrm{BP}}$ 의 비는 어떤 삼각비일까?","식":["$\\frac{\\overline{\\mathrm{BQ}}}{\\overline{\\mathrm{BP}}}=\\cos 50^{\\circ}$"],"설명":"$\\angle \\mathrm{PBQ}=50^{\\circ}$ 이므로 밑변 $\\overline{\\mathrm{BQ}}$ 와 빗변 $\\overline{\\mathrm{BP}}$ 의 비는 $\\cos 50^{\\circ}$ 이다. 따라서 구하는 값은 $\\cos 50^{\\circ}$ 이다.","확인":null,"스킬":"S6","고비":false}],"fb":"fig/ns/"},"ns-9484a662a60c":{"길":"그래프에서 세 반의 평균과 분산을 구한 뒤 보기와 비교한다","단계":[{"제목":"세 반의 평균","힌트":"각 반의 (변량×도수)의 합을 학생 수로 나누면 얼마일까?","식":["$\\mathrm{A}:\\ \\frac{3\\times2+4\\times2+5\\times2+6\\times2+7\\times2}{10}=5$","$\\mathrm{B}:\\ \\frac{3\\times3+4\\times1+5\\times2+6\\times1+7\\times3}{10}=5$","$\\mathrm{C}:\\ \\frac{3\\times1+4\\times2+5\\times4+6\\times2+7\\times1}{10}=5$"],"설명":"세 반 모두 학생 수가 $10$ 명이고 평균은 $5$ 권이다.","확인":"5","스킬":"C3","고비":false},{"제목":"세 반의 분산","힌트":"편차의 제곱에 도수를 곱해 더한 뒤 도수의 총합으로 나누면 얼마일까?","식":["$\\mathrm{A}:\\ \\frac{(-2)^{2}\\times2+(-1)^{2}\\times2+0^{2}\\times2+1^{2}\\times2+2^{2}\\times2}{10}=2$","$\\mathrm{B}:\\ \\frac{(-2)^{2}\\times3+(-1)^{2}\\times1+0^{2}\\times2+1^{2}\\times1+2^{2}\\times3}{10}=2.6$","$\\mathrm{C}:\\ \\frac{(-2)^{2}\\times1+(-1)^{2}\\times2+0^{2}\\times4+1^{2}\\times2+2^{2}\\times1}{10}=1.2$"],"설명":"편차는 변량에서 평균 $5$ 를 뺀 값이다. 분산은 $\\mathrm{A}$ 가 $2$, $\\mathrm{B}$ 가 $2.6$, $\\mathrm{C}$ 가 $1.2$ 이다.","확인":null,"스킬":"C3","고비":true},{"제목":"보기 판정","힌트":"분산의 크기 순서와 평균을 보기와 비교하면 어떻게 될까?","식":["$1.2<2<2.6$"],"설명":"분산이 가장 작은 반은 $\\mathrm{C}$ 이므로 ㄱ 은 옳지 않고 ㄷ 은 옳다. 표준편차도 $\\mathrm{C}$ 가 가장 작으므로 ㄴ 은 옳지 않다. 평균이 모두 $5$ 이므로 ㄹ 은 옳고, $\\mathrm{B}$ 의 분산이 더 크므로 ㅁ 은 옳지 않다.","확인":null,"스킬":"C3","고비":false}],"fb":"fig/ns/"},"ns-94cc24e63ec7":{"길":"접선의 길이로 CD 를 구하고 보조선으로 AB 를 구한 뒤 합동과 넓이를 보기와 비교한다","단계":[{"제목":"CD 의 길이","힌트":"한 점에서 원에 그은 두 접선의 길이는 어떤 관계일까?","식":["$\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CE}}=4$","$\\overline{\\mathrm{DB}}=\\overline{\\mathrm{DE}}=6$","$\\overline{\\mathrm{CD}}=10$"],"설명":"$\\mathrm{C}$, $\\mathrm{D}$ 에서 원에 그은 접선의 길이가 각각 같으므로 $\\overline{\\mathrm{CD}}=\\overline{\\mathrm{CE}}+\\overline{\\mathrm{DE}}=10$ 이다.","확인":"10","스킬":"S5","고비":false},{"제목":"AB 의 길이","힌트":"점 $\\mathrm{C}$ 에서 $\\overline{\\mathrm{BD}}$ 에 수선을 그으면 어떤 직각삼각형이 생길까?","식":["$\\overline{\\mathrm{HD}}=6-4=2$","$\\overline{\\mathrm{CH}}=\\sqrt{10^{2}-2^{2}}=4\\sqrt{6}$","$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{CH}}=4\\sqrt{6}$"],"설명":"점 $\\mathrm{C}$ 에서 $\\overline{\\mathrm{BD}}$ 에 내린 수선의 발을 $\\mathrm{H}$ 라 하면 $\\overline{\\mathrm{HD}}=6-4=2$ 이다. 직각삼각형 $\\mathrm{CHD}$ 에서 $\\overline{\\mathrm{CH}}=4\\sqrt{6}$ 이고, $\\square \\mathrm{ACHB}$ 는 직사각형이므로 $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{CH}}$ 이다.","확인":null,"스킬":"S2","고비":true},{"제목":"∠COD 의 크기","힌트":"$\\triangle \\mathrm{AOC}$ 와 $\\triangle \\mathrm{EOC}$ 는 어떤 합동일까?","식":["$\\triangle \\mathrm{COA}\\equiv\\triangle \\mathrm{COE}$","$\\triangle \\mathrm{DOB}\\equiv\\triangle \\mathrm{DOE}$","$\\angle \\mathrm{COD}=90^{\\circ}$"],"설명":"$\\overline{\\mathrm{OC}}$ 는 공통, $\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OE}}$, $\\angle \\mathrm{OAC}=\\angle \\mathrm{OEC}=90^{\\circ}$ 이므로 $\\mathrm{RHS}$ 합동이고, $\\triangle \\mathrm{DOB}\\equiv\\triangle \\mathrm{DOE}$ 도 같다. 네 각 $\\angle \\mathrm{COA}$, $\\angle \\mathrm{COE}$, $\\angle \\mathrm{DOE}$, $\\angle \\mathrm{DOB}$ 의 합이 $180^{\\circ}$ 이므로 $\\angle \\mathrm{COD}=90^{\\circ}$ 이다.","확인":null,"스킬":"S5","고비":false},{"제목":"나머지 보기 확인","힌트":"$\\triangle \\mathrm{BOD}$ 의 밑변과 높이는 무엇일까?","식":["$\\overline{\\mathrm{OB}}=\\frac{1}{2}\\overline{\\mathrm{AB}}=2\\sqrt{6}$","$\\triangle \\mathrm{BOD}=\\frac{1}{2}\\times2\\sqrt{6}\\times6=6\\sqrt{6}$"],"설명":"$\\overline{\\mathrm{AB}}$ 는 지름이므로 $\\overline{\\mathrm{OB}}=2\\sqrt{6}$ 이고 $\\triangle \\mathrm{BOD}=6\\sqrt{6}$ 이다. 따라서 ⑤ 의 $12\\sqrt{6}$ 은 옳지 않다. ③, ④ 는 앞의 $\\mathrm{RHS}$ 합동에서 옳다.","확인":null,"스킬":"S3","고비":false}],"fb":"fig/ns/"},"ns-9cad7e5ee980":{"길":"직선의 절편으로 삼각형 AOB 의 넓이를 구하고, 점 P 를 문자로 두어 넓이 조건을 방정식으로 세운다","단계":[{"제목":"두 삼각형의 넓이","힌트":"직선이 $x$ 축, $y$ 축과 만나는 점의 좌표는 무엇일까?","식":["$\\mathrm{A}(6,\\,0)$","$\\mathrm{B}(0,\\,12)$","$\\triangle \\mathrm{AOB}=\\frac{1}{2}\\times6\\times12=36$"],"설명":"$y=0$ 을 대입하면 $x=6$, $x=0$ 을 대입하면 $y=12$ 이다. $\\triangle \\mathrm{AOB}$ 의 넓이는 $36$ 이므로 $\\triangle \\mathrm{MOP}$ 의 넓이는 $36\\times\\frac{1}{4}=9$ 이다.","확인":"9","스킬":"G10","고비":false},{"제목":"점 P 를 문자로 두고 식 세우기","힌트":"점 $\\mathrm{P}$ 의 $x$ 좌표를 $a$ 로 두면 $y$ 좌표와 $\\mathrm{M}$ 의 좌표는 무엇일까?","식":["$\\mathrm{P}(a,\\,-2a+12)$","$\\mathrm{M}(0,\\,-2a+12)$","$\\frac{1}{2}\\times a\\times(-2a+12)=9$"],"설명":"$\\mathrm{P}$ 는 직선 위의 점이므로 $y$ 좌표는 $-2a+12$ 이다. $\\triangle \\mathrm{MOP}$ 는 밑변이 $\\overline{\\mathrm{OM}}=-2a+12$, 높이가 $a$ 인 삼각형이다.","확인":null,"스킬":"G10","고비":true},{"제목":"방정식 풀이","힌트":"정리한 이차방정식을 인수분해하면 어떻게 될까?","식":["$a^{2}-6a+9=0$","$(a-3)^{2}=0$","$a=3$"],"설명":"$\\frac{1}{2}a(-2a+12)=9$ 를 정리하면 $a^{2}-6a+9=0$ 이다. $a=3$ 이므로 $\\mathrm{P}(3,\\,6)$ 이다.","확인":null,"스킬":"A6","고비":false}],"fb":"fig/ns/"},"ns-9f28ffd3865e":{"길":"방향의 규칙으로 가로·세로 좌표를 각각 제곱수의 합과 차로 나타낸 뒤 합차 공식으로 묶어 계산한다","단계":[{"제목":"좌표를 식으로 나타내기","힌트":"동·북·서·남이 며칠마다 되풀이되고, 가로와 세로는 각각 어느 날에 움직일까?","식":["$x=1^{2}-3^{2}+5^{2}-7^{2}+9^{2}-11^{2}+13^{2}$","$y=2^{2}-4^{2}+6^{2}-8^{2}+10^{2}-12^{2}$"],"설명":"방향은 $4$ 일마다 되풀이되어 홀수 날은 가로(동은 $+$, 서는 $-$), 짝수 날은 세로(북은 $+$, 남은 $-$)로 움직인다. $13$ 일째는 동쪽이므로 $x$ 좌표의 마지막 항은 $+13^{2}$ 이다.","확인":null,"스킬":"P1","고비":true},{"제목":"x 좌표 계산","힌트":"$13^{2}$ 을 뺀 항을 둘씩 묶어 $a^{2}-b^{2}$ 꼴로 바꾸면 어떻게 될까?","식":["$(1+3)(1-3)+(5+7)(5-7)+(9+11)(9-11)+13^{2}$","$=-2\\times36+169=97$"],"설명":"합차 공식 $a^{2}-b^{2}=(a+b)(a-b)$ 를 쓰면 각 묶음의 $a-b$ 가 $-2$ 이므로 $-2(1+3+5+7+9+11)=-72$ 이다. 여기에 $13^{2}=169$ 를 더한다.","확인":"97","스킬":"P1","고비":false},{"제목":"y 좌표 계산","힌트":"같은 방법으로 짝수 날의 항을 둘씩 묶으면 어떻게 될까?","식":["$(2+4)(2-4)+(6+8)(6-8)+(10+12)(10-12)$","$=-2\\times42=-84$"],"설명":"각 묶음의 $a-b$ 가 $-2$ 이므로 $-2(2+4+6+8+10+12)=-84$ 이다.","확인":"-84","스킬":"P1","고비":false},{"제목":"거북이의 위치","힌트":"구한 두 좌표를 순서쌍으로 나타내면 무엇일까?","식":["$(97,\\,-84)$"],"설명":"$13$ 일 후 거북이의 위치는 $(97,\\,-84)$ 이므로 정답은 ⑤ 이다.","확인":null,"스킬":"P1","고비":false}],"fb":"fig/ns/"},"ns-a339b8888219":{"길":"직각삼각형마다 삼각비로 변을 구해 보기를 하나씩 확인한다","단계":[{"제목":"BE 의 길이 (ㄱ)","힌트":"직각삼각형 $\\mathrm{BEF}$ 에서 $\\angle \\mathrm{EBF}$ 는 몇 도일까?","식":["$\\angle \\mathrm{EBF}=90^{\\circ}-60^{\\circ}=30^{\\circ}$","$\\sin30^{\\circ}=\\frac{2}{\\overline{\\mathrm{BE}}}$","$\\overline{\\mathrm{BE}}=4$"],"설명":"직각삼각형 $\\mathrm{DBC}$ 에서 $\\angle \\mathrm{D}=60^{\\circ}$ 이므로 $\\angle \\mathrm{EBF}=30^{\\circ}$ 이다. $\\triangle \\mathrm{BEF}$ 에서 $\\sin30^{\\circ}=\\frac{\\overline{\\mathrm{EF}}}{\\overline{\\mathrm{BE}}}$ 이므로 $\\overline{\\mathrm{BE}}=4$ 이고 ㄱ 은 옳다.","확인":"4","스킬":"S6","고비":false},{"제목":"CE 의 길이 (ㄴ)","힌트":"$\\angle \\mathrm{ACB}$ 는 몇 도일까?","식":["$\\angle \\mathrm{ECF}=45^{\\circ}$","$\\sin45^{\\circ}=\\frac{2}{\\overline{\\mathrm{CE}}}$","$\\overline{\\mathrm{CE}}=2\\sqrt{2}$"],"설명":"직각삼각형 $\\mathrm{ABC}$ 에서 $\\angle \\mathrm{A}=45^{\\circ}$ 이므로 $\\angle \\mathrm{ACB}=45^{\\circ}$ 이다. $\\overline{\\mathrm{CE}}=2\\sqrt{2}$ 이므로 ㄴ 은 옳지 않다.","확인":null,"스킬":"S6","고비":false},{"제목":"AB 의 길이","힌트":"$\\overline{\\mathrm{BF}}$ 와 $\\overline{\\mathrm{FC}}$ 는 각각 $\\tan$ 로 구할 수 있을까?","식":["$\\overline{\\mathrm{BF}}=2\\tan60^{\\circ}=2\\sqrt{3}$","$\\overline{\\mathrm{FC}}=2\\tan45^{\\circ}=2$","$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{BC}}=2\\sqrt{3}+2$"],"설명":"$\\angle \\mathrm{BEF}=60^{\\circ}$, $\\angle \\mathrm{CEF}=45^{\\circ}$ 이므로 $\\overline{\\mathrm{BF}}=2\\sqrt{3}$, $\\overline{\\mathrm{FC}}=2$ 이다. $\\triangle \\mathrm{ABC}$ 는 $\\angle \\mathrm{A}=\\angle \\mathrm{C}=45^{\\circ}$ 인 직각이등변삼각형이므로 $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{BC}}$ 이다.","확인":null,"스킬":"S6","고비":false},{"제목":"삼각형 ABE 의 넓이 (ㄷ)","힌트":"점 $\\mathrm{E}$ 에서 $\\overline{\\mathrm{AB}}$ 까지의 거리는 어느 선분의 길이와 같을까?","식":["$\\triangle \\mathrm{ABE}=\\frac{1}{2}\\times(2\\sqrt{3}+2)\\times2\\sqrt{3}$","$=6+2\\sqrt{3}$"],"설명":"$\\overline{\\mathrm{EF}}\\parallel\\overline{\\mathrm{AB}}$ 이므로 $\\mathrm{E}$ 에서 $\\overline{\\mathrm{AB}}$ 까지의 거리는 $\\overline{\\mathrm{BF}}=2\\sqrt{3}$ 이다. 넓이는 $6+2\\sqrt{3}$ 이므로 ㄷ 은 옳고, 답은 ㄱ, ㄷ 이다.","확인":null,"스킬":"S6","고비":true}],"fb":"fig/ns/"},"ns-a41be39422f1":{"길":"내각을 구해 이등분선이 직사각형을 이룸을 확인한 뒤 삼각비로 가로와 세로를 구한다","단계":[{"제목":"내각의 크기","힌트":"평행사변형에서 이웃한 두 내각의 합은 몇 도일까?","식":["$\\angle \\mathrm{B}=180^{\\circ}\\times\\frac{1}{3}=60^{\\circ}$","$\\angle \\mathrm{C}=180^{\\circ}\\times\\frac{2}{3}=120^{\\circ}$"],"설명":"이웃한 두 내각의 합은 $180^{\\circ}$ 이고 비가 $2:1$ 이므로 $\\angle \\mathrm{B}=60^{\\circ}$, $\\angle \\mathrm{C}=120^{\\circ}$ 이다. 마주 보는 각은 같으므로 $\\angle \\mathrm{A}=120^{\\circ}$, $\\angle \\mathrm{D}=60^{\\circ}$ 이다.","확인":null,"스킬":"S10","고비":false},{"제목":"직사각형임을 확인","힌트":"한 변의 양 끝 각의 이등분선이 만나서 이루는 각은 몇 도일까?","식":["$\\angle \\mathrm{ABP}=30^{\\circ}$","$\\angle \\mathrm{BAP}=60^{\\circ}$","$\\angle \\mathrm{APB}=90^{\\circ}$"],"설명":"$\\triangle \\mathrm{ABP}$ 에서 $\\angle \\mathrm{ABP}=\\frac{1}{2}\\angle \\mathrm{B}=30^{\\circ}$, $\\angle \\mathrm{BAP}=\\frac{1}{2}\\angle \\mathrm{A}=60^{\\circ}$ 이므로 $\\angle \\mathrm{APB}=90^{\\circ}$ 이다. 다른 세 꼭짓점도 같으므로 $\\square \\mathrm{PQRS}$ 는 직사각형이다.","확인":null,"스킬":"S10","고비":true},{"제목":"PQ 의 길이","힌트":"$\\overline{\\mathrm{AP}}$, $\\overline{\\mathrm{AQ}}$ 를 각각 삼각비로 구하면 얼마일까?","식":["$\\overline{\\mathrm{AP}}=6\\sin30^{\\circ}=3$","$\\overline{\\mathrm{AQ}}=10\\sin30^{\\circ}=5$","$\\overline{\\mathrm{PQ}}=5-3=2$"],"설명":"$\\mathrm{P}$, $\\mathrm{Q}$ 는 $\\angle \\mathrm{A}$ 의 이등분선 위에 있다. $\\triangle \\mathrm{ABP}$ 에서 $\\angle \\mathrm{ABP}=30^{\\circ}$ 의 대변이 $\\overline{\\mathrm{AP}}$ 이고, $\\triangle \\mathrm{ADQ}$ 에서 $\\angle \\mathrm{ADQ}=30^{\\circ}$ 의 대변이 $\\overline{\\mathrm{AQ}}$ 이다.","확인":"2","스킬":"S6","고비":false},{"제목":"PS 의 길이","힌트":"$\\overline{\\mathrm{BP}}$, $\\overline{\\mathrm{BS}}$ 를 각각 삼각비로 구하면 얼마일까?","식":["$\\overline{\\mathrm{BP}}=6\\cos30^{\\circ}=3\\sqrt{3}$","$\\overline{\\mathrm{BS}}=10\\cos30^{\\circ}=5\\sqrt{3}$","$\\overline{\\mathrm{PS}}=5\\sqrt{3}-3\\sqrt{3}=2\\sqrt{3}$"],"설명":"$\\mathrm{P}$, $\\mathrm{S}$ 는 $\\angle \\mathrm{B}$ 의 이등분선 위에 있다. $\\triangle \\mathrm{ABP}$ 와 $\\triangle \\mathrm{CBS}$ 에서 $\\angle \\mathrm{B}$ 의 이등분선과 이루는 각이 $30^{\\circ}$ 이므로 코사인으로 $\\overline{\\mathrm{BP}}$, $\\overline{\\mathrm{BS}}$ 를 구해 뺀다.","확인":null,"스킬":"S6","고비":false},{"제목":"직사각형의 넓이","힌트":"가로와 세로를 곱하면 얼마일까?","식":["$\\square \\mathrm{PQRS}=2\\times2\\sqrt{3}=4\\sqrt{3}$"],"설명":"직사각형의 가로와 세로가 $2$, $2\\sqrt{3}$ 이므로 넓이는 $4\\sqrt{3}$ 이다.","확인":null,"스킬":"S6","고비":false}],"fb":"fig/ns/"},"ns-a7c5d2f49f77":{"길":"근호 안의 수의 범위로 바꿔 개수를 센 뒤 유리수가 되는 카드를 뺀다","단계":[{"제목":"근호 안의 범위","힌트":"$7<\\sqrt{n}<9$ 의 양변을 제곱하면 $n$ 의 범위는 어떻게 될까?","식":["$49<n<81$","$n=50,\\,51,\\,\\cdots,\\,80$"],"설명":"카드에 적힌 수는 $\\sqrt{n}$ 이므로 $7<\\sqrt{n}<9$ 에서 $49<n<81$ 이다. 이 범위의 자연수 $n$ 은 $31$ 개이다.","확인":"31","스킬":"N8","고비":false},{"제목":"유리수 카드 빼기","힌트":"이 범위에서 $\\sqrt{n}$ 이 자연수가 되는 $n$ 은 무엇일까?","식":["$\\sqrt{64}=8$","$31-1=30$"],"설명":"$n=64$ 일 때 $\\sqrt{64}=8$ 은 유리수이므로 제외한다. 무리수가 적힌 카드는 $30$ 개이다.","확인":"30","스킬":"N8","고비":true}],"fb":"fig/ns/"},"ns-af3e2c8f09d0":{"길":"직각으로 한 원 위의 네 점을 찾고, 원주각이 같음으로 각을 옮겨 보기와 대조한다","단계":[{"제목":"원에 내접하는 사각형 찾기","힌트":"한 선분을 같은 쪽에서 직각으로 보는 두 점은 어떤 도형 위에 있을까?","식":["$\\angle \\mathrm{AFC}=\\angle \\mathrm{ADC}=90^{\\circ}$","$\\angle \\mathrm{BFC}=\\angle \\mathrm{BEC}=90^{\\circ}$","$\\angle \\mathrm{AEB}=\\angle \\mathrm{ADB}=90^{\\circ}$"],"설명":"$\\overline{\\mathrm{AC}}$, $\\overline{\\mathrm{BC}}$, $\\overline{\\mathrm{AB}}$ 를 각각 같은 쪽에서 직각으로 보므로 $\\square \\mathrm{AFDC}$, $\\square \\mathrm{BCEF}$, $\\square \\mathrm{ABDE}$ 는 각각 원에 내접한다.","확인":null,"스킬":"S15","고비":true},{"제목":"원주각으로 각 옮기기","힌트":"원에 내접하는 사각형에서 같은 호에 대한 원주각은 어떤 관계일까?","식":["$\\angle \\mathrm{BAD}=\\angle \\mathrm{FCB}$","$\\angle \\mathrm{ABE}=\\angle \\mathrm{ACF}$","$\\angle \\mathrm{CAD}=\\angle \\mathrm{CBE}$"],"설명":"$\\square \\mathrm{AFDC}$ 에서 호 $\\mathrm{FD}$ 에 대한 원주각이므로 $\\angle \\mathrm{BAD}=\\angle \\mathrm{FCB}$ 이다. $\\square \\mathrm{BCEF}$ 에서는 $\\angle \\mathrm{ABE}=\\angle \\mathrm{ACF}$, $\\square \\mathrm{ABDE}$ 에서는 $\\angle \\mathrm{CAD}=\\angle \\mathrm{CBE}$ 이다.","확인":null,"스킬":"S5","고비":false},{"제목":"보기와 대조","힌트":"구한 세 등식과 같은 꼴의 보기는 어느 것일까?","식":["$\\angle \\mathrm{CAD}=\\angle \\mathrm{CBE}$"],"설명":"④ 가 $\\angle \\mathrm{CAD}=\\angle \\mathrm{CBE}$ 와 같은 꼴이다. 나머지 보기는 위에서 구한 등식에 해당하지 않으므로 옳은 것은 ④ 이다.","확인":null,"스킬":"S5","고비":false}],"fb":"fig/ns/"},"ns-af918c182595":{"길":"직각으로 내접 조건을 보기마다 확인하고 남는 하나를 고른다","단계":[{"제목":"같은 변을 보는 각","힌트":"같은 쪽에서 한 변을 같은 크기의 각으로 보는 네 점은 어떤 관계일까?","식":["$\\angle \\mathrm{BFC}=\\angle \\mathrm{BEC}=90^{\\circ}$","$\\angle \\mathrm{ADB}=\\angle \\mathrm{AEB}=90^{\\circ}$"],"설명":"한 변을 같은 쪽에서 같은 크기의 각으로 보면 네 점이 한 원 위에 있다. 따라서 $\\square \\mathrm{BCEF}$ 와 $\\square \\mathrm{ABDE}$ 는 원에 내접한다.","확인":null,"스킬":"S15","고비":true},{"제목":"마주 보는 각의 합","힌트":"마주 보는 두 각의 합이 $180^{\\circ}$ 인 사각형은 어느 것일까?","식":["$\\angle \\mathrm{HDC}+\\angle \\mathrm{HEC}=180^{\\circ}$","$\\angle \\mathrm{AFH}+\\angle \\mathrm{AEH}=180^{\\circ}$"],"설명":"$\\square \\mathrm{HDCE}$ 와 $\\square \\mathrm{AFHE}$ 는 마주 보는 두 각이 모두 직각이어서 합이 $180^{\\circ}$ 이므로 원에 내접한다.","확인":null,"스킬":"S15","고비":false},{"제목":"남는 보기","힌트":"앞의 사각형 네 개를 제외하면 남는 보기는 무엇일까?","식":["$\\square \\mathrm{DEAF}$"],"설명":"나머지 네 사각형이 모두 원에 내접하므로 원에 내접하지 않는 것은 ③ $\\square \\mathrm{DEAF}$ 이다.","확인":null,"스킬":"S15","고비":false}],"fb":"fig/ns/"},"ns-b26ff8eb9062":{"길":"넓이에서 한 변을 근호로 구한 뒤, 붙은 변을 뺀 바깥 둘레를 변의 개수로 세어 더한다.","단계":[{"제목":"세 정사각형의 한 변","힌트":"넓이가 $54$, $24$, $6$인 정사각형의 한 변의 길이를 근호로 간단히 나타내면?","식":["$\\sqrt{54}=3\\sqrt{6}$","$\\sqrt{24}=2\\sqrt{6}$","$\\sqrt{6}$"],"설명":"정사각형의 한 변의 길이는 넓이의 양의 제곱근이다. 근호 안에서 제곱인 인수를 꺼내면 세 변 모두 $\\sqrt{6}$의 배수가 된다.","확인":null,"스킬":"N8"},{"제목":"둘레를 변의 개수로 세기","힌트":"붙어 있는 변은 둘레에서 빠진다. 남는 부분의 길이는 $\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$의 변 몇 개와 같은가?","식":["$4\\times 3\\sqrt{6}+2\\times 2\\sqrt{6}+2\\times\\sqrt{6}$"],"설명":"정사각형끼리 붙은 변은 도형의 바깥 둘레에 들어가지 않는다. 남는 부분의 길이를 모두 합하면 $\\mathrm{A}$의 변 $4$개, $\\mathrm{B}$의 변 $2$개, $\\mathrm{C}$의 변 $2$개의 길이의 합과 같다.","확인":null,"스킬":"S12","고비":true},{"제목":"둘레의 길이 계산","힌트":"근호 안이 같은 항끼리 계수를 더하면?","식":["$12\\sqrt{6}+4\\sqrt{6}+2\\sqrt{6}=18\\sqrt{6}$"],"설명":"근호 안의 수가 같으므로 계수끼리 더한다.","확인":null,"스킬":"N8"}],"fb":"fig/ns/"},"ns-b48d58d603c4":{"길":"세 정사각형의 한 변을 구한 뒤, 겹치는 정사각형 때문에 각 정사각형의 둘레에서 빠지는 길이를 구해 남는 둘레를 더한다.","단계":[{"제목":"세 정사각형의 한 변","힌트":"넓이가 $2$, $5$, $8$인 정사각형의 한 변의 길이는?","식":["$\\sqrt{2}$","$\\sqrt{5}$","$\\sqrt{8}=2\\sqrt{2}$"],"설명":"한 변의 길이는 넓이의 양의 제곱근이다.","확인":null,"스킬":"N8"},{"제목":"겹쳐서 빠지는 길이","힌트":"한 정사각형의 대각선의 교점에 다른 정사각형의 꼭짓점을 맞추면, 두 정사각형의 둘레에서 각각 얼마가 빠지는가?","식":["$\\sqrt{2}$","$\\sqrt{5}$"],"설명":"겹치는 부분은 정사각형이고, 그 변의 길이는 중심이 놓인 정사각형 한 변의 절반이다. 겹친 정사각형의 변 두 개씩이 양쪽 정사각형의 둘레에서 빠지므로, 각 정사각형에서 빠지는 길이는 중심이 놓인 쪽 정사각형의 한 변과 같다. 작은 정사각형과 가운데 정사각형의 겹침에서는 $\\sqrt{2}$, 가운데 정사각형과 큰 정사각형의 겹침에서는 $\\sqrt{5}$가 빠진다.","확인":null,"스킬":"S12","고비":true},{"제목":"정사각형마다 남는 둘레","힌트":"각 정사각형의 둘레에서 빠지는 길이를 빼면?","식":["$4\\sqrt{2}-\\sqrt{2}=3\\sqrt{2}$","$4\\sqrt{5}-\\sqrt{2}-\\sqrt{5}=3\\sqrt{5}-\\sqrt{2}$","$8\\sqrt{2}-\\sqrt{5}$"],"설명":"작은 정사각형은 한 번, 가운데 정사각형은 양쪽에서 두 번, 큰 정사각형은 한 번 빠진다.","확인":null,"스킬":"S12"},{"제목":"도형의 둘레","힌트":"세 값을 더하면?","식":["$3\\sqrt{2}+(3\\sqrt{5}-\\sqrt{2})+(8\\sqrt{2}-\\sqrt{5})=10\\sqrt{2}+2\\sqrt{5}$"],"설명":"근호 안의 수가 같은 항끼리 계수를 더한다.","확인":null,"스킬":"N8"}],"fb":"fig/ns/"},"ns-b96547613acd":{"길":"두 그래프가 평행이동 관계임을 보고, 색칠한 부분을 꼭짓점을 이은 직사각형으로 바꿔 넓이를 구한다.","단계":[{"제목":"두 꼭짓점의 좌표","힌트":"두 이차함수를 $y=a(x-p)^2+q$ 꼴로 바꾸면?","식":["$y=-(x-1)^2+3$","$y=-(x-4)^2+3$","$\\mathrm{A}(1,\\,3)$, $\\mathrm{B}(4,\\,3)$"],"설명":"완전제곱식으로 고치면 꼭짓점을 읽을 수 있다.","확인":null,"스킬":"A6"},{"제목":"두 그래프의 관계","힌트":"두 그래프는 서로 어떻게 포개어지는가?","식":["$4-1=3$"],"설명":"두 식의 $x^2$의 계수와 $q$가 같으므로 $y=-x^2+8x-13$의 그래프는 $y=-x^2+2x+2$의 그래프를 $x$축의 방향으로 $3$만큼 평행이동한 것이다. 점 $\\mathrm{A}$, $\\mathrm{B}$에서 $x$축에 내린 수선의 발을 각각 $\\mathrm{C}$, $\\mathrm{D}$라 하면, 옮겨 포개지는 부분 때문에 색칠한 부분의 넓이는 직사각형 $\\mathrm{ACDB}$의 넓이와 같다.","확인":null,"스킬":"G4","고비":true},{"제목":"직사각형의 넓이","힌트":"직사각형 $\\mathrm{ACDB}$의 가로와 세로의 길이는?","식":["$(4-1)\\times 3=9$"],"설명":"가로는 $\\overline{\\mathrm{AB}}=3$, 세로는 두 꼭짓점의 $y$좌표 $3$이다.","확인":"9","스킬":"G10"}],"fb":"fig/ns/"},"ns-c8e241a1fb14":{"길":"잘라낸 두 정사각형의 변으로 $\\overline{\\mathrm{AG}}$, $\\overline{\\mathrm{AE}}$를 $x$, $y$로 나타내고 곱해 넓이를 구한다.","단계":[{"제목":"선분 AG","힌트":"정사각형 $\\mathrm{GHCD}$의 한 변의 길이를 이용하면 $\\overline{\\mathrm{AG}}$는?","식":["$\\overline{\\mathrm{GD}}=\\overline{\\mathrm{DC}}=2y$","$\\overline{\\mathrm{AG}}=3x-2y$"],"설명":"$\\overline{\\mathrm{AD}}=3x$에서 $\\overline{\\mathrm{GD}}$를 뺀다.","확인":null,"스킬":"C7"},{"제목":"선분 AE","힌트":"$\\overline{\\mathrm{AE}}$는 $\\overline{\\mathrm{AB}}$에서 무엇을 빼야 하는가?","식":["$\\overline{\\mathrm{AE}}=2y-(3x-2y)=-3x+4y$"],"설명":"$\\overline{\\mathrm{EB}}$는 정사각형 $\\mathrm{EBHF}$의 한 변이므로 $\\overline{\\mathrm{BH}}=\\overline{\\mathrm{BC}}-\\overline{\\mathrm{HC}}=3x-2y$와 같다.","확인":null,"스킬":"C7","고비":true},{"제목":"사각형 AEFG 의 넓이","힌트":"가로와 세로의 곱을 전개하면?","식":["$(3x-2y)(-3x+4y)=-9x^2+18xy-8y^2$"],"설명":"사각형 $\\mathrm{AEFG}$는 직사각형이다.","확인":null,"스킬":"S12"},{"제목":"p, q, r 로 계산","힌트":"$p$, $q$, $r$의 값을 읽고 $p\\div q\\times r$를 계산하면?","식":["$p=-9,\\ q=18,\\ r=-8$","$(-9)\\div18\\times(-8)=4$"],"설명":"곱셈과 나눗셈은 앞에서부터 차례로 계산한다.","확인":"4","스킬":"S12"}],"fb":"fig/ns/"},"ns-cc3138a12252":{"길":"두 정사각형의 한 변이 자연수가 되는 조건으로 $n$을 찾고, 그림의 변 관계에서 직사각형의 가로와 세로를 구한다.","단계":[{"제목":"A 의 조건","힌트":"$\\sqrt{24n}$이 자연수가 되려면 $n$은 어떤 꼴이어야 하는가?","식":["$\\sqrt{24n}=\\sqrt{2^3\\times 3\\times n}$","$n=6k^2$"],"설명":"근호 안의 수가 자연수의 제곱이 되도록 소인수의 지수를 모두 짝수로 만든다. $2^3\\times 3$에 $2\\times 3$이 곱해져야 하므로 $n=6k^2$($k$는 자연수) 꼴이다.","확인":null,"스킬":"N8"},{"제목":"B 의 조건","힌트":"$28-2n$이 제곱수이고 $n$이 자연수인 경우는?","식":["$28-2n=1,\\ 4,\\ 9,\\ 16,\\ 25$","$n=12,\\ 6$"],"설명":"$28-2n>0$이고 제곱수이므로 $1$, $4$, $9$, $16$, $25$ 가운데 $n$이 자연수가 되는 것을 고른다.","확인":null,"스킬":"N8"},{"제목":"n 의 값","힌트":"두 조건을 모두 만족하는 $n$은?","식":["$n=6$"],"설명":"$n=12$는 $6k^2$ 꼴이 아니고 $n=6$은 $k=1$일 때이므로 조건을 만족한다.","확인":"6","스킬":"N8","고비":true},{"제목":"두 정사각형의 한 변","힌트":"$n=6$일 때 $\\mathrm{A}$, $\\mathrm{B}$의 한 변의 길이는?","식":["$\\sqrt{24\\times 6}=12$","$\\sqrt{28-12}=4$"],"설명":"각 넓이의 양의 제곱근이 한 변의 길이이다.","확인":null,"스킬":"N8"},{"제목":"직사각형 C 의 넓이","힌트":"$\\mathrm{C}$의 가로와 세로의 길이는 $\\mathrm{A}$, $\\mathrm{B}$의 변과 어떤 관계인가?","식":["$4\\times(12-4)=32$"],"설명":"$\\mathrm{C}$의 가로는 $\\mathrm{B}$의 한 변과 같고, 세로는 $\\mathrm{A}$의 한 변에서 $\\mathrm{B}$의 한 변을 뺀 길이이다.","확인":"32","스킬":"S12"}],"fb":"fig/ns/"},"ns-cc7b0661f6e3":{"길":"넓이의 비에서 닮음비를 구하고, 반으로 자른 변의 관계로 긴 변과 짧은 변을 같은 문자로 나타낸다.","단계":[{"제목":"닮음비","힌트":"$\\mathrm{A}4$와 $\\mathrm{A}5$의 넓이의 비는, 닮음비는?","식":["$2:1$","$\\sqrt{2}:1$"],"설명":"닮은 도형의 넓이의 비는 닮음비의 제곱이다.","확인":null,"스킬":"S1"},{"제목":"짧은 변의 길이","힌트":"$\\mathrm{A}5$의 짧은 변을 $a$라 하면 $\\mathrm{A}4$의 짧은 변은?","식":["$\\sqrt{2}a$"],"설명":"$\\mathrm{A}4$의 길이는 $\\mathrm{A}5$의 대응하는 길이의 닮음비 배이다.","확인":null,"스킬":"S1"},{"제목":"긴 변의 길이","힌트":"$\\mathrm{A}4$를 반으로 자르면 $\\mathrm{A}5$의 짧은 변은 $\\mathrm{A}4$의 어느 변의 절반인가?","식":["$2a$","$\\frac{2a}{\\sqrt{2}a}=\\sqrt{2}$"],"설명":"$\\mathrm{A}4$를 긴 변의 중점끼리 이은 선으로 자르면 $\\mathrm{A}5$의 짧은 변이 $\\mathrm{A}4$의 긴 변의 절반이 되므로 긴 변은 $2a$이다.","확인":null,"스킬":"S1","고비":true}],"fb":"fig/ns/"},"ns-cceda9ed8652":{"길":"점 B 의 $x$좌표를 $t$로 두고 나머지 꼭짓점의 좌표를 $t$로 나타낸 뒤, 정사각형의 변의 길이 조건으로 $t$를 구한다.","단계":[{"제목":"점 B 의 좌표","힌트":"점 B 의 $x$좌표를 $t$라 하면 B 의 좌표와 $\\overline{\\mathrm{EB}}$는?","식":["$\\mathrm{B}\\left(t,\\ \\frac{1}{2}t^2\\right)$","$\\overline{\\mathrm{EB}}=\\overline{\\mathrm{BC}}=t$"],"설명":"점 B 는 $y=\\frac{1}{2}x^2$ 위의 점이다. E 는 $y$축 위의 점이므로 $\\overline{\\mathrm{EB}}$는 점 B 의 $x$좌표와 같다.","확인":null,"스킬":"S4"},{"제목":"점 C, D 의 좌표","힌트":"$\\overline{\\mathrm{BC}}=t$를 이용해 C 와 D 의 좌표는?","식":["$\\mathrm{C}\\left(2t,\\ \\frac{1}{2}t^2\\right)$","$\\mathrm{D}\\left(2t,\\ 2t^2\\right)$"],"설명":"$\\overline{\\mathrm{BC}}$가 $x$축에 평행하므로 C 의 $y$좌표는 B 와 같다. D 는 C 의 바로 위에서 포물선 위에 있다.","확인":null,"스킬":"S4","고비":true},{"제목":"정사각형 조건","힌트":"$\\overline{\\mathrm{BC}}=\\overline{\\mathrm{DC}}$로 식을 세우면?","식":["$t=2t^2-\\frac{1}{2}t^2$","$t=\\frac{2}{3}$"],"설명":"$t\\ne 0$이므로 $\\frac{3}{2}t-1=0$에서 $t$를 구한다.","확인":"2/3","스킬":"S4"},{"제목":"정사각형의 넓이","힌트":"한 변의 길이를 제곱하면?","식":["$\\left(\\frac{2}{3}\\right)^2=\\frac{4}{9}$"],"설명":"정사각형의 한 변은 $t$이다.","확인":"4/9","스킬":"S12"}],"fb":"fig/ns/"},"ns-cf4d3189157a":{"길":"직선이 지나는 두 점으로 $a$, $b$를 구하고, 이차함수의 식을 세워 꼭짓점·축·볼록 방향을 확인한다.","단계":[{"제목":"a, b 의 값","힌트":"직선이 $x$축, $y$축과 만나는 점으로 $a$, $b$를 구하면?","식":["$b=3,\\ 3a+b=0$","$a=-1$"],"설명":"그림에서 직선은 $(0,\\,3)$, $(3,\\,0)$을 지난다.","확인":null,"스킬":"G9","고비":true},{"제목":"이차함수의 식","힌트":"$a$, $b$를 대입하면 이차함수의 식은?","식":["$y=-(x+3)^2-3$"],"설명":"$\\frac{b}{a}=-3$이므로 $y=a(x+b)^2+\\frac{b}{a}$에 대입한다.","확인":null,"스킬":"G4"},{"제목":"선지 확인","힌트":"식에서 $x=0$일 때의 값, 축, 볼록한 방향, 꼭짓점, 폭을 확인하면?","식":["$y(0)=-12$","$x=-3$","$(-3,\\,-3)$"],"설명":"$-1<0$이므로 위로 볼록하고, $|-1|>\\frac{1}{2}$이므로 $y=\\frac{1}{2}x^2$보다 폭이 좁다. 따라서 ④만 옳다.","확인":null,"스킬":"G4"}],"fb":"fig/ns/"},"ns-cfd7359eccc0":{"길":"수선의 발이 만드는 직각과 대각의 합 $180^\\circ$로 한 원 위의 네 점을 찾아 선지마다 확인한다.","단계":[{"제목":"직각이 같은 점","힌트":"$\\angle\\mathrm{BFC}$와 $\\angle\\mathrm{BEC}$는 각각 몇 도이고, 네 점 B, C, E, F 는 어떤 관계인가?","식":["$\\angle\\mathrm{BFC}=\\angle\\mathrm{BEC}=90^\\circ$","$\\angle\\mathrm{ABE}=\\angle\\mathrm{ACF}$"],"설명":"$\\mathrm{BC}$에 대하여 같은 쪽의 두 점 $\\mathrm{E}$, $\\mathrm{F}$에서 본 각이 $90^\\circ$로 같으므로 네 점은 한 원 위에 있다. $\\angle\\mathrm{ABE}$와 $\\angle\\mathrm{ACF}$는 $\\overset{\\frown}{\\mathrm{EF}}$의 원주각이므로 같고, ①은 옳다.","확인":null,"스킬":"S15"},{"제목":"대각의 합이 180°인 사각형","힌트":"$\\mathrm{FBDH}$, $\\mathrm{DCEH}$에서 마주 보는 두 각의 합은?","식":["$\\angle\\mathrm{BFH}+\\angle\\mathrm{BDH}=180^\\circ$","$\\angle\\mathrm{HDC}+\\angle\\mathrm{HEC}=180^\\circ$"],"설명":"두 사각형은 대각의 합이 $180^\\circ$이므로 원에 내접한다. $\\mathrm{FBDH}$에서는 할선의 성질로 $\\overline{\\mathrm{AF}}\\times\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AH}}\\times\\overline{\\mathrm{AD}}$이므로 ③은 옳다.","확인":null,"스킬":"S15","고비":true},{"제목":"④ 의 원주각","힌트":"$\\mathrm{DCEH}$가 원에 내접할 때 $\\angle\\mathrm{DCH}$는 어느 호의 원주각인가?","식":["$\\angle\\mathrm{DCH}$는 $\\overset{\\frown}{\\mathrm{DH}}$의 원주각"],"설명":"$\\angle\\mathrm{DCH}$는 $\\overset{\\frown}{\\mathrm{DE}}$가 아니라 $\\overset{\\frown}{\\mathrm{DH}}$의 원주각이므로 ④는 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"② 의 각","힌트":"직각삼각형 $\\mathrm{ABE}$, $\\mathrm{ABD}$에서 $\\angle\\mathrm{ABE}$, $\\angle\\mathrm{BAD}$를 $\\angle\\mathrm{A}$, $\\angle\\mathrm{B}$로 나타내면?","식":["$\\angle\\mathrm{ABE}=90^\\circ-\\angle\\mathrm{A}$","$\\angle\\mathrm{BAD}=90^\\circ-\\angle\\mathrm{B}$"],"설명":"두 각은 $\\angle\\mathrm{A}=\\angle\\mathrm{B}$일 때만 같으므로 항상 같다고 할 수 없다. 따라서 ②는 옳지 않다.","확인":null,"스킬":"S10"},{"제목":"한 원 위의 네 점의 개수","힌트":"대각의 합이 $180^\\circ$인 경우와 한 변에 대하여 같은 쪽의 두 각이 $90^\\circ$로 같은 경우는 각각 몇 가지인가?","식":["$3+3=6$"],"설명":"대각의 합이 $180^\\circ$인 경우는 $\\square\\mathrm{AFHE}$, $\\square\\mathrm{BDHF}$, $\\square\\mathrm{DCEH}$, 같은 쪽의 두 각이 $90^\\circ$로 같은 경우는 $\\square\\mathrm{BCEF}$, $\\square\\mathrm{DCAF}$, $\\square\\mathrm{BDEA}$이다. ⑤는 옳다.","확인":null,"스킬":"S15"}],"fb":"fig/ns/"},"ns-d028edae9baa":{"길":"$x$축 대칭으로 $d=-a$, $c=-b$를 세우고, 그래프의 폭으로 크기를 비교해 보기를 하나씩 확인한다.","단계":[{"제목":"대칭 관계","힌트":"$x$축에 대하여 대칭인 두 이차함수의 계수 사이의 관계는?","식":["$d=-a$","$c=-b$"],"설명":"$x$축에 대하여 대칭이면 $y$를 $-y$로 바꾼 식이므로 계수의 부호만 다르다.","확인":null,"스킬":"G4"},{"제목":"부호와 크기","힌트":"그림에서 $a$, $b$, $c$, $d$의 부호와 절댓값의 크기는?","식":["$a>b>0$","$0>c>d$"],"설명":"위로 볼록하면 계수가 음수이고, 폭이 좁을수록 절댓값이 크다. $y=ax^2$의 폭이 가장 좁으므로 $|a|>|b|$이고, $c=-b$, $d=-a$이다.","확인":null,"스킬":"G4","고비":true},{"제목":"보기 확인","힌트":"ㄱ부터 ㅁ까지 하나씩 확인하면?","식":["$d<c$","$abcd=a^2b^2>0$","$a+b+c+d=0$"],"설명":"ㄷ은 $|a|>|c|$이므로 옳지 않다. ㅁ은 $d-b<0$이므로 $\\sqrt{(d-b)^2}=-(d-b)$가 되어 옳지 않다. 따라서 ㄱ, ㄴ, ㄹ이 옳다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-d09b77a84b13":{"길":"접선과 현이 이루는 각으로 닮음을 찾고, 닮음비·접선과 할선의 관계·각의 이등분선의 성질로 길이를 구해 선지를 판별한다.","단계":[{"제목":"닮은 삼각형","힌트":"$\\triangle\\mathrm{PCB}$와 $\\triangle\\mathrm{PDT}$에서 같은 각은?","식":["$\\angle\\mathrm{BPC}=\\angle\\mathrm{TPD}$","$\\angle\\mathrm{PBC}=\\angle\\mathrm{PTD}$","$\\triangle\\mathrm{PCB}\\backsim\\triangle\\mathrm{PDT}$"],"설명":"$\\overline{\\mathrm{PC}}$는 $\\angle\\mathrm{BPT}$의 이등분선이다. 접선과 현이 이루는 각은 그 호의 원주각과 같으므로 $\\angle\\mathrm{PBC}=\\angle\\mathrm{PTD}$이고 $AA$ 닮음이다. ①은 옳다.","확인":null,"스킬":"S1"},{"제목":"선분 PT","힌트":"닮음비로 $\\overline{\\mathrm{PT}}$를 구하면?","식":["$24:\\overline{\\mathrm{PT}}=18:12$","$\\overline{\\mathrm{PT}}=16$"],"설명":"$\\overline{\\mathrm{PC}}=\\overline{\\mathrm{PD}}+\\overline{\\mathrm{DC}}=18$이다. 대응변 $\\overline{\\mathrm{PB}}$와 $\\overline{\\mathrm{PT}}$, $\\overline{\\mathrm{PC}}$와 $\\overline{\\mathrm{PD}}$의 비가 같다.","확인":"16","스킬":"S1","고비":true},{"제목":"선분 PA","힌트":"원 밖의 한 점에서 접선과 할선을 그었을 때의 관계로 $\\overline{\\mathrm{PA}}$는?","식":["$\\overline{\\mathrm{PT}}^{\\,2}=\\overline{\\mathrm{PA}}\\times\\overline{\\mathrm{PB}}$","$\\overline{\\mathrm{PA}}=\\frac{32}{3}$"],"설명":"접선의 길이의 제곱은 할선의 두 길이의 곱과 같다.","확인":null,"스킬":"S5"},{"제목":"AD : DT","힌트":"삼각형 $\\mathrm{PAT}$에서 $\\overline{\\mathrm{PD}}$가 $\\angle\\mathrm{P}$의 이등분선임을 쓰면?","식":["$\\overline{\\mathrm{AD}}:\\overline{\\mathrm{DT}}=\\overline{\\mathrm{PA}}:\\overline{\\mathrm{PT}}=\\frac{32}{3}:16=2:3$"],"설명":"각의 이등분선은 대변을 두 변의 길이의 비로 나눈다. ③은 옳다.","확인":null,"스킬":"S1"},{"제목":"나머지 선지","힌트":"$\\angle\\mathrm{BPC}=\\angle\\mathrm{TPD}=a$, $\\angle\\mathrm{PBC}=\\angle\\mathrm{PTD}=b$라 할 때 $\\angle\\mathrm{PCT}$, $\\angle\\mathrm{CDT}$는?","식":["$\\angle\\mathrm{PCT}=a+b$","$\\angle\\mathrm{CDT}=a+b$"],"설명":"삼각형 $\\mathrm{PBC}$와 $\\mathrm{PDT}$의 외각의 성질로 두 각이 같으므로 $\\overline{\\mathrm{CT}}=\\overline{\\mathrm{DT}}$이다. ④는 옳다. 또 $\\angle\\mathrm{BAT}=2a+b$이고 $\\angle\\mathrm{ABT}=b$이므로 $\\triangle\\mathrm{TAB}$는 이등변삼각형이 아니어서 이등변삼각형 $\\mathrm{TCD}$와 닮음이 아니다. ②는 옳지 않다. ⑤는 주어진 조건으로 알 수 없다.","확인":null,"스킬":"S10"}],"fb":"fig/ns/"},"ns-d0a210bcc0da":{"길":"밑면의 대각선 $\\overline{\\mathrm{FH}}$를 구하고, 직각삼각형 $\\mathrm{DFH}$에서 $\\overline{\\mathrm{DF}}$와 삼각비를 구해 선지를 확인한다.","단계":[{"제목":"밑면의 대각선","힌트":"밑면 $\\mathrm{EFGH}$의 대각선 $\\overline{\\mathrm{FH}}$의 길이는?","식":["$\\overline{\\mathrm{FH}}=\\sqrt{(\\sqrt{5})^2+(2\\sqrt{5})^2}=5$"],"설명":"밑면은 가로 $2\\sqrt{5}$, 세로 $\\sqrt{5}$인 직사각형이다.","확인":null,"스킬":"S3"},{"제목":"직육면체의 대각선","힌트":"직각삼각형 $\\mathrm{DFH}$에서 $\\overline{\\mathrm{DF}}$는?","식":["$\\overline{\\mathrm{DF}}=\\sqrt{5^2+(\\sqrt{11})^2}=6$"],"설명":"$\\overline{\\mathrm{DH}}$는 모서리이므로 $\\sqrt{11}$이고 $\\angle\\mathrm{DHF}=90^\\circ$이다.","확인":null,"스킬":"S3","고비":true},{"제목":"삼각비","힌트":"각 $x$의 사인, 코사인, 탄젠트는?","식":["$\\sin x=\\frac{\\sqrt{11}}{6}$","$\\cos x=\\frac{5}{6}$","$\\tan x=\\frac{\\sqrt{11}}{5}$"],"설명":"$\\angle x$에서 밑변은 $\\overline{\\mathrm{FH}}$, 높이는 $\\overline{\\mathrm{DH}}$, 빗변은 $\\overline{\\mathrm{DF}}$이다. 따라서 ④만 옳다.","확인":"5/6","스킬":"S6"}],"fb":"fig/ns/"},"ns-dc7837662649":{"길":"점 A 에서 각 원에 그은 접선의 길이를 $x$로 두고, 접선의 길이가 같다는 성질로 변을 따라 차례로 구하면 $x$가 약분된다.","단계":[{"제목":"접선의 길이를 x 로","힌트":"점 A 에서 각 원에 그은 접선의 길이는 어떤 관계인가?","식":["$\\overline{\\mathrm{AG}}=\\overline{\\mathrm{AI}}=\\overline{\\mathrm{AK}}=\\overline{\\mathrm{AM}}=\\overline{\\mathrm{AO}}=x$"],"설명":"각 원이 변에 접하는 점을 그림과 같이 $\\mathrm{G}$, $\\mathrm{H}$, $\\mathrm{I}$, $\\mathrm{J}$, $\\mathrm{K}$, $\\mathrm{L}$, $\\mathrm{M}$, $\\mathrm{N}$, $\\mathrm{O}$라 하자. 이웃한 두 원은 공통 변 위의 같은 점($\\mathrm{I}$, $\\mathrm{K}$, $\\mathrm{M}$)에서 접하므로 점 A 에서 각 원에 그은 접선의 길이가 모두 같다.","확인":null,"스킬":"S5"},{"제목":"B, C 쪽의 접선","힌트":"$\\overline{\\mathrm{AB}}=16$, $\\overline{\\mathrm{BC}}=12$에서 $\\overline{\\mathrm{BG}}$, $\\overline{\\mathrm{CH}}$를 $x$로 나타내면?","식":["$\\overline{\\mathrm{BG}}=\\overline{\\mathrm{BH}}=16-x$","$\\overline{\\mathrm{CH}}=\\overline{\\mathrm{CI}}=\\overline{\\mathrm{CJ}}=12-(16-x)=x-4$"],"설명":"한 점에서 한 원에 그은 두 접선의 길이는 같다. 점 C 에서는 두 원에 그은 접선의 길이도 서로 같다.","확인":null,"스킬":"S5","고비":true},{"제목":"D 쪽의 접선","힌트":"$\\overline{\\mathrm{CD}}=9$를 이용해 $\\overline{\\mathrm{DJ}}$를 구하면?","식":["$\\overline{\\mathrm{DJ}}=\\overline{\\mathrm{DK}}=\\overline{\\mathrm{DL}}=9-(x-4)=13-x$"],"설명":"같은 방법으로 변 $\\mathrm{CD}$ 위의 접점 $\\mathrm{J}$에서 점 D 까지의 길이를 구한다.","확인":null,"스킬":"S5"},{"제목":"E, F 쪽의 접선","힌트":"$\\overline{\\mathrm{DE}}=6$, $\\overline{\\mathrm{EF}}=3$을 이용해 $\\overline{\\mathrm{EL}}$, $\\overline{\\mathrm{FN}}$을 구하면?","식":["$\\overline{\\mathrm{EL}}=\\overline{\\mathrm{EM}}=\\overline{\\mathrm{EN}}=6-(13-x)=x-7$","$\\overline{\\mathrm{FN}}=\\overline{\\mathrm{FO}}=3-(x-7)=10-x$"],"설명":"앞 단계와 같은 방법을 변 $\\mathrm{DE}$, $\\mathrm{EF}$에 되풀이한다.","확인":null,"스킬":"S5"},{"제목":"AF 의 길이","힌트":"$\\overline{\\mathrm{AF}}$를 $\\overline{\\mathrm{AO}}$와 $\\overline{\\mathrm{FO}}$로 나누어 더하면?","식":["$\\overline{\\mathrm{AF}}=\\overline{\\mathrm{AO}}+\\overline{\\mathrm{FO}}=x+(10-x)=10$"],"설명":"점 O 는 $\\overline{\\mathrm{AF}}$ 위의 접점이다. $x$는 약분되어 사라진다.","확인":"10","스킬":"S5"}],"fb":"fig/ns/"},"ns-e18edbfe9354":{"길":"정사각형의 한 변을 직사각형의 가로·세로에서 각각 빼서 색칠한 직사각형의 두 변을 구한다.","단계":[{"제목":"정사각형의 한 변","힌트":"넓이가 $2$ 인 정사각형의 한 변의 길이는?","식":["$\\overline{\\mathrm{ID}}=\\overline{\\mathrm{DG}}=\\sqrt{2}$"],"설명":"정사각형 $\\mathrm{IFGD}$ 의 넓이가 $2\\,\\mathrm{cm^2}$ 이므로 한 변의 길이는 $\\sqrt{2}\\,\\mathrm{cm}$ 이다.","확인":null,"스킬":"S12"},{"제목":"색칠한 직사각형의 두 변","힌트":"가로 $\\sqrt{7}$ 과 세로 $3\\sqrt{2}$ 에서 각각 무엇을 빼야 $\\overline{\\mathrm{EF}}$, $\\overline{\\mathrm{FH}}$ 가 되는가?","식":["$\\overline{\\mathrm{EF}}=\\sqrt{7}-\\sqrt{2}$","$\\overline{\\mathrm{FH}}=3\\sqrt{2}-\\sqrt{2}=2\\sqrt{2}$"],"설명":"$\\overline{\\mathrm{EF}}=\\overline{\\mathrm{AI}}=\\overline{\\mathrm{AD}}-\\overline{\\mathrm{ID}}$ 이고, $\\overline{\\mathrm{FH}}=\\overline{\\mathrm{GC}}=\\overline{\\mathrm{DC}}-\\overline{\\mathrm{DG}}$ 이다.","확인":null,"스킬":"S12","고비":true},{"제목":"직사각형의 넓이","힌트":"두 변의 곱을 분배법칙으로 전개하면?","식":["$\\square\\mathrm{EBHF}=2\\sqrt{2}(\\sqrt{7}-\\sqrt{2})=2\\sqrt{14}-4$"],"설명":"세로 $2\\sqrt{2}$ 에 가로 $\\sqrt{7}-\\sqrt{2}$ 를 곱하면 $2\\sqrt{14}-4\\,(\\mathrm{cm^2})$ 이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-e2695c673d51":{"길":"중심에서 같은 거리에 있는 현의 길이가 같다는 성질로 정삼각형을 확인하고, 삼각비로 반지름을 구한다.","단계":[{"제목":"삼각형의 종류","힌트":"원의 중심에서 세 현까지의 거리가 같으면 세 현의 길이는 어떤 관계인가?","식":["$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{BC}}=\\overline{\\mathrm{CA}}=6$"],"설명":"원의 중심에서 같은 거리에 있는 현의 길이는 같다. 따라서 $\\triangle\\mathrm{ABC}$ 는 한 변이 $6\\,\\mathrm{cm}$ 인 정삼각형이다.","확인":null,"스킬":"S5"},{"제목":"반지름 구하기","힌트":"$\\angle\\mathrm{OBE}$ 의 크기와 $\\overline{\\mathrm{BE}}$ 의 길이를 알면 $\\overline{\\mathrm{OB}}$ 는 어떤 삼각비로 구하는가?","식":["$\\angle\\mathrm{OBE}=30^\\circ,\\ \\overline{\\mathrm{BE}}=3$","$\\overline{\\mathrm{OB}}=\\dfrac{3}{\\cos30^\\circ}=2\\sqrt{3}$"],"설명":"$\\triangle\\mathrm{OBD}\\equiv\\triangle\\mathrm{OBE}$ ($\\mathrm{RHS}$ 합동)이므로 $\\overline{\\mathrm{OB}}$ 는 $\\angle\\mathrm{B}$ 를 이등분하여 $\\angle\\mathrm{OBE}=30^\\circ$ 이다. 또 중심에서 현에 내린 수선은 그 현을 이등분하므로 $\\overline{\\mathrm{BE}}=3$ 이다.","확인":null,"스킬":"S6","고비":true},{"제목":"원의 넓이","힌트":"반지름이 정해졌을 때 원의 넓이는?","식":["$\\pi\\times(2\\sqrt{3})^2=12\\pi$"],"설명":"$\\overline{\\mathrm{OB}}$ 가 원 $\\mathrm{O}$ 의 반지름이므로 넓이는 $12\\pi\\,\\mathrm{cm^2}$ 이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-e413ad1e5dfe":{"길":"가려진 두 도수를 문자로 두고 인원수와 평균으로 두 식을 세워 구한 뒤 보기를 하나씩 확인한다.","단계":[{"제목":"도수의 합","힌트":"학생 수가 $32$ 명이라는 조건으로 충치가 $3$개, $5$개인 학생 수 $a$, $b$ 에 대한 식을 세우면?","식":["$2+7+4+a+3+b+3+1=32$","$a+b=12$"],"설명":"충치가 $3$개인 학생을 $a$명, $5$개인 학생을 $b$명이라 하고, 그래프에 보이는 도수와 함께 더해 전체 $32$명과 같게 놓는다.","확인":null,"스킬":"C7"},{"제목":"총합으로 두 번째 식","힌트":"평균이 $3.25$개이면 충치 개수의 총합은 얼마이고, 이를 (개수)$\\times$(도수)의 합으로 쓰면?","식":["$3.25\\times32=104$","$0\\times2+1\\times7+2\\times4+3a+4\\times3+5b+6\\times3+7\\times1=104$","$3a+5b=52$"],"설명":"평균에 학생 수를 곱하면 충치 개수의 총합이다. 개수와 도수를 곱한 값의 합이 $104$ 와 같다.","확인":null,"스킬":"C7","고비":true},{"제목":"연립방정식","힌트":"두 식에서 $a$ 를 없애면 $b$ 는 얼마인가?","식":["$a=4,\\ b=8$"],"설명":"$a+b=12$ 와 $3a+5b=52$ 를 연립하여 풀면 충치가 $3$개인 학생은 $4$명, $5$개인 학생은 $8$명이다.","확인":null,"스킬":"A10"},{"제목":"보기 확인","힌트":"도수가 가장 큰 변량은 무엇이고, 학생 $32$명의 중앙값은 몇 번째 값으로 정해지는가?","식":["$(\\text{중앙값})=\\dfrac{3+3}{2}=3$","$(\\text{최빈값})=5$"],"설명":"충치가 $0$, $1$, $2$개인 학생이 $13$명이므로 $14$번째부터 $17$번째 학생은 $3$개이고, $16$번째와 $17$번째 값이 모두 $3$개이다. 최빈값은 도수가 $8$명으로 가장 큰 $5$개이므로 ⑤ 가 옳지 않다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-e55efbe91ac7":{"길":"모든 길이를 $n$ 의 식으로 나타낸 뒤 보기마다 식으로 확인한다.","단계":[{"제목":"BD 의 길이","힌트":"$\\overline{\\mathrm{AC}}$ 를 $n$ 으로 나타내면 $\\overline{\\mathrm{AD}}$ 와 $\\overline{\\mathrm{BD}}$ 는?","식":["$\\overline{\\mathrm{AC}}=2n+1,\\ \\overline{\\mathrm{AD}}=\\dfrac{2n+1}{2}$","$\\overline{\\mathrm{BD}}=\\overline{\\mathrm{AB}}-\\overline{\\mathrm{AD}}=\\dfrac{1}{2}$"],"설명":"그림에서 $\\overline{\\mathrm{AB}}=n+1$, $\\overline{\\mathrm{BC}}=n$ 이고 $\\mathrm{D}$ 는 $\\overline{\\mathrm{AC}}$ 의 중점이다. 따라서 ㄱ 은 옳다.","확인":null,"스킬":"C3","고비":true},{"제목":"S₂ − S₁","힌트":"$(n+1)^2-n^2$ 을 전개하면 어떤 식이 되는가?","식":["$S_2-S_1=(n+1)^2-n^2=2n+1$"],"설명":"$2n+1$ 은 홀수이므로 ㄴ 은 틀리다. 또 $2n+1=n+(n+1)$ 이므로 ㄷ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"S₃ − S₄","힌트":"$S_3=\\left(\\dfrac{2n+1}{2}\\right)^2$, $S_4=\\left(\\dfrac{1}{2}\\right)^2$ 을 이용해 $S_3-S_4$ 를 구하면?","식":["$S_3-S_4=\\left(\\dfrac{2n+1}{2}\\right)^2-\\left(\\dfrac{1}{2}\\right)^2=n^2+n=n(n+1)$"],"설명":"$S_3-S_4$ 는 두 자연수 $n$, $n+1$ 의 곱과 같아 ㄹ 은 옳다. 따라서 옳은 것은 ㄱ, ㄷ, ㄹ 이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-e579d96c4e20":{"길":"$\\overline{\\mathrm{AD}}$ 와 색칠한 부분의 넓이를 $r$, $a$ 의 식으로 쓰고 곱셈공식으로 묶어 푼다.","단계":[{"제목":"AD 의 길이","힌트":"$\\overline{\\mathrm{AC}}=2r$ 라 할 때 $\\overline{\\mathrm{AD}}$ 를 $r$, $a$ 로 나타내고 둘레의 길이 조건에 넣으면?","식":["$\\overline{\\mathrm{AD}}=2r+a$","$(2r+a)\\pi=8\\pi$","$2r+a=8$"],"설명":"점 $\\mathrm{D}$ 는 $\\overline{\\mathrm{BC}}$ 의 중점이므로 $\\overline{\\mathrm{CD}}=\\overline{\\mathrm{DB}}=a$ 이다. 원의 둘레는 (지름)$\\times\\pi$ 이다.","확인":null,"스킬":"S12"},{"제목":"색칠한 부분의 넓이","힌트":"$\\overline{\\mathrm{AB}}$ 를 지름으로 하는 큰 원에서 $\\overline{\\mathrm{AC}}$ 를 지름으로 하는 원을 뺀 넓이를 식으로 쓰면?","식":["$\\overline{\\mathrm{AB}}=2r+2a$","$(r+a)^2\\pi-r^2\\pi=28\\pi$","$\\pi(2r+a)a=28\\pi$"],"설명":"큰 원의 반지름은 $r+a$ 이다. $(r+a)^2-r^2=a(2r+a)$ 로 묶을 수 있다.","확인":null,"스킬":"S12","고비":true},{"제목":"a 의 값","힌트":"$2r+a$ 의 값을 대입하면 $a$ 는?","식":["$8a=28$","$a=3.5$"],"설명":"$2r+a=8$ 을 대입하면 $8a=28$ 이므로 $a=3.5$ 이다.","확인":"3.5","스킬":"S12"}],"fb":"fig/ns/"},"ns-e7525fabf949":{"길":"삼각형의 넓이를 두 가지 꼴로 나타낸 뒤 보기를 하나씩 확인한다.","단계":[{"제목":"넓이를 두 꼴로","힌트":"두 변과 그 끼인각의 사인으로 삼각형의 넓이를 나타내는 식은?","식":["$\\triangle\\mathrm{ABC}=\\dfrac{1}{2}bc\\sin A=\\dfrac{1}{2}ca\\sin B=\\dfrac{1}{2}ab\\sin C$"],"설명":"예각삼각형에서 두 변과 끼인각으로 넓이를 구하는 식은 세 가지로 쓸 수 있고 모두 같다.","확인":null,"스킬":"S8","고비":true},{"제목":"② 확인","힌트":"$\\sin A>\\sin C$ 일 때 $bc\\sin A=ab\\sin C$ 에서 $a$ 와 $c$ 의 크기는?","식":["$bc=ab\\cdot\\dfrac{\\sin C}{\\sin A}<ab$","$c<a$"],"설명":"$bc\\sin A=ab\\sin C$ 에서 $bc=ab\\cdot\\dfrac{\\sin C}{\\sin A}$ 이고 $\\sin A>\\sin C$ 이므로 $bc<ab$, 즉 $c<a$ 이다. 따라서 ② 가 옳다.","확인":null,"스킬":"S6"},{"제목":"나머지 보기","힌트":"①, ③, ④, ⑤ 는 각각 어떤 이유로 틀리는가?","식":["$\\triangle\\mathrm{ABC}=\\dfrac{1}{2}bc\\sin A=\\dfrac{1}{4}bc\\ \\left(\\sin A=\\dfrac{1}{2}\\right)$","$45^\\circ\\le A<90^\\circ\\ \\Rightarrow\\ \\tan A\\ge1$"],"설명":"① 은 $\\angle C=90^\\circ$ 일 때만 성립한다. ③ 은 $bc\\sin A=ca\\sin B=ab\\sin C$ 여야 한다. ④ 는 넓이가 $\\dfrac{1}{4}bc$ 이고, ⑤ 는 $\\angle A$ 가 $45^\\circ$ 이상이면 $\\tan A\\ge1$ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-edfebcdf35aa":{"길":"근호 안이 제곱이므로 각 항의 부호를 먼저 정하고, 삼각비를 변의 비로 바꾸어 더한다.","단계":[{"제목":"삼각비를 변으로","힌트":"$\\angle\\mathrm{C}=90^\\circ$ 인 직각삼각형에서 $\\sin A$, $\\cos A$, $\\sin B$, $\\cos B$ 를 $a$, $b$, $c$ 로 나타내면?","식":["$\\sin A=\\dfrac{a}{c},\\ \\cos A=\\dfrac{b}{c}$","$\\sin B=\\dfrac{b}{c},\\ \\cos B=\\dfrac{a}{c}$","$\\sin C=1,\\ \\cos C=0$"],"설명":"각 삼각비를 (대변)과 (빗변)의 비, (밑변)과 (빗변)의 비로 쓴다.","확인":null,"스킬":"S6"},{"제목":"각 항의 부호","힌트":"$\\angle A>\\angle B$ 이면 $a$ 와 $b$ 중 어느 쪽이 큰가? 그러면 $\\sin B-\\cos B$ 의 부호는?","식":["$a>b$","$\\sin B-\\cos B=\\dfrac{b-a}{c}<0$"],"설명":"큰 각의 대변이 더 길어서 $a>b$ 이다. $\\sin A+\\cos A>0$ 이고 $\\sin C-\\cos C=1>0$ 이다.","확인":null,"스킬":"N5","고비":true},{"제목":"근호를 풀어 합하기","힌트":"$A\\ge0$ 이면 $\\sqrt{A^2}=A$, $A<0$ 이면 $\\sqrt{A^2}=-A$ 임을 적용해 세 항을 더하면?","식":["$\\dfrac{a+b}{c}+\\left(-\\dfrac{b}{c}+\\dfrac{a}{c}\\right)+1=\\dfrac{2a+c}{c}$"],"설명":"두 번째 항은 부호가 음수이므로 $-(\\sin B-\\cos B)$ 로 근호를 푼다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-efc7361fea67":{"길":"$\\angle\\mathrm{A}$ 의 이등분선을 그어 $a^\\circ$ 를 한 각으로 갖는 직각삼각형을 만들고, 각의 이등분선의 성질로 길이를 구한다.","단계":[{"제목":"BC 의 길이","힌트":"직각삼각형 $\\mathrm{ABC}$ 에서 $\\overline{\\mathrm{BC}}$ 를 피타고라스 정리로 구하면?","식":["$\\overline{\\mathrm{BC}}=\\sqrt{10^2-6^2}=8$"],"설명":"$\\angle\\mathrm{C}=90^\\circ$ 이므로 빗변 $\\overline{\\mathrm{AB}}=10$ 과 $\\overline{\\mathrm{AC}}=6$ 으로 구한다.","확인":null,"스킬":"S3"},{"제목":"보조선 긋기","힌트":"$2a^\\circ$ 를 반으로 나누어 $a^\\circ$ 를 한 각으로 갖는 직각삼각형을 만들려면 어떤 선을 그어야 하는가?","식":["$\\angle\\mathrm{BAD}=\\angle\\mathrm{CAD}=a^\\circ$"],"설명":"$\\angle\\mathrm{A}$ 의 이등분선이 $\\overline{\\mathrm{BC}}$ 와 만나는 점을 $\\mathrm{D}$ 라 하면 $\\angle\\mathrm{CAD}=a^\\circ$ 이고 $\\triangle\\mathrm{ACD}$ 는 직각삼각형이다. $\\cos a^\\circ=\\dfrac{\\overline{\\mathrm{AC}}}{\\overline{\\mathrm{AD}}}$ 이므로 $\\overline{\\mathrm{AD}}$ 가 필요하다.","확인":null,"스킬":"S2","고비":true},{"제목":"CD 의 길이","힌트":"삼각형의 한 각의 이등분선은 대변을 어떤 비로 나누는가? 그 비로 $\\overline{\\mathrm{CD}}$ 를 구하면?","식":["$\\overline{\\mathrm{BD}}:\\overline{\\mathrm{CD}}=\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}=10:6=5:3$","$\\overline{\\mathrm{CD}}=8\\times\\dfrac{3}{5+3}=3$"],"설명":"각의 이등분선은 대변을 이웃한 두 변의 길이의 비로 나눈다.","확인":null,"스킬":"S2"},{"제목":"코사인의 값","힌트":"직각삼각형 $\\mathrm{ACD}$ 에서 $\\overline{\\mathrm{AD}}$ 를 구한 뒤 $\\cos a^\\circ$ 를 구하면?","식":["$\\overline{\\mathrm{AD}}=\\sqrt{6^2+3^2}=3\\sqrt{5}$","$\\cos a^\\circ=\\dfrac{6}{3\\sqrt{5}}=\\dfrac{2\\sqrt{5}}{5}$"],"설명":"분모에 근호가 남지 않도록 분모를 유리화한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-f25f3e763aec":{"길":"잔디밭의 반지름을 문자로 두고 넓이의 차를 곱셈공식으로 묶어 $l$ 로 바꾼다.","단계":[{"제목":"한가운데 원의 둘레","힌트":"잔디밭의 반지름을 $r$ 로 두면 폭이 $4$ 인 산책로의 한가운데 원의 반지름은?","식":["$l=2\\pi(r+2)$"],"설명":"산책로의 한가운데는 잔디밭 가장자리에서 폭의 절반인 $2$ 만큼 떨어져 있어 반지름이 $r+2$ 이다.","확인":null,"스킬":"C7"},{"제목":"산책로의 넓이","힌트":"바깥 원의 넓이에서 잔디밭의 넓이를 빼고 $A^2-B^2=(A+B)(A-B)$ 로 묶으면?","식":["$\\pi\\{(r+4)^2-r^2\\}=\\pi(r+4+r)(r+4-r)$","$=4\\pi(2r+4)=8\\pi(r+2)$"],"설명":"바깥 원의 반지름은 $r+4$ 이다. 곱셈공식으로 묶으면 $8\\pi(r+2)$ 가 된다.","확인":null,"스킬":"S12","고비":true},{"제목":"l 로 나타내기","힌트":"$8\\pi(r+2)$ 에서 $2\\pi(r+2)$ 를 묶어 내면?","식":["$8\\pi(r+2)=4\\times2\\pi(r+2)=4l$"],"설명":"$2\\pi(r+2)=l$ 이므로 산책로의 넓이는 $4l$ 이다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-f84e7134007b":{"길":"상판의 가운데를 원점으로 하는 좌표평면에 케이블의 포물선을 놓고 식을 세운다.","단계":[{"제목":"좌표 잡고 식 세우기","힌트":"상판의 가운데를 원점으로 하면 케이블의 가장 낮은 점은 어디이고, 이 포물선은 어떤 꼴의 식인가?","식":["$y=ax^2+5$"],"설명":"가장 짧은 쇠사슬은 가운데에 있고 길이가 $5\\,\\mathrm{m}$ 이므로 꼭짓점이 $(0,\\,5)$ 인 포물선이다. 기둥의 꼭대기는 $\\mathrm{C}(50,\\,10)$ 이다.","확인":null,"스킬":"S4","고비":true},{"제목":"a 의 값","힌트":"점 $(50,\\,10)$ 을 대입하면 $a$ 는?","식":["$10=a\\times50^2+5$","$a=\\dfrac{1}{500}$"],"설명":"$2500a=5$ 에서 $a=\\dfrac{1}{500}$ 이다.","확인":null,"스킬":"S4"},{"제목":"두 번째로 짧은 쇠사슬","힌트":"쇠사슬은 $10\\,\\mathrm{m}$ 간격이므로 가운데에서 가장 가까운 쇠사슬의 $x$ 좌표는? 그 점의 $y$ 좌표는?","식":["$y=\\dfrac{1}{500}\\times10^2+5=5.2$"],"설명":"$9$개의 쇠사슬이 $100\\,\\mathrm{m}$ 를 같은 간격으로 나누므로 간격은 $10\\,\\mathrm{m}$ 이고 가운데 다음 쇠사슬은 $x=10$ 에 있다. 이 점을 $\\mathrm{D}$ 라 하면 $\\mathrm{D}(10,\\,5.2)$ 이다.","확인":"5.2","스킬":"S4"}],"fb":"fig/ns/"},"ns-f94b5e7fa4e8":{"길":"현의 길이가 같으면 호의 길이가 같고, 같은 길이의 호에 대한 원주각은 같다는 성질을 이용한다.","단계":[{"제목":"현의 길이 비교","힌트":"중심에서 두 현까지의 거리가 같으면 두 현의 길이는? 호의 길이는?","식":["$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{CD}}$","$\\overset{\\frown}{\\mathrm{AB}}=\\overset{\\frown}{\\mathrm{CD}}$"],"설명":"원의 중심에서 같은 거리에 있는 두 현의 길이는 같다. 길이가 같은 현에 대한 호의 길이도 같다.","확인":null,"스킬":"S5"},{"제목":"같은 크기의 각","힌트":"$\\angle\\mathrm{ACB}$ 와 같은 호, 또는 같은 길이의 호에 대한 원주각은 어느 것들인가?","식":["$\\angle\\mathrm{ACB}=\\angle\\mathrm{ADB}$","$\\angle\\mathrm{ACB}=\\angle\\mathrm{CAD}=\\angle\\mathrm{CBD}$"],"설명":"$\\angle\\mathrm{ACB}$ 와 $\\angle\\mathrm{ADB}$ 는 같은 호 $\\mathrm{AB}$ 에 대한 원주각이다. 호 $\\mathrm{AB}$ 와 호 $\\mathrm{CD}$ 의 길이가 같으므로 호 $\\mathrm{CD}$ 에 대한 원주각 $\\angle\\mathrm{CAD}$, $\\angle\\mathrm{CBD}$ 도 $\\angle\\mathrm{ACB}$ 와 같다.","확인":null,"스킬":"S5","고비":true},{"제목":"개수 세기","힌트":"<보기> 의 네 각 중 $\\angle\\mathrm{ACB}$ 와 같은 것은 몇 개인가?","식":["$\\angle\\mathrm{ADB},\\ \\angle\\mathrm{CAD},\\ \\angle\\mathrm{CBD}$"],"설명":"$\\angle\\mathrm{ADC}$ 는 호 $\\mathrm{AC}$ 에 대한 원주각이어서 이 조건으로는 $\\angle\\mathrm{ACB}$ 와 같다고 할 수 없다. 따라서 $3$개이다.","확인":"3","스킬":"S5"}],"fb":"fig/ns/"},"ns-ff7ae3c41a57":{"길":"지름에 대한 원주각과 같은 호에 대한 원주각으로 각을 구하고, 이등분선의 성질과 닮음으로 길이를 구해 보기를 하나씩 확인한다.","단계":[{"제목":"ㄱ 확인","힌트":"$\\overline{\\mathrm{AB}}$ 가 지름이면 $\\angle\\mathrm{ADB}$ 는 몇 도이고, $\\overline{\\mathrm{AB}}$ 는 피타고라스 정리로 얼마인가?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{6^2+2^2}=2\\sqrt{10}$","$\\overline{\\mathrm{OB}}=\\sqrt{10}$"],"설명":"지름에 대한 원주각은 $90^\\circ$ 이므로 $\\angle\\mathrm{ADB}=\\angle\\mathrm{ACB}=90^\\circ$ 이다. 따라서 ㄱ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄴ 확인","힌트":"직각이등변삼각형 $\\mathrm{ABC}$ 에서 $\\angle\\mathrm{ABC}$ 는 몇 도이고, $\\angle\\mathrm{ADC}$ 와는 어떤 관계인가?","식":["$\\angle\\mathrm{ABC}=45^\\circ$","$\\angle\\mathrm{ADC}=\\angle\\mathrm{ABC}=45^\\circ$"],"설명":"$\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CB}}$ 이고 $\\angle\\mathrm{ACB}=90^\\circ$ 이므로 $\\angle\\mathrm{CAB}=\\angle\\mathrm{CBA}=45^\\circ$ 이다. 호 $\\mathrm{AC}$ 에 대한 원주각이 같으므로 $\\angle\\mathrm{ADC}=\\angle\\mathrm{ABC}=45^\\circ$ 이고 ㄴ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄷ 확인","힌트":"$\\angle\\mathrm{ADP}$ 와 $\\angle\\mathrm{BDP}$ 가 같으면 $\\overline{\\mathrm{DP}}$ 는 $\\triangle\\mathrm{ADB}$ 의 무엇이 되는가?","식":["$\\angle\\mathrm{ADP}=\\angle\\mathrm{BDP}=45^\\circ$","$\\overline{\\mathrm{AP}}:\\overline{\\mathrm{PB}}=6:2=3:1$","$\\overline{\\mathrm{PB}}=\\dfrac{\\sqrt{10}}{2}$"],"설명":"$\\overline{\\mathrm{AB}}$ 와 $\\overline{\\mathrm{CD}}$ 의 교점을 $\\mathrm{P}$ 라 한다. $\\angle\\mathrm{ADC}=45^\\circ$ 이고 $\\angle\\mathrm{BDC}=\\angle\\mathrm{BAC}=45^\\circ$ 이므로 $\\overline{\\mathrm{DP}}$ 는 $\\angle\\mathrm{ADB}$ 의 이등분선이다. 따라서 $\\overline{\\mathrm{AP}}:\\overline{\\mathrm{PB}}=\\overline{\\mathrm{AD}}:\\overline{\\mathrm{DB}}$ 이고 $\\overline{\\mathrm{PB}}=2\\sqrt{10}\\times\\dfrac{1}{4}=\\dfrac{\\sqrt{10}}{2}$ 이므로 ㄷ 은 틀리다.","확인":null,"스킬":"S5"},{"제목":"ㅁ 확인","힌트":"$\\triangle\\mathrm{CBP}$ 와 닮은 삼각형을 찾으면 $\\overline{\\mathrm{CD}}$ 는 어떻게 구하는가?","식":["$\\overline{\\mathrm{CB}}=2\\sqrt{5}$","$\\triangle\\mathrm{CBP}\\sim\\triangle\\mathrm{CDB}$","$\\overline{\\mathrm{CD}}=4\\sqrt{2}$"],"설명":"$\\overline{\\mathrm{AB}}=2\\sqrt{10}$ 인 직각이등변삼각형 $\\mathrm{ABC}$ 에서 $\\overline{\\mathrm{CB}}=2\\sqrt{5}$ 이다. $\\angle\\mathrm{C}$ 는 공통이고 $\\angle\\mathrm{CBP}=\\angle\\mathrm{CDB}=45^\\circ$ 이므로 $\\triangle\\mathrm{CBP}\\sim\\triangle\\mathrm{CDB}$ ($AA$ 닮음)이다. $\\overline{\\mathrm{CB}}:\\overline{\\mathrm{CD}}=\\overline{\\mathrm{PB}}:\\overline{\\mathrm{BD}}$ 에서 $\\overline{\\mathrm{CD}}=4\\sqrt{2}$ 이므로 ㅁ 은 틀리다.","확인":null,"스킬":"S1","고비":true},{"제목":"ㄹ 확인과 개수","힌트":"같은 닮음비로 $\\overline{\\mathrm{CP}}$ 를 구하면 $\\overline{\\mathrm{PD}}$ 는?","식":["$\\overline{\\mathrm{CP}}=\\dfrac{5\\sqrt{2}}{2}$","$\\overline{\\mathrm{PD}}=4\\sqrt{2}-\\dfrac{5\\sqrt{2}}{2}=\\dfrac{3\\sqrt{2}}{2}$"],"설명":"닮음비 $\\overline{\\mathrm{CP}}:\\overline{\\mathrm{CB}}=\\overline{\\mathrm{PB}}:\\overline{\\mathrm{BD}}$ 에서 $\\overline{\\mathrm{CP}}=\\dfrac{5\\sqrt{2}}{2}$ 이므로 $\\overline{\\mathrm{PD}}=\\overline{\\mathrm{CD}}-\\overline{\\mathrm{CP}}=\\dfrac{3\\sqrt{2}}{2}$ 이다. 옳은 것은 ㄱ, ㄴ, ㄹ 의 $3$개이다.","확인":"3","스킬":"S1"}],"fb":"fig/ns/"},"ns-05908c79b5e0":{"길":"누락된 두 값의 평균을 기존 평균과 비교하고, 홀수 개의 자료에서 두 값이 중앙값의 양쪽에 놓이는지 본다.","단계":[{"제목":"평균의 변화","힌트":"빠뜨린 두 값의 평균을 기존 평균 $179\\,\\mathrm{cm}$ 와 비교하면?","식":["$\\dfrac{178+181}{2}=179.5>179$"],"설명":"빠진 두 값의 평균이 기존 평균보다 크므로 두 값을 넣으면 전체 평균은 $179\\,\\mathrm{cm}$ 보다 높아진다.","확인":null,"스킬":"C7"},{"제목":"중앙값의 변화","힌트":"선수가 홀수 명일 때 중앙값은 어떤 값이고, 추가한 두 값은 그 값을 기준으로 어느 쪽에 놓이는가?","식":["$178\\le(\\text{중앙값})=178\\le181$"],"설명":"홀수 명이면 중앙값은 한가운데 한 값 $178\\,\\mathrm{cm}$ 이다. 추가한 $178\\,\\mathrm{cm}$ 는 중앙값 이하, $181\\,\\mathrm{cm}$ 는 중앙값 이상이어서 양쪽에 한 명씩 늘어나므로 한가운데 값은 그대로 $178\\,\\mathrm{cm}$ 이다.","확인":null,"스킬":"C2","고비":true}],"fb":"fig/ns/"},"ns-0f3ee31b0dcb":{"길":"$a$ 를 뺀 다섯 값을 정렬해 두고, $a$ 의 위치에 따라 중앙값을 구해 보기를 하나씩 확인한다.","단계":[{"제목":"정렬","힌트":"$a$ 를 뺀 다섯 값을 작은 것부터 늘어놓으면?","식":["$7,\\ 10,\\ 14,\\ 16,\\ 19$"],"설명":"$a$ 를 넣으면 자료가 $6$개이므로 중앙값은 셋째 값과 넷째 값의 평균이다.","확인":null,"스킬":"C2"},{"제목":"ㄱ 확인","힌트":"중앙값이 $a$ 보다 크려면 $a$ 는 작은 쪽에서 몇 번째까지 가능한가?","식":["$a<14$"],"설명":"$a$ 가 넷째 이후에 오면 셋째와 넷째 값이 모두 $a$ 이하라서 중앙값이 $a$ 이하가 된다. 그러므로 $a$ 는 첫째, 둘째, 셋째에 있어야 하고 $a<14$ 이다. ㄱ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"ㄴ 확인","힌트":"$a\\le10$ 일 때와 $10<a<14$ 일 때로 나누어 중앙값의 범위를 구하면?","식":["$a\\le10:\\ \\dfrac{10+14}{2}=12$","$10<a<14:\\ \\dfrac{a+14}{2},\\ \\ 12<\\dfrac{a+14}{2}<14$"],"설명":"$a\\le10$ 이면 셋째와 넷째 값이 $10$, $14$ 이므로 중앙값은 $12$ 이다. $10<a<14$ 이면 셋째와 넷째 값이 $a$, $14$ 이고 중앙값은 $12$ 보다 크고 $14$ 보다 작다. 따라서 자연수인 중앙값은 $12$, $13$ 이어서 ㄴ 은 옳다.","확인":null,"스킬":"C2","고비":true},{"제목":"ㄷ 확인","힌트":"$16$ 을 $160$ 으로 바꾸어도 셋째 값과 넷째 값은 변하는가?","식":["$\\text{셋째, 넷째 값은 변하지 않는다}$"],"설명":"$a<14$ 이므로 $16$ 은 항상 다섯째에 있어 $160$ 으로 바뀌어도 셋째, 넷째 값은 그대로이고 중앙값도 변하지 않는다. 따라서 ㄷ 은 틀리고 옳은 것은 ㄱ, ㄴ 이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-14b72d7035ab":{"길":"근의 공식에서 근호 안의 수가 제곱수가 되는 조건을 찾고, 그 조건을 만족하는 순서쌍을 센다.","단계":[{"제목":"근의 공식","힌트":"근의 공식에 대입했을 때 근호 안의 식은 $a-b$ 로 어떻게 쓰이는가?","식":["$x=\\dfrac{3\\pm\\sqrt{13-4(a-b)}}{2}$"],"설명":"$x^2-3x+a-b-1=0$ 의 근호 안은 $9-4(a-b-1)=13-4(a-b)$ 이다.","확인":null,"스킬":"N8"},{"제목":"유리수가 되는 조건","힌트":"해가 모두 유리수가 되려면 근호 안의 수는 어떤 수여야 하는가? 단 $a-b$ 는 $-5$ 이상 $5$ 이하의 정수이다.","식":["$13-4(a-b)=0,\\ 1,\\ 4,\\ 9,\\ 16,\\ 25$","$a-b=3,\\ 1,\\ -3$"],"설명":"근호 안이 $0$ 또는 제곱수여야 한다. 이 중 $a-b$ 가 정수가 되는 경우는 $13-4(a-b)=1,\\ 9,\\ 25$ 일 때이고, $a-b=3,\\ 1,\\ -3$ 이다.","확인":null,"스킬":"N8","고비":true},{"제목":"순서쌍 세기","힌트":"주사위 눈 $a$, $b$ 에 대해 $a-b=3,\\ 1,\\ -3$ 인 순서쌍은 각각 몇 개인가?","식":["$a-b=3:\\ (4,1),(5,2),(6,3)$","$a-b=1:\\ (2,1),(3,2),(4,3),(5,4),(6,5)$","$a-b=-3:\\ (1,4),(2,5),(3,6)$"],"설명":"각 경우를 $b$ 의 값부터 빠짐없이 적는다.","확인":null,"스킬":"P4"},{"제목":"확률","힌트":"전체 경우의 수 $36$ 중 조건을 만족하는 경우의 수는?","식":["$\\dfrac{3+5+3}{36}=\\dfrac{11}{36}$"],"설명":"조건을 만족하는 경우가 $3+5+3=11$ 가지이므로 확률은 $\\dfrac{11}{36}$ 이다.","확인":"11/36","스킬":"P4"}],"fb":"fig/ns/"},"ns-152c8e497f5b":{"길":"$\\sqrt{x}=a-2$ 에서 $x$ 를 $a$ 로 나타내어 근호 안을 완전제곱식으로 만든다.","단계":[{"제목":"x 를 a 로 나타내기","힌트":"$\\sqrt{x}=a-2$ 의 양변을 제곱하면 근호 안의 식은 어떻게 바뀌는가?","식":["$x=(a-2)^2=a^2-4a+4$","$x+2a-3=a^2-2a+1,\\ \\ x-2a+5=a^2-6a+9$"],"설명":"$x$ 에 $a^2-4a+4$ 를 대입해 두 근호 안의 식을 $a$ 로 나타낸다.","확인":null,"스킬":"N5"},{"제목":"완전제곱식","힌트":"두 근호 안의 식을 각각 어떤 식의 제곱으로 쓸 수 있는가?","식":["$\\sqrt{a^2-2a+1}-\\sqrt{a^2-6a+9}=\\sqrt{(a-1)^2}-\\sqrt{(a-3)^2}$"],"설명":"$a^2-2a+1=(a-1)^2$, $a^2-6a+9=(a-3)^2$ 이다.","확인":null,"스킬":"A6","고비":true},{"제목":"부호 판정","힌트":"$2<a<3$ 일 때 $a-1$ 과 $a-3$ 의 부호는?","식":["$a-1>0,\\ \\ a-3<0$","$(a-1)-\\{-(a-3)\\}=2a-4$"],"설명":"$A\\ge0$ 이면 $\\sqrt{A^2}=A$, $A<0$ 이면 $\\sqrt{A^2}=-A$ 이다. 따라서 $\\sqrt{(a-3)^2}=-(a-3)$ 이다.","확인":null,"스킬":"N5"}],"fb":"fig/ns/"},"ns-164e9c00de0e":{"길":"평균 조건으로 학생 $\\mathrm{D}$ 의 키를 구한 뒤, 나머지 키의 범위를 따져 여섯 명의 중앙값의 범위를 구한다.","단계":[{"제목":"D 의 키","힌트":"$\\mathrm{D}$ 의 키를 $d$ 라 하고, $\\mathrm{D}$ 대신 $\\mathrm{F}$ 를 넣은 $5$ 명의 키의 합을 식으로 쓰면?","식":["$161.5\\times5-d+166=160\\times5$","$d=173.5$"],"설명":"처음 $5$ 명의 키의 합은 $161.5\\times5$ 이고, 여기서 $d$ 를 빼고 $166$ 을 더한 합이 $160\\times5$ 이다.","확인":null,"스킬":"C7"},{"제목":"나머지 키의 범위","힌트":"처음 $5$ 명의 중앙값이 $161$ 이면 나머지 학생의 키는 $161$ 의 어느 쪽에 놓이는가?","식":["$a\\le161,\\ \\ b\\le161,\\ \\ e\\ge161$"],"설명":"중앙값이 $161\\,\\mathrm{cm}$ 인 학생을 $\\mathrm{C}$ 라 하고 나머지 세 명의 키를 $a$, $b$, $e$ 라 한다. $\\mathrm{D}$ 는 $161$ 보다 크므로 $a$, $b$ 는 $161$ 이하, $e$ 는 $161$ 이상이어야 한다.","확인":null,"스킬":"C2","고비":true},{"제목":"여섯 명의 중앙값","힌트":"$\\mathrm{F}$ 를 포함한 여섯 명을 작은 값부터 늘어놓으면 셋째와 넷째 값은 어떤 범위에 있는가?","식":["$161\\le(\\text{중앙값})\\le163.5$"],"설명":"$a$, $b$ 가 $161$ 이하이므로 셋째 값은 $161$ 이고 넷째 값은 $e$ 와 $166$ 중 작은 쪽이다. 넷째 값은 $161$ 이상 $166$ 이하이므로 중앙값은 $161$ 이상 $163.5$ 이하이다.","확인":null,"스킬":"C2"},{"제목":"될 수 없는 값","힌트":"선지 중 이 범위를 벗어나는 것은?","식":["$164.5>163.5$"],"설명":"$164.5\\,\\mathrm{cm}$ 는 범위 밖이므로 중앙값이 될 수 없다.","확인":"164.5","스킬":"C2"}],"fb":"fig/ns/"},"ns-1815c2e0e8a0":{"길":"한 문자에 대한 이차식으로 정리해 계수끼리 십자로 묶는다.","단계":[{"제목":"$x$ 에 대한 내림차순 정리","힌트":"$x$ 에 대해 차수별로 묶으면 $x$ 의 계수는 어떤 $y$ 의 식이 되는가?","식":["$2x^2-(7y+14)x+3y^2+2y-16$"],"설명":"$x$ 에 대한 이차식으로 보고 $x$ 의 계수와 상수항을 $y$ 의 식으로 묶는다.","확인":null,"스킬":"A11","고비":true},{"제목":"상수항 인수분해","힌트":"$3y^2+2y-16$ 은 어떤 두 일차식의 곱인가?","식":["$3y^2+2y-16=(3y+8)(y-2)$"],"설명":"상수항 $-16$ 을 $8\\times(-2)$ 로 나누고 $y$ 의 계수 $2$ 가 나오도록 $3y+8$, $y-2$ 를 잡는다.","확인":null,"스킬":"A11"},{"제목":"십자로 두 일차식 묶기","힌트":"$x$ 의 계수가 $-(7y+14)$ 가 되도록 $3y+8$, $y-2$ 에 부호를 붙여 짝지으면?","식":["$2x^2-(7y+14)x+(3y+8)(y-2)=(x-3y-8)(2x-y+2)$"],"설명":"십자 곱셈에서 $x\\times\\{-(y-2)\\}+\\{-(3y+8)\\}\\times2x=-(7y+14)x$ 가 되어 $x$ 의 계수와 맞는다.","확인":null,"스킬":"A11"},{"제목":"계수 읽어 합 구하기","힌트":"$(x+ay+b)(2x+cy+d)$ 와 비교하면 $a$, $b$, $c$, $d$ 는 각각 얼마인가?","식":["$a=-3,\\ b=-8,\\ c=-1,\\ d=2$","$a+b+c+d=-10$"],"설명":"인수분해 결과와 주어진 꼴의 각 항을 대응시켜 네 수를 읽는다.","확인":"-10","스킬":"A3"}],"fb":"fig/ns/"},"ns-19557671e607":{"길":"근의 공식으로 가를 확인하고 나와 다는 반례나 포함 관계로 가린다.","단계":[{"제목":"가 확인","힌트":"$x^2+2bx+c=0$ 을 근의 공식으로 풀면?","식":["$x=-b\\pm\\sqrt{b^2-c}$"],"설명":"일차항 계수 $2b$ 의 절반이 $b$ 이므로 근의 공식에 그대로 넣으면 보기 가와 같다. 가는 옳다.","확인":null,"스킬":"C3"},{"제목":"나 확인","힌트":"해가 유리수가 되려면 $\\sqrt{b^2-c}$ 는 어떤 수이어야 하는가?","식":["$b^2-c=(\\text{유리수})^2$"],"설명":"$c=0$ 이면 해가 유리수이지만 해가 유리수라고 해서 $c=0$ 이어야 하는 것은 아니다. 나는 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"다 반례 찾기","힌트":"$b^2=|c|$ 를 만족하는 $b$, $c$ 를 하나 잡아 해를 구하면?","식":["$b=2,\\ c=-4$","$x=-2\\pm\\sqrt{2^2-(-4)}=-2\\pm2\\sqrt2$"],"설명":"$b=2$, $c=-4$ 는 $b^2=|c|$ 를 만족하지만 해가 서로 다른 두 수이므로 중근이 아니다. 다는 옳지 않다.","확인":null,"스킬":"C3","고비":true},{"제목":"옳은 보기 고르기","힌트":"세 보기 중 옳은 것은 무엇인가?","식":["$\\text{가만 옳다}$"],"설명":"가만 옳으므로 선지 ① 이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-1b0808a462cd":{"길":"근호 안을 완전제곱식으로 고친 뒤 범위로 부호를 정해 근호를 벗긴다.","단계":[{"제목":"근호 안 완전제곱식","힌트":"$\\left(a-\\frac1a\\right)^2+4$ 와 $\\left(a+\\frac1a\\right)^2-4$ 를 전개해 정리하면 각각 어떤 식의 제곱이 되는가?","식":["$\\left(a-\\frac1a\\right)^2+4=a^2+2+\\frac1{a^2}=\\left(a+\\frac1a\\right)^2$","$\\left(a+\\frac1a\\right)^2-4=a^2-2+\\frac1{a^2}=\\left(a-\\frac1a\\right)^2$"],"설명":"$-2$ 와 $+4$ 가 합쳐져 $+2$ 가 되므로 합의 제곱이 되고, 다른 쪽은 $+2$ 와 $-4$ 가 합쳐져 $-2$ 가 되므로 차의 제곱이 된다.","확인":null,"스킬":"A6","고비":true},{"제목":"부호 판정","힌트":"$0<a<1$ 일 때 $a-\\frac1a$ 와 $a+\\frac1a$ 의 부호는?","식":["$a-\\frac1a<0$","$a+\\frac1a>0$"],"설명":"$0<a<1$ 이면 $\\frac1a>1>a$ 이므로 $a-\\frac1a$ 는 음수이고 $a+\\frac1a$ 는 양수이다.","확인":null,"스킬":"C2"},{"제목":"근호 벗기기","힌트":"근호 안이 제곱일 때 안쪽 식의 부호에 따라 어떻게 벗기는가?","식":["$\\left(a+\\frac1a\\right)+\\left(-a+\\frac1a\\right)=\\frac2a$"],"설명":"음수인 $a-\\frac1a$ 는 부호를 바꿔 $-\\left(a-\\frac1a\\right)$ 로 벗긴다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-1b3ba7a6444a":{"길":"지수가 절반씩 줄도록 합차 공식을 거듭 적용해 작은 인수를 찾는다.","단계":[{"제목":"합차 공식 거듭 적용","힌트":"$2^{64}-1=(2^{32})^2-1^2$ 으로 보고 같은 방법을 끝까지 되풀이하면?","식":["$2^{64}-1=(2^{32}+1)(2^{16}+1)(2^{8}+1)(2^{4}+1)(2^{2}+1)(2+1)(2-1)$"],"설명":"$X^2-1=(X+1)(X-1)$ 을 $X=2^{32},\\,2^{16},\\,2^{8},\\,2^{4},\\,2^{2},\\,2$ 에 차례로 적용하면 지수가 절반씩 줄어 $2-1$ 에서 멈춘다.","확인":null,"스킬":"A12","고비":true},{"제목":"작은 인수의 값","힌트":"$2^4+1$, $2^2+1$, $2+1$ 의 값은 각각 얼마인가?","식":["$2^{64}-1=(2^{32}+1)(2^{16}+1)(2^{8}+1)\\times17\\times5\\times3$"],"설명":"$2^4+1=17$, $2^2+1=5$, $2+1=3$ 이고 $2-1=1$ 은 곱에 영향이 없다.","확인":null,"스킬":"N1"},{"제목":"10 과 20 사이의 약수","힌트":"$17$, $5$, $3$ 과 그 곱 중 $10$ 보다 크고 $20$ 보다 작은 수는?","식":["$5\\times3=15$, $17$"],"설명":"앞의 세 인수는 매우 큰 수이므로 작은 약수는 $17$, $5$, $3$ 과 그 곱에서 찾고, $15$ 와 $17$ 이 조건에 맞는다.","확인":null,"스킬":"N1"},{"제목":"A 와 B 의 합","힌트":"두 수 $\\mathrm{A}$, $\\mathrm{B}$ 의 합은?","식":["$\\mathrm{A}+\\mathrm{B}=15+17=32$"],"설명":"조건에 맞는 두 수를 더한다.","확인":"32","스킬":"N1"}],"fb":"fig/ns/"},"ns-1c52ee3098ac":{"길":"부등식으로 바꿔 $m$ 을 구하고 $x$ 값별로 나눠 $n$ 을 센다.","단계":[{"제목":"$m$ 구하기","힌트":"일곱 자리 자연수 $a$ 의 범위에서 $\\sqrt a$ 는 어디에서 어디까지인가?","식":["$10^6\\le a<10^7$","$1000\\le\\sqrt a<1000\\sqrt{10}$","$m=4$"],"설명":"$\\sqrt{10}<10$ 이므로 $\\sqrt a$ 는 $1000$ 이상 $10000$ 미만이고 정수 부분은 네 자리 수이다.","확인":"4","스킬":"N7"},{"제목":"부등식으로 바꾸기","힌트":"$\\sqrt{x^2+y^2}$ 의 정수 부분이 $8$ 이면 $x^2+y^2$ 은 어떤 범위인가?","식":["$8\\le\\sqrt{x^2+y^2}<9$","$64\\le x^2+y^2<81$"],"설명":"정수 부분이 $8$ 이면 $8$ 이상 $9$ 미만이므로 제곱해서 범위를 만든다.","확인":null,"스킬":"N7"},{"제목":"$x$ 값별로 세기","힌트":"$x\\ge y$ 이므로 $x$ 를 가장 큰 값부터 정해 가능한 $y$ 를 찾으면?","식":["$(8,1),(8,2),(8,3),(8,4),(7,4),(7,5),(6,6)$","$n=7$"],"설명":"$x=8$ 이면 $y^2<17$ 이므로 $y=1,2,3,4$, $x=7$ 이면 $15\\le y^2<32$ 이므로 $y=4,5$, $x=6$ 이면 $y=6$ 하나이다. $x\\le5$ 이면 $x^2+y^2\\le50$ 이어서 $64$ 에 못 미치고, $x\\ge9$ 이면 $81$ 이상이 된다.","확인":"7","스킬":"P4","고비":true},{"제목":"$mn$ 구하기","힌트":"$m$ 과 $n$ 의 곱은?","식":["$mn=4\\times7=28$"],"설명":"앞에서 구한 $m=4$, $n=7$ 을 곱한다.","확인":"28","스킬":"P4"}],"fb":"fig/ns/"},"ns-1d5025dc26be":{"길":"한 식을 인수분해해 공통인수 후보를 정하고 후보별로 다른 식의 계수를 비교한다.","단계":[{"제목":"한 식 인수분해","힌트":"$x^2-(a+1)x+a$ 는 어떻게 인수분해되는가?","식":["$x^2-(a+1)x+a=(x-1)(x-a)$"],"설명":"합이 $-(a+1)$ 이고 곱이 $a$ 인 두 수는 $-1$ 과 $-a$ 이다.","확인":null,"스킬":"A2"},{"제목":"공통인수 후보 나누기","힌트":"공통인수가 될 수 있는 일차식은 어떤 것들인가?","식":["$x-1$ 또는 $x-a$"],"설명":"공통인수는 두 식의 인수여야 하므로 $(x-1)(x-a)$ 의 일차식인 $x-1$ 과 $x-a$ 로 경우를 나눈다.","확인":null,"스킬":"C2","고비":true},{"제목":"$x-1$ 인 경우","힌트":"다른 식을 $(x-1)(x+m)$ 이라 놓고 계수를 비교하면 $a$ 가 정해지는가?","식":["$a+5=1-m,\\ a+8=-m$","$a+5=a+9$"],"설명":"두 식에서 $m$ 을 없애면 $a$ 에 관계없이 성립하지 않는 등식이 되어 이 경우는 불가능하다.","확인":null,"스킬":"A3"},{"제목":"$x-a$ 인 경우","힌트":"다른 식을 $(x-a)(x+n)$ 이라 놓고 계수를 비교하면?","식":["$a+5=a-n,\\ a+8=-an$","$n=-5,\\ a=2$"],"설명":"$n=-5$ 를 $a+8=-an$ 에 넣으면 $a+8=5a$ 이므로 $a=2$ 이다.","확인":"2","스킬":"A3"}],"fb":"fig/ns/"},"ns-1ed8da3e32d7":{"길":"주어진 식을 정리해 $a(x-c)^2$ 과 계수를 비교하고 정수 조건으로 순서쌍을 센다.","단계":[{"제목":"빼서 정리하기","힌트":"$ax^2-(4a-b)x+b^2$ 에서 $bx-4$ 를 빼고 $x$ 의 항끼리 모으면?","식":["$ax^2-4ax+b^2+4$"],"설명":"$-(4a-b)x-bx=-4ax$ 이고 상수항은 $b^2+4$ 이다.","확인":null,"스킬":"A3"},{"제목":"계수 비교로 $c$ 구하기","힌트":"$a(x-c)^2$ 을 전개해 $x$ 의 계수를 비교하면 $c$ 는?","식":["$ax^2-4ax+b^2+4=ax^2-2acx+ac^2$","$-4a=-2ac$","$c=2$"],"설명":"$a(x-c)^2$ 은 이차식이므로 $a\\ne0$ 이고 양변을 $-2a$ 로 나눌 수 있다.","확인":null,"스킬":"A3","고비":true},{"제목":"$a$ 와 $b$ 의 관계","힌트":"상수항을 비교하면 $a$ 와 $b$ 사이에는 어떤 관계가 있는가?","식":["$b^2+4=ac^2=4a$","$b^2=4(a-1)$"],"설명":"$b^2$ 이 $4$ 의 배수이므로 $b$ 는 짝수이다.","확인":null,"스킬":"A3"},{"제목":"순서쌍 나열","힌트":"$|b|\\le10$ 인 짝수 $b$ 에 대해 $a$ 는 정수로 정해지는가?","식":["$(1,0),(2,\\pm2),(5,\\pm4),(10,\\pm6),(17,\\pm8),(26,\\pm10)$","$d=11$"],"설명":"$b=0$ 이면 $a=1$ 한 쌍이고, $b=\\pm2,\\pm4,\\pm6,\\pm8,\\pm10$ 이면 $b$ 마다 $a$ 가 하나씩 정해져 각각 두 쌍씩이다.","확인":"11","스킬":"P4"},{"제목":"$cd$ 구하기","힌트":"$c$ 와 $d$ 의 곱은?","식":["$cd=2\\times11=22$"],"설명":"$c=2$, $d=11$ 을 곱한다.","확인":"22","스킬":"A3"}],"fb":"fig/ns/"},"ns-202a9a73791b":{"길":"분모는 완전제곱 공식으로, 분자는 한 수를 문자로 놓고 두 번 치환해 완전제곱으로 만든다.","단계":[{"제목":"분모 완전제곱","힌트":"$142^2-1420+25$ 에서 $1420$ 과 $25$ 는 $142$ 와 어떤 수의 곱, 제곱인가?","식":["$142^2-2\\times142\\times5+5^2=(142-5)^2=137^2$"],"설명":"$1420=2\\times142\\times5$ 이고 $25=5^2$ 이므로 $a^2-2ab+b^2=(a-b)^2$ 에 맞는다.","확인":null,"스킬":"A6"},{"제목":"$21$ 을 $\\mathrm{A}$ 로 치환","힌트":"분자의 네 수를 $\\mathrm{A}$ 로 나타내고, 공통 부분이 생기도록 짝지어 곱하면?","식":["$(\\mathrm{A}+1)(\\mathrm{A}+4)\\cdot\\mathrm{A}(\\mathrm{A}+5)+4=(\\mathrm{A}^2+5\\mathrm{A}+4)(\\mathrm{A}^2+5\\mathrm{A})+4$"],"설명":"$21=\\mathrm{A}$ 라 하면 $22=\\mathrm{A}+1$, $25=\\mathrm{A}+4$, $26=\\mathrm{A}+5$ 이다. $(\\mathrm{A}+1)(\\mathrm{A}+4)$ 와 $\\mathrm{A}(\\mathrm{A}+5)$ 를 전개하면 $\\mathrm{A}^2+5\\mathrm{A}$ 가 공통으로 나온다.","확인":null,"스킬":"A1","고비":true},{"제목":"$\\mathrm{B}$ 로 치환","힌트":"$\\mathrm{A}^2+5\\mathrm{A}=\\mathrm{B}$ 로 놓고 분자를 $\\mathrm{B}$ 의 식으로 쓰면?","식":["$(\\mathrm{B}+4)\\mathrm{B}+4=\\mathrm{B}^2+4\\mathrm{B}+4=(\\mathrm{B}+2)^2$"],"설명":"$\\mathrm{B}$ 에 대한 완전제곱식이 된다.","확인":null,"스킬":"A1"},{"제목":"분자의 값","힌트":"$\\mathrm{A}=21$ 을 넣어 $\\mathrm{B}+2$ 를 구하고 분모의 $137$ 과 비교하면?","식":["$\\mathrm{A}^2+5\\mathrm{A}+2=548=4\\times137$","$\\frac{(\\mathrm{B}+2)^2}{137^2}=4^2$"],"설명":"분자는 $548^2$ 이고 분모는 $137^2$ 이므로 약분하면 $4^2$ 이다.","확인":null,"스킬":"A1"},{"제목":"근호 계산","힌트":"근호 안의 값은 얼마인가?","식":["$\\sqrt{4^2+9}=\\sqrt{25}=5$"],"설명":"$16+9=25$ 이고 $25$ 의 양의 제곱근을 취한다.","확인":"5","스킬":"A6"}],"fb":"fig/ns/"},"ns-20b2f77cef27":{"길":"$x$ 에 대해 정리하고 계수의 부호를 보아 부등호를 정한 뒤 유리화하여 정수를 찾는다.","단계":[{"제목":"$x$ 에 대해 정리","힌트":"$x$ 의 항을 한쪽으로 모으면?","식":["$2x+8<3\\sqrt5+\\sqrt5x$","$(2-\\sqrt5)x<3\\sqrt5-8$"],"설명":"괄호를 풀어 $x$ 항은 좌변, 상수는 우변으로 옮긴다.","확인":null,"스킬":"N5"},{"제목":"계수의 부호 보고 나누기","힌트":"$2-\\sqrt5$ 의 부호는? 그러면 부등호 방향은 어떻게 되는가?","식":["$2-\\sqrt5<0$","$x>\\frac{3\\sqrt5-8}{2-\\sqrt5}$"],"설명":"$2=\\sqrt4<\\sqrt5$ 이므로 $2-\\sqrt5$ 는 음수이고, 음수로 나누면 부등호 방향이 바뀐다.","확인":null,"스킬":"N5","고비":true},{"제목":"분모 유리화","힌트":"분모를 유리화해 우변을 정리하면?","식":["$\\frac{(3\\sqrt5-8)(2+\\sqrt5)}{(2-\\sqrt5)(2+\\sqrt5)}=\\frac{-1-2\\sqrt5}{-1}=1+2\\sqrt5$"],"설명":"분자는 $6\\sqrt5+15-16-8\\sqrt5=-1-2\\sqrt5$ 이고 분모는 $4-5=-1$ 이다.","확인":null,"스킬":"N5"},{"제목":"가장 작은 정수 찾기","힌트":"$2\\sqrt5$ 는 어느 두 정수 사이의 수인가?","식":["$4<2\\sqrt5<5$","$5<1+2\\sqrt5<6$"],"설명":"$4=\\sqrt{16}<\\sqrt{20}<\\sqrt{25}=5$ 이므로 $x>1+2\\sqrt5$ 를 만족하는 가장 작은 정수는 $6$ 이다.","확인":"6","스킬":"N7"}],"fb":"fig/ns/"},"ns-25c35f164e9b":{"길":"두 제곱의 차를 합차 공식으로 묶어 $(xy)^n$ 꼴로 만들고 $xy$ 의 값을 대입한다.","단계":[{"제목":"합차 공식으로 묶기","힌트":"$x^n$ 과 $y^n$ 을 각각 한 덩어리로 보고 두 제곱의 차를 합과 차의 곱으로 쓰면?","식":["$\\left\\{(x^n-y^n)+(x^n+y^n)\\right\\}\\left\\{(x^n-y^n)-(x^n+y^n)\\right\\}$","$=2x^n\\times(-2y^n)=-4(xy)^n$"],"설명":"$P^2-Q^2=(P+Q)(P-Q)$ 에서 $P=x^n-y^n$, $Q=x^n+y^n$ 으로 놓는다.","확인":null,"스킬":"A1","고비":true},{"제목":"$xy$ 의 값","힌트":"$xy=(9-4\\sqrt5)(9+4\\sqrt5)$ 의 값은?","식":["$xy=9^2-(4\\sqrt5)^2=81-80=1$"],"설명":"켤레의 곱이므로 $(a-b)(a+b)=a^2-b^2$ 을 쓴다.","확인":null,"스킬":"A2"},{"제목":"대입","힌트":"$xy$ 의 값을 대입하면?","식":["$-4(xy)^n=-4\\times1^n=-4$"],"설명":"$1$ 의 거듭제곱은 항상 $1$ 이다.","확인":"-4","스킬":"A2"}],"fb":"fig/ns/"},"ns-288e6687c625":{"길":"근의 합으로 $a+b$ 를 정하고 최대공약수 조건으로 두 수를 좁힌 뒤 곱을 구한다.","단계":[{"제목":"두 근의 합과 곱","힌트":"근과 계수의 관계에서 두 근의 합과 곱은 각각 무엇인가?","식":["$a+b=24,\\ ab=k$"],"설명":"$x^2-24x+k=0$ 의 두 근이 $a$, $b$ 이므로 합은 $24$ 이고 곱은 $k$ 이다.","확인":null,"스킬":"A2"},{"제목":"최대공약수로 후보 좁히기","힌트":"최대공약수가 $3$ 이면 $a$, $b$ 를 어떤 꼴로 쓸 수 있는가? 조건 $a>b>3$ 을 만족하는 쌍은?","식":["$a=3p,\\ b=3q\\ (p,q\\text{는 서로소})$","$p+q=8$","$a=15,\\ b=9$"],"설명":"$p+q=8$ 에서 $p>q$ 인 쌍은 $(7,1),(6,2),(5,3)$ 이다. $q=1$ 이면 $b=3$ 이어서 $b>3$ 에 어긋나고, $(6,2)$ 는 서로소가 아니므로 $(5,3)$ 만 남는다.","확인":null,"스킬":"N2","고비":true},{"제목":"$k$ 구하기","힌트":"$k=ab$ 를 계산하면?","식":["$k=15\\times9=135$"],"설명":"곱이 $k$ 이므로 두 근을 곱한다.","확인":"135","스킬":"A2"}],"fb":"fig/ns/"},"ns-292828986a86":{"길":"$291$ 을 $289$ 와 $2$ 로 나눠 합의 제곱으로 만들고 근호를 벗긴다.","단계":[{"제목":"근호 안 쪼개기","힌트":"$291$ 을 $289$ 와 어떤 수의 합으로 쓰면 $289$, $\\frac1{289}$ 과 함께 합의 제곱 꼴이 되는가?","식":["$291+\\frac1{289}=17^2+2+\\frac1{17^2}$"],"설명":"$291=289+2$ 이고 $289=17^2$ 이다.","확인":null,"스킬":"A6","고비":true},{"제목":"완전제곱식","힌트":"$17^2+2+\\frac1{17^2}$ 은 어떤 식의 제곱인가?","식":["$17^2+2\\times17\\times\\frac1{17}+\\frac1{17^2}=\\left(17+\\frac1{17}\\right)^2$"],"설명":"가운데 항 $2$ 는 $2\\times17\\times\\frac1{17}$ 이므로 합의 제곱이다.","확인":null,"스킬":"A6"},{"제목":"근호 벗기기","힌트":"근호를 벗기고 통분하면?","식":["$\\sqrt{\\left(17+\\frac1{17}\\right)^2}=17+\\frac1{17}=\\frac{290}{17}$"],"설명":"$17+\\frac1{17}$ 은 양수이므로 그대로 벗겨지고, 통분하면 $\\frac{289+1}{17}$ 이다.","확인":null,"스킬":"A6"},{"제목":"$\\mathrm{A}+\\mathrm{B}$ 구하기","힌트":"$290$ 과 $17$ 은 서로소인가? 그러면 $\\mathrm{A}+\\mathrm{B}$ 는?","식":["$\\mathrm{A}=17,\\ \\mathrm{B}=290$","$\\mathrm{A}+\\mathrm{B}=307$"],"설명":"$290=2\\times5\\times29$ 이므로 $17$ 과 약분되지 않아 기약분수이다.","확인":"307","스킬":"N2"}],"fb":"fig/ns/"},"ns-2ae62cb81ba9":{"길":"근의 공식으로 근호 안을 제곱수로 정하고 두 자리 범위에서 개수를 센다.","단계":[{"제목":"근의 공식","힌트":"$x^2-8x-k=0$ 의 근을 근의 공식으로 구하면?","식":["$x=4\\pm\\sqrt{16+k}$"],"설명":"$x$ 의 계수 $-8$ 이 짝수이므로 $b'=-4$ 를 써서 $x=4\\pm\\sqrt{16+k}$ 이다.","확인":null,"스킬":"N8"},{"제목":"제곱수 조건","힌트":"근이 정수가 되려면 $16+k$ 는 어떤 수이어야 하는가?","식":["$16+k=(\\text{자연수})^2$"],"설명":"$16+k$ 가 자연수이므로 $\\sqrt{16+k}$ 가 정수이려면 제곱수여야 한다.","확인":null,"스킬":"N8","고비":true},{"제목":"범위 안의 제곱수","힌트":"$k$ 가 두 자리 자연수이면 $16+k$ 는 어느 범위에 있는가?","식":["$26\\le16+k\\le115$","$16+k=36,\\ 49,\\ 64,\\ 81,\\ 100$"],"설명":"$5^2=25$ 는 $26$ 보다 작고 $11^2=121$ 은 $115$ 보다 크므로 $6^2$ 부터 $10^2$ 까지가 해당한다.","확인":null,"스킬":"N8"},{"제목":"개수 세기","힌트":"해당하는 $k$ 는 모두 몇 개인가?","식":["$k=20,\\ 33,\\ 48,\\ 65,\\ 84$","$5\\text{개}$"],"설명":"$k=(\\text{제곱수})-16$ 으로 구한 값은 모두 두 자리 자연수이다.","확인":"5","스킬":"N8"}],"fb":"fig/ns/"},"ns-2bc80b285c7f":{"길":"분모를 유리화해 합을 나열하고 상쇄되고 남는 항만 모은다.","단계":[{"제목":"분모 유리화","힌트":"분모의 켤레 $\\sqrt{x+2}-\\sqrt x$ 를 분자와 분모에 곱하면?","식":["$f(x)=\\frac{\\sqrt{x+2}-\\sqrt x}{(\\sqrt{x+2})^2-(\\sqrt x)^2}=\\frac{\\sqrt{x+2}-\\sqrt x}{2}$"],"설명":"분모는 $(x+2)-x=2$ 가 된다.","확인":null,"스킬":"P6"},{"제목":"항 나열하여 상쇄","힌트":"$f(1)$ 부터 $f(48)$ 까지 쓰면 어떤 항이 서로 지워지는가?","식":["$\\frac12\\{(\\sqrt3-\\sqrt1)+(\\sqrt4-\\sqrt2)+(\\sqrt5-\\sqrt3)+\\cdots+(\\sqrt{49}-\\sqrt{47})+(\\sqrt{50}-\\sqrt{48})\\}$"],"설명":"$f(1)$ 의 $\\sqrt3$ 은 $f(3)$ 의 $-\\sqrt3$ 과 지워지고, 이렇게 $x$ 와 $x+2$ 의 항이 짝을 이룬다.","확인":null,"스킬":"P6","고비":true},{"제목":"남는 항","힌트":"지워지지 않는 항은 앞쪽과 뒤쪽에서 각각 무엇인가?","식":["$\\frac12(-1-\\sqrt2+\\sqrt{49}+\\sqrt{50})$"],"설명":"앞쪽에서는 $-\\sqrt1$, $-\\sqrt2$ 가, 뒤쪽에서는 $\\sqrt{49}$, $\\sqrt{50}$ 이 남는다.","확인":null,"스킬":"P6"},{"제목":"값 계산","힌트":"남은 항을 간단히 하면?","식":["$\\frac12(-1-\\sqrt2+7+5\\sqrt2)=\\frac12(6+4\\sqrt2)=3+2\\sqrt2$"],"설명":"$\\sqrt{49}=7$, $\\sqrt{50}=5\\sqrt2$ 이다.","확인":null,"스킬":"P6"}],"fb":"fig/ns/"},"ns-2c88df58c0ce":{"길":"$7$ 에 $1000^2$ 을 곱한 수를 표의 두 제곱 사이에 끼워 $\\sqrt7$ 의 범위를 구한다.","단계":[{"제목":"큰 수로 바꾸기","힌트":"$7$ 에 $1000^2$ 을 곱한 수의 제곱근은 $\\sqrt7$ 의 몇 배인가?","식":["$7000000=7\\times1000^2$","$\\sqrt{7000000}=1000\\sqrt7$"],"설명":"제곱표의 값이 일곱 자리 수이므로 $7$ 에 $1000^2$ 을 곱해 같은 자릿수로 맞춘다.","확인":null,"스킬":"N7","고비":true},{"제목":"표에 끼우기","힌트":"표의 값 중 $7000000$ 을 사이에 두는 두 제곱은?","식":["$2645^2=6996025<7000000<7001316=2646^2$","$2645<1000\\sqrt7<2646$"],"설명":"제곱한 값의 대소는 제곱근의 대소와 같다.","확인":null,"스킬":"N7"},{"제목":"소수 셋째 자리","힌트":"$1000$ 으로 나누면 $\\sqrt7$ 은 어떤 두 소수 사이에 있는가?","식":["$2.645<\\sqrt7<2.646$"],"설명":"$\\sqrt7=2.645\\cdots$ 이므로 소수 셋째 자리의 수는 $5$ 이다.","확인":"5","스킬":"N7"}],"fb":"fig/ns/"},"ns-2cae99619838":{"길":"한 식을 인수분해해 공통인수 후보를 정하고 후보별로 $k$ 를 구해 곱한다.","단계":[{"제목":"인수분해","힌트":"$x^2-2x-8$ 을 인수분해하면?","식":["$x^2-2x-8=(x-4)(x+2)$"],"설명":"곱이 $-8$ 이고 합이 $-2$ 인 두 수는 $-4$ 와 $2$ 이다.","확인":null,"스킬":"A2"},{"제목":"공통인수 후보 나누기","힌트":"공통인수가 될 수 있는 일차식은 무엇인가?","식":["$x-4$ 또는 $x+2$"],"설명":"두 식이 서로 다르므로 공통인수는 일차식 하나이고, 위 두 가지 경우로 나눈다.","확인":null,"스킬":"C2","고비":true},{"제목":"$x-4$ 가 공통인수인 경우","힌트":"다른 식을 $(x-4)(x+m)$ 이라 놓고 계수를 비교하면?","식":["$k+1=4-m,\\ -4m=k+6$","$4k-12=k+6$","$k=6$"],"설명":"첫째 식에서 $m=3-k$ 이고 이를 둘째 식에 넣는다.","확인":null,"스킬":"A3"},{"제목":"$x+2$ 가 공통인수인 경우","힌트":"다른 식을 $(x+2)(x+n)$ 이라 놓고 계수를 비교하면?","식":["$k+1=-2-n,\\ 2n=k+6$","$-2k-6=k+6$","$k=-4$"],"설명":"첫째 식에서 $n=-k-3$ 이고 이를 둘째 식에 넣는다.","확인":null,"스킬":"A3"},{"제목":"$k$ 값의 곱","힌트":"가능한 $k$ 값의 곱은?","식":["$6\\times(-4)=-24$"],"설명":"두 경우에서 구한 $k$ 를 곱한다.","확인":"-24","스킬":"A3"}],"fb":"fig/ns/"},"ns-2e55ccc61c1d":{"길":"두 근을 문자로 놓고 조건으로 값을 정한 뒤 근과 계수의 관계로 $p$, $q$ 를 구한다.","단계":[{"제목":"두 근 구하기","힌트":"연속하는 두 양의 정수 근을 $n$, $n+1$ 로 놓고 제곱의 차가 $13$ 이라는 조건을 식으로 쓰면?","식":["$(n+1)^2-n^2=13$","$2n+1=13$","$n=6$"],"설명":"두 근은 $6$ 과 $7$ 이다.","확인":null,"스킬":"C7","고비":true},{"제목":"방정식 복원","힌트":"두 근이 $6$, $7$ 인 이차방정식은?","식":["$(x-6)(x-7)=0$","$x^2-13x+42=0$"],"설명":"$x^2$ 의 계수가 $1$ 이므로 $x^2+px+q=0$ 과 계수를 비교한다.","확인":null,"스킬":"A2"},{"제목":"$p+q$ 구하기","힌트":"$p+q$ 는?","식":["$p=-13,\\ q=42$","$p+q=29$"],"설명":"계수를 비교해 $p$, $q$ 를 읽고 더한다.","확인":"29","스킬":"A2"}],"fb":"fig/ns/"},"ns-30402c88756a":{"길":"평균과 편차를 구해 선지를 하나씩 확인한다.","단계":[{"제목":"평균 확인","힌트":"두 선수의 $2$라운드 평균을 구하면?","식":["$\\mathrm{A}:\\ \\frac{10+8+8+10+9}{5}=9$","$\\mathrm{B}:\\ \\frac{8+8+6+6+7}{5}=7$"],"설명":"평균이 각각 $9$, $7$ 이므로 ①, ② 는 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"A 의 분산 비교","힌트":"$\\mathrm{A}$ 의 $1$, $2$라운드 편차를 각각 구해 분산을 비교하면?","식":["$1\\text{라운드 편차}:\\ 1,-1,-1,1,0$","$2\\text{라운드 편차}:\\ 1,-1,-1,1,0$","$\\frac{1^2+(-1)^2+(-1)^2+1^2+0^2}{5}=0.8$"],"설명":"두 라운드의 편차가 같아 분산이 둘 다 $0.8$ 이므로 표준편차도 같다. ③ 은 옳다.","확인":null,"스킬":"C3","고비":true},{"제목":"B 의 분산 비교","힌트":"$\\mathrm{B}$ 의 $1$, $2$라운드 편차를 각각 구해 분산을 비교하면?","식":["$1\\text{라운드 편차}:\\ 1,1,-1,-1,0$","$2\\text{라운드 편차}:\\ 1,1,-1,-1,0$","$\\text{분산은 둘 다 }0.8$"],"설명":"두 라운드의 분산이 같으므로 $2$라운드가 더 작다는 ④ 는 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"평균 점수의 합","힌트":"두 선수의 $1$, $2$라운드 평균의 합을 구하면?","식":["$\\mathrm{A}:\\ 8+9=17$","$\\mathrm{B}:\\ 9+7=16$"],"설명":"$\\mathrm{B}$ 가 더 작으므로 ⑤ 는 옳지 않고, 옳은 것은 ③ 이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-32eaa20f0a31":{"길":"구간별로 $\\mathrm{A}$ 를 식으로 정리한 뒤 보기 네 개를 대조한다.","단계":[{"제목":"근호 벗기는 규칙","힌트":"$\\sqrt{(x-3)^2}$ 은 $x-3$ 의 부호에 따라 어떻게 벗겨지는가?","식":["$x\\ge3$ 이면 $\\sqrt{(x-3)^2}=x-3$, $x<3$ 이면 $\\sqrt{(x-3)^2}=-x+3$","$x\\ge-3$ 이면 $\\sqrt{(x+3)^2}=x+3$, $x<-3$ 이면 $\\sqrt{(x+3)^2}=-x-3$"],"설명":"제곱의 밑이 $0$ 이상이면 그대로, 음수이면 부호를 바꿔 근호를 벗긴다.","확인":null,"스킬":"C2"},{"제목":"구간별 $\\mathrm{A}$","힌트":"$x\\ge3$, $-3\\le x<3$, $x<-3$ 에서 $\\mathrm{A}$ 는 각각 어떤 식인가?","식":["$x\\ge3:\\ \\mathrm{A}=(x-3)-(x+3)=-6$","$-3\\le x<3:\\ \\mathrm{A}=(-x+3)-(x+3)=-2x$","$x<-3:\\ \\mathrm{A}=(-x+3)-(-x-3)=6$"],"설명":"경계 $x=3$ 과 $x=-3$ 에서 두 근호 안 제곱의 밑의 부호가 바뀐다.","확인":null,"스킬":"C2","고비":true},{"제목":"보기 판별","힌트":"구간별 식으로 ㄱ~ㄹ 을 하나씩 확인하면?","식":["$\\text{ㄱ 참, ㄴ 거짓, ㄷ 거짓, ㄹ 참}$"],"설명":"ㄱ 은 $-2x=0$ 에서 $x=0$ 이고 다른 구간에서는 $\\mathrm{A}=\\pm6$ 이라 $0$ 이 아니므로 참이다. ㄴ 은 $\\mathrm{A}=-6$, ㄷ 은 $\\mathrm{A}=6$ 이어서 보기의 값과 부호가 반대이므로 거짓이다. ㄹ 은 $\\mathrm{A}=-2x$ 이므로 참이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-331408024b14":{"길":"$a$ 는 완전제곱으로, $b$ 는 각 인수를 곱의 꼴로 바꿔 약분되는 규칙을 찾는다.","단계":[{"제목":"$a$ 의 값","힌트":"근호 안은 어떤 수의 제곱인가?","식":["$396^2+2\\times396\\times4+4^2=(396+4)^2$","$a=400$"],"설명":"$8\\times396=2\\times396\\times4$ 이고 $16=4^2$ 이다.","확인":"400","스킬":"A6"},{"제목":"각 인수 분해","힌트":"$1-\\frac1{n^2}$ 을 통분해 분자를 인수분해하면?","식":["$1-\\frac1{n^2}=\\frac{n^2-1}{n^2}=\\frac{(n-1)(n+1)}{n^2}$"],"설명":"$n=2,3,\\cdots,15$ 의 각 인수에 합차 공식을 쓴다.","확인":null,"스킬":"A6"},{"제목":"곱의 약분","힌트":"$n=2$ 부터 $15$ 까지 곱을 나열하면 어떤 수끼리 약분되는가?","식":["$\\frac{1\\times3}{2\\times2}\\times\\frac{2\\times4}{3\\times3}\\times\\cdots\\times\\frac{14\\times16}{15\\times15}=\\frac12\\times\\frac{16}{15}$"],"설명":"각 항의 분자 $n-1$ 은 앞 항의 분모에, 분자 $n+1$ 은 뒤 항의 분모에 있는 같은 수와 약분되어 첫 항의 $\\frac12$ 과 끝 항의 $\\frac{16}{15}$ 만 남는다.","확인":null,"스킬":"P6","고비":true},{"제목":"$b$ 와 $\\frac ab$","힌트":"$b=15\\times\\frac12\\times\\frac{16}{15}$ 를 계산하고 $\\frac ab$ 를 구하면?","식":["$b=15\\times\\frac12\\times\\frac{16}{15}=8$","$\\frac ab=\\frac{400}{8}=50$"],"설명":"앞에서 구한 $a=400$ 을 $b$ 로 나눈다.","확인":"50","스킬":"P6"}],"fb":"fig/ns/"},"ns-371a733c1fd7":{"길":"조건에서 x-y 가 일정한 값임을 읽고, 그 값으로 나눈 x-y 를 곱해 합차 공식을 계속 적용한다","단계":[{"제목":"조건을 x-y 로 나타내기","힌트":"$y=x-16$ 을 $x$, $y$ 의 차로 나타내면 어떤 식이 될까?","식":["$x-y=16$"],"설명":"$y=x-16$ 을 이항하면 $x-y$ 가 상수가 된다.","확인":"16","스킬":"A3","고비":false},{"제목":"합차 공식이 이어지도록 식 변형","힌트":"곱 앞에 $x-y$ 를 만들려면 어떤 수를 곱해야 할까?","식":["$(x+y)(x^2+y^2)(x^4+y^4)=\\frac{1}{16}(x-y)(x+y)(x^2+y^2)(x^4+y^4)$"],"설명":"$x-y=16$ 이므로 $\\frac{1}{16}(x-y)=1$ 이다. 이 값을 곱해도 식의 값은 변하지 않는다.","확인":null,"스킬":"A3","고비":true},{"제목":"합차 공식 연달아 적용","힌트":"$(x-y)(x+y)$ 를 계산한 뒤 다음 인수와 묶으면 어떤 식이 이어질까?","식":["$\\frac{1}{16}(x^2-y^2)(x^2+y^2)(x^4+y^4)$","$\\frac{1}{16}(x^4-y^4)(x^4+y^4)$","$\\frac{1}{16}(x^8-y^8)$"],"설명":"합차 공식 $(p-q)(p+q)=p^2-q^2$ 을 세 번 차례로 쓴다.","확인":null,"스킬":"A3","고비":false},{"제목":"a, b 비교","힌트":"$\\frac{1}{16}(x^8-y^8)$ 을 $a(x^b-y^b)$ 와 비교하면 $a$, $b$ 는?","식":["$a=\\frac{1}{16},\\ b=8$"],"설명":"계수가 $a$, 지수가 $b$ 이다.","확인":null,"스킬":"A3","고비":false},{"제목":"ab 계산","힌트":"구한 $a$, $b$ 를 곱하면?","식":["$ab=\\frac{1}{16}\\times8=\\frac{1}{2}$"],"설명":"$a$ 와 $b$ 의 곱을 구한다.","확인":"1/2","스킬":"A3","고비":false}],"fb":"fig/ns/"},"ns-38205cdd366e":{"길":"접선과 현이 이루는 각을 원주각으로 옮기고, 지름을 그어 만든 직각삼각형에서 삼각비를 쓴다","단계":[{"제목":"접선과 현이 이루는 각의 성질","힌트":"접선과 현 $\\mathrm{AB}$ 가 이루는 각은 그 현에 대한 어떤 각과 같을까?","식":[],"설명":"접선과 현이 이루는 각의 크기는 그 현이 끊는 호에 대한 원주각의 크기와 같다. 호 $\\mathrm{AB}$ 에 대한 원주각은 $42^\\circ$ 이다.","확인":null,"스킬":"S5","고비":false},{"제목":"지름으로 직각삼각형 만들기","힌트":"현 $\\mathrm{AB}$ 를 한 변으로 하는 직각삼각형을 만들려면 점 $\\mathrm{A}$ 에서 어떤 선을 그을까?","식":["$\\angle\\mathrm{ABC'}=90^\\circ$","$\\overline{\\mathrm{AC'}}=10$"],"설명":"점 $\\mathrm{A}$ 에서 원의 중심 $\\mathrm{O}$ 를 지나는 지름을 그어 원과 만나는 다른 끝점을 $\\mathrm{C'}$ 이라 한다. 지름에 대한 원주각은 $90^\\circ$ 이고 지름의 길이는 반지름의 $2$ 배이다.","확인":null,"스킬":"S2","고비":true},{"제목":"같은 호의 원주각","힌트":"$\\angle\\mathrm{AC'B}$ 는 호 $\\mathrm{AB}$ 에 대한 원주각 중 어느 값과 같을까?","식":["$\\angle\\mathrm{AC'B}=42^\\circ$"],"설명":"한 호에 대한 원주각은 모두 같다. $\\mathrm{C'}$ 도 호 $\\mathrm{AB}$ 에 대한 원주각의 꼭짓점이다.","확인":null,"스킬":"S5","고비":false},{"제목":"삼각비로 현의 길이 구하기","힌트":"직각삼각형 $\\mathrm{ABC'}$ 에서 빗변과 $\\overline{\\mathrm{AB}}$ 사이의 삼각비는?","식":["$\\sin 42^\\circ=\\frac{\\overline{\\mathrm{AB}}}{10}$","$\\overline{\\mathrm{AB}}=10\\sin 42^\\circ$"],"설명":"$\\angle\\mathrm{C'}$ 의 대변이 $\\overline{\\mathrm{AB}}$ 이고 빗변이 $\\overline{\\mathrm{AC'}}$ 이므로 사인을 쓴다.","확인":null,"스킬":"S6","고비":false}],"fb":"fig/ns/"},"ns-3ae7d83ab238":{"길":"빠진 두 점수를 넣은 평균을 식으로 쓰고, 중앙값은 자료가 놓인 위치로 판단한다","단계":[{"제목":"평균 식 세우기","힌트":"전체 학생 수를 $x$ 로 놓고 두 학생을 포함한 평균을 어떻게 나타낼까?","식":["$\\frac{60(x-2)+40+90}{x}=60+\\frac{10}{x}$"],"설명":"두 학생을 뺀 $x-2$ 명의 점수 합은 $60(x-2)$ 이고, $40$ 점과 $90$ 점을 더해 $x$ 로 나눈다.","확인":null,"스킬":"C7","고비":false},{"제목":"평균 비교","힌트":"$\\frac{10}{x}$ 의 부호는?","식":["$\\frac{10}{x}>0$"],"설명":"학생 수 $x$ 는 양수이므로 평균은 $60$ 점보다 크다.","확인":null,"스킬":"C7","고비":false},{"제목":"중앙값 변화 판단","힌트":"$40$ 점은 원래 중앙값 $50$ 점보다 작고 $90$ 점은 더 크다. 두 점수를 넣으면 가운데 값의 위치가 달라질까?","식":[],"설명":"중앙값보다 작은 점수 하나와 큰 점수 하나가 늘어나므로 가운데 자료의 위치는 그대로이다. 학생 수가 홀수이므로 중앙값은 $50$ 점이다. 따라서 평균은 $60$ 점보다 크고 중앙값은 $50$ 점이다.","확인":null,"스킬":"C7","고비":true}],"fb":"fig/ns/"},"ns-3b6a93e0db73":{"길":"제곱근 안이 제곱이므로 절댓값으로 바꾸고, 보기의 범위마다 부호를 정해 식을 정리한다","단계":[{"제목":"절댓값으로 바꾸기","힌트":"$\\sqrt{p^2}$ 은 $p$ 의 부호에 따라 어떻게 쓸까?","식":["$A=|x-4|-|x+4|$"],"설명":"$\\sqrt{p^2}=|p|$ 이므로 두 근호를 절댓값으로 바꾼다.","확인":null,"스킬":"C2","고비":false},{"제목":"범위별 부호 판단","힌트":"각 보기의 범위에서 $x-4$ 와 $x+4$ 는 양수일까 음수일까?","식":["$x<-4:\\ x-4<0,\\ x+4<0$","$-4<x<1:\\ x-4<0,\\ x+4>0$","$x>4:\\ x-4>0,\\ x+4>0$"],"설명":"범위마다 두 식의 부호를 정해야 절댓값을 벗길 수 있다.","확인":null,"스킬":"C2","고비":true},{"제목":"범위별 A 정리","힌트":"부호에 맞게 절댓값을 벗기고 정리하면 각 범위에서 $A$ 는?","식":["$x<-4:\\ A=-(x-4)+(x+4)=8$","$-4<x<1:\\ A=-(x-4)-(x+4)=-2x$","$x>4:\\ A=(x-4)-(x+4)=-8$"],"설명":"음수인 식은 부호를 바꿔 벗긴다.","확인":null,"스킬":"C2","고비":false},{"제목":"옳은 보기 고르기","힌트":"ㄱ, ㄴ, ㄷ 중 계산 결과와 일치하는 것은?","식":["$A=-8\\neq0$"],"설명":"ㄱ 과 ㄴ 은 보기와 같다. ㄷ 은 $x>4$ 일 때 $A=-8$ 이어서 $0$ 이 아니다. 따라서 옳은 것은 ㄱ, ㄴ 이다.","확인":null,"스킬":"C3","고비":false}],"fb":"fig/ns/"},"ns-3bfe43776b4e":{"길":"보기마다 주어진 조건을 방정식에 대입해 판별식 부호와 근을 확인한다","단계":[{"제목":"보기 ① 판별식","힌트":"$a=-2$ 를 대입한 이차방정식의 판별식 부호는?","식":["$x^2-4x+6=0$","$D=(-4)^2-4\\cdot1\\cdot6=-8<0$"],"설명":"$D<0$ 이므로 실근이 없다. 따라서 ①은 틀리다.","확인":null,"스킬":"G2","고비":false},{"제목":"보기 ②, ④ 근 대입","힌트":"한 근이 주어진 보기는 그 값을 대입해 $a$ 를 구하면?","식":["$x=1:\\ 1+2a-3a=0,\\ a=1$","$x=2:\\ 4+4a-3a=0,\\ a=-4$"],"설명":"②는 $a=1$ 일 때 $x^2+2x-3=0$ 의 다른 근이 $-3$ 이므로 틀리다. ④는 $a=-4$ 이므로 틀리다.","확인":null,"스킬":"A12","고비":false},{"제목":"보기 ③ 중근 확인","힌트":"$a=-3$ 을 대입하면 좌변이 완전제곱식이 될까?","식":["$x^2-6x+9=(x-3)^2=0$"],"설명":"중근 $x=3$ 을 가지므로 ③이 옳다.","확인":null,"스킬":"G2","고비":true},{"제목":"보기 ⑤ 판별식","힌트":"$a=1$ 일 때 판별식 부호는?","식":["$x^2+2x-3=0$","$D=2^2-4\\cdot1\\cdot(-3)=16>0$"],"설명":"서로 다른 두 실근이 있으므로 ⑤는 틀리다. 따라서 옳은 것은 ③이다.","확인":null,"스킬":"G2","고비":false}],"fb":"fig/ns/"},"ns-3effbae66b80":{"길":"곱을 합차 공식으로 바꾼 뒤 근호 안이 100 의 배수이면서 제곱수가 되는 a 를 먼저 정한다","단계":[{"제목":"곱셈공식으로 바꾸기","힌트":"$996$ 과 $1004$ 를 $1000$ 을 기준으로 나타내면?","식":["$996\\times1004=(1000-4)(1000+4)=1000^2-16$"],"설명":"합차 공식 $(p-q)(p+q)=p^2-q^2$ 을 쓴다.","확인":null,"스킬":"A6","고비":false},{"제목":"a 의 값 확정","힌트":"근호 안이 $100$ 의 배수이면서 제곱수가 되도록 $-20<a<20$ 에서 $a$ 를 고르면?","식":["$1000^2-16+a=1000^2$","$a=16$"],"설명":"$10b^2$ 은 $10$ 의 배수이므로 근호 안은 $100$ 의 배수이고 제곱수이다. $-20<a<20$ 에서 $1000^2-16+a$ 가 $100$ 의 배수인 $a$ 는 $16$ 뿐이고, 그때 $1000^2$ 이므로 제곱수이다.","확인":"16","스킬":"N8","고비":true},{"제목":"b 구하기","힌트":"$\\sqrt{1000^2}=1000$ 이므로 $10b^2=1000$ 에서 $b$ 는?","식":["$10b^2=1000$","$b^2=100,\\ b=\\pm10$"],"설명":"$b$ 는 $-20<b<20$ 인 정수이므로 $10$ 과 $-10$ 이 모두 가능하다.","확인":null,"스킬":"N8","고비":false},{"제목":"a+b 의 최솟값","힌트":"$a+b$ 가 가장 작아지는 $b$ 의 값을 고르면?","식":["$a+b=16+(-10)=6$"],"설명":"$a=16$ 이므로 $b=-10$ 일 때 가장 작다.","확인":"6","스킬":"N8","고비":false}],"fb":"fig/ns/"},"ns-415a161ae438":{"길":"근호 안을 합의 제곱 꼴로 고쳐 근호를 벗긴다","단계":[{"제목":"258 을 쪼개기","힌트":"근호 안이 $p^2+2pq+q^2$ 꼴이 되도록 $258$ 을 $\\frac{1}{256}$ 과 어울리게 나누면?","식":["$258+\\frac{1}{256}=256+2+\\frac{1}{256}$"],"설명":"$256=16^2$ 이고 $\\frac{1}{256}=\\left(\\frac{1}{16}\\right)^2$ 이므로 가운데 항이 $2\\times16\\times\\frac{1}{16}=2$ 가 되도록 $258=256+2$ 로 쪼갠다.","확인":null,"스킬":"A6","고비":true},{"제목":"완전제곱식으로 묶기","힌트":"합의 제곱 공식 $(p+q)^2$ 으로 묶으면?","식":["$16^2+2\\times16\\times\\frac{1}{16}+\\left(\\frac{1}{16}\\right)^2=\\left(16+\\frac{1}{16}\\right)^2$"],"설명":"$(p+q)^2=p^2+2pq+q^2$ 이다.","확인":null,"스킬":"A6","고비":false},{"제목":"근호 벗기기","힌트":"$16+\\frac{1}{16}$ 을 한 분수로 나타낸 뒤 근호를 벗기면?","식":["$16+\\frac{1}{16}=\\frac{257}{16}$","$\\sqrt{\\left(\\frac{257}{16}\\right)^2}=\\frac{257}{16}$"],"설명":"양수의 제곱의 제곱근은 그 수 자신이다.","확인":null,"스킬":"A6","고비":false},{"제목":"b-a 구하기","힌트":"$\\frac{b}{a}$ 와 비교해 서로소인 $a$, $b$ 를 정하면?","식":["$a=16,\\ b=257$","$b-a=241$"],"설명":"$257$ 과 $16$ 은 서로소이다.","확인":"241","스킬":"A6","고비":false}],"fb":"fig/ns/"},"ns-42fa48bdae50":{"길":"근호 안이 제곱수가 되는 조건으로 √3a 의 후보를 정하고 경우마다 b 가 자연수인지 확인한다","단계":[{"제목":"√(3a) 의 후보","힌트":"$\\sqrt{3a}$ 가 자연수가 되려면 어떤 수여야 하고, 합이 $12$ 이므로 얼마 미만일까?","식":["$\\sqrt{3a}=3,\\ 6,\\ 9$"],"설명":"$3a$ 가 자연수의 제곱이 되려면 그 자연수가 $3$ 의 배수여야 한다. 합이 $12$ 이므로 $12$ 미만인 $3$, $6$, $9$ 가 후보이다.","확인":null,"스킬":"N8","고비":false},{"제목":"경우별 2b 구하기","힌트":"각 경우에 $\\sqrt{2b}=12-\\sqrt{3a}$ 이므로 $2b$ 는?","식":["$\\sqrt{3a}=3:\\ 2b=81$","$\\sqrt{3a}=6:\\ 2b=36$","$\\sqrt{3a}=9:\\ 2b=9$"],"설명":"$\\sqrt{2b}$ 를 구해 제곱한다.","확인":null,"스킬":"C2","고비":true},{"제목":"자연수 조건 확인","힌트":"각 경우에서 $a$, $b$ 가 모두 자연수인지 확인하면?","식":["$a=3,\\ b=\\frac{81}{2}$","$a=12,\\ b=18$","$a=27,\\ b=\\frac{9}{2}$"],"설명":"$b$ 가 자연수가 아닌 첫째와 셋째 경우는 버린다.","확인":null,"스킬":"C2","고비":false},{"제목":"순서쌍의 개수","힌트":"조건을 만족하는 순서쌍은 모두 몇 개일까?","식":["$(a,\\,b)=(12,\\,18)$"],"설명":"조건을 만족하는 순서쌍은 한 개이다.","확인":"1","스킬":"N8","고비":false}],"fb":"fig/ns/"},"ns-42ff315c1e3d":{"길":"각 수를 유리수와 무리수로 먼저 나눈 뒤 보기마다 해당하는 개수를 센다","단계":[{"제목":"수 분류","힌트":"근호 안이 제곱수인 수와 순환소수는 어떤 수일까?","식":["$3.\\dot1\\dot4=\\frac{311}{99}$","$\\sqrt{\\left(-\\frac{3}{2}\\right)^2}=\\frac{3}{2}$","$\\sqrt9-\\sqrt4=1$"],"설명":"이 세 수는 유리수이다. 나머지 $\\sqrt{\\frac{1}{10}}$, $-\\sqrt7$, $-\\sqrt{2.5}$, $-\\sqrt6+1$, $\\sqrt{12}$ 는 무리수이다.","확인":null,"스킬":"N6","고비":false},{"제목":"보기 ① ② ③ 확인","힌트":"무리수의 개수, $3$ 보다 큰 무리수, 정수가 아닌 유리수는 각각 몇 개일까?","식":["$\\sqrt{12}>\\sqrt9=3$"],"설명":"무리수는 $5$ 개이므로 ①은 틀리다. $3$ 보다 큰 무리수는 $\\sqrt{12}$ 하나뿐이라 ②도 틀리다. 정수가 아닌 유리수는 $3.\\dot1\\dot4$ 와 $\\frac{3}{2}$ 두 개이므로 ③도 틀리다.","확인":null,"스킬":"N8","고비":false},{"제목":"보기 ④ 범위 판단","힌트":"$-\\sqrt6+1$ 은 어느 두 정수 사이에 있을까?","식":["$2<\\sqrt6<3$","$-2<-\\sqrt6+1<-1$"],"설명":"$-2=-\\sqrt4$ 와 $0$ 사이의 무리수는 $-\\sqrt{2.5}$ 와 $-\\sqrt6+1$ 두 개이므로 ④가 옳다.","확인":null,"스킬":"N8","고비":true},{"제목":"보기 ⑤ 확인","힌트":"$\\sqrt{20}$ 은 어느 두 정수 사이에 있을까?","식":["$4<\\sqrt{20}<5$"],"설명":"$-\\sqrt6+1$ 과 $\\sqrt{20}$ 사이의 자연수는 $1$, $2$, $3$, $4$ 네 개이므로 ⑤는 틀리다. 따라서 옳은 것은 ④이다.","확인":null,"스킬":"N8","고비":false}],"fb":"fig/ns/"},"ns-48845f951ad1":{"길":"첫 방정식의 중근 조건으로 m 과 a 를 구하고, a 를 둘째 방정식에 대입해 k 와 b 를 구한다","단계":[{"제목":"중근 조건으로 m 구하기","힌트":"우변의 $17x$ 를 이항해 정리하면 판별식은 어떻게 쓰일까?","식":["$2x^2-12x+m=0$","$(-12)^2-4\\cdot2\\cdot m=0$","$m=18$"],"설명":"중근을 가지면 판별식이 $0$ 이다.","확인":"18","스킬":"G2","고비":false},{"제목":"중근 a 구하기","힌트":"$m$ 을 대입한 식을 완전제곱식으로 나타내면?","식":["$x^2-6x+9=(x-3)^2=0$","$a=3$"],"설명":"양변을 $2$ 로 나눈 뒤 완전제곱식으로 묶는다.","확인":"3","스킬":"A6","고비":false},{"제목":"k 구하기","힌트":"$x^2-x-k=0$ 의 한 근이 $a$ 이므로 대입하면?","식":["$3^2-3-k=0$","$k=6$"],"설명":"근을 방정식에 대입하면 등식이 성립한다.","확인":"6","스킬":"A12","고비":true},{"제목":"다른 근 b 구하기","힌트":"$k$ 를 대입한 이차방정식을 인수분해하면 $a$ 말고 어떤 근이 나올까?","식":["$x^2-x-6=(x-3)(x+2)=0$","$b=-2$"],"설명":"근은 $3$ 과 $-2$ 이다.","확인":"-2","스킬":"A12","고비":false},{"제목":"값 계산","힌트":"구한 값들을 $a-b+m+k$ 에 넣으면?","식":["$a-b+m+k=3-(-2)+18+6=29$"],"설명":"$a=3$, $b=-2$, $m=18$, $k=6$ 을 대입한다.","확인":"29","스킬":"A12","고비":false}],"fb":"fig/ns/"},"ns-4fc35c4b9c58":{"길":"조건에서 a, b 의 부호를 읽고, 근호 안 식의 부호에 맞게 근호를 벗긴다","단계":[{"제목":"조건에서 부호 읽기","힌트":"$\\sqrt{p^2}$ 이 $p$ 와 같으려면, $-p$ 와 같으려면 $p$ 의 부호는?","식":["$a\\ge0$","$b\\le0$"],"설명":"$\\sqrt{p^2}=|p|$ 이다. $\\sqrt{(-a)^2}=|a|=a$ 이므로 $a\\ge0$, $\\sqrt{b^2}=|b|=-b$ 이므로 $b\\le0$ 이다.","확인":null,"스킬":"N5","고비":true},{"제목":"근호 벗기기","힌트":"$3a$, $-4b$, $-a+b$ 의 부호를 따져 근호를 벗기면?","식":["$\\sqrt{9a^2}=3a$","$\\sqrt{(-4b)^2}=-4b$","$\\sqrt{(-a+b)^2}=a-b$"],"설명":"$3a\\ge0$, $-4b\\ge0$, $-a+b\\le0$ 이므로 앞의 두 식은 그대로, 마지막 식은 부호를 바꿔 낸다.","확인":null,"스킬":"N5","고비":false},{"제목":"식 정리","힌트":"벗긴 식을 더하고 빼서 정리하면?","식":["$3a-4b-(a-b)=2a-3b$"],"설명":"괄호를 풀고 동류항끼리 정리한다.","확인":null,"스킬":"N5","고비":false}],"fb":"fig/ns/"},"ns-5155534255bf":{"길":"한 근을 대입해 a 를 정하고, 다른 근 b 를 구해 거듭제곱의 일의 자리 규칙을 쓴다","단계":[{"제목":"한 근 대입","힌트":"$x=2$ 를 대입한 식을 $a$ 에 대한 방정식으로 정리하면?","식":["$4(a-1)-2(a^2+1)+2(a+1)=0$","$a^2-3a+2=0$"],"설명":"근의 뜻에 따라 $x=2$ 를 대입한다.","확인":null,"스킬":"A12","고비":false},{"제목":"a 확정","힌트":"이차방정식이 되려면 $x^2$ 의 계수는 어떤 조건을 만족해야 할까?","식":["$(a-1)(a-2)=0$","$a=2$"],"설명":"$a=1$ 이면 $x^2$ 의 계수가 $0$ 이 되어 이차방정식이 아니므로 $a=2$ 이다.","확인":"2","스킬":"A12","고비":false},{"제목":"다른 근 b 구하기","힌트":"$a$ 를 대입한 이차방정식을 인수분해하면 다른 근은?","식":["$x^2-5x+6=0$","$(x-2)(x-3)=0$","$b=3$"],"설명":"근은 $2$ 와 $3$ 이므로 다른 근은 $3$ 이다.","확인":"3","스킬":"A12","고비":false},{"제목":"일의 자리 규칙","힌트":"$3$ 을 거듭제곱할 때 일의 자리 숫자는 어떤 순서로 되풀이될까?","식":["$3,\\ 9,\\ 7,\\ 1,\\ 3,\\ \\cdots$"],"설명":"일의 자리는 $3,9,7,1$ 이 네 번마다 되풀이된다. $2018=4\\times504+2$ 이므로 $3^{2018}$ 의 일의 자리는 두 번째 수와 같다.","확인":"9","스킬":"N3","고비":true}],"fb":"fig/ns/"},"ns-6117ab7ed7d7":{"길":"소수 부분을 정수 부분을 뺀 식으로 나타내 근호를 없앤 뒤 일의 자리만 따진다","단계":[{"제목":"정수 부분 찾기","힌트":"$\\sqrt{n^2+1}$ 은 어떤 두 연속한 자연수 사이에 있을까?","식":["$n^2<n^2+1<(n+1)^2$","$n<\\sqrt{n^2+1}<n+1$"],"설명":"정수 부분이 $n$ 이므로 소수 부분은 $\\sqrt{n^2+1}-n$ 이다.","확인":null,"스킬":"N7","고비":true},{"제목":"식 정리","힌트":"$A[2019]+2019$ 에서 소수 부분을 식으로 쓰면 무엇이 남을까?","식":["$\\left(A[2019]+2019\\right)^2=\\left(\\sqrt{2019^2+1}-2019+2019\\right)^2$","$=2019^2+1$"],"설명":"$-2019$ 와 $+2019$ 가 없어져 근호만 남는다.","확인":null,"스킬":"N7","고비":false},{"제목":"일의 자리 구하기","힌트":"$2019^2$ 의 일의 자리는 일의 자리 $9$ 를 제곱해 정해진다. 거기에 $1$ 을 더하면?","식":["$9^2=81$","$1+1=2$"],"설명":"$2019^2$ 의 일의 자리는 $1$ 이고 여기에 $1$ 을 더한다.","확인":"2","스킬":"N7","고비":false}],"fb":"fig/ns/"},"ns-61c1e00b55fe":{"길":"x+y 와 xy 를 구한 뒤 근호가 든 식을 합과 곱으로 나타내 대입한다","단계":[{"제목":"xy 구하기","힌트":"곱셈공식 $(x+y)^2=x^2+2xy+y^2$ 에서 $xy$ 를 구하면?","식":["$3^2=7+2xy$","$xy=1$"],"설명":"$x+y=3$, $x^2+y^2=7$ 을 대입한다.","확인":"1","스킬":"A2","고비":false},{"제목":"근호 식 변형","힌트":"$\\sqrt{\\frac{y}{x}}+\\sqrt{\\frac{x}{y}}$ 를 $x+y$ 와 $xy$ 로 나타내면?","식":["$\\sqrt{\\frac{y}{x}}+\\sqrt{\\frac{x}{y}}=\\frac{\\sqrt{xy}}{x}+\\frac{\\sqrt{xy}}{y}=\\frac{(x+y)\\sqrt{xy}}{xy}$"],"설명":"$xy=1>0$ 이고 $x+y=3>0$ 이므로 $x$, $y$ 는 모두 양수이다. 근호 안 분수의 분모를 유리화해 통분한다.","확인":null,"스킬":"A2","고비":true},{"제목":"값 대입","힌트":"$x+y$ 와 $xy$ 의 값을 대입하면?","식":["$\\frac{3\\times\\sqrt1}{1}=3$"],"설명":"$x+y=3$, $xy=1$ 을 넣는다.","확인":"3","스킬":"A2","고비":false}],"fb":"fig/ns/"},"ns-651a70b8dc05":{"길":"가능한 (a, b) 쌍을 모두 나열하고, 인수분해되는 쌍만 센다","단계":[{"제목":"쌍의 개수","힌트":"$a\\ne b$ 인 서로 다른 두 수를 순서 있게 고르면 모두 몇 쌍일까?","식":["$4\\times3=12$"],"설명":"네 수에서 $a$ 를 먼저 고르고 남은 세 수에서 $b$ 를 고른다.","확인":"12","스킬":"P4","고비":false},{"제목":"인수분해되는 쌍 찾기","힌트":"일차항의 계수가 $1$ 이 되도록 곱할 수 있는 쌍은 어떤 것일까?","식":["$-3x^2+x+4=(x+1)(-3x+4)$","$-x^2+x+6=(x+2)(-x+3)$","$4x^2+x-3=(4x-3)(x+1)$","$6x^2+x-1=(2x+1)(3x-1)$"],"설명":"쌍마다 곱셈공식으로 전개해 보면 위 네 쌍이 인수분해된다. 나머지 쌍은 인수분해되지 않는다.","확인":null,"스킬":"P4","고비":true},{"제목":"개수 세기","힌트":"인수분해되는 쌍은 모두 몇 개일까?","식":["$(a,\\,b)=(-3,\\,4),\\ (-1,\\,6),\\ (4,\\,-3),\\ (6,\\,-1)$"],"설명":"인수분해되는 쌍은 네 개이다.","확인":"4","스킬":"P4","고비":false}],"fb":"fig/ns/"},"ns-65bb5bc19308":{"길":"계수를 바꾼 방정식에 주어진 근을 대입해 a 를 구하고 다른 근을 인수분해로 구한다","단계":[{"제목":"바꾼 방정식 세우기","힌트":"일차항의 계수와 상수항을 서로 바꾸면 방정식은 어떻게 쓰일까?","식":["$x^2+3ax-2a=0$"],"설명":"원래 일차항 계수 $-2a$ 와 상수항 $3a$ 를 서로 바꾼다.","확인":null,"스킬":"C7","고비":true},{"제목":"a 구하기","힌트":"$x=-1$ 을 대입하면 $a$ 에 대한 식은?","식":["$1-3a-2a=0$","$a=\\frac{1}{5}$"],"설명":"근을 방정식에 대입하면 등식이 성립한다.","확인":"1/5","스킬":"A12","고비":false},{"제목":"다른 근 구하기","힌트":"$a$ 의 값을 대입한 이차방정식의 양변에 $5$ 를 곱해 인수분해하면?","식":["$x^2+\\frac{3}{5}x-\\frac{2}{5}=0$","$5x^2+3x-2=(x+1)(5x-2)=0$","$x=-1$ 또는 $x=\\frac{2}{5}$"],"설명":"다른 한 근은 $\\frac{2}{5}$ 이다.","확인":"2/5","스킬":"C7","고비":false}],"fb":"fig/ns/"},"ns-65d28584fbf7":{"길":"두 식을 각각 인수분해해 공통인수를 약분한다","단계":[{"제목":"A 인수분해","힌트":"$2019$ 를 $n$ 으로 놓으면 $A$ 는 $n$ 의 식으로 어떻게 쓰일까?","식":["$A=n(n+1)-2=n^2+n-2=(n+2)(n-1)$","$A=2021\\times2018$"],"설명":"$n=2019$ 를 대입해 다시 수로 나타낸다.","확인":null,"스킬":"A1","고비":true},{"제목":"B 인수분해","힌트":"$2018^2-9$ 는 어떤 공식으로 인수분해할까?","식":["$B=2018^2-3^2=(2018+3)(2018-3)=2021\\times2015$"],"설명":"합차 공식 $p^2-q^2=(p+q)(p-q)$ 를 쓴다.","확인":null,"스킬":"A1","고비":false},{"제목":"비 구하기","힌트":"공통인수 $2021$ 을 약분하면 $\\frac{A}{B}$ 는?","식":["$\\frac{A}{B}=\\frac{2021\\times2018}{2021\\times2015}=\\frac{2018}{2015}$"],"설명":"$A$ 는 $B$ 의 $\\frac{A}{B}$ 배이다.","확인":"2018/2015","스킬":"A1","고비":false}],"fb":"fig/ns/"},"ns-67ce5b1c91cf":{"길":"0<a<1 에서 네 수의 크기를 비교해 가장 큰 수와 가장 작은 수를 정한 뒤 곱한다","단계":[{"제목":"크기 비교","힌트":"$0<a<1$ 일 때 $a$ 와 $a^2$ 중 어느 것이 더 크고, $a$ 와 $\\sqrt{a}$ 는 어떨까?","식":["$a^2<a<\\sqrt{a}<1<\\sqrt{\\frac{1}{a}}$"],"설명":"$0<a<1$ 이면 $a^2<a<1$ 이고 $a^2<a$ 의 제곱근을 취하면 $a<\\sqrt{a}$ 이다. 또 $\\frac{1}{a}>1$ 이므로 $\\sqrt{\\frac{1}{a}}>1$ 이다.","확인":null,"스킬":"C9","고비":true},{"제목":"가장 큰 수와 가장 작은 수의 곱","힌트":"가장 큰 수와 가장 작은 수를 골라 곱하고 근호를 정리하면?","식":["$\\sqrt{\\frac{1}{a}}\\times a^2=\\frac{\\sqrt{a}}{a}\\times a^2=a\\sqrt{a}$"],"설명":"가장 큰 수는 $\\sqrt{\\frac{1}{a}}$, 가장 작은 수는 $a^2$ 이다. $\\sqrt{\\frac{1}{a}}=\\frac{\\sqrt{a}}{a}$ 로 분모를 유리화한다.","확인":null,"스킬":"C9","고비":false}],"fb":"fig/ns/"},"ns-72e70e403248":{"길":"양변에 합차 공식이 이어지도록 하는 수를 곱해 좌변을 3의 거듭제곱으로 만든 뒤, x의 범위로 x와 y를 정한다.","단계":[{"제목":"양변에 곱할 수 정하기","고비":true,"힌트":"연달아 곱셈공식이 쓰이도록 양변에 곱할 수는?","식":["$(9-3)(9+3)(9^{2}+3^{2})(9^{4}+3^{4})+3^{8}=6x\\times 3^{y}$"],"설명":"$(9+3)$ 앞에 $(9-3)$ 을 곱하면 합차 공식을 연달아 쓸 수 있다. 양변에 $9-3=6$ 을 곱하면 $\\frac{3^{7}}{2}$ 항은 $3^{8}$ 이 된다.","확인":null,"스킬":"A9"},{"제목":"합차 공식으로 좌변 정리","힌트":"합차 공식을 차례로 쓰면 좌변은 어떤 거듭제곱 꼴이 되나?","식":["$(9^{8}-3^{8})+3^{8}=9^{8}=3^{16}$"],"설명":"합차 공식 $(p-q)(p+q)=p^{2}-q^{2}$ 을 세 번 쓰면 $9^{8}-3^{8}$ 이 된다. 여기에 $3^{8}$ 을 더하면 $9^{8}=(3^{2})^{8}=3^{16}$ 이다.","확인":null,"스킬":"A9"},{"제목":"x와 y 정하기","힌트":"$3^{16}=6x\\times 3^{y}$ 에서 $6x$ 는 어떤 수의 꼴이어야 하고, 범위 안에서 가능한 값은?","식":["$3\\le 6x\\le 6$","$6x=3,\\ x=\\frac{1}{2},\\ y=15$"],"설명":"$6x=3^{16-y}$ 이므로 $6x$ 는 $3$ 의 거듭제곱이다. $3\\le 6x\\le 6$ 안의 $3$ 의 거듭제곱은 $3$ 뿐이므로 $6x=3$ 이다.","확인":null,"스킬":"N1"},{"제목":"$\\frac{y}{x}$ 계산","힌트":"구한 x, y 를 대입하면?","식":["$\\frac{y}{x}=\\frac{15}{\\frac{1}{2}}=30$"],"설명":"$x=\\frac{1}{2}$, $y=15$ 를 대입한다.","확인":"30","스킬":"A9"}],"fb":"fig/ns/"},"ns-75b4d5d9e0f7":{"길":"눈의 수가 모두 소수임을 이용해 가능한 인수분해 꼴을 두 가지로 줄이고, k의 값을 모두 비교한다.","단계":[{"제목":"인수분해 꼴 정하기","고비":true,"힌트":"$a$, $b$ 가 모두 소수일 때 두 일차식의 계수로 가능한 짝은?","식":["$k=ab+1$","$k=a+b$"],"설명":"$a$, $b$ 가 소수이므로 이차항 계수 $a$ 는 $a\\times 1$ 로만, 상수항 $b$ 는 $b\\times 1$ 로만 나뉜다. 따라서 $(ax+1)(x+b)$ 또는 $(ax+b)(x+1)$ 꼴뿐이다.","확인":null,"스킬":"N1"},{"제목":"k의 값 구하기","힌트":"$(a,\\,b)$ 로 가능한 쌍마다 두 경우의 $k$ 를 구하면?","식":["$(a,b)=(7,7)$ 일 때 $k=50$","$(a,b)=(2,2)$ 일 때 $k=4$"],"설명":"$2$, $3$, $5$, $7$ 에서 $a$, $b$ 를 고른 열 가지 쌍마다 $ab+1$ 과 $a+b$ 를 구한다. 가장 큰 값은 $a=b=7$ 일 때 $ab+1=50$, 가장 작은 값은 $a=b=2$ 일 때 $a+b=4$ 이다.","확인":null,"스킬":"P4"},{"제목":"최댓값과 최솟값의 차","힌트":"두 값의 차는?","식":["$50-4=46$"],"설명":"최댓값 $50$ 에서 최솟값 $4$ 를 뺀다.","확인":"46","스킬":"N1"}],"fb":"fig/ns/"},"ns-7af3295a1fc4":{"길":"근을 대입해 a+1/a 를 얻고, 주어진 식을 공통 인수로 묶어 제곱 꼴로 바꾼 뒤 곱셈공식 변형으로 값을 구한다.","단계":[{"제목":"a+1/a 구하기","고비":true,"힌트":"$a$ 가 근이므로 대입한 식의 양변을 $a$ 로 나누면 어떤 합이 생기나?","식":["$a^{2}-5a+1=0$","$a+\\frac{1}{a}=5$"],"설명":"$x=a$ 를 대입하면 $a^{2}-5a+1=0$ 이다. $a\\neq 0$ 이므로 양변을 $a$ 로 나눈다.","확인":null,"스킬":"A12"},{"제목":"주어진 식 묶기","힌트":"$a-\\frac{1}{a}$ 가 공통으로 보이도록 식을 바꾸면?","식":["$\\left(a-\\frac{1}{a}\\right)^{2}$"],"설명":"$a\\left(a-\\frac{1}{a}\\right)-\\frac{1}{a}\\left(a-\\frac{1}{a}\\right)$ 로 쓰면 $a-\\frac{1}{a}$ 가 공통 인수이다.","확인":null,"스킬":"A1"},{"제목":"곱셈공식 변형으로 값 구하기","힌트":"$\\left(a-\\frac{1}{a}\\right)^{2}$ 를 $a+\\frac{1}{a}$ 로 나타내려면?","식":["$\\left(a-\\frac{1}{a}\\right)^{2}=\\left(a+\\frac{1}{a}\\right)^{2}-4=21$"],"설명":"$a\\times\\frac{1}{a}=1$ 이므로 $(p-q)^{2}=(p+q)^{2}-4pq$ 에서 $pq=1$ 을 쓴다.","확인":"21","스킬":"A2"}],"fb":"fig/ns/"},"ns-7d3456230f40":{"길":"두 식을 빼서 공통근을 구하고, 계수 사이의 관계로 각 방정식의 나머지 근을 구해 더한다.","단계":[{"제목":"공통근 구하기","고비":true,"힌트":"공통인 근은 두 식을 모두 만족한다. 두 식을 빼면 어떤 식이 남나?","식":["$(-a+b)x=a-b$","$x=-1$"],"설명":"공통근을 $x$ 라 하면 두 식을 변끼리 뺀 식도 만족한다. 두 방정식이 서로 다르므로 $a\\neq b$ 이고 $x=-1$ 이다.","확인":null,"스킬":"A10"},{"제목":"계수의 관계","힌트":"공통근을 한 식에 대입하면?","식":["$2+a+b=0$","$b=-2-a$"],"설명":"$x=-1$ 을 $2x^{2}-ax+b=0$ 에 대입한다.","확인":null,"스킬":"A10"},{"제목":"두 방정식 인수분해","힌트":"$b=-2-a$ 를 각 식에 대입해 인수분해하면?","식":["$(2x-2-a)(x+1)=0$","$(2x+a)(x+1)=0$"],"설명":"공통근 $-1$ 이므로 $x+1$ 을 인수로 가진다. 나머지 근은 각각 $\\frac{2+a}{2}$ 와 $-\\frac{a}{2}$ 이다.","확인":null,"스킬":"A4"},{"제목":"나머지 두 근의 합","힌트":"공통근이 아닌 두 근을 더하면?","식":["$\\frac{2+a}{2}+\\left(-\\frac{a}{2}\\right)=1$"],"설명":"$a$ 가 소거되어 값이 하나로 정해진다.","확인":"1","스킬":"A2"}],"fb":"fig/ns/"},"ns-8c86493638d6":{"길":"호의 길이가 같으면 원주각이 같다는 성질로 같은 각을 찾고, 두 쌍의 각이 같으면 닮음임을 보기마다 확인한다.","단계":[{"제목":"보기 ㉠ 확인","힌트":"같은 길이의 호에 대한 원주각의 크기는 어떤 관계인가?","식":["$\\angle \\mathrm{BAC}=\\angle \\mathrm{CAD}$"],"설명":"$\\overset{\\frown}{\\mathrm{BC}}$ 에 대한 원주각 $\\angle \\mathrm{BAC}=\\angle \\mathrm{BDC}$, $\\overset{\\frown}{\\mathrm{CD}}$ 에 대한 원주각 $\\angle \\mathrm{CAD}=\\angle \\mathrm{CBD}$ 이다. 두 호의 길이가 같으므로 원주각도 같다. ㉠은 옳다.","확인":null,"스킬":"S5"},{"제목":"보기 ㉡ 확인","고비":true,"힌트":"$\\triangle \\mathrm{BCA}$ 와 $\\triangle \\mathrm{EDA}$ 에서 같은 각의 쌍을 찾으면?","식":["$\\angle \\mathrm{ACB}=\\angle \\mathrm{ADE}$","$\\angle \\mathrm{BAC}=\\angle \\mathrm{EAD}$","$\\triangle \\mathrm{BCA}\\sim\\triangle \\mathrm{EDA}$"],"설명":"같은 호 $\\mathrm{AB}$ 에 대한 원주각이므로 $\\angle \\mathrm{ACB}=\\angle \\mathrm{ADB}$ 이고, $\\mathrm{E}$ 가 $\\mathrm{AC}$ 위의 점이므로 $\\angle \\mathrm{EAD}=\\angle \\mathrm{CAD}$ 이다. ㉠에서 $\\angle \\mathrm{BAC}=\\angle \\mathrm{CAD}$ 이므로 $AA$ 닮음이다. ㉡은 옳다.","확인":null,"스킬":"S5"},{"제목":"보기 ㉢ 확인","힌트":"$\\triangle \\mathrm{ABE}$ 와 $\\triangle \\mathrm{DCE}$ 에서 같은 각의 쌍을 찾으면?","식":["$\\angle \\mathrm{ABE}=\\angle \\mathrm{DCE}$","$\\angle \\mathrm{BAE}=\\angle \\mathrm{CDE}$","$\\triangle \\mathrm{ABE}\\sim\\triangle \\mathrm{DCE}$"],"설명":"같은 호 $\\mathrm{AD}$ 에 대한 원주각이므로 $\\angle \\mathrm{ABD}=\\angle \\mathrm{ACD}$ 이고, 같은 호 $\\mathrm{BC}$ 에 대한 원주각이므로 $\\angle \\mathrm{BAC}=\\angle \\mathrm{BDC}$ 이다. $AA$ 닮음이다. ㉢은 옳다.","확인":null,"스킬":"S10"},{"제목":"보기 ㉣, ㉤ 판단","힌트":"주어진 조건만으로 두 보기가 항상 성립하는가?","식":["$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AC}}$, $\\angle \\mathrm{ABD}=\\angle \\mathrm{BAC}$ 는 성립하지 않는다"],"설명":"조건은 $\\overset{\\frown}{\\mathrm{BC}}=\\overset{\\frown}{\\mathrm{CD}}$ 하나뿐이라 점 $\\mathrm{A}$ 의 위치에 따라 변하는 ㉣, ㉤ 은 항상 성립하지 않는다. 따라서 옳은 것은 ㉠, ㉡, ㉢ 이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-8d82ad0efec4":{"길":"보기 세 개를 각각 인수분해 공식으로 계산해 참인지 확인한다.","단계":[{"제목":"보기 ㄱ 확인","힌트":"제곱의 차로 보이는 식을 곱셈공식으로 바꾸면?","식":["$16a^{2}-9b^{2}=(4a-3b)(4a+3b)$"],"설명":"$(4a)^{2}-(3b)^{2}$ 이므로 합차 공식과 같다. ㄱ은 옳다.","확인":null,"스킬":"C3"},{"제목":"보기 ㄴ 확인","힌트":"$a^{2}-b^{2}$ 을 인수분해해 $(a-b)$ 로 묶으면?","식":["$a^{2}-b^{2}-(a-b)(a+b-3)=3(a-b)=12$"],"설명":"$(a+b)(a-b)-(a-b)(a+b-3)=(a-b)\\{(a+b)-(a+b-3)\\}$ 이고 $a-b=4$ 를 대입하면 $12$ 이다. 보기는 $-12$ 라 했으므로 ㄴ은 틀리다.","확인":null,"스킬":"C3"},{"제목":"보기 ㄷ 확인","고비":true,"힌트":"이웃한 두 제곱을 짝지어 합차 공식을 쓰면?","식":["$(3^{2}-1^{2})+(7^{2}-5^{2})+(11^{2}-9^{2})+(15^{2}-13^{2})=128$"],"설명":"앞의 $-1^{2}$ 은 뒤 항과 묶어 $3^{2}-1^{2}$ 처럼 둘씩 짝짓는다. 각 짝은 $8$, $24$, $40$, $56$ 이므로 합은 $128$ 이다. 보기는 $64$ 라 했으므로 ㄷ은 틀리다.","확인":null,"스킬":"C3"},{"제목":"옳은 보기 고르기","힌트":"세 보기 중 참인 것은?","식":["ㄱ만 옳다"],"설명":"ㄱ 은 옳고 ㄴ, ㄷ 은 틀리다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-9083734c7744":{"길":"a²+2ab+b² 를 (a+b)² 로 묶어 a+b 를 한 문자로 놓고 인수분해한다.","단계":[{"제목":"공통부분 만들기","고비":true,"힌트":"$2ab+b^{2}+a^{2}$ 을 한 덩어리로 보면?","식":["$(a+b)^{2}-7(a+b)-8$"],"설명":"$a^{2}+2ab+b^{2}=(a+b)^{2}$ 이고 $-7a-7b=-7(a+b)$ 이다. $a+b$ 가 공통부분으로 나타난다.","확인":null,"스킬":"A1"},{"제목":"치환해 인수분해","힌트":"$a+b=A$ 로 놓고 $A$ 의 이차식을 인수분해하면?","식":["$A^{2}-7A-8=(A+1)(A-8)$"],"설명":"곱이 $-8$, 합이 $-7$ 인 두 수는 $1$ 과 $-8$ 이다.","확인":null,"스킬":"A1"},{"제목":"되돌리기","힌트":"$A$ 를 $a+b$ 로 바꾸면?","식":["$(a+b+1)(a+b-8)$"],"설명":"$A=a+b$ 를 다시 대입한다.","확인":null,"스킬":"A1"}],"fb":"fig/ns/"},"ns-950ad1b134bf":{"길":"f(x) 값이 같은 구간의 길이 규칙을 찾아 합을 쌓고, 42가 되는 n 을 구한다.","단계":[{"제목":"f(x) 값의 구간 정리","고비":true,"힌트":"$\\sqrt{x}$ 가 어떤 두 자연수 사이에 있을 때 $f(x)$ 가 같아지는가?","식":["$f(1)=0$","$f(2)=f(3)=f(4)=1$","$f(5)=\\cdots=f(9)=2$","$f(10)=\\cdots=f(16)=3$","$f(17)=\\cdots=f(25)=4$"],"설명":"$x=k^{2}$ 이면 $\\sqrt{x}=k$ 이므로 $k$ 보다 작은 자연수는 $k-1$ 개이다. $f(x)$ 값이 $k$ 인 $x$ 는 $k^{2}+1$ 부터 $(k+1)^{2}$ 까지로 $2k+1$ 개이다.","확인":null,"스킬":"P1"},{"제목":"$x=16$ 까지의 합","힌트":"값이 같은 구간별로 (값)×(개수)를 더하면?","식":["$0+1\\times 3+2\\times 5+3\\times 7=34$"],"설명":"$f(1)$ 부터 $f(16)$ 까지의 합이다.","확인":null,"스킬":"P1"},{"제목":"$n$ 구하기","힌트":"합이 $42$ 가 되려면 값이 $4$ 인 항이 몇 개 더 필요한가?","식":["$42-34=8=4\\times 2$","$n=16+2=18$"],"설명":"$f(17)$ 부터 값이 $4$ 인 항이 두 개 필요하다.","확인":"18","스킬":"P1"}],"fb":"fig/ns/"},"ns-9630732a9d2c":{"길":"소수 부분을 근호로 나타내고, 식을 전개해 x²+4x 꼴로 정리한 뒤 제곱한 관계식으로 값을 구한다.","단계":[{"제목":"$x$ 구하기","힌트":"$\\sqrt{7}$ 이 어떤 두 정수 사이에 있는가?","식":["$2<\\sqrt{7}<3$","$x=\\sqrt{7}-2$"],"설명":"정수 부분이 $2$ 이므로 소수 부분은 $\\sqrt{7}-2$ 이다.","확인":null,"스킬":"N7"},{"제목":"식 전개","힌트":"주어진 식을 전개해 정리하면?","식":["$(x+1)^{2}+2x+4=x^{2}+4x+5$"],"설명":"$(x+1)^{2}=x^{2}+2x+1$ 을 쓴다.","확인":null,"스킬":"A12"},{"제목":"$x^{2}+4x$ 의 값","고비":true,"힌트":"$x+2=\\sqrt{7}$ 의 양변을 제곱하면?","식":["$x^{2}+4x+4=7$","$x^{2}+4x=3$","$3+5=8$"],"설명":"$\\sqrt{7}$ 은 대입하지 않고 제곱해서 근호를 없앤다.","확인":"8","스킬":"A12"}],"fb":"fig/ns/"},"ns-97446420d5fd":{"길":"세 식을 각각 완전제곱식과 합차 공식으로 바꿔 A, B, C 를 구하고 크기를 비교한다.","단계":[{"제목":"A 구하기","고비":true,"힌트":"$9\\times 7\\times 3.5$ 를 $24.5$ 와 $4.5$ 로 나타내면?","식":["$24.5^{2}-2\\times 4.5\\times 24.5+4.5^{2}=(24.5-4.5)^{2}$","$A=20$"],"설명":"$9\\times 7\\times 3.5=9\\times 24.5=2\\times 4.5\\times 24.5$ 이다.","확인":"20","스킬":"A6"},{"제목":"B 구하기","힌트":"$53^{2}-45^{2}$ 에 합차 공식을 쓰면?","식":["$\\sqrt{(53-45)(53+45)}=\\sqrt{8\\times 98}=\\sqrt{2^{4}\\times 7^{2}}$","$B=28$"],"설명":"$8\\times 98=2^{3}\\times 2\\times 7^{2}$ 이므로 근호를 없앨 수 있다.","확인":"28","스킬":"A6"},{"제목":"C 구하기","힌트":"$24\\times 28$ 을 $20$ 을 기준으로 나타내면?","식":["$(20+4)(20+8)+4=20^{2}+12\\times 20+36=(20+6)^{2}$","$C=26$"],"설명":"$20^{2}+12\\times 20+36$ 은 완전제곱식이다.","확인":"26","스킬":"A6"},{"제목":"크기 비교","힌트":"세 값을 비교하면?","식":["$A<C<B$"],"설명":"$A=20$, $C=26$, $B=28$ 이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-9db32025f0e0":{"길":"5개 자료의 중앙값은 세 번째 값임을 이용해 x의 범위를 나누고, 세 중앙값이 같아지는 범위를 찾는다.","단계":[{"제목":"경우 나누기","고비":true,"힌트":"x가 어느 구간에 있을 때 세 자료의 중앙값 모양이 달라지는가?","식":["$x<5$, $5\\le x\\le 7$, $x>7$"],"설명":"변량이 $5$ 개이므로 중앙값은 크기순 세 번째 값이다. 세 자료 모두 $x$ 를 빼면 $5$ 와 $7$ 근처의 값이 중앙에 오므로 $5$, $7$ 을 경계로 나눈다.","확인":null,"스킬":"C2"},{"제목":"$x<5$ 인 경우","힌트":"세 중앙값을 각각 구하면?","식":["$A=5,\\ B=5,\\ C=3$ 또는 $x$"],"설명":"$C$ 가 $5$ 가 될 수 없으므로 $A=B=C$ 가 되지 않는다.","확인":null,"스킬":"C2"},{"제목":"$5\\le x\\le 7$ 인 경우","힌트":"세 중앙값은 각각 얼마인가?","식":["$A=B=C=x$","$x=5,\\ 6,\\ 7$"],"설명":"이 범위에서는 항상 $A=B=C$ 가 성립한다.","확인":null,"스킬":"C2"},{"제목":"$x>7$ 인 경우","힌트":"A와 B를 구해 비교하면?","식":["$A=8,\\ B=7$"],"설명":"$A\\ne B$ 이므로 성립하지 않는다.","확인":null,"스킬":"C2"},{"제목":"합 구하기","힌트":"조건을 만족하는 x의 값을 모두 더하면?","식":["$5+6+7=18$"],"설명":"$x=5$, $6$, $7$ 의 합이다.","확인":"18","스킬":"C2"}],"fb":"fig/ns/"},"ns-9ddaf5e275b2":{"길":"순환소수 두 개를 분수로 바꿔 등식에 넣고 양변을 제곱해 b/a 를 구한 뒤 서로소 조건으로 a, b 를 읽는다.","단계":[{"제목":"순환소수를 분수로","고비":true,"힌트":"$1.0\\dot{2}$ 와 $0.\\dot{2}$ 를 분수로 바꾸려면 어떻게 곱해 빼야 하나?","식":["$1.0\\dot{2}=\\frac{92}{90}$","$0.\\dot{2}=\\frac{2}{9}$"],"설명":"$x=1.0\\dot{2}$ 라 하면 $100x-10x=102.\\dot{2}-10.\\dot{2}=92$ 이므로 $x=\\frac{92}{90}$ 이다.","확인":null,"스킬":"N6"},{"제목":"양변 제곱","힌트":"분수로 바꾼 식의 양변을 제곱하면?","식":["$\\frac{92}{90}\\times\\frac{b}{a}=\\frac{4}{81}$"],"설명":"좌변의 근호가 없어지고 우변은 $\\left(\\frac{2}{9}\\right)^{2}$ 이다.","확인":null,"스킬":"N6"},{"제목":"$a$, $b$ 정하기","힌트":"$\\frac{b}{a}$ 를 구하고 약분되는지 보면?","식":["$\\frac{b}{a}=\\frac{4}{81}\\times\\frac{90}{92}=\\frac{10}{207}$","$a=207,\\ b=10$"],"설명":"$a$, $b$ 가 서로소이므로 기약분수 그대로 $a$, $b$ 이다.","확인":null,"스킬":"N6"},{"제목":"$a-b$ 계산","힌트":"두 값의 차는?","식":["$207-10=197$"],"설명":"$a=207$, $b=10$ 을 뺀다.","확인":"197","스킬":"N6"}],"fb":"fig/ns/"},"ns-9ea742e6d0b6":{"길":"높이 식을 완전제곱식으로 고쳐 최대 시각과 최대 높이를 읽고, 나머지 보기는 대입이나 방정식으로 확인한다.","단계":[{"제목":"완전제곱식으로 고치기","힌트":"$a(x-p)^2+q$ 꼴로 고치면 $p$ 와 $q$ 는 각각 무엇을 뜻하는가?","식":["$y=-10(x-10)^{2}+4000$"],"설명":"$x^2$ 의 계수 $-10$ 으로 묶어 완전제곱식을 만든다. 높이는 $x=10$ 일 때 최대이고 그 값은 $4000$ 이다.","확인":null,"스킬":"A6","고비":true},{"제목":"①, ② 판정","힌트":"최대가 되는 때와 그때의 높이는 보기와 맞는가?","식":["$x=10,\\ y_{\\max}=4000$"],"설명":"최대가 되는 때는 $10$ 초 후이고 최대 높이는 $4000\\,m$ 이므로 ①, ②는 옳지 않다.","확인":null,"스킬":"A6","고비":false},{"제목":"③ 지면에 닿는 시각","힌트":"지면에 떨어질 때 $y$ 의 값은 얼마인가?","식":["$0=-10x^{2}+200x+3000$","$(x+10)(x-30)=0$"],"설명":"$y=0$ 을 풀면 $x=-10$ 또는 $x=30$ 이고 $x>0$ 이므로 $30$ 초이다. 따라서 ③은 옳지 않다.","확인":null,"스킬":"G1","고비":false},{"제목":"④, ⑤ 판정","힌트":"$x=1$ 을 대입한 높이는 얼마인가? $4000$ 은 최대 높이와 어떤 관계인가?","식":["$x=1:\\ y=3190$","$y=4000\\iff (x-10)^{2}=0$"],"설명":"$x=1$ 이면 $y=3190$ 이므로 ④는 옳지 않다. $4000$ 은 최댓값이어서 $x=10$ 일 때만 되므로 ⑤가 옳다.","확인":null,"스킬":"A6","고비":false}],"fb":"fig/ns/"},"ns-9fbc69755ac8":{"길":"상수항 부호를 바꾼 방정식에 주어진 근을 대입해 a 를 구하고, 처음 방정식의 두 근으로 식의 값을 계산한다.","단계":[{"제목":"잘못 푼 방정식 세우기","힌트":"상수항의 부호만 바꾸면 방정식은 어떤 꼴이 되는가?","식":["$x^{2}-ax-(1-a)=0$"],"설명":"상수항 $1-a$ 의 부호만 바꾼 식이 잘못 풀었던 방정식이다.","확인":null,"스킬":"C7","고비":true},{"제목":"a 의 값 구하기","힌트":"한 근 $2$ 를 대입하면 $a$ 에 대한 어떤 식이 되는가?","식":["$4-2a-(1-a)=0$","$a=3$"],"설명":"$x=2$ 를 대입하면 $a$ 에 대한 일차방정식이 되고 그 해가 $a$ 이다.","확인":"3","스킬":"C7","고비":false},{"제목":"처음 방정식의 근","힌트":"$a$ 값을 넣은 처음 방정식을 근의 공식으로 풀면 근은 무엇인가?","식":["$x^{2}-3x-2=0$","$x=\\frac{3\\pm\\sqrt{17}}{2}$"],"설명":"큰 근이 $A=\\frac{3+\\sqrt{17}}{2}$, 작은 근이 $B=\\frac{3-\\sqrt{17}}{2}$ 이다.","확인":null,"스킬":"A6","고비":false},{"제목":"2A-B 계산","힌트":"$A$, $B$ 를 대입해 $2A-B$ 를 간단히 하면?","식":["$2A-B=(3+\\sqrt{17})-\\frac{3-\\sqrt{17}}{2}$","$=\\frac{3(1+\\sqrt{17})}{2}$"],"설명":"$2A$ 를 먼저 정리한 뒤 통분해 $B$ 를 뺀다.","확인":null,"스킬":"A6","고비":false}],"fb":"fig/ns/"},"ns-a7ac0237ff56":{"길":"보기마다 유리수가 되는 무리수 $a$ 가 있는지 찾아 반례가 있는 것을 지운다.","단계":[{"제목":"ㄱ 의 반례","힌트":"$a+\\sqrt{3}$ 이 유리수가 되려면 $a$ 는 어떤 수여야 하는가?","식":["$a=-\\sqrt{3}\\Rightarrow a+\\sqrt{3}=0$"],"설명":"$a=-\\sqrt{3}$ 은 무리수이고 이때 $a+\\sqrt{3}=0$ 은 유리수이므로 ㄱ은 항상 무리수가 아니다.","확인":null,"스킬":"C3","고비":false},{"제목":"ㄷ 의 반례","힌트":"$\\sqrt{5}a$ 가 유리수가 되는 무리수 $a$ 는 무엇인가?","식":["$a=\\sqrt{5}\\Rightarrow \\sqrt{5}a=5$"],"설명":"$a=\\sqrt{5}$ 이면 곱이 유리수이므로 ㄷ은 항상 무리수가 아니다.","확인":null,"스킬":"C3","고비":false},{"제목":"ㅁ 의 반례","힌트":"$(1-\\sqrt{3})^{2}$ 과 곱해 유리수가 되는 무리수는 무엇인가?","식":["$(1-\\sqrt{3})^{2}=4-2\\sqrt{3}$","$a=4+2\\sqrt{3}\\Rightarrow (4-2\\sqrt{3})(4+2\\sqrt{3})=4$"],"설명":"합과 차의 곱 꼴이 되도록 켤레인 $4+2\\sqrt{3}$ 을 $a$ 로 잡으면 곱이 유리수이므로 ㅁ도 항상 무리수가 아니다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄴ, ㄹ 확인","힌트":"유리수를 더하거나 $0$ 이 아닌 유리수를 곱한 결과는 무리수인가 유리수인가?","식":["$a+2\\ (\\text{무리수})$","$3a\\ (\\text{무리수})$"],"설명":"무리수에 유리수를 더하면 무리수이고, $0$ 이 아닌 유리수를 곱해도 무리수이다. 따라서 항상 무리수인 것은 ㄴ, ㄹ 이다.","확인":null,"스킬":"C3","고비":false}],"fb":"fig/ns/"},"ns-a9b514ed409c":{"길":"세로를 $x$ 로 놓고 겉넓이 식에서 $x$ 를 구한 뒤 세 모서리를 곱해 부피를 구한다.","단계":[{"제목":"겉넓이 식 세우기","힌트":"세로를 $x$ 로 두면 겉넓이는 서로 다른 세 면의 넓이의 합의 몇 배인가?","식":["$2(5\\sqrt{3}x+3\\sqrt{2}x+5\\sqrt{3}\\cdot3\\sqrt{2})=48+70\\sqrt{6}$","$(5\\sqrt{3}+3\\sqrt{2})x=24+20\\sqrt{6}$"],"설명":"직육면체의 겉넓이는 서로 다른 세 면의 넓이의 합의 $2$ 배이다. 양변을 $2$ 로 나누고 $15\\sqrt{6}$ 을 이항한다.","확인":null,"스킬":"C7","고비":true},{"제목":"세로 구하기","힌트":"분모 $5\\sqrt{3}+3\\sqrt{2}$ 를 유리화하려면 무엇을 곱하는가?","식":["$x=\\frac{24+20\\sqrt{6}}{5\\sqrt{3}+3\\sqrt{2}}=\\frac{4(6+5\\sqrt{6})(5\\sqrt{3}-3\\sqrt{2})}{57}$","$x=4\\sqrt{2}$"],"설명":"분모와 분자에 $5\\sqrt{3}-3\\sqrt{2}$ 를 곱한다. 분모는 합과 차의 곱 공식으로 $75-18=57$ 이다.","확인":null,"스킬":"N8","고비":false},{"제목":"부피 계산","힌트":"가로, 세로, 높이를 곱하면 얼마인가?","식":["$5\\sqrt{3}\\times4\\sqrt{2}\\times3\\sqrt{2}=120\\sqrt{3}$"],"설명":"$\\sqrt{2}\\times\\sqrt{2}=2$ 를 이용해 계수를 곱한다.","확인":null,"스킬":"N8","고비":false}],"fb":"fig/ns/"},"ns-af0b3dcb94f6":{"길":"각 항의 분모를 유리화해 두 근호의 차로 바꾸면 이웃한 항이 서로 지워진다.","단계":[{"제목":"한 항의 유리화","힌트":"$\\frac{1}{f(a)}$ 의 분모를 유리화하려면 무엇을 곱하는가?","식":["$\\frac{1}{f(a)}=\\frac{\\sqrt{a+1}-\\sqrt{a}}{(\\sqrt{a+1}+\\sqrt{a})(\\sqrt{a+1}-\\sqrt{a})}$","$=\\sqrt{a+1}-\\sqrt{a}$"],"설명":"분모와 분자에 $\\sqrt{a+1}-\\sqrt{a}$ 를 곱하면 분모는 $(a+1)-a=1$ 이 된다.","확인":null,"스킬":"P6","고비":true},{"제목":"항을 나열하기","힌트":"$a=1,2,3,\\cdots,1001$ 을 차례로 넣으면 이웃한 항은 어떻게 되는가?","식":["$(\\sqrt{2}-\\sqrt{1})+(\\sqrt{3}-\\sqrt{2})+\\cdots+(\\sqrt{1002}-\\sqrt{1001})$"],"설명":"앞 항의 $+\\sqrt{k}$ 와 다음 항의 $-\\sqrt{k}$ 가 서로 지워진다.","확인":null,"스킬":"P6","고비":false},{"제목":"남는 항 계산","힌트":"지워지고 남는 항은 무엇인가?","식":["$\\sqrt{1002}-\\sqrt{1}=-1+\\sqrt{1002}$"],"설명":"맨 앞의 $-\\sqrt{1}$ 과 맨 뒤의 $\\sqrt{1002}$ 만 남는다.","확인":null,"스킬":"P6","고비":false}],"fb":"fig/ns/"},"ns-b39b4a549b7f":{"길":"근의 공식에서 근호 안의 식을 구하고, 그 값이 제곱수가 되도록 하는 자연수 $k$ 를 찾는다.","단계":[{"제목":"근호 안의 식","힌트":"해가 유리수이려면 근의 공식에서 어느 부분이 제곱수여야 하는가?","식":["$x=\\frac{-5\\pm\\sqrt{13-4k}}{2}$"],"설명":"근의 공식에서 근호 안은 $25-4(k+3)=13-4k$ 이다. 해가 유리수이려면 이 값이 $0$ 이거나 자연수의 제곱이어야 한다.","확인":null,"스킬":"A6","고비":false},{"제목":"가능한 값 정하기","힌트":"$k$ 가 자연수일 때 $\\sqrt{13-4k}$ 가 될 수 있는 값은 어디까지인가?","식":["$\\sqrt{13-4k}=0,\\ 1,\\ 2,\\ 3$"],"설명":"$k\\ge1$ 이면 $13-4k\\le9$ 이므로 $\\sqrt{13-4k}$ 는 $3$ 이하의 $0$ 또는 자연수이다.","확인":null,"스킬":"N8","고비":true},{"제목":"k 구하여 합하기","힌트":"각 값에 대해 $k$ 를 구하면 자연수인 것은 어느 것인가?","식":["$k=\\frac{13}{4},\\ 3,\\ \\frac{9}{4},\\ 1$","$1+3=4$"],"설명":"자연수인 것은 $k=3$ 과 $k=1$ 이고 그 합은 $4$ 이다.","확인":"4","스킬":"N8","고비":false}],"fb":"fig/ns/"},"ns-b56e4d3253bc":{"길":"앞의 두 다항식을 인수분해해 공통인수를 찾고, 세 번째 식이 그 인수를 갖도록 $A$ 를 정한다.","단계":[{"제목":"첫째 식 인수분해","힌트":"$4x^{2}+10x-24$ 를 공통수로 묶은 뒤 인수분해하면?","식":["$4x^{2}+10x-24=2(2x-3)(x+4)$"],"설명":"$2$ 로 묶고 $2x^{2}+5x-12$ 를 인수분해한다.","확인":null,"스킬":"A4","고비":false},{"제목":"둘째 식 인수분해","힌트":"$8x^{2}y-14xy+3y$ 에서 공통인수를 묶고 남은 이차식을 인수분해하면?","식":["$8x^{2}y-14xy+3y=y(2x-3)(4x-1)$"],"설명":"$y$ 로 묶고 $8x^{2}-14x+3$ 을 인수분해한다.","확인":null,"스킬":"A4","고비":false},{"제목":"공통인수 찾기","힌트":"두 식에 공통으로 들어 있는 $x$ 의 일차식은 무엇인가?","식":["$2x-3$"],"설명":"두 식 모두 $2x-3$ 을 인수로 가진다.","확인":null,"스킬":"A4","고비":false},{"제목":"A 구하기","힌트":"$4x^{2}+Ax-3$ 의 나머지 인수는 이차항과 상수항을 맞추면 무엇인가?","식":["$4x^{2}+Ax-3=(2x-3)(2x+1)$","$A=-4$"],"설명":"이차항 $4x^{2}$ 과 상수항 $-3$ 에 맞는 나머지 인수는 $2x+1$ 이고, 전개한 $x$ 의 계수가 $A$ 이다.","확인":"-4","스킬":"A4","고비":true}],"fb":"fig/ns/"},"ns-b6794254888b":{"길":"보기를 하나씩 계산해 결과가 다르게 나오는 것을 찾는다.","단계":[{"제목":"①번 계산","힌트":"두 분수의 분모를 각각 유리화하면?","식":["$\\frac{2}{\\sqrt{5}-2}=2\\sqrt{5}+4$","$\\frac{3-\\sqrt{5}}{3+\\sqrt{5}}=\\frac{7-3\\sqrt{5}}{2}$","$2\\sqrt{5}+4+\\frac{7-3\\sqrt{5}}{2}=\\frac{15+\\sqrt{5}}{2}$"],"설명":"두 분수를 유리화해 더하면 보기의 값과 같다.","확인":null,"스킬":"N8","고비":false},{"제목":"②번 계산","힌트":"각 항을 $\\sqrt{6}$ 의 배수로 바꾸면?","식":["$\\frac{\\sqrt{6}}{7}-2\\sqrt{6}+\\frac{5\\sqrt{6}}{3}=-\\frac{4\\sqrt{6}}{21}$"],"설명":"$\\sqrt{\\frac{6}{49}}$, $\\sqrt{24}$, $\\frac{5\\sqrt{2}}{\\sqrt{3}}$ 를 모두 $\\sqrt{6}$ 꼴로 바꿔 통분하면 보기의 값과 같다.","확인":null,"스킬":"N8","고비":false},{"제목":"③번 계산","힌트":"$\\sqrt{24}$, $\\sqrt{28}$, $\\sqrt{54}$ 를 $a\\sqrt{b}$ 꼴로 나타내면?","식":["$3\\sqrt{24}-3\\sqrt{28}-\\sqrt{54}+\\sqrt{7}=6\\sqrt{6}-6\\sqrt{7}-3\\sqrt{6}+\\sqrt{7}$","$=3\\sqrt{6}-5\\sqrt{7}$"],"설명":"계산 결과는 $3\\sqrt{6}-5\\sqrt{7}$ 이므로 보기의 $9\\sqrt{6}-5\\sqrt{7}$ 과 다르다.","확인":null,"스킬":"N8","고비":true},{"제목":"④, ⑤번 확인","힌트":"나머지 두 보기도 같은 방식으로 계산하면 보기의 값과 같은가?","식":["$\\frac{\\sqrt{3}}{4}+\\frac{3\\sqrt{3}}{4}-\\frac{\\sqrt{3}}{6}=\\frac{5\\sqrt{3}}{6}$","$3+\\frac{\\sqrt{3}}{2}=\\frac{6+\\sqrt{3}}{2}$"],"설명":"④와 ⑤는 보기의 값과 같으므로 옳지 않은 것은 ③이다.","확인":null,"스킬":"N8","고비":false}],"fb":"fig/ns/"},"ns-b8634c018821":{"길":"네 방정식의 근을 모두 구한 뒤 보기를 하나씩 비교한다.","단계":[{"제목":"앞의 두 방정식 풀기","힌트":"인수분해와 제곱근으로 처음 두 방정식을 풀면?","식":["$x^{2}-2x-24=0\\Rightarrow x=-4,\\ 6$","$5x^{2}-25=0\\Rightarrow x=\\pm\\sqrt{5}$"],"설명":"첫째는 $(x+4)(x-6)=0$ 으로, 둘째는 $x^{2}=5$ 로 푼다.","확인":null,"스킬":"A6","고비":false},{"제목":"뒤의 두 방정식 풀기","힌트":"우변을 이항해 정리하거나 제곱근으로 풀면?","식":["$(x-4)^{2}=3x-8\\Rightarrow x^{2}-11x+24=0\\Rightarrow x=3,\\ 8$","$(x+2)^{2}=6\\Rightarrow x=-2\\pm\\sqrt{6}$"],"설명":"셋째는 정리해 $(x-3)(x-8)=0$ 으로, 넷째는 $x+2=\\pm\\sqrt{6}$ 으로 푼다.","확인":null,"스킬":"A6","고비":false},{"제목":"보기 판별","힌트":"각 보기의 조건을 네 방정식의 근에 대 보면 어떻게 되는가?","식":["$(-4)\\times6=-24$","$\\sqrt{5}\\times(-\\sqrt{5})=-5$","$(-2+\\sqrt{6})(-2-\\sqrt{6})=-2$"],"설명":"중근을 가지는 방정식은 없다. 둘째 방정식은 두 근의 합이 $0$ 이어서 ②는 틀리고, 두 근의 곱이 음수인 방정식은 $3$ 개, 두 근이 모두 무리수인 방정식은 $2$ 개, 두 근이 모두 음수인 방정식은 없어서 ③, ④, ⑤도 틀린다. 따라서 ①이 옳다.","확인":null,"스킬":"C3","고비":true}],"fb":"fig/ns/"},"ns-b9928e9443d3":{"길":"합차 공식을 반복해 $3^{12}-1$ 을 인수분해하고, 소인수분해한 지수로 약수의 개수를 센다.","단계":[{"제목":"합차 공식으로 인수분해","힌트":"$3^{12}-1$ 을 $a^{2}-b^{2}$ 꼴로 보고 더 이상 쪼개질 때까지 인수분해하면?","식":["$3^{12}-1=(3^{6}+1)(3^{6}-1)$","$=(3^{6}+1)(3^{3}+1)(3^{3}-1)$"],"설명":"$3^{12}=(3^{6})^{2}$, $3^{6}=(3^{3})^{2}$ 로 보고 합차 공식을 두 번 쓴다.","확인":null,"스킬":"A1","고비":true},{"제목":"소인수분해","힌트":"각 인수의 값을 구해 소인수분해하면?","식":["$730\\times28\\times26$","$=2^{4}\\times5\\times7\\times13\\times73$"],"설명":"$730=2\\times5\\times73$, $28=2^{2}\\times7$, $26=2\\times13$ 이다.","확인":null,"스킬":"N1","고비":false},{"제목":"약수의 개수","힌트":"소인수분해한 꼴에서 지수에 $1$ 을 더해 곱하면?","식":["$(4+1)\\times2\\times2\\times2\\times2=80$"],"설명":"각 소인수의 지수에 $1$ 을 더한 값을 모두 곱한 것이 약수의 개수이다.","확인":"80","스킬":"N1","고비":false}],"fb":"fig/ns/"},"ns-badb1ba0d30d":{"길":"$x^{10}$, $y^{10}$ 을 문자로 놓고 곱셈공식으로 식을 줄인 뒤 $xy$ 의 값을 넣는다.","단계":[{"제목":"곱 구하기","힌트":"$x$ 와 $y$ 의 곱은 얼마인가?","식":["$xy=(2+\\sqrt{5})(2-\\sqrt{5})=-1$"],"설명":"합과 차의 곱 공식으로 계산한다.","확인":"-1","스킬":"A2","고비":false},{"제목":"식 간단히 하기","힌트":"$x^{10}=a$, $y^{10}=b$ 로 놓으면 주어진 식은 어떤 곱으로 정리되는가?","식":["$(a+b)^{2}-(a-b)^{2}=4ab$"],"설명":"전개하면 $a^{2}$ 과 $b^{2}$ 은 사라지고 $4ab$ 만 남는다.","확인":null,"스킬":"A1","고비":true},{"제목":"값 구하기","힌트":"$ab=x^{10}y^{10}$ 을 $xy$ 로 나타내 값을 넣으면?","식":["$4x^{10}y^{10}=4(xy)^{10}=4\\times(-1)^{10}=4$"],"설명":"$(xy)^{10}$ 에서 $-1$ 의 짝수 거듭제곱은 $1$ 이다.","확인":"4","스킬":"A2","고비":false}],"fb":"fig/ns/"},"ns-bfaa9ca7b9d1":{"길":"$A$ 의 크기로 $\\cos A$ 를 구하고, $\\sqrt{X^{2}}=|X|$ 이므로 근호 안 식의 부호를 정해 푼다.","단계":[{"제목":"각과 코사인 값","힌트":"$\\sin A=\\frac{1}{2}$ 인 $A$ 는 몇 도이고 그때 $\\cos A$ 는 얼마인가?","식":["$A=30^{\\circ}$","$\\cos A=\\frac{\\sqrt{3}}{2}$"],"설명":"$0^{\\circ}\\le A\\le90^{\\circ}$ 에서 $\\sin A=\\frac{1}{2}$ 이면 $A=30^{\\circ}$ 이다.","확인":null,"스킬":"S6","고비":false},{"제목":"근호 안 식의 부호","힌트":"$\\cos A-1$ 과 $1+\\cos A$ 의 부호는 각각 어떠한가?","식":["$\\cos A-1<0$","$1+\\cos A>0$"],"설명":"$\\sqrt{X^{2}}=|X|$ 이므로 근호를 벗기려면 $X$ 의 부호를 알아야 한다. $\\cos A<1$ 이다.","확인":null,"스킬":"N5","고비":true},{"제목":"값 계산","힌트":"부호에 맞게 근호를 벗겨 더하면?","식":["$(1-\\cos A)+(1+\\cos A)=2$"],"설명":"음수인 식은 $-1$ 을 곱해 벗긴다.","확인":"2","스킬":"N5","고비":false}],"fb":"fig/ns/"},"ns-c3f3cda123bf":{"길":"근호 안의 수를 표에 있는 범위로 옮겨 읽고, $x^{2}$ 을 구한 뒤 다시 표에서 읽는다","단계":[{"제목":"$\\sqrt{166}$ 을 표의 수로 바꾸기","힌트":"$166$ 을 $100$ 과 어떤 수의 곱으로 쓰면 표에서 읽을 수 있을까?","식":["$\\sqrt{166}=10\\sqrt{1.66}$"],"설명":"$166=100\\times1.66$ 이므로 $10$ 을 근호 밖으로 꺼낸다. $\\sqrt{1.66}$ 은 표의 $1.6$ 행 $6$ 열에서 읽는다.","확인":null,"스킬":"N8","고비":true},{"제목":"$x^{2}$ 의 값 구하기","힌트":"표에서 읽은 값으로 $\\sqrt{166}$ 을 계산한 뒤 $x^{2}$ 을 구하면?","식":["$\\sqrt{166}=10\\times1.288=12.88$","$x^{2}=12.88-11.14=1.74$"],"설명":"표에서 $\\sqrt{1.66}=1.288$ 이다. 이 값으로 $\\sqrt{166}$ 을 구한 뒤 주어진 식에 넣는다.","확인":"1.74","스킬":"N8"},{"제목":"$x$ 를 표에서 읽기","힌트":"$x$ 는 양수이므로 $x^{2}$ 의 양의 제곱근을 표의 어느 칸에서 읽을까?","식":["$x=\\sqrt{1.74}=1.319$"],"설명":"$\\sqrt{1.74}$ 는 $1.7$ 행 $4$ 열의 값이다.","확인":"1.319","스킬":"N8"}],"fb":"fig/ns/"},"ns-c49be5571999":{"길":"넓이 공식에 각 설명의 조건을 넣어 참과 거짓을 가른다","단계":[{"제목":"넓이 공식 세우기","힌트":"두 변 $a$, $b$ 와 끼인각 $\\angle\\mathrm{C}$ 로 넓이를 어떻게 나타낼까?","식":["$S=\\frac{1}{2}ab\\sin C$"],"설명":"끼인각 $\\angle\\mathrm{C}$ 가 정해지면 $\\sin C$ 로 넓이가 정해진다.","확인":null,"스킬":"S6","고비":true},{"제목":"선지 ①, ② 확인","힌트":"$\\sin 45^{\\circ}$ 와 $\\sin 60^{\\circ}$ 를 넣으면 계수가 얼마인가?","식":["$\\angle\\mathrm{C}=45^{\\circ}$ 일 때 $S=\\frac{\\sqrt{2}}{4}ab$","$\\angle\\mathrm{C}=60^{\\circ}$ 일 때 $S=\\frac{\\sqrt{3}}{4}ab$"],"설명":"①, ② 는 계수가 선지와 달라 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"선지 ③, ④ 확인","힌트":"$a=b$ 인 이등변삼각형에서 ③ 은 어떤 삼각형이고, ④ 는 $\\sin 150^{\\circ}$ 가 얼마인가?","식":["$S=\\frac{\\sqrt{3}}{4}a^{2}$","$S=\\frac{1}{2}a^{2}\\sin 150^{\\circ}=\\frac{1}{4}a^{2}$"],"설명":"③ 은 $\\overline{\\mathrm{BC}}=\\overline{\\mathrm{CA}}$ 이므로 $\\angle\\mathrm{A}=\\angle\\mathrm{B}=60^{\\circ}$ 인 정삼각형이고 넓이의 계수가 선지와 다르다. ④ 는 선지와 같다.","확인":null,"스킬":"S6"},{"제목":"선지 ⑤ 확인과 답","힌트":"$\\angle\\mathrm{C}$ 가 $90^{\\circ}$ 를 넘어 커지면 $\\sin C$ 는 어떻게 되는가?","식":["$90^{\\circ}<\\angle\\mathrm{C}<180^{\\circ}$ 이면 $\\angle\\mathrm{C}$ 가 클수록 $\\sin C$ 는 작아진다"],"설명":"⑤ 는 $90^{\\circ}$ 를 넘으면 $S$ 가 작아지므로 옳지 않다. 옳은 것은 ④ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-c680955d20a0":{"길":"$6.6$ 의 제곱근을 표의 두 제곱수 사이에 끼워 소수로 나타낸다","단계":[{"제목":"$\\sqrt{6.6}$ 을 표의 수와 잇기","힌트":"표의 $a^{2}$ 값과 비교할 수 있게 $6.6$ 에 어떤 수를 곱해야 할까?","식":["$\\sqrt{66000}=100\\sqrt{6.6}$"],"설명":"$66000=10^{4}\\times6.6$ 이므로 $\\sqrt{66000}$ 은 $\\sqrt{6.6}$ 의 $100$ 배이다.","확인":null,"스킬":"N6","고비":true},{"제목":"두 제곱수 사이에 끼우기","힌트":"$66000$ 은 표의 어느 두 $a^{2}$ 값 사이에 있는가?","식":["$256^{2}<66000<257^{2}$","$256<100\\sqrt{6.6}<257$"],"설명":"표에서 $256^{2}=65536$, $257^{2}=66049$ 이다. 양수끼리의 부등식이므로 제곱근을 취해도 방향이 같다.","확인":null,"스킬":"N6"},{"제목":"소수 둘째 자리 읽기","힌트":"$100$ 으로 나누면 $\\sqrt{6.6}$ 은 어느 범위에 있는가?","식":["$2.56<\\sqrt{6.6}<2.57$"],"설명":"소수점 아래 둘째 자리 숫자는 $6$ 이다.","확인":"6","스킬":"N6"}],"fb":"fig/ns/"},"ns-cc001779af09":{"길":"다섯 수를 각각 간단히 한 뒤 음수와 양수로 나눠 크기를 비교한다","단계":[{"제목":"①, ② 계산","힌트":"①은 분배법칙, ②는 $\\sqrt{50}$ 과 $\\sqrt{18}$ 을 간단히 하면 어떻게 될까?","식":["$\\sqrt{3}(\\sqrt{3}-1)=3-\\sqrt{3}$","$\\sqrt{50}-\\sqrt{18}=2\\sqrt{2}$"],"설명":"위에서부터 ①, ② 이다. 둘 다 양수이다.","확인":null,"스킬":"N5"},{"제목":"③ 계산","힌트":"$\\frac{\\sqrt{2}-1}{\\sqrt{2}+1}$ 의 분모와 분자에 무엇을 곱하면 분모가 간단해질까?","식":["$\\frac{\\sqrt{2}-1}{\\sqrt{2}+1}=(\\sqrt{2}-1)^{2}$","$\\frac{\\sqrt{2}+1}{\\sqrt{2}-1}=(\\sqrt{2}+1)^{2}$","$(\\sqrt{2}-1)^{2}-(\\sqrt{2}+1)^{2}=-4\\sqrt{2}$"],"설명":"분모에 켤레를 곱하면 $(\\sqrt{2}+1)(\\sqrt{2}-1)=1$ 이 되어 분모가 사라진다.","확인":null,"스킬":"N5"},{"제목":"④, ⑤ 계산","힌트":"④는 $(-\\sqrt{6})^{2}$ 과 분배법칙, ⑤는 나눗셈을 곱셈으로 바꾸면 어떻게 될까?","식":["$6-18+10=-2$","$-2\\sqrt{3}+\\frac{(\\sqrt{5}-\\sqrt{3})(\\sqrt{5}+\\sqrt{3})}{2}=1-2\\sqrt{3}$"],"설명":"⑤ 는 나눗셈을 역수의 곱으로 바꾸면 합차 공식이 나온다. 둘 다 음수이다.","확인":null,"스킬":"N5"},{"제목":"대소 비교","힌트":"음수 세 개를 정수 사이에 끼우면 어떤 차례가 되는가?","식":["$-6<-4\\sqrt{2}<-5$","$-3<1-2\\sqrt{3}<-2$","$-4\\sqrt{2}<1-2\\sqrt{3}<-2<3-\\sqrt{3}<2\\sqrt{2}$"],"설명":"음수 셋이 먼저 오고 양수 둘이 뒤에 온다. $3-\\sqrt{3}$ 은 $1$ 과 $2$ 사이, $2\\sqrt{2}$ 는 $2$ 와 $3$ 사이이다.","확인":null,"스킬":"N5","고비":true},{"제목":"세 번째 수 찾기","힌트":"작은 것부터 세어 세 번째에 오는 수는?","식":["$-2$"],"설명":"세 번째는 ④ 의 계산 결과이다.","확인":null,"스킬":"N5"}],"fb":"fig/ns/"},"ns-cdf8a323c7b2":{"길":"각 항을 근호 하나로 묶어 $ab$ 로만 나타낸 뒤 값을 넣는다","단계":[{"제목":"근호 안으로 넣기","힌트":"$a$ 와 $b$ 를 근호 안으로 넣어 $ab$ 꼴로 만들 수 있을까?","식":["$a\\sqrt{\\frac{b}{a}}=\\sqrt{ab}$","$\\frac{\\sqrt{b}}{b\\sqrt{a}}=\\sqrt{\\frac{1}{ab}}$"],"설명":"$a>0$, $b>0$ 이므로 $a=\\sqrt{a^{2}}$, $b=\\sqrt{b^{2}}$ 로 근호 안에 넣을 수 있다.","확인":null,"스킬":"A2","고비":true},{"제목":"$ab=4$ 대입","힌트":"$ab=4$ 를 넣으면 식의 값은?","식":["$\\sqrt{4}-\\sqrt{\\frac{1}{4}}=2-\\frac{1}{2}=\\frac{3}{2}$"],"설명":"$ab$ 의 값만 필요하므로 $a$, $b$ 를 따로 구할 필요가 없다.","확인":"3/2","스킬":"A2"},{"제목":"양의 제곱근 구하기","힌트":"$\\frac{3}{2}$ 의 양의 제곱근은?","식":["$\\sqrt{\\frac{3}{2}}=\\frac{\\sqrt{6}}{2}$"],"설명":"분모를 유리화해 선지의 꼴로 만든다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-cf5928e93b41":{"길":"긴 부분을 $x$, 짧은 부분을 $1$ 로 두고 정의를 비례식으로 옮겨 방정식을 푼다","단계":[{"제목":"비례식 세우기","힌트":"$\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{AP}}$, $\\overline{\\mathrm{BP}}$ 를 $x$ 와 $1$ 로 나타내면?","식":["$(x+1):x=x:1$"],"설명":"$\\overline{\\mathrm{AP}}=x$ 가 긴 부분, $\\overline{\\mathrm{BP}}=1$ 이 짧은 부분이므로 $\\overline{\\mathrm{AB}}=x+1$ 이다.","확인":null,"스킬":"C7","고비":true},{"제목":"이차방정식 세우기","힌트":"내항의 곱과 외항의 곱이 같음을 쓰면?","식":["$x^{2}=x+1$","$x^{2}-x-1=0$"],"설명":"비례식에서 외항의 곱과 내항의 곱은 같다.","확인":null,"스킬":"C7"},{"제목":"근의 공식으로 풀기","힌트":"근의 공식에 $a=1$, $b=-1$, $c=-1$ 을 넣으면?","식":["$x=\\frac{1\\pm\\sqrt{5}}{2}$"],"설명":"근호 안은 $(-1)^{2}-4\\times1\\times(-1)=5$ 이다.","확인":null,"스킬":"C7"},{"제목":"길이 조건으로 거르기","힌트":"$x$ 가 길이임을 쓰면 어느 근만 남는가?","식":["$x>0$","$x=\\frac{1+\\sqrt{5}}{2}$"],"설명":"길이는 양수이므로 (라)는 $x>0$, (마)는 $\\frac{1+\\sqrt{5}}{2}$ 이다. 따라서 (다)만 옳다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-d316c7aaa08b":{"길":"두 해를 한 문자로 놓아 인수분해 꼴을 만들고 주어진 식과 계수를 비교한다","단계":[{"제목":"두 해를 문자로 놓기","힌트":"비가 $1:3$ 인 두 해를 한 문자로 나타내면?","식":["$(x-a)(x-3a)=x^{2}-4ax+3a^{2}$"],"설명":"두 해를 $a$, $3a$ 라 하고 방정식을 인수분해 꼴로 쓴다.","확인":null,"스킬":"A2","고비":true},{"제목":"계수 비교","힌트":"주어진 식과 계수를 비교하면 $k$ 와 $a$ 사이에 어떤 관계가 생기는가?","식":["$k+3=4a$","$3k=3a^{2}$"],"설명":"일차항의 계수와 상수항이 각각 같다.","확인":null,"스킬":"A2"},{"제목":"$a$ 구하기","힌트":"$k$ 를 없애 $a$ 만의 방정식으로 만들면?","식":["$4a-3=a^{2}$","$(a-1)(a-3)=0$"],"설명":"$k=4a-3$ 을 $k=a^{2}$ 에 넣는다.","확인":null,"스킬":"A2"},{"제목":"$k$ 의 합 구하기","힌트":"각 $a$ 에 대응하는 $k$ 는?","식":["$a=1\\Rightarrow k=1,\\quad a=3\\Rightarrow k=9$","$1+9=10$"],"설명":"$k=a^{2}$ 이다. 두 값을 더한다.","확인":"10","스킬":"A2"}],"fb":"fig/ns/"},"ns-d3f1216e7fbd":{"길":"정수 부분 조건으로 $x$ 의 범위를 잡고, 근호가 없어지는 $x$ 를 뺀다","단계":[{"제목":"$x$ 의 범위 세우기","힌트":"정수 부분이 $4$ 이상 $12$ 이하이면 $\\sqrt{3x}$ 는 어느 범위인가?","식":["$4\\le\\sqrt{3x}<13$","$16\\le3x<169$"],"설명":"정수 부분이 $12$ 이하이면 $13$ 미만이다. 각 변을 제곱한다.","확인":null,"스킬":"N8"},{"제목":"자연수 $x$ 의 개수","힌트":"$\\frac{16}{3}\\le x<\\frac{169}{3}$ 을 만족하는 자연수는 몇 개인가?","식":["$6\\le x\\le56$","$56-6+1=51$"],"설명":"$\\frac{16}{3}$ 은 $5$ 보다 크고 $6$ 보다 작다. $\\frac{169}{3}$ 은 $56$ 과 $57$ 사이이다.","확인":"51","스킬":"N8"},{"제목":"유리수가 되는 경우 찾기","힌트":"$\\sqrt{3x}$ 의 근호가 없어지려면 $x$ 는 어떤 꼴이어야 하는가?","식":["$x=3k^{2}$","$x=12,\\ 27,\\ 48$"],"설명":"$3x=9k^{2}$ 꼴이어야 한다. $6\\le x\\le56$ 에서 $k=2,3,4$ 이다.","확인":null,"스킬":"N8","고비":true},{"제목":"무리수가 되는 개수","힌트":"전체에서 유리수가 되는 경우를 빼면?","식":["$51-3=48$"],"설명":"조건은 무리수이므로 근호가 없어지는 세 수를 뺀다.","확인":"48","스킬":"N8"}],"fb":"fig/ns/"},"ns-d49a6e229790":{"길":"뺀 식을 정리해 완전제곱식 조건으로 $b$ 를 $a$ 로 나타내고 범위로 순서쌍을 센다","단계":[{"제목":"다항식 빼서 정리하기","힌트":"두 다항식을 빼서 $x$ 에 대한 이차식으로 정리하면?","식":["$x^{2}+7ax-3b-(ax-6b)=x^{2}+6ax+3b$"],"설명":"동류항끼리 정리한다.","확인":null,"스킬":"A6"},{"제목":"완전제곱식 조건 세우기","힌트":"이차식이 완전제곱식이려면 상수항은 일차항의 계수와 어떤 관계인가?","식":["$3b=\\left(\\frac{6a}{2}\\right)^{2}$","$b=3a^{2}$"],"설명":"상수항은 일차항 계수의 절반의 제곱과 같아야 한다.","확인":null,"스킬":"A6","고비":true},{"제목":"두 자리 자연수 조건","힌트":"$b=3a^{2}$ 이 두 자리 자연수가 되는 자연수 $a$ 는?","식":["$10\\le3a^{2}\\le99$","$a=2,\\ 3,\\ 4,\\ 5$"],"설명":"$a=1$ 이면 $b=3$ 이고 $a=6$ 이면 $b=108$ 이므로 제외된다.","확인":null,"스킬":"A6"},{"제목":"순서쌍 세기","힌트":"가능한 순서쌍은 모두 몇 개인가?","식":["$(2,12),\\ (3,27),\\ (4,48),\\ (5,75)$"],"설명":"$a$ 가 정해지면 $b$ 도 하나로 정해진다.","확인":"4","스킬":"A6"}],"fb":"fig/ns/"},"ns-d59866ef0d1f":{"길":"좌변을 인수분해할 수 있게 상수를 더한 뒤 약수 짝에서 조건에 맞는 것을 고른다","단계":[{"제목":"곱의 꼴 만들기","힌트":"양변에 어떤 수를 더하면 좌변이 두 일차식의 곱이 될까?","식":["$ab+3a+5b+15=91$","$(a+5)(b+3)=91$"],"설명":"$(a+5)(b+3)=ab+3a+5b+15$ 이므로 양변에 $15$ 를 더한다.","확인":null,"스킬":"N4","고비":true},{"제목":"약수 짝 찾기","힌트":"$a+5\\ge6$, $b+3\\ge4$ 일 때 곱이 $91$ 인 짝은?","식":["$(a+5,\\ b+3)=(7,13),\\ (13,7)$"],"설명":"$91$ 의 약수는 $1,\\ 7,\\ 13,\\ 91$ 이다. 각각 $6$ 이상, $4$ 이상이 되는 짝은 이 두 가지뿐이다.","확인":null,"스킬":"N4"},{"제목":"$a>b$ 로 정하기","힌트":"두 경우 중 $a>b$ 를 만족하는 것은?","식":["$a=8,\\ b=4$"],"설명":"다른 경우는 $a=2$, $b=10$ 이어서 $a<b$ 이다.","확인":null,"스킬":"N4"},{"제목":"값 계산","힌트":"구한 $a$, $b$ 를 넣으면?","식":["$2a-3b=16-12=4$"],"설명":"$a=8$, $b=4$ 를 대입한다.","확인":"4","스킬":"N4"}],"fb":"fig/ns/"},"ns-da70fe1f4af1":{"길":"완전제곱 꼴로 고쳐 최솟값을 문자식으로 나타내고 아래로 볼록할 조건과 함께 푼다","단계":[{"제목":"완전제곱 꼴로 고치기","힌트":"$x$ 에 대해 정리해 $(x+p)^{2}$ 꼴로 나타내면?","식":["$y=(a-1)(x+1)^{2}+a^{2}-4a+1$"],"설명":"$x^{2}$ 의 계수 $a-1$ 로 $x^{2}+2x$ 를 묶고 완전제곱식으로 만든다.","확인":null,"스킬":"A6","고비":true},{"제목":"최솟값 조건 세우기","힌트":"최솟값이 존재하려면 $x^{2}$ 의 계수는 어떤 부호이고, 그때 최솟값은 어디에 드러나는가?","식":["$a-1>0$","$a^{2}-4a+1=-2$"],"설명":"아래로 볼록해야 최솟값이 있고, 최솟값은 꼭짓점의 $y$ 좌표이다.","확인":null,"스킬":"A6"},{"제목":"$a$ 구하기","힌트":"$a$ 에 대한 이차방정식을 풀고 부호 조건과 맞춰 보면?","식":["$(a-1)(a-3)=0$","$a=3$"],"설명":"$a=1$ 은 $a>1$ 에 맞지 않는다. 따라서 $a$ 의 값은 하나이다.","확인":"3","스킬":"A6"}],"fb":"fig/ns/"},"ns-db7e986643c7":{"길":"두 반의 평균, 최빈값, 중앙값을 표에서 구해 선지를 하나씩 맞춰 본다","단계":[{"제목":"평균 비교","힌트":"각 반에서 (값 $\\times$ 학생 수)의 합을 학생 수로 나누면?","식":["$\\frac{0\\times2+1\\times4+2\\times3+3\\times3+5\\times1+6\\times2}{15}=2.4$","$\\frac{0\\times2+1\\times4+2\\times6+3\\times4+4\\times2+5\\times1+6\\times1}{20}=2.35$"],"설명":"위가 $12$ 반, 아래가 $13$ 반이다. $12$ 반의 평균이 더 크므로 ① 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"최빈값 읽기","힌트":"도수가 가장 큰 값은 각각 얼마인가?","식":["$\\text{12반 최빈값 }1$","$\\text{13반 최빈값 }2$"],"설명":"도수가 가장 큰 값은 $12$ 반이 $1$ (학생 $4$ 명), $13$ 반이 $2$ (학생 $6$ 명)이다. ②, ④ 는 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"중앙값의 위치 찾기","힌트":"자료의 개수가 홀수일 때와 짝수일 때 가운데 값은 몇 번째인가?","식":["$\\text{12반: }8\\text{번째 값 }2$","$\\text{13반: }10,\\ 11\\text{번째 값의 평균 }\\frac{2+2}{2}=2$"],"설명":"학생 수가 $15$ 이면 $8$ 번째, $20$ 이면 $10$ 번째와 $11$ 번째의 평균이다. ③ 은 옳고 ⑤ 는 옳지 않다.","확인":null,"스킬":"C3","고비":true}],"fb":"fig/ns/"},"ns-ddd56b9d16d3":{"길":"선지 순서대로 평균, 중앙값, 산포, 최빈값을 확인한다","단계":[{"제목":"학생 A, B 의 평균","힌트":"여섯 점수의 합을 $6$ 으로 나누면?","식":["$\\frac{80+75+70+75+80+70}{6}=75$","$\\frac{60+59+61+60+63+57}{6}=60$"],"설명":"①, ② 는 옳다.","확인":null,"스킬":"C3"},{"제목":"학생 C 의 평균과 중앙값","힌트":"자료가 짝수 개일 때 중앙값은 어떻게 구하는가?","식":["$\\frac{55+60+65+70+75+80}{6}=67.5$","$\\frac{65+70}{2}=67.5$"],"설명":"가운데 두 값의 평균이 중앙값이다. ③ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"산포와 최빈값 확인","힌트":"평균 $60$ 인 B 의 편차와 각 학생의 도수를 보면?","식":["$0,\\ -1,\\ 1,\\ 0,\\ 3,\\ -3$"],"설명":"B 의 편차가 가장 작아 표준편차가 가장 작다. B 는 $60$ 이 두 번 나와 최빈값이 있고, A 는 세 값이 모두 두 번씩이라 최빈값이 없으며 C 는 모두 한 번씩이라 없다. 따라서 ⑤ 가 옳지 않다.","확인":null,"스킬":"C3","고비":true}],"fb":"fig/ns/"},"ns-e1dca5228c8e":{"길":"조건에서 세 문자의 부호를 정한 뒤 근호 안 식의 부호로 근호를 벗긴다","단계":[{"제목":"$a$, $c$ 의 부호","힌트":"조건 ㉠ 에서 $b-a$ 의 부호를 알면 ㉡ 에서 $c$ 의 부호는?","식":["$b-a<0$","$c>0,\\ a>0$"],"설명":"$b<c<a$ 에서 $b-a<0$ 이다. ㉡ 에서 $c(b-a)<0$ 이므로 $c>0$ 이고, $a>c$ 이므로 $a>0$ 이다.","확인":null,"스킬":"N5"},{"제목":"$b$ 의 부호","힌트":"조건 ㉢ 에서 $b$ 를 $a$, $c$ 로 나타내면 부호는?","식":["$b=-ac<0$"],"설명":"$a>0$, $c>0$ 이므로 $ac>0$ 이다.","확인":null,"스킬":"N5"},{"제목":"근호 벗기기","힌트":"각 근호 안 식의 부호를 보면 $\\sqrt{A^{2}}$ 는 무엇이 되는가?","식":["$c-a<0,\\ \\ b<0,\\ \\ c-b>0$","$\\sqrt{(c-a)^{2}}=a-c,\\ \\ \\sqrt{b^{2}}=-b,\\ \\ \\sqrt{(c-b)^{2}}=c-b$"],"설명":"$\\sqrt{A^{2}}$ 은 $A\\ge0$ 이면 $A$, $A<0$ 이면 $-A$ 이다.","확인":null,"스킬":"N5","고비":true},{"제목":"식 정리","힌트":"세 항을 더하고 빼서 정리하면?","식":["$(a-c)+(-b)-(c-b)=a-2c$"],"설명":"$b$ 는 서로 지워진다.","확인":null,"스킬":"N5"}],"fb":"fig/ns/"},"ns-e3b68c4f308e":{"길":"두 분수를 합쳐 $\\sqrt{5}$ 의 계수를 구하고 그 계수가 $0$ 이 되는 조건과 연립한다","단계":[{"제목":"통분해 합치기","힌트":"두 분수를 하나로 합친 분자를 $\\sqrt{5}$ 항끼리 모아 쓰면?","식":["$\\frac{-x+y-10+(x+y)\\sqrt{5}}{4}$"],"설명":"분모는 $(\\sqrt{5}+1)(\\sqrt{5}-1)=4$ 이고, 분자는 전개해 유리수 부분과 $\\sqrt{5}$ 항으로 나눈다.","확인":null,"스킬":"A3"},{"제목":"유리수 조건","힌트":"$x$, $y$ 가 유리수일 때 이 수가 유리수이려면 $\\sqrt{5}$ 의 계수는?","식":["$x+y=0$"],"설명":"유리수 부분은 유리수이므로 $\\sqrt{5}$ 의 계수가 $0$ 이어야 한다.","확인":null,"스킬":"A3","고비":true},{"제목":"연립해 풀기","힌트":"$x+y=0$ 과 $x+2y=6$ 을 연립하면?","식":["$x=-6,\\ \\ y=6$"],"설명":"두 식을 빼서 $y$ 를 먼저 구한다.","확인":null,"스킬":"A10"},{"제목":"$y-x$ 계산","힌트":"구한 값을 대입하면?","식":["$y-x=6-(-6)=12$"],"설명":"음수를 빼므로 더한다.","확인":"12","스킬":"A10"}],"fb":"fig/ns/"},"ns-f2842b973556":{"길":"무리수의 범위로 정수 부분을 정하고 소수 부분을 식으로 나타내 유리화한다","단계":[{"제목":"정수 부분과 소수 부분","힌트":"$1<\\sqrt{3}<2$ 를 이용하면 $4-\\sqrt{3}$ 은 어느 두 정수 사이에 있는가?","식":["$2<4-\\sqrt{3}<3$","$a=2,\\ \\ b=2-\\sqrt{3}$"],"설명":"소수 부분은 수에서 정수 부분을 뺀 값이다.","확인":null,"스킬":"N7","고비":true},{"제목":"대입해 분모 유리화","힌트":"$a$, $b$ 를 넣고 분모와 분자에 $\\sqrt{3}$ 을 곱하면?","식":["$\\frac{b}{\\sqrt{3}a}=\\frac{2-\\sqrt{3}}{2\\sqrt{3}}=\\frac{2\\sqrt{3}-3}{6}$"],"설명":"분모가 $2\\sqrt{3}$ 이므로 분모와 분자에 $\\sqrt{3}$ 을 곱해 근호를 없앤다.","확인":null,"스킬":"N7"}],"fb":"fig/ns/"},"ns-f4bc9a4dcfd6":{"길":"각 항을 유리화해 합을 줄이고, 근호 안을 $t-2$ 에 대한 완전제곱식으로 본다","단계":[{"제목":"분모 유리화","힌트":"$\\frac{1}{\\sqrt{k}+\\sqrt{k+1}}$ 의 분모와 분자에 무엇을 곱하면 분모가 간단해지는가?","식":["$\\frac{1}{\\sqrt{k}+\\sqrt{k+1}}=\\sqrt{k+1}-\\sqrt{k}$"],"설명":"분모와 분자에 $\\sqrt{k+1}-\\sqrt{k}$ 를 곱하면 분모가 $1$ 이 된다.","확인":null,"스킬":"P6","고비":true},{"제목":"$t$ 의 값 구하기","힌트":"각 항을 바꿔 더하면 어떤 항이 남는가?","식":["$t=(\\sqrt{2}-1)+(\\sqrt{3}-\\sqrt{2})+\\cdots+(\\sqrt{80}-\\sqrt{79})=\\sqrt{80}-1$"],"설명":"가운데 항이 모두 지워지고 처음과 끝만 남는다.","확인":null,"스킬":"P6"},{"제목":"완전제곱식으로 보기","힌트":"$t-2$ 를 한 문자로 보면 근호 안은 어떤 식의 제곱인가?","식":["$(t-2)^{2}+6(t-2)+9=\\{(t-2)+3\\}^{2}=(t+1)^{2}$"],"설명":"$t-2=X$ 로 놓으면 $X^{2}+6X+9=(X+3)^{2}$ 이다.","확인":null,"스킬":"A1"},{"제목":"근호 벗기기","힌트":"$t+1$ 의 부호를 확인하고 근호를 벗기면?","식":["$\\sqrt{(t+1)^{2}}=t+1=\\sqrt{80}=4\\sqrt{5}$"],"설명":"$t+1=\\sqrt{80}>0$ 이므로 근호를 그대로 벗긴다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-fcbfc2301c22":{"길":"구하는 합과 주어진 차를 곱하면 근호가 사라지는 점을 이용한다.","단계":[{"제목":"근호의 합과 차의 곱","고비":true,"힌트":"$\\sqrt{a+2}+\\sqrt{a-2}$ 와 $\\sqrt{a+2}-\\sqrt{a-2}$ 를 곱하면 근호는 어떻게 되는가?","식":["$A=\\sqrt{a+2},\\ B=\\sqrt{a-2}$","$(A+B)(A-B)=A^2-B^2=(a+2)-(a-2)$"],"설명":"합차공식 $(A+B)(A-B)=A^2-B^2$ 에서 근호가 제곱되어 사라진다.","확인":null,"스킬":"A2"},{"제목":"곱의 값 구하기","힌트":"$(a+2)-(a-2)$ 의 값은?","식":["$(A+B)(A-B)=4$"],"설명":"$a$ 가 소거되어 곱은 상수가 된다.","확인":"4","스킬":"A2"},{"제목":"합 구하기","힌트":"곱이 $4$ 이고 한 인수가 $\\frac{1}{2}$ 이면 다른 인수는?","식":["$(A+B)\\times\\frac{1}{2}=4$","$A+B=8$"],"설명":"양변에 $2$ 를 곱한다.","확인":"8","스킬":"A2"}],"fb":"fig/ns/"},"ns-fdba6db1c695":{"길":"두 일차식의 곱으로 놓고 계수를 비교해 가능한 상수항을 센다.","단계":[{"제목":"곱의 꼴로 놓기","고비":true,"힌트":"인수분해되면 $x^2+x-k$ 를 어떤 꼴의 곱으로 쓸 수 있는가?","식":["$x^2+x-k=(x+a)(x-b)$"],"설명":"$a$, $b$ 는 정수이고 $k$ 는 $1$ 이상 $30$ 이하의 자연수이다.","확인":null,"스킬":"N4"},{"제목":"계수 비교","힌트":"전개한 식과 계수를 비교하면 $a$, $b$ 사이에는 어떤 관계가 생기는가?","식":["$a-b=1$","$ab=k$"],"설명":"$(x+a)(x-b)=x^2+(a-b)x-ab$ 이므로 $x$ 의 계수와 상수항을 비교한다.","확인":null,"스킬":"A3"},{"제목":"가능한 k 찾기","힌트":"차가 $1$ 인 두 수의 곱이 $30$ 이하인 경우를 모두 찾으면?","식":["$k=2,\\ 6,\\ 12,\\ 20,\\ 30$"],"설명":"$(a,b)=(2,1),(3,2),(4,3),(5,4),(6,5)$ 일 때 각각 $ab$ 를 구한다.","확인":null,"스킬":"N4"},{"제목":"개수 세기","힌트":"가능한 $k$ 의 값은 모두 몇 개인가?","식":["$5$"],"설명":"$k$ 의 값마다 이차식이 하나씩 대응하므로 인수분해되는 이차식은 $5$개이다.","확인":"5","스킬":"N4"}],"fb":"fig/ns/"},"ns-fdd7b6481398":{"길":"근의 공식 꼴로 놓고 보기마다 $a$, $b$ 의 부호를 바꿔 성립 여부를 확인한다.","단계":[{"제목":"근 구하기","힌트":"$(x+a)^2=b$ 의 근은 제곱근으로 어떻게 나타내는가?","식":["$x=-a\\pm\\sqrt{b}$"],"설명":"제곱근의 뜻에서 $x+a=\\pm\\sqrt{b}$ 이다.","확인":null,"스킬":"C3"},{"제목":"㉠, ㉡ 판단","힌트":"$b<0$ 이거나 $b=0$ 일 때 $\\sqrt{b}$ 는 어떻게 되는가?","식":["$b<0 \\Rightarrow \\text{근이 없다}$","$b=0 \\Rightarrow x=-a\\ (\\text{중근})$"],"설명":"$b<0$ 이면 제곱이 음수가 될 수 없어 근이 없고, $b=0$ 이면 $x=-a$ 하나뿐이다. ㉠, ㉡ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"㉢ 판단","힌트":"두 근 $-a+\\sqrt{b}$, $-a-\\sqrt{b}$ 의 절댓값이 항상 같은가?","식":["$|-a+\\sqrt{b}|\\neq|-a-\\sqrt{b}|\\ (a\\neq0)$"],"설명":"$a\\neq0$ 이면 두 근의 절댓값이 다르므로 ㉢ 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"㉣ 판단","고비":true,"힌트":"$ab>0$ 이면 $a$, $b$ 의 부호는 어떻게 될 수 있는가?","식":["$a<0,\\ b<0 \\Rightarrow \\text{근이 없다}$"],"설명":"$ab>0$ 이어도 $a$, $b$ 가 모두 음수이면 $b<0$ 이므로 근이 없다. ㉣ 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"답 고르기","힌트":"옳은 보기를 모두 모으면?","식":["$\\text{㉠, ㉡}$"],"설명":"옳은 것은 ㉠, ㉡ 이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-fdf692236514":{"길":"인수분해한 뒤 곱이 소수가 되려면 한 인수가 $\\pm1$ 이어야 함을 이용한다.","단계":[{"제목":"인수분해","힌트":"$n^2+8n-48$ 을 곱의 꼴로 바꾸면?","식":["$n^2+8n-48=(n+12)(n-4)$"],"설명":"합이 $8$, 곱이 $-48$ 인 두 수는 $12$ 와 $-4$ 이다.","확인":null,"스킬":"N4"},{"제목":"소수 조건","고비":true,"힌트":"두 정수의 곱이 소수이려면 두 인수 중 하나는 어떤 값이어야 하는가?","식":["$n+12=\\pm1\\ \\text{또는}\\ n-4=\\pm1$"],"설명":"소수는 양의 약수가 $1$ 과 자기 자신뿐이므로 한 인수는 $1$ 또는 $-1$ 이어야 한다.","확인":null,"스킬":"N4"},{"제목":"경우별 식의 값","힌트":"네 경우에 식의 값은 각각 얼마인가?","식":["$n=-11:\\ 1\\times(-15)=-15$","$n=-13:\\ (-1)\\times(-17)=17$","$n=5:\\ 17\\times1=17$","$n=3:\\ 15\\times(-1)=-15$"],"설명":"$n=-13$, $n=5$ 일 때만 값이 $17$ 로 소수이다.","확인":null,"스킬":"N4"},{"제목":"개수 세기","힌트":"조건을 만족하는 정수 $n$ 은 몇 개인가?","식":["$n=-13,\\ 5$"],"설명":"조건을 만족하는 정수 $n$ 은 $-13$, $5$ 의 $2$개이다.","확인":"2","스킬":"N4"}],"fb":"fig/ns/"},"ns-fe00d717f305":{"길":"밑을 $2$ 로 통일하고 공통인수로 묶은 뒤 인수분해 공식으로 약분한다.","단계":[{"제목":"밑을 2로 통일","힌트":"$8$, $4$, $16$ 을 모두 $2$ 의 거듭제곱으로 나타내면?","식":["$\\frac{(2^3)^8\\times2^2-(2^2)^{10}}{(2^2)^{12}\\times2^3-(2^4)^6}=\\frac{2^{26}-2^{20}}{2^{27}-2^{24}}$"],"설명":"지수법칙으로 분자와 분모의 지수를 각각 정리한다.","확인":null,"스킬":"A9"},{"제목":"공통인수로 묶기","힌트":"분자와 분모에서 가장 작은 거듭제곱으로 묶으면?","식":["$\\frac{2^{20}(2^6-1)}{2^{24}(2^3-1)}$"],"설명":"분자는 $2^{20}$, 분모는 $2^{24}$ 로 묶는다.","확인":null,"스킬":"A3"},{"제목":"합차공식 적용","고비":true,"힌트":"$2^6-1$ 을 어떻게 인수분해하면 분모와 약분되는가?","식":["$\\frac{2^{20}(2^3+1)(2^3-1)}{2^{24}(2^3-1)}=\\frac{2^3+1}{2^4}$"],"설명":"$2^6-1=(2^3)^2-1^2=(2^3+1)(2^3-1)$ 이므로 $2^3-1$ 이 약분된다.","확인":null,"스킬":"A3"},{"제목":"제곱근 계산","힌트":"약분한 값의 제곱근은?","식":["$\\sqrt{\\frac{9}{16}}=\\frac{3}{4}$"],"설명":"$9=3^2$, $16=4^2$ 이므로 근호가 풀린다.","확인":"3/4","스킬":"A9"}],"fb":"fig/ns/"},"ns-ff317992364f":{"길":"양변을 제곱해 두 인수의 곱이 $51$ 인 꼴로 만들고 약수 쌍을 따진다.","단계":[{"제목":"곱의 꼴로 변형","고비":true,"힌트":"양변을 제곱하고 $x$, $y$ 항을 한쪽으로 모으면?","식":["$4x^2-y^2=51$","$(2x+y)(2x-y)=51$"],"설명":"제곱의 차를 합차공식으로 인수분해한다.","확인":null,"스킬":"N4"},{"제목":"두 인수의 범위","힌트":"$x$, $y$ 가 자연수일 때 두 인수의 부호와 크기는?","식":["$2x+y>2x-y>0$"],"설명":"곱이 양수이고 $2x+y$ 가 양수이므로 $2x-y$ 도 양수이며, $y>0$ 이므로 $2x+y$ 가 더 크다.","확인":null,"스킬":"N5"},{"제목":"약수 쌍 찾기","힌트":"$51$ 의 약수 쌍 중 큰 수를 $2x+y$, 작은 수를 $2x-y$ 로 놓으면?","식":["$(51,\\ 1) \\Rightarrow x=13,\\ y=25$","$(17,\\ 3) \\Rightarrow x=5,\\ y=7$"],"설명":"$51=3\\times17$ 이므로 약수 쌍은 이 두 가지뿐이다.","확인":null,"스킬":"N4"},{"제목":"y 의 합","힌트":"가능한 $y$ 값을 모두 더하면?","식":["$25+7=32$"],"설명":"$y$ 의 값은 $25$ 와 $7$ 이다.","확인":"32","스킬":"N4"}],"fb":"fig/ns/"},"ns-01fe417684a4":{"길":"변의 길이를 모두 구한 뒤 중점으로 넓이를 구하고, 두 변과 끼인각으로 나타낸 넓이와 비교한다.","단계":[{"제목":"변의 길이","힌트":"$\\sin x^\\circ=\\frac{1}{4}$ 인 직각삼각형 $\\mathrm{ACD}$ 에서 $\\overline{\\mathrm{AD}}=4$ 로 놓으면 $\\overline{\\mathrm{DC}}$ 는?","식":["$\\overline{\\mathrm{DC}}=\\overline{\\mathrm{BD}}=1$","$\\overline{\\mathrm{AC}}=\\sqrt{4^2-1^2}=\\sqrt{15}$"],"설명":"$\\overline{\\mathrm{AD}}$ 가 빗변이므로 $\\overline{\\mathrm{DC}}=4\\sin x^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"AB 의 길이","힌트":"직각삼각형 $\\mathrm{ABC}$ 에서 $\\overline{\\mathrm{AB}}$ 는?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{2^2+(\\sqrt{15})^2}=\\sqrt{19}$"],"설명":"$\\overline{\\mathrm{BC}}=2$ 이다.","확인":null,"스킬":"S3"},{"제목":"삼각형 ABD 의 넓이","고비":true,"힌트":"점 $\\mathrm{D}$ 가 $\\overline{\\mathrm{BC}}$ 의 중점이면 $\\triangle \\mathrm{ABD}$ 의 넓이는 $\\triangle \\mathrm{ABC}$ 의 몇 배인가?","식":["$\\triangle \\mathrm{ABD}=\\frac{1}{2}\\triangle \\mathrm{ABC}=\\frac{\\sqrt{15}}{2}$"],"설명":"두 삼각형은 높이가 같고 밑변의 비가 $1:2$ 이다.","확인":null,"스킬":"S8"},{"제목":"sin y 구하기","힌트":"$\\triangle \\mathrm{ABD}$ 의 넓이를 두 변과 그 끼인각으로 나타내면?","식":["$\\frac{1}{2}\\times\\sqrt{19}\\times4\\times\\sin y^\\circ=\\frac{\\sqrt{15}}{2}$","$\\sin y^\\circ=\\frac{\\sqrt{15}}{4\\sqrt{19}}=\\sqrt{\\frac{15}{304}}$"],"설명":"$\\overline{\\mathrm{AB}}$ 와 $\\overline{\\mathrm{AD}}$ 의 끼인각이 $y^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"a+b 구하기","힌트":"$\\sqrt{\\frac{b}{a}}$ 꼴과 비교하면?","식":["$a=304,\\ b=15$","$a+b=319$"],"설명":"$304=2^4\\times19$ 와 $15$ 는 서로소이다.","확인":"319","스킬":"S6"}],"fb":"fig/ns/"},"ns-03451ce2ec7c":{"길":"점 P 의 좌표를 구한 뒤 정수 부분과 소수 부분을 정하고 식에 대입한다.","단계":[{"제목":"점 P 의 좌표","힌트":"정사각형의 대각선 $\\overline{\\mathrm{AC}}$ 의 길이는? 점 $\\mathrm{P}$ 는 점 $\\mathrm{A}$ 의 어느 쪽에 있는가?","식":["$\\overline{\\mathrm{AC}}=\\sqrt{2}$","$a=3-\\sqrt{2}$"],"설명":"$\\overline{\\mathrm{AP}}=\\overline{\\mathrm{AC}}$ 이고 점 $\\mathrm{P}$ 는 점 $\\mathrm{A}(3)$ 의 왼쪽에 있다.","확인":null,"스킬":"S3"},{"제목":"정수 부분과 소수 부분","고비":true,"힌트":"$\\sqrt{2}$ 의 범위로 $3-\\sqrt{2}$ 가 어느 두 정수 사이에 있는지 보면?","식":["$1<3-\\sqrt{2}<2$","$x=1,\\ y=2-\\sqrt{2}$"],"설명":"소수 부분은 수에서 정수 부분을 뺀 값이므로 $y=(3-\\sqrt{2})-1$ 이다.","확인":null,"스킬":"N7"},{"제목":"식에 대입","힌트":"$\\frac{y-1}{x-2y}$ 에 $x$, $y$ 를 대입하면?","식":["$\\frac{y-1}{x-2y}=\\frac{1-\\sqrt{2}}{2\\sqrt{2}-3}$"],"설명":"분모는 $x-2y=1-2(2-\\sqrt{2})=2\\sqrt{2}-3$ 이다.","확인":null,"스킬":"N8"},{"제목":"분모 유리화","힌트":"분모에 어떤 수를 곱해야 근호가 없어지는가?","식":["$\\frac{(1-\\sqrt{2})(2\\sqrt{2}+3)}{(2\\sqrt{2}-3)(2\\sqrt{2}+3)}=1+\\sqrt{2}$"],"설명":"분모 $(2\\sqrt{2})^2-3^2=-1$ 이고, 분자 $(1-\\sqrt{2})(2\\sqrt{2}+3)=-1-\\sqrt{2}$ 이다.","확인":null,"스킬":"N8"}],"fb":"fig/ns/"},"ns-03707f0e1f22":{"길":"작은 원의 지름을 문자로 놓아 둘레 식을 세우고, 넓이는 인수분해 공식으로 계산한다.","단계":[{"제목":"미지수 놓기","고비":true,"힌트":"$\\overline{\\mathrm{CD}}$ 를 $a$ 라 하면 큰 원의 지름 $\\overline{\\mathrm{AB}}$ 는?","식":["$\\overline{\\mathrm{AB}}=a+1.2$"],"설명":"$\\overline{\\mathrm{AC}}+\\overline{\\mathrm{BD}}=1.2$ 이므로 큰 원의 반지름은 $\\frac{a+1.2}{2}$, 작은 원의 반지름은 $\\frac{a}{2}$ 이다.","확인":null,"스킬":"C7"},{"제목":"둘레 식 세우기","힌트":"색칠한 부분의 둘레는 어떤 두 원둘레의 합인가?","식":["$2\\pi\\times\\frac{a}{2}+2\\pi\\times\\frac{a+1.2}{2}=10\\pi$"],"설명":"큰 원의 둘레와 작은 원의 둘레를 더한다.","확인":null,"스킬":"C7"},{"제목":"a 구하기","힌트":"양변을 $\\pi$ 로 나누어 $a$ 를 구하면?","식":["$2a=8.8$","$a=4.4$"],"설명":"일차방정식을 푼다.","확인":"4.4","스킬":"C7"},{"제목":"넓이 계산","힌트":"두 원의 반지름으로 넓이의 차를 계산하면?","식":["$\\pi(2.8+2.2)(2.8-2.2)=3\\pi$"],"설명":"큰 원의 반지름은 $2.8$, 작은 원의 반지름은 $2.2$ 이다. 합차공식을 쓰면 계산이 쉽다. 단위는 $\\mathrm{cm}^2$ 이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-08bfef992668":{"길":"반원의 원주각과 접선-현 각으로 닮은 삼각형을 찾고 선지를 하나씩 확인한다.","단계":[{"제목":"①, ② 확인","힌트":"반원에 대한 원주각과 접선-현 각의 성질로 ①, ② 를 확인하면?","식":["$\\angle \\mathrm{PAT}=90^\\circ$","$\\angle \\mathrm{PTA}=\\angle \\mathrm{PBT}$"],"설명":"지름 $\\overline{BT}$ 에 대한 원주각이므로 $\\angle \\mathrm{BAT}=90^\\circ$ 이고 $\\angle \\mathrm{PAT}=90^\\circ$ 이다. 접선과 현이 이루는 각은 그 호에 대한 원주각과 같다. ①, ② 는 옳다.","확인":null,"스킬":"S5"},{"제목":"③ 닮음 찾기","고비":true,"힌트":"$\\triangle \\mathrm{PAT}$ 와 $\\triangle \\mathrm{PTB}$ 에서 크기가 같은 각은?","식":["$\\angle \\mathrm{PAT}=\\angle \\mathrm{PTB}=90^\\circ$","$\\angle \\mathrm{PTA}=\\angle \\mathrm{PBT}$","$\\triangle \\mathrm{PAT}\\sim\\triangle \\mathrm{PTB}$"],"설명":"접선 $\\overline{PT}$ 는 지름 $\\overline{BT}$ 와 수직이므로 $\\angle \\mathrm{PTB}=90^\\circ$ 이다. 두 각이 같아 $AA$ 닮음이다. ③ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"④ 확인","힌트":"닮음비에서 $\\overline{\\mathrm{PT}}$ 에 관한 식을 얻으면?","식":["$\\overline{\\mathrm{PA}}:\\overline{\\mathrm{PT}}=\\overline{\\mathrm{PT}}:\\overline{\\mathrm{PB}}$","$\\overline{\\mathrm{PT}}^{2}=\\overline{\\mathrm{PA}}\\cdot\\overline{\\mathrm{PB}}$"],"설명":"대응변의 비가 같으므로 내항의 곱과 외항의 곱이 같다. ④ 는 옳다.","확인":null,"스킬":"S1"},{"제목":"⑤ 확인","힌트":"$\\overline{\\mathrm{BT}}$, $\\overline{\\mathrm{BP}}$ 에 대응하는 변을 닮은 삼각형에서 찾으면?","식":["$\\overline{\\mathrm{BT}}:\\overline{\\mathrm{BP}}=\\overline{\\mathrm{TA}}:\\overline{\\mathrm{PT}}$"],"설명":"$\\triangle \\mathrm{TAB}\\sim\\triangle \\mathrm{PTB}$ 에서 대응변의 비가 같다. ⑤ 의 비 $\\overline{TP}:\\overline{TA}$ 는 뒤 두 항의 순서가 바뀌어 옳지 않다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-0b64233ee30f":{"길":"제곱근을 나타낸 점을 $n^{2}$ 과 $(n+1)^{2}$ 사이의 자연수로 바꿔 보기 가, 나, 다, 라를 하나씩 따진다","단계":[{"제목":"보기 가","힌트":"$n$ 과 $n+1$ 사이에 있는 제곱근 $\\sqrt{k}$ 의 $k$ 는 어떤 범위일까?","식":["$n^{2}<k<(n+1)^{2}$","$(n+1)^{2}-n^{2}-1=2n$"],"설명":"$n^{2}$ 과 $(n+1)^{2}$ 사이의 자연수는 $2n$ 개이고, 이 수들의 제곱근은 모두 무리수이다. $2n$ 은 항상 짝수이므로 가는 옳다.","확인":null,"스킬":"C3"},{"제목":"보기 나","힌트":"제곱근이 유리수인 $\\sqrt{k}$ 는 어떤 수일까?","식":["$\\sqrt{k}\\ \\text{가 유리수}\\Leftrightarrow k\\ \\text{는 제곱수}$"],"설명":"그림의 점은 자연수의 양의 제곱근이어서, 유리수인 것은 제곱수의 제곱근, 곧 정수뿐이다. $n$ 과 $n+1$ 사이에는 정수가 없으므로 나는 옳다.","확인":null,"스킬":"C3"},{"제목":"보기 다","힌트":"보기 가 에서 구한 개수에 $n=2013$ 을 넣으면?","식":["$2\\times2013=4026$"],"설명":"$2013$ 과 $2014$ 사이의 무리수 점은 $4026$ 개이므로 다는 옳다.","확인":"4026","스킬":"C3"},{"제목":"보기 라","힌트":"$n=3$ 을 넣으면 $\\sqrt{n^{2}+1}$ 의 정수 부분과 $1$ 과 $n$ 사이의 정수점 개수는?","식":["$\\sqrt{3^{2}+1}=\\sqrt{10}$, $3<\\sqrt{10}<4$","$\\text{정수점은 }\\sqrt{4}=2\\text{ 하나}$"],"설명":"$\\sqrt{10}$ 의 정수 부분은 $3$ 이고 $1$ 과 $3$ 사이의 정수점은 $2$ 하나뿐이다. $3\\neq1$ 이므로 라는 옳지 않다.","확인":null,"스킬":"C3","고비":true},{"제목":"옳은 것의 개수","힌트":"가, 나, 다, 라 중 옳은 것은 몇 개일까?","식":["$\\text{옳은 것}=3$"],"설명":"옳은 것은 가, 나, 다 세 개이고 선지 ④ 이다.","확인":"3","스킬":"C3"}],"fb":"fig/ns/"},"ns-0fe992946ad1":{"길":"두 직선의 기울기를 직각삼각형의 높이와 밑변의 비로 읽어 $\\overline{BD}$, $\\overline{CD}$ 를 $b$ 로 나타낸다.","단계":[{"제목":"a, b 의 관계","힌트":"$9a^2-4b^2=0$ 을 인수분해하면?","식":["$(3a+2b)(3a-2b)=0$","$a=\\frac{2}{3}b$"],"설명":"$a$, $b$ 가 양수이므로 $3a+2b>0$ 이고 $3a-2b=0$ 이다.","확인":null,"스킬":"A3"},{"제목":"기울기로 길이 나타내기","고비":true,"힌트":"직선 $l$, $m$ 의 기울기를 직각삼각형 $\\mathrm{ADC}$, $\\mathrm{ADB}$ 의 높이와 밑변의 비로 읽으면?","식":["$\\overline{\\mathrm{CD}}=\\frac{3\\sqrt{2}}{a}=\\frac{9\\sqrt{2}}{2b}$","$\\overline{\\mathrm{BD}}=\\frac{3\\sqrt{2}}{b}$"],"설명":"직선 $l$ 의 기울기는 $a=\\frac{\\overline{AD}}{\\overline{CD}}$, 직선 $m$ 의 기울기는 $-b$ 이므로 $b=\\frac{\\overline{AD}}{\\overline{BD}}$ 이다.","확인":null,"스킬":"G9"},{"제목":"b 구하기","힌트":"$\\overline{\\mathrm{BD}}\\times\\overline{\\mathrm{CD}}=\\frac{1}{2}$ 에 대입하면?","식":["$\\frac{9\\sqrt{2}}{2b}\\times\\frac{3\\sqrt{2}}{b}=\\frac{1}{2}$","$b^2=54$","$b=3\\sqrt{6}$"],"설명":"$b>0$ 이므로 양수만 취한다.","확인":null,"스킬":"A10"},{"제목":"BD, CD 구하기","힌트":"$b=3\\sqrt{6}$ 을 두 길이에 대입하면?","식":["$\\overline{\\mathrm{BD}}=\\frac{\\sqrt{3}}{3}$","$\\overline{\\mathrm{CD}}=\\frac{\\sqrt{3}}{2}$"],"설명":"분모를 유리화한다.","확인":null,"스킬":"G9"},{"제목":"BC 구하기","힌트":"$\\overline{\\mathrm{BC}}$ 는 두 선분의 합이다.","식":["$\\overline{\\mathrm{BC}}=\\frac{\\sqrt{3}}{3}+\\frac{\\sqrt{3}}{2}=\\frac{5\\sqrt{3}}{6}$"],"설명":"$\\overline{BC}=\\overline{BD}+\\overline{CD}$ 이다.","확인":null,"스킬":"G9"}],"fb":"fig/ns/"},"ns-10711049498e":{"길":"직각삼각형 면마다 삼각비로 모서리 길이를 구하고, 이등변삼각형 $\\mathrm{BDG}$ 의 높이로 $\\sin x$ 를 구한다.","단계":[{"제목":"삼각형 DGH","힌트":"$\\angle \\mathrm{DGH}=60^\\circ$ 인 직각삼각형 $\\mathrm{DGH}$ 에서 $\\overline{\\mathrm{GH}}=2$ 일 때 $\\overline{\\mathrm{GD}}$, $\\overline{\\mathrm{DH}}$ 는?","식":["$\\overline{\\mathrm{GD}}=4$","$\\overline{\\mathrm{DH}}=2\\sqrt{3}$"],"설명":"직육면체에서 $\\overline{GH}=\\overline{CD}=\\overline{AB}=2$ 이다.","확인":null,"스킬":"S6"},{"제목":"삼각형 BFG","힌트":"$\\overline{\\mathrm{BF}}=\\overline{\\mathrm{DH}}$ 이고 $\\angle \\mathrm{BGF}=45^\\circ$ 일 때 $\\overline{\\mathrm{FG}}$, $\\overline{\\mathrm{BG}}$ 는?","식":["$\\overline{\\mathrm{BF}}=\\overline{\\mathrm{FG}}=2\\sqrt{3}$","$\\overline{\\mathrm{BG}}=2\\sqrt{6}$"],"설명":"직각이등변삼각형이다.","확인":null,"스킬":"S6"},{"제목":"BD 의 길이","힌트":"밑면의 직각삼각형 $\\mathrm{BCD}$ 에서 $\\overline{\\mathrm{BD}}$ 는?","식":["$\\overline{\\mathrm{BD}}=\\sqrt{2^2+(2\\sqrt{3})^2}=4$"],"설명":"$\\overline{BC}=\\overline{FG}=2\\sqrt{3}$ 이다.","확인":"4","스킬":"S3"},{"제목":"이등변삼각형 찾기","고비":true,"힌트":"세 변 $\\overline{\\mathrm{BD}}$, $\\overline{\\mathrm{DG}}$, $\\overline{\\mathrm{BG}}$ 를 비교하면?","식":["$\\overline{\\mathrm{BD}}=\\overline{\\mathrm{DG}}=4,\\ \\overline{\\mathrm{BG}}=2\\sqrt{6}$"],"설명":"$\\triangle \\mathrm{BDG}$ 는 이등변삼각형이다. 점 $\\mathrm{D}$ 에서 $\\overline{BG}$ 에 내린 수선의 발을 $\\mathrm{I}$ 라 하면 $\\overline{BI}=\\overline{GI}=\\sqrt{6}$ 이다.","확인":null,"스킬":"S2"},{"제목":"sin x 구하기","힌트":"직각삼각형 $\\mathrm{DIG}$ 에서 $\\sin x$ 는?","식":["$\\overline{\\mathrm{DI}}=\\sqrt{4^2-(\\sqrt{6})^2}=\\sqrt{10}$","$\\sin x=\\frac{\\sqrt{10}}{4}$"],"설명":"$\\sin x=\\frac{\\overline{DI}}{\\overline{DG}}$ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-123ca9cc94ee":{"길":"접선과 현이 이루는 각, 반원의 원주각, 닮음을 써서 보기를 하나씩 확인한다.","단계":[{"제목":"㉠ 확인","고비":true,"힌트":"접선과 현이 이루는 각 $\\angle \\mathrm{ATC}$ 와 크기가 같은 원주각은?","식":["$\\angle \\mathrm{ABT}=\\angle \\mathrm{ATC}=75^\\circ$","$\\angle \\mathrm{BAT}=90^\\circ-75^\\circ=15^\\circ$"],"설명":"$\\overline{AB}$ 가 지름이므로 $\\angle \\mathrm{ATB}=90^\\circ$ 이다. ㉠ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"㉣ 확인","힌트":"원주각의 크기와 호의 길이의 관계는?","식":["$\\overset{\\frown}{\\mathrm{BT}}:\\overset{\\frown}{\\mathrm{AT}}=15^\\circ:75^\\circ=1:5$"],"설명":"호의 길이는 원주각의 크기에 비례한다. ㉣ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"㉡ 확인","힌트":"$\\triangle \\mathrm{APT}$ 에서 $\\angle \\mathrm{APT}$ 는 몇 도인가?","식":["$\\angle \\mathrm{APT}+15^\\circ=75^\\circ$","$\\angle \\mathrm{APT}=60^\\circ$"],"설명":"세 점 $\\mathrm{P}$, $\\mathrm{T}$, $\\mathrm{C}$ 가 한 직선 위에 있으므로 $\\angle \\mathrm{ATC}$ 는 $\\triangle \\mathrm{APT}$ 의 외각이고 $\\angle \\mathrm{PAT}=\\angle \\mathrm{BAT}=15^\\circ$ 이다. $65^\\circ$ 가 아니므로 ㉡ 은 옳지 않다.","확인":null,"스킬":"S10"},{"제목":"㉢ 확인","힌트":"$\\triangle \\mathrm{APT}$ 와 닮은 삼각형은?","식":["$\\triangle \\mathrm{APT}\\sim\\triangle \\mathrm{TPB}$","$\\overline{\\mathrm{PT}}^{2}=\\overline{\\mathrm{PA}}\\cdot\\overline{\\mathrm{PB}}$"],"설명":"$\\angle \\mathrm{P}$ 는 공통이고 $\\angle \\mathrm{PAT}=\\angle \\mathrm{PTB}$ 이므로 $AA$ 닮음이다. ㉢ 은 옳다.","확인":null,"스킬":"S1"},{"제목":"답 고르기","힌트":"옳은 보기를 모두 모으면?","식":["$\\text{㉠, ㉢, ㉣}$"],"설명":"㉡ 만 옳지 않다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-157481866571":{"길":"중심에서 현에 수선을 내려 현의 이등분과 피타고라스 정리를 두 번 쓴다.","단계":[{"제목":"수선의 발 잡기","고비":true,"힌트":"원의 중심 $\\mathrm{O}$ 에서 $\\overline{\\mathrm{AB}}$ 에 내린 수선의 발을 $\\mathrm{H}$ 라 하면 $\\overline{\\mathrm{AH}}$ 는?","식":["$\\overline{\\mathrm{AH}}=9$"],"설명":"원의 중심에서 현에 내린 수선은 그 현을 이등분한다.","확인":"9","스킬":"S2"},{"제목":"OH 구하기","힌트":"직각삼각형 $\\mathrm{OAH}$ 에서 $\\overline{\\mathrm{OH}}$ 는?","식":["$\\overline{\\mathrm{OH}}=\\sqrt{11^2-9^2}=2\\sqrt{10}$"],"설명":"$\\overline{OA}$ 는 큰 원의 반지름 $11$ 이다.","확인":null,"스킬":"S3"},{"제목":"CH 구하기","힌트":"$\\overline{\\mathrm{AC}}=\\overline{\\mathrm{CD}}=\\overline{\\mathrm{DB}}$ 이므로 $\\overline{\\mathrm{AC}}$ 와 $\\overline{\\mathrm{CH}}$ 는?","식":["$\\overline{\\mathrm{AC}}=6,\\ \\overline{\\mathrm{CH}}=9-6=3$"],"설명":"$\\overline{AB}=18$ 을 삼등분한다.","확인":"3","스킬":"S3"},{"제목":"OC 구하기","힌트":"직각삼각형 $\\mathrm{OCH}$ 에서 $\\overline{\\mathrm{OC}}$ 는?","식":["$\\overline{\\mathrm{OC}}=\\sqrt{(2\\sqrt{10})^2+3^2}=7$"],"설명":"피타고라스 정리를 쓴다.","확인":"7","스킬":"S3"}],"fb":"fig/ns/"},"ns-157eae40879e":{"길":"막대그래프에서 도수를 읽어 세 반의 평균과 분산을 구해 선지를 비교한다.","단계":[{"제목":"세 반의 평균","힌트":"그래프에서 읽은 도수로 세 반의 평균을 각각 구하면?","식":["$\\mathrm{A}\\text{반}=\\mathrm{B}\\text{반}=\\mathrm{C}\\text{반}=5$"],"설명":"세 반 모두 학생 수가 $10$명이고 평균이 $5$권으로 같다. ①, ④ 는 옳지 않다.","확인":null,"스킬":"P4"},{"제목":"세 반의 분산","고비":true,"힌트":"편차의 제곱에 도수를 곱해 더한 뒤 학생 수로 나누면?","식":["$\\mathrm{A}\\text{반}:\\frac{20}{10}=2$","$\\mathrm{B}\\text{반}:\\frac{26}{10}=2.6$","$\\mathrm{C}\\text{반}:\\frac{12}{10}=1.2$"],"설명":"편차는 $-2,-1,0,1,2$ 이고 도수가 반마다 다르다.","확인":null,"스킬":"P4"},{"제목":"분산 비교","힌트":"세 분산을 크기순으로 놓으면?","식":["$1.2<2<2.6$"],"설명":"분산이 가장 작은 것은 $\\mathrm{C}$반이므로 ③ 이 옳다. 표준편차는 분산의 양의 제곱근이므로 분산이 가장 큰 $\\mathrm{B}$반이 가장 크고, $\\mathrm{A}$반과 $\\mathrm{B}$반 중 분산이 더 작은 쪽은 $\\mathrm{A}$반이다.","확인":null,"스킬":"P4"}],"fb":"fig/ns/"},"ns-174dcf6bfe94":{"길":"$\\tan x$ 로 $\\sin x$, $\\cos x$ 를 구한 뒤 반지름 $15$ 인 직각삼각형에서 두 변을 구해 넓이를 낸다.","단계":[{"제목":"AD 구하기","힌트":"직각삼각형 $\\mathrm{AOD}$ 에서 $\\tan x$ 로 $\\overline{\\mathrm{AD}}$ 를 구하면?","식":["$\\overline{\\mathrm{AD}}=15\\tan x=20$"],"설명":"$\\overline{OD}=15$ 이다.","확인":"20","스킬":"S6"},{"제목":"sin x, cos x","힌트":"$\\overline{\\mathrm{AO}}$ 를 구해 $\\sin x$, $\\cos x$ 를 정하면?","식":["$\\overline{\\mathrm{AO}}=\\sqrt{20^2+15^2}=25$","$\\cos x=\\frac{3}{5},\\ \\sin x=\\frac{4}{5}$"],"설명":"피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"},{"제목":"OC, BC 구하기","고비":true,"힌트":"$\\overline{\\mathrm{OB}}=15$ 인 직각삼각형 $\\mathrm{BOC}$ 에서 $\\overline{\\mathrm{OC}}$, $\\overline{\\mathrm{BC}}$ 는?","식":["$\\overline{\\mathrm{OC}}=15\\cos x=9$","$\\overline{\\mathrm{BC}}=15\\sin x=12$"],"설명":"점 $\\mathrm{B}$ 는 반지름 $15$ 인 원 위의 점이다.","확인":null,"스킬":"S6"},{"제목":"AE, BE 구하기","힌트":"점 $\\mathrm{B}$ 에서 $x$축과 평행하게 그은 선이 $\\overline{\\mathrm{AD}}$ 와 만나는 점을 $\\mathrm{E}$ 라 하면 $\\overline{\\mathrm{AE}}$, $\\overline{\\mathrm{BE}}$ 는?","식":["$\\overline{\\mathrm{AE}}=20-12=8$","$\\overline{\\mathrm{BE}}=15-9=6$"],"설명":"$\\overline{AE}=\\overline{AD}-\\overline{BC}$, $\\overline{BE}=\\overline{OD}-\\overline{OC}$ 이다.","확인":null,"스킬":"S4"},{"제목":"넓이 구하기","힌트":"직각삼각형 $\\mathrm{ABE}$ 의 넓이는?","식":["$\\triangle \\mathrm{ABE}=\\frac{1}{2}\\times6\\times8=24$"],"설명":"직각을 낀 두 변이 밑변과 높이이다.","확인":"24","스킬":"S8"}],"fb":"fig/ns/"},"ns-1f7049cd1f60":{"길":"세 변의 비를 한 문자로 나타내고, 직사각형의 세로 AD를 두 직각삼각형의 삼각비로 나눠 구한다","단계":[{"제목":"직각삼각형 ABC의 변의 비","힌트":"$\\overline{BC}=a$로 놓으면 $\\overline{AC}$, $\\overline{AB}$는 각각 얼마인가?","식":["$\\overline{AC}=\\sqrt{3}a$","$\\overline{AB}=2a$"],"설명":"$\\angle B=60^\\circ$, $\\angle C=90^\\circ$이므로 $\\angle A=30^\\circ$이고 세 변의 비는 $1:\\sqrt{3}:2$이다.","확인":null,"스킬":"S6","고비":false},{"제목":"FC의 길이","힌트":"직각삼각형 $\\mathrm{ACF}$에서 $\\angle \\mathrm{FAC}=45^\\circ$를 쓰면 $\\overline{FC}$는?","식":["$\\overline{FC}=\\overline{AC}\\sin45^\\circ=\\frac{\\sqrt{6}}{2}a$"],"설명":"$\\triangle \\mathrm{ACF}$는 $\\angle \\mathrm{F}=90^\\circ$인 직각삼각형이다. 빗변이 $\\overline{AC}$이므로 $\\overline{FC}$는 $\\overline{AC}$에 $\\sin45^\\circ$를 곱한 값이다.","확인":null,"스킬":"S6","고비":false},{"제목":"CE의 길이","힌트":"점 C에서 일직선 위의 각을 따라가면 $\\angle \\mathrm{BCE}$는 몇 도인가?","식":["$\\angle \\mathrm{BCE}=45^\\circ$","$\\overline{CE}=\\overline{BC}\\cos45^\\circ=\\frac{\\sqrt{2}}{2}a$"],"설명":"변 $\\mathrm{FE}$ 위의 점 C에서 $180^\\circ$가 $\\angle \\mathrm{ACF}=45^\\circ$, $\\angle \\mathrm{ACB}=90^\\circ$, $\\angle \\mathrm{BCE}$로 나뉘므로 $\\angle \\mathrm{BCE}=45^\\circ$이다. E는 직사각형의 꼭짓점이라 $\\angle \\mathrm{BEC}=90^\\circ$이다.","확인":null,"스킬":"S10","고비":true},{"제목":"cos x의 값","힌트":"$\\overline{AD}=\\overline{FE}$이므로 $\\cos x=\\frac{\\overline{AD}}{\\overline{AB}}$를 구하면?","식":["$\\overline{AD}=\\overline{FC}+\\overline{CE}=\\frac{\\sqrt{6}+\\sqrt{2}}{2}a$","$\\cos x=\\frac{\\sqrt{6}+\\sqrt{2}}{4}$"],"설명":"직사각형의 마주 보는 변이므로 $\\overline{AD}=\\overline{FE}$이다. $\\triangle \\mathrm{ABD}$는 $\\angle \\mathrm{D}=90^\\circ$이므로 $\\cos x$는 $\\overline{AD}$를 $\\overline{AB}=2a$로 나눈 값이다.","확인":null,"스킬":"S6","고비":false}],"fb":"fig/ns/"},"ns-20bb294fa36b":{"길":"접선과 반지름의 직각으로 직각삼각형을 만들고, 중심에서 현에 내린 수선으로 닮음과 피타고라스를 이어 쓴다","단계":[{"제목":"접점에서의 직각삼각형","힌트":"원 P의 반지름 $\\overline{PT}$와 접선 $\\overline{AT}$는 어떤 관계인가? $\\overline{AP}$는 얼마인가?","식":["$\\angle \\mathrm{ATP}=90^\\circ$","$\\overline{AP}=25,\\ \\overline{PT}=5$"],"설명":"접선은 접점을 지나는 반지름과 수직이다. 세 원의 지름은 모두 $10$이므로 반지름은 $5$이고, $\\overline{AP}=30-5$이다.","확인":null,"스킬":"S5","고비":false},{"제목":"닮은 삼각형 찾기","힌트":"원 N의 중심에서 직선 AT에 내린 수선의 발을 H라 하자. $\\triangle \\mathrm{AHN}$과 닮은 삼각형은?","식":["$\\triangle \\mathrm{AHN}\\sim\\triangle \\mathrm{ATP}$","$\\overline{AN}:\\overline{AP}=\\overline{HN}:\\overline{TP}$"],"설명":"두 삼각형은 $\\angle \\mathrm{A}$를 공유하고 $\\angle \\mathrm{AHN}=\\angle \\mathrm{ATP}=90^\\circ$이므로 AA 닮음이다. 점 H는 중심 N에서 현 EF에 내린 수선의 발이기도 하다.","확인":null,"스킬":"S2","고비":true},{"제목":"HN의 길이","힌트":"$\\overline{AN}=15$, $\\overline{AP}=25$, $\\overline{TP}=5$를 닮음비에 넣으면 $\\overline{HN}$은?","식":["$15:25=\\overline{HN}:5$","$\\overline{HN}=3$"],"설명":"N은 $\\overline{BC}$의 중점이므로 $\\overline{AN}=\\overline{AB}+\\overline{BN}=10+5=15$이고, $\\overline{TP}$는 원 P의 반지름 $5$이다.","확인":"3","스킬":"S1","고비":false},{"제목":"EF의 길이","힌트":"$\\overline{EN}$은 원 N의 반지름이다. $\\triangle \\mathrm{EHN}$에서 $\\overline{EH}$를 구하면?","식":["$\\overline{EH}=\\sqrt{5^2-3^2}=4$","$\\overline{EF}=2\\overline{EH}=8$"],"설명":"원의 중심에서 현에 내린 수선은 그 현을 이등분하므로 $\\overline{EF}=2\\overline{EH}$이다.","확인":"8","스킬":"S3","고비":false}],"fb":"fig/ns/"},"ns-2ad31db8a3b2":{"길":"네 동심원의 넓이를 가장 작은 반지름 x로 나타내 조건식을 세운다","단계":[{"제목":"가장 작은 반지름으로 놓기","힌트":"네 원의 반지름 비가 1:2:3:4이므로 가장 작은 반지름을 x라 하면?","식":["$r=x,\\ 2x,\\ 3x,\\ 4x$"],"설명":"네 원의 반지름을 가장 작은 원의 반지름 x의 배수로 나타낸다.","확인":null,"스킬":"A8"},{"제목":"회색 부분 넓이 구하기","힌트":"네 번째-세 번째, 두 번째-첫 번째 고리의 넓이를 더하면?","식":["$\\pi(4x)^2-\\pi(3x)^2+\\pi(2x)^2-\\pi x^2=10\\pi x^2$"],"설명":"회색으로 칠해진 두 고리의 넓이를 더해 정리한다.","확인":null,"스킬":"A8"},{"제목":"빗금 부분 넓이 구하기","힌트":"세 번째-두 번째 고리와 가장 안쪽 원의 넓이를 더하면?","식":["$\\pi(3x)^2-\\pi(2x)^2+\\pi x^2=6\\pi x^2$"],"설명":"빗금 쳐진 두 부분의 넓이를 더해 정리한다.","확인":null,"스킬":"A8"},{"제목":"조건식을 세워 x와 지름 구하기","고비":true,"힌트":"두 넓이의 차가 16π라는 조건으로 x를 구하면?","식":["$10\\pi x^2-6\\pi x^2=16\\pi\\Rightarrow x=2$","$2\\times(2\\times4)=16$"],"설명":"넓이 차 조건으로 x=2를 구하고, 가장 큰 원의 지름을 계산한다.","확인":"16","스킬":"C7"}],"fb":"fig/ns/"},"ns-2b8ef819d9f6":{"길":"회전각과 반지름으로 호의 길이를 세워 a를 구하고, 점 A를 기준으로 T의 좌표를 읽는다","단계":[{"제목":"AC와 회전각","힌트":"직각이등변삼각형에서 $\\overline{AC}$는? 점 C가 움직인 각 $\\angle \\mathrm{TAC}$는 몇 도인가?","식":["$\\overline{AC}=5\\sqrt{2}$","$\\angle \\mathrm{TAC}=135^\\circ$"],"설명":"$\\angle \\mathrm{CAB}=45^\\circ$이다. 반직선 AC를 수직선의 왼쪽 방향까지 돌리면 $180^\\circ-45^\\circ$만큼 돈 것이다.","확인":null,"스킬":"S10","고비":true},{"제목":"호의 길이로 a 구하기","힌트":"반지름 $\\overline{AC}$, 중심각 $135^\\circ$인 호의 길이를 $\\frac{3\\sqrt{a}}{4}\\pi$와 비교하면?","식":["$\\overset{\\frown}{\\mathrm{TC}}=2\\pi\\times5\\sqrt{2}\\times\\frac{135}{360}=\\frac{15\\sqrt{2}}{4}\\pi$","$\\sqrt{a}=5\\sqrt{2}$이므로 $a=50$"],"설명":"$\\frac{3\\sqrt{a}}{4}=\\frac{15\\sqrt{2}}{4}$에서 $\\sqrt{a}=5\\sqrt{2}=\\sqrt{50}$이다.","확인":"50","스킬":"S10","고비":false},{"제목":"점 T의 좌표","힌트":"B의 좌표가 $10$, $\\overline{AB}=5$이므로 A의 좌표는? T는 A에서 왼쪽으로 얼마 떨어져 있는가?","식":["A의 좌표는 $5$","$\\mathrm{T}=5-5\\sqrt{2}=5-\\sqrt{50}$"],"설명":"점 T는 점 C가 돌아온 자리이므로 $\\overline{AT}=\\overline{AC}=5\\sqrt{2}$이다. 따라서 $b=5,\\ c=-1$이다.","확인":null,"스킬":"S10","고비":false},{"제목":"a+b-c의 값","힌트":"$a=50,\\ b=5,\\ c=-1$을 대입하면?","식":["$a+b-c=50+5-(-1)=56$"],"설명":"$c$가 음수이므로 빼는 부호에 주의한다.","확인":"56","스킬":"S10","고비":false}],"fb":"fig/ns/"},"ns-2bed9f8ea505":{"길":"반지름이 같음과 현의 수직이등분선, 피타고라스 정리로 보기를 하나씩 따져 본다","단계":[{"제목":"반지름이 만드는 삼각형","힌트":"$\\overline{OA}$, $\\overline{OB}$, $\\overline{OC}$ 사이에는 어떤 관계가 있는가?","식":["$\\overline{OA}=\\overline{OB}=\\overline{OC}$"],"설명":"세 선분은 모두 원 $O$ 의 반지름이므로 길이가 같다. 따라서 $\\triangle OAB$ 와 $\\triangle OCB$ 는 두 변의 길이가 같은 이등변삼각형이다. 경진의 말은 옳다.","확인":null,"스킬":"S5"},{"제목":"$\\overline{AB}$ 의 길이","힌트":"$\\overline{OC}\\perp\\overline{AB}$ 일 때 점 $D$ 는 $\\overline{AB}$ 위에서 어떤 점인가?","식":["$\\overline{DB}=\\sqrt{(3\\sqrt{2})^{2}-2^{2}}$","$\\overline{AB}=2\\overline{DB}$"],"설명":"원의 중심에서 현에 내린 수선은 그 현을 수직이등분하므로 $\\overline{AD}=\\overline{DB}$ 이다. $\\triangle BCD$ 는 $\\angle D=90^{\\circ}$ 이므로 피타고라스 정리에서 $\\overline{DB}=\\sqrt{14}$ 이고 $\\overline{AB}=2\\sqrt{14}\\,\\mathrm{cm}$ 이다. 진호의 말은 옳지 않다.","확인":null,"스킬":"S3"},{"제목":"원의 지름","힌트":"반지름을 $r$ 로 놓으면 $\\triangle OBD$ 의 세 변은 어떻게 나타나는가?","식":["$\\overline{OD}=r-2$","$r^{2}=(r-2)^{2}+(\\sqrt{14})^{2}$","$4r=18$"],"설명":"$\\overline{OB}=r$, $\\overline{OD}=r-2$ 이고 $\\triangle OBD$ 는 $\\angle D=90^{\\circ}$ 이므로 피타고라스 정리를 쓰면 $4r=18$ 이다. 따라서 $r=\\frac{9}{2}$ 이고 지름은 $9\\,\\mathrm{cm}$ 이다. 나라의 말은 옳다.","확인":"9","스킬":"S3","고비":true},{"제목":"나머지 두 말 판정","힌트":"$\\triangle BCD$ 의 변의 비와 두 삼각형의 높이의 비는 어떻게 되는가?","식":["$\\overline{DC}:\\overline{DB}=2:\\sqrt{14}$","$\\triangle OAB:\\triangle CAB=\\overline{OD}:\\overline{CD}=\\frac{5}{2}:2$"],"설명":"$\\angle DBC=30^{\\circ}$ 이려면 $\\overline{DC}:\\overline{DB}=1:\\sqrt{3}$ 이어야 하는데 $2:\\sqrt{14}$ 이므로 승미의 말은 옳지 않다. $\\triangle OAB$ 와 $\\triangle CAB$ 는 밑변 $AB$ 가 같고 높이가 $\\overline{OD}=\\frac{5}{2}$, $\\overline{CD}=2$ 이므로 넓이의 비가 $5:4$ 이다. 소원의 말도 옳지 않다. 옳은 말을 한 사람은 경진과 나라이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-2d190623a43a":{"길":"지름의 원주각, 접선과 현이 이루는 각, 외각, 호의 비례를 보기마다 쓴다","단계":[{"제목":"ㄱ 의 판정","힌트":"지름 $AB$ 에 대한 원주각과 접선과 현이 이루는 각을 어떻게 쓰는가?","식":["$\\angle ATB=90^{\\circ}$","$\\angle ABT=\\angle ATP=35^{\\circ}$","$\\angle BAT=180^{\\circ}-90^{\\circ}-35^{\\circ}$"],"설명":"$\\overline{AB}$ 가 지름이므로 $\\angle ATB=90^{\\circ}$ 이다. 접선과 현이 이루는 각 $\\angle ATP$ 는 호 $AT$ 에 대한 원주각 $\\angle ABT$ 와 같아 $35^{\\circ}$ 이다. $\\triangle ABT$ 에서 $\\angle BAT=55^{\\circ}$ 이므로 ㄱ 은 옳다.","확인":"55","스킬":"S5","고비":true},{"제목":"ㄴ 의 판정","힌트":"$\\angle BAT$ 는 $\\triangle APT$ 에서 어떤 각인가?","식":["$\\angle BAT=\\angle APT+\\angle ATP$"],"설명":"세 점 $P$, $A$, $B$ 가 한 직선 위에 있으므로 $\\angle BAT$ 는 $\\triangle APT$ 의 꼭짓점 $A$ 에서의 외각이다. 삼각형의 외각의 성질에서 $\\angle APT=55^{\\circ}-35^{\\circ}=20^{\\circ}$ 이므로 ㄴ 은 옳지 않다.","확인":"20","스킬":"S10"},{"제목":"ㄷ 의 판정","힌트":"$\\triangle PAT$ 와 $\\triangle PTB$ 에서 크기가 같은 두 각은 어느 것인가?","식":["$\\angle P$ 는 공통","$\\angle PTA=\\angle PBT$"],"설명":"$\\angle P$ 가 공통이고 $\\angle PTA=35^{\\circ}=\\angle PBT$ 이므로 AA 닮음이다. ㄷ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄹ 의 판정","힌트":"한 원에서 호의 길이와 원주각의 크기 사이에는 어떤 관계가 있는가?","식":["$\\overset{\\frown}{BT}:\\overset{\\frown}{AT}=\\angle BAT:\\angle ABT$","$=55:35$"],"설명":"호의 길이는 그 호에 대한 원주각에 정비례한다. 호 $BT$ 에 대한 원주각은 $\\angle BAT=55^{\\circ}$, 호 $AT$ 에 대한 원주각은 $\\angle ABT=35^{\\circ}$ 이므로 호의 비는 $55:35=11:7$ 이다. ㄹ 은 옳다. 따라서 옳은 것은 ㄱ, ㄷ, ㄹ 이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-2edb372559cc":{"길":"대각선 길이를 수직선 위의 좌표로 바꾼 뒤 보기마다 길이를 직접 계산해 참거짓을 가른다","단계":[{"제목":"P와 Q의 좌표","힌트":"정사각형의 대각선 길이는? A의 좌표 $1$, B의 좌표 $2$일 때 P와 Q의 좌표는?","식":["$\\overline{AC}=\\overline{BD}=\\sqrt{2}$","$\\mathrm{P}(2-\\sqrt{2})$, $\\mathrm{Q}(1+\\sqrt{2})$"],"설명":"점 P는 B에서 왼쪽으로 $\\overline{BP}=\\sqrt{2}$, 점 Q는 A에서 오른쪽으로 $\\overline{AQ}=\\sqrt{2}$ 떨어진 점이다.","확인":null,"스킬":"S4","고비":true},{"제목":"가와 라 확인","힌트":"가의 P의 좌표와 라의 $\\overline{BD}$를 앞 단계 결과와 비교하면?","식":["$\\mathrm{P}(2-\\sqrt{2})$","$\\overline{BD}=\\sqrt{2}$"],"설명":"가와 라는 앞에서 구한 값과 같으므로 옳다.","확인":null,"스킬":"C3","고비":false},{"제목":"나와 다 확인","힌트":"두 점 사이의 거리는 큰 좌표에서 작은 좌표를 빼면 되는가? $\\overline{PA}$, $\\overline{PQ}$는?","식":["$\\overline{PA}=1-(2-\\sqrt{2})=\\sqrt{2}-1$","$\\overline{PQ}=(1+\\sqrt{2})-(2-\\sqrt{2})=2\\sqrt{2}-1$"],"설명":"나는 옳다. 다는 $2\\sqrt{2}+1$이라 했으므로 옳지 않다.","확인":null,"스킬":"S4","고비":false},{"제목":"옳은 보기","힌트":"옳은 보기를 모두 모으면?","식":["가, 나, 라"],"설명":"가, 나, 라가 옳으므로 선지 ①이다.","확인":null,"스킬":"C3","고비":false}],"fb":"fig/ns/"},"ns-39bb6484b76c":{"길":"D가 원 위에 있을 때의 각을 기준으로 삼고, D가 활꼴 안쪽으로 들어오면 각이 어떻게 변하는지 따진다","단계":[{"제목":"원 위에 있을 때의 각","힌트":"D가 원 위에 있다면 사각형 ABCD는 원에 내접한다. 이때 $\\angle \\mathrm{ADC}$는?","식":["$\\angle \\mathrm{ADC}+\\angle \\mathrm{ABC}=180^\\circ$","$\\angle \\mathrm{ADC}=100^\\circ$"],"설명":"원에 내접하는 사각형은 마주 보는 두 각의 합이 $180^\\circ$이다.","확인":"100","스킬":"S5","고비":false},{"제목":"안쪽 점에서의 각","힌트":"D가 활꼴 안쪽으로 들어오면 현 AC를 보는 각은 커지는가, 작아지는가?","식":["$\\angle \\mathrm{ADC}>100^\\circ$"],"설명":"원 안쪽의 점에서 한 현을 바라본 각은 같은 쪽 원주 위의 점에서 본 각보다 크다.","확인":null,"스킬":"S15","고비":true},{"제목":"될 수 없는 각","힌트":"보기 중 $100^\\circ$보다 크지 않은 것은?","식":["$110^\\circ,\\ 120^\\circ,\\ 125^\\circ,\\ 130^\\circ$는 모두 $100^\\circ$보다 크다"],"설명":"$\\angle \\mathrm{ADC}$는 $100^\\circ$가 될 수 없다.","확인":"100","스킬":"S5","고비":false}],"fb":"fig/ns/"},"ns-3a319242eb5e":{"길":"점 P의 좌표를 문자로 두고, 색칠한 부분을 큰 삼각형에서 직사각형을 뺀 넓이로 세워 방정식을 푼 뒤 두 삼각형의 넓이를 비교한다","단계":[{"제목":"점 P의 좌표","힌트":"P는 $y=2x$ 위의 점이다. 한 문자로 좌표를 쓰고 $\\overline{PQ}$, $\\overline{QC}$를 나타내면?","식":["$\\mathrm{P}(a,\\ 2a)$","$\\overline{PQ}=2a,\\ \\overline{QC}=10-a$"],"설명":"점 Q의 $x$좌표는 $a$, 점 C의 $x$좌표는 $10$이다.","확인":null,"스킬":"S4","고비":false},{"제목":"넓이로 식 세우기","힌트":"색칠한 부분은 삼각형 OAC에서 어느 도형을 뺀 것인가?","식":["$\\triangle \\mathrm{OAC}=\\frac12\\times10\\times20=100$","$52=100-2a(10-a)$"],"설명":"색칠하지 않은 부분은 직사각형 PQCR이고 가로 $10-a$, 세로 $2a$이다.","확인":null,"스킬":"S12","고비":true},{"제목":"a의 값","힌트":"식을 정리해 인수분해하면? $\\overline{OQ}<\\overline{QC}$는 $a$의 범위를 어떻게 정하는가?","식":["$a^2-10a+24=0$","$(a-4)(a-6)=0$"],"설명":"$\\overline{OQ}=a<\\overline{QC}=10-a$이므로 $a<5$이다. 따라서 $a=4$이다.","확인":"4","스킬":"S4","고비":false},{"제목":"넓이의 비","힌트":"$a=4$일 때 $\\triangle \\mathrm{POQ}$와 $\\triangle \\mathrm{APR}$의 넓이는?","식":["$\\triangle \\mathrm{POQ}=\\frac12\\times4\\times8=16$","$\\triangle \\mathrm{APR}=\\frac12\\times6\\times12=36$","$16:36=4:9$"],"설명":"$\\overline{PR}=10-4=6$, $\\overline{AR}=20-8=12$이다.","확인":null,"스킬":"S12","고비":false}],"fb":"fig/ns/"},"ns-3a9ccc4ab707":{"길":"사각형이 원에 내접하기 위한 조건을 각의 조건과 선분 길이의 조건으로 나눠 보기마다 확인한다","단계":[{"제목":"각에 대한 조건","힌트":"ㄱ, ㄴ, ㅂ, ㅅ, ㅇ에서 원에 내접할 조건이 되는 각의 관계는?","식":["ㄱ, ㅂ, ㅅ은 조건이 된다","ㄴ, ㅇ은 조건이 되지 않는다"],"설명":"마주 보는 두 각의 합이 $180^\\circ$이면 내접한다(ㄱ). 한 변을 같은 쪽에서 본 두 각이 같으면 네 점이 한 원 위에 있다(ㅂ은 $\\angle \\mathrm{BAC}=\\angle \\mathrm{BDC}$, ㅅ은 $\\angle \\mathrm{ABD}=\\angle \\mathrm{ACD}$). 대각의 크기가 같은 것만으로는 부족하고(ㄴ), ㅇ은 같은 호에 대한 원주각이 아니다.","확인":null,"스킬":"S5","고비":true},{"제목":"선분 길이에 대한 조건","힌트":"ㄷ, ㄹ, ㅁ에서 선분의 길이로 내접을 판단할 수 있는 것은?","식":["ㄹ만 조건이 된다"],"설명":"$\\overline{PA}\\times\\overline{PC}=\\overline{PB}\\times\\overline{PD}$이면 네 점이 한 원 위에 있다(ㄹ). ㄷ은 선분의 길이가 같은지 알 수 없고, ㅁ은 원에 외접하는 조건이다.","확인":null,"스킬":"C3","고비":false},{"제목":"개수 세기","힌트":"조건이 되는 것은 모두 몇 개인가?","식":["ㄱ, ㄹ, ㅂ, ㅅ $\\to$ $4$개"],"설명":"선지 ③이 $4$개이다.","확인":"4","스킬":"C3","고비":false}],"fb":"fig/ns/"},"ns-431d82366499":{"길":"수선의 발이 만드는 직각을 이용해 같은 선분을 보는 각이 같거나 마주 보는 두 각의 합이 $180^\\circ$인 네 점을 찾는다","단계":[{"제목":"같은 쪽에서 본 직각","힌트":"선분 AB, 선분 AC를 두 직각이 같은 쪽에서 보는 경우는 어느 네 점인가?","식":["$\\angle \\mathrm{AP}_1\\mathrm{B}=\\angle \\mathrm{AP}_2\\mathrm{B}=90^\\circ$","$\\angle \\mathrm{AP}_3\\mathrm{C}=\\angle \\mathrm{AP}_1\\mathrm{C}=90^\\circ$"],"설명":"$\\mathrm{P}_1$은 A에서 $\\overline{BC}$에 내린 수선의 발, $\\mathrm{P}_2$는 B에서 $\\overline{CA}$에 내린 수선의 발, $\\mathrm{P}_3$은 C에서 $\\overline{AB}$에 내린 수선의 발이다. 한 변을 같은 쪽에서 본 두 각이 같으므로 ㉠과 ㉥의 네 점은 각각 한 원 위에 있다.","확인":null,"스킬":"S15","고비":true},{"제목":"마주 보는 두 각의 합","힌트":"사각형 $\\mathrm{AP}_3\\mathrm{P}_4\\mathrm{P}_2$에서 마주 보는 두 각은 몇 도인가?","식":["$\\angle \\mathrm{AP}_3\\mathrm{P}_4+\\angle \\mathrm{AP}_2\\mathrm{P}_4=90^\\circ+90^\\circ=180^\\circ$"],"설명":"$\\mathrm{P}_4$는 $\\overline{CP_3}$ 위에도, $\\overline{BP_2}$ 위에도 있으므로 두 각이 모두 직각이다. 마주 보는 두 각의 합이 $180^\\circ$이면 원에 내접하므로 ㉢도 한 원 위에 있다.","확인":null,"스킬":"S5","고비":false},{"제목":"해당하는 보기","힌트":"나머지 ㉡, ㉣, ㉤은 위와 같은 각의 조건이 성립하는가?","식":["$㉠, ㉢, ㉥$"],"설명":"㉡, ㉣, ㉤은 같은 각이나 합이 $180^\\circ$인 각의 짝이 없으므로 선지 ③이다.","확인":null,"스킬":"S15","고비":false}],"fb":"fig/ns/"},"ns-450bd32fa556":{"길":"가로와 세로를 각각 인수분해해 타일의 한 변 n+1이 들어 있는 인수를 찾고, 남는 인수의 곱을 구한다","단계":[{"제목":"가로의 인수분해","힌트":"$2n^3-n^2-2n+1$을 공통인수로 묶어 인수분해하면?","식":["$2n^3-n^2-2n+1=n^2(2n-1)-(2n-1)$","$=(n+1)(n-1)(2n-1)$"],"설명":"$(2n-1)$로 묶으면 $(n^2-1)(2n-1)$이고, $n^2-1$은 곱셈 공식으로 인수분해한다.","확인":null,"스킬":"N1","고비":true},{"제목":"세로의 인수분해","힌트":"$n^2+4n+3$을 인수분해하면?","식":["$n^2+4n+3=(n+1)(n+3)$"],"설명":"합이 $4$, 곱이 $3$인 두 수는 $1$과 $3$이다.","확인":null,"스킬":"N1","고비":false},{"제목":"타일의 개수","힌트":"한 변이 $n+1$인 타일은 가로와 세로에 각각 몇 개씩 들어가는가?","식":["가로 $(n-1)(2n-1)$개, 세로 $(n+3)$개","$(n-1)(2n-1)(n+3)$"],"설명":"가로와 세로를 $n+1$로 나눈 몫이 각각 가로와 세로에 놓이는 개수이다.","확인":null,"스킬":"N1","고비":false}],"fb":"fig/ns/"},"ns-47366108a11b":{"길":"큰 반원 넓이에서 두 작은 반원 넓이를 뺀 값이 색칠한 넓이임을 이용해 AC 에 관한 방정식을 세운다","단계":[{"제목":"세 반원의 넓이 나타내기","힌트":"AC 를 문자로 놓으면 지름이 AB, AC, CB 인 세 반원의 넓이는 각각 어떻게 쓸까?","식":["$\\frac12\\times\\pi\\times10^{2}=50\\pi$","$\\frac12\\times\\pi\\times\\left(\\frac{x}{2}\\right)^{2}=\\frac{x^{2}}{8}\\pi$","$\\frac12\\times\\pi\\times\\left(\\frac{20-x}{2}\\right)^{2}=\\frac{(20-x)^{2}}{8}\\pi$"],"설명":"$\\overline{AC}=x$ 라 하면 $\\overline{CB}=20-x$ 이다. 반원의 넓이는 반지름의 제곱에 $\\pi$ 를 곱해 절반으로 한 값이다.","확인":null,"스킬":"S12"},{"제목":"색칠한 부분의 넓이로 식 세우기","힌트":"색칠한 부분은 큰 반원에서 어느 도형들을 빼면 될까?","식":["$50\\pi-\\frac{x^{2}}{8}\\pi-\\frac{(20-x)^{2}}{8}\\pi=24\\pi$"],"설명":"색칠한 부분은 지름이 $\\overline{AB}$ 인 반원에서 나머지 두 반원을 뺀 것이므로 이 넓이가 $24\\pi$ 와 같다고 놓는다.","확인":null,"스킬":"C7","고비":true},{"제목":"이차방정식 풀고 조건 확인","힌트":"양변을 정리하면 x 에 관한 어떤 방정식이 될까?","식":["$x^{2}-20x+96=0$","$(x-12)(x-8)=0$"],"설명":"$x=8$ 또는 $x=12$ 이다. $\\overline{AC}>\\overline{CB}$ 이므로 $\\overline{AC}$ 가 더 긴 쪽인 $x=12$ 를 택한다.","확인":"12","스킬":"S12"}],"fb":"fig/ns/"},"ns-48d7dea2cf8b":{"길":"정사각형에서 바깥 삼각형을 빼 삼각형 BEF 의 넓이를 구하고, 두 변과 끼인각으로 쓴 넓이 식과 맞춘다","단계":[{"제목":"BE, BF 의 길이 구하기","힌트":"한 변을 2a 라 하면 BE, BF 는 어느 직각삼각형에서 구할까?","식":["$\\overline{BE}=\\sqrt{a^{2}+(2a)^{2}}=\\sqrt5a$","$\\overline{BF}=\\sqrt{(2a)^{2}+a^{2}}=\\sqrt5a$"],"설명":"$E$, $F$ 가 중점이므로 $\\overline{AE}=\\overline{ED}=\\overline{CF}=\\overline{FD}=a$ 이다. 직각삼각형 $ABE$, $BCF$ 에서 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"},{"제목":"삼각형 BEF 의 넓이","힌트":"정사각형에서 삼각형 BEF 바깥의 세 삼각형을 빼면 넓이는 얼마일까?","식":["$\\triangle BEF=(2a)^{2}-2\\times\\left(\\frac12\\times2a\\times a\\right)-\\frac12\\times a\\times a$","$=\\frac32a^{2}$"],"설명":"바깥의 세 삼각형은 $ABE$, $BCF$ 두 개와 $EDF$ 하나이다.","확인":null,"스킬":"S12"},{"제목":"두 변과 끼인각으로 넓이 쓰기","힌트":"두 변 BE, BF 와 끼인각 x 로 같은 삼각형의 넓이를 나타내면?","식":["$\\frac12\\times\\sqrt5a\\times\\sqrt5a\\times\\sin x=\\frac32a^{2}$","$\\sin x=\\frac35$"],"설명":"삼각형의 넓이는 두 변의 길이와 그 끼인각의 사인값의 곱의 절반이다. 앞 단계의 넓이와 같다고 놓는다.","확인":"3/5","스킬":"S8","고비":true}],"fb":"fig/ns/"},"ns-54c2eef8328e":{"길":"외심에서 변에 내린 수선으로 만든 30° 직각삼각형을 이용해 선지의 길이와 넓이를 하나씩 확인한다","단계":[{"제목":"변의 길이 AC 구하기","힌트":"원의 중심 O 에서 AC 에 수선을 내리면 어떤 직각삼각형이 생길까?","식":["$\\overline{CM}=6\\cos30^{\\circ}=3\\sqrt3$","$\\overline{AC}=2\\overline{CM}=6\\sqrt3$"],"설명":"$O$ 에서 $\\overline{AC}$ 에 내린 수선의 발을 $M$ 이라 하자. 정삼각형에서는 외심이 각을 이등분하므로 직각삼각형 $OCM$ 에서 $\\angle OCM=30^{\\circ}$ 이고, 수선은 현을 이등분한다.","확인":null,"스킬":"S6"},{"제목":"정삼각형 ABC 의 넓이","힌트":"한 변이 $6\\sqrt3$ 인 정삼각형의 넓이는?","식":["$\\triangle ABC=\\frac{\\sqrt3}{4}\\times(6\\sqrt3)^{2}=27\\sqrt3$"],"설명":"한 변이 $a$ 인 정삼각형의 넓이는 $\\frac{\\sqrt3}{4}a^{2}$ 이다.","확인":null,"스킬":"S6"},{"제목":"삼각형 OCA 의 넓이","힌트":"외심이 정삼각형의 중심이면 삼각형 OCA 는 삼각형 ABC 의 몇 분의 몇일까?","식":["$\\triangle OCA=\\frac13\\triangle ABC=9\\sqrt3$"],"설명":"정삼각형의 외심은 무게중심과 같아 세 삼각형 $OAB$, $OBC$, $OCA$ 의 넓이가 같다. 따라서 선지 ③ 의 $18\\sqrt3$ 은 맞지 않다.","확인":null,"스킬":"S7","고비":true},{"제목":"나머지 선지 확인","힌트":"중심각과 원주각의 관계, 직각삼각형 ONC 로 나머지 선지를 확인하면?","식":["$\\angle AOB=2\\angle ACB=120^{\\circ}$","$\\overline{ON}=6\\sin30^{\\circ}=3$"],"설명":"$\\overline{BC}$ 에 내린 수선의 발을 $N$ 이라 하면 $\\angle OCN=30^{\\circ}$ 이다. 나머지 선지는 모두 맞으므로 옳지 않은 것은 ③ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-58a4fda9b2ad":{"길":"꼭짓점 A 에서 밑면 BCD 에 수선을 내려 직각삼각형을 만들고 tan 를 변의 비로 구한다","단계":[{"제목":"AE, DE 의 길이","힌트":"정삼각형의 높이는 한 변의 길이의 몇 배일까?","식":["$\\overline{AE}=\\overline{ED}=\\frac{\\sqrt3}{2}\\times2=\\sqrt3$"],"설명":"$\\overline{AE}$, $\\overline{ED}$ 는 한 변이 $2$ 인 정삼각형 $ABC$, $BCD$ 의 높이이다.","확인":null,"스킬":"S3"},{"제목":"수선의 발 H 의 위치","힌트":"A 에서 밑면 BCD 에 내린 수선의 발은 정삼각형 BCD 의 어떤 점일까?","식":["$\\overline{EH}=\\frac13\\overline{DE}=\\frac{\\sqrt3}{3}$"],"설명":"$A$ 에서 $\\overline{ED}$ 에 내린 수선의 발을 $H$ 라 하자. 정사면체에서 $A$ 에서 밑면에 내린 수선의 발은 정삼각형 $BCD$ 의 무게중심이므로 $H$ 는 중선 $\\overline{ED}$ 를 $2:1$ 로 나누는 점이다.","확인":null,"스킬":"S7","고비":true},{"제목":"높이 AH 구하기","힌트":"직각삼각형 AEH 에서 AE 와 EH 를 알면 AH 는?","식":["$\\overline{AH}=\\sqrt{(\\sqrt3)^{2}-\\left(\\frac{\\sqrt3}{3}\\right)^{2}}=\\frac{2\\sqrt6}{3}$"],"설명":"$\\overline{AH}$ 는 밑면에 수직이므로 $\\triangle AEH$ 는 $\\angle AHE=90^{\\circ}$ 인 직각삼각형이다.","확인":null,"스킬":"S3"},{"제목":"tan x 구하기","힌트":"x 는 직각삼각형 AEH 의 어느 각일까?","식":["$\\tan x=\\frac{\\overline{AH}}{\\overline{EH}}=\\frac{2\\sqrt6}{3}\\times\\sqrt3=2\\sqrt2$"],"설명":"$H$ 가 선분 $ED$ 위에 있으므로 $\\angle AED=\\angle AEH=x$ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-5b32517af903":{"길":"단가와 판매량의 직선 식을 구하고, 매출액을 단가의 이차식으로 나타내 꼭짓점을 찾는다","단계":[{"제목":"판매량의 직선 식","힌트":"그래프가 직선이므로 y = ax + b 에 주어진 두 점을 넣으면?","식":["$300a+b=500$","$350a+b=400$","$y=-2x+1100$"],"설명":"두 식을 연립하면 $a=-2$, $b=1100$ 이다.","확인":null,"스킬":"A10"},{"제목":"매출액을 x 의 식으로","힌트":"매출액은 단가와 판매량의 어떤 관계일까?","식":["$(\\text{매출액})=x(-2x+1100)=-2x^{2}+1100x$"],"설명":"매출액은 단가에 판매량을 곱한 값이다.","확인":null,"스킬":"C7","고비":true},{"제목":"최대가 되는 단가","힌트":"이차식을 완전제곱 꼴로 고치면 꼭짓점은 어디일까?","식":["$-2(x-275)^{2}+2\\times275^{2}$"],"설명":"이차항의 계수가 음수이므로 $x=275$ 일 때 매출액이 최대이다.","확인":"275","스킬":"A6"}],"fb":"fig/ns/"},"ns-62e4775f8d0e":{"길":"삼각형 ABC 의 변을 k 로 나타내고, D 에서 AB 의 연장선에 수선을 그어 직각삼각형 ADH 의 변으로 cos y 를 구한다","단계":[{"제목":"삼각형 ABC 의 세 변","힌트":"sin x = 1/3 이면 직각삼각형 ABC 의 두 변의 비는?","식":["$\\overline{AB}=3k,\\ \\overline{BC}=k$","$\\overline{AC}=\\sqrt{(3k)^{2}-k^{2}}=2\\sqrt2k$"],"설명":"$\\sin x=\\frac{\\overline{BC}}{\\overline{AB}}=\\frac13$ 이므로 $\\overline{AB}=3k$, $\\overline{BC}=k$ 로 놓는다.","확인":null,"스킬":"S6"},{"제목":"수선 DH 를 긋고 닮음 찾기","힌트":"D 에서 AB 의 연장선에 수선을 그으면 삼각형 ABC 와 닮은 삼각형이 생기는데 어느 삼각형일까?","식":["$\\triangle ABC\\sim\\triangle DBH$","$\\overline{BH}=\\frac13k,\\ \\overline{DH}=\\frac{2\\sqrt2}{3}k$"],"설명":"$D$ 에서 $\\overline{AB}$ 의 연장선에 내린 수선의 발을 $H$ 라 하자. $\\angle ABC$ 와 $\\angle DBH$ 는 맞꼭지각이고 $\\angle C=\\angle H=90^{\\circ}$ 이므로 $AA$ 닮음이다. $\\overline{BD}=\\overline{BC}=k$ 이므로 $\\overline{AB}:\\overline{DB}=3:1$ 이 닮음비이다.","확인":null,"스킬":"S1","고비":true},{"제목":"AH 와 AD 의 길이","힌트":"AH 는 AB 와 BH 를 합한 길이이다. 그러면 직각삼각형 ADH 에서 AD 는?","식":["$\\overline{AH}=3k+\\frac13k=\\frac{10}{3}k$","$\\overline{AD}=\\sqrt{\\left(\\frac{2\\sqrt2}{3}k\\right)^{2}+\\left(\\frac{10}{3}k\\right)^{2}}=2\\sqrt3k$"],"설명":"$H$ 는 $\\overline{AB}$ 의 연장선 위에 있으므로 $\\overline{AH}=\\overline{AB}+\\overline{BH}$ 이다.","확인":null,"스킬":"S3"},{"제목":"cos y 구하기","힌트":"y 는 직각삼각형 ADH 의 어느 각일까?","식":["$\\cos y=\\frac{\\overline{AH}}{\\overline{AD}}=\\frac{\\frac{10}{3}k}{2\\sqrt3k}=\\frac{5\\sqrt3}{9}$"],"설명":"$H$ 가 반직선 $AB$ 위에 있으므로 $\\angle BAD=\\angle HAD=y$ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-650c063f2abd":{"길":"반지름이 1 인 직각삼각형에서 삼각비를 선분의 길이로 바꾸고, 각 b 와 c 를 a 와 연결해 보기를 하나씩 확인한다","단계":[{"제목":"ㄱ, ㄴ 확인","힌트":"빗변이나 밑변이 1 인 직각삼각형에서 sin a 와 tan a 는 어느 선분의 길이일까?","식":["$\\sin a^{\\circ}=\\frac{\\overline{AB}}{\\overline{OA}}=\\overline{AB}$","$\\tan a^{\\circ}=\\frac{\\overline{CD}}{\\overline{OC}}=\\overline{CD}$"],"설명":"$\\overline{OA}=\\overline{OC}=1$ 이므로 분모가 $1$ 이다. 따라서 ㄱ, ㄴ 은 옳다.","확인":null,"스킬":"S6"},{"제목":"각 b, c 를 a 와 연결","힌트":"직각삼각형 OAB, ODC 에서 b 와 c 는 각각 a 와 어떤 관계일까?","식":["$b=90^{\\circ}-a^{\\circ}$","$c=90^{\\circ}-a^{\\circ}$"],"설명":"삼각형의 세 각의 합이 $180^{\\circ}$ 이므로 두 직각삼각형에서 나머지 각은 각각 $90^{\\circ}-a^{\\circ}$ 이다. 따라서 $b=c$ 이다.","확인":null,"스킬":"S10","고비":true},{"제목":"ㄷ, ㄹ 확인","힌트":"각 b 에서 cos b 와 sin b 는 각각 어느 선분을 빗변으로 나눈 값일까?","식":["$\\cos b^{\\circ}=\\frac{\\overline{AB}}{\\overline{OA}}=\\overline{AB}$","$\\sin c^{\\circ}=\\sin b^{\\circ}=\\frac{\\overline{OB}}{\\overline{OA}}=\\overline{OB}$"],"설명":"ㄷ 은 $\\cos b^{\\circ}$ 가 $\\overline{AB}$ 이므로 옳지 않고, ㄹ 은 옳다. 따라서 옳은 것은 ㄱ, ㄴ, ㄹ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-65126883563c":{"길":"각의 이등분선 성질로 변의 비를 잡고 피타고라스 정리로 길이를 문자로 연결해 sin x 를 구한다","단계":[{"제목":"각의 이등분선으로 변의 비 잡기","힌트":"AD 가 각 A 의 이등분선이면 AB:AC 는 어떤 비와 같을까?","식":["$\\overline{AB}:\\overline{AC}=\\overline{BD}:\\overline{DC}=2:1$","$\\overline{AB}=2a,\\ \\overline{AC}=a,\\ \\overline{BD}=2b,\\ \\overline{DC}=b$"],"설명":"각의 이등분선은 대변을 두 변의 길이의 비로 나눈다. $\\angle C=90^{\\circ}$ 이므로 $\\overline{AB}$ 가 빗변이다.","확인":null,"스킬":"A8"},{"제목":"a 와 b 의 관계","힌트":"직각삼각형 ABC 에서 세 변 사이의 식을 세우면?","식":["$(2a)^{2}=a^{2}+(3b)^{2}$","$a^{2}=3b^{2}$"],"설명":"$\\overline{BC}=\\overline{BD}+\\overline{DC}=3b$ 이다. 피타고라스 정리로 $a$ 와 $b$ 를 연결한다.","확인":null,"스킬":"S3","고비":true},{"제목":"sin x 구하기","힌트":"직각삼각형 ACD 에서 AD 는? x 는 이 삼각형의 어느 각일까?","식":["$\\overline{AD}=\\sqrt{a^{2}+b^{2}}=2b$","$\\sin x=\\frac{\\overline{DC}}{\\overline{AD}}=\\frac{b}{2b}=\\frac12$"],"설명":"$\\overline{AD}$ 가 이등분선이므로 $\\angle CAD=\\angle BAD=x$ 이다.","확인":"1/2","스킬":"S6"}],"fb":"fig/ns/"},"ns-668df0521415":{"길":"점수를 평균 $6$ 에 대한 편차로 바꿔 두 사람의 분산을 비교한다","단계":[{"제목":"다트 판에서 점수 읽기","힌트":"각 점이 어느 구역에 있는지 보면 갑과 을의 점수는 무엇인가?","식":["$\\text{갑}:\\ 3,\\ 5,\\ 7,\\ 7,\\ 7,\\ 7,\\ 6,\\ 6,\\ 6,\\ 6$","$\\text{을}:\\ 8,\\ 8,\\ 5,\\ 5,\\ 3,\\ 7,\\ 7,\\ 7,\\ 4,\\ 6$"],"설명":"점수는 점이 놓인 구역에 적힌 수이다. 두 사람 모두 $10$곳의 점수 합이 $60$ 이어서 평균 $6$점이다.","확인":null,"스킬":"P4"},{"제목":"갑의 분산","힌트":"갑의 점수에서 평균 $6$ 을 뺀 편차의 제곱의 평균은 얼마인가?","식":["$\\frac{(-3)^2\\times1+(-1)^2\\times1+1^2\\times4}{10}=1.4$"],"설명":"편차가 $-3$ 인 점수 $1$개, $-1$ 인 점수 $1$개, $1$ 인 점수 $4$개, $0$ 인 점수 $4$개이다. 분산은 편차의 제곱의 평균이다.","확인":"1.4","스킬":"P4","고비":true},{"제목":"을의 분산","힌트":"을의 편차는 어떤 값이 몇 개씩 나오는가?","식":["$\\frac{(-3)^2+(-2)^2+(-1)^2\\times2+1^2\\times3+2^2\\times2}{10}=2.6$"],"설명":"편차가 $-3,\\ -2$ 인 점수가 각각 $1$개, $-1$ 이 $2$개, $0$ 이 $1$개, $1$ 이 $3$개, $2$ 가 $2$개이다.","확인":"2.6","스킬":"P4"},{"제목":"두 분산의 비교와 보기 판정","힌트":"분산이 작은 쪽은 평균 가까이에 얼마나 모여 있는가?","식":["$1.4<2.6$"],"설명":"갑의 분산이 더 작으므로 표준편차도 갑이 더 작고, 갑의 점수가 평균 가까이에 더 모여 있다. 따라서 갑의 실력이 더 안정적이라는 ⑤ 가 옳다. 편차의 합은 어떤 자료에서도 $0$ 이어서 안정성을 비교하는 근거가 되지 못한다.","확인":null,"스킬":"P4"}],"fb":"fig/ns/"},"ns-67f04da381e9":{"길":"y 축 대칭을 이용해 점의 좌표를 문자로 놓고 정사각형의 두 변이 같다는 식을 세운다","단계":[{"제목":"점의 좌표 놓기","힌트":"포물선이 y 축에 대칭이므로 C 의 x 좌표를 a 로 놓으면 B, D 의 좌표는?","식":["$C(a,\\ 0)$","$D(a,\\ 6-a^{2})$","$\\overline{BC}=2a$"],"설명":"$B$ 는 $C$ 와 $y$ 축에 대하여 대칭이므로 $B(-a,\\ 0)$ 이다. $a>0$ 이다.","확인":null,"스킬":"S4"},{"제목":"한 변이 같다는 식 세우기","힌트":"정사각형이면 CD 와 BC 의 길이는 어떤 관계일까?","식":["$\\overline{CD}=\\overline{BC}$","$6-a^{2}=2a$","$a=-1+\\sqrt7$"],"설명":"정리하면 $a^{2}+2a-6=0$ 이고, $a>0$ 이므로 $a=-1+\\sqrt7$ 이다.","확인":null,"스킬":"S4","고비":true},{"제목":"정사각형의 넓이","힌트":"한 변이 2a 인 정사각형의 넓이를 a 로 쓰면?","식":["$4a^{2}=4\\left(-1+\\sqrt7\\right)^{2}=32-8\\sqrt7$"],"설명":"$\\left(-1+\\sqrt7\\right)^{2}=8-2\\sqrt7$ 이다.","확인":null,"스킬":"S4"}],"fb":"fig/ns/"},"ns-6d4432367fb7":{"길":"완전제곱 꼴로 꼭짓점을 구하고, y 축 위의 변 OB 를 밑변으로 잡아 넓이 식을 세운다","단계":[{"제목":"꼭짓점 A 와 점 B 의 좌표","힌트":"이차식을 완전제곱 꼴로 고치면 꼭짓점은? y 축과의 교점은?","식":["$y=-(x+4)^{2}+16+k$","$A(-4,\\ 16+k)$","$B(0,\\ k)$"],"설명":"$y$ 축과의 교점은 $x=0$ 을 대입한 값이다.","확인":null,"스킬":"A6"},{"제목":"넓이 식 세우기","힌트":"y 축 위의 변 OB 를 밑변으로 잡으면 높이는 어느 값일까?","식":["$\\triangle OAB=\\frac12\\times k\\times4=2$"],"설명":"그림에서 $B$ 는 원점 위쪽에 있으므로 $\\overline{OB}=k$ 이고, 높이는 $A$ 의 $x$ 좌표의 절댓값 $4$ 이다.","확인":null,"스킬":"G10","고비":true},{"제목":"k 구하기","힌트":"식을 k 에 대해 풀면?","식":["$2k=2$","$k=1$"],"설명":"선지에서 $k=1$ 을 고른다.","확인":"1","스킬":"G10"}],"fb":"fig/ns/"},"ns-6d44498cb0e2":{"길":"접선과 반지름이 수직임을 이용해 BE 를 구하고, 한 점에서 그은 두 접선의 길이가 같음을 이용해 피타고라스 식을 세운다","단계":[{"제목":"BE 의 길이","힌트":"접선과 접점을 지나는 반지름이 이루는 각은 몇 도일까?","식":["$\\overline{BE}=\\sqrt{5^{2}-4^{2}}=3$"],"설명":"접선은 접점을 지나는 반지름에 수직이므로 $\\angle BEC=90^{\\circ}$ 이고, $\\overline{CE}$ 는 반지름 $4$ 이다.","확인":"3","스킬":"S5"},{"제목":"접선의 길이를 x 로 놓기","힌트":"점 F 에서 원에 그은 두 접선의 길이 사이에는 어떤 관계가 있을까?","식":["$\\overline{FD}=\\overline{FE}=x$","$\\overline{BF}=3+x$"],"설명":"$\\overline{AD}$ 는 반지름 $\\overline{CD}$ 에 수직이므로 점 $D$ 에서 원에 접한다. 원 밖의 점 $F$ 에서 그은 두 접선의 길이는 같다.","확인":null,"스킬":"S5","고비":true},{"제목":"피타고라스로 x 구하기","힌트":"F 에서 BC 에 수선을 내리면 직각삼각형 BFP 의 세 변은 각각 얼마일까?","식":["$\\overline{FP}=4,\\ \\overline{BP}=5-x$","$4^{2}+(5-x)^{2}=(3+x)^{2}$","$x=2$"],"설명":"$F$ 에서 $\\overline{BC}$ 에 내린 수선의 발을 $P$ 라 하자. $\\overline{FP}=\\overline{AB}=4$ 이고 $\\overline{PC}=\\overline{FD}=x$ 이므로 $\\overline{BP}=5-x$ 이다.","확인":"2","스킬":"S3"},{"제목":"삼각형 ABF 의 넓이","힌트":"AF 는 AD 에서 FD 를 뺀 길이이다. 넓이는?","식":["$\\overline{AF}=5-2=3$","$\\triangle ABF=\\frac12\\times4\\times3=6$"],"설명":"$\\overline{AD}=\\overline{BC}=5$ 이고 $\\angle A=90^{\\circ}$ 이므로 $\\overline{AB}$ 와 $\\overline{AF}$ 가 밑변과 높이이다.","확인":"6","스킬":"S12"}],"fb":"fig/ns/"},"ns-6f37dcccb60d":{"길":"두 작은 반원의 반지름을 문자로 놓고 색칠한 넓이와 원 O 의 넓이를 각각 나타내 비교한다","단계":[{"제목":"색칠한 부분의 넓이","힌트":"지름이 AH, HB 인 두 반원의 반지름을 문자로 놓고 큰 반원에서 빼면?","식":["$\\frac12\\pi(r_{1}+r_{2})^{2}-\\frac12\\pi r_{1}^{2}-\\frac12\\pi r_{2}^{2}=r_{1}r_{2}\\pi$"],"설명":"$\\overline{AH}=2r_{1}$, $\\overline{HB}=2r_{2}$ 이므로 큰 반원의 반지름은 $r_{1}+r_{2}$ 이다.","확인":null,"스킬":"S12"},{"제목":"PH 의 길이 관계","힌트":"각 APB 는 몇 도이고, 그 직각삼각형에서 높이 PH 의 제곱은 어떤 두 선분의 곱일까?","식":["$\\overline{PH}^{2}=\\overline{AH}\\times\\overline{BH}=2r_{1}\\times2r_{2}=4r_{1}r_{2}$"],"설명":"큰 반원의 지름에 대한 원주각은 $90^{\\circ}$ 이므로 $\\triangle APB$ 는 직각삼각형이고 $\\overline{PH}\\perp\\overline{AB}$ 이다. 직각삼각형에서 높이의 제곱은 밑변이 나뉜 두 선분의 곱과 같다.","확인":null,"스킬":"S5","고비":true},{"제목":"원 O 의 넓이와 비교","힌트":"지름이 PH 인 원의 넓이를 r1, r2 로 쓰면?","식":["$\\pi\\left(\\frac{\\overline{PH}}{2}\\right)^{2}=\\frac{\\overline{PH}^{2}}{4}\\pi=r_{1}r_{2}\\pi$"],"설명":"색칠한 부분의 넓이와 같으므로 $\\sqrt2$ 배라는 ④ 는 옳지 않다.","확인":null,"스킬":"S12"},{"제목":"선지 ⑤ 확인","힌트":"큰 반원의 둘레와 두 작은 반원의 둘레의 합을 각각 쓰면?","식":["$\\pi(r_{1}+r_{2})+2r_{1}+2r_{2}$","$\\left(\\pi r_{1}+2r_{1}\\right)+\\left(\\pi r_{2}+2r_{2}\\right)$"],"설명":"두 식이 같으므로 ⑤ 는 옳다. 따라서 옳지 않은 것은 ④ 이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-74f6de60e6e6":{"길":"원주각과 공통각으로 AA 닮음이 성립하는 선지를 가려내고 남는 선지를 찾는다","단계":[{"제목":"①에서 원주각으로 닮음 확인","고비":true,"힌트":"$\\triangle \\mathrm{APD}$와 $\\triangle \\mathrm{BPC}$에서 크기가 같은 두 각은 어느 호에 대한 원주각일까?","식":["$\\angle \\mathrm{PAD}=\\angle \\mathrm{PBC},\\ \\angle \\mathrm{PDA}=\\angle \\mathrm{PCB}$","$\\triangle \\mathrm{APD}\\sim\\triangle \\mathrm{BPC}$"],"설명":"$\\angle \\mathrm{PAD}$와 $\\angle \\mathrm{PBC}$는 호 $\\mathrm{DC}$에 대한 원주각, $\\angle \\mathrm{PDA}$와 $\\angle \\mathrm{PCB}$는 호 $\\mathrm{AB}$에 대한 원주각이므로 각각 같다. 두 쌍의 각이 같으므로 AA 닮음이다.","확인":null,"스킬":"S5"},{"제목":"④에서 원주각으로 닮음 확인","힌트":"$\\triangle \\mathrm{ABP}$와 $\\triangle \\mathrm{DCP}$에서 같은 호에 대한 원주각은 어느 것일까?","식":["$\\angle \\mathrm{PAB}=\\angle \\mathrm{PDC},\\ \\angle \\mathrm{PBA}=\\angle \\mathrm{PCD}$","$\\triangle \\mathrm{ABP}\\sim\\triangle \\mathrm{DCP}$"],"설명":"$\\angle \\mathrm{PAB}$와 $\\angle \\mathrm{PDC}$는 호 $\\mathrm{BC}$에 대한 원주각, $\\angle \\mathrm{PBA}$와 $\\angle \\mathrm{PCD}$는 호 $\\mathrm{AD}$에 대한 원주각이므로 AA 닮음이다.","확인":null,"스킬":"S5"},{"제목":"③, ⑤에서 공통각 이용","힌트":"점 $\\mathrm{S}$에서 만나는 두 삼각형이 공통으로 가지는 각은 무엇이고, 나머지 한 쌍은 어떻게 같음을 보일까?","식":["$\\triangle \\mathrm{ACS}\\sim\\triangle \\mathrm{BDS}$","$\\triangle \\mathrm{ABS}\\sim\\triangle \\mathrm{CDS}$"],"설명":"③은 $\\angle \\mathrm{SAC}$와 $\\angle \\mathrm{SBD}$가 호 $\\mathrm{DC}$에 대한 원주각이라 같다. ⑤는 $□\\mathrm{ABCD}$가 원에 내접하므로 한 외각 $\\angle \\mathrm{SCD}$가 대각 $\\angle \\mathrm{SAB}$와 같다. 둘 다 공통각 $\\angle \\mathrm{S}$와 함께 AA 닮음이다.","확인":null,"스킬":"S5"},{"제목":"남은 ② 가려내기","힌트":"①, ③, ④, ⑤가 모두 닮음이라면 닮음이라고 할 수 없는 것은 어느 선지일까?","식":["$\\triangle \\mathrm{ABC}\\not\\sim\\triangle \\mathrm{BDA}$"],"설명":"①, ③, ④, ⑤는 닮음이 성립하므로 틀리게 말한 것은 ②이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-77543a237570":{"길":"한 직선 위의 선분 길이의 비를 x좌표의 비로 바꿔 점 C를 잡고, 직선과 포물선에 차례로 대입한다","단계":[{"제목":"점 A를 두 식에 대입","힌트":"점 $\\mathrm{A}$는 직선과 $y=ax^2$ 위에 동시에 있다. $x=2$를 각 식에 넣으면?","식":["$-\\frac{1}{2}\\times 2+b=4a$","$4a-b=-1\\ \\cdots ㉠$"],"설명":"점 $\\mathrm{A}$의 $x$좌표가 $2$이므로 두 식에 모두 대입한다. 얻은 식을 ㉠이라 하자.","확인":null,"스킬":"G1"},{"제목":"길이의 비로 점 C의 좌표 구하기","고비":true,"힌트":"선분 $\\mathrm{AB}$와 $\\mathrm{AC}$의 길이의 비는 두 점의 $x$좌표 차의 비와 어떤 관계일까?","식":["$\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}=2:3$","$\\mathrm{C}\\left(5,\\ \\frac{25}{6}\\right)$"],"설명":"점 $\\mathrm{B}$는 $y$축 위의 점($x$좌표 $0$)이므로 $\\mathrm{A}$의 $x$좌표 $2$가 $\\overline{\\mathrm{AB}}$에 해당한다. 한 직선 위에서 선분의 길이의 비는 $x$좌표 차의 비와 같으므로(평행선 사이의 선분의 길이의 비) $\\mathrm{C}$의 $x$좌표는 $5$이다. $\\mathrm{C}$는 $y=\\frac{1}{6}x^2$ 위의 점이므로 $y$좌표는 $\\frac{25}{6}$이다.","확인":"5","스킬":"A8"},{"제목":"직선의 식에서 b 구하기","힌트":"점 $\\mathrm{C}$가 직선 위에 있다는 조건을 식으로 어떻게 쓸까?","식":["$\\frac{25}{6}=-\\frac{1}{2}\\times 5+b$","$b=\\frac{20}{3}$"],"설명":"$\\mathrm{C}$의 좌표를 직선의 식에 대입해 $b$를 구한다.","확인":"20/3","스킬":"G1"},{"제목":"a 구하기","힌트":"㉠에 $b$의 값을 넣으면 $a$는 어떻게 될까?","식":["$4a-\\frac{20}{3}=-1$","$a=\\frac{17}{12}$"],"설명":"㉠에 $b$를 대입해 $a$를 구한다.","확인":"17/12","스킬":"G1"}],"fb":"fig/ns/"},"ns-8302f3f24f7a":{"길":"삼각비를 변의 길이로 바꾸고 각의 크기에 따른 부호를 정해 근호를 벗긴다","단계":[{"제목":"삼각비를 변의 길이로 나타내기","힌트":"직각삼각형에서 $\\sin$, $\\cos$은 각각 어느 두 변의 비일까?","식":["$\\sin A=\\frac{a}{c},\\ \\sin B=\\frac{b}{c}$","$\\cos A=\\frac{b}{c},\\ \\cos B=\\frac{a}{c}$"],"설명":"$\\angle C=90^{\\circ}$이고 $a$, $b$, $c$가 각각 $\\angle A$, $\\angle B$, $\\angle C$의 대변이므로 $\\sin$은 (높이)/(빗변), $\\cos$은 (밑변)/(빗변)이다.","확인":null,"스킬":"S6"},{"제목":"근호 안의 부호 정하기","고비":true,"힌트":"$0^{\\circ}$에서 $90^{\\circ}$ 사이에서 각이 커지면 $\\sin$ 값과 $\\cos$ 값은 각각 어떻게 변할까?","식":["$\\sin A<\\sin B,\\ \\cos A>\\cos B$"],"설명":"$0^{\\circ}<A<45^{\\circ}<B<90^{\\circ}$에서 각이 커질수록 $\\sin$ 값은 커지고 $\\cos$ 값은 작아진다. 따라서 $\\sin A-\\sin B<0$, $\\cos A-\\cos B>0$이다.","확인":null,"스킬":"C2"},{"제목":"근호를 벗겨 계산하기","힌트":"$\\sqrt{X^2}$은 $X$가 음수일 때와 양수일 때 각각 무엇과 같을까?","식":["$\\sqrt{(\\sin A-\\sin B)^2}+\\sqrt{(\\cos A-\\cos B)^2}=-(\\sin A-\\sin B)+(\\cos A-\\cos B)$","$=-\\frac{a}{c}+\\frac{b}{c}+\\frac{b}{c}-\\frac{a}{c}=\\frac{2(b-a)}{c}$"],"설명":"$\\sqrt{X^2}=|X|$이므로 음수인 앞의 식에는 $-$를 붙여 벗기고, 양수인 뒤의 식은 그대로 둔 뒤 변의 길이로 바꿔 계산한다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-85ece874f24e":{"길":"수선을 내려 변의 길이를 구하고, 삼각형의 넓이를 두 방법으로 나타내 내접원의 반지름을 구한다","단계":[{"제목":"AB, AC의 길이 구하기","힌트":"점 $\\mathrm{A}$에서 $\\overline{\\mathrm{BC}}$에 수선을 내리면 직각삼각형 $\\mathrm{ABH}$의 변의 비는 어떻게 될까?","식":["$\\overline{\\mathrm{BH}}=\\overline{\\mathrm{CH}}=4\\sqrt{3}$","$4\\sqrt{3}:\\overline{\\mathrm{AB}}=\\sqrt{3}:2$","$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AC}}=8$"],"설명":"점 $\\mathrm{A}$에서 $\\overline{\\mathrm{BC}}$에 내린 수선의 발을 $\\mathrm{H}$라 한다. 이등변삼각형의 꼭지각의 이등분선은 밑변을 수직이등분하므로 $\\overline{\\mathrm{BH}}=\\overline{\\mathrm{CH}}$이다. $\\angle \\mathrm{B}=30^{\\circ}$인 직각삼각형 $\\mathrm{ABH}$에서 $\\overline{\\mathrm{BH}}:\\overline{\\mathrm{AB}}=\\sqrt{3}:2$이다.","확인":"8","스킬":"S6"},{"제목":"넓이를 두 가지로 나타내기","고비":true,"힌트":"삼각형의 넓이를 두 변과 끼인각, 그리고 내접원의 반지름으로 각각 나타내면?","식":["$\\triangle \\mathrm{ABC}=\\frac{1}{2}\\times 8\\times 8\\sqrt{3}\\times \\sin 30^{\\circ}$","$\\triangle \\mathrm{ABC}=\\frac{r}{2}(\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{AC}})=\\frac{r}{2}(16+8\\sqrt{3})$"],"설명":"내접원의 반지름을 $r$라 하면, 내심에서 세 변에 그은 수선의 길이가 모두 $r$이므로 삼각형의 넓이는 $\\frac{r}{2}\\times$(세 변의 길이의 합)이다. 이 값이 두 변 $\\mathrm{AB}$, $\\mathrm{BC}$와 끼인각으로 구한 넓이와 같다고 놓는다.","확인":null,"스킬":"S8"},{"제목":"r 구하기","힌트":"$16\\sqrt{3}=(8+4\\sqrt{3})r$에서 $r$는 어떻게 정리될까?","식":["$16\\sqrt{3}=(8+4\\sqrt{3})r$","$r=\\frac{16\\sqrt{3}}{8+4\\sqrt{3}}=\\frac{4\\sqrt{3}}{2+\\sqrt{3}}=4(2\\sqrt{3}-3)$"],"설명":"두 넓이를 같게 놓은 식에서 $r$를 구하고 분모를 유리화한다.","확인":null,"스킬":"S8"}],"fb":"fig/ns/"},"ns-86e6a8646092":{"길":"접힌 도형에서 같은 길이와 각을 찾아 이등변삼각형을 만들고, 수선을 내려 만든 직각삼각형으로 tan 값을 구한다","단계":[{"제목":"접힌 도형에서 같은 길이 찾기","힌트":"점 $\\mathrm{D}$가 점 $\\mathrm{G}$로 옮겨지도록 접었을 때 $\\overline{\\mathrm{ED}}$와 길이가 같은 선분은?","식":["$\\overline{\\mathrm{\\ge }}=\\overline{\\mathrm{ED}}=4$","$\\angle \\mathrm{GEF}=\\angle \\mathrm{DEF}$"],"설명":"접으면 겹치는 선분과 각은 같다. 점 $\\mathrm{D}$가 옮겨진 점이 $\\mathrm{G}$이므로 $\\overline{\\mathrm{\\ge }}=\\overline{\\mathrm{ED}}$이고, 접는 선 $\\mathrm{EF}$를 기준으로 $\\angle \\mathrm{GEF}=\\angle \\mathrm{DEF}$이다.","확인":null,"스킬":"S10"},{"제목":"이등변삼각형 찾기","고비":true,"힌트":"$\\overline{\\mathrm{AD}}/\\!/\\overline{\\mathrm{BC}}$이므로 $\\angle \\mathrm{GFE}$와 같은 각은?","식":["$\\angle \\mathrm{GFE}=\\angle \\mathrm{DEF}=\\angle \\mathrm{GEF}$","$\\overline{\\mathrm{GF}}=\\overline{\\mathrm{\\ge }}=4$"],"설명":"$\\angle \\mathrm{GFE}$와 $\\angle \\mathrm{DEF}$는 평행선의 엇각이라 같고, $\\angle \\mathrm{DEF}=\\angle \\mathrm{GEF}$이므로 $\\triangle \\mathrm{GEF}$는 $\\overline{\\mathrm{\\ge }}=\\overline{\\mathrm{GF}}$인 이등변삼각형이다.","확인":null,"스킬":"S10"},{"제목":"FC의 길이 구하기","힌트":"접어서 겹치는 변끼리 길이가 같다면 직각삼각형 $\\mathrm{GHF}$에서 $\\overline{\\mathrm{GH}}$는 어느 변과 같을까?","식":["$\\overline{\\mathrm{GH}}=\\overline{\\mathrm{DC}}=3$","$\\overline{\\mathrm{HF}}=\\sqrt{4^2-3^2}=\\sqrt{7}$","$\\overline{\\mathrm{FC}}=\\overline{\\mathrm{HF}}=\\sqrt{7}$"],"설명":"점 $\\mathrm{H}$는 점 $\\mathrm{C}$가 접혀 옮겨진 점이다. $\\angle \\mathrm{GHF}=90^{\\circ}$인 직각삼각형 $\\mathrm{GHF}$에서 빗변 $\\overline{\\mathrm{GF}}=4$, $\\overline{\\mathrm{GH}}=\\overline{\\mathrm{DC}}=3$이므로 피타고라스 정리로 $\\overline{\\mathrm{HF}}$를 구하고, 접힌 변이므로 $\\overline{\\mathrm{FC}}=\\overline{\\mathrm{HF}}$이다.","확인":null,"스킬":"S3"},{"제목":"수선의 발 P로 EP 구하기","힌트":"점 $\\mathrm{F}$에서 $\\overline{\\mathrm{AD}}$에 수선을 내리면 $\\overline{\\mathrm{PD}}$는 어느 선분과 길이가 같을까?","식":["$\\overline{\\mathrm{PD}}=\\overline{\\mathrm{FC}}=\\sqrt{7}$","$\\overline{\\mathrm{EP}}=4-\\sqrt{7}$"],"설명":"점 $\\mathrm{F}$에서 $\\overline{\\mathrm{AD}}$에 내린 수선의 발을 $\\mathrm{P}$라 하면 $\\square\\mathrm{PFCD}$는 직사각형이므로 $\\overline{\\mathrm{PD}}=\\overline{\\mathrm{FC}}$이고, $\\overline{\\mathrm{EP}}=\\overline{\\mathrm{ED}}-\\overline{\\mathrm{PD}}$이다.","확인":null,"스킬":"S3"},{"제목":"tan x 구하기","힌트":"직각삼각형 $\\mathrm{EPF}$에서 $\\tan x$는 어느 두 변의 비일까?","식":["$\\tan x=\\frac{\\overline{\\mathrm{PF}}}{\\overline{\\mathrm{EP}}}=\\frac{3}{4-\\sqrt{7}}=\\frac{4+\\sqrt{7}}{3}$"],"설명":"$x=\\angle \\mathrm{DEF}$이므로 $\\triangle \\mathrm{EPF}$에서 $\\overline{\\mathrm{PF}}=\\overline{\\mathrm{DC}}=3$을 쓰고 분모를 유리화한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-880730b6a481":{"길":"세 자료의 평균과 분산을 구한 뒤 보기를 하나씩 참, 거짓으로 가린다","단계":[{"제목":"세 자료의 평균 구하기","힌트":"도수가 있는 자료의 평균은 (변량×도수)의 합을 전체 도수로 나누면 어떻게 될까?","식":["$A:\\ \\frac{11+12+13\\times 6+14+15}{10}=13$","$B:\\ 13,\\quad C:\\ \\frac{11+12\\times 3+13\\times 2+14\\times 3+15}{10}=13$"],"설명":"세 자료 모두 학생 수가 $10$명이고 평균은 같다.","확인":"13","스킬":"C3"},{"제목":"세 자료의 분산 구하기","고비":true,"힌트":"편차의 제곱에 도수를 곱해 모두 더한 뒤 도수의 합으로 나누면?","식":["$A:\\ \\frac{4+1+0\\times 6+1+4}{10}=1$","$B:\\ \\frac{2(4+1+0+1+4)}{10}=2$","$C:\\ \\frac{4+3\\times 1+2\\times 0+3\\times 1+4}{10}=\\frac{14}{10}=1.4$"],"설명":"평균이 $13$이므로 편차는 $-2$, $-1$, $0$, $1$, $2$이다. 분산은 $A$가 $1$, $B$가 $2$, $C$가 $1.4$이다.","확인":null,"스킬":"C3"},{"제목":"ㄱ, ㄴ 가리기","힌트":"표준편차가 가장 작은 자료는 분산이 어떤 자료일까? 평균은 서로 어떤 관계일까?","식":[],"설명":"ㄱ은 표준편차가 분산의 양의 제곱근이므로 분산이 가장 작은 $A$가 표준편차도 가장 작아 참이다. ㄴ은 세 자료의 평균이 모두 $13$으로 같으므로 거짓이다.","확인":null,"스킬":"C3"},{"제목":"ㄷ, ㄹ 가리기","힌트":"평균, 중앙값, 최빈값이 모두 같은 자료와 최빈값이 가장 많은 자료는 각각 무엇일까?","식":[],"설명":"ㄷ은 평균, 중앙값, 최빈값이 모두 같은 자료가 $A$ 하나뿐이므로 거짓이다. $A$는 세 값이 모두 $13$이다. $B$는 모든 값의 도수가 같아 최빈값이 없고, $C$는 최빈값이 $12$와 $14$로 $2$개이므로 최빈값의 개수가 가장 많은 자료는 $C$이고 ㄹ은 거짓이다. 따라서 옳은 것은 ㄱ뿐이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-8b5d201eca67":{"길":"넓이가 최대가 되는 위치를 꼭짓점으로 잡고 두 꼭짓점 사이의 거리를 식으로 세운다","단계":[{"제목":"넓이가 최대가 되는 위치 찾기","고비":true,"힌트":"두 그래프가 만나는 점 $\\mathrm{A}$, $\\mathrm{B}$는 고정이므로 사각형의 넓이는 무엇에 따라 변할까?","식":["$\\square \\mathrm{PAQB}=\\triangle \\mathrm{ABP}+\\triangle \\mathrm{ABQ}$"],"설명":"$\\overline{\\mathrm{AB}}$가 고정이므로 $P$는 위로 볼록한 그래프에서 가장 높을 때, $Q$는 아래로 볼록한 그래프에서 가장 낮을 때 넓이가 최대이다. 즉 $P$, $Q$가 각각 꼭짓점이다.","확인":null,"스킬":"G10"},{"제목":"두 꼭짓점의 좌표 구하기","힌트":"각 이차식을 $a(x-p)^2+q$ 꼴로 고치면?","식":["$y=-\\frac{1}{2}(x-1)^2+\\frac{1}{2}-\\frac{1}{4}a,\\quad y=2(x-1)^2-2+a$","$\\mathrm{P}\\left(1,\\ \\frac{1}{2}-\\frac{1}{4}a\\right),\\ \\mathrm{Q}(1,\\ -2+a)$"],"설명":"완전제곱식으로 고쳐 두 꼭짓점의 좌표를 구한다.","확인":null,"스킬":"A6"},{"제목":"PQ의 길이로 a 구하기","힌트":"두 점의 $x$좌표가 같을 때 $\\overline{\\mathrm{PQ}}$는 $y$좌표의 차이다. 이를 $10$과 같게 놓으면?","식":["$\\frac{1}{2}-\\frac{1}{4}a-(-2+a)=10$","$a=-6$"],"설명":"$P$가 $Q$보다 위에 있으므로 $P$의 $y$좌표에서 $Q$의 $y$좌표를 빼서 $10$과 같게 놓고 $a$를 구한다.","확인":"-6","스킬":"A6"}],"fb":"fig/ns/"},"ns-8dd3d3394514":{"길":"그래프의 모양과 축, 절편으로 a, b, c의 부호를 정하고 특정 x의 함숫값 부호로 선지를 확인한다","단계":[{"제목":"a, b, c의 부호 정하기","힌트":"위로 볼록이면 $a$의 부호는? 축이 $x=-1$이면 $b$의 부호는?","식":["$a<0$","$\\frac{b}{2a}=-1$","$b>0,\\ c>0$"],"설명":"위로 볼록하므로 $a<0$이다. 축의 방정식이 $x=\\frac{b}{2a}=-1$이고 $a<0$이므로 $b>0$이다. $y$절편이 양수이므로 $c>0$이다.","확인":null,"스킬":"G6"},{"제목":"①, ② 확인하기","힌트":"$abc$의 부호는? 그래프는 $x$축과 몇 점에서 만날까?","식":["$abc<0$","$b^2-4ac>0$"],"설명":"$a<0$, $b>0$, $c>0$이므로 $abc<0$이다. 그래프가 $x$축과 서로 다른 두 점에서 만나므로 판별식 $b^2-4ac>0$이다.","확인":null,"스킬":"G6"},{"제목":"③, ④ 확인하기","힌트":"$x=-1$과 $x=1$을 식에 넣으면 각각 어떤 식이 될까?","식":["$x=-1:\\ y=a+b+c>0$","$x=1:\\ y=a-b+c<0$"],"설명":"$x=-1$에서 그래프는 $x$축 위에 있어 $y>0$이고, $x=1$에서는 $x$축 아래에 있어 $y<0$이므로 ③, ④는 옳다.","확인":null,"스킬":"G6"},{"제목":"⑤ 확인하기","고비":true,"힌트":"$a+2b+4c$를 $x=-\\frac{1}{2}$일 때의 $y$ 값과 연결하면?","식":["$x=-\\frac{1}{2}:\\ y=\\frac{1}{4}a+\\frac{1}{2}b+c>0$","$a+2b+4c=4\\left(\\frac{1}{4}a+\\frac{1}{2}b+c\\right)>0$"],"설명":"$x=-\\frac{1}{2}$에서 그래프가 $x$축 위에 있으므로 $y>0$이다. 이 값에 $4$를 곱하면 $a+2b+4c>0$이므로 $a+2b+4c<0$이라는 ⑤는 옳지 않다.","확인":null,"스킬":"G6"}],"fb":"fig/ns/"},"ns-9032f663b6a3":{"길":"접선과 반지름이 수직인 직각삼각형으로 각과 길이를 구해 선지를 하나씩 확인한다","단계":[{"제목":"∠APB 구하기","힌트":"직각삼각형 $\\mathrm{PAO}$에서 $\\overline{\\mathrm{PA}}:\\overline{\\mathrm{AO}}$의 비로 $\\angle \\mathrm{APO}$를 알 수 있을까?","식":["$\\overline{\\mathrm{PA}}:\\overline{\\mathrm{AO}}=\\sqrt{3}:1$","$\\angle \\mathrm{APO}=\\angle \\mathrm{BPO}=30^{\\circ}$","$\\angle \\mathrm{APB}=60^{\\circ}$"],"설명":"접선과 반지름은 수직이므로 $\\angle \\mathrm{PAO}=90^{\\circ}$이고, 두 변의 비가 $\\sqrt{3}:1$이므로 $\\angle \\mathrm{APO}=30^{\\circ}$이다. $\\triangle \\mathrm{PAO}$와 $\\triangle \\mathrm{PBO}$는 빗변 $\\mathrm{PO}$가 공통이고 $\\overline{\\mathrm{AO}}=\\overline{\\mathrm{BO}}$인 직각삼각형이라 RHS 합동이므로 $\\angle \\mathrm{BPO}=30^{\\circ}$이다. ①은 옳다.","확인":null,"스킬":"S5"},{"제목":"AB 구하기","힌트":"한 점에서 원에 그은 두 접선의 길이와 $\\angle \\mathrm{APB}=60^{\\circ}$로 $\\triangle \\mathrm{PAB}$는 어떤 삼각형일까?","식":["$\\overline{\\mathrm{PA}}=\\overline{\\mathrm{PB}},\\ \\angle \\mathrm{APB}=60^{\\circ}$","$\\overline{\\mathrm{AB}}=8\\sqrt{3}$"],"설명":"접선의 길이가 같으므로 $\\overline{\\mathrm{PA}}=\\overline{\\mathrm{PB}}$이고 꼭지각이 $60^{\\circ}$이므로 $\\triangle \\mathrm{PAB}$는 정삼각형이다. 따라서 $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{PA}}=8\\sqrt{3}$이다. ②는 옳다.","확인":null,"스킬":"S5"},{"제목":"△AOB와 ∠BAO 확인하기","힌트":"직각삼각형 $\\mathrm{PAO}$에서 $\\angle \\mathrm{AOP}$는 몇 도일까? 그러면 $\\angle \\mathrm{AOB}$는?","식":["$\\angle \\mathrm{AOB}=2\\times 60^{\\circ}=120^{\\circ}$","$\\triangle \\mathrm{AOB}=\\frac{1}{2}\\times 8\\times 8\\times \\sin 120^{\\circ}=16\\sqrt{3}$","$\\angle \\mathrm{BAO}=\\frac{1}{2}(180^{\\circ}-120^{\\circ})=30^{\\circ}$"],"설명":"$\\angle \\mathrm{AOP}=\\angle \\mathrm{BOP}=60^{\\circ}$이므로 $\\angle \\mathrm{AOB}=120^{\\circ}$이다. 이등변삼각형 $\\mathrm{AOB}$의 넓이는 두 변과 끼인각으로 구하고, 밑각은 $(180^{\\circ}-120^{\\circ})\\div 2$이다. ④, ⑤는 옳다.","확인":null,"스킬":"S6"},{"제목":"③ 사각형 APBO의 넓이 확인하기","고비":true,"힌트":"사각형 $\\mathrm{APBO}$를 합동인 두 직각삼각형으로 나누면 넓이는 얼마일까?","식":["$\\square \\mathrm{APBO}=2\\triangle \\mathrm{PAO}=2\\times\\left(\\frac{1}{2}\\times 8\\sqrt{3}\\times 8\\right)=64\\sqrt{3}$"],"설명":"사각형 $\\mathrm{APBO}$의 넓이는 $64\\sqrt{3}$이고, ③에 적힌 $64\\sqrt{3}-12\\pi$와 다르므로 ③이 옳지 않다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-92d8602f7bb4":{"길":"아래 두 원의 중심과 접점을 이어 직각삼각형을 만들고, 한 변을 세 부분으로 나누어 길이를 구한다","단계":[{"제목":"접점과 중심 사이의 거리 정하기","힌트":"변 $\\mathrm{BC}$ 위 두 원의 중심에서 접점까지는 길이가 얼마이고, 접점끼리의 거리는 얼마일까?","식":["$\\overline{\\mathrm{OP}}=\\overline{\\mathrm{O'Q}}=3$","$\\overline{\\mathrm{PQ}}=\\overline{\\mathrm{OO'}}=6$"],"설명":"$\\overline{\\mathrm{BC}}$에 접하는 두 원의 중심을 $\\mathrm{B}$쪽부터 $\\mathrm{O}$, $\\mathrm{O'}$, 접점을 $\\mathrm{P}$, $\\mathrm{Q}$라 한다. 접점에서 반지름은 접선에 수직이므로 $\\square \\mathrm{OPQO'}$는 직사각형이고, 두 원이 외접하므로 $\\overline{\\mathrm{OO'}}=3+3=6$이다.","확인":null,"스킬":"S2"},{"제목":"∠OBP 구하기","고비":true,"힌트":"원 $\\mathrm{O}$가 두 변 $\\mathrm{AB}$, $\\mathrm{BC}$에 모두 접한다면 $\\overline{\\mathrm{BO}}$는 $\\angle \\mathrm{B}$를 어떻게 나눌까?","식":["$\\angle \\mathrm{OBP}=\\frac{1}{2}\\times 60^{\\circ}=30^{\\circ}$"],"설명":"원의 중심에서 두 접선까지의 거리가 같으므로 중심 $\\mathrm{O}$는 $\\angle \\mathrm{B}$의 이등분선 위에 있다. 정삼각형의 한 각은 $60^{\\circ}$이므로 $\\angle \\mathrm{OBP}=30^{\\circ}$이다.","확인":null,"스킬":"S2"},{"제목":"BP 구하기","힌트":"직각삼각형 $\\mathrm{OBP}$에서 $\\overline{\\mathrm{OP}}$와 $\\overline{\\mathrm{BP}}$의 관계를 나타내는 삼각비는?","식":["$\\overline{\\mathrm{BP}}=\\frac{\\overline{\\mathrm{OP}}}{\\tan 30^{\\circ}}=3\\sqrt{3}$"],"설명":"$\\tan 30^{\\circ}$는 $\\frac{\\overline{\\mathrm{OP}}}{\\overline{\\mathrm{BP}}}$이므로 $\\overline{\\mathrm{BP}}$를 구한다.","확인":null,"스킬":"S6"},{"제목":"둘레의 길이 구하기","힌트":"점 $\\mathrm{C}$쪽도 같은 방법으로 구하면 $\\overline{\\mathrm{BC}}$는 어떤 세 길이의 합일까?","식":["$\\overline{\\mathrm{BC}}=3\\sqrt{3}+6+3\\sqrt{3}=6+6\\sqrt{3}$","$3\\times(6+6\\sqrt{3})=18+18\\sqrt{3}$"],"설명":"정삼각형이므로 $\\overline{\\mathrm{CQ}}=\\overline{\\mathrm{BP}}$이다. $\\overline{\\mathrm{BC}}=\\overline{\\mathrm{BP}}+\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{QC}}$이고 세 변의 길이가 같으므로 둘레는 $\\overline{\\mathrm{BC}}$의 $3$배이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-9620490165a0":{"길":"두 히스토그램에서 최빈값, 인원, 중앙값을 읽고 상대적 위치는 아래쪽 인원으로 비교한다","단계":[{"제목":"인원 합과 최빈값","힌트":"막대 높이를 모두 더하면 두 대회의 인원은 각각 몇 명인가?","식":["$A:\\ 1+5+8+9+11+12+4=50$","$B:\\ 1+2+3+7+8+12+9+4+2+2=50$"],"설명":"두 대회 모두 $50$ 명이므로 ② 는 틀리다. 최빈값은 도수가 가장 큰 계급의 계급값이다. A 는 $80$점 이상 $90$점 미만이라 $85$점, B 는 $50$점 이상 $60$점 미만이라 $55$점이어서 ① 도 틀리다.","확인":"50","스킬":"C3"},{"제목":"편차의 합과 중앙값","힌트":"$50$ 명의 중앙값은 몇 번째와 몇 번째 값의 평균인가?","식":["$\\text{편차의 합}=0$","$A:\\ 75\\text{점},\\ B:\\ 55\\text{점}$"],"설명":"편차의 합은 어떤 자료에서도 $0$ 이므로 ③ 은 틀리다. 중앙값은 $25$번째와 $26$번째 값의 평균이다. A 의 누적 인원은 $1,\\ 6,\\ 14,\\ 23,\\ 34$ 이므로 $70$점 이상 $80$점 미만 계급에 있고, B 의 누적 인원은 $1,\\ 3,\\ 6,\\ 13,\\ 21,\\ 33$ 이므로 $50$점 이상 $60$점 미만 계급에 있다. B 대회의 성적이 더 낮아 ④ 도 틀리다.","확인":null,"스킬":"C3"},{"제목":"상대적인 성적 비교","힌트":"A 의 $50$점과 B 의 $40$점보다 낮은 점수를 받은 선수는 각각 몇 명인가?","식":["$A:\\ 50\\text{점 미만}\\ 1+5=6$","$B:\\ 40\\text{점 미만}\\ 1+2+3+7=13$"],"설명":"A 에서 $50$점은 $6$명보다 높고, B 에서 $40$점은 $13$명보다 높다. 자기보다 점수가 낮은 선수가 더 많은 B 대회의 $40$점이 상대적으로 더 좋은 성적이다. 따라서 ⑤ 가 옳다.","확인":null,"스킬":"C3","고비":true}],"fb":"fig/ns/"},"ns-967d7abaf6ae":{"길":"점 A의 좌표를 문자로 놓고 삼각형의 넓이를 식으로 세워 이차방정식을 푼다","단계":[{"제목":"점 A의 좌표를 문자로 놓기","힌트":"이차함수를 완전제곱식으로 고치고, 점 $\\mathrm{A}$의 $x$좌표를 $k$로 놓으면 $y$좌표는?","식":["$y=2x^2-4x+2=2(x-1)^2$","$\\mathrm{A}\\left(k,\\ 2(k-1)^2\\right)$"],"설명":"점 $\\mathrm{A}$는 그래프 위의 점이므로 $y$좌표는 $x=k$를 대입한 값이다. 제$1$사분면의 점이므로 $y$좌표는 삼각형 $\\mathrm{AOB}$의 높이가 된다.","확인":null,"스킬":"A6"},{"제목":"넓이식 세우기","고비":true,"힌트":"밑변 $\\overline{\\mathrm{OB}}=6$이고 높이가 $A$의 $y$좌표일 때 삼각형의 넓이를 식으로 쓰면?","식":["$\\frac{1}{2}\\times 6\\times 2(k-1)^2=24$","$(k-1)^2=4,\\ k=-1\\ \\text{또는}\\ k=3$"],"설명":"넓이를 $24$와 같게 놓고 $k$에 대한 방정식을 푼다.","확인":null,"스킬":"G10"},{"제목":"조건에 맞는 값 고르기","힌트":"점 $\\mathrm{A}$가 제$1$사분면에 있으려면 $x$좌표의 부호는?","식":["$k>0$","$k=3$"],"설명":"제$1$사분면의 점은 $x$좌표가 양수이므로 $k=-1$은 버린다.","확인":"3","스킬":"G10"}],"fb":"fig/ns/"},"ns-9749ec4e0c1d":{"길":"모눈에서 정사각형의 넓이를 읽어 변의 길이를 구하고, 호로 옮긴 점의 좌표를 거꾸로 따라간다","단계":[{"제목":"정사각형의 한 변의 길이 구하기","힌트":"모눈 한 칸이 $1$일 때 기울어진 두 정사각형의 넓이는 각각 얼마일까?","식":["$\\square \\mathrm{ABCD}=10,\\ \\square \\mathrm{DEFG}=17$","$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{BC}}=\\sqrt{10},\\ \\overline{\\mathrm{DE}}=\\overline{\\mathrm{EF}}=\\sqrt{17}$"],"설명":"모눈에서 넓이를 읽으면 $\\square \\mathrm{ABCD}$는 $10$, $\\square \\mathrm{DEFG}$는 $17$이다. 정사각형의 한 변의 길이는 넓이의 양의 제곱근이다.","확인":null,"스킬":"S12"},{"제목":"점 B에 대응하는 수 구하기","고비":true,"힌트":"$\\overline{\\mathrm{BA}}=\\overline{\\mathrm{BP}}$이므로 점 $\\mathrm{P}$는 점 $\\mathrm{B}$에서 왼쪽으로 얼마 떨어져 있을까?","식":["$\\overline{\\mathrm{BP}}=\\sqrt{10}$","$-2-\\sqrt{10}+\\sqrt{10}=-2$"],"설명":"점 $\\mathrm{P}$에 대응하는 수가 $-2-\\sqrt{10}$이고 $\\mathrm{P}$는 $\\mathrm{B}$에서 왼쪽으로 $\\sqrt{10}$만큼 떨어져 있으므로 $\\mathrm{B}$에 대응하는 수는 $-2$이다.","확인":"-2","스킬":"S4"},{"제목":"점 E에 대응하는 수 구하기","힌트":"그림에서 점 $\\mathrm{B}$와 점 $\\mathrm{E}$ 사이에는 모눈이 몇 칸 있을까?","식":["$-2+3=1$"],"설명":"$\\mathrm{B}$와 $\\mathrm{E}$ 사이는 모눈 $3$칸이므로 점 $\\mathrm{E}$에 대응하는 수는 $1$이다.","확인":"1","스킬":"S4"},{"제목":"점 Q의 좌표 구하기","힌트":"$\\overline{\\mathrm{EF}}=\\overline{\\mathrm{EQ}}$이므로 점 $\\mathrm{Q}$는 점 $\\mathrm{E}$에서 오른쪽으로 얼마 떨어져 있을까?","식":["$\\overline{\\mathrm{EQ}}=\\sqrt{17}$","$\\mathrm{Q}=1+\\sqrt{17}$"],"설명":"$\\overline{\\mathrm{EQ}}=\\overline{\\mathrm{EF}}=\\sqrt{17}$이고 점 $\\mathrm{Q}$는 $\\mathrm{E}$의 오른쪽에 있으므로 $1+\\sqrt{17}$이다.","확인":null,"스킬":"S4"}],"fb":"fig/ns/"},"ns-9e5a3892e942":{"길":"지름의 원주각과 같은 호의 원주각으로 두 보기를 확인하고, 길이를 계산해 나머지 보기를 걸러낸다","단계":[{"제목":"보기 1, 3 판정","힌트":"$\\overline{AD}$ 는 원의 지름이고 $\\angle ABC$, $\\angle ADC$ 는 같은 호 위의 각인가?","식":["$\\angle ACD=90^{\\circ}$","$\\angle ABC=\\angle ADC$"],"설명":"지름이 $8$ 이므로 $\\overline{AD}=8$ 은 지름이고, 지름에 대한 원주각은 $90^{\\circ}$ 이므로 $\\angle ACD=90^{\\circ}$ 이다. $\\angle ABC$ 와 $\\angle ADC$ 는 호 $AC$ 에 대한 원주각이므로 같다. 1번과 3번은 옳다.","확인":null,"스킬":"S5","고비":true},{"제목":"$\\overline{BP}$ 와 $\\overline{AC}$ 의 길이","힌트":"$\\triangle ABP$ 에서 $\\angle ABC$ 의 사인값은 얼마인가?","식":["$\\overline{BP}=\\sqrt{4^{2}-3^{2}}=\\sqrt{7}$","$\\sin(\\angle ADC)=\\sin(\\angle ABC)=\\frac{3}{4}$","$\\overline{AC}=8\\times\\frac{3}{4}$"],"설명":"$\\triangle ABP$ 는 $\\angle P=90^{\\circ}$ 이므로 $\\overline{BP}=\\sqrt{16-9}=\\sqrt{7}$ 이다. 4번은 옳지 않다. $\\sin(\\angle ABC)=\\frac{3}{4}$ 이고 $\\angle ADC=\\angle ABC$ 이므로, 빗변이 $\\overline{AD}=8$ 인 직각삼각형 $ACD$ 에서 $\\overline{AC}=8\\times\\frac{3}{4}=6$ 이다. 5번도 옳지 않다.","확인":"6","스킬":"S6"},{"제목":"보기 2 판정","힌트":"$\\angle BAC=90^{\\circ}$ 이면 $\\overline{BC}$ 의 길이는 얼마여야 하는가?","식":["$\\overline{PC}=\\sqrt{6^{2}-3^{2}}=3\\sqrt{3}$","$\\overline{BC}=\\sqrt{7}+3\\sqrt{3}$","$(\\sqrt{7}+3\\sqrt{3})^{2}=34+6\\sqrt{21}<64$"],"설명":"$\\angle BAC=90^{\\circ}$ 이면 $\\overline{BC}$ 는 지름이므로 $\\overline{BC}=8$ 이어야 한다. $\\triangle APC$ 에서 $\\overline{PC}=3\\sqrt{3}$ 이므로 $\\overline{BC}=\\sqrt{7}+3\\sqrt{3}$ 이다. $\\sqrt{21}<5$ 이므로 $(\\sqrt{7}+3\\sqrt{3})^{2}=34+6\\sqrt{21}<64$ 이고 $\\overline{BC}<8$ 이다. 따라서 $\\angle BAC\\neq90^{\\circ}$ 이다. 2번은 옳지 않고, 옳은 것은 1번, 3번이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-9f16784d267e":{"길":"각의 이등분선의 성질로 두 변의 비를 잡고, 피타고라스 정리로 변의 길이의 관계를 구해 코사인을 계산한다","단계":[{"제목":"변의 비 정하기","힌트":"삼각형에서 각의 이등분선은 맞변을 어떤 비로 나눌까?","식":["$\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}=\\overline{\\mathrm{BD}}:\\overline{\\mathrm{DC}}=2:1$","$\\overline{\\mathrm{AB}}=2a,\\ \\overline{\\mathrm{AC}}=a,\\ \\overline{\\mathrm{BD}}=2b,\\ \\overline{\\mathrm{DC}}=b$"],"설명":"삼각형의 한 각의 이등분선은 맞변을 그 각을 낀 두 변의 비로 나눈다. 비례상수 $a$, $b$를 위와 같이 놓는다.","확인":null,"스킬":"A8"},{"제목":"a와 b의 관계 구하기","고비":true,"힌트":"직각삼각형 $\\mathrm{ABC}$에서 빗변은 어느 변이고, 세 변 사이에 어떤 식이 성립할까?","식":["$(2a)^2=(3b)^2+a^2$","$3a^2=9b^2,\\ a=\\sqrt{3}\\,b$"],"설명":"$\\angle \\mathrm{C}=90^{\\circ}$이므로 빗변은 $\\overline{\\mathrm{AB}}$이고 $\\overline{\\mathrm{BC}}=\\overline{\\mathrm{BD}}+\\overline{\\mathrm{DC}}=3b$이다. 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"},{"제목":"cos x 구하기","힌트":"직각삼각형 $\\mathrm{ACD}$에서 $\\cos x$는 어느 두 변의 비일까?","식":["$\\overline{\\mathrm{AD}}=\\sqrt{a^2+b^2}=2b$","$\\cos x=\\frac{\\overline{\\mathrm{AC}}}{\\overline{\\mathrm{AD}}}=\\frac{\\sqrt{3}\\,b}{2b}=\\frac{\\sqrt{3}}{2}$"],"설명":"$\\angle \\mathrm{DAC}=x$이므로 $\\cos x$는 $\\frac{\\overline{\\mathrm{AC}}}{\\overline{\\mathrm{AD}}}$이다. $a=\\sqrt{3}\\,b$를 대입해 $\\overline{\\mathrm{AD}}$와 비를 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-9f8ba76a6a1b":{"길":"두 변과 끼인각으로 세 삼각형의 넓이를 식으로 쓰고, 서로 같게 놓아 세 길이 사이의 관계를 찾는다.","단계":[{"제목":"세 삼각형의 넓이 식","힌트":"두 변의 길이와 그 끼인각을 알 때 삼각형의 넓이는 어떻게 나타낼까?","식":["$\\frac{1}{2}ab\\sin 30^{\\circ}$","$\\frac{1}{2}ac\\sin 60^{\\circ}$","$\\frac{1}{2}bc\\sin 45^{\\circ}$"],"설명":"삼각형의 넓이는 두 변의 곱에 끼인각의 사인을 곱한 값의 절반이다. 그림의 세 삼각형에 각각 적용한다.","확인":null,"스킬":"S6","고비":true},{"제목":"넓이를 같게 놓기","힌트":"세 넓이가 같다는 조건에 삼각비의 값을 넣으면 어떤 식이 되나?","식":["$ab=\\sqrt{3}ac=\\sqrt{2}bc$"],"설명":"$\\sin 30^{\\circ}=\\frac{1}{2}$, $\\sin 60^{\\circ}=\\frac{\\sqrt{3}}{2}$, $\\sin 45^{\\circ}=\\frac{\\sqrt{2}}{2}$ 를 넣고 세 식에 같은 수를 곱해 계수를 정리한다.","확인":null,"스킬":"S6","고비":false},{"제목":"b, a 를 c 로 나타내기","힌트":"공통인 변을 약분하면 $b$, $a$ 는 각각 $c$ 의 몇 배가 되나?","식":["$b=\\sqrt{3}c$","$a=\\sqrt{2}c$"],"설명":"$ab=\\sqrt{3}ac$ 의 양변을 $a$ 로 나누고, $ab=\\sqrt{2}bc$ 의 양변을 $b$ 로 나눈다.","확인":null,"스킬":"A8","고비":false},{"제목":"세 길이의 비","힌트":"$a:b:c$ 를 $c$ 에 대한 식으로 쓰면 어떤 비가 되나?","식":["$a:b:c=\\sqrt{2}c:\\sqrt{3}c:c=\\sqrt{2}:\\sqrt{3}:1$"],"설명":"세 항에서 $c$ 를 약분하면 비가 나온다.","확인":null,"스킬":"A8","고비":false}],"fb":"fig/ns/"},"ns-a149243b1330":{"길":"현이 지나지 않는 부분이 중심이 같은 작은 원임을 알고, 두 반지름의 제곱의 차로 넓이를 나타낸다.","단계":[{"제목":"안쪽의 작은 원 찾기","힌트":"길이가 같은 현은 중심에서의 거리도 같다. 현이 한 번도 지나가지 않는 부분은 어떤 도형일까?","식":["$(\\text{현이 지나간 부분})=(\\text{큰 원})-(\\text{작은 원})$"],"설명":"길이가 같은 현은 원의 중심에서 같은 거리에 있다. 따라서 현의 중점들은 중심에서 일정한 거리에 놓이고, 이 중점들을 이으면 큰 원과 중심이 같은 작은 원이 된다. 현은 이 작은 원에 접하며 한 바퀴 돈다.","확인":null,"스킬":"S13","고비":true},{"제목":"반지름 사이의 관계식","힌트":"큰 원의 반지름을 $b$, 작은 원의 반지름을 $a$ 라 하고 중심에서 현에 수선을 그으면 어떤 직각삼각형이 생기나?","식":["$b^{2}=a^{2}+4^{2}$","$b^{2}-a^{2}=16$"],"설명":"큰 원의 중심 O 에서 현의 중점 M 까지 선분 OM 을 그으면 OM 은 현에 수직이다(현의 수직이등분선). 직각삼각형 OMA 에서 빗변은 큰 원의 반지름 $b$, 한 변은 작은 원의 반지름 $a$, 다른 한 변은 현의 길이의 절반이다.","확인":null,"스킬":"S3","고비":false},{"제목":"지나간 부분의 넓이","힌트":"큰 원의 넓이에서 작은 원의 넓이를 빼면 두 반지름의 어떤 식이 되나?","식":["$\\pi b^{2}-\\pi a^{2}=\\pi(b^{2}-a^{2})$","$=16\\pi$"],"설명":"$\\pi$ 로 묶으면 앞 단계의 $b^{2}-a^{2}$ 가 그대로 나타난다.","확인":null,"스킬":"S13","고비":false}],"fb":"fig/ns/"},"ns-a2fbf3d881d3":{"길":"두 선분의 길이 비로 점의 x좌표를 문자로 두고, 같은 직선 위의 두 점의 y좌표가 같다는 조건으로 식을 세운다.","단계":[{"제목":"PA 와 PD 의 비","힌트":"$3\\overline{PA}=4\\overline{PD}$ 에서 두 선분의 길이의 비는 어떻게 되나?","식":["$\\overline{PA}:\\overline{PD}=4:3$"],"설명":"등식의 양변을 같은 수로 나누어 비례식으로 바꾼다.","확인":null,"스킬":"A8","고비":false},{"제목":"점 A, D 의 좌표","힌트":"$k>0$ 으로 두고 A, D 의 x좌표를 $k$ 로 나타내면 y좌표는 각각 어떻게 되나?","식":["$\\mathrm{A}(-4k,\\ 16k^{2})$","$\\mathrm{D}(3k,\\ 9ak^{2})$"],"설명":"A 는 y축의 왼쪽, D 는 오른쪽에 있고 y축까지의 거리가 각각 $4k$, $3k$ 이다. A 는 $y=x^{2}$ 위의 점이므로 y좌표가 $16k^{2}$, D 는 $y=ax^{2}$ 위의 점이므로 y좌표가 $9ak^{2}$ 이다.","확인":null,"스킬":"G1","고비":true},{"제목":"y좌표를 같게 놓아 a 구하기","힌트":"직선 $l$ 이 $x$축과 평행하므로 A 와 D 의 y좌표 사이에 어떤 관계가 있나?","식":["$9ak^{2}=16k^{2}$","$a=\\frac{16}{9}$"],"설명":"양변을 $k^{2}$ 으로 나누면 $a$ 의 값이 나온다.","확인":"16/9","스킬":"G1","고비":false}],"fb":"fig/ns/"},"ns-b74769e3d16b":{"길":"두 정사각형의 한 변을 a, b 로 나타내 넓이의 차에서 곱 ab 를 구하고, 분자를 a+b 로 묶어 약분한 뒤 대입한다.","단계":[{"제목":"BD 와 DC 의 길이","힌트":"D 가 $\\overline{AC}$ 의 중점일 때 $\\overline{DC}$, $\\overline{BD}$ 를 $a$, $b$ 로 나타내면?","식":["$\\overline{DC}=\\frac{a+b}{2}$","$\\overline{BD}=\\frac{b-a}{2}$"],"설명":"$\\overline{AC}=a+b$ 이고 D 가 중점이므로 $\\overline{DC}=\\frac{a+b}{2}$ 이다. 그림에서 $\\overline{BC}=b$ 이므로 $\\overline{BD}=b-\\frac{a+b}{2}$ 이다.","확인":null,"스킬":"A2","고비":false},{"제목":"ab 의 값","힌트":"$S_{2}-S_{1}$ 을 곱셈 공식으로 전개하면 어떤 값만 남나?","식":["$S_{2}-S_{1}=\\left(\\frac{a+b}{2}\\right)^{2}-\\left(\\frac{b-a}{2}\\right)^{2}=ab$","$ab=11$"],"설명":"$S_{2}$, $S_{1}$ 은 각각 $\\overline{DC}$, $\\overline{BD}$ 를 한 변으로 하는 정사각형의 넓이이다. 제곱의 차를 전개하면 $ab$ 만 남는다.","확인":"11","스킬":"A2","고비":false},{"제목":"분자를 a+b 로 묶기","힌트":"분자 $2ab^{2}+a+2a^{2}b+b$ 를 $a+b$ 가 보이도록 묶으면?","식":["$\\frac{2ab(a+b)+(a+b)}{a+b}=2ab+1$"],"설명":"$2ab^{2}+2a^{2}b=2ab(a+b)$ 이고 $a+b$ 는 $a+b$ 로 묶이므로 분자가 $(2ab+1)(a+b)$ 가 되어 약분된다.","확인":null,"스킬":"A2","고비":true},{"제목":"식의 값","힌트":"$ab$ 의 값을 대입하면?","식":["$2\\times11+1=23$"],"설명":"앞에서 구한 $ab=11$ 을 $2ab+1$ 에 넣는다.","확인":"23","스킬":"A2","고비":false}],"fb":"fig/ns/"},"ns-bb37e0b4ca52":{"길":"모눈 위 정사각형의 넓이로 한 변의 길이를 구하고, 수직선에서 점의 좌표와 정수 부분·소수 부분을 구해 보기를 하나씩 판별한다.","단계":[{"제목":"정사각형의 한 변","힌트":"모눈 위의 큰 정사각형에서 직각삼각형 네 개를 빼면 정사각형 ABCD 의 넓이는?","식":["$3\\times3-4\\times\\frac{1}{2}\\times1\\times2=5$","$\\overline{AB}=\\overline{BC}=\\sqrt{5}$"],"설명":"넓이가 5 인 정사각형이므로 한 변의 길이는 5 의 양의 제곱근이다.","확인":null,"스킬":"S8","고비":false},{"제목":"점 P, Q 의 좌표","힌트":"그림에서 점 B 의 좌표는 $-1$ 이다. B 에서 왼쪽, 오른쪽으로 한 변의 길이만큼 가면 $a$, $b$ 는?","식":["$a=-1-\\sqrt{5}$","$b=-1+\\sqrt{5}$"],"설명":"$\\overline{PB}=\\overline{AB}=\\sqrt{5}$, $\\overline{BQ}=\\overline{BC}=\\sqrt{5}$ 이고 P 는 B 의 왼쪽, Q 는 B 의 오른쪽에 있다.","확인":null,"스킬":"N8","고비":false},{"제목":"정수 부분과 소수 부분","힌트":"$2<\\sqrt{5}<3$ 을 이용해 $b$ 가 어느 두 정수 사이에 있는지 보면?","식":["$1<-1+\\sqrt{5}<2$","$x=1,\\ y=-2+\\sqrt{5}$"],"설명":"정수 부분이 $1$ 이므로 소수 부분은 $b$ 에서 $1$ 을 뺀 값이다.","확인":null,"스킬":"N7","고비":true},{"제목":"보기 판별","힌트":"각 보기를 앞에서 구한 값과 비교하면 옳은 것은 몇 개인가?","식":["$\\overline{QB}=\\sqrt{5}$","$y=-2+\\sqrt{5}$"],"설명":"ㄱ 은 $-1-\\sqrt{5}$, ㄴ 은 $\\sqrt{5}$, ㄷ 은 $-1+\\sqrt{5}$, ㅁ 은 $2\\sqrt{5}$, ㅂ 은 $x=1$, ㅇ 은 $a+xy=-3$ 이어야 하므로 틀리다. 옳은 보기는 ㄹ 과 ㅅ 두 개이다.","확인":"2","스킬":"N7","고비":false}],"fb":"fig/ns/"},"ns-bd6c2eeaba94":{"길":"B, C 에서 직선 AD 에 수선을 내려 높이를 삼각비로 구하고, 두 직각삼각형의 닮음비로 BD:DC 를 구한다.","단계":[{"제목":"수선 긋기","힌트":"$\\overline{BD}:\\overline{DC}$ 를 높이의 비로 바꾸려면 B, C 에서 직선 AD 에 어떤 선분을 그어야 할까?","식":["$\\overline{BP}\\perp\\overline{AD},\\ \\overline{CQ}\\perp\\overline{AD}$"],"설명":"B 에서 직선 AD 에 내린 수선의 발을 P, C 에서 직선 AD 에 내린 수선의 발을 Q 라 한다. P, Q 는 발문에 없는 점이며 해설 그림처럼 직선 AD 위에 놓는다.","확인":null,"스킬":"S2","고비":true},{"제목":"BP 의 길이","힌트":"직각삼각형 ABP 에서 $\\angle BAP=60^{\\circ}$ 이고 빗변이 $4$ 일 때 $\\overline{BP}$ 는?","식":["$\\overline{BP}=4\\sin 60^{\\circ}=2\\sqrt{3}$"],"설명":"빗변이 $\\overline{AB}$ 이고 $\\angle BAP$ 의 대변이 $\\overline{BP}$ 이므로 사인을 쓴다.","확인":null,"스킬":"S6","고비":false},{"제목":"CQ 의 길이","힌트":"직각삼각형 ACQ 에서 $\\angle CAQ=45^{\\circ}$ 이고 빗변이 $\\sqrt{6}$ 일 때 $\\overline{CQ}$ 는?","식":["$\\overline{CQ}=\\sqrt{6}\\sin 45^{\\circ}=\\sqrt{3}$"],"설명":"빗변이 $\\overline{AC}$ 이고 $\\angle CAQ$ 의 대변이 $\\overline{CQ}$ 이다.","확인":null,"스킬":"S6","고비":false},{"제목":"닮음으로 비 구하기","힌트":"삼각형 BDP 와 CDQ 는 어떤 조건으로 닮음일까?","식":["$\\triangle BDP\\sim\\triangle CDQ$","$\\overline{BD}:\\overline{DC}=\\overline{BP}:\\overline{CQ}=2:1$"],"설명":"$\\angle BPD=\\angle CQD=90^{\\circ}$ 이고 $\\angle BDP=\\angle CDQ$ (맞꼭지각)이므로 AA 닮음이다. 대응하는 변의 비가 같으므로 $\\overline{BD}:\\overline{DC}=\\overline{BP}:\\overline{CQ}$ 이다.","확인":null,"스킬":"S1","고비":false}],"fb":"fig/ns/"},"ns-c2202e7388cc":{"길":"P 의 좌표를 한 문자로 두어 직사각형의 넓이를 이차식으로 나타내고, 완전제곱 꼴로 고쳐 최대가 되는 때를 찾는다.","단계":[{"제목":"넓이를 식으로 나타내기","힌트":"P 의 $x$좌표를 $p$ 라 하면 직사각형 PQOR 의 가로와 세로는 각각 얼마인가?","식":["$\\mathrm{P}\\left(p,\\ \\frac{4}{3}p+4\\right)$","$S=-p\\left(\\frac{4}{3}p+4\\right)$"],"설명":"P 는 제2사분면의 점이므로 $p<0$ 이다. 가로는 $-p$, 세로는 P 의 $y$좌표 $\\frac{4}{3}p+4$ 이다.","확인":null,"스킬":"G10","고비":true},{"제목":"완전제곱 꼴로 고치기","힌트":"$S$ 를 $(p+\\square)^{2}$ 꼴을 포함한 식으로 고치면?","식":["$S=-\\frac{4}{3}\\left(p+\\frac{3}{2}\\right)^{2}+3$"],"설명":"$S=-\\frac{4}{3}(p^{2}+3p)$ 에서 $p^{2}+3p$ 를 완전제곱식으로 만들고 더한 값을 보정한다.","확인":null,"스킬":"A6","고비":false},{"제목":"점 P 의 좌표","힌트":"넓이가 최대일 때의 $p$ 와 그때의 $y$좌표는?","식":["$p=-\\frac{3}{2}$","$\\mathrm{P}\\left(-\\frac{3}{2},\\ 2\\right)$"],"설명":"$S$ 는 $p=-\\frac{3}{2}$ 일 때 최대이다. 이때 $y$좌표는 $\\frac{4}{3}\\times\\left(-\\frac{3}{2}\\right)+4$ 이다.","확인":null,"스킬":"G10","고비":false}],"fb":"fig/ns/"},"ns-c2a889b585f7":{"길":"합동으로 ∠CBF 를 구하고 코사인으로 BF, BI 를 차례로 구한 뒤 두 이등변삼각형의 넓이를 더한다.","단계":[{"제목":"합동으로 각 구하기","힌트":"$\\overline{BE}=\\overline{BF}$, $\\overline{AB}=\\overline{CB}$ 인 두 직각삼각형 ABE, CBF 는 어떤 합동일까?","식":["$\\triangle ABE\\equiv\\triangle CBF$","$\\angle ABE=\\angle CBF=30^{\\circ}$"],"설명":"직각과 빗변, 다른 한 변이 각각 같으므로 RHS 합동이다. $\\angle ABE+\\angle EBF+\\angle CBF=90^{\\circ}$ 이고 $\\angle EBF=30^{\\circ}$ 이므로 합동인 두 각은 각각 $30^{\\circ}$ 이다.","확인":null,"스킬":"S10","고비":true},{"제목":"BF 의 길이","힌트":"직각삼각형 BCF 에서 $\\angle CBF=30^{\\circ}$, $\\overline{BC}=3$ 일 때 $\\overline{BF}$ 는?","식":["$\\overline{BF}=\\frac{3}{\\cos 30^{\\circ}}=2\\sqrt{3}$"],"설명":"밑변 $\\overline{BC}$ 와 빗변 $\\overline{BF}$ 사이에 코사인을 쓴다.","확인":null,"스킬":"S6","고비":false},{"제목":"BI 의 길이","힌트":"직각삼각형 BFI 에서 $\\overline{BF}$ 를 알 때 $\\overline{BI}$ 는?","식":["$\\overline{BI}=\\frac{2\\sqrt{3}}{\\cos 30^{\\circ}}=4$"],"설명":"I 는 직선 BC 위의 점이므로 $\\angle FBI=30^{\\circ}$ 이고, 정사각형 BGHF 에서 $\\angle BFI=90^{\\circ}$ 이다.","확인":"4","스킬":"S6","고비":false},{"제목":"두 삼각형의 넓이의 합","힌트":"끼인각이 $30^{\\circ}$ 인 두 이등변삼각형의 넓이는 각각 얼마인가?","식":["$\\triangle BEF=\\frac{1}{2}\\times(2\\sqrt{3})^{2}\\times\\sin 30^{\\circ}=3$","$\\triangle BIJ=\\frac{1}{2}\\times4^{2}\\times\\sin 30^{\\circ}=4$","$3+4=7$"],"설명":"$\\overline{BE}=\\overline{BF}=2\\sqrt{3}$, $\\overline{BI}=\\overline{BJ}=4$ 이고 끼인각이 모두 $30^{\\circ}$ 이다.","확인":"7","스킬":"S6","고비":false}],"fb":"fig/ns/"},"ns-c582cf7ef96b":{"길":"암호의 두 수를 이차식으로 만들어 인수분해하고, 나온 두 수를 부호로 삼아 표의 열과 행에서 글자를 찾아 합친다.","단계":[{"제목":"첫 글자의 이차식 인수분해","힌트":"암호 $(-2,-3)$, $(3,2)$ 를 각각 $x^{2}+(a+b)x+ab$ 로 만들어 인수분해하면?","식":["$x^{2}-2x-3=(x-3)(x+1)$","$x^{2}+3x+2=(x+2)(x+1)$"],"설명":"그림의 규칙에서 $(a+b,\\ ab)$ 는 $x^{2}+(a+b)x+ab=(x+a)(x+b)$ 로 바뀐다.","확인":null,"스킬":"C6","고비":true},{"제목":"첫 글자 찾기","힌트":"인수분해한 식에서 $(a,\\ b)$ 를 읽어 표에서 찾으면?","식":["$(a,\\ b)=(-3,\\ 1)$","$(a,\\ b)=(2,\\ 1)$"],"설명":"표는 열이 a, 행이 b 이다. (-3, 1) 은 ㅁ, (2, 1) 은 ㅣ 이고 두 글자를 합치면 '미' 가 된다.","확인":null,"스킬":"C6","고비":false},{"제목":"둘째 글자 찾기","힌트":"$(-5,6)$, $(2,-3)$ 도 같은 방법으로 인수분해하고 표에서 찾으면?","식":["$x^{2}-5x+6=(x-2)(x-3)$","$x^{2}+2x-3=(x+3)(x-1)$"],"설명":"각각 (-2, -3) 과 (3, -1) 이 된다. (-2, -3) 은 ㄴ, (3, -1) 은 ㅕ 이고 두 글자를 합치면 '녀' 가 된다.","확인":null,"스킬":"C6","고비":false},{"제목":"단어 만들기","힌트":"두 글자를 차례로 이으면 어떤 단어가 되나?","식":[],"설명":"'미' 와 '녀' 를 이으면 '미녀' 이다.","확인":null,"스킬":"C6","고비":false}],"fb":"fig/ns/"},"ns-c72f9d95b335":{"길":"이웃한 칸 사이의 호가 모두 같음을 이용해 각 원주각이 마주 보는 호를 세고, 호의 비로 크기를 구한다.","단계":[{"제목":"각이 마주 보는 호 세기","힌트":"$\\angle x$, $\\angle y$ 가 각각 마주 보는 호는 이웃한 칸 사이 호의 몇 개일까?","식":["$\\frac{2}{10},\\ \\frac{3}{10}$"],"설명":"열 개의 칸이 일정한 간격이므로 이웃한 칸 사이의 호는 모두 같고 원 전체의 $\\frac{1}{10}$ 이다. $\\angle x$ 는 두 개, $\\angle y$ 는 세 개의 호를 마주 본다.","확인":null,"스킬":"S5","고비":true},{"제목":"원주각의 크기","힌트":"원주각은 호의 길이에 비례하고 원 전체의 호에 대한 원주각은 $180^{\\circ}$ 로 볼 수 있다. 각각 얼마인가?","식":["$\\angle x=180^{\\circ}\\times\\frac{2}{10}=36^{\\circ}$","$\\angle y=180^{\\circ}\\times\\frac{3}{10}=54^{\\circ}$"],"설명":"호가 원 전체의 몇 분의 몇인지에 맞춰 크기를 정한다.","확인":null,"스킬":"S5","고비":false},{"제목":"두 각의 합","힌트":"$\\angle x$ 와 $\\angle y$ 를 더하면?","식":["$x+y=36+54=90$"],"설명":"두 각의 크기를 더한다.","확인":"90","스킬":"S5","고비":false}],"fb":"fig/ns/"},"ns-c860de59185c":{"길":"정사각형의 넓이로 한 변을 구해 a, b 를 정하고, 주어진 식을 인수분해해 a-b 와 a+b 의 값을 대입한다.","단계":[{"제목":"정사각형의 한 변","힌트":"모눈 위의 큰 정사각형에서 직각삼각형 네 개를 빼면 정사각형 ABCD 의 넓이는?","식":["$\\square ABCD=3\\times3-4\\times\\frac{1}{2}\\times1\\times2=5$","$\\overline{AB}=\\overline{AD}=\\sqrt{5}$"],"설명":"넓이가 5 인 정사각형이므로 한 변의 길이는 5 의 양의 제곱근이다.","확인":null,"스킬":"A2","고비":false},{"제목":"a, b 의 값","힌트":"그림에서 점 A 의 대응 수는 $2$ 이다. A 에서 한 변의 길이만큼 왼쪽, 오른쪽에 있는 점이 P, Q 일 때 $a$, $b$ 는?","식":["$a=2-\\sqrt{5}$","$b=2+\\sqrt{5}$"],"설명":"$\\overline{AP}=\\overline{AD}$, $\\overline{AQ}=\\overline{AB}$ 이고 P 는 A 의 왼쪽, Q 는 A 의 오른쪽에 있다.","확인":null,"스킬":"A2","고비":false},{"제목":"식을 인수분해하기","힌트":"$b-a=-(a-b)$ 임을 이용해 $a-b$ 로 묶으면?","식":["$(a-b)a^{2}-(a-b)b^{2}=(a-b)(a^{2}-b^{2})=(a-b)^{2}(a+b)$"],"설명":"두 번째 항의 $b-a$ 를 $-(a-b)$ 로 고치면 공통인수 $a-b$ 가 보이고, $a^{2}-b^{2}$ 는 합과 차의 곱으로 인수분해한다.","확인":null,"스킬":"A6","고비":true},{"제목":"값 대입","힌트":"$a-b$ 와 $a+b$ 의 값을 구해 대입하면?","식":["$a-b=-2\\sqrt{5},\\ a+b=4$","$(-2\\sqrt{5})^{2}\\times4=80$"],"설명":"$a$, $b$ 의 값을 더하고 빼서 구한 뒤 인수분해한 식에 넣는다.","확인":"80","스킬":"A2","고비":false}],"fb":"fig/ns/"},"ns-c9489edb4faa":{"길":"그래프의 꼭짓점과 y절편으로 이차함수의 식을 세우고, 땅에 떨어질 때의 높이가 0 임을 이용해 방정식을 푼다.","단계":[{"제목":"꼭짓점으로 식 세우기","힌트":"꼭짓점이 $(2,\\ 50)$ 인 이차함수의 식은 어떤 꼴로 놓나?","식":["$y=a(x-2)^{2}+50$"],"설명":"꼭짓점의 좌표를 알면 꼭짓점 꼴로 놓고 남은 상수 하나만 정하면 된다.","확인":null,"스킬":"G7","고비":true},{"제목":"a 의 값 구하기","힌트":"그래프가 $y$축과 만나는 점 $(0,\\ 30)$ 을 대입하면?","식":["$30=a\\times(0-2)^{2}+50$","$a=-5$"],"설명":"$y$ 절편이 30 이므로 $x=0$, $y=30$ 을 식에 넣는다.","확인":"-5","스킬":"G7","고비":false},{"제목":"땅에 떨어지는 때의 방정식","힌트":"땅에 떨어질 때 높이 $y$ 는 얼마이고, 그때의 식은 어떻게 정리되나?","식":["$-5(x-2)^{2}+50=0$","$x^{2}-4x-6=0$"],"설명":"높이가 $0$ 이 되는 $x$ 를 구하는 것이므로 $y=0$ 을 넣고 양변을 $-5$ 로 나누어 전개한다.","확인":null,"스킬":"G1","고비":false},{"제목":"걸리는 시간","힌트":"방정식의 두 근 중 시간으로 알맞은 것은?","식":["$x=2+\\sqrt{10}$"],"설명":"$(x-2)^{2}=10$ 에서 $x=2\\pm\\sqrt{10}$ 이고 시간은 양수이므로 $x>0$ 인 근을 택한다.","확인":null,"스킬":"G1","고비":false}],"fb":"fig/ns/"},"ns-cdde9b68e251":{"길":"포물선이 직사각형과 두 점에서 만나는 범위를 점 $B$, 점 $D$를 지날 때의 $a$ 값으로 가른다.","단계":[{"제목":"경계 경우 찾기","힌트":"$a$가 너무 작거나 너무 크면 포물선과 직사각형은 어떻게 될까?","식":[],"설명":"$a$가 너무 작으면 포물선이 $B(4,1)$ 아래로 지나가고, 너무 크면 $D(2,4)$ 위로 지나가서 직사각형과 만나지 않는다. 두 점에서 만나는 범위는 점 $B$를 지날 때와 점 $D$를 지날 때 사이이다.","확인":null,"스킬":"G1","고비":true},{"제목":"점 B 조건","힌트":"점 $B(4,1)$보다 아래로 지나지 않으려면 $x=4$에서 $y$ 값은 어떠해야 할까?","식":["$16a>1$","$a>\\frac{1}{16}$"],"설명":"$x=4$에서 포물선의 $y$ 값 $16a$가 $1$보다 커야 한다.","확인":null,"스킬":"G6"},{"제목":"점 D 조건","힌트":"점 $D(2,4)$보다 위로 지나지 않으려면 $x=2$에서 $y$ 값은 어떠해야 할까?","식":["$4a<4$","$a<1$"],"설명":"$x=2$에서 포물선의 $y$ 값 $4a$가 $4$보다 작아야 한다.","확인":null,"스킬":"G6"},{"제목":"범위 밖의 선지 고르기","힌트":"$\\frac{1}{16}<a<1$에 들어가지 않는 선지는?","식":["$\\frac{1}{16}<a<1$"],"설명":"$\\frac15$, $\\frac14$, $\\frac13$, $\\frac12$은 이 범위에 들어가고 $1$은 들어가지 않는다. 따라서 옳지 않은 것은 ⑤이다.","확인":null,"스킬":"G6"}],"fb":"fig/ns/"},"ns-cf0bc439482b":{"길":"그래프의 절편으로 a, b를 구한 뒤 이차함수의 꼭짓점·축·볼록 방향·폭을 식에서 읽는다.","단계":[{"제목":"절편으로 a, b 구하기","힌트":"그림에서 $y$절편과 $x$절편은 각각 얼마이고, 그러면 $a$는?","식":["$b=3$","$0=4a+3,\\ a=-\\frac34$"],"설명":"$y$절편이 $b$이므로 $b=3$이다. $x$절편이 $4$이므로 직선은 점 $(4,0)$을 지난다.","확인":null,"스킬":"G9"},{"제목":"이차함수 식 쓰기","힌트":"$a$, $b$ 값을 넣고 $\\frac{b}{a}$를 계산하면?","식":["$\\frac{b}{a}=3\\div\\left(-\\frac34\\right)=-4$","$y=-\\frac34(x+3)^2-4$"],"설명":"$a=-\\frac34$, $b=3$을 $y=a(x+b)^2+\\frac{b}{a}$에 대입한다.","확인":null,"스킬":"A6","고비":true},{"제목":"보기 하나씩 판정","힌트":"꼭짓점, 축, 볼록 방향, 폭, $x$축과의 교점을 식에서 읽으면?","식":["$\\text{꼭짓점}:\\ (-3,\\,-4)$"],"설명":"꼭짓점이 $(-3,-4)$이므로 ④가 옳다. ①은 위로 볼록하고 꼭짓점의 $y$ 좌표가 음수라서 $x$축과 만나지 않고, ②는 축이 $x=-3$이고, ③은 $a<0$이라 위로 볼록하며, ⑤는 $\\left|-\\frac34\\right|>\\left|-\\frac12\\right|$이므로 폭이 더 좁다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-d02ace9e3bd0":{"길":"새 빗변은 앞 선분을 $\\cos30^\\circ$로 나눈 값이므로 같은 계산을 차례로 반복한다.","단계":[{"제목":"첫 빗변 BO","힌트":"직각삼각형 $OAB$에서 $\\cos30^\\circ$는 어느 두 변의 비일까?","식":["$\\overline{BO}=\\frac{3}{\\cos30^\\circ}=2\\sqrt3$"],"설명":"$\\cos30^\\circ=\\frac{\\overline{OA}}{\\overline{BO}}$이므로 $\\overline{BO}=\\overline{OA}\\div\\cos30^\\circ$이다.","확인":null,"스킬":"S6"},{"제목":"반복 규칙 찾기","힌트":"다음 삼각형들에서 새 선분은 앞 선분에 어떤 수를 곱한 것일까?","식":["$\\overline{CO}=4$","$\\overline{DO}=\\frac{8\\sqrt3}{3}$","$\\overline{EO}=\\frac{16}{3}$","$\\overline{FO}=\\frac{32\\sqrt3}{9}$","$\\overline{GO}=\\frac{64}{9}$"],"설명":"각 직각삼각형에서 앞 삼각형의 빗변이 밑변이고 한 내각이 $30^\\circ$이므로, 새 빗변은 앞 선분에 $\\frac{1}{\\cos30^\\circ}=\\frac{2}{\\sqrt3}$를 곱한 값이다.","확인":null,"스킬":"P1","고비":true},{"제목":"OH 구하기","힌트":"$\\overline{GO}$에 같은 규칙을 한 번 더 쓰면?","식":["$\\overline{HO}=\\frac{64}{9}\\times\\frac{2}{\\sqrt3}=\\frac{128\\sqrt3}{27}$"],"설명":"분모를 유리화하여 $\\frac{128\\sqrt3}{27}$로 나타낸다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-d09e4fe3dbbd":{"길":"직각삼각형 $CDH$에서 $\\angle x$, $\\angle y$가 어느 꼭짓점의 각인지 찾고 보기를 하나씩 판별한다.","단계":[{"제목":"같은 각 찾기","힌트":"$\\angle x$와 같은 각은 삼각형 $CDH$ 안에 있을까?","식":["$\\angle DCH=\\angle x$","$\\angle CDH=\\angle y$"],"설명":"$\\angle x+\\angle CDH=90^\\circ$이고 $\\angle CDH+\\angle DCH=90^\\circ$이므로 $\\angle DCH=\\angle x$이다. $\\angle ACD=\\angle DCH=\\angle x$이고 $\\angle ACB+\\angle ACD=90^\\circ$이므로 $\\angle x+\\angle y=90^\\circ$이고, $\\angle CDH=90^\\circ-\\angle x=\\angle y$이다.","확인":null,"스킬":"S10","고비":true},{"제목":"㈎ 판별","힌트":"직각삼각형 $ABC$에서 $\\sin y$는?","식":["$\\sin y=\\frac{\\overline{AB}}{\\overline{AC}}=\\frac{1}{\\overline{CA}}$"],"설명":"$\\overline{AB}=1$이므로 ㈎는 옳다.","확인":null,"스킬":"S6"},{"제목":"㈏㈐㈑ 판별","힌트":"직각삼각형 $CDH$에서 $\\angle x$는 꼭짓점 $C$, $\\angle y$는 꼭짓점 $D$에 있다. 각각의 삼각비는?","식":["$\\cos x=\\frac{\\overline{CH}}{\\overline{CD}}$","$\\tan y=\\frac{\\overline{CH}}{\\overline{DH}}$","$\\tan x=\\frac{\\overline{HD}}{\\overline{CH}}$"],"설명":"㈏는 분자가 $\\overline{DH}$가 아니라 $\\overline{CH}$이므로 틀렸다. ㈐는 $\\frac{\\overline{DH}}{\\overline{CH}}$가 아니라 $\\frac{\\overline{CH}}{\\overline{DH}}$이므로 틀렸다. ㈑은 옳다. 따라서 옳은 것은 ㈎, ㈑이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-db986aa181d8":{"길":"평균 식과 분산 식을 $a$, $m$에 대한 두 식으로 세우고 $a$를 소거해 $m$을 구한다.","단계":[{"제목":"평균 식 세우기","힌트":"다섯 학생이 읽은 책의 합을 $m$으로 나타내면?","식":["$\\frac{3+5+1+6+a}{5}=m$","$a=5m-15$"],"설명":"합 $15+a$가 $5m$과 같다.","확인":null,"스킬":"A10"},{"제목":"분산 식 세우기","힌트":"분산을 (제곱의 평균)$-$(평균의 제곱)으로 쓰면?","식":["$\\frac{3^2+5^2+1^2+6^2+a^2}{5}-m^2=9.2$","$5m^2-a^2=25$"],"설명":"$9+25+1+36=71$이므로 양변에 $5$를 곱하면 $71+a^2-5m^2=46$이다.","확인":null,"스킬":"A10","고비":true},{"제목":"a를 없애 m의 식 만들기","힌트":"$a=5m-15$를 분산 식에 넣으면?","식":["$5m^2-(5m-15)^2=25$","$2m^2-15m+25=0$"],"설명":"전개하면 $-20m^2+150m-225=25$이고, 양변을 $-10$으로 나눈다.","확인":null,"스킬":"A10"},{"제목":"m, a 정하기","힌트":"이차식을 인수분해하면 $m$의 값은?","식":["$(2m-5)(m-5)=0$","$m=5,\\ a=10$"],"설명":"$m=\\frac52$이면 $a=-\\frac52$로 자연수가 아니므로 $m=5$이고 $a=10$이다.","확인":null,"스킬":"A10"},{"제목":"a+m 구하기","힌트":"$a$와 $m$을 더하면?","식":["$a+m=10+5=15$"],"설명":"구한 두 값을 더한다.","확인":"15","스킬":"A10"}],"fb":"fig/ns/"},"ns-dee7beb9b26f":{"길":"$x$축에 평행하다는 조건을 두 꼭짓점의 $y$좌표가 같다는 식으로 바꾼다.","단계":[{"제목":"평행 조건 바꾸기","힌트":"$x$축에 평행한 직선 위의 두 점은 무엇이 같을까?","식":[],"설명":"$x$축에 평행한 직선 위의 점은 $y$좌표가 모두 같다. 따라서 두 꼭짓점의 $y$좌표가 같다.","확인":null,"스킬":"A6","고비":true},{"제목":"첫 번째 꼭짓점","힌트":"$2x^2-12x$를 $2(x-\\square)^2$ 꼴로 묶으면?","식":["$y=2(x-3)^2+3k-17$","$(3,\\,3k-17)$"],"설명":"$2x^2-12x+3k+1=2(x-3)^2-18+3k+1$이다.","확인":null,"스킬":"A6"},{"제목":"두 번째 꼭짓점","힌트":"$y=-5(x+2)^2+25-4k$의 꼭짓점은?","식":["$(-2,\\,25-4k)$"],"설명":"이미 꼭짓점 꼴이므로 바로 읽는다.","확인":null,"스킬":"A6"},{"제목":"k 구하기","힌트":"두 꼭짓점의 $y$좌표를 같다고 놓으면?","식":["$3k-17=25-4k$","$k=6$"],"설명":"$7k=42$이다.","확인":"6","스킬":"A6"}],"fb":"fig/ns/"},"ns-e0069d94c33a":{"길":"두 점에서 수선을 그어 닮은 직각삼각형을 만들고, 대응변의 비로 $EF$를 구한다.","단계":[{"제목":"AM 구하기","힌트":"$AC$, $AD$, $CD$가 모두 $1$이면 삼각형 $ACD$는 어떤 삼각형일까?","식":["$\\angle ADC=60^\\circ$","$\\overline{AM}=1\\times\\sin60^\\circ=\\frac{\\sqrt3}{2}$"],"설명":"$A$에서 $CD$에 내린 수선의 발을 $M$이라 한다. 삼각형 $ACD$는 정삼각형이다.","확인":null,"스킬":"S6"},{"제목":"EN 구하기","힌트":"$B$, $C$, $D$, $F$는 한 직선 위에 있다. $\\angle EDF$는 몇 도일까?","식":["$\\angle EDF=180^\\circ-60^\\circ-90^\\circ=30^\\circ$","$\\overline{EN}=1\\times\\sin30^\\circ=\\frac12$"],"설명":"$E$에서 $DF$에 내린 수선의 발을 $N$이라 한다. $\\angle ADF=180^\\circ-60^\\circ=120^\\circ$이고 $\\angle ADE=90^\\circ$이다.","확인":null,"스킬":"S6"},{"제목":"AE 구하기","힌트":"직각이등변삼각형 $ADE$에서 $AE$는?","식":["$\\overline{AE}=\\sqrt{1^2+1^2}=\\sqrt2$"],"설명":"$\\overline{AD}=\\overline{DE}=1$이고 $\\angle ADE=90^\\circ$이다.","확인":null,"스킬":"S3"},{"제목":"닮은 삼각형 찾기","힌트":"$\\triangle AMF$와 $\\triangle ENF$에서 같은 각은?","식":["$\\triangle AMF\\sim\\triangle ENF$","$\\overline{AM}:\\overline{AF}=\\overline{EN}:\\overline{EF}$"],"설명":"$\\angle AMF=\\angle ENF=90^\\circ$이고 $\\angle F$는 공통이므로 $AA$ 닮음이다. $\\overline{EF}=x$라 하면 $E$가 $AF$ 위의 점이므로 $\\overline{AF}=\\sqrt2+x$이다.","확인":null,"스킬":"S1","고비":true},{"제목":"EF 구하기","힌트":"비례식에서 $x$를 구하면?","식":["$\\frac{\\sqrt3}{2}:(\\sqrt2+x)=\\frac12:x$","$x=\\frac{\\sqrt2}{\\sqrt3-1}=\\frac{\\sqrt6+\\sqrt2}{2}$"],"설명":"내항의 곱과 외항의 곱을 같게 하면 $\\frac{\\sqrt3}{2}x=\\frac12(\\sqrt2+x)$이고, 정리하면 $(\\sqrt3-1)x=\\sqrt2$이다. 분모를 유리화한다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-e41558363dea":{"길":"밑면의 대각선 $FH$와 입체의 대각선 $FD$를 차례로 구한 뒤 직각삼각형 $DFH$에서 $\\cos x$를 쓴다.","단계":[{"제목":"FH 구하기","힌트":"$\\overline{DH}=a$라 하면 밑면의 대각선 $FH$는?","식":["$\\overline{FG}=3a,\\ \\overline{GH}=2a$","$\\overline{FH}=\\sqrt{9a^2+4a^2}=\\sqrt{13}a$"],"설명":"밑면 $FGHE$는 직사각형이므로 직각삼각형 $FGH$에 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"},{"제목":"FD 구하기","힌트":"모서리 $DH$는 밑면과 어떤 관계라서 삼각형 $FHD$는 어떤 삼각형일까?","식":["$\\overline{FD}=\\sqrt{13a^2+a^2}=\\sqrt{14}a$"],"설명":"$\\overline{DH}$가 밑면에 수직이므로 $\\angle FHD=90^\\circ$이다.","확인":null,"스킬":"S3","고비":true},{"제목":"cos x 구하기","힌트":"직각삼각형 $DFH$에서 $\\angle DFH$의 코사인은 어느 두 변의 비일까?","식":["$\\cos x=\\frac{\\overline{FH}}{\\overline{FD}}=\\frac{\\sqrt{13}a}{\\sqrt{14}a}=\\frac{\\sqrt{182}}{14}$"],"설명":"$\\sqrt{13}\\div\\sqrt{14}$의 분모를 유리화한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-e5016777cc89":{"길":"호의 길이와 원주각이 정비례함을 이용해 두 원주각을 구하고 삼각형의 내각의 합으로 $\\angle x$를 구한다.","단계":[{"제목":"호 AC의 원주각","힌트":"지름에 대한 원주각은 몇 도이고, 호 $AC$는 그중 몇 분의 몇일까?","식":["$\\angle ADC=90^\\circ\\times\\frac59=50^\\circ$"],"설명":"$\\overset{\\frown}{AC}:\\overset{\\frown}{BC}=5:4$이므로 반원의 호 $ACB$에 대한 원주각 $90^\\circ$ 중 $\\overset{\\frown}{AC}$에 대한 원주각이 $\\frac59$이다. 호의 길이와 원주각의 크기는 정비례한다.","확인":"50","스킬":"S5","고비":true},{"제목":"호 BD의 원주각","힌트":"호 $BD$는 반원의 호 $ADB$ 중 얼마일까?","식":["$\\angle BAD=90^\\circ\\times\\frac25=36^\\circ$"],"설명":"$\\overset{\\frown}{AD}:\\overset{\\frown}{BD}=3:2$이므로 $\\overset{\\frown}{BD}$는 반원의 $\\frac25$이고, $\\overset{\\frown}{BD}$에 대한 원주각은 $\\angle BAD$이다.","확인":"36","스킬":"S5"},{"제목":"각 x 구하기","힌트":"$AB$와 $CD$의 교점을 $P$라 할 때 삼각형 $PAD$의 내각의 합은?","식":["$\\angle x=180^\\circ-(36^\\circ+50^\\circ)=94^\\circ$"],"설명":"$\\angle x=\\angle APD$이고 $\\angle PAD=\\angle BAD$, $\\angle PDA=\\angle ADC$이다.","확인":"94","스킬":"S10"}],"fb":"fig/ns/"},"ns-f1a3134c4a1d":{"길":"원 $O'$의 접선 길이로 $AB$를 구하고, 직각삼각형 $ABE$의 내접원 반지름은 넓이로 구해 보기를 판별한다.","단계":[{"제목":"접선의 길이로 AE 나타내기","힌트":"원 $O'$의 반지름을 $R$이라 하면 $AB$와 $AE$는?","식":["$\\overline{AB}=\\overline{CD}=2R$","$\\overline{AG}=\\overline{AH}=12-R$","$\\overline{EI}=\\overline{EH}=4-R$","$\\overline{AE}=16-2R$"],"설명":"원 $O'$이 $AD$, $AE$, $EC$와 닿는 점을 각각 $G$, $H$, $I$라 한다. $AB$는 원 $O'$의 지름과 같으므로 $2R$이고 $\\overline{EC}=12-8=4$이다. 한 점에서 원에 그은 두 접선의 길이는 같다.","확인":null,"스킬":"S5","고비":true},{"제목":"R 구하기","힌트":"직각삼각형 $ABE$에 피타고라스 정리를 쓰면?","식":["$4R^2+64=(16-2R)^2$","$64R=192,\\ R=3$"],"설명":"$\\overline{AB}=2R$, $\\overline{BE}=8$, $\\overline{AE}=16-2R$이다.","확인":"3","스킬":"S3"},{"제목":"원 O의 반지름 구하기","힌트":"삼각형의 넓이를 내접원의 반지름 $r$과 세 변으로 나타내면?","식":["$\\overline{AB}=6,\\ \\overline{BE}=8,\\ \\overline{AE}=10$","$\\frac12\\times6\\times8=\\frac12\\times r\\times(6+8+10)$","$r=2$"],"설명":"삼각형의 넓이는 $\\frac12\\times r\\times(\\text{세 변의 합})$으로도 나타낼 수 있다.","확인":"2","스킬":"S8"},{"제목":"보기 ①②③ 판정","힌트":"원 $O$의 반지름과 두 원의 넓이, 삼각형의 둘레는?","식":["$\\pi\\times2^2+\\pi\\times3^2=13\\pi$","$6+8+10=24$"],"설명":"①은 $r=2$이므로 옳지 않다. ②는 $13\\pi$이므로 옳고, ③은 둘레가 $24$이므로 옳다.","확인":null,"스킬":"C3"},{"제목":"OO′ 구하기","힌트":"점 $O$에서 $O'I$에 내린 수선의 발 $P$를 잡으면 $O'P$와 $OP$는?","식":["$\\overline{O'P}=3-2=1$","$\\overline{OP}=12-2-3=7$","$\\overline{OO'}=\\sqrt{1^2+7^2}=5\\sqrt2$"],"설명":"$O'I$는 반지름 $3$이고 $O$는 $BE$에서 $2$ 높이에 있으므로 $\\overline{O'P}=3-2=1$이다. $O$는 $AB$에서 $2$, $O'$은 $CD$에서 $3$ 떨어져 있으므로 $\\overline{OP}=12-2-3=7$이다. 따라서 ④는 옳고 ⑤는 옳지 않다. 옳지 않은 것은 ①, ⑤이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-f4c50dac8cd4":{"길":"처음 가로를 x 로 두고 상자의 가로·세로·높이를 x 로 나타내 부피를 이차방정식으로 만든 뒤 푼다.","단계":[{"제목":"처음 세로의 길이","힌트":"처음 가로를 $x\\,\\mathrm{cm}$ 라 하면 세로는 얼마일까?","식":["$x-4$"],"설명":"가로가 세로보다 $4\\,\\mathrm{cm}$ 더 길므로 세로는 $x-4$이다.","확인":null,"스킬":"C7"},{"제목":"상자의 세 변","힌트":"넓이가 $4\\,\\mathrm{cm}^2$ 인 정사각형을 네 귀퉁이에서 잘라 내면 가로·세로·높이는 각각 얼마가 될까?","식":["$x-4,\\ x-8,\\ 2$"],"설명":"잘라 낸 정사각형의 한 변이 $2$이므로 높이가 $2$이다. 가로와 세로는 양쪽에서 $2$씩 줄어 각각 $4$만큼 짧아진다. 가로는 $x-4$, 세로는 $(x-4)-4=x-8$이다.","확인":null,"스킬":"C7"},{"제목":"부피식 세우기","힌트":"(가로)$\\times$(세로)$\\times$(높이)가 $384$ 라는 식을 쓰고 정리하면?","식":["$2(x-4)(x-8)=384$","$x^2-12x-160=0$"],"설명":"상자의 부피는 가로, 세로, 높이의 곱이다. 전개해 정리하면 이차방정식이 된다.","확인":null,"스킬":"C7","고비":true},{"제목":"이차방정식 풀기","힌트":"인수분해하면 어떤 근이 나오고, 길이로 쓸 수 있는 것은?","식":["$(x-20)(x+8)=0$","$x=20$"],"설명":"$x>0$이므로 $x=20$이다. 처음 직사각형의 가로의 길이는 $20\\,\\mathrm{cm}$이다.","확인":"20","스킬":"C7"}],"fb":"fig/ns/"},"ns-f4cfd5ec2e93":{"길":"정육면체의 선분 길이를 피타고라스로 구해 삼각형 DIH 를 만들고, 수선을 그어 두 삼각비를 읽는다.","단계":[{"제목":"삼각형 DIH 의 세 변","힌트":"직각삼각형 $BID$, $FIH$ 에서 $\\overline{ID}$, $\\overline{IH}$ 는?","식":["$\\overline{BD}=\\overline{FH}=3\\sqrt2$","$\\overline{ID}=\\sqrt{19}$","$\\overline{IH}=\\sqrt{22}$"],"설명":"$\\overline{BI}=1$, $\\overline{IF}=2$이고 $\\overline{BD}$, $\\overline{FH}$ 는 한 변이 $3$인 정사각형의 대각선이므로 $3\\sqrt2$이다. 직각삼각형 $BID$, $FIH$ 에 피타고라스 정리를 쓴다. $\\overline{DH}=3$이다.","확인":null,"스킬":"S3"},{"제목":"수선의 발 잡기","힌트":"삼각형 $DIH$ 에서 $I$ 로부터 $\\overline{DH}$ 에 수선을 그으면 어떤 두 직각삼각형이 생길까?","식":["$\\overline{IP}^{2}=22-k^{2}=19-(3-k)^{2}$"],"설명":"점 $I$ 에서 $\\overline{DH}$ 에 내린 수선의 발을 $P$라 하고 $\\overline{HP}=k$ 라 하면 $\\overline{PD}=3-k$이다. $\\overline{IP}^{2}$ 을 직각삼각형 $IHP$, $IDP$ 에서 각각 피타고라스 정리로 나타낸다.","확인":null,"스킬":"S2","고비":true},{"제목":"k 와 IP 구하기","힌트":"두 식을 같다고 놓으면 $k$ 는?","식":["$6k=12,\\ k=2$","$\\overline{IP}=\\sqrt{22-4}=3\\sqrt2$"],"설명":"양변의 $k^{2}$ 이 없어져 $k$ 에 대한 일차방정식이 된다. $\\overline{HP}=2$, $\\overline{PD}=1$이다.","확인":"2","스킬":"S3"},{"제목":"sin x, cos y 읽기","힌트":"직각삼각형 $IHP$, $IDP$ 에서 $\\sin x$, $\\cos y$ 는 각각 어느 두 변의 비일까?","식":["$\\sin x=\\frac{\\overline{IP}}{\\overline{IH}}=\\frac{3\\sqrt{2}}{\\sqrt{22}}=\\frac{3\\sqrt{11}}{11}$","$\\cos y=\\frac{\\overline{PD}}{\\overline{ID}}=\\frac{1}{\\sqrt{19}}=\\frac{\\sqrt{19}}{19}$"],"설명":"$\\angle IHD=x$ 는 직각삼각형 $IHP$ 의 한 각이고, $\\angle IDH=y$ 는 직각삼각형 $IDP$ 의 한 각이다.","확인":null,"스킬":"S6"},{"제목":"두 값의 합","힌트":"두 값을 더하면 선지 중 어느 것과 같을까?","식":["$\\sin x+\\cos y=\\frac{3\\sqrt{11}}{11}+\\frac{\\sqrt{19}}{19}$"],"설명":"두 값을 더하면 선지 ⑤와 같다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-fa1e75ddbcbd":{"길":"각 선지를 특수각의 삼각비 값으로 계산하고, 일차함수의 기울기가 tan 값임을 써서 다섯 값을 비교한다.","단계":[{"제목":"선지 ①~③ 계산","힌트":"①, ②, ③ 에 특수각의 삼각비 값을 넣으면 각각 얼마일까?","식":["$1-\\frac{\\sqrt2}{2}$","$-1$","$\\frac{13}{12}$"],"설명":"$\\sin45^\\circ=\\cos45^\\circ=\\frac{\\sqrt2}{2}$, $\\tan45^\\circ=1$, $\\sin90^\\circ=1$, $\\cos60^\\circ=\\frac12$, $\\tan30^\\circ=\\frac{1}{\\sqrt3}$, $\\sin60^\\circ=\\cos30^\\circ=\\frac{\\sqrt3}{2}$, $\\cos90^\\circ=0$을 넣어 계산한다. 계산하면 ①은 $1-\\frac{\\sqrt2}{2}$, ②는 $-1$, ③은 $\\frac{13}{12}$이다.","확인":null,"스킬":"S6"},{"제목":"선지 ④, ⑤ 값","힌트":"④ 에서 $\\tan\\alpha$ 는 직선의 무엇과 같고, ⑤ 에서 근을 넣으면 $a$ 는?","식":["$\\tan\\alpha=\\frac32$","$a=3-\\sqrt3$"],"설명":"일차함수가 $x$축과 이루는 각의 $\\tan$ 값은 그래프의 기울기와 같다. $3x-2y+3=0$을 $y$에 대해 풀면 기울기가 $\\frac32$이다. ⑤는 $x=\\sin60^\\circ=\\frac{\\sqrt3}{2}$를 방정식에 대입해 $a$를 구한다.","확인":null,"스킬":"G9","고비":true},{"제목":"크기 비교","힌트":"다섯 값을 어림값으로 바꾸어 비교하면 가장 큰 것은?","식":["$0.29,\\ -1,\\ 1.08,\\ 1.5,\\ 1.27$"],"설명":"①은 약 $0.29$, ②는 $-1$, ③은 약 $1.08$, ④는 $1.5$, ⑤는 약 $1.27$이다. 가장 큰 값은 ④이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-fd5890886853":{"길":"두 내접사각형의 외각 성질을 이어 보기마다 평행 조건을 따진다","단계":[{"제목":"각 PDE 와 각 A 의 비교","힌트":"$\\angle PDE$ 는 원 O' 의 내접사각형에서 어느 각과 같은가?","식":["$\\angle PDE=\\angle PQC$","$\\angle PQC=\\angle A$"],"설명":"사각형 PDCQ 는 원 O' 에 내접하므로 꼭짓점 D 의 외각 $\\angle PDE$ 는 마주 보는 안쪽 각 $\\angle PQC$ 와 같다. 사각형 ABQP 는 원 O 에 내접하므로 꼭짓점 Q 의 외각 $\\angle PQC$ 는 마주 보는 안쪽 각 $\\angle A$ 와 같다. 따라서 ① 은 옳다.","확인":null,"스킬":"S5"},{"제목":"각 C 와 각 APQ 의 비교","힌트":"점 P 에서 원 O' 의 내접사각형 PDCQ 의 외각은 어느 각인가?","식":["$\\angle C=\\angle APQ$"],"설명":"A, P, D 는 한 직선 위에 있으므로 $\\angle APQ$ 는 사각형 PDCQ 의 꼭짓점 P 의 외각이다. 이 외각은 마주 보는 안쪽 각 $\\angle C$ 와 같다.","확인":null,"스킬":"S10"},{"제목":"각 B 와 각 C 의 합, 그리고 AB 와 EC","힌트":"원 O 의 내접사각형 ABQP 에서 $\\angle B$ 와 짝을 이루는 각은 어느 각인가?","식":["$\\angle B+\\angle APQ=180^{\\circ}$","$\\angle B+\\angle C=180^{\\circ}$"],"설명":"사각형 ABQP 는 원 O 에 내접하므로 마주 보는 두 각 $\\angle B$, $\\angle APQ$ 의 합이 $180^{\\circ}$ 이다. $\\angle C=\\angle APQ$ 이므로 ② 가 옳다. 직선 BC 가 두 직선 AB, EC 와 만나 이루는 동측내각의 합이 $180^{\\circ}$ 이므로 $\\overline{AB}\\parallel\\overline{EC}$ 이고 ④ 도 옳다.","확인":null,"스킬":"S10"},{"제목":"③ 과 ⑤ 의 성립 여부","힌트":"$\\angle A+\\angle C$ 를 $\\angle A$ 와 $\\angle APQ$ 의 합으로 바꾸면 어떤 평행 조건과 같아지는가?","식":["$\\angle A+\\angle C=\\angle A+\\angle APQ$","$\\angle A+\\angle APQ=180^{\\circ}\\iff\\overline{AB}\\parallel\\overline{PQ}$"],"설명":"직선 AP 가 두 직선 AB, PQ 와 만날 때 $\\angle A+\\angle APQ=180^{\\circ}$ 인 것과 $\\overline{AB}\\parallel\\overline{PQ}$ 인 것은 서로 필요충분조건이다. 그런데 주어진 조건만으로는 $\\overline{AB}\\parallel\\overline{PQ}$ 가 정해지지 않는다. 그래서 ③ 과 ⑤ 는 항상 성립하지 않고, 틀린 것은 ③, ⑤ 이다.","확인":null,"스킬":"S5","고비":true}],"fb":"fig/ns/"},"ns-fd7321858297":{"길":"점 A 의 x 좌표를 a 로 두고 두 포물선 위의 점들을 a 로 나타낸 뒤 변의 비로 a 를 구한다.","단계":[{"제목":"A, D 의 좌표","힌트":"점 $A$ 의 $x$ 좌표를 $a$ 라 하면 $A$, $D$ 의 좌표는?","식":["$\\mathrm{A}\\left(a,\\ \\frac13a^{2}\\right)$","$\\mathrm{D}\\left(a,\\ 3a^{2}\\right)$"],"설명":"$\\overline{AD}$ 가 $y$축에 평행하므로 $D$ 의 $x$ 좌표도 $a$이다. $A$ 는 $y=\\frac13x^{2}$ 위의 점이고 $D$ 는 $y=3x^{2}$ 위의 점이다.","확인":null,"스킬":"S4"},{"제목":"C 의 좌표","힌트":"$\\overline{DC}$ 가 $x$축에 평행하면 $C$ 의 $y$ 좌표는, $C$ 가 $y=\\frac13x^{2}$ 위에 있으면 $x$ 좌표는?","식":["$\\frac13x^{2}=3a^{2}$","$x=3a$","$\\mathrm{C}\\left(3a,\\ 3a^{2}\\right)$"],"설명":"$C$ 의 $y$ 좌표는 $D$ 와 같은 $3a^{2}$이다. 그림에서 $C$ 는 $D$ 의 오른쪽에 있으므로 $x$ 좌표는 양수 $3a$이다.","확인":null,"스킬":"S4","고비":true},{"제목":"두 변의 길이와 비","힌트":"$\\overline{AB}$ 와 $\\overline{BC}$ 를 $a$ 로 나타내고 $1:2$ 를 식으로 쓰면?","식":["$\\overline{AB}=\\overline{DC}=3a-a=2a$","$\\overline{BC}=\\overline{AD}=3a^{2}-\\frac13a^{2}=\\frac83a^{2}$","$2a:\\frac83a^{2}=1:2$"],"설명":"직사각형에서 마주 보는 변의 길이는 같다. 비례식에서 내항의 곱과 외항의 곱이 같으므로 $\\frac83a^{2}=4a$이다.","확인":null,"스킬":"A8"},{"제목":"a 와 둘레","힌트":"$a>0$ 에서 $a$ 를 구하고 둘레를 계산하면?","식":["$a=\\frac32$","$2\\left(2a+\\frac83a^{2}\\right)=2(3+6)=18$"],"설명":"$\\frac83a^{2}=4a$ 의 양변을 $a$ 로 나누면 $a=\\frac32$이다. $\\overline{AB}=3$, $\\overline{BC}=6$이므로 둘레는 $18$이다.","확인":"18","스킬":"A8"}],"fb":"fig/ns/"},"ns-025e808cf6f0":{"길":"두 수의 정수 부분을 제곱근 크기 비교로 찾아 a, b 를 구하고, √(a-b)² 은 절댓값이므로 a-b 의 부호를 판정한다.","단계":[{"제목":"a 구하기","힌트":"$4\\sqrt7$ 을 $\\sqrt{\\ }$ 꼴로 바꾸면 어느 두 정수 사이에 있을까?","식":["$4\\sqrt7=\\sqrt{112}$","$10<\\sqrt{112}<11$","$a=4\\sqrt7-10$"],"설명":"$10^{2}=100$, $11^{2}=121$이므로 정수 부분은 $10$이다. 소수 부분은 수에서 정수 부분을 뺀 값이다.","확인":null,"스킬":"N7"},{"제목":"b 구하기","힌트":"$2\\sqrt7=\\sqrt{28}$ 이므로 $8-2\\sqrt7$ 의 정수 부분은?","식":["$5<\\sqrt{28}<6$","$2<8-2\\sqrt7<3$","$b=6-2\\sqrt7$"],"설명":"부등식의 각 변에 $-1$ 을 곱하고 $8$ 을 더한다. 정수 부분이 $2$이므로 $b=(8-2\\sqrt7)-2$이다.","확인":null,"스킬":"N7"},{"제목":"a-b 계산","힌트":"$a-b$ 는 얼마일까?","식":["$a-b=(4\\sqrt7-10)-(6-2\\sqrt7)=6\\sqrt7-16$"],"설명":"무리수 부분과 정수 부분을 따로 모아 계산한다.","확인":null,"스킬":"N7"},{"제목":"부호 판정","힌트":"$\\sqrt{A^{2}}=|A|$ 이다. $6\\sqrt7$ 과 $16$ 중 어느 것이 클까?","식":["$6\\sqrt7=\\sqrt{252}<\\sqrt{256}=16$","$\\sqrt{(a-b)^{2}}=-(6\\sqrt7-16)=16-6\\sqrt7$"],"설명":"$6\\sqrt7-16<0$ 이므로 $\\sqrt{A^{2}}=-A$이다.","확인":null,"스킬":"C2","고비":true}],"fb":"fig/ns/"},"ns-03c3fbd3acf9":{"길":"전체 인원과 합격자 수를 문자로 두고 (평균)×(인원)으로 총점을 써서 전체 평균 식을 세운 뒤 비를 구한다.","단계":[{"제목":"총점 쓰기","힌트":"전체 학생 수를 $n$, 합격자 수를 $a$ 라 하면 합격자와 불합격자의 점수 총합은 각각 얼마일까?","식":["$82a$","$66(n-a)$"],"설명":"(평균)$\\times$(인원수)가 총점이다. 불합격자는 $n-a$명이다.","확인":null,"스킬":"C7"},{"제목":"평균 식 세우기","힌트":"전체 총점을 $n$ 으로 나눈 값이 $70$ 이라는 식을 세우고 정리하면?","식":["$\\frac{82a+66(n-a)}{n}=70$","$16a=4n$","$n=4a$"],"설명":"분모를 없애고 정리하면 $n$ 과 $a$ 의 관계가 정해진다.","확인":null,"스킬":"C7","고비":true},{"제목":"합격률 구하기","힌트":"합격률 $\\frac{a}{n}\\times100$ 에 $n=4a$ 를 넣으면?","식":["$\\frac{a}{4a}\\times100=25$"],"설명":"합격률은 $25\\%$이다.","확인":"25","스킬":"C7"}],"fb":"fig/ns/"},"ns-056b784fa1ce":{"길":"식을 전개해 a, b 에 대한 이차식으로 만들고 b² 으로 나눠 a/b 의 이차방정식으로 푼 뒤 a>b>0 으로 근을 고른다.","단계":[{"제목":"전개해 정리하기","힌트":"$(a+b)^{2}=5ab$ 를 전개해 한쪽으로 모으면?","식":["$a^{2}+2ab+b^{2}=5ab$","$a^{2}-3ab+b^{2}=0$"],"설명":"곱셈 공식으로 전개한 뒤 $5ab$ 를 좌변으로 옮긴다.","확인":null,"스킬":"A1"},{"제목":"a/b 로 바꾸기","힌트":"$b>0$ 이므로 양변을 $b^{2}$ 으로 나누면 $\\frac ab$ 만 남는 식은?","식":["$\\left(\\frac ab\\right)^{2}-3\\cdot\\frac ab+1=0$"],"설명":"$\\frac ab=t$ 로 두면 $t^{2}-3t+1=0$이다.","확인":null,"스킬":"A1","고비":true},{"제목":"근의 공식과 조건","힌트":"근의 공식으로 $t$ 를 구하고 $a>b>0$ 에서 $t$ 의 범위를 쓰면?","식":["$t=\\frac{3\\pm\\sqrt5}{2}$","$t>1$","$\\frac ab=\\frac{3+\\sqrt5}{2}$"],"설명":"$a>b>0$ 이므로 $\\frac ab>1$이다. $\\frac{3-\\sqrt5}{2}$ 는 $1$ 보다 작아 조건에 맞지 않는다.","확인":null,"스킬":"A1"}],"fb":"fig/ns/"},"ns-05bf8c1db0b9":{"길":"a 를 상수로 보고 y 를 소거해 x, y 를 구한 뒤, x-y 와 x+y 를 완전제곱식으로 만들고 0<a<3 으로 부호를 정한다.","단계":[{"제목":"대입해 x 의 식 만들기","힌트":"첫째 식에서 $y$ 를 $x$ 로 나타내어 둘째 식에 넣으면 $x$ 에 대한 식은?","식":["$y=ax-a^{3}-3a$","$(9-a^{2})x=81-a^{4}$"],"설명":"$a$ 는 상수로 보고 $y$ 를 소거한다. 둘째 식에 대입해 정리하면 $x$ 의 계수가 $9-a^{2}$이다.","확인":null,"스킬":"A10"},{"제목":"x, y 구하기","힌트":"$0<a<3$ 이므로 $9-a^{2}\\ne0$ 이다. $81-a^{4}$ 를 인수분해해 나누면?","식":["$81-a^{4}=(9-a^{2})(9+a^{2})$","$x=9+a^{2}$","$y=a(9+a^{2})-a^{3}-3a=6a$"],"설명":"$0<a<3$ 이면 $9-a^{2}>0$ 이므로 양변을 나눌 수 있다. $y$ 는 $y=ax-a^{3}-3a$ 에 $x$ 를 대입해 구한다.","확인":null,"스킬":"A10"},{"제목":"근호 안 완전제곱","힌트":"$x-y$, $x+y$ 에 $x$, $y$ 를 넣으면 근호 안은 어떤 꼴일까?","식":["$x-y=a^{2}-6a+9=(a-3)^{2}$","$x+y=a^{2}+6a+9=(a+3)^{2}$"],"설명":"$x=9+a^{2}$ 에서 $y=6a$ 를 빼거나 더하면 완전제곱식이 된다.","확인":null,"스킬":"A6"},{"제목":"부호 따지기","힌트":"$\\sqrt{A^{2}}=|A|$ 이다. $0<a<3$ 일 때 $a-3$, $a+3$ 의 부호는?","식":["$\\sqrt{(a-3)^{2}}=-(a-3)=3-a$","$\\sqrt{(a+3)^{2}}=a+3$","$(3-a)-(a+3)=-2a$"],"설명":"$a-3<0$ 이므로 절댓값을 벗길 때 부호가 바뀌고, $a+3>0$ 이므로 그대로이다.","확인":null,"스킬":"C2","고비":true}],"fb":"fig/ns/"},"ns-0e99b5cb640e":{"길":"근호 안을 곱의 꼴로 인수분해하고, 주사위 눈의 범위에서 나올 수 있는 곱의 값을 따져 제곱수가 되는 순서쌍을 센다.","단계":[{"제목":"인수분해","힌트":"$xy-4y-2x+8$ 을 묶어 곱의 꼴로 바꾸면?","식":["$xy-4y-2x+8=(x-4)(y-2)$"],"설명":"$y$ 가 들어 있는 항끼리 $y(x-4)$ 로 묶고 나머지를 $-2(x-4)$ 로 묶으면 공통인수가 나온다.","확인":null,"스킬":"N4"},{"제목":"가능한 곱의 범위","힌트":"$x$, $y$ 는 $1$ 부터 $6$ 까지이다. $x-4$, $y-2$ 의 범위와 곱의 최댓값은?","식":["$-3\\le x-4\\le2$","$-1\\le y-2\\le4$","$(x-4)(y-2)\\le8$"],"설명":"곱이 가장 큰 경우는 $2\\times4=8$이다. 근호 안이 자연수의 제곱이 되려면 $0$ 보다 큰 제곱수여야 하므로 $1$ 또는 $4$이다.","확인":null,"스킬":"N8","고비":true},{"제목":"순서쌍 찾기","힌트":"곱이 $1$ 인 경우와 $4$ 인 경우에 범위 안에 있는 $(x-4,\\ y-2)$ 는?","식":["$(x-4,\\ y-2)=(-1,-1),\\ (1,1),\\ (1,4),\\ (2,2)$"],"설명":"곱이 $1$ 이면 $(-1,-1)$, $(1,1)$ 이고 곱이 $4$ 이면 $(1,4)$, $(2,2)$ 가 범위에 들어간다. $(-2,-2)$, $(4,1)$ 등은 범위를 벗어난다.","확인":null,"스킬":"P4"},{"제목":"순서쌍의 개수","힌트":"$(x,\\ y)$ 로 되돌리면 모두 몇 개일까?","식":["$(x,\\ y)=(3,1),\\ (5,3),\\ (5,6),\\ (6,4)$"],"설명":"순서쌍은 모두 $4$개이다.","확인":"4","스킬":"P4"}],"fb":"fig/ns/"},"ns-0f457aa28a56":{"길":"근을 식에 넣고 a 로 나눠 2a+1/a 의 값을 얻은 뒤, 합의 제곱과 차의 제곱의 관계로 2a-1/a 를 구한다.","단계":[{"제목":"근 대입","힌트":"$a$ 가 근이므로 식에 넣고 $a$ 로 나누면 어떤 합의 꼴이 나올까?","식":["$2a^{2}-5a+1=0$","$2a-5+\\frac1a=0$","$2a+\\frac1a=5$"],"설명":"$a=0$ 은 근이 아니므로 양변을 $a$ 로 나눌 수 있다.","확인":null,"스킬":"A12"},{"제목":"제곱의 관계","힌트":"$\\left(2a-\\frac1a\\right)^{2}$ 과 $\\left(2a+\\frac1a\\right)^{2}$ 의 차는 얼마일까?","식":["$\\left(2a-\\frac1a\\right)^{2}=\\left(2a+\\frac1a\\right)^{2}-4\\cdot2a\\cdot\\frac1a$","$=\\left(2a+\\frac1a\\right)^{2}-8$"],"설명":"$(x-y)^{2}=(x+y)^{2}-4xy$ 에서 $x=2a$, $y=\\frac1a$, $xy=2$이다.","확인":null,"스킬":"A2","고비":true},{"제목":"값 구하기","힌트":"$2a+\\frac1a=5$ 를 넣으면 제곱은 얼마이고, $2a-\\frac1a$ 는?","식":["$\\left(2a-\\frac1a\\right)^{2}=25-8=17$","$2a-\\frac1a=\\pm\\sqrt{17}$"],"설명":"제곱해서 $17$ 이 되는 수는 $\\pm\\sqrt{17}$이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-10148a9cf7aa":{"길":"x-y 를 한 문자로 치환해 이차방정식을 풀고, x<y 로 값을 고른 뒤 일차식과 연립한다.","단계":[{"제목":"치환","힌트":"(3) 의 $x-y$ 를 $A$ 로 놓으면 $A$ 에 대한 식은?","식":["$A(A-1)=12$","$A^{2}-A-12=0$"],"설명":"공통으로 들어 있는 $x-y$ 를 $A$ 로 바꾸면 $A$ 에 대한 이차방정식이 된다.","확인":null,"스킬":"A1"},{"제목":"A 의 값 고르기","힌트":"인수분해로 얻은 두 값 중 $x<y$ 에 맞는 것은?","식":["$(A-4)(A+3)=0$","$x-y=-3$"],"설명":"$A=4$ 또는 $A=-3$이다. $x<y$ 이면 $x-y<0$ 이므로 $A=-3$이다.","확인":null,"스킬":"A1","고비":true},{"제목":"연립해 풀기","힌트":"$2x+y=5$ 와 $x-y=-3$ 을 변끼리 더하면?","식":["$3x=2$","$x=\\frac23,\\ y=\\frac{11}{3}$"],"설명":"두 식을 더하면 $y$ 가 사라져 $x$ 에 대한 일차방정식이 된다.","확인":null,"스킬":"A10"}],"fb":"fig/ns/"},"ns-2c41d8cec8e6":{"길":"x=1 을 대입해 t 를 구하고 이차방정식 조건으로 t 를 정한 뒤 다른 근을 구해 거듭제곱의 일의 자리 주기를 쓴다.","단계":[{"제목":"t 구하기","힌트":"한 근이 $1$ 이므로 $x=1$ 을 넣으면 $t$ 에 대한 식은?","식":["$(t-1)-(t^{2}+4)+2t+3=0$","$t^{2}-3t+2=0$","$t=1$ 또는 $t=2$"],"설명":"근은 방정식을 성립시키는 값이므로 $x=1$ 을 대입한다.","확인":null,"스킬":"C2"},{"제목":"이차방정식 조건","힌트":"$x$ 에 대한 이차방정식이려면 $x^{2}$ 의 계수는 어떠해야 할까?","식":["$t-1\\ne0$","$t=2$"],"설명":"$t=1$ 이면 $x^{2}$ 항이 사라져 이차방정식이 아니므로 $t=2$이다.","확인":null,"스킬":"C2","고비":true},{"제목":"다른 근 구하기","힌트":"$t=2$ 일 때 방정식을 인수분해하면?","식":["$x^{2}-8x+7=0$","$(x-1)(x-7)=0$","$a=7$"],"설명":"한 근이 $1$ 이므로 다른 근은 $7$이다.","확인":null,"스킬":"A2"},{"제목":"일의 자리 숫자","힌트":"$7$ 의 거듭제곱의 일의 자리는 어떤 순서로 반복되고, $2016$ 을 반복 주기로 나누면?","식":["$7\\to9\\to3\\to1$","$2016=4\\times504$"],"설명":"일의 자리 숫자가 $7$, $9$, $3$, $1$ 순서로 $4$개씩 반복된다. $2016$ 은 $4$ 의 배수이므로 $7^{2016}$ 의 일의 자리는 주기의 마지막인 $1$이다.","확인":"1","스킬":"N3"}],"fb":"fig/ns/"},"ns-783f7809edcc":{"길":"길이가 같은 모서리가 네 개씩임을 써서 평균으로 a+b+c 를, 분산으로 편차 제곱의 합을 구하고 전개해 a²+b²+c² 를 얻는다.","단계":[{"제목":"평균으로 합 구하기","힌트":"모서리 $12$ 개의 합을 $a$, $b$, $c$ 로 나타내고 평균 식을 세우면?","식":["$\\frac{4(a+b+c)}{12}=6$","$a+b+c=18$"],"설명":"길이가 $a$, $b$, $c$ 인 모서리가 각각 $4$개씩이므로 $12$개의 합은 $4(a+b+c)$이다.","확인":null,"스킬":"C7"},{"제목":"분산 식 세우기","힌트":"표준편차가 $3$ 이면 분산은 얼마이고, 편차의 제곱의 평균으로 식을 세우면?","식":["$\\frac{4\\{(a-6)^{2}+(b-6)^{2}+(c-6)^{2}\\}}{12}=9$","$(a-6)^{2}+(b-6)^{2}+(c-6)^{2}=27$"],"설명":"분산은 (편차)$^{2}$ 의 평균이고 표준편차의 제곱이다.","확인":null,"스킬":"C7","고비":true},{"제목":"전개해 값 구하기","힌트":"편차의 제곱합을 전개한 뒤 $a+b+c=18$ 을 넣으면 $a^{2}+b^{2}+c^{2}$ 는?","식":["$a^{2}+b^{2}+c^{2}-12(a+b+c)+108=27$","$a^{2}+b^{2}+c^{2}-12\\times18+108=27$","$a^{2}+b^{2}+c^{2}=135$"],"설명":"$(a-6)^{2}=a^{2}-12a+36$ 이고 세 식을 더하면 상수항이 $108$이다.","확인":"135","스킬":"A6"}],"fb":"fig/ns/"},"ns-8fe3432184f1":{"길":"두 방정식의 네 근을 구해 근호를 정수 사이에 끼워 크기순을 정하고, b 와 c 를 찾아 분모를 유리화해 합한다.","단계":[{"제목":"네 근 구하기","힌트":"두 이차방정식을 근의 공식으로 풀면?","식":["$x=1\\pm\\sqrt5$","$x=-2\\pm\\sqrt2$"],"설명":"$x^{2}-2x-4=0$ 에서 $x=1\\pm\\sqrt{1+4}$이고, $x^{2}+4x+2=0$ 에서 $x=-2\\pm\\sqrt{4-2}$이다.","확인":null,"스킬":"A6"},{"제목":"근호 어림으로 범위 잡기","힌트":"$\\sqrt5$, $\\sqrt2$ 가 어느 두 정수 사이에 있는지로 네 근의 범위를 잡으면?","식":["$-2<1-\\sqrt5<-1,\\ \\ 3<1+\\sqrt5<4$","$-4<-2-\\sqrt2<-3,\\ \\ -1<-2+\\sqrt2<0$"],"설명":"$2<\\sqrt5<3$, $1<\\sqrt2<2$ 이므로 각 근이 놓인 구간을 정수 사이로 잡을 수 있다.","확인":null,"스킬":"C9","고비":true},{"제목":"b 와 c 정하기","힌트":"작은 것부터 늘어놓았을 때 둘째와 셋째 근은?","식":["$-2-\\sqrt2<1-\\sqrt5<-2+\\sqrt2<1+\\sqrt5$","$b=1-\\sqrt5,\\ \\ c=-2+\\sqrt2$"],"설명":"$a<b<c<d$ 이므로 둘째가 $b$, 셋째가 $c$이다.","확인":null,"스킬":"C9"},{"제목":"분모 유리화","힌트":"$-\\frac1b$ 와 $\\frac1c$ 의 분모를 유리화하면?","식":["$-\\frac{1}{1-\\sqrt5}=\\frac{1+\\sqrt5}{4}$","$\\frac{1}{-2+\\sqrt2}=\\frac{-2-\\sqrt2}{2}$"],"설명":"분모의 켤레를 곱한다. $(\\sqrt5-1)(\\sqrt5+1)=4$, $(-2+\\sqrt2)(-2-\\sqrt2)=2$이다.","확인":null,"스킬":"C9"},{"제목":"두 값의 합","힌트":"분모를 통분해 더하면?","식":["$\\frac{1+\\sqrt5}{4}+\\frac{-4-2\\sqrt2}{4}=\\frac{-2\\sqrt2+\\sqrt5-3}{4}$"],"설명":"분모를 $4$ 로 통분해 분자끼리 더한다.","확인":null,"스킬":"C9"}],"fb":"fig/ns/"},"ns-a86f0ae4725d":{"길":"자료 A 의 중앙값 조건으로 b 를 정하고, 두 자료를 합쳐 크기순으로 나열해 가운데 두 수의 평균으로 a 를 구한다.","단계":[{"제목":"b 정하기","힌트":"$a\\ge b$ 일 때 $b$ 가 $15$ 보다 작으면 자료 $A$ 의 가운데 값은 어떻게 될까?","식":["$b=15$"],"설명":"$b$ 가 $15$ 보다 작으면 $10$, $14$, $b$ 세 수가 모두 $15$ 보다 작아서 가운데 값이 $15$ 보다 작아진다. 따라서 $b=15$이고 $a\\ge15$이다.","확인":null,"스킬":"C2","고비":true},{"제목":"두 자료 합쳐 나열","힌트":"$b=15$ 를 넣고 두 자료를 합친 $10$ 개를 크기순으로 놓으면?","식":["$10,\\ 11,\\ 14,\\ 14,\\ 15,\\ a,\\ a,\\ 21,\\ 22,\\ 22$"],"설명":"자료 $A$ 는 $10, 14, 15, a, 22$, 자료 $B$ 는 $11, 14, a, 21, 22$이다. $a$ 가 $15$ 이상 $21$ 이하라고 보고 늘어놓는다.","확인":null,"스킬":"P4"},{"제목":"중앙값으로 a 구하기","힌트":"열 개의 가운데 두 수의 평균이 $16$ 이라는 식은?","식":["$\\frac{15+a}{2}=16$","$a=17$"],"설명":"자료가 $10$개이므로 중앙값은 $5$번째와 $6$번째 수의 평균이다. $a=17$ 은 가정한 범위에 들어간다.","확인":null,"스킬":"C2"},{"제목":"a+b","힌트":"구한 $a$, $b$ 의 합은?","식":["$a+b=17+15=32$"],"설명":"$a=17$, $b=15$이므로 합은 $32$이다.","확인":"32","스킬":"C2"}],"fb":"fig/ns/"},"ns-a91841ad2693":{"길":"중앙값 184를 편차로 바꾸고, $a$를 작은 값부터 넣어 편차의 가운데 값이 같아지는 첫 값을 찾는다","단계":[{"제목":"중앙값을 편차로 바꾸기","힌트":"평균이 180일 때 중앙값 184는 편차로 얼마인가?","식":["$184-180=4$"],"설명":"편차는 (변량)−(평균)이므로 중앙값 184의 편차는 4이다. 다섯 편차를 크기순으로 놓았을 때 가운데 값이 4이면 된다.","확인":"4","스킬":"C6"},{"제목":"$a=1,\\ 2,\\ 3$ 일 때 가운데 값 확인","힌트":"$a$에 1, 2, 3을 넣고 편차를 크기순으로 나열하면 가운데 값은 얼마인가?","식":["$a=1:\\ -11,\\ 1,\\ 1,\\ 4,\\ 5\\ \\to\\ 1$","$a=2:\\ -11,\\ 0,\\ 2,\\ 4,\\ 5\\ \\to\\ 2$","$a=3:\\ -11,\\ -1,\\ 3,\\ 4,\\ 5\\ \\to\\ 3$"],"설명":"$2-a$와 $a$를 함께 크기순으로 놓으면 가운데 값이 각각 1, 2, 3이 되어 4에 못 미친다.","확인":null,"스킬":"C2","고비":true},{"제목":"$a=4$ 에서 조건 확인","힌트":"$a$가 4일 때 편차의 가운데 값은 얼마인가?","식":["$a=4:\\ -11,\\ -2,\\ 4,\\ 4,\\ 5\\ \\to\\ 4$"],"설명":"$a=4$이면 편차의 가운데 값이 4이고 중앙값은 $180+4=184$가 되어 조건과 맞는다. $a$가 1, 2, 3일 때는 맞지 않으므로 가장 작은 $a$는 4이다.","확인":"4","스킬":"C2"}],"fb":"fig/ns/"},"ns-aed6b96691e5":{"길":"조건에서 $x-a$를 $b$로 나타내고, 이차식을 $x-a$로 묶어 $b$에 대한 방정식으로 바꾼다","단계":[{"제목":"$x-a$를 $b$로 나타내기","힌트":"$x+1=a+b$에서 $x-a$를 한 식으로 정리하면?","식":["$x-a=b-1$"],"설명":"양변에서 $a$와 1을 옮겨 $x-a$를 $b$로 나타낸다.","확인":null,"스킬":"A10"},{"제목":"이차식을 $x-a$로 묶기","힌트":"$x^2-2ax+a^2$은 어떤 완전제곱식인가? 남은 항은 $x-a$로 어떻게 묶이는가?","식":["$(x-a)^2+2(x-a)-3(b-1)=0$"],"설명":"$x^2-2ax+a^2$은 $(x-a)^2$, $2x-2a$는 $2(x-a)$, $-3b+3$은 $-3(b-1)$로 묶는다. 주어진 식이 0이므로 묶은 식도 0이다.","확인":null,"스킬":"A1","고비":true},{"제목":"$b$만의 식으로 바꾸기","힌트":"$x-a$ 자리에 $b-1$을 넣으면 식은 어떻게 되는가?","식":["$(b-1)^2+2(b-1)-3(b-1)=0$","$(b-1)(b-2)=0$"],"설명":"공통인 $b-1$로 묶으면 $(b-1)(b-2)=0$이 된다.","확인":null,"스킬":"A1"},{"제목":"$b$의 값의 합","힌트":"방정식을 만족하는 $b$는 모두 무엇인가?","식":["$b=1,\\ 2$","$1+2=3$"],"설명":"$b=1$ 또는 $b=2$이므로 합은 3이다.","확인":"3","스킬":"A2"}],"fb":"fig/ns/"},"ns-b38128db2322":{"길":"근의 공식에서 근호 안이 제곱수가 되는 조건을 세우고, $k$가 두 자리 수인 범위에서 해당하는 값을 센다","단계":[{"제목":"정수해가 되는 조건","힌트":"근의 공식에서 해가 정수가 되려면 근호 안은 어떤 수여야 하는가?","식":["$x=\\dfrac{5\\pm\\sqrt{25+4k}}{2}$"],"설명":"$25+4k$가 어떤 홀수의 제곱이어야 근호가 사라져 해가 정수가 된다. $25+4k$는 항상 홀수이므로 홀수의 제곱이면 된다.","확인":null,"스킬":"N8"},{"제목":"$k$의 범위로 제곱수 좁히기","힌트":"$k$가 10 이상 99 이하일 때 $25+4k$의 범위는 어디까지인가?","식":["$65\\le 25+4k\\le 421$"],"설명":"$k$가 두 자리 자연수이므로 $10\\le k\\le 99$이다. 이때 $25+4k$는 65 이상 421 이하이고, 이 범위에서 홀수의 제곱을 찾는다.","확인":null,"스킬":"N8","고비":true},{"제목":"$k$의 값 구하기","힌트":"이 범위의 홀수의 제곱을 하나씩 넣으면 $k$는 어떻게 되는가?","식":["$25+4k=81,\\ 121,\\ 169,\\ 225,\\ 289,\\ 361$","$k=14,\\ 24,\\ 36,\\ 50,\\ 66,\\ 84$"],"설명":"홀수 9, 11, 13, 15, 17, 19의 제곱이 범위에 들어간다. 따라서 $k$는 모두 6개이다.","확인":"6","스킬":"N8"}],"fb":"fig/ns/"},"ns-c64589daa547":{"길":"첫째 방정식은 완전제곱식으로 $a,\\ b$를, 둘째 방정식은 계수를 정수로 고쳐 근의 공식으로 $c,\\ d$를 구한다","단계":[{"제목":"$(x+a)^2=b$ 꼴로 고치기","힌트":"4로 나눈 뒤 $x$의 계수의 절반의 제곱을 양변에 더하면 어떻게 되는가?","식":["$x^2-3x=-\\dfrac74$","$\\left(x-\\dfrac32\\right)^2=\\dfrac12$","$a=-\\dfrac32,\\ b=\\dfrac12$"],"설명":"양변을 4로 나눈 뒤 $x^2-3x$에 $\\left(\\frac32\\right)^2=\\frac94$를 더해 완전제곱식으로 만든다.","확인":null,"스킬":"A6","고비":true},{"제목":"계수를 정수로 만들어 근 구하기","힌트":"양변에 10을 곱하면 계수가 모두 정수가 되는가?","식":["$2x^2+4x-1=0$","$x=\\dfrac{-2\\pm\\sqrt6}{2}$"],"설명":"양변에 10을 곱하면 $\\frac25$도 정수 4가 된다. 근의 공식으로 풀면 $c=2,\\ d=6$이다.","확인":null,"스킬":"A6"},{"제목":"$abcd$ 계산","힌트":"네 수를 읽어 곱하면 얼마인가?","식":["$abcd=-\\dfrac32\\times\\dfrac12\\times2\\times6=-9$"],"설명":"$a,\\ b,\\ c,\\ d$를 모두 곱한다.","확인":"-9","스킬":"A6"}],"fb":"fig/ns/"},"ns-c6bdf255edb6":{"길":"근을 대입해 얻은 $a^2-5a=-1$을 이용해 높은 차수의 항을 차례로 낮춘다","단계":[{"제목":"근을 대입해 관계식 만들기","힌트":"$a$가 근이면 $x=a$를 이차방정식에 대입한 식은 어떻게 되는가?","식":["$a^2-5a+1=0$","$a^2-5a=-1$"],"설명":"$x=a$를 대입하면 등식이 성립하고, 이를 $a^2-5a=-1$로 쓴다.","확인":null,"스킬":"A12"},{"제목":"$a^2-5a$를 떼어 4차식으로 낮추기","힌트":"$a^5-5a^4$처럼 $a^2-5a$가 들어 있는 묶음을 만들 수 있는가?","식":["$a^5-7a^4+11a^3-a^2-5a-4=a^3(a^2-5a)-2a^4+11a^3-a^2-5a-4$","$=-2a^4+10a^3-a^2-5a-4$"],"설명":"$a^3(a^2-5a)$를 떼어 $a^2-5a=-1$을 넣으면 $-a^3$이 된다. $a^3$ 항을 합쳐 4차식으로 낮춘다.","확인":null,"스킬":"A12","고비":true},{"제목":"한 번 더 낮춰 계산","힌트":"남은 식에서 $-2a^2(a^2-5a)$ 꼴을 찾을 수 있는가?","식":["$-2a^2(a^2-5a)-a^2-5a-4=a^2-5a-4$","$=-1-4=-5$"],"설명":"$-2a^4+10a^3=-2a^2(a^2-5a)=2a^2$이므로 식은 $a^2-5a-4$가 된다. 다시 $a^2-5a=-1$을 넣는다.","확인":"-5","스킬":"A12"}],"fb":"fig/ns/"},"ns-cc694bc34027":{"길":"근의 공식으로 두 근을 구하고, 근호 값을 어림해 두 근 사이의 정수를 센다","단계":[{"제목":"근의 공식으로 두 근 구하기","힌트":"일차항 계수가 짝수일 때 쓰는 근의 공식으로 풀면?","식":["$x=-4\\pm\\sqrt{4^2-(-3)}=-4\\pm\\sqrt{19}$"],"설명":"일차항 계수 8의 절반인 4로 근의 공식을 쓴다.","확인":null,"스킬":"G8"},{"제목":"$\\sqrt{19}$ 어림으로 두 근의 위치 찾기","힌트":"$\\sqrt{19}$는 어떤 두 정수 사이에 있는가?","식":["$4<\\sqrt{19}<5$","$-9<-4-\\sqrt{19}<-8,\\ \\ 0<-4+\\sqrt{19}<1$"],"설명":"$16<19<25$이므로 $4<\\sqrt{19}<5$이다. 작은 근은 −9와 −8 사이, 큰 근은 0과 1 사이에 있다.","확인":null,"스킬":"G8","고비":true},{"제목":"두 근 사이의 정수 세기","힌트":"작은 근 바로 다음 정수부터 큰 근 바로 앞 정수까지 세면 몇 개인가?","식":["$-8,\\ -7,\\ \\cdots,\\ 0$","$9$"],"설명":"두 근 사이에 있는 정수는 −8부터 0까지로 모두 9개이다.","확인":"9","스킬":"G8"}],"fb":"fig/ns/"},"ns-f51ca107837b":{"길":"두 차를 유리화로 구하고, $(a-b)(c-d)$를 전개한 식에서 $ad+bc$를 $ac+bd$로 나타낸다","단계":[{"제목":"$a-b$ 분모 유리화","힌트":"분모 $2-\\sqrt3$에 곱해 유리수로 만드는 수는 무엇인가?","식":["$a-b=\\dfrac{1}{2-\\sqrt3}=2+\\sqrt3$"],"설명":"분모와 분자에 $2+\\sqrt3$을 곱하면 분모가 $4-3=1$이 된다.","확인":null,"스킬":"A2"},{"제목":"$c-d$ 분모 유리화","힌트":"분모 $2\\sqrt3+3$은 어떤 수를 곱하면 유리수가 되는가?","식":["$c-d=\\dfrac{3}{2\\sqrt3+3}=2\\sqrt3-3$"],"설명":"분모와 분자에 $2\\sqrt3-3$을 곱하면 분모가 $12-9=3$이 되어 $\\frac{3(2\\sqrt3-3)}{3}$이다.","확인":null,"스킬":"A2"},{"제목":"$(a-b)(c-d)$ 전개로 $ad+bc$ 만들기","힌트":"$(a-b)(c-d)$를 전개하면 $ad+bc$는 어디에 나타나는가?","식":["$(a-b)(c-d)=ac+bd-(ad+bc)$","$ad+bc=ac+bd-(a-b)(c-d)$"],"설명":"전개하면 $ac-ad-bc+bd$이므로 $ad+bc$를 $ac+bd$와 $(a-b)(c-d)$로 나타낼 수 있다.","확인":null,"스킬":"A2","고비":true},{"제목":"값 대입","힌트":"$ac+bd$와 $(a-b)(c-d)$에 구한 값을 넣으면?","식":["$ad+bc=2\\sqrt3-(2+\\sqrt3)(2\\sqrt3-3)$","$(2+\\sqrt3)(2\\sqrt3-3)=\\sqrt3$","$ad+bc=\\sqrt3$"],"설명":"$ac+bd=2\\sqrt3$이고 $(2+\\sqrt3)(2\\sqrt3-3)=4\\sqrt3-6+6-3\\sqrt3=\\sqrt3$이다. 따라서 $ad+bc=2\\sqrt3-\\sqrt3=\\sqrt3$이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-05cb19e42484":{"길":"각의 크기를 따라가 닮은 삼각형과 같은 길이의 변을 찾고, 비례식에서 나온 이차방정식을 푼다","단계":[{"제목":"각의 크기 구하기","힌트":"꼭지각 $36^\\circ$인 이등변삼각형의 밑각과, 이등분선이 만드는 각은 각각 몇 도인가?","식":["$\\angle B=\\angle ACB=72^\\circ$","$\\angle ACD=\\angle DCB=36^\\circ$","$\\angle CDB=72^\\circ$"],"설명":"밑각은 $(180^\\circ-36^\\circ)\\div2=72^\\circ$이다. $\\overline{CD}$가 $\\angle C$의 이등분선이므로 $36^\\circ$씩 나뉘고, $\\angle CDB$는 $\\triangle ACD$의 외각이므로 $36^\\circ+36^\\circ=72^\\circ$이다.","확인":null,"스킬":"S10"},{"제목":"닮음과 같은 길이의 변 찾기","힌트":"$\\triangle ABC$와 닮은 삼각형은 무엇이며, 길이가 같은 변은 어느 것인가?","식":["$\\triangle ABC\\sim\\triangle CDB$","$\\overline{CD}=\\overline{CB}=8$","$\\overline{DB}=x-8$"],"설명":"$\\overline{AB}=x$라 한다. 두 삼각형은 두 각이 같아 AA 닮음이다. $\\angle CDB=\\angle CBD=72^\\circ$이므로 $\\overline{CD}=\\overline{CB}=8$이고, $\\angle A=\\angle ACD$이므로 $\\overline{AD}=\\overline{CD}=8$이어서 $\\overline{DB}=x-8$이다.","확인":null,"스킬":"S10","고비":true},{"제목":"비례식으로 이차방정식 풀기","힌트":"대응변의 비를 $\\overline{AB},\\ \\overline{CD},\\ \\overline{BC},\\ \\overline{DB}$로 세우면?","식":["$x:8=8:(x-8)$","$x^2-8x-64=0$","$x=4+4\\sqrt5$"],"설명":"대응변의 비 $\\overline{AB}:\\overline{CD}=\\overline{BC}:\\overline{DB}$에서 $x(x-8)=64$이다. 근의 공식으로 $x=4\\pm4\\sqrt5$이고 $x>0$이므로 $x=4+4\\sqrt5$이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-05e1ceee904a":{"길":"축에 대칭인 두 꼭짓점의 $x$좌표를 $a$로 나타내 둘레를 이차식으로 쓰고, 완전제곱 꼴로 최댓값을 찾는다","단계":[{"제목":"축의 방정식 찾기","힌트":"이차식을 $(x-p)^2+q$ 꼴로 바꾸면 축은 어디인가?","식":["$y=-2(x-4)^2+8$","$x=4$"],"설명":"그래프는 직선 $x=4$에 대하여 대칭이다.","확인":null,"스킬":"A6"},{"제목":"점 $D$를 $a$로 두고 두 변 나타내기","힌트":"$D$의 $x$좌표를 $a$로 놓으면 $A$의 $x$좌표와 두 변의 길이는 어떻게 되는가?","식":["$D(a,\\,-2a^2+16a-24)$","$A(8-a,\\,-2a^2+16a-24)$","$\\overline{AD}=2a-8,\\ \\ \\overline{CD}=-2a^2+16a-24$"],"설명":"$A$와 $D$는 축 $x=4$에 대하여 대칭이므로 $A$의 $x$좌표는 $8-a$이다. 가로 $\\overline{AD}=a-(8-a)=2a-8$이고, 세로 $\\overline{CD}$는 $D$의 $y$좌표이다.","확인":null,"스킬":"S4","고비":true},{"제목":"둘레를 식으로 쓰고 최댓값 구하기","힌트":"둘레를 $a$의 이차식으로 쓰고 완전제곱 꼴로 바꾸면?","식":["$l=2\\{(2a-8)+(-2a^2+16a-24)\\}=-4a^2+36a-64$","$=-4\\left(a-\\dfrac92\\right)^2+17$"],"설명":"둘레 $l$을 $a$의 이차식으로 쓰고 완전제곱 꼴로 고치면 $a=\\frac92$에서 최대이다. 이 값은 $4<a<6$ 안에 있으므로 최댓값은 17이다.","확인":"17","스킬":"A6"}],"fb":"fig/ns/"},"ns-118d97f1ef65":{"길":"직사각형의 세로 변을 $x$로 두고 가로 변을 $x$로 나타낸 뒤, 넓이의 이차식에서 최댓값을 찾는다","단계":[{"제목":"변을 $x$로 나타내기","힌트":"직사각형의 세로 변을 $x$로 두면 직각이등변삼각형 덕분에 가로 변은 어떻게 나타나는가?","식":["$\\overline{EF}=\\overline{BF}=x,\\ \\ \\overline{HG}=\\overline{GC}=x$","$\\overline{FG}=20-2x$"],"설명":"직사각형을 $EFGH$라 하고 $E$는 $\\overline{AB}$ 위, $F$와 $G$는 $\\overline{BC}$ 위, $H$는 $\\overline{AC}$ 위의 꼭짓점이라 하자. $\\angle B=\\angle C=45^\\circ$이므로 $\\overline{EF},\\ \\overline{HG}$는 $\\overline{BF},\\ \\overline{GC}$와 길이가 같고, 이를 $x$로 놓으면 $\\overline{FG}=20-2x$이다.","확인":null,"스킬":"S10","고비":true},{"제목":"넓이의 최댓값 구하기","힌트":"넓이를 $x$의 이차식으로 쓰고 완전제곱 꼴로 바꾸면 최대가 되는 $x$는?","식":["$x(20-2x)=-2(x-5)^2+50$","$x=5$"],"설명":"넓이를 완전제곱 꼴로 고치면 $x=5$일 때 최대이다.","확인":null,"스킬":"A6"},{"제목":"둘레 구하기","힌트":"$x=5$일 때 가로 변은 얼마이고 둘레는 얼마인가?","식":["$\\overline{FG}=20-10=10$","$2\\times(5+10)=30$"],"설명":"세로 5, 가로 10이므로 둘레는 30이다.","확인":"30","스킬":"A6"}],"fb":"fig/ns/"},"ns-1bfc2d402296":{"길":"직선 위의 점을 $a$로 나타내 직사각형의 넓이를 이차방정식으로 쓰고, $a\\le b$ 조건으로 근을 고른다","단계":[{"제목":"점 $P$의 좌표와 넓이식","힌트":"$P$가 직선 위에 있으므로 $b$를 $a$로 나타내면? 직사각형 $OQPR$의 가로, 세로는?","식":["$P(a,\\,-a+6)$","$a(-a+6)=6$"],"설명":"$P$의 좌표는 $(a,\\ -a+6)$이고 $OQPR$은 가로 $a$, 세로 $-a+6$인 직사각형이다.","확인":null,"스킬":"G10","고비":true},{"제목":"이차방정식 풀기","힌트":"넓이식을 정리해 근의 공식으로 풀면?","식":["$a^2-6a+6=0$","$a=3\\pm\\sqrt3$"],"설명":"근의 공식으로 $a=3\\pm\\sqrt3$이다.","확인":null,"스킬":"G10"},{"제목":"조건으로 근 고르기","힌트":"$a\\le b$를 $a$에 대한 부등식으로 쓰면?","식":["$a\\le -a+6\\ \\Rightarrow\\ a\\le3$","$a=3-\\sqrt3,\\ \\ b=3+\\sqrt3$"],"설명":"$a\\le b$이므로 $a\\le3$이고 $a=3-\\sqrt3$이다. 그때 $b=-a+6=3+\\sqrt3$이다.","확인":null,"스킬":"G10"}],"fb":"fig/ns/"},"ns-1e58d22870e9":{"길":"$P$의 $x$좌표를 $p$로 두고 $y$좌표의 차로 $\\overline{PQ}$를 쓴 뒤 완전제곱 꼴로 최솟값을 구한다","단계":[{"제목":"$\\overline{PQ}$를 $p$로 나타내기","힌트":"$P,\\ Q$의 $x$좌표가 같으므로 $\\overline{PQ}$는 두 $y$좌표의 차이다. 어느 쪽이 위인가?","식":["$P(p,\\,-(p-1)^2-2),\\ \\ Q\\left(p,\\,\\dfrac12p-1\\right)$","$\\overline{PQ}=\\left(\\dfrac12p-1\\right)-\\{-(p-1)^2-2\\}$"],"설명":"그림에서 직선이 위, 포물선이 아래에 있으므로 (직선의 $y$좌표)−(포물선의 $y$좌표)가 $\\overline{PQ}$의 길이이다.","확인":null,"스킬":"A6","고비":true},{"제목":"식을 정리해 완전제곱 꼴로","힌트":"전개해 정리한 뒤 완전제곱 꼴로 바꾸면?","식":["$\\overline{PQ}=p^2-\\dfrac32p+2$","$=\\left(p-\\dfrac34\\right)^2+\\dfrac{23}{16}$"],"설명":"$p^2-\\frac32p$에 $\\left(\\frac34\\right)^2$을 더하고 빼서 완전제곱 꼴로 고친다.","확인":null,"스킬":"A6"},{"제목":"최솟값 구하기","힌트":"완전제곱 꼴에서 $\\overline{PQ}$가 가장 작을 때의 값은?","식":["$p=\\dfrac34\\ \\text{일 때}\\ \\overline{PQ}=\\dfrac{23}{16}$"],"설명":"제곱식이 0이 되는 $p=\\frac34$에서 최소이다.","확인":"23/16","스킬":"A6"}],"fb":"fig/ns/"},"ns-229fe22fb5bc":{"길":"합동인 직각삼각형 네 개와 작은 정사각형의 넓이를 큰 정사각형의 넓이와 같다고 놓아 이차방정식을 푼다","단계":[{"제목":"합동 삼각형과 변의 길이","힌트":"네 모서리의 직각삼각형은 서로 합동인가? $\\overline{AH}=x$로 두면 $\\overline{AE}$는?","식":["$\\overline{AH}=x,\\ \\ \\overline{AE}=7-x$"],"설명":"$\\triangle AEH\\equiv\\triangle BFE\\equiv\\triangle CGF\\equiv\\triangle DHG$(RHA 합동)이므로 $\\overline{AH}=\\overline{BE}=\\overline{CF}=\\overline{DG}=x$로 놓으면 $\\overline{AE}=\\overline{BF}=\\overline{CG}=\\overline{DH}=7-x$이다.","확인":null,"스킬":"S8"},{"제목":"넓이 식 세우기","힌트":"$\\square ABCD$의 넓이를 직각삼각형 네 개와 $\\square EFGH$로 나누면?","식":["$49=4\\times\\dfrac12x(7-x)+25$","$x^2-7x+12=0$"],"설명":"큰 정사각형의 넓이 49는 직각삼각형 네 개와 한 변이 5인 정사각형의 넓이의 합이다.","확인":null,"스킬":"S8","고비":true},{"제목":"조건으로 $x$ 고르기","힌트":"이차방정식을 풀고 $\\overline{AE}>\\overline{AH}$를 적용하면?","식":["$(x-3)(x-4)=0$","$x=3\\ \\text{또는}\\ x=4$","$x=3$"],"설명":"$\\overline{AE}>\\overline{AH}$이므로 $7-x>x$이고 $x=3$이다. 따라서 $\\overline{AH}=3$이다.","확인":"3","스킬":"S8"}],"fb":"fig/ns/"},"ns-23a47617a134":{"길":"대칭으로 $\\triangle AQR$를 $\\overline{AP}$에 대한 식으로 바꾸고, $\\overline{AP}$가 높이일 때 최소임을 이용한다","단계":[{"제목":"$\\overline{AQ}=\\overline{AP}=\\overline{AR}$와 $\\angle QAR$","힌트":"$\\triangle AQM$과 $\\triangle APM$은 어떤 관계인가?","식":["$\\overline{AQ}=\\overline{AP}=\\overline{AR}$","$\\angle QAR=2\\times60^\\circ=120^\\circ$"],"설명":"$\\triangle AQM\\equiv\\triangle APM$(RHS 합동)이므로 $\\overline{AQ}=\\overline{AP}$, $\\angle QAM=\\angle PAM$이다. 마찬가지로 $\\overline{AR}=\\overline{AP}$, $\\angle RAN=\\angle PAN$이다. $\\angle PAM+\\angle PAN=60^\\circ$이므로 $\\angle QAR=120^\\circ$이다.","확인":null,"스킬":"S14"},{"제목":"$\\overline{AP}$가 최소일 때 찾기","힌트":"$\\angle QAR$가 일정할 때 $\\triangle AQR$의 넓이는 $\\overline{AP}$와 어떤 관계인가?","식":["$\\triangle AQR=\\dfrac12\\overline{AP}^2\\sin60^\\circ$"],"설명":"넓이는 $\\frac12\\times\\overline{AP}\\times\\overline{AP}\\times\\sin(180^\\circ-120^\\circ)$이므로 $\\overline{AP}$가 짧을수록 작다. $\\overline{AP}$는 $A$에서 $\\overline{BC}$에 내린 수선일 때 가장 짧다.","확인":null,"스킬":"S14","고비":true},{"제목":"$\\overline{BC}$ 구하기","힌트":"$B$에서 $\\overline{AC}$에 내린 수선의 발을 $H$라 하면 $\\overline{AH}$, $\\overline{BH}$는 얼마인가?","식":["$\\overline{AH}=4\\cos60^\\circ=2,\\ \\ \\overline{BH}=4\\sin60^\\circ=2\\sqrt3$","$\\overline{BC}=\\sqrt{(2\\sqrt3)^2+3^2}=\\sqrt{21}$"],"설명":"$\\overline{CH}=5-2=3$이므로 직각삼각형 $BCH$에서 $\\overline{BC}=\\sqrt{21}$이다.","확인":null,"스킬":"S6"},{"제목":"$\\overline{AP}$의 최솟값 구하기","힌트":"$\\triangle ABC$의 넓이를 두 가지로 쓰면?","식":["$\\dfrac12\\times4\\times5\\times\\sin60^\\circ=\\dfrac12\\times\\sqrt{21}\\times\\overline{AP}$","$\\overline{AP}=\\dfrac{10\\sqrt7}{7}$"],"설명":"왼쪽은 두 변과 끼인각으로, 오른쪽은 밑변 $\\overline{BC}$와 높이 $\\overline{AP}$로 쓴 같은 넓이이다.","확인":null,"스킬":"S8"},{"제목":"넓이의 최솟값","힌트":"구한 $\\overline{AP}$를 넓이 식에 넣으면?","식":["$\\dfrac12\\times\\left(\\dfrac{10\\sqrt7}{7}\\right)^2\\times\\sin60^\\circ=\\dfrac{25\\sqrt3}{7}$"],"설명":"$\\left(\\frac{10\\sqrt7}{7}\\right)^2=\\frac{700}{49}$이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-23b192dceb96":{"길":"가려진 두 도수를 문자로 두고 인원과 평균 조건으로 연립해 구한 뒤, 편차의 제곱의 평균으로 분산을 구한다","단계":[{"제목":"가려진 도수를 두고 인원 식 세우기","힌트":"30 이상 40 미만의 도수를 $x$, 40 이상 50 미만의 도수를 $y$라 하면 전체 인원 조건은?","식":["$8+12+x+y+4+2=50$","$x+y=24$"],"설명":"히스토그램에서 보이는 도수는 8, 12, 4, 2이고 전체는 50명이다.","확인":null,"스킬":"A10"},{"제목":"평균으로 두 번째 식 세우기","힌트":"계급값을 이용해 평균을 $x,\\ y$로 나타내면?","식":["$\\dfrac{15\\times8+25\\times12+35x+45y+55\\times4+65\\times2}{50}=35$","$7x+9y=196$"],"설명":"각 계급의 계급값은 15, 25, 35, 45, 55, 65이고 평균은 (계급값×도수)의 합을 50으로 나눈 값이다.","확인":null,"스킬":"A10","고비":true},{"제목":"연립해 $x,\\ y$ 구하기","힌트":"두 식을 연립하면 $x,\\ y$는 얼마인가?","식":["$x=10,\\ \\ y=14$"],"설명":"$x+y=24$와 $7x+9y=196$을 연립해 푼다.","확인":null,"스킬":"A10"},{"제목":"분산 구하기","힌트":"편차의 제곱에 도수를 곱해 더한 뒤 50으로 나누면?","식":["$\\dfrac{(-20)^2\\times8+(-10)^2\\times12+0^2\\times10+10^2\\times14+20^2\\times4+30^2\\times2}{50}=184$"],"설명":"각 계급값의 편차는 −20, −10, 0, 10, 20, 30이고 (편차)²의 평균이 분산이다.","확인":"184","스킬":"C7"}],"fb":"fig/ns/"},"ns-26ba14ece1a8":{"길":"점 $B$의 $x$좌표를 $a$로 두고 $D$의 좌표를 나타낸 뒤, $\\overline{AB}=2\\overline{BC}$로 $a$를 구한다","단계":[{"제목":"점 $B,\\ D$의 좌표 나타내기","힌트":"$B$의 $x$좌표를 $a$로 두면 $\\overline{EB}$, $\\overline{BC}$와 $D$의 $x$좌표는 어떻게 되는가?","식":["$B(a,\\,a^2)$","$\\overline{EB}=a,\\ \\ \\overline{BC}=2a$","$D(3a,\\,9a^2)$"],"설명":"$E$는 $y$축 위의 점이므로 $\\overline{EB}$는 $B$의 $x$좌표 $a$와 같고, $2\\overline{EB}=\\overline{BC}$에서 $\\overline{BC}=2a$이다. $D$의 $x$좌표는 $a+2a=3a$이고 $D$는 $y=x^2$ 위에 있으므로 $y$좌표는 $9a^2$이다.","확인":null,"스킬":"S4","고비":true},{"제목":"$\\overline{AB}=2\\overline{BC}$로 $a$ 구하기","힌트":"$\\overline{AB}$는 $B$와 $D$의 $y$좌표의 차이다. $\\overline{AB}=2\\overline{BC}$를 식으로 쓰면?","식":["$\\overline{AB}=9a^2-a^2=8a^2$","$8a^2=2\\times2a$","$a=\\dfrac12$"],"설명":"$\\overline{AB}$는 세로 변이므로 $D$와 $B$의 $y$좌표의 차이다. $8a^2=4a$에서 $a>0$이므로 $a=\\frac12$이다.","확인":null,"스킬":"S4"},{"제목":"넓이 구하기","힌트":"가로와 세로를 구해 곱하면?","식":["$\\overline{AB}=8\\times\\dfrac14=2,\\ \\ \\overline{BC}=2\\times\\dfrac12=1$","$\\square ABCD=2\\times1=2$"],"설명":"$a=\\frac12$을 대입해 두 변의 길이를 구한다.","확인":"2","스킬":"S4"}],"fb":"fig/ns/"},"ns-2d1f99c81dac":{"길":"한 점을 대입해 식을 정하고, y 축 대칭을 이용해 네 점의 좌표를 구한 뒤 사다리꼴 넓이를 계산한다","단계":[{"제목":"a 의 값","힌트":"그래프가 지나는 점의 좌표를 식에 넣으면?","식":["$-2=a\\times(-3)^2$","$a=-\\frac{2}{9}$"],"설명":"점 $A(-3,\\,-2)$ 가 $y=ax^2$ 위의 점이므로 대입한다.","확인":"-2/9","스킬":"G10","고비":false},{"제목":"D 와 두 밑변","힌트":"$y=ax^2$ 의 그래프는 어느 직선에 대칭인가?","식":["$D(3,\\,-2)$","$\\overline{AD}=6,\\ \\overline{BC}=12$"],"설명":"$A$ 와 $D$ 는 $y$ 좌표가 같고 포물선이 $y$ 축에 대칭이므로 $D$ 는 $A$ 와 $y$ 축 대칭인 점이다. $\\overline{BC}=2\\overline{AD}$ 이다.","확인":null,"스킬":"G11","고비":true},{"제목":"B, C 의 좌표","힌트":"$BC$ 도 $y$ 축에 대칭이면 $B$, $C$ 의 $x$ 좌표는?","식":["$x=\\pm6$","$y=-\\frac{2}{9}\\times36=-8$","$B(-6,\\,-8),\\ C(6,\\,-8)$"],"설명":"$B$, $C$ 의 $y$ 좌표가 같으므로 두 점은 $y$ 축에 대칭이고, $BC=12$ 이므로 $x$ 좌표는 $\\pm6$ 이다.","확인":null,"스킬":"G11","고비":false},{"제목":"사다리꼴의 넓이","힌트":"$AD$ 와 $BC$ 가 평행한 사각형의 넓이는 어떻게 구하는가?","식":["$\\square ABCD=\\frac{1}{2}\\times(6+12)\\times6=54$"],"설명":"$AD$, $BC$ 가 모두 $x$ 축에 평행하므로 사다리꼴이고, 높이는 두 직선 $y=-2$, $y=-8$ 사이의 거리 $6$ 이다.","확인":"54","스킬":"G10","고비":false}],"fb":"fig/ns/"},"ns-31b868665b94":{"길":"교점 A 와 C 를 구하고, P 의 x 좌표를 문자로 두어 D 의 좌표를 구한 뒤 두 삼각형의 넓이를 식으로 맞춘다","단계":[{"제목":"A 와 C 의 좌표","힌트":"직선과 포물선의 식을 연립하면?","식":["$x^2=-x+2$","$A(-2,\\,4),\\ C(0,\\,2)$"],"설명":"$x^2+x-2=0$ 을 풀면 교점의 $x$ 좌표가 나온다. 그림에서 $A$ 는 $y$ 축 왼쪽의 교점이고, $C$ 는 직선의 $y$ 절편이다.","확인":null,"스킬":"G1","고비":false},{"제목":"P 를 문자로 두고 D 구하기","힌트":"$P$ 의 $x$ 좌표를 $k$ 라 하면 직선 $AP$ 의 식은?","식":["$P(k,\\,k^2)\\ (k>0)$","$y=(k-2)x+2k$","$D(0,\\,2k)$"],"설명":"그림에서 $P$ 는 $y$ 축 오른쪽에 있으므로 $k>0$ 이다. 두 점 $A$, $P$ 를 지나는 직선의 기울기는 $\\frac{k^2-4}{k+2}=k-2$ 이고, $x=0$ 일 때의 $y$ 값이 $D$ 의 $y$ 좌표이다.","확인":null,"스킬":"G10","고비":true},{"제목":"두 삼각형의 넓이","힌트":"$y$ 축 위의 선분을 밑변으로 보면 높이는 각각 얼마인가?","식":["$\\triangle ACD=\\frac{1}{2}\\times(2-2k)\\times2=2-2k$","$\\triangle DPO=\\frac{1}{2}\\times2k\\times k=k^2$"],"설명":"$CD$ 와 $OD$ 가 $y$ 축 위에 있으므로 이를 밑변으로 하면 높이는 $A$ 의 $x$ 좌표의 절댓값 $2$, $P$ 의 $x$ 좌표 $k$ 이다.","확인":null,"스킬":"G10","고비":false},{"제목":"k 의 값","힌트":"두 넓이가 같다는 조건으로 세운 이차방정식의 해는?","식":["$2-2k=k^2$","$k^2+2k-2=0$","$k=-1+\\sqrt{3}$"],"설명":"근의 공식으로 풀고 $k>0$ 인 값을 택한다. $P$ 의 $x$ 좌표가 곧 $k$ 이다.","확인":null,"스킬":"G10","고비":false}],"fb":"fig/ns/"},"ns-33cc155c899a":{"길":"두 그래프의 공통 축을 찾아 꼭짓점들을 축으로부터의 거리 k 로 나타내고, 둘레를 완전제곱 꼴로 바꿔 최댓값을 a 에 대한 식으로 얻는다","단계":[{"제목":"축의 방정식","힌트":"두 이차함수를 완전제곱 꼴로 바꾸면 축은?","식":["$y=\\left(x-\\frac{a}{2}\\right)^2-\\frac{a^2}{4}-3$","$y=-\\left(x-\\frac{a}{2}\\right)^2+\\frac{a^2}{4}+3$"],"설명":"두 그래프는 $x$ 축에 대칭이고 축이 모두 $x=\\frac{a}{2}$ 이다.","확인":null,"스킬":"A6","고비":false},{"제목":"네 점을 k 로 두기","힌트":"축에서 오른쪽으로 $k$ 만큼 떨어진 곳에 $D$ 를 잡으면 $A$ 의 $x$ 좌표는?","식":["$D\\left(\\frac{a}{2}+k,\\,-k^2+\\frac{a^2}{4}+3\\right)$","$A\\left(\\frac{a}{2}-k,\\,-k^2+\\frac{a^2}{4}+3\\right)$","$C\\left(\\frac{a}{2}+k,\\,k^2-\\frac{a^2}{4}-3\\right)$"],"설명":"$AD$ 는 $x$ 축에 평행하므로 $A$, $D$ 는 축에 대칭이고 $y$ 좌표가 같다. $D$ 는 위쪽 그래프 위의 점이다. $C$ 는 $D$ 와 $x$ 좌표가 같고 아래쪽 그래프 위의 점이다.","확인":null,"스킬":"G11","고비":true},{"제목":"가로와 세로","힌트":"$AD$ 와 $DC$ 의 길이는 각각 어떻게 되는가?","식":["$\\overline{AD}=2k$","$\\overline{DC}=-2k^2+\\frac{a^2}{2}+6$"],"설명":"$AD$ 는 두 점의 $x$ 좌표의 차이이고, $DC$ 는 $D$ 와 $C$ 의 $y$ 좌표의 차이이다.","확인":null,"스킬":"S4","고비":false},{"제목":"둘레의 최댓값","힌트":"둘레를 $k$ 에 대한 이차식으로 쓰고 완전제곱 꼴로 바꾸면?","식":["$l=2\\left(2k-2k^2+\\frac{a^2}{2}+6\\right)=-4\\left(k-\\frac{1}{2}\\right)^2+a^2+13$"],"설명":"$k=\\frac{1}{2}$ 일 때 둘레가 최대이고, 최댓값은 $a^2+13$ 이다.","확인":null,"스킬":"A6","고비":false},{"제목":"a 의 값","힌트":"최댓값이 $49$ 라는 조건으로 $a$ 를 구하면?","식":["$a^2+13=49$","$a^2=36$","$a=6$"],"설명":"$a$ 가 양수이므로 $a=6$ 이다.","확인":"6","스킬":"A6","고비":false}],"fb":"fig/ns/"},"ns-3570d873e91c":{"길":"EC 를 문자로 두고 탄젠트 값으로 AC 를 나타낸 뒤, 직각이등변삼각형 조건으로 길이를 정하고 CD 를 빼서 AD 를 구한다","단계":[{"제목":"AC 를 a 로 나타내기","힌트":"직각삼각형 $ACE$ 에서 $\\tan75^\\circ$ 는 어느 두 변의 비인가?","식":["$\\overline{EC}=a$","$\\overline{AC}=(2+\\sqrt{3})\\,a$"],"설명":"삼각형 $ACE$ 는 $C$ 에서 직각이고 $\\tan75^\\circ=\\frac{\\overline{AC}}{\\overline{EC}}=2+\\sqrt{3}$ 이다.","확인":null,"스킬":"S6","고비":false},{"제목":"BC 와 AC 가 같음","힌트":"$\\angle B=45^\\circ$ 인 직각삼각형 $ABC$ 에서 $AC$ 와 $BC$ 의 관계는?","식":["$2+a=(2+\\sqrt{3})\\,a$","$a=\\frac{2}{\\sqrt{3}+1}=\\sqrt{3}-1$"],"설명":"$\\angle B=45^\\circ$, $\\angle C=90^\\circ$ 이므로 $\\overline{BC}=\\overline{AC}$ 이다. $\\overline{BC}=\\overline{BE}+\\overline{EC}=2+a$ 이다. 분모를 유리화해서 $a$ 를 구한다.","확인":null,"스킬":"S6","고비":true},{"제목":"CD 의 길이","힌트":"삼각형 $BCD$ 에서 $\\angle DBC=30^\\circ$ 이면 $BC$ 와 $CD$ 의 비는?","식":["$\\overline{BC}=\\overline{AC}=1+\\sqrt{3}$","$(1+\\sqrt{3}):\\overline{CD}=\\sqrt{3}:1$","$\\overline{CD}=\\frac{3+\\sqrt{3}}{3}$"],"설명":"삼각형 $BCD$ 는 $C$ 에서 직각이고 한 각이 $30^\\circ$ 이므로 $\\overline{BC}:\\overline{CD}=\\sqrt{3}:1$ 이다.","확인":null,"스킬":"S6","고비":false},{"제목":"AD 의 길이","힌트":"$AD$ 는 $AC$ 에서 어느 선분을 빼면 되는가?","식":["$\\overline{AD}=\\overline{AC}-\\overline{CD}=(1+\\sqrt{3})-\\frac{3+\\sqrt{3}}{3}=\\frac{2\\sqrt{3}}{3}$"],"설명":"$D$ 는 $AC$ 위에 있고 $CD$ 가 $AC$ 보다 짧으므로 $AD=AC-CD$ 이다.","확인":null,"스킬":"S6","고비":false}],"fb":"fig/ns/"},"ns-37f4e5ef93c1":{"길":"축의 방정식으로 식을 확정하고, 축에서의 거리를 문자로 둬 둘레를 이차식으로 만든 뒤 완전제곱으로 최댓값을 찾는다","단계":[{"제목":"b 의 값","힌트":"이차함수를 완전제곱 꼴로 바꾸면 축은 $b$ 와 어떤 관계인가?","식":["$y=-\\left(x-\\frac{b}{2}\\right)^2+\\frac{b^2}{4}$","$\\frac{b}{2}=2$","$y=-x^2+4x$"],"설명":"축이 $x=2$ 이므로 $b=4$ 이다.","확인":"4","스킬":"A6","고비":false},{"제목":"점을 k 로 두기","힌트":"축에서 $k$ 만큼 떨어진 점으로 두면 $A$, $D$ 의 $x$ 좌표는?","식":["$D(2+k,\\,-k^2+4)$","$A(2-k,\\,-k^2+4)$","$C(2+k,\\,0)$"],"설명":"$y=-(x-2)^2+4$ 이므로 $x=2+k$ 일 때 $y=-k^2+4$ 이다. $A$ 와 $D$ 는 축에 대칭이고 $C$ 는 $D$ 의 바로 아래 $x$ 축 위의 점이다.","확인":null,"스킬":"G11","고비":true},{"제목":"둘레의 최댓값","힌트":"가로와 세로를 $k$ 로 나타낸 뒤 둘레를 완전제곱 꼴로 바꾸면?","식":["$2(2k-k^2+4)=-2k^2+4k+8=-2(k-1)^2+10$"],"설명":"가로는 $2k$, 세로는 $-k^2+4$ 이다. $k=1$ 일 때 둘레가 최대이다.","확인":"10","스킬":"A6","고비":false}],"fb":"fig/ns/"},"ns-39c62b008543":{"길":"A 의 x 좌표를 문자로 두고 대칭과 같은 x 좌표를 이용해 B, D 를 나타낸 뒤 두 변의 길이가 같다는 식을 세운다","단계":[{"제목":"꼭짓점의 좌표","힌트":"$A$ 의 $x$ 좌표를 $a$ 라 하면 $B$, $D$ 의 좌표는?","식":["$A(a,\\,2a^2)$","$B(-a,\\,2a^2)$","$D\\left(a,\\,-\\frac{1}{2}a^2\\right)$"],"설명":"$AB$ 가 $x$ 축에 평행하고 그래프가 $y$ 축에 대칭이므로 $B$ 의 $x$ 좌표는 $-a$ 이다. $AD$ 는 $y$ 축에 평행하므로 $D$ 는 $A$ 와 $x$ 좌표가 같고 아래쪽 그래프 위의 점이다.","확인":null,"스킬":"G11","고비":true},{"제목":"두 변의 길이를 같게","힌트":"정사각형에서 $AB$ 와 $AD$ 의 길이는 어떤 관계인가?","식":["$\\overline{AB}=2a$","$\\overline{AD}=2a^2+\\frac{1}{2}a^2=\\frac{5}{2}a^2$","$2a=\\frac{5}{2}a^2$"],"설명":"$AB$ 는 두 점의 $x$ 좌표의 차이이고 $AD$ 는 $y$ 좌표의 차이이다. 정사각형이므로 두 길이가 같다.","확인":null,"스킬":"S4","고비":false},{"제목":"a 의 값","힌트":"식을 정리해 인수분해하면?","식":["$\\frac{5}{2}a\\left(a-\\frac{4}{5}\\right)=0$","$a=\\frac{4}{5}$"],"설명":"$A$ 가 제1사분면의 점이므로 $a>0$ 이다.","확인":"4/5","스킬":"S4","고비":false}],"fb":"fig/ns/"},"ns-3b99b9aa1e48":{"길":"그래프의 두 점으로 판매량의 식을 세우고, 가격과 판매량의 곱으로 수입의 식을 만들어 완전제곱 꼴로 최댓값을 구한다","단계":[{"제목":"판매량의 식","힌트":"그래프가 지나는 두 점으로 일차함수의 식을 구하면?","식":["$5000a+b=160,\\ 5600a+b=100$","$k=-\\frac{1}{10}x+660$"],"설명":"하루 판매량을 $k$ 개라 하고 $k=ax+b$ 로 둔다. 그래프에서 읽은 두 점 $(5000,\\,160)$, $(5600,\\,100)$ 을 대입해 연립한다.","확인":null,"스킬":"C7","고비":false},{"제목":"판매 수입의 식","힌트":"수입은 가격과 판매량으로 어떻게 나타내는가?","식":["$y=x\\left(-\\frac{1}{10}x+660\\right)$","$y=-\\frac{1}{10}x^2+660x$"],"설명":"하루 판매 수입은 가격 $x$ 에 판매량 $k$ 를 곱한 값이다.","확인":null,"스킬":"C7","고비":true},{"제목":"수입의 최댓값","힌트":"이차식을 완전제곱 꼴로 바꾸면 최댓값은?","식":["$y=-\\frac{1}{10}(x-3300)^2+1089000$"],"설명":"$x=3300$ 일 때 $y$ 가 최대이다.","확인":"1089000","스킬":"A6","고비":false}],"fb":"fig/ns/"},"ns-3bc563ffcd48":{"길":"포물선의 축을 구해 직사각형의 꼭짓점을 한 문자로 나타내고, 둘레를 완전제곱 꼴로 바꿔 최댓값을 찾는다","단계":[{"제목":"축과 꼭짓점의 좌표","힌트":"포물선과 $x$ 축이 만드는 대칭축은 어디인가?","식":["$y=-2(x-2)^2+8$","$B(k,\\,0),\\ A(k,\\,-2k^2+8k),\\ C(4-k,\\,0)$"],"설명":"축은 $x=2$ 이다. 직사각형의 $B$, $C$ 는 축에 대칭이므로 $B$ 의 $x$ 좌표를 $k$ 라 하면 $C$ 의 $x$ 좌표는 $4-k$ 이다. $A$ 는 $B$ 의 바로 위 포물선 위의 점이다.","확인":null,"스킬":"G11","고비":true},{"제목":"가로와 세로","힌트":"$BC$ 와 $AB$ 의 길이는?","식":["$\\overline{BC}=4-2k$","$\\overline{AB}=-2k^2+8k$"],"설명":"$BC$ 는 두 점의 $x$ 좌표의 차이이고, $AB$ 는 $A$ 의 $y$ 좌표이다.","확인":null,"스킬":"S4","고비":false},{"제목":"둘레의 최댓값","힌트":"둘레를 $k$ 에 대한 이차식으로 쓰고 완전제곱 꼴로 바꾸면?","식":["$l=2(4-2k-2k^2+8k)=-4k^2+12k+8$","$=-4\\left(k-\\frac{3}{2}\\right)^2+17$"],"설명":"$k=\\frac{3}{2}$ 일 때 둘레가 최대이다.","확인":"17","스킬":"A6","고비":false}],"fb":"fig/ns/"},"ns-421bfdbe4d15":{"길":"세로를 문자로 두고 밑각이 45° 임을 이용해 가로를 나타낸 뒤, 넓이를 완전제곱 꼴로 바꿔 최댓값을 구한다","단계":[{"제목":"가로의 길이","힌트":"밑각이 $45^\\circ$ 이면 직사각형 양쪽에서 밑변이 얼마씩 남는가?","식":["$16-x-x=16-2x$"],"설명":"직사각형의 세로를 $x$ 라 하자. 밑각이 $45^\\circ$ 이므로 직사각형 양쪽의 밑변 위에 각각 $x$ 씩 남는다. 따라서 가로는 $16-2x$ 이다.","확인":null,"스킬":"C7","고비":true},{"제목":"넓이의 식","힌트":"넓이를 $x$ 에 대한 식으로 쓰면?","식":["$y=x(16-2x)=-2x^2+16x$"],"설명":"직사각형의 넓이 $y$ 는 가로 곱하기 세로이다.","확인":null,"스킬":"C7","고비":false},{"제목":"넓이의 최댓값","힌트":"완전제곱 꼴로 바꾸면 최댓값은?","식":["$y=-2(x-4)^2+32$"],"설명":"$x=4$ 일 때 넓이가 최대이다.","확인":"32","스킬":"A6","고비":false}],"fb":"fig/ns/"},"ns-5170a696055b":{"길":"그림에서 꼭짓점의 좌표를 읽고, a 가 커질 때 그래프가 사각형과 만나는 모양이 달라지는 경계를 꼭짓점을 지날 때로 잡는다","단계":[{"제목":"꼭짓점의 좌표","힌트":"그림에서 직사각형의 꼭짓점 좌표를 읽으면?","식":["$A(1,\\,4),\\ B(1,\\,2),\\ C(4,\\,2),\\ D(4,\\,4)$"],"설명":"그림의 눈금에서 각 점의 좌표를 읽는다.","확인":null,"스킬":"G1","고비":false},{"제목":"경계가 되는 꼭짓점","힌트":"$a$ 가 커질수록 $y=2ax^2$ 의 그래프는 어떻게 움직이는가? 처음 닿는 꼭짓점과 마지막에 닿는 꼭짓점은?","식":[],"설명":"$x>0$ 에서 $a$ 가 클수록 그래프는 위로 올라간다. $a$ 가 아주 작으면 그래프가 사각형 아래에 있다가, 오른쪽 아래 꼭짓점 $C$ 를 지나면서 사각형과 만나기 시작한다. $a$ 가 더 커져 왼쪽 위 꼭짓점 $A$ 를 지나면 사각형 위로 벗어난다.","확인":null,"스킬":"G7","고비":true},{"제목":"꼭짓점을 지날 때의 a","힌트":"그래프가 $C$ 를 지날 때와 $A$ 를 지날 때 각각 $a$ 는?","식":["$C(4,\\,2):\\ 2=2a\\times4^2,\\ a=\\frac{1}{16}$","$A(1,\\,4):\\ 4=2a\\times1^2,\\ a=2$"],"설명":"각 꼭짓점의 좌표를 $y=2ax^2$ 에 대입한다.","확인":null,"스킬":"G1","고비":false},{"제목":"a 의 범위","힌트":"그래프가 둘레 위의 서로 다른 두 점을 지나는 $a$ 의 범위는?","식":["$\\frac{1}{16}<a<2$"],"설명":"$a=\\frac{1}{16}$ 이거나 $a=2$ 일 때는 꼭짓점 한 점에서만 만나므로 등호는 들어가지 않는다.","확인":null,"스킬":"G7","고비":false}],"fb":"fig/ns/"},"ns-536a18144b58":{"길":"세 변의 길이를 구하고, D 에서 AC 에 내린 수선이 두 직각삼각형의 공통 변임을 이용해 길이를 구한 뒤 사인을 정의대로 구한다","단계":[{"제목":"AB, BD, AC","힌트":"삼각형 $ABD$ 는 어떤 삼각형인가?","식":["$\\overline{AB}=\\overline{BD}=\\sqrt{5}$","$\\overline{AC}=\\sqrt{(\\sqrt{5})^2+(2\\sqrt{5})^2}=5$"],"설명":"$\\overline{AB}=\\overline{BD}$ 이고 $\\angle B=90^\\circ$ 이므로 삼각형 $ABD$ 는 직각이등변삼각형이다. 빗변 $\\overline{AD}=\\sqrt{10}$ 이므로 $\\overline{AB}=\\overline{BD}=\\sqrt{5}$ 이고, $\\overline{BC}=\\overline{BD}+\\overline{DC}=2\\sqrt{5}$ 이다.","확인":"5","스킬":"S3","고비":false},{"제목":"수선 긋기","힌트":"$D$ 에서 $AC$ 에 수선을 내리면 $DH$ 는 어느 두 직각삼각형에 함께 들어가는가?","식":["$\\overline{CH}=x,\\ \\overline{AH}=5-x$"],"설명":"$D$ 에서 $AC$ 에 내린 수선의 발을 $H$ 라 하자. $DH$ 는 직각삼각형 $DHC$ 와 $DHA$ 에 공통으로 들어 있다.","확인":null,"스킬":"S2","고비":true},{"제목":"CH 의 길이","힌트":"$DH^2$ 을 두 직각삼각형에서 각각 나타내 같다고 놓으면?","식":["$\\overline{DH}^2=(\\sqrt{5})^2-x^2=(\\sqrt{10})^2-(5-x)^2$","$10x=20,\\ x=2$"],"설명":"$\\overline{DC}=\\sqrt{5}$, $\\overline{AD}=\\sqrt{10}$ 에 각각 피타고라스 정리를 쓴다.","확인":"2","스킬":"S3","고비":false},{"제목":"sin x 의 값","힌트":"$\\angle CAD$ 는 어느 직각삼각형의 예각인가?","식":["$\\overline{AH}=3,\\ \\overline{DH}=\\sqrt{(\\sqrt{10})^2-3^2}=1$","$\\sin x=\\frac{1}{\\sqrt{10}}=\\frac{\\sqrt{10}}{10}$"],"설명":"직각삼각형 $ADH$ 에서 $\\sin x=\\frac{\\overline{DH}}{\\overline{AD}}$ 이다.","확인":null,"스킬":"S6","고비":false}],"fb":"fig/ns/"},"ns-5386405d69d8":{"길":"한 점을 대입해 식을 정하고, 대칭을 이용해 C 의 좌표를 구한 뒤 사다리꼴의 넓이를 계산한다","단계":[{"제목":"a 의 값","힌트":"그래프가 지나는 점의 좌표를 식에 넣으면?","식":["$1=a\\times2^2$","$a=\\frac{1}{4}$"],"설명":"점 $B(2,\\,1)$ 이 $y=ax^2$ 위의 점이므로 대입한다.","확인":"1/4","스킬":"G10","고비":false},{"제목":"C 의 좌표","힌트":"$CD$ 가 $x$ 축에 평행하고 그래프가 $y$ 축에 대칭이면 $C$ 의 $x$ 좌표는 $CD$ 의 몇 분의 몇인가?","식":["$2p=12,\\ p=6$","$q=\\frac{1}{4}\\times6^2=9$"],"설명":"$C$ 의 좌표를 $(p,\\,q)$ 라 하자. $C$, $D$ 는 $y$ 축에 대칭이므로 $\\overline{CD}=2p$ 이다. $y$ 좌표는 $y=\\frac{1}{4}x^2$ 에 $x=6$ 을 넣어 구한다.","확인":null,"스킬":"G11","고비":true},{"제목":"사다리꼴의 넓이","힌트":"$AB$ 와 $CD$ 가 평행한 사각형의 높이는?","식":["$\\square ABCD=\\frac{1}{2}\\times(4+12)\\times(9-1)=64$"],"설명":"$AB$, $CD$ 가 모두 $x$ 축에 평행하므로 사다리꼴이고, 높이는 두 선분의 $y$ 좌표의 차이 $9-1$ 이다.","확인":"64","스킬":"G10","고비":false}],"fb":"fig/ns/"},"ns-55b092103f60":{"길":"잘못 기록된 값과 실제 값의 합이 같아 평균이 같음을 확인하고, 분산에서 편차의 제곱의 합을 구해 두 값만 바꿔 계산한다","단계":[{"제목":"평균이 그대로임","힌트":"잘못 기록된 두 값의 합과 실제 두 값의 합을 비교하면?","식":["$51+47=46+52=98$"],"설명":"두 값의 합이 같으므로 전체 합이 변하지 않고, 평균은 그대로 $50$ 이다.","확인":"98","스킬":"C7","고비":false},{"제목":"편차 제곱의 합","힌트":"분산에 변량의 개수를 곱하면 무엇이 되는가?","식":["$10\\times5=50$","$(-4)^2+2^2=20$"],"설명":"분산은 (편차)$^2$ 의 평균이므로 (편차)$^2$ 의 합은 $10\\times5=50$ 이다. 잘못 기록된 값 $46$, $52$ 의 편차는 각각 $-4$, $2$ 이다.","확인":null,"스킬":"C7","고비":true},{"제목":"실제 분산","힌트":"잘못된 두 값의 제곱을 빼고 실제 두 값의 제곱을 더하면?","식":["$50-(-4)^2-2^2+1^2+(-3)^2=40$","$\\frac{40}{5}=8$"],"설명":"실제 값 $51$, $47$ 의 편차는 각각 $1$, $-3$ 이다. 이 합을 개수 $5$ 로 나누면 실제 분산이다.","확인":"8","스킬":"C7","고비":false},{"제목":"표준편차","힌트":"표준편차와 분산은 어떤 관계인가?","식":["$\\sqrt{8}=2\\sqrt{2}$"],"설명":"표준편차는 분산의 양의 제곱근이다.","확인":null,"스킬":"C7","고비":false}],"fb":"fig/ns/"},"ns-593d707b885e":{"길":"보이지 않는 두 막대의 학생 수를 문자로 두고, 전체 인원과 평균 조건으로 두 식을 세워 연립한 뒤 중앙값과 최빈값을 읽는다","단계":[{"제목":"인원의 식","힌트":"보이지 않는 막대를 문자로 두고 전체 학생 수 $40$ 을 식으로 쓰면?","식":["$8+2+3+x+3+y+2+1=40$","$x+y=21$"],"설명":"$3$ 회, $5$ 회인 학생 수를 각각 $x$, $y$ 라 하자. 그림에서 $0$ 회 $8$ 명, $1$ 회 $2$ 명, $2$ 회 $3$ 명, $4$ 회 $3$ 명, $6$ 회 $2$ 명, $7$ 회 $1$ 명이다.","확인":null,"스킬":"C7","고비":false},{"제목":"평균의 식","힌트":"(횟수 × 학생 수) 의 합을 $40$ 으로 나눈 값이 평균이다. 식으로 쓰면?","식":["$\\frac{0\\times8+1\\times2+2\\times3+3x+4\\times3+5y+6\\times2+7\\times1}{40}=3$","$3x+5y=81$"],"설명":"분자를 정리하면 $3x+5y+39$ 이고, 이것이 $40\\times3=120$ 과 같다.","확인":null,"스킬":"C7","고비":true},{"제목":"x, y 의 값","힌트":"두 식을 연립해 풀면?","식":["$x=12,\\ y=9$"],"설명":"$x+y=21$ 과 $3x+5y=81$ 에서 한 문자를 없앤다.","확인":null,"스킬":"A10","고비":false},{"제목":"중앙값과 최빈값","힌트":"$40$ 명의 중앙값은 몇 번째와 몇 번째 값으로 구하는가?","식":["$a=3,\\ b=3$","$a-b=0$"],"설명":"$40$ 명이므로 중앙값은 $20$ 번째와 $21$ 번째 값의 평균이다. $0$ 회, $1$ 회, $2$ 회가 모두 $13$ 명이고 $3$ 회가 $12$ 명이므로 $14$ 번째부터 $25$ 번째까지가 $3$ 회이다. 최빈값은 학생 수가 가장 많은 $3$ 회이다.","확인":"0","스킬":"C7","고비":false}],"fb":"fig/ns/"},"ns-5b3d5b9f6dc9":{"길":"수선을 내려 닮음으로 두 점의 x 좌표의 비를 구하고, 두 점이 원점을 지나는 같은 직선 위에 있다는 식을 세운다","단계":[{"제목":"닮음으로 x 좌표의 비","힌트":"$A$, $B$ 에서 $x$ 축에 수선을 내리면 어떤 닮은 삼각형이 생기는가?","식":["$\\triangle APO\\sim\\triangle BQO$","$\\overline{OP}:\\overline{OQ}=1:4$"],"설명":"$A$, $B$ 에서 $x$ 축에 내린 수선의 발을 각각 $P$, $Q$ 라 하면 두 직각삼각형은 $AA$ 닮음이고 닮음비가 $\\overline{OA}:\\overline{OB}=1:4$ 이므로 $\\overline{OP}:\\overline{OQ}=1:4$ 이다.","확인":null,"스킬":"S1","고비":true},{"제목":"두 점의 좌표","힌트":"$A$ 의 $x$ 좌표를 $t$ 라 하면 $B$ 의 좌표는?","식":["$A(t,\\,t^2)$","$B(4t,\\,16at^2)$"],"설명":"$B$ 의 $x$ 좌표는 $4t$ 이고, $B$ 는 $y=ax^2$ 위의 점이다.","확인":null,"스킬":"S4","고비":false},{"제목":"a 의 값","힌트":"원점을 지나는 직선 위의 두 점에서 ($y$ 좌표) 를 ($x$ 좌표) 로 나눈 값은?","식":["$t^2=kt,\\ 16at^2=4kt$","$16a=4,\\ a=\\frac{1}{4}$"],"설명":"직선 $l$ 은 원점을 지나므로 $y=kx\\ (k>0)$ 로 둔다. 두 점을 각각 대입한 뒤 $k$ 를 없앤다.","확인":"1/4","스킬":"G9","고비":false}],"fb":"fig/ns/"},"ns-624816fb0a08":{"길":"삼각비로 $\\overline{AM}$을 구하고 닮은 삼각형으로 $\\overline{DM}$을 얻은 뒤 피타고라스 정리로 $\\overline{AC}$를 잇는다.","단계":[{"제목":"$\\overline{AM}$ 구하기","힌트":"$\\triangle ABM$에서 $\\sin x^\\circ$는 어느 두 변의 비인가?","식":["$\\sin x^\\circ=\\frac{3}{\\overline{AM}}=\\frac{1}{3}$","$\\overline{AM}=9$"],"설명":"$\\angle B=90^\\circ$이므로 $\\sin x^\\circ=\\frac{\\overline{BM}}{\\overline{AM}}$이다.","확인":"9","스킬":"S6"},{"제목":"닮은 삼각형 찾기","힌트":"$\\triangle ABM$과 닮은 삼각형은 무엇일까? 맞꼭지각을 보자.","식":["$\\triangle ABM\\sim\\triangle CDM$"],"설명":"$\\angle B=\\angle D=90^\\circ$이고 $\\angle AMB=\\angle CMD$(맞꼭지각)이므로 $AA$ 닮음이다.","확인":null,"스킬":"S1","고비":true},{"제목":"$\\overline{DM}$ 구하기","힌트":"대응하는 변끼리 비례식을 세워 보자.","식":["$\\overline{AM}:\\overline{CM}=\\overline{BM}:\\overline{DM}$","$9:3=3:\\overline{DM}$","$\\overline{DM}=1$"],"설명":"닮은 삼각형에서 대응변의 길이의 비는 같다.","확인":"1","스킬":"S1"},{"제목":"$\\overline{CD}$, $\\overline{AC}$ 구하기","힌트":"$\\triangle CDM$에서 $\\overline{CD}$를, 그다음 $\\triangle ADC$에서 $\\overline{AC}$를 구하자.","식":["$\\overline{CD}=\\sqrt{3^2-1^2}=2\\sqrt{2}$","$\\overline{AD}=9+1=10$","$\\overline{AC}=\\sqrt{10^2+(2\\sqrt{2})^2}=6\\sqrt{3}$"],"설명":"$A$, $M$, $D$가 한 직선 위에 있으므로 $\\overline{AD}=\\overline{AM}+\\overline{MD}$이다. $\\triangle ADC$는 $\\angle D=90^\\circ$인 직각삼각형이다.","확인":null,"스킬":"S3"},{"제목":"$\\sin y^\\circ$ 구하기","힌트":"$\\angle CAD=y^\\circ$인 직각삼각형 $ADC$에서 $\\sin y^\\circ$는 어느 두 변의 비인가?","식":["$\\sin y^\\circ=\\frac{\\overline{CD}}{\\overline{AC}}=\\frac{2\\sqrt{2}}{6\\sqrt{3}}=\\frac{\\sqrt{6}}{9}$"],"설명":"$\\angle D=90^\\circ$이므로 $\\sin y^\\circ$는 $\\angle CAD$의 대변과 빗변의 비이다. 분모를 유리화한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-63d5fc90666c":{"길":"$A$의 $x$좌표를 문자로 두어 두 선분의 길이를 쓰고 비례식을 세운다.","단계":[{"제목":"세 점의 좌표 나타내기","힌트":"$A$의 $x$좌표를 $a$라 하면 $A$, $B$, $D$의 좌표는?","식":["$A(a,\\ 2a^2)$","$B(-a,\\ 2a^2)$","$D\\left(a,\\ -\\frac{1}{3}a^2\\right)$"],"설명":"$A$는 제$1$사분면 위의 점이므로 $a>0$이다. $B$는 $y$축에 대칭이라 $y$좌표가 같고, $D$는 $A$와 $x$좌표가 같으며 $y=-\\frac{1}{3}x^2$ 위에 있다.","확인":null,"스킬":"S4"},{"제목":"두 선분의 길이","힌트":"$\\overline{AB}$는 $x$좌표의 차, $\\overline{AD}$는 $y$좌표의 차이다. 각각 $a$로 나타내면?","식":["$\\overline{AB}=2a$","$\\overline{AD}=2a^2+\\frac{1}{3}a^2=\\frac{7}{3}a^2$"],"설명":"$\\overline{AB}$는 수평 선분이고 $\\overline{AD}$는 수직 선분이다.","확인":null,"스킬":"S4"},{"제목":"비례식으로 $a$ 구하기","힌트":"$\\overline{AB}:\\overline{AD}=3:4$를 $a$의 식으로 쓰면?","식":["$2a:\\frac{7}{3}a^2=3:4$","$8a=7a^2$","$a=\\frac{8}{7}$"],"설명":"내항의 곱과 외항의 곱이 같으므로 식을 세운 뒤 $a>0$이므로 양변을 $a$로 나눈다.","확인":"8/7","스킬":"A8","고비":true}],"fb":"fig/ns/"},"ns-69a84c02d2be":{"길":"터널 가운데 바닥을 원점으로 잡아 포물선의 식을 세우고, 트럭 폭의 끝 위치에서 높이를 읽는다.","단계":[{"제목":"포물선 식의 꼴 정하기","힌트":"$\\overline{AB}$의 중점 $C$를 원점으로 하면 꼭짓점 $D$와 $B$의 좌표는?","식":["$D(0,\\ 6)$, $B(2,\\ 0)$","$y=ax^2+6$"],"설명":"$\\overline{AB}=4$이므로 $B(2,0)$이고 꼭짓점이 $(0,6)$이므로 $y=ax^2+6$으로 둘 수 있다.","확인":null,"스킬":"S4"},{"제목":"$a$ 구하기","힌트":"그래프가 $(2,0)$을 지난다. 대입하면?","식":["$0=4a+6$","$a=-\\frac{3}{2}$","$y=-\\frac{3}{2}x^2+6$"],"설명":"점 $(2,0)$을 $y=ax^2+6$에 대입한다.","확인":"-3/2","스킬":"S4"},{"제목":"트럭 폭에 맞는 높이","힌트":"폭이 $2$인 트럭이 터널 가운데로 지나면 트럭 양 끝의 $x$좌표는? 그 위치의 포물선 높이를 구하자.","식":["$x=1$일 때 $y=-\\frac{3}{2}\\times1^2+6=\\frac{9}{2}$"],"설명":"트럭이 가운데로 지나가므로 트럭 폭의 양 끝은 $x=\\pm1$이다. 짐의 윗 모서리가 포물선에 닿을 때까지가 한계이므로 그 위치의 포물선 높이가 한계 높이이다.","확인":"9/2","스킬":"C7","고비":true},{"제목":"바닥 높이 빼기","힌트":"트럭 바닥은 지면에서 $1\\,\\mathrm{m}$ 떠 있다. 짐을 실을 수 있는 높이는?","식":["$\\frac{9}{2}-1=\\frac{7}{2}$"],"설명":"트럭 바닥을 기준으로 하므로 지면 기준 높이에서 $1$을 뺀다.","확인":"7/2","스킬":"C7"}],"fb":"fig/ns/"},"ns-780fe51c960b":{"길":"$P$의 좌표를 문자로 두어 $\\overline{PQ}$를 이차식으로 나타낸 뒤 완전제곱꼴로 최솟값을 구한다.","단계":[{"제목":"$P$, $Q$의 좌표","힌트":"$Q$는 $P$와 $y$좌표가 같고 직선 $y=x+1$ 위에 있다. $P$의 $x$좌표를 $a$로 두면 $Q$의 $x$좌표는?","식":["$P(a,\\ -a^2-4)$","$-a^2-4=x+1$","$Q(-a^2-5,\\ -a^2-4)$"],"설명":"$Q$의 $y$좌표 $-a^2-4$를 $y=x+1$에 대입해 $x$를 구한다.","확인":null,"스킬":"S4"},{"제목":"$\\overline{PQ}$를 $a$의 식으로","힌트":"$\\overline{PQ}$는 $x$축에 평행하다. 두 점의 $x$좌표의 차로 쓰면?","식":["$\\overline{PQ}=a-(-a^2-5)=a^2+a+5$"],"설명":"$a^2+a+5>0$이므로 $Q$는 항상 $P$의 왼쪽에 있고, 길이는 $P$의 $x$좌표에서 $Q$의 $x$좌표를 뺀 값이다.","확인":null,"스킬":"S4","고비":true},{"제목":"완전제곱꼴로 최솟값","힌트":"이차식을 $(a+\\square)^2+\\triangle$ 꼴로 고치자.","식":["$a^2+a+5=\\left(a+\\frac{1}{2}\\right)^2+\\frac{19}{4}$","$a=-\\frac{1}{2}$일 때 최솟값 $\\frac{19}{4}$"],"설명":"제곱식은 $0$ 이상이므로 $a=-\\frac{1}{2}$일 때 가장 작다.","확인":"19/4","스킬":"A6"}],"fb":"fig/ns/"},"ns-79192f7f20d2":{"길":"$A$를 지나는 수평선으로 닮은 삼각형을 만들어 $B$의 좌표를 $A$의 좌표로 나타낸 뒤 포물선 위의 조건을 쓴다.","단계":[{"제목":"수평선으로 닮음 만들기","힌트":"$A$를 지나는 수평선을 긋고 $C$, $B$에서 수선을 내리면 닮은 삼각형이 생긴다.","식":["$\\triangle ACP\\sim\\triangle ABQ$","$\\overline{AP}:\\overline{AQ}=\\overline{CP}:\\overline{BQ}=1:5$"],"설명":"점 $A$를 지나 $x$축에 평행한 직선을 긋고 $C$, $B$에서 이 직선에 내린 수선의 발을 각각 $P$, $Q$라 하자. $\\overline{AC}:\\overline{CB}=1:4$이므로 $\\overline{AC}:\\overline{AB}=1:5$이고, 두 삼각형은 닮음비가 $1:5$이다.","확인":null,"스킬":"S1","고비":true},{"제목":"$A$, $Q$의 좌표","힌트":"$A$의 $x$좌표를 $a$라 하면 $\\overline{AP}$는? 닮음비로 $\\overline{AQ}$를 구하자.","식":["$A\\left(a,\\ \\frac{1}{4}a^2\\right)\\ (a<0)$","$\\overline{AP}=-a,\\ \\overline{AQ}=-5a$","$Q\\left(-4a,\\ \\frac{1}{4}a^2\\right)$"],"설명":"그림에서 $A$는 $y$축의 왼쪽에 있으므로 $a<0$이다. $P$는 $y$축 위의 점이라 $\\overline{AP}=-a$이다.","확인":null,"스킬":"S4"},{"제목":"$B$의 좌표","힌트":"$\\overline{BQ}$는 $\\overline{CP}$의 몇 배인가? $B$의 $y$좌표를 구하자.","식":["$\\overline{CP}=1-\\frac{1}{4}a^2$","$\\overline{BQ}=5-\\frac{5}{4}a^2$","$B\\left(-4a,\\ 5-a^2\\right)$"],"설명":"$\\overline{CP}$는 $C$와 $P$의 $y$좌표의 차이다. $B$의 $y$좌표는 $\\frac{1}{4}a^2+\\overline{BQ}$이다.","확인":null,"스킬":"S1"},{"제목":"$a$ 구하기","힌트":"$B$가 $y=\\frac{1}{4}x^2$ 위의 점임을 이용해 대입하자.","식":["$5-a^2=\\frac{1}{4}(-4a)^2=4a^2$","$a^2=1$","$a=-1$"],"설명":"$a<0$이므로 $a=-1$이다.","확인":"-1","스킬":"S4"},{"제목":"직선 $l$의 기울기","힌트":"$A$, $B$의 좌표를 구해 기울기 공식에 넣자.","식":["$A\\left(-1,\\ \\frac{1}{4}\\right),\\ B(4,\\ 4)$","$\\frac{4-\\frac{1}{4}}{4-(-1)}=\\frac{3}{4}$"],"설명":"$a=-1$을 $A$, $B$의 좌표에 대입한다.","확인":"3/4","스킬":"S4"}],"fb":"fig/ns/"},"ns-795f0b2b8f3f":{"길":"각을 차례로 구해 이등변삼각형 두 개와 닮음을 찾은 뒤 $\\overline{CD}=x$로 두고 비례식을 이차방정식으로 푼다.","단계":[{"제목":"각의 크기 구하기","힌트":"$\\angle A$는 몇 도일까? $\\angle B$의 이등분선이 만드는 각들도 구해 보자.","식":["$\\angle A=36^\\circ$","$\\angle ABD=\\angle DBC=36^\\circ$","$\\angle BDC=72^\\circ$"],"설명":"삼각형의 내각의 합이 $180^\\circ$이므로 $\\angle A=180^\\circ-72^\\circ-72^\\circ$이다. $\\angle B=72^\\circ$를 이등분하면 각각 $36^\\circ$이고, $\\triangle BCD$에서 $\\angle BDC=180^\\circ-36^\\circ-72^\\circ$이다.","확인":null,"스킬":"S10"},{"제목":"같은 길이의 변 찾기","힌트":"크기가 같은 두 각을 가진 삼각형은 어떤 삼각형일까?","식":["$\\overline{DA}=\\overline{DB}$","$\\overline{BD}=\\overline{BC}$"],"설명":"$\\triangle ABD$에서 $\\angle A=\\angle ABD=36^\\circ$이므로 $\\overline{DA}=\\overline{DB}$이다. $\\triangle BCD$에서 $\\angle C=\\angle BDC=72^\\circ$이므로 $\\overline{BD}=\\overline{BC}$이다.","확인":null,"스킬":"S10"},{"제목":"닮은 삼각형 찾기","힌트":"$\\triangle ABC$와 $\\triangle BCD$에서 크기가 같은 각의 짝을 찾아 보자.","식":["$\\triangle ABC\\sim\\triangle BCD$","$\\overline{AB}:\\overline{BC}=\\overline{BC}:\\overline{CD}$"],"설명":"$\\triangle ABC$는 $\\angle B=\\angle C=72^\\circ$이고 $\\triangle BCD$는 $\\angle C=\\angle BDC=72^\\circ$이며 $\\angle A=\\angle DBC=36^\\circ$이므로 $AA$ 닮음이다. 대응변의 길이의 비는 같다.","확인":null,"스킬":"S1","고비":true},{"제목":"$x$에 대한 이차방정식","힌트":"$\\overline{CD}=x$로 두고 $\\overline{BC}$를 $x$로 나타내 비례식에 넣자.","식":["$\\overline{DA}=\\overline{BD}=\\overline{BC}=10-x$","$10:(10-x)=(10-x):x$","$x^2-30x+100=0$"],"설명":"$\\overline{AC}=\\overline{AB}=10$이므로 $\\overline{DA}=10-x$이다. 앞에서 $\\overline{DA}=\\overline{BD}=\\overline{BC}$였다. 외항의 곱과 내항의 곱을 같게 놓는다.","확인":null,"스킬":"S1"},{"제목":"범위에 맞는 근 고르기","힌트":"근의 공식으로 푼 뒤 $0<x<10$에 맞는 근을 고르자.","식":["$x=15\\pm5\\sqrt{5}$","$x=15-5\\sqrt{5}$"],"설명":"$15+5\\sqrt{5}$는 $10$보다 크므로 $\\overline{CD}$의 길이가 될 수 없다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-7ad570262026":{"길":"일차함수의 식에서 $P$의 좌표를 문자로 나타내고, 직사각형의 넓이를 이차방정식으로 푼 뒤 조건으로 근을 고른다.","단계":[{"제목":"일차함수의 식","힌트":"$x$절편과 $y$절편이 모두 $-20$이다. 기울기는?","식":["$y=-x-20$"],"설명":"기울기는 $\\frac{-20-0}{0-(-20)}=-1$이고 $y$절편이 $-20$이다.","확인":null,"스킬":"S4"},{"제목":"$P$의 좌표와 두 변의 길이","힌트":"$P$의 $x$좌표를 $-a\\ (a>0)$로 두면 $y$좌표는? 직사각형의 가로와 세로는 무엇일까?","식":["$P(-a,\\ a-20)$","$\\overline{BO}=a,\\ \\overline{BP}=20-a$"],"설명":"$P$는 제$3$사분면 위의 점이다. $\\overline{BO}$는 $P$의 $x$좌표의 절댓값, $\\overline{BP}$는 $y$좌표의 절댓값이다.","확인":null,"스킬":"G10"},{"제목":"넓이 식 풀기","힌트":"직사각형 $APBO$의 넓이가 $36$이라는 식을 $a$로 세우자.","식":["$a(20-a)=36$","$a^2-20a+36=0$","$a=2$ 또는 $a=18$"],"설명":"가로 $\\times$ 세로가 넓이이므로 식을 세우고 좌변을 인수분해한다.","확인":null,"스킬":"G10","고비":true},{"제목":"조건으로 근 고르기","힌트":"$\\overline{PA}$는 $P$의 $x$좌표의 절댓값이다. $\\overline{PA}>\\overline{PB}$를 $a$로 쓰면?","식":["$a>20-a$","$a=18$","$y=18-20=-2$"],"설명":"$\\overline{PA}=a$, $\\overline{PB}=20-a$이므로 $a$는 $10$보다 커야 한다.","확인":"-2","스킬":"G10"}],"fb":"fig/ns/"},"ns-7b78d2883f89":{"길":"닮은 삼각형으로 직사각형의 가로를 세로의 식으로 나타내 넓이를 이차식으로 만들고 최댓값을 찾는다.","단계":[{"제목":"닮음으로 $\\overline{DG}$ 나타내기","힌트":"직사각형의 윗변과 $\\overline{BC}$는 평행하다. 닮은 삼각형의 높이의 비와 밑변의 비를 이용하자.","식":["$(12-x):12=\\overline{DG}:18$","$\\overline{DG}=\\frac{3}{2}(12-x)$"],"설명":"직사각형을 $DEFG$라 하자. $D$, $G$는 각각 $\\overline{AB}$, $\\overline{AC}$ 위의 점이고 $E$, $F$는 $\\overline{BC}$ 위의 점이며 $\\overline{DE}=x$이다. $\\overline{DG}\\parallel\\overline{BC}$이므로 $\\triangle ADG\\sim\\triangle ABC$이고 높이의 비가 닮음비이다.","확인":null,"스킬":"S1","고비":true},{"제목":"넓이를 $x$의 식으로","힌트":"직사각형의 넓이를 $y$라 하고 가로 $\\times$ 세로로 쓰자.","식":["$y=x\\times\\frac{3}{2}(12-x)=-\\frac{3}{2}x^2+18x$"],"설명":"세로는 $\\overline{DE}=x$, 가로는 $\\overline{DG}$이다.","확인":null,"스킬":"A6"},{"제목":"넓이가 최대일 때의 $x$","힌트":"이차식을 완전제곱꼴로 고치자.","식":["$y=-\\frac{3}{2}(x-6)^2+54$","$x=6$"],"설명":"$0<x<12$이므로 $x=6$은 범위 안이고, 이때 넓이가 최대이다.","확인":"6","스킬":"A6"},{"제목":"둘레의 길이","힌트":"$x=6$일 때 가로와 세로를 구해 둘레를 계산하자.","식":["$\\overline{DG}=\\frac{3}{2}\\times(12-6)=9$","$2\\times(6+9)=30$"],"설명":"직사각형의 둘레는 (가로 $+$ 세로)$\\times2$이다.","확인":"30","스킬":"A6"}],"fb":"fig/ns/"},"ns-7ce4abf70947":{"길":"수선의 길이를 구한 뒤 각 $x$를 $\\triangle ADE$의 각으로 옮겨 삼각비를 계산한다.","단계":[{"제목":"$\\overline{DE}$ 구하기","힌트":"직각삼각형 $ADC$에서 빗변에 내린 수선 $\\overline{DE}$는 $\\overline{AE}$, $\\overline{CE}$와 어떤 관계일까?","식":["$\\overline{DE}^2=\\overline{AE}\\times\\overline{CE}=36$","$\\overline{DE}=6$"],"설명":"$\\overline{AD}\\perp\\overline{BC}$이므로 $\\triangle ADC$는 $\\angle D=90^\\circ$인 직각삼각형이고, $\\overline{DE}\\perp\\overline{AC}$이므로 $\\overline{DE}^2=\\overline{AE}\\times\\overline{CE}$이다.","확인":"6","스킬":"S3"},{"제목":"$\\overline{AD}$ 구하기","힌트":"직각삼각형 $ADE$에서 피타고라스 정리를 쓰자.","식":["$\\overline{AD}=\\sqrt{4^2+6^2}=2\\sqrt{13}$"],"설명":"$\\triangle ADE$는 $\\angle E=90^\\circ$인 직각삼각형이다.","확인":null,"스킬":"S3"},{"제목":"각 $x$를 옮기기","힌트":"$x^\\circ+y^\\circ$의 크기와 $\\triangle ADE$의 각을 비교해 보자.","식":["$x+y=90$","$\\angle ADE=x^\\circ$"],"설명":"$\\angle BAC=90^\\circ$이므로 $x+y=90$이다. $\\triangle ADE$에서 $\\angle DAE=y^\\circ$, $\\angle AED=90^\\circ$이므로 $\\angle ADE=90^\\circ-y^\\circ=x^\\circ$이다.","확인":null,"스킬":"S10","고비":true},{"제목":"삼각비 값 구하기","힌트":"$\\triangle ADE$에서 $\\sin x^\\circ$, $\\cos y^\\circ$, $\\tan y^\\circ$를 각각 구하자.","식":["$\\sin x^\\circ=\\frac{\\overline{AE}}{\\overline{AD}}=\\frac{2}{\\sqrt{13}}$","$\\cos y^\\circ=\\frac{\\overline{AE}}{\\overline{AD}}=\\frac{2}{\\sqrt{13}}$","$\\tan y^\\circ=\\frac{\\overline{DE}}{\\overline{AE}}=\\frac{3}{2}$"],"설명":"$\\angle ADE=x^\\circ$의 대변은 $\\overline{AE}$이고, $\\angle DAE=y^\\circ$의 인접변은 $\\overline{AE}$, 대변은 $\\overline{DE}$이다.","확인":null,"스킬":"S6"},{"제목":"$a$, $b$ 정하고 합 구하기","힌트":"계산한 값을 $\\frac{4\\sqrt{a}}{a}-b$ 꼴로 맞춰 $a$, $b$를 읽자.","식":["$\\frac{4}{\\sqrt{13}}-3=\\frac{4\\sqrt{13}}{13}-3$","$a=13,\\ b=3$","$a+b=16$"],"설명":"$\\frac{2}{\\sqrt{13}}+\\frac{2}{\\sqrt{13}}-2\\times\\frac{3}{2}$를 계산하고 분모를 유리화한다.","확인":"16","스킬":"S6"}],"fb":"fig/ns/"},"ns-832eff30e5c9":{"길":"대칭인 두 점의 좌표를 문자로 두어 둘레를 이차식으로 나타낸 뒤 완전제곱꼴로 최댓값을 구한다.","단계":[{"제목":"두 점의 좌표 나타내기","힌트":"$A$, $D$는 $y$축에 대하여 대칭이다. $D$의 $x$좌표를 $a$라 하면 두 점의 좌표는?","식":["$D(a,\\ -a^2+6)\\ (a>0)$","$A(-a,\\ -a^2+6)$"],"설명":"$A$, $D$는 높이가 같고 $y=-x^2+6$ 위의 점이다.","확인":null,"스킬":"S4"},{"제목":"둘레를 $a$의 식으로","힌트":"$\\overline{AD}$와 $\\overline{CD}$를 $a$로 나타내자.","식":["$\\overline{AD}=2a,\\ \\overline{CD}=-a^2+6$","$y=2(2a-a^2+6)=-2a^2+4a+12$"],"설명":"직사각형의 둘레를 $y$라 하자. $\\overline{CD}$는 $D$의 $y$좌표와 같다.","확인":null,"스킬":"S4","고비":true},{"제목":"최댓값 구하기","힌트":"이차식을 완전제곱꼴로 고치자.","식":["$y=-2(a-1)^2+14$","$a=1$일 때 최댓값 $14$"],"설명":"$0<a<\\sqrt{6}$이므로 $a=1$은 범위 안에 있다.","확인":"14","스킬":"A6"}],"fb":"fig/ns/"},"ns-84746b634b33":{"길":"꼭짓점의 좌표를 문자로 두고 이웃한 두 변의 길이가 같다는 식을 세워 푼다.","단계":[{"제목":"세 꼭짓점의 좌표","힌트":"$D$의 $x$좌표를 $a$라 하면 $A$, $C$의 좌표는?","식":["$D(a,\\ -a^2)\\ (a>0)$","$A(-a,\\ -a^2)$","$C(a,\\ -4)$"],"설명":"$A$, $D$는 $y=-x^2$ 위에서 $y$축에 대칭이고, $C$는 $D$의 바로 아래 직선 $y=-4$ 위의 점이다.","확인":null,"스킬":"S4"},{"제목":"정사각형 조건으로 식 세우기","힌트":"정사각형은 이웃한 두 변의 길이가 같다. $\\overline{AD}$와 $\\overline{DC}$를 $a$로 쓰면?","식":["$\\overline{AD}=2a,\\ \\overline{DC}=-a^2+4$","$2a=-a^2+4$","$a^2+2a-4=0$"],"설명":"$\\overline{DC}$는 $D$와 $C$의 $y$좌표의 차이다.","확인":null,"스킬":"C7","고비":true},{"제목":"$a$를 구해 넓이 계산","힌트":"근의 공식으로 $a$를 구하고 $(2a)^2$에 넣자.","식":["$a=-1+\\sqrt{5}$","$(2a)^2=4(6-2\\sqrt{5})=24-8\\sqrt{5}$"],"설명":"$a>0$이므로 $a=-1-\\sqrt{5}$는 버린다. 정사각형의 넓이는 한 변의 제곱이다.","확인":null,"스킬":"S4"}],"fb":"fig/ns/"},"ns-85f2638f2da2":{"길":"$\\overline{CE}=k$로 두고 같은 선분 $\\overline{AC}$와 $\\overline{BC}$를 서로 다른 삼각형에서 나타내 방정식을 세운다.","단계":[{"제목":"두 변의 관계","힌트":"$\\angle ABC=45^\\circ$, $\\angle C=90^\\circ$인 삼각형에서 $\\overline{AC}$와 $\\overline{BC}$의 관계는?","식":["$\\overline{AC}=\\overline{BC}$"],"설명":"$\\angle C=90^\\circ$, $\\angle B=45^\\circ$이므로 $\\triangle ABC$는 직각이등변삼각형이다.","확인":null,"스킬":"S6"},{"제목":"$k$로 식 세우기","힌트":"$\\overline{CE}=k$라 하자. $\\overline{AC}$는 $\\tan75^\\circ$로, $\\overline{BC}$는 $\\overline{BE}+\\overline{EC}$로 나타내 보자.","식":["$\\overline{AC}=(2+\\sqrt{3})k$","$\\overline{BC}=a+k$","$(2+\\sqrt{3})k=a+k$"],"설명":"$\\triangle AEC$에서 $\\tan75^\\circ=\\frac{\\overline{AC}}{\\overline{CE}}$이다. $\\overline{AC}=\\overline{BC}$이므로 두 식을 같게 놓을 수 있다.","확인":null,"스킬":"S6","고비":true},{"제목":"$k$를 풀고 $\\overline{BC}$ 구하기","힌트":"방정식에서 $k$를 $a$로 나타낸 뒤 $\\overline{BC}$를 구하자.","식":["$k=\\frac{a}{1+\\sqrt{3}}=\\frac{\\sqrt{3}-1}{2}a$","$\\overline{AC}=\\overline{BC}=\\frac{\\sqrt{3}+1}{2}a$"],"설명":"분모를 유리화해서 $k$를 구하고, $\\overline{BC}=a+k$에 대입한다.","확인":null,"스킬":"A8"},{"제목":"$\\overline{DC}$ 구하기","힌트":"직각삼각형 $BCD$에서 $\\angle DBC=30^\\circ$이다. $\\overline{DC}$는 $\\overline{BC}$와 어떤 관계일까?","식":["$\\overline{DC}=\\overline{BC}\\tan30^\\circ=\\frac{\\sqrt{3}+1}{2}a\\times\\frac{\\sqrt{3}}{3}=\\frac{3+\\sqrt{3}}{6}a$"],"설명":"$\\tan30^\\circ=\\frac{\\overline{DC}}{\\overline{BC}}$이다.","확인":null,"스킬":"S6"},{"제목":"$\\overline{AD}$ 구하기","힌트":"$D$는 $\\overline{AC}$ 위의 점이다. $\\overline{AC}$에서 $\\overline{DC}$를 빼자.","식":["$\\overline{AD}=\\overline{AC}-\\overline{DC}=\\frac{\\sqrt{3}}{3}a$"],"설명":"$\\frac{\\sqrt{3}+1}{2}a-\\frac{3+\\sqrt{3}}{6}a$를 통분해 계산한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-889b13ab0012":{"길":"정사각형으로 변의 길이를 문자로 나타내고 닮은 사각형의 대응변의 비로 이차방정식을 세워 푼다.","단계":[{"제목":"변의 길이를 $x$로 나타내기","힌트":"$\\overline{AD}=x$라 하면 $\\overline{DF}$는? 정사각형 $ABEF$의 성질을 쓰자.","식":["$\\overline{AF}=12$","$\\overline{DF}=x-12$","$\\overline{DC}=12$"],"설명":"정사각형 $ABEF$에서 $\\overline{AF}=\\overline{AB}=12$이다. $\\overline{DC}$는 직사각형의 마주 보는 변이라 $\\overline{AB}$와 같다.","확인":null,"스킬":"S1"},{"제목":"대응변의 비례식","힌트":"$\\square ABCD\\sim\\square DFEC$에서 $\\overline{AB}$, $\\overline{AD}$에 대응하는 변은 각각 무엇일까?","식":["$\\overline{AB}:\\overline{DF}=\\overline{AD}:\\overline{DC}$","$12:(x-12)=x:12$"],"설명":"꼭짓점 순서대로 $A\\to D$, $B\\to F$, $C\\to E$, $D\\to C$가 대응한다. $\\overline{AB}$에는 $\\overline{DF}$, $\\overline{AD}$에는 $\\overline{DC}$가 대응하고 닮은 도형의 대응변의 비는 일정하다.","확인":null,"스킬":"S1","고비":true},{"제목":"이차방정식 풀기","힌트":"외항의 곱과 내항의 곱을 같게 놓고 정리하자.","식":["$x^2-12x-144=0$","$x=6+6\\sqrt{5}$"],"설명":"근의 공식으로 푼 뒤 $x>12$인 근을 고른다.","확인":null,"스킬":"S1"},{"제목":"$ab$ 구하기","힌트":"$x=a+b\\sqrt{5}$ 꼴에서 $a$, $b$를 읽자.","식":["$a=6,\\ b=6$","$ab=36$"],"설명":"$\\overline{AD}=(a+b\\sqrt{5})\\,\\mathrm{cm}$이므로 계수를 비교한다.","확인":"36","스킬":"S1"}],"fb":"fig/ns/"},"ns-889f22dc5bc0":{"길":"$P$의 $x$좌표를 문자로 두어 $Q$의 좌표를 나타내고, 두 점의 $y$좌표가 같다는 식을 푼다.","단계":[{"제목":"두 점의 좌표","힌트":"$P$의 $x$좌표를 $a$라 하면 $Q$의 $x$좌표는? 두 점은 같은 높이이고 $\\overline{PQ}=2$이다.","식":["$P(a,\\ 4a^2)$","$Q(a+2,\\ (a+2)^2)$"],"설명":"$y=x^2$이 $y=4x^2$보다 완만하므로 같은 높이에서 $Q$가 $P$의 오른쪽에 있다. $\\overline{PQ}$는 수평 선분이라 $x$좌표의 차가 $2$이다.","확인":null,"스킬":"S4"},{"제목":"$y$좌표가 같다는 식","힌트":"두 점이 직선 $y=k$ 위에 있으므로 $y$좌표가 같다. 식으로 쓰고 풀어 보자.","식":["$4a^2=(a+2)^2$","$3a^2-4a-4=0$","$a=2$"],"설명":"$(3a+2)(a-2)=0$에서 $a>0$이므로 $a=2$이다.","확인":"2","스킬":"C7","고비":true},{"제목":"$k$의 값","힌트":"$k$는 $P$의 $y$좌표이다.","식":["$k=4\\times2^2=16$"],"설명":"$k=4a^2$에 $a=2$를 대입한다.","확인":"16","스킬":"S4"}],"fb":"fig/ns/"},"ns-8bc2251e0243":{"길":"$a$ 의 값을 바꿔 가며 포물선이 직사각형을 지나는 범위의 양 끝이 되는 꼭짓점을 찾아 그 점을 지날 때의 $a$ 를 구한다","단계":[{"제목":"경계가 되는 꼭짓점 찾기","힌트":"$a<0$ 에서 $a$ 가 작아질 때 포물선이 직사각형에 처음 닿는 꼭짓점과 마지막으로 벗어나는 꼭짓점은 어디인가?","식":["$\\mathrm{A}(-4,-4)$","$\\mathrm{C}(-2,-12)$"],"설명":"$a$ 가 작아지면 포물선은 아래로 좁아지며 직사각형을 지나간다. 처음 닿는 꼭짓점이 $\\mathrm{A}$, 마지막으로 벗어나는 꼭짓점이 $\\mathrm{C}$ 이므로 이 두 점을 지날 때가 범위의 양 끝이다.","확인":null,"스킬":"G1","고비":true},{"제목":"점 A 를 지날 때의 a","힌트":"$y=ax^2$ 에 점 $\\mathrm{A}$ 의 좌표를 대입하면 $a$ 는?","식":["$-4=a\\times(-4)^2$","$a=-\\frac{1}{4}$"],"설명":"점 $\\mathrm{A}(-4,-4)$ 를 $y=ax^2$ 에 대입한다.","확인":"-1/4","스킬":"G1"},{"제목":"점 C 를 지날 때의 a","힌트":"$y=ax^2$ 에 점 $\\mathrm{C}$ 의 좌표를 대입하면 $a$ 는?","식":["$-12=a\\times(-2)^2$","$a=-3$"],"설명":"점 $\\mathrm{C}(-2,-12)$ 를 $y=ax^2$ 에 대입한다.","확인":"-3","스킬":"G1"},{"제목":"a 의 범위 정하기","힌트":"두 경계값 사이에서 서로 다른 두 점을 지나는 범위는?","식":["$-3<a<-\\frac{1}{4}$"],"설명":"$a=-\\frac{1}{4}$ 일 때는 $\\mathrm{A}$ 한 점에서만 만나고 $a=-3$ 일 때는 $\\mathrm{C}$ 한 점에서만 만나므로 양 끝값은 포함하지 않는다. 두 값 사이일 때 서로 다른 두 점을 지난다.","확인":null,"스킬":"G1"}],"fb":"fig/ns/"},"ns-8cb045e4caad":{"길":"접힌 변의 길이와 엇각으로 삼각형 PQC 가 이등변삼각형임을 찾고 수선을 그어 직각삼각형의 삼각비로 바꾼다","단계":[{"제목":"접힌 선분의 길이","힌트":"$\\mathrm{A}$ 가 $\\mathrm{C}$ 에 겹치도록 접었을 때 $\\overline{\\mathrm{AP}}$ 와 길이가 같은 선분은?","식":["$\\overline{\\mathrm{PC}}=\\overline{\\mathrm{AP}}=5$"],"설명":"접으면 $\\mathrm{A}$ 가 $\\mathrm{C}$ 로 옮겨지므로 $\\overline{\\mathrm{AP}}$ 와 $\\overline{\\mathrm{PC}}$ 의 길이가 같다. 그림에서 $\\overline{\\mathrm{AP}}=5$ 이다.","확인":"5","스킬":"S10"},{"제목":"PD 의 길이","힌트":"직각삼각형 $\\mathrm{CDP}$ 에서 $\\overline{\\mathrm{PD}}$ 는?","식":["$\\overline{\\mathrm{PD}}=\\sqrt{5^2-3^2}=4$"],"설명":"$\\overline{\\mathrm{DC}}=\\overline{\\mathrm{AB}}=3$ 이고 $\\angle\\mathrm{D}=90^\\circ$ 이다.","확인":"4","스킬":"S3"},{"제목":"삼각형 PQC 의 모양","힌트":"$\\angle\\mathrm{APQ}$ 와 $\\angle\\mathrm{PQC}$, $\\angle\\mathrm{CPQ}$ 사이의 관계로 삼각형 $\\mathrm{PQC}$ 의 모양을 알 수 있는가?","식":["$\\angle\\mathrm{PQC}=\\angle\\mathrm{CPQ}$","$\\overline{\\mathrm{QC}}=\\overline{\\mathrm{PC}}=5$"],"설명":"$\\overline{\\mathrm{AP}}\\parallel\\overline{\\mathrm{QC}}$ 이므로 $\\angle\\mathrm{APQ}=\\angle\\mathrm{PQC}$(엇각)이고, 접은 각이므로 $\\angle\\mathrm{APQ}=\\angle\\mathrm{CPQ}$ 이다. 따라서 삼각형 $\\mathrm{PQC}$ 는 $\\overline{\\mathrm{PC}}=\\overline{\\mathrm{QC}}$ 인 이등변삼각형이다.","확인":"5","스킬":"S10","고비":true},{"제목":"수선을 그어 HP, HQ 구하기","힌트":"점 $\\mathrm{Q}$ 에서 $\\overline{\\mathrm{AP}}$ 에 수선을 내리면 $\\overline{\\mathrm{AH}}$ 와 $\\overline{\\mathrm{HQ}}$ 는 각각 어느 선분과 같은가?","식":["$\\overline{\\mathrm{HP}}=5-4=1$","$\\overline{\\mathrm{HQ}}=\\overline{\\mathrm{AB}}=3$"],"설명":"점 $\\mathrm{Q}$ 에서 $\\overline{\\mathrm{AP}}$ 에 내린 수선의 발을 $\\mathrm{H}$ 라 하면 사각형 $\\mathrm{ABQH}$ 는 직사각형이다. $\\overline{\\mathrm{BC}}=\\overline{\\mathrm{AD}}=5+4=9$ 이므로 $\\overline{\\mathrm{BQ}}=9-5=4$ 이고 $\\overline{\\mathrm{AH}}=4$ 이다. 따라서 $\\overline{\\mathrm{HP}}=5-4=1$ 이다.","확인":"1","스킬":"S2"},{"제목":"tan x 의 값","힌트":"직각삼각형 $\\mathrm{HPQ}$ 에서 $x^\\circ$ 의 탄젠트는?","식":["$\\tan x^\\circ=\\frac{\\overline{\\mathrm{HQ}}}{\\overline{\\mathrm{HP}}}=3$"],"설명":"$\\angle\\mathrm{HPQ}=\\angle\\mathrm{APQ}=x^\\circ$ 이므로 $\\tan x^\\circ=\\frac{3}{1}$ 이다.","확인":"3","스킬":"S6"}],"fb":"fig/ns/"},"ns-9217b5f58700":{"길":"한 점을 문자로 두어 나머지 꼭짓점의 좌표를 모두 같은 문자로 나타내고 정사각형의 두 변이 같다는 식을 세운다","단계":[{"제목":"세 꼭짓점의 좌표","힌트":"$\\mathrm{A}$ 의 $x$좌표를 $a$ 로 두면 $\\mathrm{D}$, $\\mathrm{C}$ 의 좌표는?","식":["$\\mathrm{A}(a,\\,a^2)$","$\\mathrm{D}(a,\\,9a^2)$","$\\mathrm{C}(3a,\\,9a^2)$"],"설명":"정사각형의 변은 축에 평행하므로 $\\mathrm{D}$ 는 $\\mathrm{A}$ 와 $x$좌표가 같고 $\\mathrm{C}$ 는 $\\mathrm{D}$ 와 $y$좌표가 같다. $\\mathrm{C}$ 가 $y=x^2$ 위의 제1사분면 점이므로 $x^2=9a^2$ 에서 $x=3a$ 이다.","확인":null,"스킬":"S4","고비":true},{"제목":"한 변이 같다는 식","힌트":"정사각형이므로 길이가 같은 두 변은?","식":["$\\overline{\\mathrm{AD}}=\\overline{\\mathrm{DC}}$","$9a^2-a^2=3a-a$","$8a^2-2a=0$"],"설명":"$\\overline{\\mathrm{AD}}$ 는 $y$좌표의 차이고 $\\overline{\\mathrm{DC}}$ 는 $x$좌표의 차이다.","확인":null,"스킬":"S4"},{"제목":"a 의 값","힌트":"$a>0$ 일 때 $8a^2-2a=0$ 의 해는?","식":["$8a\\left(a-\\frac{1}{4}\\right)=0$","$a=\\frac{1}{4}$"],"설명":"좌변을 인수분해하고 $a>0$ 인 해를 고른다.","확인":"1/4","스킬":"S4"},{"제목":"정사각형의 넓이","힌트":"정사각형의 한 변의 길이는?","식":["$2a=\\frac{1}{2}$","$\\left(\\frac{1}{2}\\right)^2=\\frac{1}{4}$"],"설명":"한 변의 길이는 $\\overline{\\mathrm{DC}}=3a-a=2a$ 이다.","확인":"1/4","스킬":"S4"}],"fb":"fig/ns/"},"ns-95c7d0f9b065":{"길":"작은 직사각형의 짧은 변과 긴 변을 문자로 두고 그림에서 읽은 길이 관계와 넓이로 식을 세운다","단계":[{"제목":"짧은 변과 긴 변의 관계","힌트":"$\\overline{\\mathrm{AD}}$ 의 길이를 윗줄과 아랫줄에서 각각 읽으면?","식":["$4x=3y$","$y=\\frac{4}{3}x$"],"설명":"작은 직사각형의 짧은 변을 $x$, 긴 변을 $y$ 라 한다. 그림에서 $\\overline{\\mathrm{AD}}$ 는 윗줄의 짧은 변 $4$개의 길이이고 $\\overline{\\mathrm{BC}}$ 는 아랫줄의 긴 변 $3$개의 길이이다.","확인":null,"스킬":"C7","고비":true},{"제목":"넓이로 식 세우기","힌트":"$\\overline{\\mathrm{AB}}$ 를 $x$, $y$ 로 나타내고 넓이를 식으로 쓰면?","식":["$\\overline{\\mathrm{AB}}=x+y$","$4x\\times\\left(x+\\frac{4}{3}x\\right)=189$"],"설명":"$\\overline{\\mathrm{AB}}$ 는 윗줄 직사각형의 긴 변과 아랫줄 직사각형의 짧은 변을 합한 길이이다.","확인":null,"스킬":"C7"},{"제목":"x 의 값","힌트":"$x$ 에 대한 이차방정식을 풀면?","식":["$\\frac{28}{3}x^2=189$","$x^2=\\frac{81}{4}$","$x=\\frac{9}{2}$"],"설명":"$x>0$ 이므로 양수인 해만 고른다.","확인":"9/2","스킬":"C7"},{"제목":"둘레의 길이","힌트":"$y$ 를 구한 뒤 작은 직사각형 하나의 둘레는?","식":["$y=\\frac{4}{3}\\times\\frac{9}{2}=6$","$2\\left(\\frac{9}{2}+6\\right)=21$"],"설명":"직사각형의 둘레는 (가로+세로)의 $2$ 배이다.","확인":"21","스킬":"C7"}],"fb":"fig/ns/"},"ns-9d47b2990d2d":{"길":"눈이 $1,2,3$ 나온 횟수를 문자로 두고 합계·평균·분산을 각각 식으로 세운 뒤 연립한다","단계":[{"제목":"횟수의 합","힌트":"$1,2,3$ 의 눈이 나온 횟수를 $a,b,c$ 라 할 때 전체 $19$번에서 알려진 횟수를 빼면?","식":["$a+b+c+1+2+4=19$","$a+b+c=12$"],"설명":"표에서 $4,5,6$ 의 눈은 각각 $1$번, $2$번, $4$번 나왔다.","확인":"12","스킬":"C7"},{"제목":"평균으로 세운 식","힌트":"눈의 수의 총합을 $a,b,c$ 로 나타내고 평균이 $3$ 임을 식으로 쓰면?","식":["$\\frac{a+2b+3c+4+10+24}{19}=3$","$a+2b+3c=19$"],"설명":"눈의 수의 총합은 눈의 수에 횟수를 곱해 더한 값이다.","확인":"19","스킬":"C7"},{"제목":"분산으로 세운 식","힌트":"표준편차가 $2$ 일 때 분산은? 눈마다 평균과의 차를 제곱해 횟수만큼 더하면?","식":["$\\frac{4a+b+0\\times c+1\\times 1+4\\times 2+9\\times 4}{19}=4$","$4a+b=31$"],"설명":"표준편차가 $2$ 이므로 분산은 $4$ 이다. 눈 $1,2,3,4,5,6$ 의 편차는 각각 $-2,-1,0,1,2,3$ 이고 편차의 제곱의 평균이 분산이다.","확인":"31","스킬":"C7","고비":true},{"제목":"2 의 눈이 나온 횟수","힌트":"세 식을 연립하면 $a,b,c$ 는?","식":["$a=7,\\ b=3,\\ c=2$"],"설명":"$4a+b=31$ 에서 $b=31-4a$ 이다. 이를 앞의 두 식에 대입하면 $c=3a-19$ 와 $-7a+3c=-43$ 을 얻고, 연립하면 $a=7$, $b=3$, $c=2$ 이다.","확인":"3","스킬":"A10"}],"fb":"fig/ns/"},"ns-9dfc89c2807a":{"길":"점 B 의 $x$좌표를 문자로 두어 두 선분의 길이를 나타내고 비례식으로 방정식을 세운다","단계":[{"제목":"세 점의 좌표","힌트":"$\\mathrm{B}$ 의 $x$좌표를 $a$ 로 두면 $\\mathrm{A}$ 와 $\\mathrm{C}$ 의 좌표는?","식":["$\\mathrm{B}(a,\\,a^2)$","$\\mathrm{A}(-a,\\,a^2)$","$\\mathrm{C}\\left(a,\\,-\\frac{1}{2}a^2\\right)$"],"설명":"$\\mathrm{A}$ 와 $\\mathrm{B}$ 는 $y$축에 대칭이므로 $y$좌표가 같고 $x$좌표의 부호가 반대이다. $\\mathrm{C}$ 는 $\\mathrm{B}$ 와 $x$좌표가 같다.","확인":null,"스킬":"S4"},{"제목":"두 선분의 길이","힌트":"$\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{BC}}$ 를 $a$ 로 나타내면?","식":["$\\overline{\\mathrm{AB}}=2a$","$\\overline{\\mathrm{BC}}=a^2-\\left(-\\frac{1}{2}a^2\\right)=\\frac{3}{2}a^2$"],"설명":"$\\overline{\\mathrm{AB}}$ 는 $x$좌표의 차이고 $\\overline{\\mathrm{BC}}$ 는 $y$좌표의 차이다.","확인":null,"스킬":"S4"},{"제목":"비례식으로 a 구하기","힌트":"$\\overline{\\mathrm{AB}}:\\overline{\\mathrm{BC}}=4:1$ 을 $a$ 에 대한 방정식으로 쓰면?","식":["$2a:\\frac{3}{2}a^2=4:1$","$6a^2=2a$","$a=\\frac{1}{3}$"],"설명":"내항의 곱과 외항의 곱이 같다. $a>0$ 이므로 $6a^2-2a=0$ 에서 $a=\\frac{1}{3}$ 이다.","확인":"1/3","스킬":"A8","고비":true}],"fb":"fig/ns/"},"ns-9f7c00358b55":{"길":"두 작은 반원의 반지름을 한 문자로 나타내고 색칠한 넓이를 큰 반원에서 두 작은 반원을 뺀 식으로 세운다","단계":[{"제목":"두 작은 반원의 반지름","힌트":"가장 작은 반원의 반지름을 $r$ 이라 하면 중간 크기의 반원의 반지름은?","식":["$15-r$"],"설명":"큰 반원의 지름이 $30\\ \\mathrm{cm}$ 이고 두 작은 반원의 지름의 합이 $30\\ \\mathrm{cm}$ 이므로 두 반지름의 합은 $15\\ \\mathrm{cm}$ 이다.","확인":null,"스킬":"C7"},{"제목":"색칠한 넓이로 식 세우기","힌트":"색칠한 부분의 넓이를 반원 세 개의 넓이로 나타내면?","식":["$\\frac{1}{2}\\pi\\times15^2-\\frac{1}{2}\\pi r^2-\\frac{1}{2}\\pi(15-r)^2=50\\pi$","$r^2-15r+50=0$"],"설명":"색칠한 넓이는 큰 반원의 넓이에서 두 작은 반원의 넓이를 뺀 값이다. 양변에 $\\frac{2}{\\pi}$ 를 곱해 정리한다.","확인":null,"스킬":"S12","고비":true},{"제목":"r 의 값","힌트":"이차방정식을 풀어 조건에 맞는 $r$ 을 고르면?","식":["$(r-5)(r-10)=0$","$r=5$"],"설명":"$r=10$ 이면 중간 크기 반원의 반지름이 $15-10=5$ 가 되어 가장 작은 반원이 아니게 되므로 $r=5$ 이다.","확인":"5","스킬":"S12"}],"fb":"fig/ns/"},"ns-a0ba8541b273":{"길":"점 P 의 좌표를 한 문자로 나타내 두 삼각형의 넓이를 식으로 쓰고 합의 최솟값을 완전제곱식으로 구한다","단계":[{"제목":"점 P 의 좌표","힌트":"직선 위의 점 $\\mathrm{P}$ 의 $x$좌표를 $a$ 로 두면 $y$좌표는? $\\mathrm{A}$, $\\mathrm{B}$ 의 좌표는?","식":["$\\mathrm{A}(0,12)$","$\\mathrm{B}(6,0)$","$\\mathrm{P}(a,\\,-2a+12)$"],"설명":"$x=0$ 일 때 $y=12$, $y=0$ 일 때 $x=6$ 이다. 제1사분면 위의 점이므로 $0<a<6$ 이다.","확인":null,"스킬":"G10"},{"제목":"두 삼각형의 넓이","힌트":"삼각형 $\\mathrm{ARP}$ 에서 밑변을 $\\overline{\\mathrm{AR}}$ 로 보면 높이는? 삼각형 $\\mathrm{PQB}$ 는?","식":["$\\triangle\\mathrm{ARP}=\\frac{1}{2}\\times 2a\\times a=a^2$","$\\triangle\\mathrm{PQB}=\\frac{1}{2}\\times(6-a)\\times(-2a+12)=(6-a)^2$"],"설명":"$\\mathrm{R}(0,\\,-2a+12)$ 이므로 $\\overline{\\mathrm{AR}}=12-(-2a+12)=2a$ 이고, $\\mathrm{Q}(a,0)$ 이므로 $\\overline{\\mathrm{QB}}=6-a$, $\\overline{\\mathrm{PQ}}=-2a+12$ 이다.","확인":null,"스킬":"G10","고비":true},{"제목":"넓이의 합의 최솟값","힌트":"두 넓이의 합을 $a$ 에 대한 이차식으로 쓰고 완전제곱식으로 고치면?","식":["$a^2+(6-a)^2=2a^2-12a+36$","$=2(a-3)^2+18$"],"설명":"$a=3$ 일 때 최솟값을 갖고, $3$ 은 $0<a<6$ 안에 있다.","확인":"18","스킬":"A6"}],"fb":"fig/ns/"},"ns-ab914fbe52ca":{"길":"점 $\\mathrm{B}$ 에서 $\\overline{\\mathrm{AD}}$ 의 연장선에 수선을 그어 닮은 직각삼각형을 만든 뒤 삼각비를 이어 쓴다","단계":[{"제목":"AD 의 길이","힌트":"직각삼각형 $\\mathrm{ACD}$ 에서 $\\sin x^\\circ$ 를 변의 비로 쓰면?","식":["$\\sin x^\\circ=\\frac{3}{\\overline{\\mathrm{AD}}}=\\frac{1}{3}$","$\\overline{\\mathrm{AD}}=9$"],"설명":"$x^\\circ$ 는 $\\angle\\mathrm{CAD}$ 이고 $\\overline{\\mathrm{CD}}=3$ 이 그 대변이다.","확인":"9","스킬":"S6"},{"제목":"보조선과 닮은 삼각형","힌트":"점 $\\mathrm{B}$ 에서 $\\overline{\\mathrm{AD}}$ 의 연장선에 수선을 내리면 닮은 삼각형이 생긴다. 어느 두 삼각형인가?","식":["$\\triangle\\mathrm{BDE}\\sim\\triangle\\mathrm{ADC}$"],"설명":"$\\mathrm{B}$ 에서 $\\overline{\\mathrm{AD}}$ 의 연장선에 내린 수선의 발을 $\\mathrm{E}$ 라 한다. $\\angle\\mathrm{BED}=\\angle\\mathrm{ACD}=90^\\circ$ 이고 $\\angle\\mathrm{BDE}=\\angle\\mathrm{ADC}$(맞꼭지각)이므로 $AA$ 닮음이다.","확인":null,"스킬":"S2","고비":true},{"제목":"DE 의 길이","힌트":"닮음에서 삼각형 $\\mathrm{BDE}$ 의 각 중 $x^\\circ$ 와 같은 것은? 그 사인을 쓰면?","식":["$\\sin x^\\circ=\\frac{\\overline{\\mathrm{DE}}}{3}=\\frac{1}{3}$","$\\overline{\\mathrm{DE}}=1$"],"설명":"닮음에서 $\\angle\\mathrm{DBE}=\\angle\\mathrm{DAC}=x^\\circ$ 이므로 직각삼각형 $\\mathrm{BDE}$ 에서 $\\sin x^\\circ=\\frac{\\overline{\\mathrm{DE}}}{\\overline{\\mathrm{BD}}}$ 이다.","확인":"1","스킬":"S6"},{"제목":"BE 와 AE 의 길이","힌트":"직각삼각형 $\\mathrm{BDE}$ 에서 $\\overline{\\mathrm{BE}}$ 는? $\\overline{\\mathrm{AE}}$ 는 $\\overline{\\mathrm{AD}}$ 와 $\\overline{\\mathrm{DE}}$ 의 합이다.","식":["$\\overline{\\mathrm{BE}}=\\sqrt{3^2-1^2}=2\\sqrt{2}$","$\\overline{\\mathrm{AE}}=9+1=10$"],"설명":"$\\mathrm{E}$ 는 $\\overline{\\mathrm{AD}}$ 의 연장선 위에 있다.","확인":null,"스킬":"S3"},{"제목":"tan y 의 값","힌트":"직각삼각형 $\\mathrm{ABE}$ 에서 $y^\\circ$ 의 탄젠트는?","식":["$\\tan y^\\circ=\\frac{\\overline{\\mathrm{BE}}}{\\overline{\\mathrm{AE}}}=\\frac{2\\sqrt{2}}{10}=\\frac{\\sqrt{2}}{5}$"],"설명":"$y^\\circ$ 는 $\\angle\\mathrm{BAD}$ 이고 $\\mathrm{E}$ 가 $\\overline{\\mathrm{AD}}$ 의 연장선 위에 있으므로 $\\angle\\mathrm{BAE}$ 와 같다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-aebecf38cc82":{"길":"정오각형의 각을 따라가 두 이등변삼각형에서 같은 길이를 찾고 주어진 비로 $\\overline{\\mathrm{BP}}$ 를 구한다","단계":[{"제목":"삼각형 ABP 는 이등변삼각형","힌트":"정오각형의 한 내각을 이용해 $\\angle\\mathrm{BAC}$, $\\angle\\mathrm{ABE}$ 는 각각?","식":["$\\angle\\mathrm{BAC}=\\angle\\mathrm{ABE}=36^\\circ$","$\\overline{\\mathrm{PA}}=\\overline{\\mathrm{PB}}$"],"설명":"정오각형의 한 내각은 $108^\\circ$ 이다. $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{BC}}$, $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AE}}$ 이므로 $\\angle\\mathrm{BAC}=\\angle\\mathrm{ABE}=\\frac{180^\\circ-108^\\circ}{2}=36^\\circ$ 이다. 따라서 $\\triangle\\mathrm{ABP}$ 는 $\\overline{\\mathrm{PA}}=\\overline{\\mathrm{PB}}$ 인 이등변삼각형이다.","확인":null,"스킬":"S10"},{"제목":"PC 의 길이","힌트":"삼각형 $\\mathrm{CBP}$ 의 두 각 $\\angle\\mathrm{CBP}$, $\\angle\\mathrm{CPB}$ 는 각각?","식":["$\\angle\\mathrm{CBP}=108^\\circ-36^\\circ=72^\\circ$","$\\angle\\mathrm{CPB}=36^\\circ+36^\\circ=72^\\circ$","$\\overline{\\mathrm{PC}}=\\overline{\\mathrm{CB}}=2$"],"설명":"$\\angle\\mathrm{CPB}$ 는 $\\triangle\\mathrm{ABP}$ 의 한 외각이므로 이웃하지 않는 두 내각의 합과 같다. 두 각이 같으므로 $\\overline{\\mathrm{CP}}=\\overline{\\mathrm{CB}}$ 이다.","확인":"2","스킬":"S10","고비":true},{"제목":"BP 구하기","힌트":"$\\overline{\\mathrm{BP}}=x$ 라 하면 $\\overline{\\mathrm{AP}}$ 는? 주어진 비로 식을 세우면?","식":["$x:2=1:\\frac{1+\\sqrt{5}}{2}$","$x=\\frac{4}{1+\\sqrt{5}}=\\sqrt{5}-1$"],"설명":"$\\overline{\\mathrm{AP}}=\\overline{\\mathrm{BP}}=x$ 이고 $\\overline{\\mathrm{PC}}=2$ 이므로 $\\overline{\\mathrm{AP}}:\\overline{\\mathrm{PC}}=x:2$ 이다. 분모를 유리화한다.","확인":null,"스킬":"A8"}],"fb":"fig/ns/"},"ns-b5387f5cee1e":{"길":"평행사변형의 성질로 점 $\\mathrm{B}$ 의 좌표를 한 문자로 나타내고 $y$좌표의 절댓값이 같다는 조건을 식으로 쓴다","단계":[{"제목":"A, D 의 좌표","힌트":"$\\mathrm{A}$, $\\mathrm{D}$ 는 $y=2x^2$ 위의 점이고 $\\overline{\\mathrm{AD}}$ 가 $x$축에 평행하다. $\\mathrm{A}$ 의 $x$좌표를 $-k$ 로 두면 $\\mathrm{D}$ 의 좌표는?","식":["$\\mathrm{A}(-k,\\,2k^2)$","$\\mathrm{D}(k,\\,2k^2)$"],"설명":"$\\overline{\\mathrm{AD}}$ 가 $x$축에 평행하므로 두 점의 $y$좌표가 같고, $y=2x^2$ 은 $y$축에 대칭이므로 $x$좌표는 부호만 반대이다. 그림에서 $\\mathrm{A}$ 가 $y$축 왼쪽에 있으므로 $k>0$ 이다.","확인":null,"스킬":"S4"},{"제목":"B 의 좌표","힌트":"평행사변형에서 $\\overline{\\mathrm{BC}}$ 와 $\\overline{\\mathrm{AD}}$ 의 관계는? $\\mathrm{C}$ 는 $y$축 위의 점이다.","식":["$\\overline{\\mathrm{BC}}=\\overline{\\mathrm{AD}}=2k$","$\\mathrm{B}(-2k,\\,4ak^2)$"],"설명":"$\\overline{\\mathrm{BC}}\\parallel\\overline{\\mathrm{AD}}$ 이고 길이가 같으므로 $\\overline{\\mathrm{BC}}$ 도 $x$축에 평행하다. $\\mathrm{C}$ 의 $x$좌표가 $0$ 이므로 $\\mathrm{B}$ 의 $x$좌표는 $-2k$ 이고, $y=ax^2$ 위의 점이므로 $y$좌표는 $a(-2k)^2=4ak^2$ 이다.","확인":null,"스킬":"S4","고비":true},{"제목":"a 의 값","힌트":"$\\mathrm{A}$, $\\mathrm{B}$ 의 $y$좌표의 절댓값이 같을 때 $\\mathrm{B}$ 의 $y$좌표의 부호는?","식":["$-2k^2=4ak^2$","$a=-\\frac{1}{2}$"],"설명":"$\\mathrm{B}$ 가 $\\mathrm{A}$ 와 같은 높이에 있으면 네 점이 한 직선 위에 놓여 평행사변형이 되지 않으므로 $\\mathrm{B}$ 의 $y$좌표는 $-2k^2$ 이다. 양변을 $4k^2$ 으로 나눈다.","확인":"-1/2","스킬":"S4"}],"fb":"fig/ns/"},"ns-b790d0202772":{"길":"한 점을 문자로 두어 나머지 꼭짓점의 좌표를 같은 문자로 나타내고 정사각형의 두 변이 같다는 식을 세운다","단계":[{"제목":"세 꼭짓점의 좌표","힌트":"$\\mathrm{A}$ 의 좌표를 $(a,\\,a^2)$ 이라 하면 $\\mathrm{D}$, $\\mathrm{C}$ 의 좌표는?","식":["$\\mathrm{D}(a,\\,9a^2)$","$\\mathrm{C}(3a,\\,9a^2)$"],"설명":"각 변이 축에 평행하므로 $\\mathrm{D}$ 는 $\\mathrm{A}$ 와 $x$좌표가 같고 $\\mathrm{C}$ 는 $\\mathrm{D}$ 와 $y$좌표가 같다. $\\mathrm{C}$ 가 $y=x^2$ 위의 제1사분면 점이므로 $x^2=9a^2$ 에서 $x=3a$ 이다.","확인":null,"스킬":"S4","고비":true},{"제목":"한 변이 같다는 식","힌트":"정사각형에서 $\\overline{\\mathrm{AD}}$ 와 길이가 같은 변은?","식":["$\\overline{\\mathrm{AD}}=\\overline{\\mathrm{CD}}$","$9a^2-a^2=3a-a$","$8a^2-2a=0$"],"설명":"$\\overline{\\mathrm{AD}}$ 는 $y$좌표의 차이고 $\\overline{\\mathrm{CD}}$ 는 $x$좌표의 차이다.","확인":null,"스킬":"S4"},{"제목":"a 의 값","힌트":"$a>0$ 일 때 $8a^2-2a=0$ 의 해는?","식":["$8a\\left(a-\\frac{1}{4}\\right)=0$","$a=\\frac{1}{4}$"],"설명":"좌변을 인수분해하고 $a>0$ 인 해를 고른다.","확인":"1/4","스킬":"S4"},{"제목":"둘레의 길이","힌트":"한 변의 길이를 구하면 정사각형의 둘레는?","식":["$2a=\\frac{1}{2}$","$4\\times\\frac{1}{2}=2$"],"설명":"한 변의 길이는 $\\overline{\\mathrm{CD}}=3a-a=2a$ 이다.","확인":"2","스킬":"S4"}],"fb":"fig/ns/"},"ns-ba286031db1e":{"길":"바닥의 가로와 세로를 비를 이용해 한 문자로 나타내 넓이로 방정식을 풀고, 접은 높이를 양쪽에 더해 종이의 크기를 구한다","단계":[{"제목":"바닥의 길이를 나타내는 문자","힌트":"가로와 세로의 비가 $4:3$ 이므로 한 문자로 쓰고 넓이 $432$ 로 식을 세우면?","식":["$4a\\times 3a=432$","$a^2=36$","$a=6$"],"설명":"바닥의 가로를 $4a$, 세로를 $3a$ 라 하면 $12a^2=432$ 이다. $a>0$ 이므로 $a=6$ 이다.","확인":"6","스킬":"C7","고비":true},{"제목":"바닥의 가로와 세로","힌트":"$a=6$ 을 대입하면 바닥의 가로와 세로는?","식":["$4a=24$","$3a=18$"],"설명":"가로는 $4a$, 세로는 $3a$ 에 $a=6$ 을 대입한다.","확인":null,"스킬":"C7"},{"제목":"종이의 가로와 세로","힌트":"네 모퉁이에서 $5\\ \\mathrm{cm}$ 씩 오려내 접었으므로 가로와 세로 각각 양쪽에 얼마씩 더해지는가?","식":["$24+5+5=34$","$18+5+5=28$"],"설명":"상자 바닥의 가로와 세로 양쪽에 접은 높이 $5\\ \\mathrm{cm}$ 가 하나씩 붙어 있다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-bd55ac8eb5c4":{"길":"축에 대한 대칭으로 직사각형의 네 꼭짓점을 한 문자로 나타내 둘레를 이차식으로 만들고 완전제곱식으로 최댓값을 구한다","단계":[{"제목":"b 의 값","힌트":"$y=-x^2+bx$ 의 축의 방정식을 $b$ 로 나타내면?","식":["$x=\\frac{b}{2}=5$","$b=10$"],"설명":"$y=-x^2+bx=-\\left(x-\\frac{b}{2}\\right)^2+\\frac{b^2}{4}$ 이므로 축은 $x=\\frac{b}{2}$ 이다.","확인":"10","스킬":"A6"},{"제목":"네 꼭짓점의 좌표","힌트":"$\\mathrm{B}$ 의 $x$좌표를 $k$ 로 두면 $\\mathrm{A}$ 의 좌표는? $\\mathrm{D}$, $\\mathrm{C}$ 는 축 $x=5$ 에 대해 $\\mathrm{A}$, $\\mathrm{B}$ 와 어떤 관계인가?","식":["$\\mathrm{A}(k,\\,-k^2+10k)$","$\\mathrm{D}(10-k,\\,-k^2+10k)$","$\\mathrm{C}(10-k,\\,0)$"],"설명":"$\\mathrm{B}(k,0)$ 으로 두면 $\\mathrm{A}$ 는 $y=-x^2+10x$ 위의 점이다. $\\mathrm{D}$, $\\mathrm{C}$ 는 $\\mathrm{A}$, $\\mathrm{B}$ 와 축 $x=5$ 에 대칭이므로 $x$좌표가 $10-k$ 이다.","확인":null,"스킬":"G11","고비":true},{"제목":"둘레의 식","힌트":"$\\overline{\\mathrm{BC}}$ 와 $\\overline{\\mathrm{AB}}$ 를 $k$ 로 나타내면?","식":["$\\overline{\\mathrm{BC}}=10-2k$","$\\overline{\\mathrm{AB}}=-k^2+10k$","$l=2(10-2k-k^2+10k)=-2k^2+16k+20$"],"설명":"직사각형 $\\mathrm{ABCD}$ 의 둘레의 길이를 $l$ 이라 한다. 둘레는 (가로+세로)의 $2$ 배이다.","확인":null,"스킬":"S4"},{"제목":"둘레의 최댓값","힌트":"$l$ 을 완전제곱식으로 고치면?","식":["$l=-2(k-4)^2+52$"],"설명":"$k=4$ 일 때 최대이다. $0<k<5$ 이므로 $k=4$ 는 범위 안에 있다.","확인":"52","스킬":"A6"}],"fb":"fig/ns/"},"ns-bfbf9bf84671":{"길":"접은 각과 엇각으로 삼각형 $\\mathrm{BPQ}$ 가 이등변삼각형임을 찾고 수선을 그어 직각삼각형의 삼각비로 바꾼다","단계":[{"제목":"이등변삼각형 BPQ","힌트":"접은 각과 엇각 사이의 관계로 삼각형 $\\mathrm{BPQ}$ 에서 크기가 같은 두 각을 찾으면?","식":["$\\angle\\mathrm{BPQ}=\\angle\\mathrm{PQB}=x$","$\\overline{\\mathrm{BP}}=\\overline{\\mathrm{BQ}}$"],"설명":"접은 각이므로 $\\angle\\mathrm{DPQ}=\\angle\\mathrm{BPQ}$ 이고, $\\overline{\\mathrm{AD}}\\parallel\\overline{\\mathrm{BC}}$ 이므로 $\\angle\\mathrm{DPQ}=\\angle\\mathrm{PQB}$(엇각)이다.","확인":null,"스킬":"S10","고비":true},{"제목":"BP 와 BQ 의 길이","힌트":"접으면 $\\mathrm{D}$ 가 $\\mathrm{B}$ 로 옮겨지므로 $\\overline{\\mathrm{BP}}$ 와 같은 선분은?","식":["$\\overline{\\mathrm{BP}}=\\overline{\\mathrm{PD}}=10$","$\\overline{\\mathrm{BQ}}=\\overline{\\mathrm{BP}}=10$"],"설명":"그림에서 $\\overline{\\mathrm{PD}}=10$ 이다.","확인":"10","스킬":"S10"},{"제목":"수선을 그어 HQ 구하기","힌트":"점 $\\mathrm{P}$ 에서 $\\overline{\\mathrm{BQ}}$ 에 수선을 내리면 $\\overline{\\mathrm{PH}}$, $\\overline{\\mathrm{BH}}$ 는?","식":["$\\overline{\\mathrm{PH}}=\\overline{\\mathrm{AB}}=6$","$\\overline{\\mathrm{BH}}=\\sqrt{10^2-6^2}=8$","$\\overline{\\mathrm{HQ}}=10-8=2$"],"설명":"점 $\\mathrm{P}$ 에서 $\\overline{\\mathrm{BQ}}$ 에 내린 수선의 발을 $\\mathrm{H}$ 라 한다. 사각형 $\\mathrm{ABHP}$ 는 직사각형이므로 $\\overline{\\mathrm{PH}}=\\overline{\\mathrm{AB}}=\\overline{\\mathrm{CD}}=6$ 이다.","확인":"2","스킬":"S2"},{"제목":"cos x 의 값","힌트":"직각삼각형 $\\mathrm{PHQ}$ 에서 $\\overline{\\mathrm{PQ}}$ 를 구하고 $\\cos x$ 를 변의 비로 쓰면?","식":["$\\overline{\\mathrm{PQ}}=\\sqrt{6^2+2^2}=2\\sqrt{10}$","$\\cos x=\\frac{\\overline{\\mathrm{QH}}}{\\overline{\\mathrm{PQ}}}=\\frac{2}{2\\sqrt{10}}=\\frac{\\sqrt{10}}{10}$"],"설명":"$\\angle\\mathrm{PQH}=\\angle\\mathrm{PQB}=x$ 이므로 직각삼각형 $\\mathrm{PHQ}$ 에서 $\\cos x=\\frac{\\overline{\\mathrm{QH}}}{\\overline{\\mathrm{PQ}}}$ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-c552d9166cbf":{"길":"그래프에서 이차함수의 식을 구하고 점 $\\mathrm{P}$ 를 한 문자로 두어 $\\overline{\\mathrm{PQ}}$ 를 이차식으로 나타낸 뒤 완전제곱식으로 최솟값을 구한다","단계":[{"제목":"이차함수의 식","힌트":"꼭짓점 $(1,0)$ 과 점 $(0,-1)$ 로 식을 세우면?","식":["$y=a(x-1)^2$","$-1=a\\times(0-1)^2$","$y=-(x-1)^2$"],"설명":"그림에서 꼭짓점이 $(1,0)$ 이고 점 $(0,-1)$ 을 지난다.","확인":null,"스킬":"S4"},{"제목":"PQ 를 k 의 식으로","힌트":"$\\mathrm{P}$ 의 $x$좌표를 $k$ 로 두면 $\\mathrm{P}$, $\\mathrm{Q}$ 의 좌표는? $\\overline{\\mathrm{PQ}}$ 는 $y$좌표의 차이다.","식":["$\\mathrm{P}(k,\\,k)$","$\\mathrm{Q}(k,\\,-(k-1)^2)$","$\\overline{\\mathrm{PQ}}=k+(k-1)^2=k^2-k+1$"],"설명":"$\\mathrm{P}$ 는 직선 $y=x$ 위에 있고 $\\mathrm{Q}$ 는 같은 $x$좌표를 가진 포물선 위의 점이다. $\\overline{\\mathrm{PQ}}$ 는 두 점의 $y$좌표의 차이다.","확인":null,"스킬":"S4","고비":true},{"제목":"PQ 의 최솟값","힌트":"$k^2-k+1$ 을 완전제곱식으로 고치면?","식":["$\\overline{\\mathrm{PQ}}=\\left(k-\\frac{1}{2}\\right)^2+\\frac{3}{4}$"],"설명":"$k=\\frac{1}{2}$ 일 때 최솟값 $\\frac{3}{4}$ 을 갖는다.","확인":"3/4","스킬":"A6"}],"fb":"fig/ns/"},"ns-cab2be7208fc":{"길":"포물선이 직사각형과 두 점에서 만나는 a의 경계를 꼭짓점에서 찾는다.","단계":[{"제목":"점 $A$를 지날 때의 $a$","힌트":"그림에서 점 $A$의 좌표를 읽어 $y=ax^2$에 넣으면 $a$는 얼마인가?","식":["$4=a\\times1^2$","$a=4$"],"설명":"점 $A$의 좌표는 $(1,4)$이다. 이 값을 $y=ax^2$에 대입하면 그래프가 $A$를 지날 때의 $a$가 나온다.","확인":"4","스킬":"G1"},{"제목":"점 $C$를 지날 때의 $a$","힌트":"점 $C$의 좌표를 $y=ax^2$에 넣으면 $a$는 얼마인가?","식":["$2=a\\times4^2$","$a=\\frac{1}{8}$"],"설명":"점 $C$의 좌표는 $(4,2)$이다.","확인":"1/8","스킬":"G1"},{"제목":"두 경계 사이의 범위","힌트":"$a$가 두 경계값 사이에 있을 때만 서로 다른 두 점에서 만나는 까닭은 무엇인가?","식":["$\\frac{1}{8}<a<4$"],"설명":"$a=\\frac{1}{8}$이면 점 $C$ 한 점에서만 만나고 더 작으면 만나지 않는다. $a=4$이면 점 $A$ 한 점에서만 만나고 더 크면 만나지 않는다. 두 값 사이에서는 직사각형의 둘레와 두 점에서 만난다.","확인":null,"스킬":"G1","고비":true},{"제목":"범위 안의 정수의 합","힌트":"범위에 속하는 정수를 모두 더하면?","식":["$1+2+3=6$"],"설명":"범위의 양 끝값은 포함되지 않는다. 정수는 $1$, $2$, $3$이다.","확인":"6","스킬":"G1"}],"fb":"fig/ns/"},"ns-cd376711e8e8":{"길":"점의 좌표를 구하고 오각형을 사다리꼴과 삼각형으로 나누어 넓이를 더한다.","단계":[{"제목":"점 $B$, $E$의 좌표","힌트":"높이가 $8$인 점의 $x$좌표는 포물선의 식에서 얼마인가?","식":["$8=\\frac{1}{2}x^2$","$x=\\pm4$","$B(-4,8),\\ E(4,8)$"],"설명":"$B$, $E$의 $y$좌표가 $8$이므로 식에 넣으면 $x^2=16$이다. $B$가 왼쪽, $E$가 오른쪽에 있다.","확인":null,"스킬":"G10"},{"제목":"점 $C$, $D$의 좌표","힌트":"$\\overline{CD}=\\overline{AE}$이고 $C$, $D$가 $y$축에 대칭일 때 $x$좌표는?","식":["$\\overline{CD}=\\overline{AE}=4$","$C(-2,2),\\ D(2,2)$"],"설명":"$C$, $D$는 $y$축에 대칭이므로 $x$좌표는 $-2$, $2$이다. $y=\\frac{1}{2}\\times2^2=2$이다.","확인":null,"스킬":"G10"},{"제목":"오각형을 나누어 넓이 구하기","힌트":"오각형 $BCODE$는 어떤 두 도형으로 나뉘는가?","식":["$\\square BCDE=\\frac{1}{2}\\times(8+4)\\times6=36$","$\\triangle OCD=\\frac{1}{2}\\times4\\times2=4$","$36+4=40$"],"설명":"$\\overline{BE}=8$, $\\overline{CD}=4$이고 높이가 $8-2=6$인 사다리꼴 $BCDE$와, 밑변 $4$, 높이 $2$인 삼각형 $OCD$로 나눈다.","확인":"40","스킬":"S12","고비":true}],"fb":"fig/ns/"},"ns-dc60e88140b0":{"길":"정사면체의 높이로 부피를 구하고, 같은 삼각뿔을 다른 면을 밑면으로 보아 높이 $MH$를 구한다.","단계":[{"제목":"$\\overline{OM}$, $\\overline{CM}$의 길이","힌트":"정삼각형 $OAB$, $ABC$에서 중선 $OM$, $CM$의 길이는?","식":["$\\overline{OM}=\\overline{CM}=\\frac{\\sqrt{3}}{2}\\times\\sqrt{3}=\\frac{3}{2}$"],"설명":"한 변이 $\\sqrt{3}$인 정삼각형의 높이는 $\\frac{\\sqrt{3}}{2}\\times\\sqrt{3}$이고, 변의 중점을 지나는 중선은 높이와 같다.","확인":"3/2","스킬":"S3"},{"제목":"정사면체의 높이","힌트":"꼭짓점 $O$에서 면 $ABC$에 내린 수선의 발 $H'$은 삼각형 $ABC$의 어디에 있는가?","식":["$\\overline{MH'}=\\frac{1}{3}\\overline{MC}=\\frac{1}{2}$","$\\overline{OH'}=\\sqrt{\\left(\\frac{3}{2}\\right)^2-\\left(\\frac{1}{2}\\right)^2}=\\sqrt{2}$"],"설명":"$O$에서 면 $ABC$에 내린 수선의 발을 $H'$이라 하면 $H'$은 정삼각형 $ABC$의 무게중심이다. 무게중심은 중선 $CM$을 $2:1$로 나누므로 $\\overline{MH'}=\\frac{1}{3}\\overline{MC}$이다. 직각삼각형 $OMH'$에서 높이 $\\overline{OH'}$를 구한다.","확인":null,"스킬":"S3"},{"제목":"삼각뿔 $O$-$MBC$의 부피","힌트":"삼각형 $MBC$의 넓이는 삼각형 $ABC$ 넓이의 몇 분의 몇인가?","식":["$V=\\frac{1}{2}\\times\\left\\{\\frac{1}{3}\\times\\frac{\\sqrt{3}}{4}\\times(\\sqrt{3})^2\\times\\sqrt{2}\\right\\}=\\frac{\\sqrt{6}}{8}$"],"설명":"$M$이 $\\overline{AB}$의 중점이므로 삼각형 $MBC$의 넓이는 삼각형 $ABC$의 $\\frac{1}{2}$이다. 높이 $\\overline{OH'}$가 같으므로 삼각뿔 $O$-$MBC$의 부피는 정사면체 부피의 $\\frac{1}{2}$이다.","확인":null,"스킬":"S8"},{"제목":"같은 삼각뿔을 밑면 $OBC$로 보기","힌트":"삼각뿔 $M$-$OBC$는 삼각뿔 $O$-$MBC$와 같은 입체이다. 밑면을 $OBC$로 보면 높이는 무엇인가?","식":["$\\frac{1}{3}\\times\\frac{\\sqrt{3}}{4}\\times(\\sqrt{3})^2\\times\\overline{MH}=\\frac{\\sqrt{6}}{8}$","$\\overline{MH}=\\frac{\\sqrt{2}}{2}$"],"설명":"$M$에서 면 $OBC$에 내린 수선 $MH$가 이 삼각뿔의 높이이다. 부피를 두 방법으로 세어 $\\overline{MH}$를 구한다.","확인":null,"스킬":"S8","고비":true},{"제목":"$\\cos x^\\circ$ 구하기","힌트":"$\\angle OMH=x^\\circ$인 직각삼각형에서 $\\cos x^\\circ$는 어느 두 변의 비인가?","식":["$\\cos x^\\circ=\\frac{\\overline{MH}}{\\overline{OM}}=\\frac{\\frac{\\sqrt{2}}{2}}{\\frac{3}{2}}=\\frac{\\sqrt{2}}{3}$"],"설명":"$\\overline{MH}$는 면 $OBC$에 수직이므로 $\\angle MHO=90^\\circ$이고, 직각삼각형 $OMH$에서 $\\overline{OM}$이 빗변이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-debdff32be23":{"길":"점 $B$의 좌표를 한 문자로 두고 두 선분의 길이의 비를 식으로 쓴다.","단계":[{"제목":"세 점의 좌표","힌트":"$B$의 $x$좌표를 $a$라 하면 $A$, $C$의 좌표는?","식":["$A(-a,a^2),\\ B(a,a^2),\\ C\\left(a,-\\frac{1}{4}a^2\\right)$"],"설명":"$A$와 $B$는 $y$축에 대칭이므로 $y$좌표가 같고 $x$좌표는 부호만 다르다. $C$는 $B$와 $x$좌표가 같고 곡선 $y=-\\frac{1}{4}x^2$ 위에 있다.","확인":null,"스킬":"G10"},{"제목":"두 선분의 길이","힌트":"$\\overline{AB}$는 $x$좌표의 차, $\\overline{BC}$는 $y$좌표의 차이다. 각각 $a$로 나타내면?","식":["$\\overline{AB}=2a$","$\\overline{BC}=a^2-\\left(-\\frac{1}{4}a^2\\right)=\\frac{5}{4}a^2$"],"설명":"$A$, $B$는 $y$좌표가 같고 $B$, $C$는 $x$좌표가 같다.","확인":null,"스킬":"G10"},{"제목":"비례식으로 $a$ 구하기","힌트":"비례식에서 내항의 곱과 외항의 곱이 같음을 쓰면 $a$에 대한 어떤 식이 되는가?","식":["$2a:\\frac{5}{4}a^2=4:5$","$5a^2=10a$","$a=2$"],"설명":"$a>0$이므로 $a$로 나누어 풀 수 있다.","확인":"2","스킬":"A8","고비":true},{"제목":"점 $A$의 좌표","힌트":"$A$의 $x$좌표는 $-a$이다. $y$좌표는?","식":["$A(-2,4)$"],"설명":"$a=2$를 $A(-a,a^2)$에 넣는다.","확인":null,"스킬":"G10"}],"fb":"fig/ns/"},"ns-e1b566407fe0":{"길":"한 점의 좌표를 문자로 두고, 대칭으로 나머지 점을 구해 둘레를 식으로 쓴다.","단계":[{"제목":"네 점의 좌표","힌트":"점 $B$의 $x$좌표를 $a$라 하면 점 $A$, $D$의 좌표는?","식":["$B\\left(a,\\frac{3}{2}a^2\\right)$","$A\\left(-a,\\frac{3}{2}a^2\\right),\\ D(a,0)$"],"설명":"$A$, $B$는 포물선 위에서 $y$축에 대칭이고, $D$는 $B$의 바로 아래 $x$축 위의 점이다.","확인":null,"스킬":"C7"},{"제목":"둘레의 길이로 식 세우기","힌트":"$\\overline{AB}$, $\\overline{BD}$를 $a$로 나타내고 둘레 $4$로 식을 세우면?","식":["$\\overline{AB}=2a,\\ \\overline{BD}=\\frac{3}{2}a^2$","$2\\left(2a+\\frac{3}{2}a^2\\right)=4$","$3a^2+4a-4=0$"],"설명":"직사각형의 둘레는 이웃한 두 변의 합의 $2$배이다.","확인":null,"스킬":"C7","고비":true},{"제목":"$a$ 구하기","힌트":"인수분해하여 $a>0$인 해를 고르면?","식":["$(3a-2)(a+2)=0$","$a=\\frac{2}{3}$"],"설명":"$a>0$이므로 $a+2>0$이다.","확인":"2/3","스킬":"C7"},{"제목":"직사각형의 넓이","힌트":"$\\overline{AB}$, $\\overline{BD}$의 길이는?","식":["$\\overline{AB}=\\frac{4}{3},\\ \\overline{BD}=\\frac{2}{3}$","$\\frac{4}{3}\\times\\frac{2}{3}=\\frac{8}{9}$"],"설명":"$a=\\frac{2}{3}$을 두 변의 길이에 넣는다.","확인":"8/9","스킬":"G10"}],"fb":"fig/ns/"},"ns-e41b10a56584":{"길":"색칠한 부분을 큰 반원에서 작은 두 반원을 뺀 넓이로 보고, $\\overline{AC}$를 문자로 놓아 식을 세운다.","단계":[{"제목":"반지름을 문자로 놓기","힌트":"$\\overline{AC}=2x$라 하면 $\\overline{BC}$와 두 반원의 반지름은?","식":["$\\overline{AC}=2x,\\ \\overline{BC}=12-2x$","$x>3$"],"설명":"지름이 $2x$, $12-2x$인 반원의 반지름은 $x$, $6-x$이다. $\\overline{AC}>\\overline{BC}$에서 $x>3$이다.","확인":null,"스킬":"C7"},{"제목":"넓이로 식 세우기","힌트":"색칠한 부분은 큰 반원에서 어떤 도형을 빼면 되는가?","식":["$\\frac{1}{2}\\pi\\times6^2-\\frac{1}{2}\\pi x^2-\\frac{1}{2}\\pi(6-x)^2=\\frac{27}{4}\\pi$","$4x^2-24x+27=0$"],"설명":"반지름이 $r$인 반원의 넓이는 $\\frac{1}{2}\\pi r^2$이다. 양변을 $\\pi$로 나누어 정리한다.","확인":null,"스킬":"S12","고비":true},{"제목":"$x$ 구하기","힌트":"인수분해하고 $x>3$인 해를 고르면?","식":["$(2x-9)(2x-3)=0$","$x=\\frac{9}{2}$"],"설명":"$x=\\frac{3}{2}$은 $x>3$에 맞지 않는다.","확인":"9/2","스킬":"C7"},{"제목":"$\\overline{AC}$의 길이","힌트":"$\\overline{AC}=2x$에 $x$를 넣으면?","식":["$\\overline{AC}=2x=9$"],"설명":"단위는 $\\mathrm{cm}$이다.","확인":"9","스킬":"C7"}],"fb":"fig/ns/"},"ns-e5107c4d8dab":{"길":"$75^\\circ$를 직각삼각형 $ABC$의 한 예각으로 만들고, 여러 직각삼각형에서 삼각비로 변의 길이를 이어 구한다.","단계":[{"제목":"$\\angle ABC=75^\\circ$ 확인","힌트":"$\\angle EBD$의 크기와 $\\angle ABE$를 더하면?","식":["$\\angle EBD=90^\\circ-60^\\circ=30^\\circ$","$\\angle ABC=45^\\circ+30^\\circ=75^\\circ$"],"설명":"삼각형 $BED$에서 $\\angle D=90^\\circ$, $\\angle BED=60^\\circ$이다. 직각삼각형 $ABC$에서 $\\sin75^\\circ=\\frac{\\overline{AC}}{\\overline{AB}}$이므로 $\\overline{AC}$, $\\overline{AB}$를 구하면 된다.","확인":null,"스킬":"S10"},{"제목":"$\\overline{AB}$, $\\overline{BE}$ 구하기","힌트":"삼각형 $ABE$에서 $\\overline{AE}=2$, $\\angle ABE=45^\\circ$이다. 빗변 $AB$와 $\\overline{BE}$는?","식":["$\\overline{AB}=\\frac{2}{\\sin45^\\circ}=2\\sqrt{2}$","$\\overline{BE}=2\\tan45^\\circ=2$"],"설명":"삼각형 $ABE$는 $\\angle AEB=90^\\circ$인 직각삼각형이다.","확인":null,"스킬":"S6"},{"제목":"$\\overline{AC}$를 두 부분으로 나누기","힌트":"$\\overline{AC}=\\overline{AF}+\\overline{FC}$에서 $\\overline{AF}$는 어느 직각삼각형에서 구하는가?","식":["$\\overline{AF}=2\\sin60^\\circ=\\sqrt{3}$","$\\overline{FC}=\\overline{ED}=\\overline{BE}\\cos60^\\circ=1$","$\\overline{AC}=\\sqrt{3}+1$"],"설명":"$\\angle FEB=90^\\circ-60^\\circ=30^\\circ$이므로 $\\angle AEF=90^\\circ-30^\\circ=60^\\circ$이다. 직각삼각형 $AEF$에서 $\\overline{AF}$를 구한다. 직사각형 $CDEF$에서 $\\overline{FC}=\\overline{ED}$이다.","확인":null,"스킬":"S6","고비":true},{"제목":"$\\sin75^\\circ$ 구하기","힌트":"직각삼각형 $ABC$에서 $\\sin75^\\circ$를 두 변의 비로 쓰면?","식":["$\\sin75^\\circ=\\frac{\\sqrt{3}+1}{2\\sqrt{2}}=\\frac{\\sqrt{6}+\\sqrt{2}}{4}$"],"설명":"분모의 근호를 없애려고 분자와 분모에 $\\sqrt{2}$를 곱한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-e5484a89bb8b":{"길":"점 $B$의 좌표를 한 문자로 두고 두 선분의 길이의 비를 식으로 쓴 뒤 넓이를 구한다.","단계":[{"제목":"세 점의 좌표","힌트":"$B$의 $x$좌표를 $a$라 하면 $A$, $C$의 좌표는?","식":["$A(-a,a^2),\\ B(a,a^2),\\ C\\left(a,-\\frac{1}{2}a^2\\right)$"],"설명":"$A$와 $B$는 $y$축에 대칭이므로 $y$좌표가 같고 $x$좌표는 부호만 다르다. $C$는 $B$와 $x$좌표가 같고 곡선 $y=-\\frac{1}{2}x^2$ 위에 있다.","확인":null,"스킬":"G10"},{"제목":"두 선분의 길이","힌트":"$\\overline{AB}$는 $x$좌표의 차, $\\overline{BC}$는 $y$좌표의 차이다. 각각 $a$로 나타내면?","식":["$\\overline{AB}=2a$","$\\overline{BC}=a^2-\\left(-\\frac{1}{2}a^2\\right)=\\frac{3}{2}a^2$"],"설명":"$A$, $B$는 $y$좌표가 같고 $B$, $C$는 $x$좌표가 같다.","확인":null,"스킬":"G10"},{"제목":"비례식으로 $a$ 구하기","힌트":"비례식에서 내항의 곱과 외항의 곱이 같음을 쓰면 $a$에 대한 어떤 식이 되는가?","식":["$2a:\\frac{3}{2}a^2=4:1$","$6a^2-2a=0$","$a=\\frac{1}{3}$"],"설명":"$a>0$이므로 $6a^2-2a=2a(3a-1)$에서 $a\\neq0$인 해를 고른다.","확인":"1/3","스킬":"A8","고비":true},{"제목":"삼각형 $ABC$의 넓이","힌트":"$\\angle B=90^\\circ$인 직각삼각형이다. 두 변의 길이는?","식":["$\\overline{AB}=\\frac{2}{3},\\ \\overline{BC}=\\frac{3}{2}\\times\\frac{1}{9}=\\frac{1}{6}$","$\\triangle ABC=\\frac{1}{2}\\times\\frac{2}{3}\\times\\frac{1}{6}=\\frac{1}{18}$"],"설명":"$\\overline{AB}$는 가로, $\\overline{BC}$는 세로이므로 두 변은 수직이다.","확인":"1/18","스킬":"G10"}],"fb":"fig/ns/"},"ns-e868dcd42ea1":{"길":"$C$에서 $\\overline{AD}$의 연장선에 수선을 내려 닮음을 만들고, $\\sin x^\\circ$를 직각삼각형의 변의 비로 읽는다.","단계":[{"제목":"변의 길이 구하기","힌트":"직각이등변삼각형 $ABD$에서 $\\overline{AD}=\\sqrt{2}$일 때 $\\overline{AB}$, $\\overline{BD}$는?","식":["$\\overline{AB}=\\overline{BD}=1$","$\\overline{BC}=\\overline{BD}+\\overline{DC}=2$","$\\overline{AC}=\\sqrt{1^2+2^2}=\\sqrt{5}$"],"설명":"$\\overline{AB}=\\overline{BD}$이고 $\\angle B=90^\\circ$이므로 삼각형 $ABD$는 직각이등변삼각형이다. 빗변이 $\\sqrt{2}$이면 나머지 두 변은 $1$이다. $\\overline{DC}=\\overline{BD}=1$이므로 $\\overline{BC}=2$이다.","확인":null,"스킬":"S3"},{"제목":"수선의 발 $H$ 잡기","힌트":"$\\sin x^\\circ$를 직각삼각형의 변의 비로 읽으려면 점 $C$에서 어디로 수선을 내려야 하는가?","식":["$\\angle CHA=90^\\circ$","$\\sin x^\\circ=\\frac{\\overline{CH}}{\\overline{AC}}$"],"설명":"점 $C$에서 $\\overline{AD}$의 연장선에 내린 수선의 발을 $H$라 한다. $H$는 직선 $AD$ 위에 있으므로 $\\angle CAH=x^\\circ$이고, 직각삼각형 $ACH$에서 $\\overline{CH}$가 필요하다.","확인":null,"스킬":"S2","고비":true},{"제목":"닮음으로 $\\overline{CH}$ 구하기","힌트":"$\\triangle ABD$와 $\\triangle CHD$에서 같은 각은 무엇인가?","식":["$\\triangle ABD\\sim\\triangle CHD$","$1:\\overline{CH}=\\sqrt{2}:1$","$\\overline{CH}=\\frac{\\sqrt{2}}{2}$"],"설명":"$\\angle B=\\angle H=90^\\circ$이고 $\\angle ADB=\\angle CDH$(맞꼭지각)이므로 $AA$ 닮음이다. 대응변 $AB$와 $CH$, $AD$와 $CD$의 비를 쓴다.","확인":null,"스킬":"S1"},{"제목":"$\\sin x^\\circ$ 구하기","힌트":"직각삼각형 $ACH$에서 $\\sin x^\\circ$를 변의 비로 쓰면?","식":["$\\sin x^\\circ=\\frac{\\overline{CH}}{\\overline{AC}}=\\frac{\\frac{\\sqrt{2}}{2}}{\\sqrt{5}}=\\frac{\\sqrt{10}}{10}$"],"설명":"분모의 근호를 없애려고 분자와 분모에 $\\sqrt{5}$를 곱한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-ef797fde7576":{"길":"그림에서 읽은 좌표로 $\\overline{AB}$를 구하고, $y=ax^2$ 위의 점의 좌표를 $a$로 나타내 사다리꼴의 넓이식을 세운다.","단계":[{"제목":"윗변과 아랫변의 길이","힌트":"$A$, $B$는 $y$축에 대칭이고 $B(1,-3)$이다. $\\overline{AB}$, $\\overline{CD}$는?","식":["$A(-1,-3),\\ B(1,-3)$","$\\overline{AB}=2,\\ \\overline{CD}=2\\overline{AB}=4$"],"설명":"그림에서 $B$의 좌표는 $(1,-3)$이다.","확인":null,"스킬":"G10"},{"제목":"점 $C$, $D$의 좌표","힌트":"$\\overline{CD}=4$이고 $C$, $D$가 $y$축에 대칭이면 $x$좌표는? $y$좌표를 $a$로 나타내면?","식":["$C(2,4a),\\ D(-2,4a)$"],"설명":"$C$, $D$의 $x$좌표는 $\\pm2$이고 $y=ax^2$에 넣으면 $y$좌표가 $4a$이다.","확인":null,"스킬":"G10"},{"제목":"사다리꼴 넓이로 식 세우기","힌트":"사다리꼴의 높이는 두 변 $AB$, $CD$ 사이의 거리이다. $a$로 나타내면?","식":["$\\frac{1}{2}\\times(2+4)\\times(4a+3)=21$"],"설명":"$A$, $B$의 $y$좌표는 $-3$이고 $C$, $D$의 $y$좌표는 $4a$이므로 높이는 $4a-(-3)=4a+3$이다.","확인":null,"스킬":"G10","고비":true},{"제목":"$a$ 구하기","힌트":"식을 정리하면?","식":["$4a+3=7$","$a=1$"],"설명":"양변을 $3$으로 나눈 뒤 풀면 된다.","확인":"1","스킬":"G10"}],"fb":"fig/ns/"},"ns-f000aaf76f3c":{"길":"삼각형 $PQR$을 사다리꼴에서 두 삼각형을 뺀 넓이로 나타내고, $x$에 대한 이차식의 최댓값을 구한다.","단계":[{"제목":"길이를 $x$로 나타내기","힌트":"$\\overline{BP}=\\overline{BQ}=x$라 하면 $\\overline{AP}$, $\\overline{AR}$는?","식":["$\\overline{AP}=\\overline{AR}=14-x$"],"설명":"$\\overline{AB}=14$이므로 $\\overline{AP}=14-\\overline{BP}$이다.","확인":null,"스킬":"C7"},{"제목":"삼각형 $PQR$의 넓이식","힌트":"삼각형 $PQR$은 사다리꼴 $ABQR$에서 어떤 두 삼각형을 뺀 것인가?","식":["$\\triangle PQR=\\square ABQR-\\triangle APR-\\triangle BPQ$","$=\\frac{1}{2}\\times14\\times14-\\frac{1}{2}(14-x)^2-\\frac{1}{2}x^2$","$=-x^2+14x$"],"설명":"$\\square ABQR$는 $\\overline{AR}=14-x$, $\\overline{BQ}=x$, 높이 $\\overline{AB}=14$인 사다리꼴이므로 넓이는 $\\frac{1}{2}\\times14\\times14$이다.","확인":null,"스킬":"S12","고비":true},{"제목":"완전제곱식으로 최댓값 구하기","힌트":"$-x^2+14x$를 $-(x-m)^2+n$ 꼴로 고치면?","식":["$-x^2+14x=-(x-7)^2+49$"],"설명":"$0<x<14$ 안에 $x=7$이 있으므로 $x=7$일 때 최댓값을 갖는다.","확인":"49","스킬":"A6"}],"fb":"fig/ns/"},"ns-f05df75475d6":{"길":"두 점의 $x$좌표를 문자로 두고 정사각형의 두 변의 길이가 같다는 식을 세워 구하는 합이 바로 나오게 한다.","단계":[{"제목":"점 $B$, $D$의 좌표","힌트":"$B$, $D$의 $x$좌표를 각각 $b$, $d$라 하면 $y$좌표는?","식":["$B\\left(b,\\frac{1}{3}b^2\\right),\\ D\\left(d,\\frac{1}{3}d^2\\right)$"],"설명":"$B$, $D$는 곡선 $y=\\frac{1}{3}x^2$ 위의 점이다.","확인":null,"스킬":"S4"},{"제목":"$\\overline{AB}$, $\\overline{BC}$를 $b$, $d$로 나타내기","힌트":"변이 축에 평행하므로 $\\overline{BC}$는 $x$좌표의 차, $\\overline{AB}$는 $y$좌표의 차이다. 각각 쓰면?","식":["$\\overline{BC}=d-b$","$\\overline{AB}=\\frac{1}{3}d^2-\\frac{1}{3}b^2$"],"설명":"$C$의 $x$좌표는 $D$의 $x$좌표 $d$와 같고, $A$의 $x$좌표는 $B$의 $x$좌표 $b$와 같다.","확인":null,"스킬":"S4"},{"제목":"정사각형 조건으로 식 세우기","힌트":"$\\overline{AB}=\\overline{BC}$를 쓰고 좌변을 인수분해하면?","식":["$\\frac{1}{3}d^2-\\frac{1}{3}b^2=d-b$","$\\frac{1}{3}(d+b)(d-b)=d-b$"],"설명":"정사각형이므로 이웃한 두 변의 길이가 같다. 좌변을 곱셈 공식으로 인수분해한다.","확인":null,"스킬":"S4","고비":true},{"제목":"$b+d$ 구하기","힌트":"$b\\neq d$이므로 양변을 $d-b$로 나누면?","식":["$\\frac{1}{3}(d+b)=1$","$b+d=3$"],"설명":"$B$와 $D$는 서로 다른 점이므로 $d-b\\neq0$이다. 구하는 값은 $B$의 $x$좌표 $b$와 $C$의 $x$좌표 $d$의 합이다.","확인":"3","스킬":"A2"}],"fb":"fig/ns/"},"ns-f339a8548c54":{"길":"점 $P$의 좌표를 한 문자로 두고, 색칠한 두 삼각형의 넓이를 그 문자로 나타내 식을 세운다.","단계":[{"제목":"삼각형 $POQ$의 넓이","힌트":"$P(p,2p)$라 하면 $\\overline{OQ}$, $\\overline{PQ}$는?","식":["$P(p,2p),\\ Q(p,0)$","$\\triangle POQ=\\frac{1}{2}\\times p\\times2p=p^2$"],"설명":"$P$는 직선 $y=2x$ 위의 점이므로 $y$좌표가 $2p$이다.","확인":null,"스킬":"G10"},{"제목":"삼각형 $APR$의 넓이","힌트":"$R$은 $P$에서 $\\overline{AC}$에 내린 수선의 발이다. $\\overline{PR}$, $\\overline{AR}$를 $p$로 나타내면?","식":["$R(10,2p)$","$\\overline{PR}=10-p,\\ \\overline{AR}=20-2p$","$\\triangle APR=\\frac{1}{2}\\times(10-p)\\times(20-2p)=(10-p)^2$"],"설명":"$\\overline{PR}$은 $x$축에 평행하므로 $R$의 $y$좌표는 $P$와 같고 $x$좌표는 $10$이다.","확인":null,"스킬":"G10"},{"제목":"넓이의 합으로 식 세우기","힌트":"색칠한 부분은 두 삼각형의 넓이의 합이다. 식을 세워 정리하면?","식":["$p^2+(10-p)^2=68$","$p^2-10p+16=0$","$(p-2)(p-8)=0$"],"설명":"$\\overline{OQ}<\\overline{PR}$이면 $p<10-p$, 즉 $p<5$이다.","확인":null,"스킬":"C7","고비":true},{"제목":"넓이의 비","힌트":"$p=2$일 때 두 삼각형의 넓이는?","식":["$\\triangle POQ=4,\\ \\triangle APR=64$","$4:64=1:16$"],"설명":"$p<5$이므로 $p=2$이다.","확인":null,"스킬":"G10"}],"fb":"fig/ns/"},"ns-f64c62da7ab0":{"길":"오각형의 넓이를 직사각형에서 삼각형 $PBQ$를 뺀 넓이로 나타내 $t$에 대한 이차방정식을 푼다.","단계":[{"제목":"시간 $t$로 길이 나타내기","힌트":"$t$초 후 $\\overline{AP}$, $\\overline{BQ}$, $\\overline{PB}$는?","식":["$\\overline{AP}=\\frac{1}{2}t,\\ \\overline{BQ}=t$","$\\overline{PB}=10-\\frac{1}{2}t$"],"설명":"그림에서 $\\overline{AB}=10\\,\\mathrm{cm}$, $\\overline{BC}=15\\,\\mathrm{cm}$이다. 움직인 거리는 속력에 시간을 곱한 값이다.","확인":null,"스킬":"C7"},{"제목":"오각형 넓이로 식 세우기","힌트":"오각형 $APQCD$는 직사각형에서 어떤 도형을 뺀 것인가?","식":["$15\\times10-\\frac{1}{2}t\\left(10-\\frac{1}{2}t\\right)=134$"],"설명":"직사각형의 넓이에서 직각삼각형 $PBQ$의 넓이를 뺀다.","확인":null,"스킬":"S12","고비":true},{"제목":"이차방정식 풀기","힌트":"식을 정리해 인수분해하고 $t$의 범위에 맞는 해를 고르면?","식":["$t^2-20t+64=0$","$(t-4)(t-16)=0$","$t=4$"],"설명":"점 $Q$는 $15\\,\\mathrm{cm}$를 $1$초에 $1\\,\\mathrm{cm}$씩 가므로 $0<t<15$이다.","확인":"4","스킬":"C7"}],"fb":"fig/ns/"},"ns-fab079b94cb7":{"길":"점 $\\mathrm{P}$ 의 좌표를 한 문자로 놓고 $\\overline{\\mathrm{PQ}}$ 를 그 문자의 이차식으로 나타내 최솟값을 구한다","단계":[{"제목":"점 $\\mathrm{P}$, $\\mathrm{Q}$ 의 좌표","고비":true,"힌트":"$\\mathrm{P}$ 의 $x$좌표를 $a$ 로 놓으면 $\\mathrm{Q}$ 의 $x$좌표는 어떻게 구할까?","식":["$\\mathrm{P}(a,\\ 2a^{2}+1)$","$2x-1=2a^{2}+1\\ \\Rightarrow\\ x=a^{2}+1$","$\\mathrm{Q}(a^{2}+1,\\ 2a^{2}+1)$"],"설명":"$\\overline{\\mathrm{PQ}}$ 는 $x$축에 평행하므로 $\\mathrm{Q}$ 의 $y$좌표는 $\\mathrm{P}$ 와 같은 $2a^{2}+1$ 이다. 이 값을 직선의 식에 넣어 $x$좌표를 구한다.","확인":null,"스킬":"S4"},{"제목":"$\\mathrm{PQ}$ 를 $a$ 의 식으로","힌트":"두 점의 $y$좌표가 같을 때 거리는 무엇의 차일까?","식":["$\\overline{\\mathrm{PQ}}=(a^{2}+1)-a=a^{2}-a+1$"],"설명":"$a^{2}-a+1$ 은 항상 양수이므로 $\\mathrm{Q}$ 는 $\\mathrm{P}$ 의 오른쪽에 있고, 길이는 $x$좌표의 차이이다.","확인":null,"스킬":"S4"},{"제목":"완전제곱 꼴로 고치기","힌트":"이차식의 최솟값은 어떤 꼴로 바꾸면 보일까?","식":["$a^{2}-a+1=\\left(a-\\frac{1}{2}\\right)^{2}+\\frac{3}{4}$"],"설명":"$a=\\frac{1}{2}$ 일 때 $\\overline{\\mathrm{PQ}}$ 는 최솟값 $\\frac{3}{4}$ 을 갖는다.","확인":"3/4","스킬":"A6"}],"fb":"fig/ns/"},"ns-fc94bf527ad8":{"길":"$\\mathrm{A}$, $\\mathrm{B}$ 의 좌표를 한 문자로 놓고 $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{PQ}}$ 로 식을 세운 뒤 사다리꼴 넓이를 구한다","단계":[{"제목":"점 $\\mathrm{C}$, $\\mathrm{D}$ 의 좌표","힌트":"$\\mathrm{C}$, $\\mathrm{D}$ 는 포물선 위에서 $y$좌표가 $-6$ 이다. $x$좌표는?","식":["$-6=-\\frac{1}{2}x^{2}\\ \\Rightarrow\\ x^{2}=12$","$\\mathrm{D}(-2\\sqrt{3},\\ -6),\\ \\mathrm{C}(2\\sqrt{3},\\ -6)$"],"설명":"$\\overline{\\mathrm{DC}}$ 의 길이는 $4\\sqrt{3}$ 이다.","확인":null,"스킬":"S4"},{"제목":"$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{PQ}}$ 로 식 세우기","고비":true,"힌트":"$\\mathrm{A}$, $\\mathrm{B}$ 의 $x$좌표를 $-a$, $a$ 로 놓으면 $\\overline{\\mathrm{AB}}$ 와 $\\overline{\\mathrm{PQ}}$ 를 $a$ 의 식으로 어떻게 쓸까?","식":["$\\mathrm{A}\\left(-a,\\ -\\frac{1}{2}a^{2}\\right),\\ \\mathrm{B}\\left(a,\\ -\\frac{1}{2}a^{2}\\right)\\ (a>0)$","$\\overline{\\mathrm{AB}}=2a,\\ \\overline{\\mathrm{PQ}}=-\\frac{1}{2}a^{2}+6$","$2a=-\\frac{1}{2}a^{2}+6$"],"설명":"$\\mathrm{P}$ 는 직선 $\\mathrm{AB}$ 와 $y$축의 교점이므로 $y$좌표가 $-\\frac{1}{2}a^{2}$ 이고, $\\mathrm{Q}$ 의 $y$좌표는 $-6$ 이다. 두 점의 $y$좌표의 차가 $\\overline{\\mathrm{PQ}}$ 이다.","확인":null,"스킬":"S4"},{"제목":"$a$ 의 값","힌트":"식을 정리해 인수분해하면?","식":["$a^{2}+4a-12=0$","$(a+6)(a-2)=0$"],"설명":"$a>0$ 이므로 $a=2$ 이고 $\\overline{\\mathrm{AB}}=4$ 이다.","확인":"2","스킬":"S4"},{"제목":"사다리꼴의 넓이","힌트":"윗변, 아랫변, 높이는 각각 얼마일까?","식":["$\\overline{\\mathrm{AB}}=4,\\ \\overline{\\mathrm{DC}}=4\\sqrt{3}$","$-2-(-6)=4$","$\\square\\mathrm{ABCD}=\\frac{1}{2}\\times(4+4\\sqrt{3})\\times4=8(\\sqrt{3}+1)$"],"설명":"$\\overline{\\mathrm{AB}}$ 와 $\\overline{\\mathrm{DC}}$ 는 $x$축에 평행하므로 사다리꼴이다. 두 변 사이의 거리는 $y$좌표의 차 $4$ 이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-084d76427d4e":{"길":"처음 양을 $1$ 로 놓고 퍼낸 뒤 부은 양을 $x$ 로 나타내 이차방정식을 세운다","단계":[{"제목":"남은 양을 식으로","힌트":"처음의 $x\\%$ 를 퍼내면 남는 양은 얼마일까?","식":["$1-\\frac{x}{100}$"],"설명":"처음 물의 양을 $1$ 이라 하면 $x\\%$ 를 퍼낸 뒤 남은 양은 $1-\\frac{x}{100}$ 이다.","확인":null,"스킬":"C7"},{"제목":"부은 뒤의 양으로 식 세우기","고비":true,"힌트":"남은 양의 $x\\%$ 를 부은 뒤의 양은 처음보다 $25\\%$ 줄어든 양과 같다. 식으로 쓰면?","식":["$\\left(1-\\frac{x}{100}\\right)+\\frac{x}{100}\\left(1-\\frac{x}{100}\\right)=\\frac{75}{100}$","$\\left(1-\\frac{x}{100}\\right)\\left(1+\\frac{x}{100}\\right)=\\frac{75}{100}$"],"설명":"남은 양에 그 $x\\%$ 를 더하면 $\\left(1-\\frac{x}{100}\\right)$ 로 묶인다.","확인":null,"스킬":"C7"},{"제목":"$x$ 의 값","힌트":"곱셈 공식으로 좌변을 정리하면?","식":["$1-\\left(\\frac{x}{100}\\right)^{2}=\\frac{75}{100}$","$x^{2}=2500$"],"설명":"$x>0$ 이므로 $x=50$ 이다.","확인":"50","스킬":"C7"}],"fb":"fig/ns/"},"ns-14e61c2ceebc":{"길":"$a$ 에 대한 이차방정식으로 보고 중근 조건으로 $y$ 를 $x$ 의 식으로 나타낸 뒤 최솟값을 구한다","단계":[{"제목":"중근이면 판별식이 0","고비":true,"힌트":"$a$ 에 대한 이차방정식에서 중근이 될 조건은?","식":["$a^{2}-2(x-2)a+(-3x+y)=0$","$\\frac{D}{4}=(x-2)^{2}-(-3x+y)=0$"],"설명":"$x$, $y$ 를 상수로 보고 $a$ 에 대한 이차방정식으로 읽는다. 중근을 가지면 판별식 $D=0$ 이다.","확인":null,"스킬":"G2"},{"제목":"$y$ 를 $x$ 의 식으로","힌트":"식을 $y$ 에 대해 정리하면?","식":["$y=x^{2}-4x+4+3x=x^{2}-x+4$"],"설명":"$(x-2)^{2}$ 을 전개하고 $y$ 를 한쪽으로 옮긴다.","확인":null,"스킬":"G2"},{"제목":"$y$ 의 최솟값","힌트":"이차식을 어떤 꼴로 바꾸면 최솟값이 보일까?","식":["$y=\\left(x-\\frac{1}{2}\\right)^{2}+\\frac{15}{4}$"],"설명":"$x=\\frac{1}{2}$ 일 때 $y$ 는 최솟값 $\\frac{15}{4}$ 를 갖는다.","확인":"15/4","스킬":"A6"}],"fb":"fig/ns/"},"ns-290628af0c58":{"길":"인상 후 가격과 손님 수의 곱이 처음 판매금액의 $1.08$ 배라는 식을 세운다","단계":[{"제목":"인상 후 가격과 손님 수","힌트":"처음 가격을 $a$, 손님 수를 $b$ 로 놓으면 인상 후 가격과 손님 수는?","식":["$a\\left(1+\\frac{x}{100}\\right)$","$b\\left(1-\\frac{0.5x}{100}\\right)=b\\left(1-\\frac{x}{200}\\right)$"],"설명":"가격이 $x\\%$ 오르고 손님이 $0.5x\\%$ 줄어든다.","확인":null,"스킬":"C7"},{"제목":"판매금액 식 세우기","고비":true,"힌트":"처음 판매금액 $ab$ 가 $8\\%$ 늘어난 식을 쓰면?","식":["$a\\left(1+\\frac{x}{100}\\right)\\times b\\left(1-\\frac{x}{200}\\right)=ab\\left(1+\\frac{8}{100}\\right)$","$(100+x)(200-x)=21600$"],"설명":"양변을 $ab$ 로 나눈 뒤 $20000$ 을 곱해 정리한다.","확인":null,"스킬":"C7"},{"제목":"이차방정식 풀기","힌트":"전개해 인수분해하면?","식":["$x^{2}-100x+1600=0$","$(x-20)(x-80)=0$"],"설명":"$x=20$ 또는 $x=80$ 이고 두 값 모두 가능하므로 선지에서 $20\\%$ 와 $80\\%$ 를 고른다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-2de572925eb8":{"길":"평균의 합 변화로 새 학생의 몸무게를 구한 뒤, 바뀐 자료의 중앙값과 최빈값을 읽는다","단계":[{"제목":"새 학생의 몸무게","힌트":"처음 합과 나중 합의 차이는 어디서 생겼을까?","식":["$60\\times5-66+x=59\\times5$","$x=61$"],"설명":"$66\\,\\mathrm{kg}$ 인 학생이 나가고 몸무게 $x\\,\\mathrm{kg}$ 인 학생이 들어와 평균이 $59$ 가 되었다. 합이 $300$ 에서 $295$ 로 줄었다.","확인":"61","스킬":"C7"},{"제목":"처음 자료의 모양","고비":true,"힌트":"중앙값과 최빈값이 모두 $61$ 이라면 $61$ 은 몇 번 이상 나오고, 나머지 값은 어디에 놓일까?","식":["$a,\\ 61,\\ 61,\\ b,\\ 66\\ (a\\ne b)$","$a+b=300-61-61-66=112$"],"설명":"중앙값이 $61$ 이고 최빈값도 $61$ 이므로 $61$ 이 두 번 이상 나온다. $66$ 이 가장 크다고 보고 나머지를 $a$, $b$ 로 놓는다.","확인":null,"스킬":"C2"},{"제목":"나중 자료의 중앙값과 최빈값","힌트":"$66$ 대신 새 학생의 몸무게를 넣고 크기순으로 놓으면?","식":["$a,\\ 61,\\ 61,\\ 61,\\ b$","$61+61=122$"],"설명":"새 학생의 몸무게는 $61$ 이므로 $61$ 이 세 번 나온다. 가운데 값도 $61$ 이므로 중앙값과 최빈값이 모두 $61$ 이다.","확인":"122","스킬":"C2"}],"fb":"fig/ns/"},"ns-3f6aaaf1c77e":{"길":"근의 공식에서 근호 안이 제곱수가 되는 조건을 찾아 $k$ 의 개수를 센다","단계":[{"제목":"근의 공식","힌트":"근의 공식으로 해를 $k$ 로 나타내면?","식":["$x=\\frac{6\\pm\\sqrt{36+8k}}{4}=\\frac{3\\pm\\sqrt{9+2k}}{2}$"],"설명":"$36+8k=4(9+2k)$ 이므로 $\\sqrt{36+8k}=2\\sqrt{9+2k}$ 이고, 분자와 분모를 $2$ 로 나눈다.","확인":null,"스킬":"N8"},{"제목":"해가 정수가 될 조건","고비":true,"힌트":"$\\sqrt{9+2k}$ 가 어떤 수일 때 $\\frac{3\\pm\\sqrt{9+2k}}{2}$ 가 정수일까?","식":["$9+2k=m^{2}\\ (m\\text{ 은 홀수})$","$11\\le m^{2}\\le209$"],"설명":"$9+2k$ 는 홀수이므로 제곱수이면 홀수의 제곱이고, 그때 $3\\pm m$ 이 짝수가 되어 해가 정수이다. $1\\le k\\le100$ 이므로 $9+2k$ 는 $11$ 이상 $209$ 이하이다.","확인":null,"스킬":"N8"},{"제목":"$k$ 의 값 세기","힌트":"범위 안에 있는 홀수의 제곱을 모두 찾으면?","식":["$9+2k=25,\\ 49,\\ 81,\\ 121,\\ 169$","$k=8,\\ 20,\\ 36,\\ 56,\\ 80$"],"설명":"$15^{2}=225$ 는 $209$ 보다 크므로 뺀다. 따라서 $k$ 는 모두 $5$ 개이다.","확인":"5","스킬":"N8"}],"fb":"fig/ns/"},"ns-47bb1ec5adf0":{"길":"두 근을 $k$, $2k$ 로 놓고 $a+b$ 를 $k$ 의 식으로 나타낸 뒤, 선지의 값이 만들어지는지 확인한다","단계":[{"제목":"두 근을 $k$, $2k$ 로 놓기","고비":true,"힌트":"두 근의 비가 $1:2$ 일 때 두 근을 한 문자로 나타내면?","식":["$-a=k+2k=3k$","$b=k\\times2k=2k^{2}$"],"설명":"두 근을 $k$, $2k$ 라 하고 근과 계수의 관계로 $a$, $b$ 를 $k$ 로 나타낸다.","확인":null,"스킬":"A8"},{"제목":"$a+b$ 를 $k$ 의 식으로","힌트":"$a$, $b$ 를 더하면?","식":["$a+b=2k^{2}-3k$"],"설명":"$a=-3k$ 이므로 $a+b=-3k+2k^{2}$ 이다.","확인":null,"스킬":"A2"},{"제목":"선지의 값 만들어 보기","힌트":"선지의 값을 하나씩 만들 수 있는 $k$ 가 있을까?","식":["$k=1\\ \\Rightarrow\\ -1$","$k=2\\ \\Rightarrow\\ 2$","$k=-1\\ \\Rightarrow\\ 5,\\quad k=-3\\ \\Rightarrow\\ 27$"],"설명":"$a=-3k$ 와 $b=2k^{2}$ 이 정수가 되는 $k$ 를 넣어 보면 $-1$, $2$, $5$, $27$ 이 모두 만들어진다.","확인":null,"스킬":"A2"},{"제목":"10 이 되는 경우","힌트":"$2k^{2}-3k=10$ 을 만족하는 $k$ 는 정수일까?","식":["$2k^{2}-3k-10=0$","$k=\\frac{3\\pm\\sqrt{89}}{4}$"],"설명":"$k$ 가 무리수이면 $a=-3k$ 도 정수가 아니다. 따라서 $a+b=10$ 은 만들 수 없다.","확인":"10","스킬":"A2"}],"fb":"fig/ns/"},"ns-4abef50e2479":{"길":"가격을 내린 횟수를 $x$ 로 놓고 수익을 $x$ 의 이차식으로 세워 꼭짓점을 구한다","단계":[{"제목":"가격과 관객 수를 $x$ 로","고비":true,"힌트":"$50$ 원씩 $x$ 번 내리면 가격과 관객 수는 각각 어떻게 될까?","식":["$5000-50x$","$500+10x$"],"설명":"가격은 $50$ 원씩 $x$ 번 내려 $5000-50x$ 원이고, 관객은 $10$ 명씩 $x$ 번 늘어 $500+10x$ 명이다.","확인":null,"스킬":"C7"},{"제목":"수익을 이차식으로","힌트":"수익은 가격 곱하기 관객 수이다. 전개하면?","식":["$y=(5000-50x)(500+10x)$","$y=-500x^{2}+25000x+2500000$"],"설명":"수익을 $y$ 원이라 하고 전개한다.","확인":null,"스킬":"C7"},{"제목":"최대가 되는 $x$","힌트":"완전제곱 꼴로 고치면 $y$ 가 최대일 때의 $x$ 는?","식":["$y=-500(x-25)^{2}+2812500$"],"설명":"$x=25$ 일 때 $y$ 가 최대이고, 이때 관객은 $750$ 명으로 $1000$ 명 이하라 조건에 맞는다.","확인":"25","스킬":"A6"},{"제목":"입장권 가격","힌트":"$x=25$ 일 때 가격은?","식":["$5000-50\\times25=3750$"],"설명":"입장권 가격은 $3750$ 원이다.","확인":"3750","스킬":"C7"}],"fb":"fig/ns/"},"ns-4fb5b24f878d":{"길":"중앙값의 편차가 $4$ 임을 구하고, $a$ 를 작은 수부터 넣어 가운데 편차가 $4$ 가 되는 때를 찾는다","단계":[{"제목":"중앙값의 편차","힌트":"평균이 $180$ 이고 중앙값이 $184$ 이면 가운데 학생의 편차는?","식":["$184-180=4$"],"설명":"편차는 변량에서 평균을 뺀 값이므로 중앙값이 $184$ 인 학생의 편차는 $4$ 이다.","확인":"4","스킬":"C2"},{"제목":"$a$ 가 작을 때 가운데 편차","고비":true,"힌트":"$a$ 가 작을 때 다섯 편차를 크기순으로 놓으면 가운데 값은?","식":["$a=1:\\ -11,\\ 1,\\ 1,\\ 4,\\ 5$","$a=2:\\ -11,\\ 0,\\ 2,\\ 4,\\ 5$","$a=3:\\ -11,\\ -1,\\ 3,\\ 4,\\ 5$"],"설명":"$a=1,\\ 2,\\ 3$ 일 때 가운데 편차는 각각 $1$, $2$, $3$ 이라 $4$ 가 아니다.","확인":null,"스킬":"C2"},{"제목":"$a=4$ 일 때","힌트":"$a=4$ 이면 가운데 편차가 $4$ 가 될까?","식":["$a=4:\\ -11,\\ -2,\\ 4,\\ 4,\\ 5$"],"설명":"가운데 편차가 $4$ 이므로 조건을 만족한다. 따라서 가장 작은 $a$ 는 $4$ 이다.","확인":"4","스킬":"C2"}],"fb":"fig/ns/"},"ns-55b78b139fa6":{"길":"정다각형을 중심에서 꼭짓점으로 이은 합동인 삼각형으로 나눠 넓이를 구하고 더한다","단계":[{"제목":"정팔각형의 넓이","고비":true,"힌트":"중심과 꼭짓점을 이으면 합동인 이등변삼각형 몇 개로 나뉠까?","식":["$\\angle\\mathrm{AOB}=\\frac{360^{\\circ}}{8}=45^{\\circ}$","$\\overline{\\mathrm{AH}}=2\\sqrt{2}$","$8\\times\\frac{1}{2}\\times4\\times2\\sqrt{2}=32\\sqrt{2}$"],"설명":"원의 중심을 $\\mathrm{O}$, 이웃한 두 꼭짓점을 $\\mathrm{A}$, $\\mathrm{B}$ 라 하고 $\\mathrm{A}$ 에서 $\\overline{\\mathrm{OB}}$ 에 내린 수선의 발을 $\\mathrm{H}$ 라 하면 $\\triangle\\mathrm{AOH}$ 는 $45^{\\circ}$ 직각이등변삼각형이다. $\\overline{\\mathrm{OA}}=4$ 이므로 $\\overline{\\mathrm{AH}}=2\\sqrt{2}$ 이고, 삼각형 $\\mathrm{OAB}$ 의 넓이는 $4\\sqrt{2}$ 이다.","확인":null,"스킬":"S12"},{"제목":"정육각형의 한 변","힌트":"외접하는 정육각형에서 원의 반지름은 삼각형 $\\mathrm{OAB}$ 의 무엇일까?","식":["$\\frac{\\sqrt{3}}{2}\\times\\overline{\\mathrm{OA}}=3\\sqrt{3}$","$\\overline{\\mathrm{OA}}=6$"],"설명":"정육각형의 중심을 $\\mathrm{O}$, 이웃한 두 꼭짓점을 $\\mathrm{A}$, $\\mathrm{B}$ 라 하면 $\\triangle\\mathrm{OAB}$ 는 정삼각형이고 원의 반지름 $3\\sqrt{3}$ 은 그 높이이다. 정삼각형의 높이는 한 변의 $\\frac{\\sqrt{3}}{2}$ 배이다.","확인":null,"스킬":"S3"},{"제목":"정육각형의 넓이와 합","힌트":"정삼각형 $6$ 개의 넓이를 더하고 두 넓이의 합을 $\\sqrt{2}$, $\\sqrt{3}$ 별로 묶으면?","식":["$6\\times\\frac{\\sqrt{3}}{4}\\times6^{2}=54\\sqrt{3}$","$32\\sqrt{2}+54\\sqrt{3}\\ \\Rightarrow\\ a=32,\\ b=54,\\ c=d=0$","$a+b+c+d=86$"],"설명":"두 넓이의 합이 $32\\sqrt{2}+54\\sqrt{3}$ 이므로 $\\sqrt{5}$, $\\sqrt{6}$ 의 계수 $c$, $d$ 는 $0$ 이다.","확인":"86","스킬":"S12"}],"fb":"fig/ns/"},"ns-5bd93614770c":{"길":"잘못 적힌 두 값을 뺀 나머지 세 값의 편차 제곱합을 구한 뒤, 바른 값을 넣어 분산을 다시 구한다","단계":[{"제목":"평균이 그대로인지 확인","힌트":"잘못 기록된 두 값의 합과 실제 값의 합은 어떤 관계일까?","식":["$27+36=31+32=63$"],"설명":"두 합이 같으므로 평균은 그대로 $30$ 이다. 편차의 기준이 되는 $30$ 이 바뀌지 않는다.","확인":null,"스킬":"A2"},{"제목":"나머지 세 명의 편차 제곱합","고비":true,"힌트":"분산 $12$ 로 편차 제곱의 합을 구한 뒤 잘못된 두 값의 몫을 빼면?","식":["$5\\times12=60$","$(27-30)^{2}+(36-30)^{2}=9+36=45$","$60-45=15$"],"설명":"바뀌지 않은 세 명의 기록을 $a$, $b$, $c$ 라 하면 $(a-30)^{2}+(b-30)^{2}+(c-30)^{2}=15$ 이다.","확인":null,"스킬":"A2"},{"제목":"실제 분산과 표준편차","힌트":"바른 두 값 $31$, $32$ 의 편차의 제곱을 더하면?","식":["$\\frac{15+(31-30)^{2}+(32-30)^{2}}{5}=\\frac{20}{5}=4$","$\\sqrt{4}=2$"],"설명":"실제 분산은 $4$ 이므로 표준편차는 $2$ 이다.","확인":"2","스킬":"A2"}],"fb":"fig/ns/"},"ns-60ba70fa235e":{"길":"넓이를 가로 길이의 식으로 쓰고, 평균·표준편차 조건에서 합과 제곱의 합을 구해 넓이의 평균을 계산한다","단계":[{"제목":"세로 길이와 넓이","힌트":"둘레가 $20\\,\\mathrm{cm}$ 일 때 가로가 $a$ 이면 세로는?","식":["$10-a$","$a(10-a)$"],"설명":"철사의 길이가 $20\\,\\mathrm{cm}$ 이므로 가로와 세로의 합은 $10\\,\\mathrm{cm}$ 이다. 가로를 $a$ 라 하면 세로는 $10-a$ 이고 넓이는 $a(10-a)$ 이다.","확인":null,"스킬":"C7"},{"제목":"가로의 합과 제곱의 합","힌트":"평균 $5$ 로 합을, 표준편차 $2$ 로 편차 제곱의 합을 구하면?","식":["$a+b+c+d+e=5\\times5=25$","$(a-5)^{2}+(b-5)^{2}+(c-5)^{2}+(d-5)^{2}+(e-5)^{2}=5\\times2^{2}=20$","$a^{2}+b^{2}+c^{2}+d^{2}+e^{2}=20+10\\times25-125=145$"],"설명":"가로의 길이를 $a$, $b$, $c$, $d$, $e$ 라 한다. 분산은 편차의 제곱의 평균이므로 편차 제곱의 합은 $5\\times4$ 이고, 이를 전개하면 제곱의 합이 나온다.","확인":null,"스킬":"A2"},{"제목":"넓이의 평균","고비":true,"힌트":"다섯 넓이의 합을 가로의 합과 제곱의 합으로 쓰면?","식":["$\\frac{10(a+b+c+d+e)-(a^{2}+b^{2}+c^{2}+d^{2}+e^{2})}{5}$","$=\\frac{250-145}{5}=21$"],"설명":"넓이는 $10a-a^{2}$ 꼴이므로 다섯 넓이의 합은 가로의 합의 $10$ 배에서 제곱의 합을 뺀 값이다.","확인":"21","스킬":"A6"}],"fb":"fig/ns/"},"ns-61aa6dda9de6":{"길":"각 쌍의 합과 제곱의 합을 구한 뒤, 네 수 전체의 평균을 기준으로 편차 제곱의 합을 다시 전개한다","단계":[{"제목":"$a+b$ 와 $a^{2}+b^{2}$","힌트":"평균과 분산으로 합과 제곱의 합을 구하면?","식":["$a+b=2\\times6=12$","$(a-6)^{2}+(b-6)^{2}=2\\times1=2$","$a^{2}+b^{2}=2+12\\times12-72=74$"],"설명":"분산은 편차의 제곱의 평균이므로 편차 제곱의 합을 구하고, 전개해 $a+b$ 의 값을 넣는다.","확인":null,"스킬":"A2"},{"제목":"$c+d$ 와 $c^{2}+d^{2}$","힌트":"같은 방법으로 $c$, $d$ 의 합과 제곱의 합은?","식":["$c+d=2\\times2=4$","$(c-2)^{2}+(d-2)^{2}=2\\times4=8$","$c^{2}+d^{2}=8+4\\times4-8=16$"],"설명":"$(c-2)^{2}+(d-2)^{2}=c^{2}+d^{2}-4(c+d)+8$ 이다.","확인":null,"스킬":"A2"},{"제목":"네 수 전체의 평균","고비":true,"힌트":"네 수의 합은 두 쌍의 합을 더한 것이다. 평균은?","식":["$\\frac{12+4}{4}=4$"],"설명":"$a+b+c+d=16$ 이므로 평균은 $4$ 이다. 전체의 분산은 편차를 이 평균 $4$ 를 기준으로 새로 계산해야 한다.","확인":"4","스킬":"A2"},{"제목":"전체 분산과 표준편차","힌트":"$(a-4)^{2}+(b-4)^{2}+(c-4)^{2}+(d-4)^{2}$ 을 전개해 위의 값을 넣으면?","식":["$\\frac{(a^{2}+b^{2}+c^{2}+d^{2})-8(a+b+c+d)+4\\times4^{2}}{4}$","$=\\frac{90-128+64}{4}=\\frac{26}{4}$","$\\sqrt{\\frac{26}{4}}=\\frac{\\sqrt{26}}{2}$"],"설명":"분산은 편차 제곱의 합을 $4$ 로 나눈 값이다. 표준편차는 그 양의 제곱근이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-63f56a636d57":{"길":"전체 평균에서 $\\mathrm{B}$ 의 평균을, 편차 제곱합의 차에서 $\\mathrm{B}$ 의 분산을 구한다","단계":[{"제목":"자료 $\\mathrm{B}$ 의 평균","힌트":"전체 평균이 $3$ 이 되려면 $\\mathrm{B}$ 의 평균은?","식":["$\\frac{5\\times3+4m}{9}=3$","$m=3$"],"설명":"자료 $\\mathrm{B}$ 의 평균을 $m$ 이라 하고 전체 합으로 식을 세운다.","확인":"3","스킬":"A2"},{"제목":"편차 제곱합의 차","고비":true,"힌트":"분산에 개수를 곱하면 편차 제곱의 합이다. 전체에서 $\\mathrm{A}$ 의 몫을 빼면?","식":["$9\\times8=72,\\ 5\\times4=20$","$72-20=52$","$v=\\frac{52}{4}=13$"],"설명":"자료 $\\mathrm{A}$, $\\mathrm{B}$, 전체의 평균이 모두 $3$ 이라 편차의 기준이 같다. 그래서 전체의 편차 제곱합에서 $\\mathrm{A}$ 의 편차 제곱합을 빼면 $\\mathrm{B}$ 의 편차 제곱합이다.","확인":null,"스킬":"A2"},{"제목":"평균과 분산의 차","힌트":"$\\mathrm{B}$ 의 분산에서 평균을 빼면?","식":["$13-3=10$"],"설명":"자료 $\\mathrm{B}$ 의 분산은 $13$, 평균은 $3$ 이다.","확인":"10","스킬":"A2"}],"fb":"fig/ns/"},"ns-6d8a37903268":{"길":"중앙값으로 $b$ 를 정하고, 평균과 분산 조건에서 $a$, $c$ 를 구한다","단계":[{"제목":"$b$ 의 값과 $a+c$","힌트":"세 수를 크기순으로 놓으면 가운데는? 평균 $9$ 로 합은?","식":["$b=8$","$a+8+c=27\\ \\Rightarrow\\ a+c=19$"],"설명":"$0<a<b<c$ 이므로 가운데 수 $b$ 가 중앙값 $8$ 이다.","확인":null,"스킬":"A2"},{"제목":"분산 조건으로 식 세우기","고비":true,"힌트":"분산이 $\\frac{26}{3}$ 이면 편차 제곱의 합은?","식":["$(a-9)^{2}+(8-9)^{2}+(c-9)^{2}=26$","$(a-9)^{2}+(10-a)^{2}=25$"],"설명":"편차 제곱의 합은 $3\\times\\frac{26}{3}=26$ 이다. $c=19-a$ 이므로 $c-9=10-a$ 를 넣으면 $a$ 만의 식이 된다.","확인":null,"스킬":"A2"},{"제목":"$a$, $c$ 구하기","힌트":"정리해 인수분해하면?","식":["$a^{2}-19a+78=0$","$(a-6)(a-13)=0$","$a=6,\\ c=13$"],"설명":"$a<c$ 이므로 $a=13$ 은 $c=6$ 이 되어 맞지 않는다. 따라서 $a=6$, $c=13$ 이다.","확인":null,"스킬":"A2"},{"제목":"$a+b-c$ 의 값","힌트":"구한 값을 대입하면?","식":["$6+8-13=1$"],"설명":"$a=6$, $b=8$, $c=13$ 을 대입한다.","확인":"1","스킬":"A2"}],"fb":"fig/ns/"},"ns-7335d48f848d":{"길":"정삼각형의 넓이의 비는 한 변의 길이의 비의 제곱임을 이용해 이차방정식을 세워 푼다","단계":[{"제목":"두 변의 관계","힌트":"끈의 길이가 $15$ 이므로 두 정삼각형의 둘레의 합은? 큰 변을 $x$ 로 놓으면 작은 변은?","식":["$3x+3y=15$","$y=5-x$"],"설명":"큰 정삼각형의 한 변을 $x$, 작은 쪽의 한 변을 $y$ 라 하면 둘레의 합이 $15$ 이다.","확인":null,"스킬":"C7"},{"제목":"넓이의 비를 변의 비로","고비":true,"힌트":"정삼각형끼리는 닮음이다. 넓이의 비가 $2:3$ 이면 한 변의 길이의 비는 어떻게 쓸까?","식":["$y^{2}:x^{2}=2:3$","$(5-x)^{2}:x^{2}=2:3$"],"설명":"닮은 도형의 넓이의 비는 닮음비의 제곱이다.","확인":null,"스킬":"S1"},{"제목":"이차방정식 풀기","힌트":"비례식을 곱의 꼴로 바꿔 풀면?","식":["$3(5-x)^{2}=2x^{2}$","$x^{2}-30x+75=0$","$x=15\\pm5\\sqrt{6}$"],"설명":"$y=5-x>0$ 이므로 $x<5$ 이다. $15+5\\sqrt{6}$ 은 $5$ 보다 크므로 버리고 $x=15-5\\sqrt{6}$ 이다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-746ff9f7cf60":{"길":"근의 공식에서 근호 안이 $3$ 의 배수인 제곱수가 되는 가장 작은 $k$ 를 찾는다","단계":[{"제목":"근의 공식","힌트":"근의 공식으로 해를 $k$ 로 나타내면?","식":["$x=\\frac{12\\pm\\sqrt{144-12(12-5k)}}{6}=\\frac{6\\pm\\sqrt{15k}}{3}$"],"설명":"근호 안은 $144-144+60k=60k$ 이고 $\\sqrt{60k}=2\\sqrt{15k}$ 이므로 분자와 분모를 $2$ 로 나눈다.","확인":null,"스킬":"N8"},{"제목":"해가 정수일 조건","고비":true,"힌트":"$\\frac{6\\pm\\sqrt{15k}}{3}$ 이 정수이려면 $\\sqrt{15k}$ 는 어떤 수여야 할까?","식":["$\\sqrt{15k}=3m,\\ 15k=9m^{2}$","$k=\\frac{3}{5}m^{2}$"],"설명":"$6\\pm\\sqrt{15k}$ 가 $3$ 의 배수이어야 하므로 $\\sqrt{15k}$ 는 $3$ 의 배수인 정수이다. 이를 $3m$ 으로 놓고 $k$ 를 $m$ 으로 나타낸다.","확인":null,"스킬":"N8"},{"제목":"가장 작은 $k$","힌트":"$k$ 가 자연수가 되는 가장 작은 $m$ 은?","식":["$m=5\\ \\Rightarrow\\ k=15$"],"설명":"$k=\\frac{3}{5}m^{2}$ 이 자연수이려면 $m$ 이 $5$ 의 배수이어야 하므로 $m=5$ 일 때 가장 작다.","확인":"15","스킬":"N8"}],"fb":"fig/ns/"},"ns-7a234b38a01d":{"길":"완전제곱식 조건을 판별식이 0 이라는 식으로 쓴 뒤, $k$ 에 관한 이차방정식의 두 근의 합을 근과 계수의 관계로 구한다.","단계":[{"제목":"완전제곱식 조건 세우기","고비":true,"힌트":"이차식이 완전제곱식이면 이차방정식으로 보았을 때 근은 몇 개일까?","식":["$(-\\sqrt{60})^2-4\\times3\\times(k^2-4k+\\sqrt{15})=0$"],"설명":"완전제곱식이면 이차방정식이 중근을 가지므로 판별식이 $0$ 이다.","확인":null,"스킬":"A6"},{"제목":"$k$ 에 관한 이차방정식으로 정리","힌트":"식을 전개하고 $k^2$ 의 계수가 양수가 되게 정리하면?","식":["$60-12k^2+48k-12\\sqrt{15}=0$","$12k^2-48k-60+12\\sqrt{15}=0$"],"설명":"괄호를 풀어 $k$ 에 관한 이차방정식으로 만든다.","확인":null,"스킬":"A6"},{"제목":"$k$ 의 값들의 합 구하기","힌트":"이차방정식의 두 근의 합은 계수로 어떻게 나타낼까?","식":["$k_1+k_2=-\\frac{-48}{12}=4$"],"설명":"이차방정식의 두 근의 합은 근과 계수의 관계로 구한다.","확인":"4","스킬":"A2"}],"fb":"fig/ns/"},"ns-7bc4e0c3ef50":{"길":"평균과 분산을 합과 편차의 제곱합으로 바꾸고, 제곱의 합을 구해 두었다가 바뀐 평균을 기준으로 분산을 다시 계산한다.","단계":[{"제목":"합과 편차의 제곱합 구하기","힌트":"평균이 $80$, 분산이 $12$ 이면 $5$ 명의 점수의 합과 편차의 제곱합은 각각 얼마일까?","식":["$a+b+c+d+e=400$","$(a-80)^2+(b-80)^2+(c-80)^2+(d-80)^2+(e-80)^2=60$"],"설명":"점수를 $a,\\ b,\\ c,\\ d,\\ e$ 라 하면 합은 평균에 $5$ 를 곱한 값이고, 편차의 제곱합은 분산에 $5$ 를 곱한 값이다.","확인":null,"스킬":"C7"},{"제목":"점수의 제곱의 합 구하기","고비":true,"힌트":"편차의 제곱합을 전개하고 합을 대입하면 $a^2+b^2+c^2+d^2+e^2$ 은?","식":["$(a^2+\\cdots+e^2)-160\\times400+5\\times80^2=60$","$a^2+b^2+c^2+d^2+e^2=32060$"],"설명":"$(a-80)^2=a^2-160a+80^2$ 이므로 다섯 개를 더해 전개한 뒤 합 $400$ 을 대입한다.","확인":null,"스킬":"A2"},{"제목":"새 평균 구하기","힌트":"$92$ 점이 더해진 $6$ 명의 점수의 합은 얼마이고 평균은?","식":["$\\frac{400+92}{6}=82$"],"설명":"여섯 명의 합을 $6$ 으로 나누면 평균이 $82$ 점이다.","확인":"82","스킬":"C7"},{"제목":"새 분산 구하기","힌트":"$82$ 를 기준으로 편차의 제곱합을 다시 전개하면?","식":["$\\frac{(a^2+\\cdots+e^2)-164\\times400+5\\times82^2+(92-82)^2}{6}$","$=\\frac{32060-65600+33620+100}{6}=\\frac{180}{6}=30$"],"설명":"원래 다섯 명은 $82$ 를 기준으로 전개해 앞에서 구한 합과 제곱의 합을 넣고, 새로 들어온 학생은 $(92-82)^2$ 을 더한다.","확인":"30","스킬":"A2"}],"fb":"fig/ns/"},"ns-8b34b1103abf":{"길":"큰 정삼각형의 한 변을 $x$ 로 두어 작은 정삼각형의 한 변을 나타내고, 닮은 도형의 넓이의 비는 길이의 비의 제곱임을 이용해 이차방정식을 세운다.","단계":[{"제목":"작은 정삼각형의 한 변 나타내기","힌트":"두 정삼각형의 둘레의 합은 끈 전체의 길이와 같다. 큰 변을 $x$ 라 하면 작은 변은?","식":["$3x+3y=18$","$y=6-x$"],"설명":"큰 정삼각형의 한 변을 $x$, 작은 정삼각형의 한 변을 $y$ 라 하면 두 둘레의 합이 $18$ 이다.","확인":null,"스킬":"C7"},{"제목":"넓이비로 이차방정식 세우기","고비":true,"힌트":"닮은 도형의 넓이의 비는 길이의 비와 어떤 관계일까?","식":["$(6-x)^2:x^2=1:3$","$3(6-x)^2=x^2$","$x^2-18x+54=0$"],"설명":"정삼각형은 모두 닮은 도형이므로 넓이의 비는 한 변의 길이의 비의 제곱이다.","확인":null,"스킬":"S1"},{"제목":"이차방정식 풀고 범위로 근 고르기","힌트":"작은 정삼각형의 한 변도 양수여야 한다. $x$ 의 범위는?","식":["$x=9\\pm3\\sqrt{3}$","$0<x<6$ 이므로 $x=9-3\\sqrt{3}$"],"설명":"근의 공식으로 풀고, $y=6-x>0$ 이어야 하므로 $x<6$ 인 근을 고른다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-9039fc1c0f87":{"길":"평균과 분산 조건에서 세 수의 합과 제곱의 합을 구하고, 두 수를 더한 다섯 개 자료의 평균과 분산을 그 값으로 계산한다.","단계":[{"제목":"세 수의 합 구하기","힌트":"평균이 $4$ 이면 세 수의 합은?","식":["$\\frac{a+b+c}{3}=4$","$a+b+c=12$"],"설명":"평균에 개수 $3$ 을 곱하면 합이다.","확인":"12","스킬":"C7"},{"제목":"세 수의 제곱의 합 구하기","고비":true,"힌트":"분산이 $2$ 이면 편차의 제곱합은? 그것을 전개하면?","식":["$(a-4)^2+(b-4)^2+(c-4)^2=6$","$a^2+b^2+c^2-8(a+b+c)+48=6$","$a^2+b^2+c^2=54$"],"설명":"분산에 $3$ 을 곱한 값이 편차의 제곱합이다. 전개한 식에 $a+b+c=12$ 를 대입한다.","확인":null,"스킬":"A2"},{"제목":"새 평균 $m$ 구하기","힌트":"$1,\\ 2,\\ a,\\ b,\\ c$ 의 합은?","식":["$m=\\frac{1+2+a+b+c}{5}=\\frac{15}{5}=3$"],"설명":"다섯 수의 합 $3+12=15$ 를 $5$ 로 나눈다.","확인":"3","스킬":"C7"},{"제목":"새 분산 $S$ 구하기","힌트":"평균 $3$ 을 기준으로 편차의 제곱합을 전개하면?","식":["$S=\\frac{(-2)^2+(-1)^2+(a-3)^2+(b-3)^2+(c-3)^2}{5}$","$=\\frac{5+54-6\\times12+27}{5}=\\frac{14}{5}=2.8$"],"설명":"$(a-3)^2+(b-3)^2+(c-3)^2=a^2+b^2+c^2-6(a+b+c)+27$ 에 앞에서 구한 값을 넣는다.","확인":"2.8","스킬":"A2"},{"제목":"$m+S$ 구하기","힌트":"$m$ 과 $S$ 를 더하면?","식":["$m+S=3+2.8=5.8$"],"설명":"앞에서 구한 평균과 분산을 더한다.","확인":"5.8","스킬":"C7"}],"fb":"fig/ns/"},"ns-98d75dbaffa2":{"길":"변량의 크기 순서에서 중앙값 조건을 만족하는 배열을 정한 뒤, 최빈값 조건으로 값이 같아지는 두 항을 찾는다.","단계":[{"제목":"변량의 크기 순서 정하기","힌트":"$a$ 와 $3a$, 그리고 $a^2$, $a^2+a$, $a^2+2a$ 는 어떤 순서로 놓일까?","식":["$a<3a$","$a^2<a^2+a<a^2+2a$","$a<3a\\le a^2<a^2+a<a^2+2a$"],"설명":"$a^2$ 이 가운데 값이려면 $a^2$ 보다 작거나 같은 값이 $a$, $3a$ 두 개이고 큰 값이 $a^2+a$, $a^2+2a$ 두 개여야 한다.","확인":null,"스킬":"C2"},{"제목":"최빈값 조건으로 식 세우기","고비":true,"힌트":"$a^2$ 이 최빈값이면 $a^2$ 은 몇 번 나와야 할까?","식":["$3a=a^2$"],"설명":"최빈값이 되려면 $a^2$ 과 같은 값이 하나 더 있어야 한다. $a^2\\ge3a>a$ 이므로 $a^2$ 과 같을 수 있는 값은 $3a$ 뿐이다.","확인":null,"스킬":"C2"},{"제목":"$a$ 의 값 구하기","힌트":"$a(a-3)=0$ 에서 자연수인 $a$ 는?","식":["$a(a-3)=0$","$a=3$"],"설명":"$a$ 가 자연수이므로 $a=0$ 은 될 수 없고 $a=3$ 이다.","확인":"3","스킬":"C2"}],"fb":"fig/ns/"},"ns-9b68e2e482e6":{"길":"평균을 $5$ 로 잘못 본 분산에서 변량의 제곱의 합을 구한 뒤, 평균 $6$ 을 기준으로 분산을 다시 계산한다.","단계":[{"제목":"다섯 수의 합 구하기","힌트":"평균이 $6$ 이면 다섯 수의 합은?","식":["$a+b+c+d+e=30$"],"설명":"평균에 개수 $5$ 를 곱한 값이 합이다.","확인":"30","스킬":"C7"},{"제목":"잘못 본 분산으로 편차의 제곱합 세우기","힌트":"평균을 $5$ 로 보고 구한 분산이 $4$ 이면 $5$ 를 기준으로 한 편차의 제곱합은?","식":["$(a-5)^2+(b-5)^2+(c-5)^2+(d-5)^2+(e-5)^2=20$"],"설명":"분산에 개수 $5$ 를 곱한 값이 편차의 제곱합이다.","확인":"20","스킬":"C7"},{"제목":"제곱의 합 구하기","고비":true,"힌트":"편차의 제곱합을 전개하고 합 $30$ 을 대입하면?","식":["$(a^2+\\cdots+e^2)-10\\times30+125=20$","$a^2+b^2+c^2+d^2+e^2=195$"],"설명":"$(a-5)^2=a^2-10a+25$ 이므로 다섯 개를 더해 전개한다.","확인":null,"스킬":"A2"},{"제목":"원래 분산 구하기","힌트":"평균 $6$ 을 기준으로 편차의 제곱합을 전개하면?","식":["$\\frac{195-12\\times30+180}{5}=\\frac{15}{5}=3$"],"설명":"$(a-6)^2=a^2-12a+36$ 이므로 다섯 개를 더하면 $(a^2+\\cdots+e^2)-12\\times30+5\\times36$ 이다.","확인":"3","스킬":"A2"}],"fb":"fig/ns/"},"ns-9c86fee6e5d8":{"길":"처음 따라낸 양을 $x$ 로 두고, 두 번째에는 섞인 통에서 원액과 물이 비율대로 빠지는 것을 반영해 최종 물과 원액의 양을 쓴 뒤 비례식을 푼다.","단계":[{"제목":"첫 번째 뒤의 원액과 물의 양","힌트":"원액 $x\\,L$ 를 따라내고 같은 양의 물을 채우면 통 속의 원액과 물은 각각 몇 $L$ 일까?","식":["$\\text{원액}=48-x$","$\\text{물}=x$"],"설명":"따라낸 만큼 물을 채우므로 통 속의 전체 양은 계속 $48\\,L$ 이다.","확인":null,"스킬":"C7"},{"제목":"두 번째에 따라낼 때 빠지는 양","고비":true,"힌트":"$48\\,L$ 중 원액과 물이 섞여 있을 때, $(x+4)\\,L$ 를 따라내면 원액과 물은 각각 얼마나 빠질까?","식":["$\\text{빠진 원액}=(x+4)\\times\\frac{48-x}{48}$","$\\text{빠진 물}=(x+4)\\times\\frac{x}{48}$"],"설명":"두 번째에는 처음보다 $4\\,L$ 더 따라내므로 $(x+4)\\,L$ 이다. 섞인 액체는 전체 $48\\,L$ 에서 원액과 물의 비율대로 빠진다.","확인":null,"스킬":"C7"},{"제목":"마지막에 남은 물과 원액의 양","힌트":"물은 남은 양에 새로 채운 양을 더하고, 원액은 남은 양만 쓰면?","식":["$\\text{물}=x-(x+4)\\times\\frac{x}{48}+(x+4)$","$\\text{원액}=(48-x)-(x+4)\\times\\frac{48-x}{48}$"],"설명":"두 번째에도 따라낸 $(x+4)\\,L$ 만큼 물을 채우므로 물에는 $(x+4)$ 가 더해진다.","확인":null,"스킬":"C5"},{"제목":"비례식을 풀어 $x$ 구하기","힌트":"물과 원액의 양의 비가 $3:5$ 라는 식을 세워 정리하면?","식":["$\\left\\{x-\\frac{x(x+4)}{48}+(x+4)\\right\\}:\\left\\{(48-x)-\\frac{(x+4)(48-x)}{48}\\right\\}=3:5$","$x^2-92x+672=0$","$(x-8)(x-84)=0$"],"설명":"비례식에서 내항의 곱과 외항의 곱이 같다는 것을 써서 $x$ 에 관한 이차방정식으로 만든다.","확인":null,"스킬":"C7"},{"제목":"조건에 맞는 근 고르기","힌트":"처음에 따라낸 양은 통 안의 원액 $48\\,L$ 를 넘을 수 있을까?","식":["$0<x<48$ 이므로 $x=8$"],"설명":"따라낸 양은 $0$ 보다 크고 $48$ 보다 작아야 하므로 $x=84$ 는 버린다.","확인":"8","스킬":"C7"}],"fb":"fig/ns/"},"ns-a464da4a877a":{"길":"둘레의 합으로 반지름의 합과 평균을 구하고, 표준편차로 반지름의 제곱의 합을 구한 뒤 넓이의 평균에 넣는다.","단계":[{"제목":"반지름의 합과 평균 구하기","힌트":"원의 둘레는 $2\\pi r$ 이다. 다섯 원의 둘레의 합이 $20\\pi$ 이면 반지름의 합은?","식":["$2\\pi(r_1+r_2+r_3+r_4+r_5)=20\\pi$","$r_1+r_2+r_3+r_4+r_5=10$, 평균 $=2$"],"설명":"둘레의 합에서 $2\\pi$ 로 나누면 반지름의 합이고, $5$ 로 나누면 평균이다.","확인":"10","스킬":"C7"},{"제목":"반지름의 제곱의 합 구하기","고비":true,"힌트":"표준편차가 $\\sqrt{2}$ 이면 분산은 얼마이고, 편차의 제곱합은?","식":["$(r_1-2)^2+\\cdots+(r_5-2)^2=5\\times2=10$","$(r_1^2+\\cdots+r_5^2)-4\\times10+20=10$","$r_1^2+r_2^2+r_3^2+r_4^2+r_5^2=30$"],"설명":"분산은 표준편차의 제곱인 $2$ 이다. 편차의 제곱합을 전개하고 반지름의 합 $10$ 을 대입한다.","확인":null,"스킬":"A2"},{"제목":"넓이의 평균 구하기","힌트":"원의 넓이는 $\\pi r^2$ 이다. 다섯 원의 넓이의 합을 $5$ 로 나누면?","식":["$\\frac{\\pi(r_1^2+r_2^2+r_3^2+r_4^2+r_5^2)}{5}=\\pi\\times\\frac{30}{5}=6\\pi$"],"설명":"넓이의 합은 $\\pi$ 에 반지름의 제곱의 합을 곱한 것이다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-a720f04dbf2f":{"길":"직각이등변삼각형의 한 예각의 이등분선을 그어 $22.5^{\\circ}$ 를 낀 직각삼각형을 만들고, 각의 이등분선의 성질로 변의 길이를 구한다.","단계":[{"제목":"보조선 긋기","고비":true,"힌트":"$45^{\\circ}$ 의 절반인 $22.5^{\\circ}$ 를 만들려면 어떤 선을 그어야 할까?","식":["$\\angle C=90^\\circ,\\ \\overline{AC}=\\overline{BC}=a$","$\\overline{AB}=\\sqrt{2}\\,a$"],"설명":"$\\angle C=90^\\circ$ 인 직각이등변삼각형 $ABC$ 에서 $\\angle A$ 의 이등분선이 $\\overline{BC}$ 와 만나는 점을 $D$ 라 하면 $\\angle CAD=22.5^\\circ$ 이다.","확인":null,"스킬":"S2"},{"제목":"각의 이등분선의 성질 쓰기","힌트":"$\\angle A$ 의 이등분선은 대변 $\\overline{BC}$ 를 어떤 두 변의 비로 나눌까?","식":["$\\overline{BD}:\\overline{CD}=\\overline{AB}:\\overline{AC}=\\sqrt{2}:1$"],"설명":"삼각형에서 한 각의 이등분선은 대변을 그 각을 낀 두 변의 길이의 비로 나눈다.","확인":null,"스킬":"S2"},{"제목":"$\\overline{CD}$ 의 길이 구하기","힌트":"$\\overline{BC}$ 를 $\\sqrt{2}:1$ 로 나눈 것 중 $\\overline{CD}$ 는 전체의 얼마일까?","식":["$\\overline{CD}=\\frac{1}{\\sqrt{2}+1}\\overline{BC}=(\\sqrt{2}-1)\\,a$"],"설명":"$\\overline{BC}=a$ 를 $\\sqrt{2}:1$ 로 나눈 작은 쪽이며, 분모를 유리화한다.","확인":null,"스킬":"S2"},{"제목":"$\\tan22.5^{\\circ}$ 구하기","힌트":"직각삼각형 $ADC$ 에서 $\\tan$ 는 어느 두 변의 비일까?","식":["$\\tan22.5^\\circ=\\frac{\\overline{CD}}{\\overline{AC}}=\\frac{(\\sqrt{2}-1)\\,a}{a}=\\sqrt{2}-1$"],"설명":"$\\angle CAD=22.5^\\circ$ 이므로 밑변 $\\overline{AC}$ 에 대한 높이 $\\overline{CD}$ 의 비가 $\\tan22.5^\\circ$ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-a8a2311e2647":{"길":"편차로 $A$ 의 횟수가 중앙값임을 확인한 뒤, 나머지 두 학생이 $A$ 의 아래·위에 놓이는 순서를 경우로 나누어 $x$ 의 범위를 구한다.","단계":[{"제목":"$A$ 의 횟수와 중앙값 확인","힌트":"편차는 (횟수)-(평균) 이다. 편차가 $3$ 인 $A$ 의 횟수는?","식":["$120+3=123$"],"설명":"평균이 $120$ 회이므로 $A$ 의 횟수는 $123$ 회이고 중앙값과 같다.","확인":"123","스킬":"C7"},{"제목":"가운데에 $A$ 가 오는 순서 나누기","고비":true,"힌트":"$A$ 가 가운데이려면 $D$ 와 $E$ 중 누가 $A$ 보다 작아야 할까?","식":["$B,\\ D,\\ A,\\ E,\\ C$","$B,\\ E,\\ A,\\ D,\\ C$"],"설명":"$B$ 는 편차가 $-12$ 로 $A$ 보다 작고 $C$ 는 편차가 $5$ 로 $A$ 보다 크다. 나머지 $D$, $E$ 중 어느 쪽이 $A$ 보다 작은지에 따라 두 경우로 나눈다.","확인":null,"스킬":"C2"},{"제목":"(ⅰ) 의 조건 구하기","힌트":"$D$ 의 편차가 $A$ 보다 작고 $E$ 의 편차가 $A$ 보다 크다는 식을 세우면?","식":["$3-x\\le3\\le x+1$","$x\\ge0,\\ x\\ge2$, 즉 $x\\ge2$"],"설명":"횟수의 크기 순서는 편차의 크기 순서와 같으므로 편차끼리 비교한다.","확인":null,"스킬":"C2"},{"제목":"(ⅱ) 의 조건과 $x$ 의 최솟값","힌트":"(ⅱ) 에서 $x$ 의 범위는 $x>0$ 과 함께 만족될 수 있을까?","식":["$x+1\\le3\\le3-x$","$x\\le2,\\ x\\le0$"],"설명":"$x>0$ 이므로 (ⅱ) 를 만족하는 $x$ 는 없다. 따라서 (ⅰ) 에서 $x$ 의 최솟값은 $2$ 이다.","확인":"2","스킬":"C2"}],"fb":"fig/ns/"},"ns-ab91fcaa70e9":{"길":"대각선과 평행한 변이 만드는 작은 직각이등변삼각형의 변을 $x$ 로 두어 직사각형의 가로·세로를 나타내고, 넓이의 이차식에서 최댓값일 때의 둘레를 구한다.","단계":[{"제목":"도형의 점과 길이 정하기","힌트":"정사각형의 대각선은 서로를 어떻게 나눌까?","식":["$\\overline{OA}=\\overline{OD}=12\\times\\frac{1}{2}=6$"],"설명":"정사각형 $ABCD$ 의 대각선 $AC$, $BD$ 의 교점을 $O$, 직사각형 $EFGH$ 의 꼭짓점 $E$, $F$, $G$, $H$ 를 각각 변 $AD$, $AB$, $BC$, $CD$ 위의 점이라 한다. $EF$ 와 $AC$ 의 교점을 $P$, $EH$ 와 $BD$ 의 교점을 $S$ 라 하면, 정사각형의 두 대각선은 서로를 이등분하므로 $\\overline{OA}=\\overline{OD}=6$ 이다.","확인":null,"스킬":"S2"},{"제목":"가로와 세로를 $x$ 로 나타내기","고비":true,"힌트":"$\\overline{EF}$ 는 $\\overline{BD}$ 와 평행하다. $\\triangle APE$ 는 어떤 삼각형일까?","식":["$\\overline{AP}=\\overline{PE}=x$","$\\overline{ES}=6-x,\\ \\overline{EH}=12-2x,\\ \\overline{FE}=2x$"],"설명":"$\\overline{EF}\\parallel\\overline{BD}$ 이므로 $\\triangle APE\\sim\\triangle AOD$ 이고, $\\triangle AOD$ 가 직각이등변삼각형이므로 $\\triangle APE$ 도 직각이등변삼각형이다. 직사각형은 두 대각선에 대해 대칭이므로 $P$, $S$ 는 각각 $\\overline{EF}$, $\\overline{EH}$ 의 중점이다.","확인":null,"스킬":"S1"},{"제목":"넓이를 $x$ 의 이차식으로 나타내기","힌트":"직사각형의 넓이는 가로와 세로의 곱이다. 완전제곱 꼴로 고치면?","식":["$y=(12-2x)\\times2x=-4x^2+24x$","$=-4(x-3)^2+36$"],"설명":"넓이를 $y$ 라 하고 완전제곱 꼴로 고치면 $x=3$ 일 때 최댓값 $36$ 을 가진다.","확인":null,"스킬":"G7"},{"제목":"둘레의 길이 구하기","힌트":"$x=3$ 일 때 가로와 세로는?","식":["$\\overline{FE}=2\\times3=6,\\ \\overline{EH}=12-2\\times3=6$","$2\\times(6+6)=24$"],"설명":"넓이가 최대일 때의 가로와 세로를 더해 $2$ 배한다.","확인":"24","스킬":"G7"}],"fb":"fig/ns/"},"ns-c41802b7ca33":{"길":"최빈값과 중앙값이 $178$ 이라는 조건으로 선수의 키를 문자로 놓고, 두 쿼터의 평균 조건에서 $E$ 의 키를 구한 뒤 $3$ 쿼터의 중앙값을 읽는다.","단계":[{"제목":"$1$ 쿼터 선수의 키를 문자로 놓기","고비":true,"힌트":"중앙값과 최빈값이 모두 $178$ 이면 $178$ 은 최소 몇 번 나올까?","식":["$a,\\ 178,\\ 178,\\ d,\\ x$","$\\frac{a+178+178+d+x}{5}=180$","$a+d+x=544$"],"설명":"최빈값이 $178$ 이므로 $178$ 이 두 번 나온다고 보고, 나머지 선수의 키를 $a$, $d$, $E$ 의 키를 $x$ 라 한다.","확인":null,"스킬":"C7"},{"제목":"$3$ 쿼터의 평균 조건 세우기","힌트":"$E$ 대신 키가 $178$ 인 $F$ 가 들어오면 선수들의 키는?","식":["$a,\\ 178,\\ 178,\\ 178,\\ d$","$\\frac{a+178+178+178+d}{5}=181$","$a+d=371$"],"설명":"$E$ 가 빠지고 $F$ 의 키 $178$ 이 들어간 다섯 명의 평균이 $181$ 이다.","확인":null,"스킬":"C7"},{"제목":"$E$ 의 키 구하기","힌트":"$a+d+x=544$ 에서 $a+d$ 를 빼면?","식":["$x=544-371=173$"],"설명":"두 식을 비교해 $x$ 를 구한다.","확인":"173","스킬":"C7"},{"제목":"$3$ 쿼터의 중앙값과 $x-y$ 구하기","힌트":"$3$ 쿼터 선수의 키 중 $178$ 은 몇 번 나올까?","식":["$y=178$","$x-y=173-178=-5$"],"설명":"$3$ 쿼터의 키는 $a$, $178$, $178$, $178$, $d$ 로 $178$ 이 세 번 나오므로 가운데 값은 $178$ 이다.","확인":"-5","스킬":"C2"}],"fb":"fig/ns/"},"ns-d38f3bef8f8c":{"길":"각 항의 근호를 간단히 해 $x$ 에 관한 일차방정식으로 정리하고, 해의 분모를 유리화한다.","단계":[{"제목":"근호가 있는 항 간단히 하기","힌트":"$\\sqrt{12}$, $\\sqrt{18}$ 을 간단히 하고 분모의 근호는 어떻게 없앨까?","식":["$\\sqrt{12}=2\\sqrt{3}$","$\\frac{\\sqrt{18}\\,x+\\sqrt{2}}{\\sqrt{2}}=3x+1$","$\\frac{6-\\sqrt{12}\\,x}{\\sqrt{3}}=2\\sqrt{3}-2x$"],"설명":"분자의 각 항을 $\\sqrt{2}$, $\\sqrt{3}$ 으로 나누어 근호를 정리한다.","확인":null,"스킬":"N8"},{"제목":"일차방정식 정리하기","힌트":"$x$ 가 있는 항은 왼쪽, 상수는 오른쪽으로 모으면?","식":["$2\\sqrt{3}\\,x-3x-1=2\\sqrt{3}-2x$","$(2\\sqrt{3}-1)\\,x=2\\sqrt{3}+1$"],"설명":"이항하여 $x$ 의 계수를 묶는다.","확인":null,"스킬":"N8"},{"제목":"분모 유리화하기","고비":true,"힌트":"$2\\sqrt{3}-1$ 의 분모를 유리화하려면 무엇을 곱할까?","식":["$x=\\frac{2\\sqrt{3}+1}{2\\sqrt{3}-1}=\\frac{(2\\sqrt{3}+1)^2}{(2\\sqrt{3}-1)(2\\sqrt{3}+1)}$","$=\\frac{13+4\\sqrt{3}}{11}$"],"설명":"분모와 분자에 $2\\sqrt{3}+1$ 을 곱하면 분모가 $(a-b)(a+b)=a^2-b^2$ 꼴이 되어 유리수가 된다.","확인":null,"스킬":"N8"}],"fb":"fig/ns/"},"ns-d4b8998b440a":{"길":"바구니 한 개에 든 초콜릿 수를 $n$ 으로 나타내고, 바구니·상자·낱개의 합이 $336$ 이라는 식을 세워 푼다.","단계":[{"제목":"바구니 한 개의 초콜릿 수 구하기","고비":true,"힌트":"바구니 한 개에는 상자가 몇 개 들어 있고, 상자 한 개에는 초콜릿이 몇 개일까?","식":["$n(3n+1)$"],"설명":"한 상자에 $n$ 개씩 담고 상자 $(3n+1)$ 개가 한 바구니가 되므로 바구니 한 개에는 $n(3n+1)$ 개가 들어 있다.","확인":null,"스킬":"C7"},{"제목":"전체 개수로 식 세우기","힌트":"바구니 $4$ 개, 상자 $3$ 개, 낱개 $1$ 개를 모두 더하면?","식":["$4n(3n+1)+3n+1=336$","$12n^2+7n-335=0$"],"설명":"바구니 $4$ 개의 초콜릿 수, 상자 $3$ 개의 초콜릿 수 $3n$, 남은 $1$ 개의 합이 $336$ 이다.","확인":null,"스킬":"C7"},{"제목":"인수분해로 $n$ 구하기","힌트":"$12n^2+7n-335$ 를 인수분해하면?","식":["$(n-5)(12n+67)=0$","$n=5$"],"설명":"$n$ 은 양수이므로 $n=5$ 이다.","확인":"5","스킬":"C7"}],"fb":"fig/ns/"},"ns-d7315acd59de":{"길":"$P$ 의 좌표를 문자로 놓고 $Q$ 의 좌표를 구한 뒤, 같은 높이의 두 점 사이 거리를 $x$ 좌표의 차로 쓴 이차식의 최솟값을 구한다.","단계":[{"제목":"두 점의 좌표 놓기","고비":true,"힌트":"$P$ 에서 $x$ 축에 평행하게 그으면 $P$ 와 $Q$ 는 어떤 좌표가 같을까?","식":["$P(p,\\ p^2+3)$","$p^2+3=x-1$","$Q(p^2+4,\\ p^2+3)$"],"설명":"$P$ 와 $Q$ 는 $y$ 좌표가 같다. $Q$ 는 직선 $y=x-1$ 위의 점이므로 $y=p^2+3$ 을 넣어 $x$ 좌표를 구한다.","확인":null,"스킬":"S4"},{"제목":"$\\overline{PQ}$ 를 $p$ 로 나타내기","힌트":"$x$ 축에 평행한 선분의 길이는 두 점의 어떤 좌표의 차일까?","식":["$\\overline{PQ}=(p^2+4)-p=p^2-p+4$"],"설명":"$y$ 좌표가 같은 두 점 사이의 거리는 $x$ 좌표의 차이다.","확인":null,"스킬":"S4"},{"제목":"최솟값 구하기","힌트":"$p^2-p+4$ 를 완전제곱 꼴로 고치면?","식":["$\\overline{PQ}=\\left(p-\\frac{1}{2}\\right)^2+\\frac{15}{4}$"],"설명":"$p=\\frac{1}{2}$ 일 때 $\\overline{PQ}$ 가 최소이고, 최솟값은 $\\frac{15}{4}$ 이다.","확인":"15/4","스킬":"A6"}],"fb":"fig/ns/"},"ns-df43c0064c42":{"길":"잘못 기록된 자료에서 바뀌지 않는 세 학생의 합과 편차의 제곱합을 구한 뒤, 실제 값 두 개를 넣어 평균과 분산을 다시 구한다.","단계":[{"제목":"나머지 세 학생의 합 구하기","힌트":"잘못 기록된 자료의 평균이 $40$ 이면 나머지 세 학생의 합은?","식":["$\\frac{a+b+c+39+43}{5}=40$","$a+b+c=118$"],"설명":"잘못 기록된 두 값 $39$, $43$ 을 뺀 나머지 세 학생의 횟수를 $a$, $b$, $c$ 라 한다.","확인":"118","스킬":"C7"},{"제목":"세 학생의 편차의 제곱합 구하기","고비":true,"힌트":"표준편차가 $2$ 이면 편차의 제곱합은 얼마일까?","식":["$(a-40)^2+(b-40)^2+(c-40)^2+(-1)^2+3^2=5\\times2^2$","$(a-40)^2+(b-40)^2+(c-40)^2=10$"],"설명":"표준편차의 제곱이 분산 $4$ 이고, 분산에 $5$ 를 곱한 값 $20$ 이 편차의 제곱합이다.","확인":null,"스킬":"A2"},{"제목":"실제 평균 구하기","힌트":"실제 자료는 $a,\\ b,\\ c,\\ 37,\\ 45$ 이다. 평균은?","식":["$\\frac{118+37+45}{5}=40$"],"설명":"합이 $200$ 으로 그대로이므로 평균도 $40$ 이다.","확인":"40","스킬":"C7"},{"제목":"실제 분산과 표준편차 구하기","힌트":"평균 $40$ 을 기준으로 $37$, $45$ 의 편차의 제곱을 더하면?","식":["$\\frac{10+(-3)^2+5^2}{5}=\\frac{44}{5}=8.8$","$\\sqrt{8.8}$"],"설명":"분산의 양의 제곱근이 표준편차이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-e403105d8945":{"길":"추가한 변량을 문자로 두고 새 평균과 편차를 나타낸 뒤 분산 식을 세워 완전제곱식으로 푼다","단계":[{"제목":"새 평균을 x로 나타내기","힌트":"네 변량의 합을 변량의 개수로 나누면 평균은 어떻게 쓸까?","식":["$\\frac{1+3+5+x}{4}=\\frac{9+x}{4}$"],"설명":"추가한 변량을 $x$라 하면 변량이 4개가 되므로 평균은 네 변량의 합을 4로 나눈 값이다.","확인":null,"스킬":"C7"},{"제목":"네 변량의 편차 구하기","힌트":"각 변량에서 평균을 빼면 편차는 어떤 식이 될까?","식":["$1-\\frac{9+x}{4}=\\frac{-5-x}{4},\\ \\ 3-\\frac{9+x}{4}=\\frac{3-x}{4}$","$5-\\frac{9+x}{4}=\\frac{11-x}{4}$","$x-\\frac{9+x}{4}=\\frac{3x-9}{4}$"],"설명":"편차는 (변량)-(평균)이다. 분모를 4로 통분해 정리한다.","확인":null,"스킬":"C7"},{"제목":"분산 식 세우기","힌트":"분산은 편차의 제곱의 평균이다. 네 편차를 어떻게 써서 분산이 2라는 식을 만들까?","식":["$\\frac{(-5-x)^{2}+(3-x)^{2}+(11-x)^{2}+(3x-9)^{2}}{16}\\times\\frac{1}{4}=2$","$\\frac{12x^{2}-72x+236}{16}=8$"],"설명":"네 편차의 제곱의 합을 4로 나눈 값이 분산 2이다. 분자를 전개하면 $12x^{2}-72x+236$이다.","확인":null,"스킬":"C7","고비":true},{"제목":"이차방정식 풀기","힌트":"양변에 16을 곱해 정리한 식을 인수분해하면?","식":["$x^{2}-6x+9=0$","$(x-3)^{2}=0$","$x=3$"],"설명":"양변에 16을 곱해 $12x^{2}-72x+108=0$으로 만들고 12로 나누면 완전제곱식이 된다. 따라서 $x=3$이다.","확인":"3","스킬":"A6"}],"fb":"fig/ns/"},"ns-eb9fd636ddbc":{"길":"근의 공식의 근호 안이 제곱수일 조건으로 a의 후보를 좁힌다","단계":[{"제목":"근호 안의 식 구하기","힌트":"계수 2, $-3$, $a-4$를 근의 공식에 넣으면 근호 안은 어떤 식일까?","식":["$x=\\frac{3\\pm\\sqrt{41-8a}}{4}$"],"설명":"이차항의 계수 2, 일차항의 계수 $-3$, 상수항 $a-4$를 근의 공식에 넣으면 근호 안은 $9-8(a-4)=41-8a$이다.","확인":null,"스킬":"N8"},{"제목":"유리수가 되는 조건 세우기","힌트":"근호 안의 수가 어떤 수일 때 해가 유리수가 될까?","식":["$41-8a=0,\\ 1,\\ 4,\\ 9,\\ 16,\\ 25,\\ 36$"],"설명":"해가 유리수이려면 근호 안이 0 또는 제곱수여야 한다. $a$가 자연수이므로 $41-8a$는 41보다 작다. 따라서 0 이상 41 미만의 제곱수만 가능하다.","확인":null,"스킬":"N8","고비":true},{"제목":"자연수 a 찾아 더하기","힌트":"각 경우에서 $8a$의 값을 구하면 $a$가 자연수인 것은 어느 것일까?","식":["$8a=41,\\ 40,\\ 37,\\ 32,\\ 25,\\ 16,\\ 5$","$a=5,\\ 4,\\ 2$","$5+4+2=11$"],"설명":"$8a$가 8의 배수인 경우만 $a$가 자연수가 되므로 $a=5,\\ 4,\\ 2$이다. 이 값을 모두 더한다.","확인":"11","스킬":"P4"}],"fb":"fig/ns/"},"ns-f5ec0ab7d17b":{"길":"자료 A의 중앙값 조건으로 b를 정한 뒤 합친 자료의 중앙값 식에서 a를 구한다","단계":[{"제목":"b의 값 정하기","힌트":"5개 자료의 중앙값 15는 크기순 몇 번째 값이고, $a\\ge b$는 어떻게 쓰일까?","식":["$b=15$"],"설명":"자료 $A$의 10, 14, 22 중에는 15가 없으므로 15는 $a$ 또는 $b$이다. $a\\ge b$에서 $b$가 15보다 작으면 3번째 값이 15가 될 수 없으므로 $b=15$이다.","확인":null,"스킬":"C2","고비":true},{"제목":"두 자료 정리하기","힌트":"$b=15$를 넣으면 두 자료는 어떻게 쓸 수 있을까?","식":["$A:\\ 10,\\ 14,\\ 15,\\ a,\\ 22$","$B:\\ 11,\\ a,\\ 14,\\ 21,\\ 22$"],"설명":"$b-1=14$이다. 두 자료에 모두 $a$가 들어 있다.","확인":null,"스킬":"C2"},{"제목":"합친 자료를 크기순으로 나열하기","힌트":"10개 자료의 중앙값은 몇 번째와 몇 번째 값의 평균일까?","식":["$10,\\ 11,\\ 14,\\ 14,\\ 15,\\ a,\\ a,\\ 21,\\ 22,\\ 22$"],"설명":"자료가 10개이므로 중앙값은 5번째와 6번째 값의 평균이다. $a\\ge15$이고 $a$가 21보다 크면 6번째 값이 21이 되어 중앙값이 18이므로 맞지 않는다. 따라서 $15\\le a\\le21$로 놓고 나열한다.","확인":null,"스킬":"P4"},{"제목":"a, b의 값 구하기","힌트":"5번째와 6번째 값의 평균이 16이 되도록 식을 세우면?","식":["$\\frac{15+a}{2}=16$","$a=17,\\ a+b=32$"],"설명":"$a=17$은 $15\\le a\\le21$을 만족한다. $b=15$이므로 $a+b=32$이다.","확인":"32","스킬":"P4"}],"fb":"fig/ns/"},"ns-f5f811ac5665":{"길":"평균이 변하지 않음을 확인한 뒤 편차의 제곱의 합에서 잘못된 두 값의 몫만 실제 값으로 바꾼다","단계":[{"제목":"평균이 변하지 않음 확인하기","힌트":"잘못 기록된 두 값의 합과 실제 두 값의 합을 비교하면?","식":["$47+51=98,\\ \\ 53+45=98$"],"설명":"두 값의 합이 같으므로 10명 전체의 합이 변하지 않고 평균은 그대로 50개이다.","확인":null,"스킬":"C5"},{"제목":"잘못 기록된 편차 제곱의 합 구하기","힌트":"분산이 10이고 학생이 10명이면 편차의 제곱의 합은 얼마일까?","식":["$10\\times10=100$"],"설명":"분산은 편차의 제곱의 평균이므로 편차의 제곱의 합은 분산에 학생 수를 곱한 값이다.","확인":null,"스킬":"C5"},{"제목":"실제 편차 제곱의 합 구하기","힌트":"잘못 기록된 두 학생의 편차의 제곱은 빼고 실제 두 학생의 편차의 제곱은 더하면?","식":["$53-50=3,\\ 45-50=-5$","$47-50=-3,\\ 51-50=1$","$100-3^{2}-(-5)^{2}+(-3)^{2}+1^{2}=76$"],"설명":"잘못 기록된 두 값의 편차는 $3,\\ -5$이고 실제 값의 편차는 $-3,\\ 1$이다. 나머지 8명의 편차는 그대로이다.","확인":null,"스킬":"C5","고비":true},{"제목":"실제 분산 구하기","힌트":"편차의 제곱의 합을 학생 수로 나누면?","식":["$\\frac{76}{10}=7.6$"],"설명":"실제 편차의 제곱의 합 76을 학생 수 10으로 나눈다.","확인":"7.6","스킬":"C5"}],"fb":"fig/ns/"},"ns-faf5e79116d0":{"길":"한 번 퍼내고 물을 넣은 뒤의 농도를 문자로 나타내고 같은 과정을 한 번 더 식으로 세운다","단계":[{"제목":"첫 번째 뒤의 농도 구하기","힌트":"$x$ g을 퍼낼 때 소금은 얼마나 함께 나가고, 물을 부은 뒤 농도를 $A\\%$라 하면 소금의 양은 어떻게 비교할까?","식":["$100\\times\\frac{10}{100}-x\\times\\frac{10}{100}=100\\times\\frac{A}{100}$","$A=10-\\frac{1}{10}x$"],"설명":"퍼낸 소금물의 농도는 $10\\%$이므로 $x$ g 속 소금은 $x\\times\\frac{10}{100}$ g이다. 물을 부어도 소금의 양은 그대로이므로 농도를 $A\\%$로 놓고 소금의 양을 비교한다.","확인":null,"스킬":"C7"},{"제목":"두 번째 과정으로 식 세우기","힌트":"농도가 $A\\%$인 소금물에서 $2x$ g을 퍼내고 물을 넣어 $4.8\\%$가 되었다면 소금의 양은 어떻게 쓸까?","식":["$100\\times\\frac{A}{100}-2x\\times\\frac{A}{100}=100\\times\\frac{4.8}{100}$","$1000-10x-20x+\\frac{1}{5}x^{2}=480$"],"설명":"$A=10-\\frac{1}{10}x$를 대입해 정리한다. 두 번째에도 퍼낸 소금물의 농도는 $A\\%$이다.","확인":null,"스킬":"A1","고비":true},{"제목":"이차방정식 풀기","힌트":"양변에 5를 곱하면 인수분해할 수 있는 식이 될까?","식":["$\\frac{1}{5}x^{2}-30x+520=0$","$x^{2}-150x+2600=0$","$(x-130)(x-20)=0$"],"설명":"양변에 5를 곱해 계수를 정수로 만든 뒤 인수분해한다.","확인":null,"스킬":"C7"},{"제목":"조건에 맞는 값 고르기","힌트":"처음 소금물이 100 g일 때 퍼내는 양의 범위는?","식":["$x=20$"],"설명":"처음 100 g에서 $x$ g과 $2x$ g을 차례로 퍼내므로 $x$는 양수이고 100보다 작아야 한다. 130은 맞지 않으므로 $x=20$이다.","확인":"20","스킬":"C7"}],"fb":"fig/ns/"},"ns-fdfe7c347a4c":{"길":"원가를 문자로 두고 정가·판매가를 나타내 이익 조건으로 방정식을 세운다","단계":[{"제목":"정가와 판매가 나타내기","힌트":"원가를 $a$원이라 하면 정가는 원가의 몇 배이고, 판매가는 정가의 몇 배일까?","식":["$\\text{정가}=a\\left(1+\\frac{x}{100}\\right)$","$\\text{판매가}=a\\left(1+\\frac{x}{100}\\right)\\left(1-\\frac{x}{200}\\right)$"],"설명":"정가는 원가에 $x\\%$의 이익을 더한 값이고, 판매가는 정가에서 $\\frac{x}{2}\\%$를 할인한 값이다.","확인":null,"스킬":"C7","고비":true},{"제목":"이익 조건으로 방정식 세우기","힌트":"원가의 $12.5\\%$가 이익이면 판매가는 원가의 몇 배일까?","식":["$\\left(1+\\frac{x}{100}\\right)\\left(1-\\frac{x}{200}\\right)=\\frac{112.5}{100}$","$(100+x)(200-x)=22500$"],"설명":"판매가가 원가의 $\\frac{112.5}{100}$배이므로 양변을 $a$로 나눈다. 양변에 20000을 곱하면 정수 계수 식이 된다.","확인":null,"스킬":"C7"},{"제목":"이차방정식 풀기","힌트":"정리한 식의 좌변은 어떤 꼴의 식일까?","식":["$x^{2}-100x+2500=0$","$(x-50)^{2}=0$","$x=50$"],"설명":"좌변을 전개해 정리하면 완전제곱식이 되므로 $x=50$이다.","확인":"50","스킬":"A6"}],"fb":"fig/ns/"},"ns-01b8059c3be7":{"길":"호의 길이로 두 원주각을 구하고 삼각형의 외각 성질로 ∠x 를 구한다","단계":[{"제목":"∠ACB 구하기","힌트":"호의 길이가 원 둘레의 $\\frac{1}{5}$이면 그 호에 대한 원주각은 몇 도일까?","식":["$\\angle\\mathrm{ACB}=\\frac{1}{5}\\times180^{\\circ}=36^{\\circ}$"],"설명":"한 원에서 원주각의 크기는 호의 길이에 비례하며, 원 전체에 해당하는 원주각의 크기를 $180^{\\circ}$로 본다.","확인":"36","스킬":"S5"},{"제목":"∠CBD 구하기","힌트":"호의 길이의 비가 $1:2$이면 원주각의 비는 어떻게 될까?","식":["$\\angle\\mathrm{CBD}=2\\angle\\mathrm{ACB}=72^{\\circ}$"],"설명":"호 $\\mathrm{CD}$에 대한 원주각 $\\angle\\mathrm{CBD}$는 호 $\\mathrm{AB}$에 대한 원주각 $\\angle\\mathrm{ACB}$의 2배이다.","확인":"72","스킬":"S5"},{"제목":"외각의 성질로 ∠x 구하기","힌트":"두 현 $\\mathrm{AC}$, $\\mathrm{BD}$의 교점을 $\\mathrm{P}$라 하면 $\\angle x$는 삼각형 $\\mathrm{PBC}$의 어떤 각일까?","식":["$\\angle x=\\angle\\mathrm{PBC}+\\angle\\mathrm{PCB}=72^{\\circ}+36^{\\circ}=108^{\\circ}$"],"설명":"두 현의 교점을 $\\mathrm{P}$라 하면 $\\angle x$는 삼각형 $\\mathrm{PBC}$에서 꼭짓점 $\\mathrm{P}$의 외각이므로 이웃하지 않는 두 내각의 합과 같다.","확인":"108","스킬":"S10","고비":true}],"fb":"fig/ns/"},"ns-0d3d996759b9":{"길":"접선과 현이 이루는 각으로 원주각을 구하고 이등변삼각형의 성질로 남은 각을 구한다","단계":[{"제목":"∠BPA 구하기","힌트":"접선과 현 $\\mathrm{AB}$가 이루는 각은 그 현에 대한 원주각과 어떤 관계일까?","식":["$\\angle\\mathrm{BPA}=\\angle\\mathrm{BAT}=65^{\\circ}$"],"설명":"접선과 현이 이루는 각의 크기는 그 각 안에 있는 호에 대한 원주각의 크기와 같다.","확인":"65","스킬":"S5","고비":true},{"제목":"∠BAP 구하기","힌트":"두 호의 길이가 같으면 두 현의 길이는 어떻고, 삼각형 $\\mathrm{PAB}$는 어떤 삼각형일까?","식":["$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{PB}}$","$\\angle\\mathrm{BAP}=\\angle\\mathrm{BPA}=65^{\\circ}$"],"설명":"한 원에서 길이가 같은 호에 대한 현의 길이도 같으므로 삼각형 $\\mathrm{PAB}$는 $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{PB}}$인 이등변삼각형이다. 이등변삼각형의 두 밑각은 같다.","확인":"65","스킬":"S10"},{"제목":"∠PBA 구하기","힌트":"삼각형 $\\mathrm{PAB}$의 세 내각의 합을 이용하면?","식":["$\\angle\\mathrm{PBA}=180^{\\circ}-2\\times65^{\\circ}=50^{\\circ}$"],"설명":"삼각형의 세 내각의 합은 $180^{\\circ}$이다.","확인":"50","스킬":"S10"}],"fb":"fig/ns/"},"ns-10d1f6d17d63":{"길":"꼭짓점 A에서 BC에 수선을 내려 두 직각삼각형에서 삼각비로 길이를 차례로 구한다","단계":[{"제목":"수선 AH의 길이 구하기","힌트":"점 $\\mathrm{A}$에서 변 $\\mathrm{BC}$에 내린 수선의 발을 $\\mathrm{H}$라 하면 삼각형 $\\mathrm{ACH}$에서 $\\overline{\\mathrm{AH}}$는 $\\overline{\\mathrm{AC}}$와 어떤 삼각비로 이어질까?","식":["$\\overline{\\mathrm{AH}}=5\\sin45^{\\circ}=\\frac{5\\sqrt{2}}{2}$"],"설명":"점 $\\mathrm{A}$에서 변 $\\mathrm{BC}$에 내린 수선의 발을 $\\mathrm{H}$라 하자. 삼각형 $\\mathrm{ACH}$는 $\\angle\\mathrm{C}=45^{\\circ}$인 직각삼각형이므로 $\\overline{\\mathrm{AH}}=\\overline{\\mathrm{AC}}\\sin45^{\\circ}$이다.","확인":null,"스킬":"S2","고비":true},{"제목":"AB의 길이 구하기","힌트":"삼각형 $\\mathrm{ABH}$에서 $\\overline{\\mathrm{AH}}$와 $\\overline{\\mathrm{AB}}$는 $\\sin60^{\\circ}$로 어떻게 이어질까?","식":["$\\overline{\\mathrm{AB}}=\\frac{\\overline{\\mathrm{AH}}}{\\sin60^{\\circ}}=\\frac{5\\sqrt{2}}{2}\\times\\frac{2}{\\sqrt{3}}=\\frac{5\\sqrt{6}}{3}$"],"설명":"삼각형 $\\mathrm{ABH}$는 $\\angle\\mathrm{B}=60^{\\circ}$인 직각삼각형이므로 $\\sin60^{\\circ}=\\frac{\\overline{\\mathrm{AH}}}{\\overline{\\mathrm{AB}}}$이다. 분모를 유리화한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-16e24a5031cc":{"길":"중심에서 현에 수선을 내려 반 현의 길이를 피타고라스로 구한 뒤 두 배 한다","단계":[{"제목":"수선의 발 $H$ 잡기","고비":true,"힌트":"중심 $O$에서 현 $AB$에 수선을 내리면 그 길이는 어느 원의 반지름과 같을까?","식":["$\\overline{OH}=3$","$\\overline{OA}=4$"],"설명":"중심 $O$에서 $\\overline{AB}$에 내린 수선의 발을 $H$라 한다. $\\overline{AB}$가 작은 원에 접하므로 $H$는 접점이고, 접선은 접점을 지나는 반지름에 수직이므로 $\\overline{OH}$는 작은 원의 반지름 $3$이다. $A$는 큰 원 위의 점이므로 $\\overline{OA}=4$이다.","확인":null,"스킬":"S2"},{"제목":"$AH$ 구하기","힌트":"직각삼각형 $OAH$에서 빗변과 한 변을 알 때 나머지 변은?","식":["$\\overline{AH}=\\sqrt{4^{2}-3^{2}}=\\sqrt{7}$"],"설명":"$\\angle OHA=90^{\\circ}$인 직각삼각형 $OAH$에 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"},{"제목":"$AB$ 구하기","힌트":"원의 중심에서 현에 내린 수선은 그 현을 어떻게 나눌까?","식":["$\\overline{AB}=2\\overline{AH}=2\\sqrt{7}$"],"설명":"원의 중심에서 현에 내린 수선은 그 현을 이등분하므로 $\\overline{AB}=2\\overline{AH}$이다. 따라서 답은 ④이다.","확인":null,"스킬":"S2"}],"fb":"fig/ns/"},"ns-1c39ac442c02":{"길":"한 현의 중심까지 거리를 피타고라스로 구하고, 길이가 같은 현은 중심에서 같은 거리임을 쓴다","단계":[{"제목":"$AE$ 구하기","힌트":"중심에서 현에 내린 수선은 그 현을 어떻게 나눌까?","식":["$\\overline{AE}=\\frac{1}{2}\\overline{AB}=8$"],"설명":"길이가 $16$인 두 현을 $\\overline{AB}$, $\\overline{CD}$라 하고, 중심 $O$에서 $\\overline{AB}$, $\\overline{CD}$에 내린 수선의 발을 각각 $E$, $F$라 한다. 원의 중심에서 현에 내린 수선은 그 현을 이등분하므로 $\\overline{AE}=8$이다.","확인":"8","스킬":"S2"},{"제목":"$OE$ 구하기","힌트":"직각삼각형 $OAE$에서 빗변이 $10$, 한 변이 $8$일 때 나머지 변은?","식":["$\\overline{OE}=\\sqrt{10^{2}-8^{2}}=6$"],"설명":"$\\overline{OA}$는 반지름 $10$이고 $\\angle OEA=90^{\\circ}$이므로 피타고라스 정리를 쓴다.","확인":"6","스킬":"S3"},{"제목":"$x$ 구하기","고비":true,"힌트":"길이가 같은 두 현은 중심에서 어떤 거리에 있을까?","식":["$x=\\overline{OF}=\\overline{OE}=6$"],"설명":"$\\overline{AB}=\\overline{CD}$이므로 두 현은 중심으로부터 같은 거리에 있다. 그러므로 $x=\\overline{OF}=\\overline{OE}$이다.","확인":"6","스킬":"S5"}],"fb":"fig/ns/"},"ns-1ce236928c5f":{"길":"반지름을 $r$로 놓고 직각삼각형 $OAB$에 피타고라스 정리를 써서 $r$을 구한다","단계":[{"제목":"$OB$를 $r$로 나타내기","힌트":"$\\overline{OD}$가 반지름이고 $\\overline{BD}=4$이면 $\\overline{OB}$는 어떻게 쓸까?","식":["$\\overline{OA}=\\overline{OD}=r$","$\\overline{OB}=r-4$"],"설명":"원 $O$의 반지름을 $r$라 하면 $\\overline{OA}$, $\\overline{OD}$가 모두 반지름이다. $B$는 $\\overline{OD}$ 위의 점이므로 $\\overline{OB}=\\overline{OD}-\\overline{BD}=r-4$이다.","확인":null,"스킬":"S13"},{"제목":"피타고라스 식 세우기","고비":true,"힌트":"직각삼각형 $OAB$에서 세 변의 관계는?","식":["$r^{2}=8^{2}+(r-4)^{2}$"],"설명":"$\\overline{AC}\\perp\\overline{OD}$이므로 $\\angle OBA=90^{\\circ}$이다. 빗변이 $\\overline{OA}=r$, 나머지 두 변이 $\\overline{AB}=8$, $\\overline{OB}=r-4$인 직각삼각형이다.","확인":null,"스킬":"S3"},{"제목":"$r$ 구하기","힌트":"식을 전개하면 $r^{2}$ 항은 어떻게 될까?","식":["$8r=80$","$r=10$"],"설명":"$(r-4)^{2}=r^{2}-8r+16$이므로 양변의 $r^{2}$이 없어지고 $8r=80$이 된다.","확인":"10","스킬":"S3"},{"제목":"원의 넓이 구하기","힌트":"반지름이 $10$인 원의 넓이는?","식":["$\\pi\\times10^{2}=100\\pi$"],"설명":"반지름의 길이가 $10$인 원이므로 넓이는 $100\\pi$이다.","확인":null,"스킬":"S13"}],"fb":"fig/ns/"},"ns-1fe72ccdb785":{"길":"산책로를 가장자리로 모아 잔디밭을 하나의 직사각형으로 보고 넓이로 이차방정식을 세운다","단계":[{"제목":"잔디밭 넓이 식 세우기","고비":true,"힌트":"폭이 일정한 두 길을 가장자리로 밀면 잔디밭은 어떤 모양이 될까?","식":["$(18-x)(16-x)=195$"],"설명":"산책로의 폭을 $x$ m라 한다. 두 산책로를 가장자리로 옮겨도 잔디밭의 넓이는 변하지 않으므로, 가로가 $18-x$, 세로가 $16-x$인 직사각형의 넓이가 $195$이다.","확인":null,"스킬":"S12"},{"제목":"이차방정식 풀기","힌트":"전개해서 $x^{2}$의 계수가 $1$인 이차방정식으로 정리하면?","식":["$x^{2}-34x+93=0$","$(x-3)(x-31)=0$"],"설명":"$288-34x+x^{2}=195$를 정리하고 인수분해하면 $x=3$ 또는 $x=31$이다.","확인":null,"스킬":"S12"},{"제목":"알맞은 근 고르기","힌트":"산책로의 폭은 잔디밭의 세로 $16$보다 작아야 하지 않을까?","식":["$0<x<16$","$x=3$"],"설명":"$x=31$은 세로의 길이 $16$보다 크므로 알맞지 않고, 폭은 $x=3$ m이다.","확인":"3","스킬":"S12"}],"fb":"fig/ns/"},"ns-240ae615bed6":{"길":"한 점에서 그은 두 접선의 길이가 같음을 써서 $\\overline{BP}$를 $x$로 놓고 변의 길이로 식을 세운다","단계":[{"제목":"접선의 길이를 $x$로 나타내기","고비":true,"힌트":"원 밖의 한 점에서 원에 그은 두 접선의 길이는 어떤 관계일까?","식":["$\\overline{BP}=\\overline{BQ}=x$","$\\overline{AP}=\\overline{AR}=12-x$","$\\overline{CQ}=\\overline{CR}=14-x$"],"설명":"$\\overline{BP}=x$라 하자. 한 점에서 원에 그은 두 접선의 길이는 같으므로 $\\overline{BQ}=x$이고, $\\overline{AP}=\\overline{AB}-\\overline{BP}=12-x$, $\\overline{CQ}=\\overline{BC}-\\overline{BQ}=14-x$이다. 같은 성질로 $\\overline{AR}=12-x$, $\\overline{CR}=14-x$이다.","확인":null,"스킬":"S5"},{"제목":"$\\overline{AC}$로 식 세우기","힌트":"$\\overline{AC}$는 $\\overline{AR}$과 $\\overline{CR}$로 어떻게 쓸까?","식":["$(12-x)+(14-x)=10$"],"설명":"$R$가 $\\overline{AC}$ 위의 접점이므로 $\\overline{AC}=\\overline{AR}+\\overline{CR}$이다.","확인":null,"스킬":"S5"},{"제목":"$x$ 구하기","힌트":"일차방정식을 풀면?","식":["$2x=16$","$x=8$"],"설명":"$26-2x=10$이므로 $x=8$이고, $\\overline{BP}=8$이다.","확인":"8","스킬":"S5"}],"fb":"fig/ns/"},"ns-26b784b947f5":{"길":"접은 선이 $\\overline{OC}$를 수직이등분함을 찾아 $\\overline{OM}$을 구하고, 피타고라스로 $\\overline{AM}$을 구한다","단계":[{"제목":"$OM$ 구하기","고비":true,"힌트":"접은 선 $AB$는 $O$와 겹친 점을 이은 선분과 어떤 관계일까?","식":["$\\overline{OC}=6$","$\\overline{OM}=\\frac{1}{2}\\overline{OC}=3$"],"설명":"접기 전 원 위의 점으로 $O$와 겹치는 점을 $C$, $\\overline{OC}$와 $\\overline{AB}$의 교점을 $M$이라 한다. 접은 선 $AB$는 $\\overline{OC}$를 수직이등분하고 $\\overline{OC}$는 반지름이므로 $\\overline{OM}=3$이다.","확인":null,"스킬":"S2"},{"제목":"$AM$ 구하기","힌트":"직각삼각형 $OAM$에서 $\\overline{OA}$는 무엇과 같을까?","식":["$\\overline{OA}=6$","$\\overline{AM}=\\sqrt{6^{2}-3^{2}}=3\\sqrt{3}$"],"설명":"$A$는 원 위의 점이므로 $\\overline{OA}=6$이다. $\\angle OMA=90^{\\circ}$인 직각삼각형 $OAM$에 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"},{"제목":"$AB$ 구하기","힌트":"$M$은 현 $AB$의 어떤 점일까?","식":["$\\overline{AB}=2\\overline{AM}=6\\sqrt{3}$"],"설명":"$\\overline{OC}$가 $\\overline{AB}$를 수직이등분하므로 $M$은 $\\overline{AB}$의 중점이다.","확인":null,"스킬":"S2"}],"fb":"fig/ns/"},"ns-270ac0e645e5":{"길":"세 꼭짓점의 좌표를 구한 뒤 사다리꼴에서 두 삼각형의 넓이를 빼서 $\\triangle ABC$의 넓이를 구한다","단계":[{"제목":"$A$, $B$의 좌표 구하기","힌트":"$x$축, $y$축과 만나는 점은 각각 어떤 값을 대입해 구할까?","식":["$A(3,\\,0)$","$B(0,\\,-6)$"],"설명":"$y=0$을 대입하면 $x^{2}-2x-3=0$에서 $x=3$ 또는 $x=-1$이다. 그림에서 $A$는 $x$축의 양의 부분에 있으므로 $A(3,0)$이다. $x=0$을 대입하면 $y=-6$이므로 $B(0,-6)$이다.","확인":null,"스킬":"G1"},{"제목":"꼭짓점 $C$ 구하기","힌트":"완전제곱 꼴로 고치면 꼭짓점의 좌표는?","식":["$y=2(x-1)^{2}-8$","$C(1,\\,-8)$"],"설명":"$y=2x^{2}-4x-6=2(x^{2}-2x+1-1)-6=2(x-1)^{2}-8$이므로 꼭짓점은 $C(1,-8)$이다.","확인":null,"스킬":"G10"},{"제목":"넓이를 쪼개는 식 세우기","고비":true,"힌트":"$C$에서 $y$축에 수선을 내리면 사다리꼴에서 어떤 부분을 빼야 $\\triangle ABC$가 남을까?","식":["$\\triangle ABC=\\square OHCA-\\triangle OAB-\\triangle BCH$"],"설명":"$C$에서 $y$축에 내린 수선의 발을 $H(0,-8)$이라 한다. 사다리꼴 $OHCA$에서 $\\triangle OAB$와 $\\triangle BCH$를 빼면 $\\triangle ABC$가 남는다.","확인":null,"스킬":"G10"},{"제목":"넓이 계산하기","힌트":"사다리꼴과 두 삼각형의 넓이를 각각 구하면?","식":["$\\square OHCA=\\frac{1}{2}\\times(3+1)\\times8=16$","$\\triangle OAB=\\frac{1}{2}\\times3\\times6=9$, $\\triangle BCH=\\frac{1}{2}\\times1\\times2=1$","$\\triangle ABC=16-9-1=6$"],"설명":"사다리꼴의 윗변은 $\\overline{OA}=3$, 아랫변은 $\\overline{HC}=1$, 높이는 $8$이다. 세 넓이를 정리하면 $\\triangle ABC=6$이다.","확인":"6","스킬":"G10"}],"fb":"fig/ns/"},"ns-28e791f7f679":{"길":"$\\overline{OP}$의 연장선을 그어 두 할선의 길이의 곱이 같다는 성질로 반지름을 구한다","단계":[{"제목":"할선의 곱으로 식 세우기","고비":true,"힌트":"원 밖의 점 $P$에서 그은 두 직선에서 길이의 곱은 어떤 관계일까?","식":["$\\overline{PA}\\times\\overline{PB}=\\overline{PC}\\times\\overline{PD}$"],"설명":"$\\overline{OP}$의 연장선이 원과 만나는 점을 $D$라 한다. 원 밖의 점 $P$에서 원에 그은 두 할선에서 $\\overline{PA}\\times\\overline{PB}=\\overline{PC}\\times\\overline{PD}$가 성립한다.","확인":null,"스킬":"S5"},{"제목":"길이 대입하기","힌트":"$\\overline{PB}$와 $\\overline{PC}$, $\\overline{PD}$를 구하면?","식":["$\\overline{PA}\\times\\overline{PB}=9\\times15$","$\\overline{PC}\\times\\overline{PD}=(12-x)(12+x)$"],"설명":"원 $O$의 반지름을 $x$라 하면 $\\overline{OC}=\\overline{OD}=x$이므로 $\\overline{PC}=12-x$, $\\overline{PD}=12+x$이다. $\\overline{PB}=\\overline{PA}+\\overline{AB}=9+6=15$이다.","확인":null,"스킬":"S5"},{"제목":"$x$ 구하기","힌트":"$x^{2}$을 구한 뒤 반지름이 양수임을 쓰면?","식":["$135=144-x^{2}$","$x^{2}=9$","$x=3$"],"설명":"반지름은 양수이므로 $x=3$이다.","확인":"3","스킬":"S5"}],"fb":"fig/ns/"},"ns-2c3058aadef2":{"길":"닮은 삼각형으로 $\\angle BAC=\\angle EDC$임을 찾고 직각삼각형 $CDE$에서 $\\cos$를 구한다","단계":[{"제목":"같은 크기의 각 찾기","고비":true,"힌트":"$\\triangle ABC$와 $\\triangle DEC$가 공통으로 가진 각은 무엇일까?","식":["$\\angle BAE=\\angle BAC=\\angle EDC=x^{\\circ}$"],"설명":"두 삼각형 $ABC$, $DEC$에서 $\\angle C$는 공통이고 $\\angle B=\\angle DEC=90^{\\circ}$이므로 닮음이다. 따라서 $\\angle BAC=\\angle EDC$이고, $E$가 $\\overline{AC}$ 위의 점이므로 $\\angle BAE=\\angle BAC$이다.","확인":null,"스킬":"S10"},{"제목":"$DE$ 구하기","힌트":"직각삼각형 $CDE$에서 빗변이 $6$, 한 변이 $4$일 때 나머지 변은?","식":["$\\overline{DE}=\\sqrt{6^{2}-4^{2}}=2\\sqrt{5}$"],"설명":"$\\angle DEC=90^{\\circ}$이므로 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"},{"제목":"$\\cos x^{\\circ}$ 구하기","힌트":"$\\angle EDC$를 낀 변 중 직각이 아닌 쪽 변과 빗변의 비는?","식":["$\\cos x^{\\circ}=\\frac{\\overline{DE}}{\\overline{CD}}=\\frac{2\\sqrt{5}}{6}=\\frac{\\sqrt{5}}{3}$"],"설명":"직각삼각형 $CDE$에서 $\\angle EDC=x^{\\circ}$이므로 $\\cos x^{\\circ}$는 $\\overline{DE}$를 빗변 $\\overline{CD}$로 나눈 값이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-2dc6f46727c1":{"길":"큰 원의 반지름을 구하고, 두 중심을 잇는 직각삼각형의 세 변을 작은 원의 반지름 $r$로 나타내 피타고라스 정리를 쓴다","단계":[{"제목":"원 $O$의 반지름 구하기","힌트":"원 $O$가 마주 보는 두 변에 접하면 지름은 어느 변의 길이와 같을까?","식":["$\\frac{1}{2}\\times8=4$"],"설명":"원 $O$는 $\\overline{AD}$와 $\\overline{BC}$에 접하므로 지름이 $\\overline{AB}=8$이고 반지름은 $4$이다. 원 $O'$의 반지름은 $r$라 한다.","확인":"4","스킬":"S13"},{"제목":"직각삼각형의 세 변 나타내기","고비":true,"힌트":"$O$에서 $\\overline{BC}$에 내린 수선의 발을 $E$, $O'$에서 $\\overline{OE}$에 내린 수선의 발을 $H$라 하면 세 변은 각각 어떻게 쓸까?","식":["$\\overline{OO'}=4+r$","$\\overline{OH}=4-r$","$\\overline{HO'}=5-r$"],"설명":"두 원이 외접하므로 $\\overline{OO'}=4+r$이다. $O'$에서 $\\overline{BC}$까지의 거리가 $r$이므로 $\\overline{OH}=4-r$이고, $O'$에서 $\\overline{CD}$까지의 거리가 $r$이므로 $\\overline{HO'}=9-4-r=5-r$이다.","확인":null,"스킬":"S13"},{"제목":"피타고라스 식 세우기","힌트":"직각삼각형 $OHO'$에서 빗변은 어느 선분일까?","식":["$(4+r)^{2}=(4-r)^{2}+(5-r)^{2}$"],"설명":"$\\angle OHO'=90^{\\circ}$이므로 빗변 $\\overline{OO'}$의 제곱이 나머지 두 변의 제곱의 합과 같다.","확인":null,"스킬":"S3"},{"제목":"$r$ 구하기","힌트":"전개해서 정리하면 $r$에 대한 이차방정식은?","식":["$r^{2}-26r+25=0$","$(r-1)(r-25)=0$","$r=1$"],"설명":"$0<r<4$이므로 $r=1$이다.","확인":"1","스킬":"S3"},{"제목":"둘레의 합 구하기","힌트":"두 원의 반지름을 알면 둘레의 합은?","식":["$2\\pi\\times4+2\\pi\\times1=10\\pi$"],"설명":"원 $O$의 둘레는 $8\\pi$, 원 $O'$의 둘레는 $2\\pi$이다.","확인":null,"스킬":"S13"}],"fb":"fig/ns/"},"ns-2fff97efa517":{"길":"점 C에서 AB에 수선을 내려 특수각이 들어 있는 직각삼각형 둘로 AB를 나누어 구한다","단계":[{"제목":"수선의 발 H 정하기","고비":true,"힌트":"점 C에서 AB에 수선을 내리면 어떤 직각삼각형 둘이 생길까?","식":["$\\triangle \\mathrm{BCH},\\ \\triangle \\mathrm{ACH}$"],"설명":"점 C에서 $\\overline{\\mathrm{AB}}$에 내린 수선의 발을 H라 하면 삼각형 BCH와 삼각형 ACH가 직각삼각형이 된다. $\\angle \\mathrm{B}=45^\\circ$이므로 $\\angle \\mathrm{BCH}=45^\\circ$이다.","확인":null,"스킬":"S2"},{"제목":"BH, CH 구하기","힌트":"빗변이 $4$이고 한 각이 $45^\\circ$인 직각삼각형에서 두 변은 어떤 삼각비로 나타낼까?","식":["$\\overline{\\mathrm{BH}}=4\\cos45^\\circ=2\\sqrt{2}$","$\\overline{\\mathrm{CH}}=4\\sin45^\\circ=2\\sqrt{2}$"],"설명":"삼각형 BCH에서 빗변 BC의 길이가 $4$이므로 삼각비로 BH와 CH를 구한다.","확인":null,"스킬":"S6"},{"제목":"AH 구하기","힌트":"$\\angle \\mathrm{ACH}$의 크기는 얼마이고, 이 각의 탄젠트는 어떤 변의 비일까?","식":["$\\angle \\mathrm{ACH}=105^\\circ-45^\\circ=60^\\circ$","$\\overline{\\mathrm{AH}}=\\overline{\\mathrm{CH}}\\tan60^\\circ=2\\sqrt{6}$"],"설명":"$\\angle \\mathrm{ACH}$는 $\\angle \\mathrm{ACB}$에서 $\\angle \\mathrm{BCH}$를 뺀 값이다. 삼각형 ACH에서 AH는 CH의 $\\tan60^\\circ$배이다.","확인":null,"스킬":"S6"},{"제목":"AB 구하기","힌트":"$\\overline{\\mathrm{AB}}$를 $\\overline{\\mathrm{BH}}$와 $\\overline{\\mathrm{AH}}$로 나타내면?","식":["$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{BH}}+\\overline{\\mathrm{AH}}=2\\sqrt{2}+2\\sqrt{6}$"],"설명":"H가 선분 AB 위에 있으므로 두 길이를 더하면 AB이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-3376685ec19f":{"길":"사각형 APBO의 내각으로 중심각 AOB를 구하고, 점 C가 있는 큰 호의 중심각의 절반으로 원주각을 구한다","단계":[{"제목":"접점에서 직각 확인","힌트":"접선과 접점을 지나는 반지름은 어떤 각을 이룰까?","식":["$\\angle \\mathrm{PAO}=\\angle \\mathrm{PBO}=90^\\circ$"],"설명":"$\\overline{\\mathrm{OA}}$, $\\overline{\\mathrm{OB}}$를 그으면 접선은 접점을 지나는 반지름에 수직이므로 두 각은 모두 $90^\\circ$이다.","확인":null,"스킬":"S2"},{"제목":"중심각 AOB 구하기","힌트":"사각형 APBO의 네 내각의 합은 얼마일까?","식":["$\\angle \\mathrm{AOB}=360^\\circ-(30^\\circ+90^\\circ+90^\\circ)=150^\\circ$"],"설명":"사각형의 내각의 합은 $360^\\circ$이다.","확인":"150","스킬":"S10"},{"제목":"점 C가 있는 호의 중심각","고비":true,"힌트":"점 C는 중심각이 $150^\\circ$인 호와 그 반대쪽 호 중 어느 쪽에 있을까?","식":["$360^\\circ-150^\\circ=210^\\circ$"],"설명":"점 C는 큰 호 위에 있으므로 $\\angle \\mathrm{ACB}$가 마주 보는 호의 중심각은 $360^\\circ$에서 $150^\\circ$를 뺀 값이다.","확인":"210","스킬":"S5"},{"제목":"원주각 구하기","힌트":"한 호에 대한 원주각과 중심각의 크기는 어떤 관계일까?","식":["$\\angle \\mathrm{ACB}=\\frac{1}{2}\\times210^\\circ=105^\\circ$"],"설명":"원주각의 크기는 같은 호에 대한 중심각의 크기의 $\\frac{1}{2}$이다.","확인":"105","스킬":"S5"}],"fb":"fig/ns/"},"ns-35e50e18a92e":{"길":"밑면의 대각선 FH를 먼저 구하고 직각삼각형 DFH에서 DF를 구한 뒤 삼각비를 잡는다","단계":[{"제목":"밑면의 대각선 FH 구하기","힌트":"밑면 FGH는 어떤 직각삼각형일까?","식":["$\\overline{\\mathrm{FH}}=\\sqrt{4^2+3^2}=5$"],"설명":"밑면의 두 변이 $4$, $3$이고 그 사이각이 직각이다.","확인":"5","스킬":"S3"},{"제목":"대각선 DF 구하기","고비":true,"힌트":"삼각형 DFH는 어느 각이 직각이고, DF는 어떤 변일까?","식":["$\\overline{\\mathrm{DF}}=\\sqrt{\\overline{\\mathrm{FH}}^2+\\overline{\\mathrm{DH}}^2}=\\sqrt{5^2+5^2}=5\\sqrt{2}$"],"설명":"$\\overline{\\mathrm{DH}}$는 밑면에 수직이므로 삼각형 DFH는 $\\angle \\mathrm{DHF}=90^\\circ$인 직각삼각형이고 DF는 빗변이다.","확인":null,"스킬":"S11"},{"제목":"삼각비 세 값 구하기","힌트":"직각삼각형 DFH에서 $\\angle x$의 코사인, 사인, 탄젠트는 각각 어떤 변의 비일까?","식":["$\\cos x^\\circ=\\frac{5}{5\\sqrt{2}}=\\frac{\\sqrt{2}}{2}$","$\\sin x^\\circ=\\frac{\\sqrt{2}}{2}$","$\\tan x^\\circ=1$"],"설명":"$\\cos x^\\circ=\\frac{\\overline{\\mathrm{FH}}}{\\overline{\\mathrm{DF}}}$, $\\sin x^\\circ=\\frac{\\overline{\\mathrm{DH}}}{\\overline{\\mathrm{DF}}}$, $\\tan x^\\circ=\\frac{\\overline{\\mathrm{DH}}}{\\overline{\\mathrm{FH}}}$이다.","확인":null,"스킬":"S6"},{"제목":"식의 값 계산","힌트":"세 값을 주어진 식에 넣으면?","식":["$\\frac{\\sqrt{2}}{2}+\\frac{\\sqrt{2}}{2}-1=\\sqrt{2}-1$"],"설명":"앞 두 항을 더하면 $\\sqrt{2}$이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-3b07eb6cda6f":{"길":"성의 높이를 x로 놓고 두 직각삼각형에서 BH와 CH를 x로 나타낸 뒤 BC의 길이로 방정식을 세운다","단계":[{"제목":"높이를 x로 두고 수선의 발 정하기","고비":true,"힌트":"성의 높이를 어떤 선분으로 보고, 어떤 직각삼각형 둘을 만들 수 있을까?","식":["$\\overline{\\mathrm{AH}}=x$"],"설명":"점 A에서 $\\overline{\\mathrm{BC}}$의 연장선에 내린 수선의 발을 H라 하고 성의 높이를 $\\overline{\\mathrm{AH}}=x$라 하면 직각삼각형 ABH와 ACH가 생긴다.","확인":null,"스킬":"C7"},{"제목":"BH, CH를 x로 나타내기","힌트":"각 BAH와 각 CAH는 각각 몇 도이고, 밑변은 높이의 몇 배일까?","식":["$\\overline{\\mathrm{BH}}=x\\tan60^\\circ=\\sqrt{3}x$","$\\overline{\\mathrm{CH}}=x\\tan45^\\circ=x$"],"설명":"$\\angle \\mathrm{BAH}=60^\\circ$, $\\angle \\mathrm{CAH}=45^\\circ$이므로 각각 높이에 탄젠트를 곱해 밑변을 구한다.","확인":null,"스킬":"S6"},{"제목":"식 세우기","힌트":"BC는 BH와 CH로 어떻게 나타낼 수 있을까?","식":["$\\overline{\\mathrm{BC}}=\\overline{\\mathrm{BH}}-\\overline{\\mathrm{CH}}$","$\\sqrt{3}x-x=10$"],"설명":"점 C는 B와 H 사이에 있으므로 BC는 BH에서 CH를 뺀 길이이고 $10$이다.","확인":null,"스킬":"C7"},{"제목":"x 구하기","힌트":"$(\\sqrt{3}-1)x=10$에서 분모의 근호는 어떻게 없앨까?","식":["$x=\\frac{10}{\\sqrt{3}-1}=\\frac{10(\\sqrt{3}+1)}{(\\sqrt{3}-1)(\\sqrt{3}+1)}=5(\\sqrt{3}+1)$"],"설명":"분모와 분자에 $\\sqrt{3}+1$을 곱해 분모를 유리화한다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-3b9e91c12343":{"길":"각 B를 x로 두고 내접 사각형의 외각과 삼각형의 외각으로 삼각형 CDF의 세 각을 x로 나타낸다","단계":[{"제목":"각 CDF를 x로 나타내기","힌트":"원에 내접하는 사각형 ABCD에서 한 외각과 크기가 같은 내각은 어느 것일까?","식":["$\\angle \\mathrm{B}=x$","$\\angle \\mathrm{CDF}=x$"],"설명":"내접 사각형에서 한 외각의 크기는 그 대각의 크기와 같으므로 $\\angle \\mathrm{CDF}=\\angle \\mathrm{B}=x$이다.","확인":null,"스킬":"S5"},{"제목":"각 DCF를 x로 나타내기","고비":true,"힌트":"삼각형 BCE에서 점 C의 바깥쪽 각은 어떤 두 각의 합일까?","식":["$\\angle \\mathrm{DCF}=\\angle \\mathrm{B}+\\angle \\mathrm{E}=x+44^\\circ$"],"설명":"삼각형의 한 외각은 이웃하지 않는 두 내각의 합과 같다.","확인":null,"스킬":"S10"},{"제목":"삼각형 CDF의 내각의 합으로 x 구하기","힌트":"삼각형 CDF의 세 각을 모두 더하면 얼마일까?","식":["$(x+44^\\circ)+x+42^\\circ=180^\\circ$","$2x=94^\\circ,\\ x=47^\\circ$"],"설명":"삼각형 CDF의 세 내각은 $x$, $x+44^\\circ$, $42^\\circ$이다.","확인":"47","스킬":"S10"}],"fb":"fig/ns/"},"ns-3d31973695ee":{"길":"호 BC에 대한 원주각을 x로 두고 삼각형의 외각의 성질을 두 번 써서 x에 관한 방정식을 세운다","단계":[{"제목":"같은 호의 원주각 표시","힌트":"호 BC에 대한 원주각인 각 BAC와 각 BDC의 크기는 어떤 관계일까?","식":["$\\angle \\mathrm{BAC}=\\angle \\mathrm{BDC}=x$"],"설명":"한 호에 대한 원주각의 크기는 모두 같다.","확인":null,"스킬":"S5"},{"제목":"각 ACD를 x로 나타내기","고비":true,"힌트":"삼각형 AQC에서 점 C의 바깥쪽 각은 어떤 두 각의 합일까?","식":["$\\angle \\mathrm{ACD}=\\angle \\mathrm{AQC}+\\angle \\mathrm{QAC}=30^\\circ+x$"],"설명":"점 B가 $\\overline{\\mathrm{AQ}}$ 위에 있으므로 $\\angle \\mathrm{QAC}=\\angle \\mathrm{BAC}=x$이다. 삼각형의 한 외각은 이웃하지 않는 두 내각의 합이다.","확인":null,"스킬":"S10"},{"제목":"삼각형 CPD의 외각으로 식 세우기","힌트":"각 APD는 삼각형 CPD의 어느 각의 바깥쪽 각일까?","식":["$\\angle \\mathrm{APD}=\\angle \\mathrm{PCD}+\\angle \\mathrm{PDC}$","$(30^\\circ+x)+x=78^\\circ$"],"설명":"$\\angle \\mathrm{APD}$는 삼각형 CPD의 점 P에서의 외각이다. $\\angle \\mathrm{PCD}=\\angle \\mathrm{ACD}$이고 $\\angle \\mathrm{PDC}=\\angle \\mathrm{BDC}=x$이다.","확인":null,"스킬":"S10"},{"제목":"x 구하기","힌트":"x에 관한 일차방정식을 풀면?","식":["$2x=48^\\circ,\\ x=24^\\circ$"],"설명":"$\\angle \\mathrm{BDC}=x$이므로 구하는 값은 $24^\\circ$이다.","확인":"24","스킬":"S10"}],"fb":"fig/ns/"},"ns-3e51099b1e51":{"길":"접선의 길이를 x로 두어 세 변을 나타내고 내심에서 세 꼭짓점을 이어 넓이를 세 삼각형의 합으로 구한다","단계":[{"제목":"접선의 길이를 문자로 두기","힌트":"한 점에서 원에 그은 두 접선의 길이는 어떤 관계일까?","식":["$\\overline{\\mathrm{BQ}}=\\overline{\\mathrm{BP}}=x$","$\\overline{\\mathrm{AP}}=\\overline{\\mathrm{AR}}=6-x$"],"설명":"점 B에서 그은 두 접선의 길이가 같으므로 $\\overline{\\mathrm{BP}}=\\overline{\\mathrm{BQ}}=x$이다. $\\overline{\\mathrm{AB}}=6$이므로 $\\overline{\\mathrm{AP}}=6-x$이고, 점 A에서 그은 접선이므로 $\\overline{\\mathrm{AR}}$도 같다.","확인":null,"스킬":"S5"},{"제목":"점 C 쪽 접선의 길이 구하기","힌트":"$\\angle \\mathrm{C}=90^\\circ$이고 $\\overline{\\mathrm{OQ}}=1$일 때 사각형 OQCR는 어떤 도형일까?","식":["$\\overline{\\mathrm{CQ}}=\\overline{\\mathrm{CR}}=1$"],"설명":"$\\overline{\\mathrm{OQ}}\\perp\\overline{\\mathrm{BC}}$, $\\overline{\\mathrm{OR}}\\perp\\overline{\\mathrm{CA}}$이고 $\\angle \\mathrm{C}=90^\\circ$이므로 사각형 OQCR는 한 변이 $1$인 정사각형이다.","확인":"1","스킬":"S5"},{"제목":"두 변의 길이를 x로 나타내기","힌트":"BC와 CA를 접선의 길이의 합으로 나타내면?","식":["$\\overline{\\mathrm{BC}}=x+1$","$\\overline{\\mathrm{CA}}=1+(6-x)=7-x$"],"설명":"$\\overline{\\mathrm{BC}}=\\overline{\\mathrm{BQ}}+\\overline{\\mathrm{QC}}$, $\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CR}}+\\overline{\\mathrm{RA}}$이다.","확인":null,"스킬":"S5"},{"제목":"넓이를 세 삼각형으로 쪼개기","고비":true,"힌트":"내심 O와 세 꼭짓점을 이으면 삼각형 ABC는 어떤 세 삼각형으로 나뉠까?","식":["$\\triangle \\mathrm{ABC}=\\triangle \\mathrm{OBC}+\\triangle \\mathrm{OCA}+\\triangle \\mathrm{OAB}$","$=\\frac{1}{2}\\times1\\times(x+1)+\\frac{1}{2}\\times1\\times(7-x)+\\frac{1}{2}\\times1\\times6$"],"설명":"내접원의 반지름 $1$이 세 삼각형의 높이이므로 각 삼각형의 넓이는 변의 길이의 $\\frac{1}{2}$이다.","확인":null,"스킬":"S8"},{"제목":"넓이 계산","힌트":"x가 들어 있는 항을 모으면 어떻게 될까?","식":["$\\triangle \\mathrm{ABC}=\\frac{1}{2}\\{(x+1)+(7-x)+6\\}=7$"],"설명":"$x$가 있는 항은 서로 없어지고 세 변의 길이의 합 $14$의 $\\frac{1}{2}$만 남는다.","확인":"7","스킬":"S8"}],"fb":"fig/ns/"},"ns-42a4c092e3e9":{"길":"꼭짓점 B에서 AC에 수선을 내려 BC가 빗변인 삼각형에서 BH를 구하고, 삼각형 ABH에서 AB를 구한다","단계":[{"제목":"수선의 발 H 정하기","고비":true,"힌트":"꼭짓점 B에서 AC에 수선을 내리면 알려진 각과 변이 어느 삼각형에 들어갈까?","식":["$\\overline{\\mathrm{BH}}\\perp\\overline{\\mathrm{AC}}$"],"설명":"꼭짓점 B에서 $\\overline{\\mathrm{AC}}$에 내린 수선의 발을 H라 하면 삼각형 BCH에는 $\\angle \\mathrm{C}=45^\\circ$와 $\\overline{\\mathrm{BC}}=6$이 모두 들어 있다.","확인":null,"스킬":"S2"},{"제목":"BH 구하기","힌트":"빗변이 $6$이고 한 각이 $45^\\circ$일 때 BH는 어떤 삼각비로 나타낼까?","식":["$\\overline{\\mathrm{BH}}=6\\sin45^\\circ=3\\sqrt{2}$"],"설명":"삼각형 BCH에서 BH는 $\\angle \\mathrm{C}$의 대변이다.","확인":null,"스킬":"S6"},{"제목":"각 A 구하기","힌트":"삼각형 ABC의 세 내각의 합을 이용하면 각 A는 얼마일까?","식":["$\\angle \\mathrm{BAH}=\\angle \\mathrm{A}=180^\\circ-(75^\\circ+45^\\circ)=60^\\circ$"],"설명":"두 각 $\\angle \\mathrm{B}$, $\\angle \\mathrm{C}$가 모두 예각이므로 H는 변 AC 위에 있다.","확인":"60","스킬":"S10"},{"제목":"AB 구하기","힌트":"삼각형 ABH에서 BH는 AB와 어떤 삼각비로 이어질까?","식":["$\\overline{\\mathrm{AB}}=\\frac{\\overline{\\mathrm{BH}}}{\\sin60^\\circ}=3\\sqrt{2}\\times\\frac{2}{\\sqrt{3}}=2\\sqrt{6}$"],"설명":"$\\sin60^\\circ=\\frac{\\overline{\\mathrm{BH}}}{\\overline{\\mathrm{AB}}}$이므로 AB는 BH를 $\\sin60^\\circ$로 나눈 값이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-43276e18d370":{"길":"PO를 그어 직각삼각형 APO에서 PA를 구한 뒤 삼각형 APB가 정삼각형임을 이용해 AB를 구한다","단계":[{"제목":"PO를 긋고 각 APO 구하기","고비":true,"힌트":"OA, OB가 접선에 수직이면 삼각형 APO와 삼각형 BPO는 어떤 관계일까?","식":["$\\triangle \\mathrm{APO}\\equiv\\triangle \\mathrm{BPO}\\ (\\mathrm{RHS})$","$\\angle \\mathrm{APO}=\\frac{1}{2}\\times60^\\circ=30^\\circ$"],"설명":"$\\angle \\mathrm{PAO}=\\angle \\mathrm{PBO}=90^\\circ$이고 PO는 공통, $\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}$이므로 두 삼각형은 RHS 합동이다.","확인":"30","스킬":"S2"},{"제목":"PA 구하기","힌트":"직각삼각형 APO에서 PA는 OA와 어떤 삼각비로 이어질까?","식":["$\\overline{\\mathrm{PA}}=\\frac{\\overline{\\mathrm{OA}}}{\\tan30^\\circ}=\\frac{\\sqrt{3}}{\\tan30^\\circ}=\\sqrt{3}\\times\\sqrt{3}=3$"],"설명":"$\\tan30^\\circ=\\frac{\\overline{\\mathrm{OA}}}{\\overline{\\mathrm{PA}}}$이다.","확인":"3","스킬":"S6"},{"제목":"삼각형 APB의 모양 알기","힌트":"$\\overline{\\mathrm{PA}}=\\overline{\\mathrm{PB}}$이고 $\\angle \\mathrm{P}=60^\\circ$이면 삼각형 APB는 어떤 삼각형일까?","식":["$\\overline{\\mathrm{PA}}=\\overline{\\mathrm{PB}},\\ \\angle \\mathrm{APB}=60^\\circ$"],"설명":"한 점에서 원에 그은 두 접선의 길이가 같으므로 삼각형 APB는 이등변삼각형이고, 꼭지각이 $60^\\circ$이므로 정삼각형이다.","확인":null,"스킬":"S5"},{"제목":"AB 구하기","힌트":"정삼각형에서 세 변의 길이는 어떤 관계일까?","식":["$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{PA}}=3$"],"설명":"정삼각형의 세 변의 길이는 모두 같다.","확인":"3","스킬":"S5"}],"fb":"fig/ns/"},"ns-0a1635fed159":{"길":"겉넓이 식을 세워 $a$ 를 분리하고 분모를 유리화해 $a$ 를 구한다","단계":[{"제목":"겉넓이 식 세우기","힌트":"가로 $a$, 세로 $\\sqrt{3}$, 높이 $\\sqrt{2}$ 인 직육면체의 겉넓이는 세 종류의 면으로 어떻게 나타낼까?","식":["$2(a\\sqrt{3}+a\\sqrt{2}+\\sqrt{3}\\times\\sqrt{2})=6\\sqrt{6}+10$"],"설명":"겉넓이는 서로 마주 보는 면 두 개씩의 넓이를 더한 것이다. $\\sqrt{3}\\times\\sqrt{2}=\\sqrt{6}$ 이다.","확인":null,"스킬":"C7","고비":true},{"제목":"$a$ 를 한쪽으로 모으기","힌트":"양변을 $2$ 로 나눈 뒤 $\\sqrt{6}$ 항을 우변으로 옮기면?","식":["$a(\\sqrt{3}+\\sqrt{2})+\\sqrt{6}=3\\sqrt{6}+5$","$a(\\sqrt{3}+\\sqrt{2})=2\\sqrt{6}+5$"],"설명":"양변을 $2$ 로 나누어 $a(\\sqrt{3}+\\sqrt{2})+\\sqrt{6}=3\\sqrt{6}+5$ 를 얻은 뒤 $\\sqrt{6}$ 을 이항한다.","확인":null,"스킬":"C7"},{"제목":"분모 유리화","힌트":"$\\sqrt{3}+\\sqrt{2}$ 로 나누려면 분모와 분자에 무엇을 곱할까?","식":["$a=\\frac{2\\sqrt{6}+5}{\\sqrt{3}+\\sqrt{2}}=\\frac{(2\\sqrt{6}+5)(\\sqrt{3}-\\sqrt{2})}{3-2}$","$a=6\\sqrt{2}-4\\sqrt{3}+5\\sqrt{3}-5\\sqrt{2}=\\sqrt{2}+\\sqrt{3}$"],"설명":"분모와 분자에 $\\sqrt{3}-\\sqrt{2}$ 를 곱하면 분모는 $3-2=1$ 이 된다. $2\\sqrt{6}\\times\\sqrt{3}=6\\sqrt{2}$, $2\\sqrt{6}\\times\\sqrt{2}=4\\sqrt{3}$ 임을 이용한다. 선지 ③ 이다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-0d73766ddaf3":{"길":"근호 부등식을 $ab$ 의 범위로 줄이고 가능한 눈의 쌍을 나열해 합의 최댓값을 찾는다","단계":[{"제목":"부등식을 $ab$ 의 범위로","힌트":"각 변이 양수일 때 $2<\\sqrt{2ab}<3$ 의 각 변을 제곱하면?","식":["$4<2ab<9$","$2<ab<\\frac{9}{2}$","$ab=3\\ \\text{또는}\\ ab=4$"],"설명":"$ab$ 는 자연수이므로 $2$ 보다 크고 $4.5$ 보다 작은 값은 $3$ 과 $4$ 이다.","확인":null,"스킬":"P4"},{"제목":"가능한 눈의 쌍","힌트":"주사위 눈 $a$, $b$ 의 곱이 $3$ 이거나 $4$ 인 순서쌍을 빠짐없이 나열하면?","식":["$ab=3:\\ (1,\\ 3),\\ (3,\\ 1)$","$ab=4:\\ (1,\\ 4),\\ (2,\\ 2),\\ (4,\\ 1)$"],"설명":"서로 다른 두 주사위이므로 $(1,\\ 3)$ 과 $(3,\\ 1)$ 은 다른 경우이다. 눈은 $1$ 부터 $6$ 까지이다.","확인":null,"스킬":"P4","고비":true},{"제목":"합의 최댓값","힌트":"각 순서쌍의 $a+b$ 를 구해 가장 큰 값을 고르면?","식":["$1+3=4,\\ 1+4=5,\\ 2+2=4$"],"설명":"가능한 $a+b$ 의 값은 $4$ 와 $5$ 이므로 가장 큰 값은 $5$ 이고 선지 ① 이다.","확인":"5","스킬":"P4"}],"fb":"fig/ns/"},"ns-13a6cb750cad":{"길":"세 정사각형의 변을 구하고 $y$ 축에 평행한 선분들이 만드는 닮은 삼각형의 비로 $\\overline{EB}$, $\\overline{HI}$ 를 잇는다","단계":[{"제목":"세 정사각형의 한 변","힌트":"넓이가 $1$, $\\frac{1}{2}$, $\\frac{1}{4}$ 인 정사각형의 한 변은?","식":["$\\overline{AO}=1$","$\\overline{BI}=\\sqrt{\\frac{1}{2}}=\\frac{\\sqrt{2}}{2}$","$\\overline{IK}=\\sqrt{\\frac{1}{4}}=\\frac{1}{2}$"],"설명":"한 변의 길이는 넓이의 양의 제곱근이다.","확인":null,"스킬":"S1"},{"제목":"$\\overline{OK}$ 의 길이","힌트":"$x$ 축 위의 $\\overline{OB}$, $\\overline{BI}$, $\\overline{IK}$ 를 이으면?","식":["$\\overline{OK}=1+\\frac{\\sqrt{2}}{2}+\\frac{1}{2}=\\frac{3+\\sqrt{2}}{2}$"],"설명":"$\\overline{OB}$ 는 첫 정사각형의 한 변이므로 $1$ 이다.","확인":null,"스킬":"S1"},{"제목":"닮은 삼각형 찾기","힌트":"$\\overline{AO}$, $\\overline{EB}$, $\\overline{HI}$ 는 서로 어떤 위치 관계일까?","식":["$\\triangle AOK\\backsim\\triangle EBK\\backsim\\triangle HIK$"],"설명":"$\\overline{AO}$, $\\overline{EB}$, $\\overline{HI}$ 는 모두 $x$ 축에 수직이어서 서로 평행하다. 각 $K$ 가 공통이고 동위각이 같으므로 세 삼각형은 AA 닮음이다.","확인":null,"스킬":"S1","고비":true},{"제목":"$\\overline{EB}$, $\\overline{HI}$ 구하기","힌트":"$\\overline{AO}=1$ 일 때 닮음비에서 $\\overline{EB}$ 와 $\\overline{HI}$ 는 각각 어떤 두 길이의 비일까?","식":["$\\overline{EB}:1=\\overline{BK}:\\overline{OK}$","$\\overline{EB}=\\frac{(1+\\sqrt{2})/2}{(3+\\sqrt{2})/2}=\\frac{1+\\sqrt{2}}{3+\\sqrt{2}}$","$\\overline{HI}=\\frac{1/2}{(3+\\sqrt{2})/2}=\\frac{1}{3+\\sqrt{2}}$"],"설명":"$\\overline{BK}=\\overline{OK}-1=\\frac{1+\\sqrt{2}}{2}$ 이고 $\\overline{IK}=\\frac{1}{2}$ 이다. 닮음비 $\\overline{EB}:\\overline{AO}=\\overline{BK}:\\overline{OK}$, $\\overline{HI}:\\overline{AO}=\\overline{IK}:\\overline{OK}$ 를 쓴다.","확인":null,"스킬":"S1"},{"제목":"합 구하고 분모 유리화","힌트":"두 길이를 더한 뒤 분모의 근호를 없애면?","식":["$\\frac{2+\\sqrt{2}}{3+\\sqrt{2}}=\\frac{(2+\\sqrt{2})(3-\\sqrt{2})}{(3+\\sqrt{2})(3-\\sqrt{2})}=\\frac{4+\\sqrt{2}}{7}$"],"설명":"분자 분모에 $3-\\sqrt{2}$ 를 곱하면 분모는 $9-2=7$ 이 되어 답은 선지 ③ 이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-2417a16fb262":{"길":"피타고라스로 $\\overline{CA}$ 를 구해 점 $P$ 의 위치와 $a$ 를 정하고 선지를 어림해 비교한다","단계":[{"제목":"$\\overline{CA}$ 의 길이","힌트":"모눈에서 $A$ 는 $C$ 로부터 가로와 세로로 얼마씩 떨어져 있을까?","식":["$\\overline{CA}=\\sqrt{3^{2}+1^{2}}=\\sqrt{10}$"],"설명":"그림에서 $A$ 는 $C$ 의 왼쪽 $3$ 칸, 위쪽 $1$ 칸에 있는 점이다.","확인":null,"스킬":"S3"},{"제목":"$a$ 를 식으로 나타내기","힌트":"$\\overline{CP}=\\overline{CA}$ 일 때 $P$ 에 대응하는 수와 $Q$ 에 대응하는 수는?","식":["$P=4-\\sqrt{10}$, $Q=5$","$a=5-(4-\\sqrt{10})=1+\\sqrt{10}$"],"설명":"$C$ 에 대응하는 수가 $4$ 이고 $P$ 는 $C$ 의 왼쪽에서 $\\sqrt{10}$ 만큼 떨어져 있다.","확인":null,"스킬":"S3","고비":true},{"제목":"$a$ 어림하기","힌트":"$\\sqrt{10}=3.162$ 일 때 $a$ 는 대략 얼마일까?","식":["$a=1+3.162=4.162$"],"설명":"$a$ 와 $5$ 사이의 수는 $4.162$ 보다 크고 $5$ 보다 작은 무리수이다.","확인":null,"스킬":"S3"},{"제목":"선지 비교","힌트":"선지마다 값을 어림해 $4.162$ 와 $5$ 사이에 있는지 확인하면?","식":["$\\sqrt{15}<4$, $\\frac{9}{5}+\\sqrt{5}\\approx4.04$, $4.5$, $\\frac{a}{2}+2\\approx4.08$, $a+\\frac{1}{2}\\approx4.66$"],"설명":"①, ②, ④ 는 $a$ 보다 작다. ③ 은 $a$ 와 $5$ 사이에 있지만 유리수이다. ⑤ 는 $4.162<4.66<5$ 이고 무리수이므로 선지 ⑤ 이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-2d3cb0ed9c64":{"길":"겹친 부분이 앞 정사각형의 한 변의 절반을 한 변으로 하는 정사각형임을 찾아 둘레에서 겹친 변을 뺀다","단계":[{"제목":"정사각형의 한 변","힌트":"넓이가 $3$, $5$, $8$, $12$ 인 정사각형의 한 변은?","식":["$\\sqrt{3},\\ \\sqrt{5},\\ 2\\sqrt{2},\\ 2\\sqrt{3}$"],"설명":"$\\sqrt{8}=2\\sqrt{2}$, $\\sqrt{12}=2\\sqrt{3}$ 으로 고친다.","확인":null,"스킬":"S12"},{"제목":"겹친 부분의 모양","힌트":"다음 정사각형의 꼭짓점이 앞 정사각형의 대각선의 교점에 있으면 겹친 부분은 앞 정사각형의 몇 분의 몇일까?","식":["$\\text{겹친 부분의 한 변}=\\frac{s}{2}$"],"설명":"앞 정사각형의 한 변을 $s$ 라 한다. 다음 정사각형의 꼭짓점이 앞 정사각형의 중심에 있고 두 정사각형의 변의 방향이 같으므로, 겹친 부분은 중심에서 앞 정사각형의 꼭짓점 쪽으로 이어지는 작은 정사각형이다. 그 한 변은 $\\frac{s}{2}$ 이다.","확인":null,"스킬":"S12","고비":true},{"제목":"겹칠 때마다 빠지는 둘레","힌트":"앞 정사각형의 한 변을 $s$ 라 할 때 겹친 곳에서 둘레는 얼마나 줄까?","식":["$\\frac{s}{2}\\times2+\\frac{s}{2}\\times2=2s$"],"설명":"앞 정사각형의 둘레 중 겹친 부분 안으로 들어가는 길이가 작은 정사각형의 두 변 $s$ 이고, 뒤 정사각형의 둘레 중 앞 정사각형 안으로 들어가는 길이도 $s$ 이다. 겹칠 때마다 둘레는 $2s$ 줄어든다.","확인":null,"스킬":"S12"},{"제목":"도형의 둘레","힌트":"네 정사각형의 둘레의 합에서 세 번 겹친 부분을 빼면?","식":["$4(\\sqrt{3}+\\sqrt{5}+2\\sqrt{2}+2\\sqrt{3})-2(\\sqrt{3}+\\sqrt{5}+2\\sqrt{2})$","$=10\\sqrt{3}+4\\sqrt{2}+2\\sqrt{5}$"],"설명":"겹치는 곳은 앞 세 정사각형과 뒤 정사각형 사이의 세 곳이므로 앞 세 정사각형의 한 변만 $2$ 배하여 뺀다. 선지 ② 이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-2ea318b94868":{"길":"정사각형의 대각선 길이를 구해 $F$ 에서 거꾸로 $B$, $C$, $E$ 의 위치를 잡는다","단계":[{"제목":"대각선의 길이","힌트":"넓이가 $4$ 인 정사각형의 한 변과 대각선은?","식":["한 변 $=2$","$\\overline{AC}=\\overline{BD}=2\\sqrt{2}$"],"설명":"한 변이 $2$ 이므로 대각선은 $2\\sqrt{2}$ 이다.","확인":null,"스킬":"S3"},{"제목":"점 $B$ 의 위치","힌트":"$\\overline{BF}=\\overline{BD}$ 이므로 $F$ 에서 $B$ 까지의 거리는?","식":["$\\overline{BF}=2\\sqrt{2}$","$B=8-2\\sqrt{2}$"],"설명":"점 $B$ 는 $F$ 의 왼쪽에 있다.","확인":null,"스킬":"S3","고비":true},{"제목":"점 $C$ 의 위치","힌트":"$B$ 와 $C$ 사이의 길이는 정사각형의 한 변과 같을까?","식":["$C=B+2=10-2\\sqrt{2}$"],"설명":"$\\overline{BC}=2$ 이고 $C$ 는 $B$ 의 오른쪽에 있다.","확인":null,"스킬":"S3"},{"제목":"점 $E$ 의 위치","힌트":"$\\overline{CE}=\\overline{CA}$ 이므로 $C$ 에서 왼쪽으로 얼마만큼 가면 $E$ 일까?","식":["$E=C-2\\sqrt{2}=10-4\\sqrt{2}$"],"설명":"$\\overline{CA}=2\\sqrt{2}$ 이므로 $E$ 에 대응하는 수는 $10-4\\sqrt{2}$ 이고 선지 ① 이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-41a0f79d3d32":{"길":"직사각형에서 정사각형을 차례로 떼어 내며 각 변을 구하고 반지름의 합으로 사분원 호의 길이를 더한다","단계":[{"제목":"정사각형 $A$ 와 $B$ 의 한 변","힌트":"세로가 $2$ 인 직사각형에서 가장 큰 정사각형의 한 변은? 그 오른쪽에 남는 직사각형의 가로는?","식":["$A$ 의 한 변 $=2$","$(1+\\sqrt{5})-2=\\sqrt{5}-1$"],"설명":"$A$ 를 떼어 내면 가로 $\\sqrt{5}-1$, 세로 $2$ 인 직사각형이 남는다. 짧은 변이 $\\sqrt{5}-1$ 이므로 $B$ 의 한 변은 $\\sqrt{5}-1$ 이다.","확인":null,"스킬":"S12"},{"제목":"정사각형 $C$ 의 한 변","힌트":"$B$ 를 떼어 낸 뒤 남는 직사각형의 짧은 변은?","식":["$2-(\\sqrt{5}-1)=3-\\sqrt{5}$"],"설명":"$B$ 아래에 가로 $\\sqrt{5}-1$, 세로 $3-\\sqrt{5}$ 인 직사각형이 남는다. $3-\\sqrt{5}<\\sqrt{5}-1$ 이므로 $C$ 의 한 변은 $3-\\sqrt{5}$ 이다.","확인":null,"스킬":"S12","고비":true},{"제목":"정사각형 $D$ 의 한 변","힌트":"$C$ 를 떼어 내고 남는 직사각형의 짧은 변은?","식":["$(\\sqrt{5}-1)-(3-\\sqrt{5})=2\\sqrt{5}-4$"],"설명":"남는 직사각형은 가로 $2\\sqrt{5}-4$, 세로 $3-\\sqrt{5}$ 이고 가로가 더 짧으므로 $D$ 의 한 변은 $2\\sqrt{5}-4$ 이다.","확인":null,"스킬":"S12"},{"제목":"호의 길이의 합","힌트":"사분원의 호의 길이는 반지름 $r$ 로 어떻게 나타낼까?","식":["$\\frac{1}{4}\\times2\\pi r=\\frac{\\pi r}{2}$","$\\frac{\\pi}{2}\\{2+(\\sqrt{5}-1)+(3-\\sqrt{5})+(2\\sqrt{5}-4)\\}=\\frac{\\pi}{2}\\times2\\sqrt{5}=\\sqrt{5}\\pi$"],"설명":"사분원 $A$, $B$, $C$, $D$ 의 반지름은 각각 정사각형의 한 변이다. 반지름의 합이 $2\\sqrt{5}$ 이므로 호의 길이의 합은 $\\sqrt{5}\\pi$ 이고 선지 ③ 이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-4d9f048e1b88":{"길":"모눈 한 칸의 넓이를 평행사변형 $OADE$ 의 넓이에서 구하고, 정사각형 $OABC$ 의 넓이로 한 변 $\\overline{OA}$ 를 구한다","단계":[{"제목":"$OADE$ 의 넓이를 모눈 칸 수로 세기","힌트":"$OADE$ 를 감싸는 직사각형에서 바깥쪽 삼각형들을 빼면 몇 칸일까?","식":["$5\\times3-(1+2+1+2)=9$"],"설명":"점 $O$ 에서 오른쪽으로 $1$칸, 위로 $2$칸 간 곳이 $A$ 이다. $OADE$ 를 감싸는 가로 $5$칸, 세로 $3$칸 직사각형은 $15$칸이고, 네 모서리의 직각삼각형은 각각 $1$칸, $2$칸, $1$칸, $2$칸이다.","확인":"9","스킬":"S12"},{"제목":"모눈 한 칸의 넓이","힌트":"$OADE$ 의 넓이 $54$ 는 모눈 $9$칸의 넓이이다. 한 칸의 넓이는?","식":["$9\\times(\\text{한 칸})=54$"],"설명":"한 칸의 가로와 세로 길이가 같으므로 한 칸은 넓이가 같은 정사각형이다. $54\\div9$ 로 한 칸의 넓이를 구한다.","확인":"6","스킬":"S12","고비":true},{"제목":"정사각형 $OABC$ 의 넓이","힌트":"$\\overline{OA}$ 를 한 변으로 하는 정사각형 $OABC$ 는 모눈 몇 칸일까?","식":["$3\\times3-4\\times1=5$","$5\\times6=30$"],"설명":"$OABC$ 를 감싸는 $3\\times3$ 정사각형은 $9$칸이고, 모서리의 직각삼각형 네 개가 각각 $1$칸이다. 따라서 $5$칸이고 넓이는 $5\\times6=30$ 이다.","확인":"30","스킬":"S12"},{"제목":"$\\overline{OA}$ 의 길이","힌트":"정사각형의 넓이가 $30$ 이면 한 변의 길이는?","식":["$\\overline{OA}^{2}=30$","$\\overline{OA}=\\sqrt{30}$"],"설명":"한 변의 길이는 넓이의 양의 제곱근이므로 $\\sqrt{30}$ 이고, 선지 ① 이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-6607399ec827":{"길":"넓이비를 변의 길이비로 바꿔 둘레의 식을 세우고, 분모를 유리화해 $\\mathrm{A}$ 의 한 변과 넓이를 구한다","단계":[{"제목":"세 정사각형의 변의 길이비","힌트":"정사각형의 넓이의 비가 $1:2:4$ 이면 한 변의 길이의 비는?","식":["$1:\\sqrt2:2$"],"설명":"닮은 도형에서 넓이의 비는 닮음비의 제곱이다. 넓이의 비 $1:2:4$ 의 양의 제곱근을 취하면 변의 길이의 비는 $1:\\sqrt2:2$ 이다.","확인":null,"스킬":"S1","고비":true},{"제목":"둘레를 $x$ 로 나타내기","힌트":"$\\mathrm{A}$ 의 한 변을 $x$ 라 할 때 계단 모양 도형의 둘레는 가로 전체와 세로 전체로 어떻게 쓸까?","식":["$2\\{(x+\\sqrt2x+2x)+2x\\}=46$"],"설명":"$\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$ 의 한 변은 $x$, $\\sqrt2x$, $2x$ 이다. 계단 모양의 둘레는 바깥을 둘러싼 직사각형의 둘레와 같고, 가로는 $(3+\\sqrt2)x$, 세로는 $2x$ 이다.","확인":null,"스킬":"C7"},{"제목":"$x$ 의 값","힌트":"$(10+2\\sqrt2)x=46$ 에서 $x$ 의 분모를 유리화하면?","식":["$x=\\frac{46}{10+2\\sqrt2}=\\frac{23}{5+\\sqrt2}$","$x=\\frac{23(5-\\sqrt2)}{(5+\\sqrt2)(5-\\sqrt2)}=5-\\sqrt2$"],"설명":"분모와 분자에 $5-\\sqrt2$ 를 곱하면 분모는 $25-2=23$ 이 되어 $x=5-\\sqrt2$ 이다.","확인":null,"스킬":"S1"},{"제목":"$\\mathrm{A}$ 의 넓이","힌트":"한 변이 $5-\\sqrt2$ 인 정사각형의 넓이는?","식":["$(5-\\sqrt2)^2=25-10\\sqrt2+2=27-10\\sqrt2$"],"설명":"곱셈 공식 $(a-b)^2=a^2-2ab+b^2$ 으로 전개하면 $27-10\\sqrt2\\ (m^2)$ 이고, 선지 ② 이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-6cef4e7c4cac":{"길":"정사각형이 꼭짓점을 중심으로 $90^{\\circ}$ 씩 네 번 회전하는 동안 점 $\\mathrm{A}$ 가 그리는 호를 더한다","단계":[{"제목":"회전 횟수와 회전각","힌트":"정사각형이 한 바퀴 굴러 같은 모양이 되기까지 꼭짓점을 중심으로 몇 번 회전하는가?","식":["네 변이 차례로 바닥에 닿으므로 $90^{\\circ}$ 씩 $4$ 번 회전"],"설명":"한 번 회전할 때마다 한 변이 바닥에 놓이고 회전각은 $90^{\\circ}$ 이다.","확인":"4","스킬":"C2"},{"제목":"회전할 때마다의 반지름","힌트":"각 회전의 중심에서 점 $\\mathrm{A}$ 까지의 거리는 차례로 얼마인가?","식":["첫째: 중심이 $\\mathrm{A}$ 와 이웃한 꼭짓점이므로 반지름 $4$","둘째: 중심이 $\\mathrm{A}$ 의 맞은편 꼭짓점이므로 반지름 $4\\sqrt{2}$","셋째: 반지름 $4$, 넷째: 중심이 $\\mathrm{A}$ 자신이므로 움직이지 않는다"],"설명":"정사각형의 대각선은 한 변이 $4$ 인 직각이등변삼각형의 빗변이므로 $4\\sqrt{2}$ 이다.","확인":null,"스킬":"S3","고비":true},{"제목":"호의 길이의 합","힌트":"중심각이 $90^{\\circ}$ 이고 반지름이 $r$ 인 호의 길이를 $r$ 로 나타내면?","식":["반지름 $4$: $\\frac{1}{4}\\times2\\pi\\times4=2\\pi$","반지름 $4\\sqrt{2}$: $\\frac{1}{4}\\times2\\pi\\times4\\sqrt{2}=2\\sqrt{2}\\pi$","합 $=2\\pi+2\\sqrt{2}\\pi+2\\pi+0=(4+2\\sqrt{2})\\pi$"],"설명":"움직이지 않는 마지막 회전은 호의 길이가 $0$ 이다.","확인":null,"스킬":"S13"}]},"ns-6f78c0d958cc":{"길":"$96n$ 과 $60-n$ 이 모두 제곱수가 되는 $n$ 을 찾고, 두 정사각형의 변에서 직사각형 $\\mathrm{C}$ 의 가로와 세로를 구한다","단계":[{"제목":"$96n$ 이 제곱수가 되는 $n$ 의 꼴","힌트":"$96$ 을 소인수분해하면 $n$ 에는 어떤 인수가 더 있어야 할까?","식":["$96n=2^4\\times6n$","$n=6k^2\\ (k\\text{는 자연수})$"],"설명":"$96=2^5\\times3$ 이므로 $96n=2^4\\times6n$ 이다. 제곱수가 되려면 $6n$ 이 제곱수여야 하므로 $n=6k^2$ 꼴이다.","확인":null,"스킬":"N1","고비":true},{"제목":"$60-n$ 도 제곱수인 $n$","힌트":"$n=6k^2$ 이고 $60-n$ 이 양수인 $n$ 을 하나씩 넣어 보면?","식":["$n=6\\Rightarrow54,\\quad n=24\\Rightarrow36,\\quad n=54\\Rightarrow6$"],"설명":"$n=6,\\ 24,\\ 54$ 에서 $60-n$ 이 $54$, $36$, $6$ 이다. 제곱수인 것은 $36$ 뿐이므로 $n=24$ 이다.","확인":"24","스킬":"N8"},{"제목":"두 정사각형의 한 변","힌트":"$n=24$ 일 때 $\\mathrm{A}$, $\\mathrm{B}$ 의 넓이는 각각 얼마이고 한 변은?","식":["$96\\times24=2304=48^2$","$60-24=36=6^2$"],"설명":"$\\mathrm{A}$ 의 한 변은 $48$, $\\mathrm{B}$ 의 한 변은 $6$ 이다.","확인":null,"스킬":"N8"},{"제목":"직사각형 $\\mathrm{C}$ 의 넓이","힌트":"$\\mathrm{C}$ 의 가로는 $\\mathrm{B}$ 의 가로와 같다. 세로는 $\\mathrm{A}$ 의 세로에서 무엇을 빼면 될까?","식":["$\\text{가로}=6,\\quad\\text{세로}=48-6=42$","$6\\times42=252$"],"설명":"오른쪽 열의 $\\mathrm{C}$ 와 $\\mathrm{B}$ 는 가로가 $6$ 으로 같고, 두 도형의 세로를 더하면 $\\mathrm{A}$ 의 세로 $48$ 과 같다. 그래서 $\\mathrm{C}$ 의 세로는 $42$ 이고 넓이는 $252$ 이다.","확인":"252","스킬":"N8"}],"fb":"fig/ns/"},"ns-73fd30918936":{"길":"$\\overline{BD}$ 로 $B$ 의 좌표를 찾고 $\\overline{AF}$ 로 $Q$ 의 좌표를 구한 뒤 $\\frac{1}{Q}$ 의 분모를 유리화한다","단계":[{"제목":"점 $B$ 와 점 $A$ 의 좌표","힌트":"$\\overline{BD}$ 의 길이를 구하고, $P$ 가 $B$ 의 어느 쪽에 있는지 보면 $B$ 의 좌표는?","식":["$\\overline{BD}=\\sqrt{1^2+1^2}=\\sqrt2$","$B=(-1-\\sqrt2)+\\sqrt2=-1,\\quad A=-2$"],"설명":"$\\overline{BD}$ 는 한 변이 $1$ 인 정사각형 $ABED$ 의 대각선이므로 $\\sqrt2$ 이다. $P$ 는 $B$ 에서 왼쪽으로 $\\sqrt2$ 만큼 떨어져 있으므로 $B=-1$ 이다. $\\overline{AB}=1$ 이고 $A$ 는 $B$ 의 왼쪽에 있으므로 $A=-2$ 이다.","확인":null,"스킬":"S3","고비":true},{"제목":"점 $Q$ 의 좌표","힌트":"$\\overline{AF}$ 는 가로 $2$, 세로 $1$ 인 직사각형 $ACFD$ 의 무엇일까?","식":["$\\overline{AF}=\\sqrt{2^2+1^2}=\\sqrt5$","$Q=-2+\\sqrt5$"],"설명":"$\\overline{AF}$ 는 직사각형 $ACFD$ 의 대각선이므로 피타고라스 정리로 $\\sqrt5$ 이다. $Q$ 는 $A$ 에서 오른쪽으로 $\\sqrt5$ 만큼 떨어져 있으므로 $Q=-2+\\sqrt5$ 이다.","확인":null,"스킬":"S3"},{"제목":"$\\frac{1}{Q}$ 의 값","힌트":"$\\frac{1}{\\sqrt5-2}$ 의 분모를 유리화하려면 무엇을 곱할까?","식":["$\\frac{1}{Q}=\\frac{1}{\\sqrt5-2}=\\frac{\\sqrt5+2}{(\\sqrt5-2)(\\sqrt5+2)}=2+\\sqrt5$"],"설명":"분모와 분자에 $\\sqrt5+2$ 를 곱하면 분모가 $5-4=1$ 이 되어 $2+\\sqrt5$ 이고, 선지 ⑤ 이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-899b59729446":{"길":"중점을 이은 정사각형의 한 변을 차례로 구한 뒤, 색칠한 삼각형 네 개와 가장 안쪽 정사각형의 둘레를 더한다","단계":[{"제목":"안쪽 정사각형들의 한 변","힌트":"변의 중점을 이어 만든 정사각형의 한 변은 직각이등변삼각형의 어느 변이 될까?","식":["$\\sqrt{1^2+1^2}=\\sqrt2$","$\\sqrt{\\left(\\frac{\\sqrt2}{2}\\right)^2+\\left(\\frac{\\sqrt2}{2}\\right)^2}=1$","$\\sqrt{\\left(\\frac12\\right)^2+\\left(\\frac12\\right)^2}=\\frac{\\sqrt2}{2}$"],"설명":"새 정사각형의 한 변은 바깥 정사각형의 모서리에서 잘려 나간 직각이등변삼각형의 빗변이다. 한 변 $2$ 에서 $\\sqrt2$, 그 다음 $1$, 가장 안쪽은 $\\frac{\\sqrt2}{2}$ 가 된다.","확인":null,"스킬":"S3","고비":true},{"제목":"색칠한 부분의 모양","힌트":"한 변이 $\\sqrt2$ 인 정사각형에서 한 변이 $1$ 인 정사각형 바깥에 남는 부분은 어떤 도형일까?","식":["$\\text{삼각형 4개: 빗변 }1,\\ \\text{다른 두 변 }\\tfrac{\\sqrt2}{2}$"],"설명":"한 변이 $\\sqrt2$ 인 정사각형의 네 꼭짓점 쪽에 직각이등변삼각형이 하나씩 남는다. 빗변이 $1$ 이므로 다른 두 변은 각각 $\\frac{\\sqrt2}{2}$ 이다. 색칠한 부분은 이 삼각형 네 개와 한 변이 $\\frac{\\sqrt2}{2}$ 인 가장 안쪽 정사각형이다.","확인":null,"스킬":"S3"},{"제목":"둘레의 길이의 합","힌트":"삼각형 하나의 둘레와 가장 안쪽 정사각형의 둘레를 구해 더하면?","식":["$4\\left(\\frac{\\sqrt2}{2}+\\frac{\\sqrt2}{2}+1\\right)=4\\sqrt2+4$","$4\\times\\frac{\\sqrt2}{2}=2\\sqrt2$","$4\\sqrt2+4+2\\sqrt2=6\\sqrt2+4$"],"설명":"삼각형 하나의 둘레는 $\\sqrt2+1$ 이고 네 개이면 $4\\sqrt2+4$ 이다. 가장 안쪽 정사각형의 둘레 $2\\sqrt2$ 를 더하면 $6\\sqrt2+4$ 이고, 선지 ② 이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-8ce162532927":{"길":"넓이비를 길이비로 바꿔 둘레의 식에서 작은 변을 구하고, 두 정사각형의 넓이를 더한다","단계":[{"제목":"두 정사각형의 변의 길이비","힌트":"넓이의 비가 $1:3$ 인 두 정사각형의 한 변의 길이의 비는?","식":["$1:\\sqrt3$"],"설명":"넓이의 비는 길이의 비의 제곱이므로 변의 길이의 비는 $1:\\sqrt3$ 이다. 작은 정사각형의 한 변을 $x$, 큰 정사각형의 한 변을 $\\sqrt3x$ 라 한다.","확인":null,"스킬":"S1","고비":true},{"제목":"둘레의 식","힌트":"계단 모양 도형의 둘레는 가로 전체와 세로 전체로 어떻게 나타낼까?","식":["$2\\{(x+\\sqrt3x)+\\sqrt3x\\}=2(1+2\\sqrt3)x=44$"],"설명":"도형의 둘레는 바깥을 둘러싼 직사각형의 둘레와 같다. 가로는 $x+\\sqrt3x$, 세로는 큰 정사각형의 한 변인 $\\sqrt3x$ 이다.","확인":null,"스킬":"C7"},{"제목":"작은 정사각형의 한 변","힌트":"$(1+2\\sqrt3)x=22$ 에서 $x$ 의 분모를 유리화하면?","식":["$x=\\frac{22}{1+2\\sqrt3}=\\frac{22(2\\sqrt3-1)}{(2\\sqrt3+1)(2\\sqrt3-1)}=\\frac{22(2\\sqrt3-1)}{11}=4\\sqrt3-2$"],"설명":"분모와 분자에 $2\\sqrt3-1$ 을 곱하면 분모가 $12-1=11$ 이 되어 $x=4\\sqrt3-2$ 이다.","확인":null,"스킬":"S1"},{"제목":"도형의 넓이","힌트":"두 정사각형의 넓이를 $x^2$ 으로 나타내어 더하면?","식":["$x^2+3x^2=4x^2$","$4(4\\sqrt3-2)^2=4(52-16\\sqrt3)=208-64\\sqrt3$"],"설명":"작은 정사각형의 넓이는 $x^2$, 큰 정사각형의 넓이는 $3x^2$ 이므로 합은 $4x^2$ 이다. $(4\\sqrt3-2)^2=48-16\\sqrt3+4=52-16\\sqrt3$ 이므로 $208-64\\sqrt3$ 이고, 선지 ③ 이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-8f34eee26866":{"길":"$54n$ 이 제곱수가 되는 $n$ 의 꼴을 구하고 $12+n$ 도 제곱수인 가장 작은 $n$ 을 찾아 무밭의 가로와 세로를 구한다","단계":[{"제목":"$54n$ 이 제곱수가 되는 $n$ 의 꼴","힌트":"$54$ 를 소인수분해하면 $n$ 에는 어떤 인수가 더 있어야 할까?","식":["$54n=2\\times3^3\\times n$","$n=6k^2\\ (k\\text{는 자연수})$"],"설명":"제곱수는 소인수의 지수가 모두 짝수이다. $54=2\\times3^3$ 에서 $2$ 와 $3$ 의 지수를 짝수로 만들려면 $n$ 에 $2\\times3$ 이 필요하므로 $n=6k^2$ 꼴이다.","확인":null,"스킬":"N1","고비":true},{"제목":"$12+n$ 도 제곱수인 가장 작은 $n$","힌트":"$n=6,\\ 24,\\ 54,\\dots$ 를 차례로 넣어 $12+n$ 이 제곱수가 되는 첫 값은?","식":["$n=6\\Rightarrow18,\\quad n=24\\Rightarrow36$"],"설명":"$n=6$ 이면 $18$ 로 제곱수가 아니고, $n=24$ 이면 $36=6^2$ 이다. 가장 작은 $n$ 은 $24$ 이다.","확인":"24","스킬":"N8"},{"제목":"과수원과 배추밭의 한 변","힌트":"$n=24$ 일 때 넓이 $54n$, $12+n$ 의 제곱근은?","식":["$54\\times24=1296=36^2$","$12+24=36=6^2$"],"설명":"과수원의 한 변은 $36$, 배추밭의 한 변은 $6$ 이다.","확인":null,"스킬":"N8"},{"제목":"무밭의 둘레","힌트":"무밭의 가로는 배추밭의 가로와 같고, 세로는 과수원의 세로에서 배추밭의 세로를 뺀 길이이다. 둘레는?","식":["$\\text{가로}=6,\\quad\\text{세로}=36-6=30$","$2(6+30)=72$"],"설명":"무밭과 배추밭은 오른쪽 열에 있고 두 세로의 합이 과수원의 한 변 $36$ 과 같다. 무밭은 가로 $6$, 세로 $30$ 이므로 둘레는 $72$ 이다.","확인":"72","스킬":"N8"}],"fb":"fig/ns/"},"ns-8f933cfcb6c9":{"길":"네 정사각형의 둘레의 합에서 겹친 정사각형의 둘레를 빼서 도형의 둘레를 구한다","단계":[{"제목":"정사각형의 한 변과 대각선","힌트":"넓이가 $S$ 인 정사각형의 한 변은 얼마이고, 대각선은 한 변의 몇 배일까?","식":["$\\text{한 변: }2,\\ 2\\sqrt2,\\ 4,\\ 3\\sqrt2$","$\\text{대각선: }2\\sqrt2,\\ 4,\\ 4\\sqrt2,\\ 6$"],"설명":"넓이 $4$, $8$, $16$, $18$ 의 한 변은 $2$, $2\\sqrt2$, $4$, $3\\sqrt2$ 이고, 대각선은 한 변의 $\\sqrt2$ 배이므로 $2\\sqrt2$, $4$, $4\\sqrt2$, $6$ 이다.","확인":null,"스킬":"S3"},{"제목":"겹친 정사각형의 크기","힌트":"겹친 정사각형의 대각선은 앞 정사각형의 대각선 중 어느 부분일까?","식":["$\\text{대각선: }\\sqrt2,\\ 2,\\ 2\\sqrt2$","$\\text{한 변: }1,\\ \\sqrt2,\\ 2$"],"설명":"뒤 정사각형의 꼭짓점이 앞 정사각형의 대각선의 교점에 있으므로, 겹친 정사각형의 한 대각선은 앞 정사각형의 중심에서 꼭짓점까지, 곧 대각선의 절반이다. 앞 대각선이 $2\\sqrt2$, $4$, $4\\sqrt2$ 이므로 겹친 정사각형의 대각선은 $\\sqrt2$, $2$, $2\\sqrt2$ 이고 한 변은 $1$, $\\sqrt2$, $2$ 이다.","확인":null,"스킬":"S3","고비":true},{"제목":"둘레의 합과 겹친 부분의 둘레","힌트":"네 정사각형의 둘레의 합과 겹친 정사각형 세 개의 둘레의 합은 각각 얼마일까?","식":["$8+8\\sqrt2+16+12\\sqrt2=24+20\\sqrt2$","$4+4\\sqrt2+8=12+4\\sqrt2$"],"설명":"네 정사각형의 둘레는 $8$, $8\\sqrt2$, $16$, $12\\sqrt2$ 이다. 겹친 정사각형의 둘레는 한 변의 네 배이므로 $4$, $4\\sqrt2$, $8$ 이다.","확인":null,"스킬":"S3"},{"제목":"도형의 둘레","힌트":"겹친 정사각형의 네 변 중 두 변은 앞 정사각형의, 두 변은 뒤 정사각형의 변이고 모두 도형 안쪽에 있다. 둘레는 어떻게 구할까?","식":["$(24+20\\sqrt2)-(12+4\\sqrt2)=12+16\\sqrt2$"],"설명":"겹친 정사각형의 네 변은 도형의 안쪽에 있으므로 둘레의 합에서 겹친 정사각형의 둘레를 한 번 빼면 도형의 둘레가 된다. $12+16\\sqrt2$ 이고 선지 ⑤ 이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-921ac8d8dfac":{"길":"반으로 자를 때마다 닮음비가 $1:\\sqrt{2}$ 임을 이용해 $A2$ 와 $B6$ 을 모두 $A0$ 의 길이로 나타낸다","단계":[{"제목":"반으로 자를 때의 닮음비","힌트":"반으로 자르면 넓이비는 얼마이고, 닮음비는?","식":["$2:1=(\\sqrt{2})^{2}:1^{2}$","$\\sqrt{2}:1$"],"설명":"반으로 자른 용지는 원래 용지와 닮은 도형이고 넓이는 $\\frac{1}{2}$ 배이다. 넓이비가 닮음비의 제곱이므로 닮음비는 $\\sqrt{2}:1$ 이고, 한 번 자를 때마다 길이는 $\\frac{1}{\\sqrt{2}}$ 배가 된다.","확인":null,"스킬":"S1","고비":true},{"제목":"$A2$ 의 크기","힌트":"$A0$ 을 두 번 자르면 길이는 몇 배가 될까?","식":["$\\left(\\frac{1}{\\sqrt{2}}\\right)^{2}=\\frac{1}{2}$"],"설명":"$A2$ 는 $A0$ 을 두 번 자른 것이므로 $A2$ 의 길이는 $A0$ 의 $\\frac{1}{2}$ 배이다.","확인":"1/2","스킬":"S1"},{"제목":"$B0$ 의 크기","힌트":"넓이가 $1.5$ 배인 닮은 도형의 닮음비는?","식":["$\\text{넓이비}\\ B0:A0=3:2$","$\\sqrt{\\frac{3}{2}}=\\frac{\\sqrt{6}}{2}$"],"설명":"넓이비 $3:2$ 에서 닮음비는 $\\sqrt{3}:\\sqrt{2}$ 이다. 따라서 $B0$ 의 길이는 $A0$ 의 $\\frac{\\sqrt{6}}{2}$ 배이다.","확인":null,"스킬":"S1"},{"제목":"$B6$ 의 크기","힌트":"$B0$ 을 여섯 번 자르면 길이는 몇 배가 될까?","식":["$\\frac{\\sqrt{6}}{2}\\times\\left(\\frac{1}{\\sqrt{2}}\\right)^{6}=\\frac{\\sqrt{6}}{2}\\times\\frac{1}{8}=\\frac{\\sqrt{6}}{16}$"],"설명":"$B6$ 의 길이는 $A0$ 의 $\\frac{\\sqrt{6}}{16}$ 배이다.","확인":null,"스킬":"S1"},{"제목":"닮음비 $1:b$","힌트":"$A2$ 와 $B6$ 의 길이를 $A0$ 에 대한 배수로 비교하면?","식":["$\\frac{1}{2}:\\frac{\\sqrt{6}}{16}=1:\\frac{\\sqrt{6}}{8}$"],"설명":"앞의 항을 $1$ 로 만들기 위해 양쪽에 $2$ 를 곱하면 $1:\\frac{\\sqrt{6}}{8}$ 이다. 따라서 $b=\\frac{\\sqrt{6}}{8}$ 이고 선지 ① 이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-9e1fc758b1c3":{"길":"모눈에서 정사각형의 한 변을 피타고라스 정리로 구해 네 점의 좌표를 쓰고 선지를 하나씩 확인한다","단계":[{"제목":"두 정사각형의 한 변","힌트":"모눈에서 정사각형의 한 변은 가로 몇 칸, 세로 몇 칸을 가는 선분일까?","식":["$\\sqrt{1^2+1^2}=\\sqrt2$","$\\sqrt{2^2+2^2}=2\\sqrt2$"],"설명":"왼쪽 정사각형의 한 변은 가로 $1$칸, 세로 $1$칸을 지나므로 $\\sqrt2$ 이고, 오른쪽 정사각형의 한 변은 가로 $2$칸, 세로 $2$칸을 지나므로 $2\\sqrt2$ 이다. 반원의 반지름은 이 한 변이다.","확인":null,"스킬":"S3","고비":true},{"제목":"네 점의 좌표","힌트":"반원의 중심은 수직선 위의 어떤 점이고, 그 점에서 양쪽으로 반지름만큼 가면?","식":["$a=-1-\\sqrt2,\\quad b=-1+\\sqrt2$","$c=5-2\\sqrt2,\\quad d=5+2\\sqrt2$"],"설명":"왼쪽 반원의 중심은 수직선의 $-1$, 오른쪽 반원의 중심은 $5$ 이다. 중심에서 반지름 $\\sqrt2$, $2\\sqrt2$ 만큼 좌우로 간 점이 $\\mathrm{A}$, $\\mathrm{B}$ 와 $\\mathrm{C}$, $\\mathrm{D}$ 이다.","확인":null,"스킬":"S3"},{"제목":"보기 확인","힌트":"네 좌표로 선지의 식을 하나씩 계산하면?","식":["$a\\ne-\\sqrt2,\\quad c\\ne1+\\sqrt8$","$\\overline{BC}=c-b=6-3\\sqrt2$","$a+d=4+\\sqrt2,\\quad b+c=4-\\sqrt2$"],"설명":"$\\overline{BC}=c-b=6-3\\sqrt2$ 이므로 선지 ③ 은 틀리고, $b+c=4-\\sqrt2$ 이므로 선지 ⑤ 도 틀린다. $a+d=(-1-\\sqrt2)+(5+2\\sqrt2)=4+\\sqrt2$ 이므로 선지 ④ 가 옳다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-bfe094f73c01":{"길":"모눈 위 정사각형의 변과 호의 반지름을 피타고라스 정리로 구해 수직선의 수로 옮긴 뒤 선지를 확인한다","단계":[{"제목":"$\\square PQRS$ 의 한 변","힌트":"$\\triangle PEQ$ 에서 $\\overline{PE}$ 와 $\\overline{EQ}$ 는 얼마일까?","식":["$\\overline{PQ}=\\sqrt{1^2+2^2}=\\sqrt5$","$\\square PQRS=5$"],"설명":"$\\mathrm{E}$ 는 큰 정사각형 $EFGH$ 의 왼쪽 위 꼭짓점이고 $\\overline{PE}=1$, $\\overline{EQ}=2$ 이다. 피타고라스 정리로 한 변은 $\\sqrt5$, 넓이는 $5$ 이다. 따라서 선지 ① 은 틀리다.","확인":null,"스킬":"S3"},{"제목":"점 $\\mathrm{A}$ 와 점 $\\mathrm{B}$ 의 좌표","힌트":"점 $\\mathrm{S}$ 에서 수직선까지 그린 호의 중심은 $\\mathrm{R}$ 이다. 반지름과 중심의 좌표로 $\\mathrm{A}$ 를 구하면?","식":["$\\overline{RS}=\\sqrt{1^2+2^2}=\\sqrt5$","$A=1+\\sqrt5$","$\\overline{AC}=\\sqrt{1^2+1^2}=\\sqrt2,\\quad B=1+\\sqrt5+\\sqrt2$"],"설명":"$\\mathrm{R}$ 의 좌표는 $1$ 이고 호의 반지름은 $\\overline{RS}=\\sqrt5$ 이므로 $A=1+\\sqrt5$ 이다. 정사각형 $ABCD$ 에서 점 $\\mathrm{B}$ 는 $\\mathrm{A}$ 에서 대각선 $\\overline{AC}=\\sqrt2$ 만큼 오른쪽에 있으므로 $B=1+\\sqrt5+\\sqrt2$ 이다. 따라서 선지 ② 와 ⑤ 는 틀리다.","확인":null,"스킬":"S3","고비":true},{"제목":"점 $\\mathrm{G}$ 에서 왼쪽으로 이동한 점","힌트":"$\\overline{QR}$ 는 정사각형 $PQRS$ 의 한 변과 같을까?","식":["$\\overline{QR}=\\sqrt5$","$2-\\sqrt5$"],"설명":"$\\mathrm{G}$ 의 좌표는 $2$ 이고 $\\overline{QR}=\\sqrt5$ 이다. $2$ 에서 $\\sqrt5$ 만큼 왼쪽으로 이동하면 $2-\\sqrt5$ 이므로 선지 ③ 은 옳다.","확인":null,"스킬":"S3"},{"제목":"선지 ④ 의 확인","힌트":"$\\overline{AC}$ 는 한 변이 $1$ 인 정사각형의 무엇일까?","식":["$\\overline{AC}=\\sqrt2$","$\\text{넓이가 }2\\text{인 정사각형의 한 변}=\\sqrt2$"],"설명":"$\\overline{AC}$ 는 한 변이 $1$ 인 정사각형의 대각선이므로 $\\sqrt2$ 이다. 넓이가 $2$ 인 정사각형의 한 변도 $\\sqrt2$ 이므로 선지 ④ 는 옳다. 옳은 것은 ③, ④ 이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-fa0e7682383d":{"길":"모눈 위 비스듬한 선분마다 피타고라스 정리로 길이를 구해 몸통과 꼬리의 테두리를 각각 더한 뒤 뺀다","단계":[{"제목":"몸통의 비스듬한 선분","힌트":"몸통 왼쪽 아래 꼭짓점을 원점으로 하고 오른쪽 $x$ 칸, 위쪽 $y$ 칸을 $(x,\\ y)$ 로 쓸 때, 비스듬한 선분은 가로 몇 칸, 세로 몇 칸을 갈까?","식":["$(0,3)\\to(2,5):\\ \\sqrt{2^2+2^2}=2\\sqrt2$","$(2,5)\\to(5,4):\\ \\sqrt{3^2+1^2}=\\sqrt{10}$","$(5,2)\\to(4,0),\\ (0,0)\\to(1,2):\\ \\sqrt5$","$(1,2)\\to(0,3):\\ \\sqrt2$"],"설명":"몸통의 꼭짓점은 $(0,0)$, $(4,0)$, $(5,2)$, $(5,4)$, $(2,5)$, $(0,3)$, $(1,2)$ 이다. 비스듬한 선분은 모눈 위의 직각삼각형의 빗변으로 보고 피타고라스 정리로 구한다.","확인":null,"스킬":"S3","고비":true},{"제목":"몸통의 테두리 $x$","힌트":"몸통과 꼬리의 경계선 $(5,2)\\to(5,4)$ 도 몸통의 테두리에 포함되는데, 길이는?","식":["$x=(2\\sqrt2+\\sqrt{10}+\\sqrt5+\\sqrt5+\\sqrt2)+4+2$","$x=6+3\\sqrt2+\\sqrt{10}+2\\sqrt5$"],"설명":"곧은 선분은 밑변 $(0,0)\\to(4,0)$ 이 $4$, 경계선이 $2$ 이다. 곧은 선분 $6$ 과 비스듬한 선분을 모두 더한다.","확인":null,"스킬":"S3"},{"제목":"꼬리의 비스듬한 선분","힌트":"꼬리의 꼭짓점은 $(5,2)$, $(6,0)$, $(8,0)$, $(8,1)$, $(7,2)$, $(8,3)$, $(7,4)$, $(8,5)$, $(8,6)$, $(7,5)$, $(5,4)$ 이다. 비스듬한 선분은 몇 개이고 각각의 길이는?","식":["$(5,4)\\to(7,5):\\ \\sqrt{2^2+1^2}=\\sqrt5$","$(6,0)\\to(5,2):\\ \\sqrt5$","$(7,5)\\to(8,6)\\text{과 톱니 네 개}:\\ \\sqrt2\\text{가 5개}$"],"설명":"가로 $1$칸, 세로 $1$칸을 가는 선분은 $\\sqrt2$ 이고, 가로 $2$칸 세로 $1$칸 또는 가로 $1$칸 세로 $2$칸을 가는 선분은 $\\sqrt5$ 이다.","확인":null,"스킬":"S3"},{"제목":"꼬리의 테두리 $y$","힌트":"곧은 선분은 경계선 $(5,4)\\to(5,2)$ 를 포함해 모두 합하면 몇일까?","식":["$2+1+1+2=6$","$y=6+2\\sqrt5+5\\sqrt2$"],"설명":"곧은 선분은 경계선 $2$, $(8,6)\\to(8,5)$ 가 $1$, $(8,1)\\to(8,0)$ 이 $1$, $(8,0)\\to(6,0)$ 이 $2$ 이다. 비스듬한 선분을 더하면 $y=6+2\\sqrt5+5\\sqrt2$ 이다.","확인":null,"스킬":"S3"},{"제목":"$x-y$ 의 값","힌트":"$x$ 와 $y$ 에서 곧은 선분의 합과 같은 무리수끼리 정리하면?","식":["$x-y=(6+3\\sqrt2+\\sqrt{10}+2\\sqrt5)-(6+5\\sqrt2+2\\sqrt5)=\\sqrt{10}-2\\sqrt2$"],"설명":"곧은 선분의 합 $6$ 과 $2\\sqrt5$ 는 서로 소거되고 $3\\sqrt2-5\\sqrt2=-2\\sqrt2$ 가 남는다. $\\sqrt{10}-2\\sqrt2$ 이고 선지 ④ 이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-fd3d373778f6":{"길":"정팔각형을 둘러싼 정사각형에서 모서리의 직각이등변삼각형 네 개를 빼 넓이를 한 변 $a$ 의 식으로 쓴다","단계":[{"제목":"정팔각형을 둘러싼 정사각형의 한 변","힌트":"정팔각형의 한 변을 $a$ 라 할 때, 모서리에서 잘려 나간 직각이등변삼각형의 변의 길이는?","식":["$\\text{삼각형의 빗변}=a,\\quad\\text{다른 두 변}=\\frac{a}{\\sqrt2}=\\frac{\\sqrt2}{2}a$","$\\text{정사각형의 한 변}=a+2\\times\\frac{\\sqrt2}{2}a=(1+\\sqrt2)a$"],"설명":"겹친 두 정사각형 중 하나를 정팔각형을 둘러싼 정사각형으로 본다. 네 모서리에 직각이등변삼각형이 남고 그 빗변이 정팔각형의 한 변 $a$ 이므로 다른 두 변은 $\\frac{\\sqrt2}{2}a$ 이다. 정사각형의 한 변은 $a$ 에 삼각형의 변 두 개를 더한 $(1+\\sqrt2)a$ 이다.","확인":null,"스킬":"S12","고비":true},{"제목":"잘려 나간 삼각형의 넓이","힌트":"직각이등변삼각형 하나의 넓이와 네 개의 합은?","식":["$\\frac12\\times\\frac{\\sqrt2}{2}a\\times\\frac{\\sqrt2}{2}a=\\frac{a^2}{4}$","$4\\times\\frac{a^2}{4}=a^2$"],"설명":"삼각형 하나의 넓이는 $\\frac{a^2}{4}$ 이고 네 개를 합하면 $a^2$ 이다.","확인":null,"스킬":"S12"},{"제목":"넓이로 $a^2$ 구하기","힌트":"정팔각형의 넓이를 정사각형의 넓이에서 삼각형 네 개를 뺀 값으로 쓰면?","식":["$(1+\\sqrt2)^2a^2-a^2=(3+2\\sqrt2)a^2-a^2=(2+2\\sqrt2)a^2$","$(2+2\\sqrt2)a^2=32+32\\sqrt2=16(2+2\\sqrt2)$","$a^2=16$"],"설명":"$(1+\\sqrt2)^2=3+2\\sqrt2$ 이다. 정팔각형의 넓이 $32+32\\sqrt2$ 는 $16(2+2\\sqrt2)$ 이므로 $a^2=16$ 이다.","확인":null,"스킬":"S12"},{"제목":"정팔각형의 한 변","힌트":"$a^2=16$ 일 때 길이 $a$ 는 양수이다. $a$ 는?","식":["$a=4$"],"설명":"$a$ 는 길이이므로 양수이다. $a=4$ 이고 선지 ④ 이다.","확인":"4","스킬":"S12"}],"fb":"fig/ns/"},"ns-09a3fe1aa40e":{"길":"제곱의 차를 합과 차의 곱으로 인수분해하고 곱이 $72$ 인 두 수의 홀짝 조건으로 가능한 쌍을 센다","단계":[{"제목":"제곱의 차를 곱으로 바꾸기","힌트":"$a^2-b^2$ 을 두 일차식의 곱으로 인수분해하면?","식":["$a^2-b^2=(a-b)(a+b)=72$"],"설명":"곱셈 공식 $a^2-b^2=(a-b)(a+b)$ 로 $(a-b)(a+b)=72$ 이다. $a>b$ 이므로 $a-b<a+b$ 이다.","확인":null,"스킬":"N4"},{"제목":"두 인수의 홀짝","힌트":"$a-b$ 와 $a+b$ 를 더한 $2a$ 는 짝수이다. 두 수의 홀짝은 어떻게 될까?","식":["$(a-b)+(a+b)=2a$"],"설명":"합이 짝수인 두 수는 홀짝이 같다. 곱 $72$ 가 짝수이므로 둘 다 홀수일 수 없고, 두 수는 모두 짝수이다.","확인":null,"스킬":"N5","고비":true},{"제목":"조건에 맞는 약수의 쌍","힌트":"곱이 $72$ 이고 둘 다 짝수인 두 수 중 작은 수를 앞에 놓은 쌍은?","식":["$(2,\\ 36),\\ (4,\\ 18),\\ (6,\\ 12)$"],"설명":"$72$ 를 곱으로 나타낸 $(1,72)$, $(2,36)$, $(3,24)$, $(4,18)$, $(6,12)$, $(8,9)$ 중 둘 다 짝수인 것은 $(2,36)$, $(4,18)$, $(6,12)$ 이다.","확인":null,"스킬":"N4"},{"제목":"순서쌍 $(a,\\ b)$ 의 개수","힌트":"각 쌍에서 $a=\\frac{(a-b)+(a+b)}{2}$ 와 $b$ 를 구하면?","식":["$(19,\\ 17),\\ (11,\\ 7),\\ (9,\\ 3)$"],"설명":"세 쌍 모두 $a$, $b$ 가 자연수이고 $a>b$ 를 만족한다. 순서쌍은 $3$개이고 선지 ③ 이다.","확인":"3","스킬":"N4"}],"fb":"fig/ns/"},"ns-1101a67963eb":{"길":"각 값을 분수로 쓴 뒤 분자의 곱이 $2^{16}-1$임을 곱셈 공식으로 알아본다","단계":[{"제목":"각 값을 분수로 쓰기","힌트":"$f(1)$, $f(2)$, $f(4)$, $f(8)$을 통분해 하나의 분수로 나타내면?","식":["$f(1)=\\frac{3}{2}$","$f(2)=\\frac{5}{4}$","$f(4)=\\frac{17}{16}$","$f(8)=\\frac{257}{256}$"],"설명":"$1+\\frac{1}{2^{x}}=\\frac{2^{x}+1}{2^{x}}$이므로 $x=1$, $2$, $4$, $8$을 각각 넣는다.","확인":null,"스킬":"A9"},{"제목":"분모의 곱을 지수로 정리하기","힌트":"분모 $2$, $2^{2}$, $2^{4}$, $2^{8}$을 곱하면 지수는 어떻게 될까?","식":["$2\\times2^{2}\\times2^{4}\\times2^{8}=2^{1+2+4+8}=2^{15}$"],"설명":"밑이 같은 수의 곱은 지수끼리 더한다.","확인":null,"스킬":"A9"},{"제목":"분자의 곱 구하기","고비":true,"힌트":"$3$, $5$, $17$, $257$은 각각 $2$의 거듭제곱에 $1$을 더한 꼴인데, 여기에 어떤 수를 곱해 두면 곱셈 공식을 쓸 수 있을까?","식":["$(2-1)(2+1)(2^{2}+1)(2^{4}+1)(2^{8}+1)$","$=2^{16}-1$"],"설명":"$3=2+1$, $5=2^{2}+1$, $17=2^{4}+1$, $257=2^{8}+1$이다. $2-1=1$을 곱해도 값이 변하지 않으므로 $(a-b)(a+b)=a^{2}-b^{2}$을 연달아 쓰면 $(2-1)(2+1)=2^{2}-1$, $(2^{2}-1)(2^{2}+1)=2^{4}-1$, $(2^{4}-1)(2^{4}+1)=2^{8}-1$, $(2^{8}-1)(2^{8}+1)=2^{16}-1$이 된다.","확인":null,"스킬":"A9"},{"제목":"$a-b$ 구하기","힌트":"곱을 $\\frac{2^{a}-1}{2^{b}}$ 꼴과 비교하면 $a$, $b$는?","식":["$\\frac{2^{16}-1}{2^{15}}$","$a=16,\\ b=15$","$a-b=1$"],"설명":"곱은 $\\frac{2^{16}-1}{2^{15}}$이므로 $a=16$, $b=15$이다.","확인":"1","스킬":"A9"}],"fb":"fig/ns/"},"ns-1a3f34aaca0a":{"길":"접어서 겹친 변의 길이가 같다는 것으로 $\\overline{GF}$ 와 $\\overline{GI}$ 를 $a$, $b$ 로 나타내고 제곱의 차를 인수분해한다","단계":[{"제목":"첫 번째 접기","힌트":"변 $\\mathrm{AB}$ 가 변 $\\mathrm{BF}$ 에 겹치면 $\\overline{BF}$ 의 길이는?","식":["$\\overline{BF}=\\overline{AB}=3b$","$\\overline{FC}=a-3b$"],"설명":"$\\overline{BE}$ 를 접는 선으로 접으면 $\\overline{AB}$ 가 $\\overline{BF}$ 에 겹치므로 $\\overline{BF}=3b$ 이다. $\\overline{BC}=a$ 이므로 $\\overline{FC}=a-3b$ 이다.","확인":null,"스킬":"C7"},{"제목":"두 번째 접기","힌트":"변 $\\mathrm{ED}$ 가 변 $\\mathrm{EG}$ 에 겹치면 $\\overline{EG}$ 는 얼마이고, $\\overline{GF}$ 는?","식":["$\\overline{EG}=\\overline{ED}=a-3b$","$\\overline{GF}=3b-(a-3b)=6b-a$"],"설명":"$\\overline{EH}$ 를 접는 선으로 접는다. $\\overline{AE}=\\overline{BF}=3b$ 이므로 $\\overline{ED}=a-3b$ 이고 이것이 $\\overline{EG}$ 와 같다. $\\overline{EF}=3b$ 에서 $\\overline{EG}$ 를 빼면 $\\overline{GF}=6b-a$ 이다.","확인":null,"스킬":"C7"},{"제목":"세 번째 접기","힌트":"변 $\\mathrm{HC}$ 가 변 $\\mathrm{HI}$ 에 겹친다. $\\overline{HI}$ 와 $\\overline{GH}$ 를 구해 $\\overline{GI}$ 를 나타내면?","식":["$\\overline{HI}=\\overline{HC}=\\overline{GF}=6b-a$","$\\overline{GH}=\\overline{FC}=a-3b$","$\\overline{GI}=(a-3b)-(6b-a)=2a-9b$"],"설명":"사각형 $GFCH$ 는 직사각형이므로 $\\overline{HC}=\\overline{GF}$, $\\overline{GH}=\\overline{FC}$ 이다. 점 $\\mathrm{I}$ 는 $\\overline{GH}$ 위에 있으므로 $\\overline{GI}=\\overline{GH}-\\overline{HI}$ 이다. $9b<2a$ 이므로 $2a-9b>0$ 이다.","확인":null,"스킬":"C7","고비":true},{"제목":"제곱의 차의 인수분해","힌트":"$\\overline{GF}^2-\\overline{GI}^2$ 을 $A^2-B^2=(A+B)(A-B)$ 로 인수분해하면?","식":["$(6b-a)^2-(2a-9b)^2=\\{(6b-a)+(2a-9b)\\}\\{(6b-a)-(2a-9b)\\}$","$=(a-3b)(15b-3a)=3(a-3b)(5b-a)$"],"설명":"첫째 괄호는 $a-3b$, 둘째 괄호는 $15b-3a=3(5b-a)$ 이다. 따라서 $3(a-3b)(5b-a)$ 이고 선지 ③ 이다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-5255e4c9ebfc":{"길":"타일 장수로 넓이를 $x$ 의 이차식으로 나타내고 일차식 두 개의 곱으로 인수분해되지 않는 선지를 찾는다","단계":[{"제목":"타일의 넓이의 합","힌트":"$\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$ 타일 한 장의 넓이는 각각 얼마일까?","식":["$x^2,\\quad x,\\quad1$","$(p,\\ q,\\ r)\\ \\Rightarrow\\ px^2+qx+r$"],"설명":"$\\mathrm{A}$ 는 $x\\times x$, $\\mathrm{B}$ 는 $x\\times1$, $\\mathrm{C}$ 는 $1\\times1$ 이다. 장수가 $p$, $q$, $r$ 이면 전체 넓이는 $px^2+qx+r$ 이다.","확인":null,"스킬":"S12"},{"제목":"직사각형이 되는 조건","힌트":"빈틈없이 이어 붙인 직사각형의 넓이는 가로와 세로의 곱이다. 넓이의 식은 어떻게 쓸 수 있어야 할까?","식":["$px^2+qx+r=(\\text{일차식})\\times(\\text{일차식})$"],"설명":"직사각형의 가로와 세로는 각각 $x$ 의 일차식이다. 그러므로 넓이의 식이 계수가 음이 아닌 정수인 두 일차식의 곱으로 인수분해되어야 한다.","확인":null,"스킬":"A2","고비":true},{"제목":"선지마다 인수분해","힌트":"선지의 장수로 넓이의 식을 만들어 인수분해해 보면?","식":["$\\text{①}\\ x^2+8x+16=(x+4)^2$","$\\text{②}\\ 2x^2+4=2(x^2+2)$","$\\text{③}\\ 3x^2+14x+8=(3x+2)(x+4)$","$\\text{④}\\ 4x^2+7x+3=(4x+3)(x+1)$","$\\text{⑤}\\ 5x^2+2x=x(5x+2)$"],"설명":"①, ③, ④, ⑤ 는 일차식 두 개의 곱으로 인수분해된다. ② 는 $x^2+2$ 가 더 인수분해되지 않으므로 직사각형을 만들 수 없는 경우이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-56301c8fde9a":{"길":"직사각형을 정사각형으로 떼어 내며 사분원의 반지름을 차례로 구하고 $\\frac{\\pi}{4}r^2$ 을 더한다","단계":[{"제목":"사분원 $\\mathrm{A}$ 의 반지름","힌트":"직사각형의 세로가 $2$ 일 때, 왼쪽에 놓인 가장 큰 정사각형의 한 변은?","식":["$r_{A}=2$"],"설명":"가장 큰 정사각형의 한 변은 직사각형의 짧은 변인 $2$ 이다. 이 정사각형의 꼭짓점이 사분원 $\\mathrm{A}$ 의 중심이므로 반지름은 $2$ 이다.","확인":"2","스킬":"S12"},{"제목":"사분원 $\\mathrm{B}$ 의 반지름","힌트":"$\\mathrm{A}$ 를 떼어 낸 직사각형의 가로는 얼마이고, 그 안의 정사각형의 한 변은?","식":["$(1+\\sqrt5)-2=\\sqrt5-1$","$r_{B}=\\sqrt5-1$"],"설명":"남은 직사각형은 가로 $\\sqrt5-1$, 세로 $2$ 이다. $\\sqrt5-1<2$ 이므로 짧은 변인 $\\sqrt5-1$ 이 정사각형 $\\mathrm{B}$ 의 한 변이다.","확인":null,"스킬":"S12"},{"제목":"사분원 $\\mathrm{C}$ 의 반지름","힌트":"$\\mathrm{B}$ 까지 떼어 낸 직사각형의 세로는 얼마일까?","식":["$2-(\\sqrt5-1)=3-\\sqrt5$","$r_{C}=3-\\sqrt5$"],"설명":"남은 직사각형은 가로 $\\sqrt5-1$, 세로 $3-\\sqrt5$ 이다. $3-\\sqrt5$ 가 더 짧으므로 정사각형 $\\mathrm{C}$ 의 한 변은 $3-\\sqrt5$ 이다.","확인":null,"스킬":"S12","고비":true},{"제목":"사분원 $\\mathrm{D}$ 의 반지름","힌트":"$\\mathrm{C}$ 를 떼어 낸 직사각형에서 짧은 변은 어느 쪽일까?","식":["$(\\sqrt5-1)-(3-\\sqrt5)=2\\sqrt5-4$","$r_{D}=2\\sqrt5-4$"],"설명":"남은 직사각형은 가로 $2\\sqrt5-4$, 세로 $3-\\sqrt5$ 이다. $2\\sqrt5-4<3-\\sqrt5$ 이므로 정사각형 $\\mathrm{D}$ 의 한 변은 $2\\sqrt5-4$ 이다.","확인":null,"스킬":"S12"},{"제목":"사분원 넓이의 합","힌트":"반지름이 $r$ 인 사분원의 넓이를 $r^2$ 으로 나타내면?","식":["$r_A^2+r_B^2+r_C^2+r_D^2=4+(6-2\\sqrt5)+(14-6\\sqrt5)+(36-16\\sqrt5)=60-24\\sqrt5$","$\\frac{\\pi}{4}(60-24\\sqrt5)=(15-6\\sqrt5)\\pi$"],"설명":"사분원 하나의 넓이는 $\\frac{\\pi}{4}r^2$ 이다. 반지름의 제곱을 모두 더한 뒤 $\\frac{\\pi}{4}$ 를 곱하면 $(15-6\\sqrt5)\\pi$ 이고, 선지 ④ 이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-6969e168a300":{"길":"가운데 수를 문자로 놓고 곱셈공식으로 분모를 간단히 한다","단계":[{"제목":"큰 수를 문자로 놓기","힌트":"$987655$, $987651$, $987653$ 사이의 관계는?","식":["$987653=m$","$987655=m+2,\\ 987651=m-2$"],"설명":"가운데 수 $987653$을 $m$이라 하면 나머지 두 수는 $m$보다 $2$ 크거나 $2$ 작다.","확인":null,"스킬":"A1","고비":true},{"제목":"분모 계산","힌트":"분모를 $m$으로 나타내고 곱셈공식으로 계산하면?","식":["$(m+2)(m-2)-m^2=m^2-4-m^2=-4$"],"설명":"$(a+b)(a-b)=a^2-b^2$을 쓴다. $m^2$이 서로 없어져 분모는 $-4$가 된다.","확인":"-4","스킬":"A1"},{"제목":"분수의 값","힌트":"분자 $1004$를 분모로 나누면?","식":["$\\dfrac{1004}{-4}=-251$"],"설명":"분모가 $-4$이므로 몫은 음수이다.","확인":"-251","스킬":"A1"}],"fb":"fig/ns/"},"ns-99c03cec8480":{"길":"$\\overline{AD}$ 와 $\\overline{DB}$ 를 $a$, $b$ 로 나타내 두 원의 넓이를 쓰고 제곱의 차를 인수분해한다","단계":[{"제목":"$\\overline{AD}$ 와 $\\overline{DB}$ 의 길이","힌트":"$\\overline{AC}$ 는 $\\overline{AB}$ 와 $\\overline{BC}$ 의 합이다. $\\mathrm{D}$ 가 $\\overline{AC}$ 의 중점일 때 $\\overline{AD}$ 와 $\\overline{DB}$ 는?","식":["$\\overline{AC}=a+b,\\quad\\overline{AD}=\\frac{a+b}{2}$","$\\overline{DB}=\\overline{AB}-\\overline{AD}=a-\\frac{a+b}{2}=\\frac{a-b}{2}$"],"설명":"두 원의 지름이 $\\overline{AB}=a$, $\\overline{BC}=b$ 이므로 $\\overline{AC}=a+b$ 이다. $\\mathrm{D}$ 는 중점이므로 $\\overline{AD}=\\frac{a+b}{2}$ 이고 $\\mathrm{D}$ 는 $\\overline{AB}$ 위에 있으므로 $\\overline{DB}=\\overline{AB}-\\overline{AD}$ 이다.","확인":null,"스킬":"A2","고비":true},{"제목":"두 원의 넓이 $S_1$, $S_2$","힌트":"지름이 $d$ 인 원의 넓이를 $d$ 로 나타내면?","식":["$S_1=\\pi\\left(\\frac{a+b}{4}\\right)^2,\\quad S_2=\\pi\\left(\\frac{a-b}{4}\\right)^2$"],"설명":"지름이 $d$ 이면 반지름이 $\\frac{d}{2}$ 이다. 지름 $\\frac{a+b}{2}$, $\\frac{a-b}{2}$ 의 반지름은 $\\frac{a+b}{4}$, $\\frac{a-b}{4}$ 이다.","확인":null,"스킬":"A2"},{"제목":"넓이의 차","힌트":"$S_1-S_2$ 를 $\\frac{\\pi}{16}$ 로 묶으면 괄호 안은 어떤 꼴일까?","식":["$\\frac{\\pi}{16}\\{(a+b)^2-(a-b)^2\\}$","$=\\frac{\\pi}{16}\\{(a+b)+(a-b)\\}\\{(a+b)-(a-b)\\}=\\frac{\\pi}{16}\\times2a\\times2b=\\frac{ab}{4}\\pi$"],"설명":"제곱의 차를 합과 차의 곱으로 인수분해하면 $2a\\times2b=4ab$ 이다. $\\frac{\\pi}{16}\\times4ab=\\frac{ab}{4}\\pi$ 이고 선지 ① 이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-a16e18231d62":{"길":"$(x-c)^2$ 을 전개해 $a$, $b$ 와 $c$ 의 관계를 얻고, 조건에 맞는 값만 골라 $a+b+c$ 를 구한다","단계":[{"제목":"계수 비교","힌트":"$(x-c)^2$ 을 전개해 $x^2-ax+b$ 와 비교하면?","식":["$(x-c)^2=x^2-2cx+c^2$","$a=2c,\\quad b=c^2$"],"설명":"$x^2-ax+b=x^2-2cx+c^2$ 이 항등식이므로 $x$ 의 계수와 상수항을 비교한다.","확인":null,"스킬":"A6","고비":true},{"제목":"가능한 $b$ 와 $c$","힌트":"$b$ 는 $10$ 이하의 홀수 $1,\\ 3,\\ 5,\\ 7,\\ 9$ 중 하나이다. 이 중 어떤 $b$ 가 $c^2$ 꼴일까?","식":["$b=1\\Rightarrow c=1,\\quad b=9\\Rightarrow c=3$"],"설명":"$b=c^2$ 이고 $c$ 는 자연수이므로 $b$ 는 제곱수이다. $1$, $3$, $5$, $7$, $9$ 중 제곱수는 $1$ 과 $9$ 뿐이다.","확인":null,"스킬":"A6"},{"제목":"$a$ 의 조건과 $a+b+c$","힌트":"$a=2c$ 가 $10$ 이하의 짝수인지 확인한 뒤 $a+b+c$ 를 구하면?","식":["$(a,\\ b,\\ c)=(2,\\ 1,\\ 1),\\ (6,\\ 9,\\ 3)$","$2+1+1=4,\\quad6+9+3=18$"],"설명":"$c=1$ 이면 $a=2$, $c=3$ 이면 $a=6$ 이며 둘 다 $10$ 이하의 짝수이다. $a+b+c$ 는 $4$ 또는 $18$ 이고 선지 ④ 이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-a5e0f7f4c1f6":{"길":"세 번 접은 변의 길이가 같다는 것으로 $\\overline{EG}$ 와 $\\overline{FJ}$ 를 $a$, $b$ 로 나타내고 제곱의 차를 인수분해한다","단계":[{"제목":"첫 번째 접기","힌트":"변 $\\mathrm{AB}$ 가 변 $\\mathrm{BF}$ 에 겹치면 $\\overline{BF}$ 와 $\\overline{FC}$ 는?","식":["$\\overline{BF}=\\overline{AB}=2b$","$\\overline{FC}=3a-2b$"],"설명":"$\\overline{BE}$ 를 접는 선으로 접으면 $\\overline{BF}=\\overline{AB}=2b$ 이고, $\\overline{BC}=3a$ 이므로 $\\overline{FC}=3a-2b$ 이다. 이때 $\\overline{AE}=\\overline{BF}=2b$ 이다.","확인":null,"스킬":"S10"},{"제목":"두 번째 접기","힌트":"변 $\\mathrm{ED}$ 가 변 $\\mathrm{EG}$ 에 겹치면 $\\overline{EG}$ 와 $\\overline{GF}$ 는?","식":["$\\overline{EG}=\\overline{ED}=3a-2b$","$\\overline{GF}=2b-(3a-2b)=4b-3a$"],"설명":"$\\overline{AD}=3a$ 에서 $\\overline{AE}=2b$ 를 빼면 $\\overline{ED}=3a-2b$ 이고 $\\overline{EG}$ 와 같다. $\\overline{EF}=2b$ 에서 $\\overline{EG}$ 를 빼면 $\\overline{GF}=4b-3a$ 이다.","확인":null,"스킬":"S10"},{"제목":"세 번째 접기와 $\\overline{FJ}$","힌트":"변 $\\mathrm{HC}$ 가 변 $\\mathrm{HI}$ 에 겹칠 때 사각형 $JCHI$ 는 어떤 도형일까?","식":["$\\overline{HC}=\\overline{GF}=4b-3a$","$\\overline{JC}=\\overline{HC}=4b-3a$","$\\overline{FJ}=\\overline{FC}-\\overline{JC}=(3a-2b)-(4b-3a)=6a-6b$"],"설명":"사각형 $GFCH$ 는 직사각형이므로 $\\overline{HC}=\\overline{GF}$ 이다. 접힌 뒤 $\\angle HIJ=\\angle HCJ=90^\\circ$ 이고 $\\overline{IJ}$ 는 $\\overline{BC}$ 에 수직이므로 $JCHI$ 는 직사각형이며, $\\overline{HI}=\\overline{HC}$ 이므로 정사각형이다. 따라서 $\\overline{JC}=\\overline{HC}$ 이다.","확인":null,"스킬":"S10","고비":true},{"제목":"제곱의 차의 인수분해","힌트":"$\\overline{EG}^2-\\overline{FJ}^2$ 을 $A^2-B^2=(A+B)(A-B)$ 로 인수분해하면?","식":["$(3a-2b)^2-(6a-6b)^2=\\{(3a-2b)+(6a-6b)\\}\\{(3a-2b)-(6a-6b)\\}$","$=(9a-8b)(-3a+4b)$"],"설명":"첫째 괄호는 $9a-8b$, 둘째 괄호는 $-3a+4b$ 이다. 따라서 $(9a-8b)(-3a+4b)$ 이고 선지 ③ 이다.","확인":null,"스킬":"S10"}],"fb":"fig/ns/"},"ns-ba9a59a01171":{"길":"산책로 넓이를 곱의 꼴로 묶어 두 반지름의 합을 구하고, 점선의 반지름을 평균으로 잡는다","단계":[{"제목":"산책로 넓이를 두 반지름으로 나타내기","힌트":"바깥 원의 반지름을 $R$, 안쪽 원의 반지름을 $r$ 이라 하면 산책로의 넓이와 폭은 어떻게 쓸까?","식":["$\\pi R^2-\\pi r^2=198\\pi$","$R-r=3$"],"설명":"산책로는 바깥 원에서 안쪽 원을 뺀 부분이다. 폭이 $3$ 이므로 두 반지름의 차가 $3$ 이다.","확인":null,"스킬":"C7"},{"제목":"곱셈 공식으로 묶기","힌트":"$R^2-r^2$ 을 두 식의 곱으로 바꾸고 $R-r$ 의 값을 넣으면?","식":["$\\pi(R+r)(R-r)=198\\pi$","$3(R+r)=198$"],"설명":"$R^2-r^2=(R+r)(R-r)$ 이므로 $R-r=3$ 을 넣어 $R+r$ 를 구한다.","확인":"66","스킬":"C7","고비":true},{"제목":"점선의 반지름","힌트":"점선은 산책로 폭의 한가운데이다. 점선의 반지름은 $R$ 과 $r$ 으로 어떻게 나타낼까?","식":["$\\frac{R+r}{2}$"],"설명":"점선은 바깥 원과 안쪽 원 사이의 한가운데를 지나므로 반지름이 두 반지름의 평균이다.","확인":"33","스킬":"C7"},{"제목":"점선을 따라 한 바퀴 돈 거리","힌트":"점선의 반지름으로 원의 둘레를 구하면?","식":["$l=2\\pi\\times33$","$l=66\\pi$"],"설명":"점선은 반지름이 $33$ 인 원이므로 둘레가 $l$ 이고, 선지 ① 이다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-c7f9c47ba604":{"길":"조각의 넓이 합을 식으로 세우고 두 일차식의 곱으로 인수분해되는 개수만 모아 거짓을 찾는다","단계":[{"제목":"조각 넓이의 합","힌트":"$x$ 짜리 직사각형을 $k$ 개 쓴다고 하면 모든 조각의 넓이의 합은?","식":["$2x^2+kx+24$"],"설명":"넓이가 $x^2$ 인 정사각형 $2$ 개, 넓이가 $1$ 인 정사각형 $24$ 개, 넓이가 $x$ 인 직사각형 $k$ 개를 모두 합한다.","확인":null,"스킬":"C7"},{"제목":"직사각형이 되는 조건","힌트":"조각들로 직사각형이 만들어지려면 넓이식이 어떤 꼴이어야 할까?","식":["$2x^2+kx+24=(2x+a)(x+b)$","$ab=24$","$k=2b+a$"],"설명":"직사각형의 가로와 세로가 일차식이므로 넓이식이 두 일차식의 곱으로 인수분해되어야 한다. $x^2$ 의 계수가 $2$ 이므로 $(2x+a)(x+b)$ 꼴이고, 전개하면 상수항이 $ab$, $x$ 의 계수가 $2b+a$ 이다.","확인":null,"스킬":"N4","고비":true},{"제목":"$24$ 의 약수 쌍으로 $k$ 구하기","힌트":"$ab=24$ 를 만족하는 자연수 $(a,\\ b)$ 마다 $k=2b+a$ 는 얼마일까?","식":["$(a,\\ b)=(1,\\ 24),\\ (2,\\ 12),\\ (3,\\ 8),\\ (4,\\ 6),\\ (6,\\ 4),\\ (8,\\ 3),\\ (12,\\ 2),\\ (24,\\ 1)$","$k=49,\\ 26,\\ 19,\\ 16,\\ 14,\\ 14,\\ 16,\\ 26$"],"설명":"쌍마다 $2b+a$ 를 계산한다. 가능한 $k$ 의 값은 $14$, $16$, $19$, $26$, $49$ 이다.","확인":null,"스킬":"N4"},{"제목":"거짓말한 사람 찾기","힌트":"선지의 $26$, $19$, $16$, $14$, $12$ 중 가능한 $k$ 의 값에 없는 것은?","식":["$12\\ne k$"],"설명":"$12$ 는 위의 값에 없으므로 직사각형을 만들 수 없다. 따라서 $x$ 를 $12$ 개 더해서 만들 수 있다고 한 E 가 거짓말을 했다.","확인":"12","스킬":"N4"}],"fb":"fig/ns/"},"ns-1f41c8d3df07":{"길":"근이 만족하는 식을 $a$ 로 나눠 $a+\\frac{3}{a}$ 를 얻고, 주어진 식을 그 꼴이 보이게 묶는다","단계":[{"제목":"$a+\\frac{3}{a}$ 의 값","힌트":"$a$ 가 근이므로 성립하는 등식의 양변을 $a$ 로 나누면 어떤 식이 될까?","식":["$a^2-5a+3=0$","$a-5+\\frac{3}{a}=0$"],"설명":"근을 대입하면 $a^2-5a+3=0$ 이고, $a\\ne0$ 이므로 양변을 $a$ 로 나눌 수 있다.","확인":"5","스킬":"A12"},{"제목":"주어진 식을 인수분해로 묶기","힌트":"$a^2-\\frac{9}{a^2}$ 과 $-a+\\frac{3}{a}$ 를 각각 $a-\\frac{3}{a}$ 가 보이게 바꾸면?","식":["$a^2-\\frac{9}{a^2}=\\left(a-\\frac{3}{a}\\right)\\left(a+\\frac{3}{a}\\right)$","$-a+\\frac{3}{a}=-\\left(a-\\frac{3}{a}\\right)$","$\\left(a-\\frac{3}{a}\\right)\\left(a+\\frac{3}{a}-1\\right)$"],"설명":"앞의 두 항은 곱셈 공식 $p^2-q^2=(p+q)(p-q)$ 로 묶고, 뒤의 두 항은 $-1$ 로 묶으면 공통인수 $a-\\frac{3}{a}$ 가 나온다.","확인":null,"스킬":"A12","고비":true},{"제목":"$a-\\frac{3}{a}$ 의 값","힌트":"$\\left(a-\\frac{3}{a}\\right)^2$ 을 $\\left(a+\\frac{3}{a}\\right)^2$ 로 나타내려면 어떻게 할까?","식":["$\\left(a-\\frac{3}{a}\\right)^2=\\left(a+\\frac{3}{a}\\right)^2-12$","$a-\\frac{3}{a}=\\pm\\sqrt{13}$"],"설명":"$a\\times\\frac{3}{a}=3$ 이므로 $(p-q)^2=(p+q)^2-4pq$ 에서 $4pq=12$ 이다. $\\left(a+\\frac{3}{a}\\right)^2=25$ 를 넣으면 $13$ 이 된다.","확인":null,"스킬":"A2"},{"제목":"식의 값 계산","힌트":"묶은 두 인수에 각각 값을 넣으면?","식":["$\\left(\\pm\\sqrt{13}\\right)\\times(5-1)=\\pm4\\sqrt{13}$"],"설명":"$a+\\frac{3}{a}-1=4$ 이므로 값은 $\\pm4\\sqrt{13}$ 이고, 선지 ⑤ 이다.","확인":null,"스킬":"A12"}],"fb":"fig/ns/"},"ns-311d3f7e708c":{"길":"$2013\\times2015$ 를 제곱의 차로 보아 두 방정식을 인수분해하고 작은 근끼리 곱한다","단계":[{"제목":"$2013\\times2015$ 를 제곱의 차로 나타내기","힌트":"$2013$ 과 $2015$ 는 $2014$ 에서 각각 얼마씩 떨어져 있을까?","식":["$2013\\times2015=(2014-1)(2014+1)=2014^2-1$"],"설명":"합 · 차 공식 $(p-q)(p+q)=p^2-q^2$ 을 쓴다.","확인":null,"스킬":"A12","고비":true},{"제목":"첫째 방정식의 작은 근","힌트":"$2014^2x^2-(2014^2-1)x-1=0$ 을 인수분해하면?","식":["$(2014^2x+1)(x-1)=0$","$x=-\\frac{1}{2014^2},\\ 1$"],"설명":"$(2014^2x+1)(x-1)$ 을 전개하면 $2014^2x^2-2014^2x+x-1$ 이어서 주어진 식과 같다. 작은 근은 $a=-\\frac{1}{2014^2}$ 이다.","확인":null,"스킬":"A12"},{"제목":"둘째 방정식의 작은 근","힌트":"$x^2+2013x-2014=0$ 을 인수분해하면?","식":["$(x+2014)(x-1)=0$","$b=-2014$"],"설명":"합이 $2013$, 곱이 $-2014$ 인 두 수는 $2014$ 와 $-1$ 이므로 근은 $-2014$, $1$ 이고 작은 근은 $b=-2014$ 이다.","확인":"-2014","스킬":"A12"},{"제목":"$\\frac{1}{ab}$ 의 값","힌트":"$ab$ 를 먼저 구한 뒤 역수를 취하면?","식":["$ab=\\frac{1}{2014^2}\\times2014=\\frac{1}{2014}$","$\\frac{1}{ab}=2014$"],"설명":"두 작은 근 $a$, $b$ 가 모두 음수이므로 곱은 양수이다. 역수는 $2014$ 이고 선지 ⑤ 이다.","확인":"2014","스킬":"A12"}],"fb":"fig/ns/"},"ns-5d9ac45554a4":{"길":"두 근을 구해 어림한 뒤 보기의 무리수를 하나씩 그 사이에 있는지 확인한다","단계":[{"제목":"이차방정식의 두 근","힌트":"$3(x-1)^2-9=0$ 에서 $(x-1)^2$ 의 값을 먼저 구하면?","식":["$(x-1)^2=3$","$x-1=\\pm\\sqrt{3}$","$x=1\\pm\\sqrt{3}$"],"설명":"양변을 $3$ 으로 나누고 제곱근의 뜻을 쓴다. $\\alpha<\\beta$ 이므로 $\\alpha=1-\\sqrt{3}$, $\\beta=1+\\sqrt{3}$ 이다.","확인":null,"스킬":"A6"},{"제목":"두 근의 크기 어림","힌트":"$\\sqrt{3}$ 은 약 얼마이며, 이를 이용하면 $\\alpha$ 와 $\\beta$ 는 약 얼마일까?","식":["$\\sqrt{3}\\approx1.73$","$\\alpha\\approx-0.73$","$\\beta\\approx2.73$"],"설명":"$1.7^2=2.89$, $1.8^2=3.24$ 이므로 $\\sqrt{3}$ 은 $1.7$ 과 $1.8$ 사이의 수이다.","확인":null,"스킬":"A6"},{"제목":"보기의 수 판정","힌트":"보기의 네 수 가운데 무리수이면서 $\\alpha$ 와 $\\beta$ 사이에 있는 것은 어느 것일까?","식":["$\\sqrt{2}+1\\approx2.41$","$\\pi-2\\approx1.14$","$0.\\dot{4}\\dot{5}=\\frac{5}{11}$","$3-\\sqrt{27}=3-3\\sqrt{3}\\approx-2.20$"],"설명":"$\\sqrt{2}+1$ 과 $\\pi-2$ 는 무리수이고 $-0.73$ 과 $2.73$ 사이에 있다. $0.\\dot{4}\\dot{5}$ 는 분수로 나타나는 순환소수이므로 유리수이다. $3-3\\sqrt{3}$ 은 무리수이지만 $\\alpha$ 보다 작다.","확인":null,"스킬":"A6","고비":true},{"제목":"개수 세기","힌트":"조건을 만족하는 보기는 모두 몇 개일까?","식":["$\\sqrt{2}+1,\\ \\pi-2$"],"설명":"두 수가 조건을 만족하므로 $2$ 개이고, 선지 ③ 이다.","확인":"2","스킬":"A6"}],"fb":"fig/ns/"},"ns-772332e956db":{"길":"정오각형에서 $36^\\circ$, $72^\\circ$, $108^\\circ$ 를 따라가 닮은 삼각형을 찾고 $x$ 에 관한 식을 세워 선지를 하나씩 가린다","단계":[{"제목":"$\\angle CAD$ 와 $\\angle DCE$","힌트":"정오각형의 한 내각은 몇 도이고, 이등변삼각형 $AED$ 의 밑각은?","식":["$\\angle AED=108^\\circ,\\ \\angle EAD=\\frac{180^\\circ-108^\\circ}{2}=36^\\circ$","$\\angle CAD=108^\\circ-36^\\circ-36^\\circ=36^\\circ$"],"설명":"정오각형의 한 내각은 $108^\\circ$ 이다. $\\triangle ABC$ 와 $\\triangle AED$ 는 이등변삼각형이므로 $\\angle BAC=\\angle EAD=36^\\circ$ 이고, $\\angle CAD=36^\\circ$ 이다. 같은 방식으로 $\\angle DCE=36^\\circ$ 이므로 ① 은 옳다.","확인":"36","스킬":"S10"},{"제목":"닮은 삼각형 찾기","힌트":"$\\triangle ACD$ 와 $\\triangle CDF$ 의 각을 비교하면?","식":["$\\angle CAD=\\angle DCF=36^\\circ$","$\\angle ADC=\\angle CDF=\\angle CFD=72^\\circ$","$\\triangle ACD\\backsim\\triangle CDF$"],"설명":"$\\triangle ACD$ 에서 $\\angle ACD=108^\\circ-36^\\circ=72^\\circ$ 이므로 $\\angle ADC=72^\\circ$ 이다. $\\triangle CDF$ 에서 $\\angle CFD=180^\\circ-36^\\circ-72^\\circ=72^\\circ$ 이다. 두 쌍의 각이 같으므로 AA 닮음이고, $\\overline{AC}:\\overline{CD}=\\overline{CD}:\\overline{DF}$ 이므로 ② 는 옳다.","확인":null,"스킬":"S10"},{"제목":"$\\overline{AF}$ 와 $\\overline{CD}$ 비교","힌트":"$\\triangle CDF$ 와 $\\triangle ACF$ 에서 같은 각이 있는 변끼리 길이가 같을까?","식":["$\\overline{CD}=\\overline{CF}$","$\\angle CAF=\\angle ACF=36^\\circ\\Rightarrow\\overline{AF}=\\overline{CF}$"],"설명":"$\\triangle CDF$ 에서 $\\angle CDF=\\angle CFD$ 이므로 $\\overline{CD}=\\overline{CF}$ 이다. $\\triangle ACF$ 에서 $\\angle ACF=72^\\circ-36^\\circ=36^\\circ=\\angle CAF$ 이므로 $\\overline{AF}=\\overline{CF}$ 이다. 따라서 $\\overline{AF}=\\overline{CD}$ 이고 ③ 은 옳다.","확인":null,"스킬":"S10"},{"제목":"$x$ 에 대한 식","힌트":"$\\overline{DF}$ 를 $x$ 로 나타내어 닮음의 비례식에 넣으면?","식":["$\\overline{DF}=\\overline{AD}-\\overline{AF}=x-1$","$x:1=1:(x-1)$","$x^{2}-x-1=0$"],"설명":"정오각형의 대각선은 길이가 모두 같으므로 $\\overline{AD}=x$ 이고 $\\overline{AF}=\\overline{CD}=1$ 이다. 비례식에서 $x(x-1)=1$ 이다.","확인":null,"스킬":"S1","고비":true},{"제목":"④ 와 ⑤ 판정","힌트":"$x^{2}-x-1=0$ 의 해 중 선분의 길이가 될 수 있는 것은?","식":["$x=\\frac{1\\pm\\sqrt{5}}{2}$","$x=\\frac{1+\\sqrt{5}}{2}\\ (x>0)$"],"설명":"$x^{2}-x+1=0$ 은 위 식과 다르므로 ④ 는 옳지 않다. 근의 공식으로 얻은 두 근 중 $\\frac{1-\\sqrt{5}}{2}$ 는 음수여서 길이가 될 수 없으므로 ⑤ 도 옳지 않다. 따라서 옳지 않은 것은 ④, ⑤ 이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-785a973fc47d":{"길":"ㄱ 에서 $x^2$ 의 계수가 $0$ 이 되는 값을 빼고, ㄴ 에서 좌변이 완전제곱식이 되는 값을 구해 겹치는 값을 찾는다","단계":[{"제목":"ㄱ 의 조건","힌트":"이차방정식이 되려면 $x^2$ 의 계수가 어떤 조건을 만족해야 할까?","식":["$\\left\\{1-(a-2)^2\\right\\}x^2+3x-10=0$","$(a-2)^2\\ne1$","$a\\ne1,\\ 3$"],"설명":"좌변을 전개하면 $x^2+3x-10$ 이다. 우변을 이항하면 $x^2$ 의 계수가 $1-(a-2)^2$ 이므로 이 값이 $0$ 이 아니어야 한다.","확인":null,"스킬":"G2"},{"제목":"ㄴ 의 조건","힌트":"중근을 가지려면 이차식이 어떤 꼴이어야 하며, 상수항과 일차항의 계수 사이에는 어떤 관계가 생길까?","식":["$x^2+\\frac{a}{2}x+\\frac{a}{2}-\\frac{7}{16}=0$","$\\left(\\frac{a}{4}\\right)^2=\\frac{a}{2}-\\frac{7}{16}$","$a^2-8a+7=0$","$(a-1)(a-7)=0$"],"설명":"양변을 $2$ 로 나누면 $x^2$ 의 계수가 $1$ 이 된다. 중근을 가지면 좌변이 완전제곱식이므로 상수항이 일차항 계수의 절반의 제곱과 같다.","확인":null,"스킬":"G2","고비":true},{"제목":"두 조건을 함께 만족하는 값","힌트":"ㄴ 에서 나온 값 가운데 ㄱ 에서 제외된 값이 있는지 확인하면?","식":["$a=1,\\ 7$","$a\\ne1,\\ 3$","$a=7$"],"설명":"ㄴ 의 두 값 중 $a=1$ 은 ㄱ 에서 제외된 값이므로 두 조건을 모두 만족하는 값은 $7$ 이고, 선지 ④ 이다.","확인":"7","스킬":"G2"}],"fb":"fig/ns/"},"ns-93e26693e084":{"길":"$\\overline{AP}=\\overline{BQ}$ 를 문자로 놓고 직각삼각형 $PQC$ 의 넓이를 이차방정식으로 세운다","단계":[{"제목":"미지수를 놓고 $\\overline{PC}$, $\\overline{QC}$ 나타내기","힌트":"$\\overline{AP}=\\overline{BQ}$ 의 길이를 $t$ 로 놓으면 $\\overline{PC}$ 와 $\\overline{QC}$ 는 각각 어떻게 쓸까?","식":["$\\overline{AP}=\\overline{BQ}=t$","$\\overline{PC}=8-t$","$\\overline{QC}=6-t$"],"설명":"그림에서 $\\angle C=90^\\circ$, $\\overline{AC}=8$, $\\overline{BC}=6$ 이다. 점 $P$ 는 $\\overline{AC}$ 위에, 점 $Q$ 는 $\\overline{BC}$ 위에 있으므로 전체 길이에서 $t$ 를 뺀다.","확인":null,"스킬":"C7"},{"제목":"넓이로 이차방정식 세우기","힌트":"직각삼각형 $PQC$ 의 넓이를 $t$ 로 나타내 $4$ 와 같다고 하면?","식":["$\\frac{1}{2}(8-t)(6-t)=4$","$t^2-14t+40=0$","$(t-4)(t-10)=0$"],"설명":"밑변 $\\overline{QC}$, 높이 $\\overline{PC}$ 로 넓이를 쓰고 정리하면 $t^2-14t+40=0$ 이다.","확인":null,"스킬":"C7","고비":true},{"제목":"길이의 범위로 해 고르기","힌트":"점 $Q$ 가 $\\overline{BC}$ 위에 있으려면 $t$ 는 어떤 범위에 있어야 할까?","식":["$0<t<6$","$t=4$"],"설명":"$t=10$ 은 $\\overline{BC}=6$ 보다 길어서 맞지 않다. 따라서 $\\overline{BQ}=4$ 이고, 선지 ③ 이다.","확인":"4","스킬":"C7"}],"fb":"fig/ns/"},"ns-a0dcc7727418":{"길":"점 $P$ 가 직선 위에 있음을 이용해 $b$ 를 $a$ 로 나타내고, 사다리꼴의 넓이식을 $a$ 에 관한 이차방정식으로 만든다","단계":[{"제목":"점 $\\mathrm{A}$ 와 $b$ 를 구하기","힌트":"점 $\\mathrm{A}$ 는 직선이 $y$ 축과 만나는 점이다. 좌표는? 또 점 $\\mathrm{P}$ 가 직선 위에 있으면 $a$, $b$ 사이에 어떤 관계가 있을까?","식":["$\\mathrm{A}(0,\\ 2)$","$b=\\frac{1}{2}a+2$"],"설명":"$y$ 축 위의 점은 $x=0$ 이므로 직선의 식에 넣어 $y=2$ 를 얻는다. 점 $\\mathrm{P}(a,\\ b)$ 도 직선 위의 점이다.","확인":null,"스킬":"G1"},{"제목":"사각형 $\\mathrm{AOBP}$ 의 넓이식","힌트":"사각형 $\\mathrm{AOBP}$ 는 어떤 사각형이고, 윗변 · 아랫변 · 높이는 각각 무엇일까?","식":["$\\overline{\\mathrm{OA}}=2$","$\\overline{\\mathrm{BP}}=b$","$\\overline{\\mathrm{OB}}=a$","$\\frac{1}{2}(2+b)\\times a=3$"],"설명":"$\\overline{\\mathrm{OA}}$ 와 $\\overline{\\mathrm{BP}}$ 는 모두 $x$ 축에 수직이라 서로 평행하므로 사다리꼴이다. 높이는 $\\overline{\\mathrm{OB}}=a$ 이다.","확인":null,"스킬":"S12","고비":true},{"제목":"$a$ 에 관한 이차방정식","힌트":"넓이식의 $b$ 에 $\\frac{1}{2}a+2$ 를 넣어 정리하면?","식":["$\\frac{1}{2}\\left(4+\\frac{1}{2}a\\right)a=3$","$a^2+8a-12=0$"],"설명":"양변에 $4$ 를 곱해 분수를 없애면 $a^2+8a-12=0$ 이 된다.","확인":null,"스킬":"G1"},{"제목":"$a$ 의 값","힌트":"이차방정식을 근의 공식으로 풀고 $a$ 의 부호 조건을 따지면?","식":["$a=-4\\pm\\sqrt{16+12}=-4\\pm2\\sqrt{7}$","$a=-4+2\\sqrt{7}$"],"설명":"점 $\\mathrm{P}$ 가 제$1$사분면 위의 점이므로 $a>0$ 이다. $-4-2\\sqrt{7}$ 은 음수이므로 버린다.","확인":null,"스킬":"G1"},{"제목":"$a+b$ 의 값","힌트":"$b$ 를 $a$ 로 나타낸 식에 $a$ 를 넣어 $b$ 를 구한 뒤 더하면?","식":["$b=\\frac{1}{2}(-4+2\\sqrt{7})+2=\\sqrt{7}$","$a+b=-4+3\\sqrt{7}$"],"설명":"$a+b=-4+2\\sqrt{7}+\\sqrt{7}$ 이므로 선지 ④ 이다.","확인":null,"스킬":"G1"}],"fb":"fig/ns/"},"ns-b0135a4c36d9":{"길":"공통인 $x+\\frac{1}{2}$ 을 한 문자로 놓고 푼 뒤 $x$ 로 되돌려 합을 구한다","단계":[{"제목":"공통부분을 문자로 놓기","힌트":"양변에 모두 들어 있는 식은 무엇일까?","식":["$x+\\frac{1}{2}=u$","$3u^2-12=-u^2+2u$"],"설명":"$x+\\frac{1}{2}$ 을 $u$ 로 놓으면 방정식이 $u$ 에 관한 이차방정식이 된다.","확인":null,"스킬":"A1","고비":true},{"제목":"$u$ 에 관한 방정식 풀기","힌트":"모든 항을 한쪽으로 모아 인수분해하면?","식":["$4u^2-2u-12=0$","$2u^2-u-6=0$","$(2u+3)(u-2)=0$","$u=-\\frac{3}{2},\\ 2$"],"설명":"양변을 $2$ 로 나눈 뒤 인수분해한다.","확인":null,"스킬":"A1"},{"제목":"$x$ 로 되돌려 합 구하기","힌트":"$u=x+\\frac{1}{2}$ 이므로 각 $u$ 에 대응하는 $x$ 는?","식":["$x=u-\\frac{1}{2}=-2,\\ \\frac{3}{2}$","$-2+\\frac{3}{2}=-\\frac{1}{2}$"],"설명":"두 해의 합은 $-\\frac{1}{2}$ 이고, 선지 ② 이다.","확인":"-1/2","스킬":"A1"}],"fb":"fig/ns/"},"ns-b988b658f4e5":{"길":"그림의 $1$ 간격으로 세 변을 한 문자로 나타내고, 큰 정사각형의 넓이가 두 정사각형의 넓이 합과 같다는 식을 푼다","단계":[{"제목":"세 정사각형의 변의 길이","힌트":"그림에서 $1\\mathrm{cm}$ 간격은 정사각형의 한 변이 안쪽으로 얼마씩 줄어드는 것을 뜻할까?","식":["$a,\\ a-2,\\ a-4$"],"설명":"세 정사각형은 대각선의 중점이 일치하므로 한 변씩 $1\\mathrm{cm}$ 들어간다. 마주 보는 두 변이 함께 줄어 한 변의 길이는 $2\\mathrm{cm}$ 씩 줄어든다. 가장 큰 정사각형의 한 변을 $a$ 라 한다.","확인":null,"스킬":"C7"},{"제목":"넓이 조건을 식으로","힌트":"가장 큰 정사각형의 넓이가 나머지 두 정사각형 넓이의 합과 같다는 조건을 식으로 쓰면?","식":["$a^2=(a-2)^2+(a-4)^2$","$a^2-12a+20=0$","$(a-2)(a-10)=0$"],"설명":"우변을 전개해 정리하면 $a^2-12a+20=0$ 이다.","확인":null,"스킬":"C7","고비":true},{"제목":"$a$ 의 값 정하기","힌트":"가장 작은 정사각형의 변의 길이가 양수이려면 $a$ 는 얼마여야 할까?","식":["$a-4>0$","$a=10$"],"설명":"$a=2$ 이면 $a-4$ 가 음수여서 맞지 않다. 따라서 세 변의 길이는 $10$, $8$, $6$ 이다.","확인":"10","스킬":"C7"},{"제목":"어두운 부분의 넓이","힌트":"어두운 부분은 어느 두 정사각형 사이일까?","식":["$8^2-6^2=64-36=28$"],"설명":"어두운 부분은 중간 정사각형에서 가장 작은 정사각형을 뺀 부분이므로 넓이가 $28$ 이고, 선지 ② 이다.","확인":"28","스킬":"C7"}],"fb":"fig/ns/"},"ns-bf0da2c06782":{"길":"두 학생이 맞게 본 계수를 구분해 근의 꼴로 식을 세우고 원래 계수를 복원한 뒤 푼다","단계":[{"제목":"맞게 본 계수 가려내기","힌트":"원래 방정식을 $px^2+qx+r=0$ 이라 하면, 예진이와 윤진이는 각각 어느 계수를 맞게 보았을까?","식":["$px^2-2x+r=0$"],"설명":"선생님이 $x$ 의 계수가 $-2$ 라고 알려 주었다. 예진이는 $x^2$ 의 계수만, 윤진이는 상수항만 잘못 보았으므로 예진이가 푼 식에서는 $x$ 의 계수와 상수항이, 윤진이가 푼 식에서는 $x^2$ 의 계수와 $x$ 의 계수가 맞다.","확인":null,"스킬":"C7"},{"제목":"예진이의 식에서 상수항 구하기","힌트":"근이 $-1$, $2$ 인 이차방정식은 $m$ 을 $0$ 이 아닌 수라 하고 어떤 꼴로 쓸까?","식":["$m(x+1)(x-2)=mx^2-mx-2m$","$-m=-2$, $m=2$","$r=-2m=-4$"],"설명":"예진이가 푼 식에서 $x$ 의 계수는 $-2$ 이므로 $-m=-2$ 이다. 상수항 $-2m$ 이 원래 식의 상수항 $r$ 과 같다.","확인":"-4","스킬":"A2","고비":true},{"제목":"윤진이의 식에서 $x^2$ 의 계수 구하기","힌트":"근이 $-\\frac{1}{3}$, $\\frac{1}{2}$ 인 식의 $x$ 의 계수를 $-2$ 와 비교하면?","식":["$n\\left(x+\\frac{1}{3}\\right)\\left(x-\\frac{1}{2}\\right)=nx^2-\\frac{n}{6}x-\\frac{n}{6}$","$\\frac{n}{6}=2$","$n=12$"],"설명":"윤진이가 푼 식에서 $x$ 의 계수 $-\\frac{n}{6}$ 이 $-2$ 와 같아야 한다. 이 $n$ 이 원래 식의 $x^2$ 의 계수 $p$ 이다.","확인":"12","스킬":"A2"},{"제목":"원래 방정식 풀기","힌트":"복원한 방정식을 인수분해하면?","식":["$12x^2-2x-4=0$","$6x^2-x-2=0$","$(3x-2)(2x+1)=0$","$x=\\frac{2}{3},\\ -\\frac{1}{2}$"],"설명":"양변을 $2$ 로 나눈 뒤 인수분해하면 해가 $\\frac{2}{3}$, $-\\frac{1}{2}$ 이고, 선지 ③ 이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-d02c950a0d96":{"길":"분모를 유리화한 $x$ 에서 $x+2$ 를 제곱해 $x^2+4x$ 의 값을 얻고 식에 대입한다","단계":[{"제목":"$x$ 의 분모 유리화","힌트":"$\\frac{2}{1+\\sqrt2}$ 의 분모를 유리화하려면 무엇을 곱할까?","식":["$x=\\frac{2(\\sqrt2-1)}{(\\sqrt2+1)(\\sqrt2-1)}=2\\sqrt2-2$"],"설명":"분모와 분자에 $\\sqrt2-1$ 을 곱하면 분모가 $2-1=1$ 이 되어 $x=2\\sqrt2-2$ 이다.","확인":null,"스킬":"A6"},{"제목":"$x^2+4x$ 의 값 구하기","힌트":"$x+2$ 에서 근호가 하나만 남는다. 양변을 제곱하면 $x^2+4x$ 가 나올까?","식":["$x+2=2\\sqrt2$","$(x+2)^2=8,\\quad x^2+4x+4=8,\\quad x^2+4x=4$"],"설명":"$x=2\\sqrt2-2$ 에서 $x+2=2\\sqrt2$ 이다. 양변을 제곱하여 정리하면 $x^2+4x=4$ 이다. 근호가 든 값을 직접 대입하지 않고 식을 바꿔 쓰는 것이다.","확인":null,"스킬":"A6","고비":true},{"제목":"식의 값","힌트":"$5x^2+20x$ 를 $x^2+4x$ 로 묶어 대입하면?","식":["$5x^2+20x-13=5(x^2+4x)-13=5\\times4-13=7$"],"설명":"$5x^2+20x=5(x^2+4x)$ 이므로 $20-13=7$ 이고, 선지 ② 이다.","확인":"7","스킬":"A6"}],"fb":"fig/ns/"},"ns-d3aa5fd7bb4d":{"길":"직선 $l$ 의 식으로 $\\mathrm{P}$ 를 $a$ 로 나타내고 삼각형의 넓이식을 풀어 $a$, $b$ 를 구한다","단계":[{"제목":"직선 $l$ 의 식","힌트":"두 점 $(0,\\ -1)$, $(3,\\ 0)$ 을 지나는 직선의 기울기는?","식":["$\\frac{0-(-1)}{3-0}=\\frac{1}{3}$","$y=\\frac{1}{3}x-1$"],"설명":"기울기가 $\\frac{1}{3}$ 이고 $y$ 절편이 $-1$ 이므로 $l$ 의 식은 $y=\\frac{1}{3}x-1$ 이다.","확인":"1/3","스킬":"G10"},{"제목":"점 $\\mathrm{P}$ 를 $a$ 로 나타내기","힌트":"$m$ 이 $x$ 축에 수직이면 $\\mathrm{P}$ 의 $x$ 좌표는 무엇과 같을까?","식":["$\\mathrm{P}\\left(a,\\ \\frac{a-3}{3}\\right)$"],"설명":"$m$ 은 $x$ 축에 수직이므로 $\\mathrm{P}$ 의 $x$ 좌표 $a$ 는 $m$ 과 $x$ 축이 만나는 점의 $x$ 좌표와 같다. $l$ 의 식에 $x=a$ 를 넣으면 $y$ 좌표는 $\\frac{a}{3}-1=\\frac{a-3}{3}$ 이다. 삼각형의 밑변은 $(3,\\ 0)$ 에서 $(a,\\ 0)$ 까지의 $a-3$, 높이는 $\\frac{a-3}{3}$ 이다.","확인":null,"스킬":"G10","고비":true},{"제목":"$a$ 구하기","힌트":"삼각형의 넓이가 $24$ 라는 조건으로 $a$ 에 대한 식을 세우면?","식":["$\\frac{1}{2}(a-3)\\times\\frac{a-3}{3}=24$","$(a-3)^{2}=144$"],"설명":"양변에 $6$ 을 곱하면 $(a-3)^{2}=144$ 이다. $a>3$ 이므로 $a-3=12$ 이다.","확인":"15","스킬":"G10"},{"제목":"$b$ 구하기","힌트":"$a$ 의 값을 $P$ 의 $y$ 좌표에 넣으면?","식":["$b=\\frac{15-3}{3}=4$"],"설명":"$\\mathrm{P}$ 의 좌표는 $(15,\\ 4)$ 이고, 선지 ⑤ 이다.","확인":"4","스킬":"G10"}],"fb":"fig/ns/"},"ns-f48341cedf1f":{"길":"각을 따라가 이등변삼각형 두 개를 찾고 닮음으로 $\\overline{BC}$ 에 관한 이차방정식을 세운다","단계":[{"제목":"각 구하기","힌트":"$\\angle A=36^\\circ$ 인 이등변삼각형의 밑각은? 이등분선으로 나뉜 각은 얼마일까?","식":["$\\angle ABC=\\angle C=72^\\circ$","$\\angle ABD=\\angle DBC=36^\\circ$","$\\angle BDC=180^\\circ-72^\\circ-36^\\circ=72^\\circ$"],"설명":"$\\overline{AB}=\\overline{AC}$ 이므로 밑각은 $\\frac{180^\\circ-36^\\circ}{2}=72^\\circ$ 이다. $\\overline{BD}$ 는 $\\angle B$ 의 이등분선이므로 $\\angle DBC=36^\\circ$ 이다.","확인":null,"스킬":"S10"},{"제목":"같은 길이 찾기","힌트":"크기가 같은 두 각을 가진 삼각형 $ABD$, $BCD$ 는 어떤 삼각형일까?","식":["$\\overline{AD}=\\overline{BD}=\\overline{BC}$","$\\overline{BC}=x,\\ \\overline{AD}=x,\\ \\overline{DC}=2-x$"],"설명":"$\\triangle ABD$ 에서 $\\angle A=\\angle ABD=36^\\circ$ 이므로 $\\overline{AD}=\\overline{BD}$ 이다. $\\triangle BCD$ 에서 $\\angle C=\\angle BDC=72^\\circ$ 이므로 $\\overline{BD}=\\overline{BC}$ 이다. $\\overline{BC}=x$ 라 하면 $\\overline{AD}=x$ 이고 $\\overline{DC}=2-x$ 이다.","확인":null,"스킬":"S10"},{"제목":"닮은 삼각형 찾기","힌트":"$\\triangle ABC$ 와 각이 모두 같은 삼각형은?","식":["$\\triangle ABC\\backsim\\triangle BCD$","$\\overline{AB}:\\overline{BC}=\\overline{BC}:\\overline{CD}$"],"설명":"$\\triangle ABC$ 는 $36^\\circ$, $72^\\circ$, $72^\\circ$ 이고 $\\triangle BCD$ 도 $\\angle CBD=36^\\circ$, $\\angle C=72^\\circ$, $\\angle BDC=72^\\circ$ 이다. 세 각이 같으므로 닮음이다.","확인":null,"스킬":"S1","고비":true},{"제목":"이차방정식 세우기","힌트":"비례식에 $\\overline{AB}=2$, $\\overline{BC}=x$, $\\overline{CD}=2-x$ 를 넣으면?","식":["$2:x=x:(2-x)$","$x^{2}=2(2-x)$","$x^{2}+2x-4=0$"],"설명":"내항의 곱과 외항의 곱이 같으므로 $x^{2}=4-2x$ 이다.","확인":null,"스킬":"S1"},{"제목":"$x$ 구하기","힌트":"이차방정식의 해 중 길이가 될 수 있는 것은?","식":["$x=-1\\pm\\sqrt{5}$","$x=-1+\\sqrt{5}$"],"설명":"근의 공식으로 $x=\\frac{-2\\pm\\sqrt{4+16}}{2}=-1\\pm\\sqrt{5}$ 이다. $x>0$ 이므로 $\\overline{BC}=(-1+\\sqrt{5})\\ \\mathrm{cm}$ 이고 선지 ① 이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-f5fb947e591c":{"길":"두 작은 원의 반지름의 합이 큰 원의 반지름과 같음을 쓰고, 넓이 조건으로 곱을 구해 이차방정식을 푼다","단계":[{"제목":"반지름 사이의 관계","힌트":"세 원의 중심이 일직선 위에 있고 서로 접할 때, 두 작은 원의 지름의 합은 큰 원의 지름과 어떤 관계일까?","식":["$2r_1+2r_2=30$","$r_1+r_2=15$"],"설명":"두 작은 원의 반지름을 $r_1$, $r_2$ 라 한다. 두 작은 원의 지름이 큰 원의 지름 위에 이어 놓이므로 지름의 합이 $30$ 이다.","확인":null,"스킬":"A2"},{"제목":"색칠한 부분의 넓이식","힌트":"색칠한 부분은 큰 원에서 두 작은 원을 뺀 것이다. 넓이를 식으로 쓰면?","식":["$\\pi\\times15^2-\\pi r_1^2-\\pi r_2^2=72\\pi$","$r_1^2+r_2^2=153$"],"설명":"양변을 $\\pi$ 로 나누고 정리하면 $r_1^2+r_2^2=225-72=153$ 이다.","확인":"153","스킬":"C7"},{"제목":"두 반지름의 곱","힌트":"$(r_1+r_2)^2$ 을 전개한 식에 이미 구한 두 값을 넣으면?","식":["$(r_1+r_2)^2=r_1^2+r_2^2+2r_1r_2$","$225=153+2r_1r_2$","$r_1r_2=36$"],"설명":"합과 제곱의 합을 알면 곱을 구할 수 있다.","확인":"36","스킬":"A2","고비":true},{"제목":"작은 반지름 구하기","힌트":"합이 $15$, 곱이 $36$ 인 두 수는 어떻게 찾을까?","식":["$t(15-t)=36$","$t^2-15t+36=0$","$(t-3)(t-12)=0$","$t=3,\\ 12$"],"설명":"한 반지름을 $t$ 라 하면 다른 반지름은 $15-t$ 이다. 두 값은 $3$ 과 $12$ 이므로 가장 작은 원의 반지름은 $3\\mathrm{cm}$ 이고, 선지 ⑤ 이다.","확인":"3","스킬":"A2"}],"fb":"fig/ns/"},"ns-f90c54f27654":{"길":"$n$ 팀 리그전의 경기 수를 두 그룹에 적용하고 결승전 한 경기를 더해 이차방정식을 푼다","단계":[{"제목":"리그전의 경기 수","힌트":"$n$ 팀이 서로 한 번씩 경기하면 모두 몇 경기일까?","식":["$\\frac{n(n-1)}{2}$"],"설명":"각 팀이 나머지 $n-1$ 팀과 경기하면 $n(n-1)$ 인데, 한 경기를 두 팀이 중복해 센 것이므로 $2$ 로 나눈다.","확인":null,"스킬":"C7"},{"제목":"총 경기 수로 식 세우기","힌트":"A그룹을 $n$ 팀이라 하면 B그룹은 몇 팀이며, 두 그룹과 결승전의 경기 수를 합한 식은?","식":["$16-n$","$\\frac{n(n-1)}{2}+\\frac{(16-n)(15-n)}{2}+1=73$"],"설명":"B그룹은 $16-n$ 팀이다. 결승전은 한 경기이다.","확인":null,"스킬":"C7","고비":true},{"제목":"이차방정식 풀기","힌트":"식을 정리해 인수분해하면?","식":["$2n^2-32n+96=0$","$n^2-16n+48=0$","$(n-4)(n-12)=0$","$n=4,\\ 12$"],"설명":"양변에 $2$ 를 곱해 $n(n-1)+(16-n)(15-n)=144$ 로 만들고 전개하면 위의 식이 된다.","확인":null,"스킬":"C7"},{"제목":"조건에 맞는 값 고르기","힌트":"A그룹 팀 수가 B그룹 팀 수보다 많지 않다는 조건을 쓰면?","식":["$n\\le8$","$n=4$"],"설명":"두 그룹의 팀 수의 합이 $16$ 이므로 A그룹은 $8$ 팀 이하이다. 따라서 $4$ 팀이고, 선지 ③ 이다.","확인":"4","스킬":"C7"}],"fb":"fig/ns/"},"ns-fb78024d18e0":{"길":"두 작은 원의 지름의 합이 큰 원의 지름과 같음을 쓰고, 넓이 조건에서 합과 곱을 구해 이차방정식을 푼다","단계":[{"제목":"반지름 사이의 관계","힌트":"가장 큰 원의 반지름은 얼마이며, 두 작은 원의 반지름의 합은 얼마일까?","식":["$R=8$","$r_1+r_2=8$"],"설명":"두 작은 원의 지름이 큰 원의 지름 위에 이어 놓이므로 지름의 합이 $16$ 이다. 두 작은 원의 반지름을 $r_1$, $r_2$ 라 한다.","확인":null,"스킬":"A2"},{"제목":"색칠한 부분의 넓이식","힌트":"큰 원의 넓이에서 두 작은 원의 넓이를 빼고 $24\\pi$ 와 같다고 하면?","식":["$\\pi\\times8^2-\\pi r_1^2-\\pi r_2^2=24\\pi$","$r_1^2+r_2^2=40$"],"설명":"양변을 $\\pi$ 로 나누면 $r_1^2+r_2^2=64-24=40$ 이다.","확인":"40","스킬":"C7"},{"제목":"두 반지름의 곱","힌트":"$(r_1+r_2)^2$ 을 전개한 식에 이미 구한 두 값을 넣으면?","식":["$(r_1+r_2)^2=r_1^2+r_2^2+2r_1r_2$","$64=40+2r_1r_2$","$r_1r_2=12$"],"설명":"합과 제곱의 합을 알면 곱을 구할 수 있다.","확인":"12","스킬":"A2","고비":true},{"제목":"작은 원의 반지름","힌트":"합이 $8$, 곱이 $12$ 인 두 수는 어떻게 찾을까?","식":["$t(8-t)=12$","$t^2-8t+12=0$","$(t-2)(t-6)=0$","$t=2,\\ 6$"],"설명":"한 반지름을 $t$ 라 하면 다른 반지름은 $8-t$ 이다. 가장 작은 원의 반지름은 $2$ 이다.","확인":"2","스킬":"A2"},{"제목":"지름 구하기","힌트":"가장 작은 원의 반지름으로 지름을 구하면?","식":["$2\\times2=4$"],"설명":"지름은 반지름의 $2$ 배이므로 $4$ 이고, 선지 ② 이다.","확인":"4","스킬":"C7"}],"fb":"fig/ns/"},"ns-0eb0dc9081d8":{"길":"담장에 수직인 변을 $x$ 로 두고 넓이를 $x$ 의 이차식으로 세워 완전제곱 꼴로 고친다","단계":[{"제목":"꽃밭의 넓이를 $x$ 로 나타내기","힌트":"담장은 철망이 필요 없으므로 담장에 나란한 변의 길이는 $x$ 로 어떻게 쓸까?","식":["$16-2x$","$S=x(16-2x)$"],"설명":"철망 $16\\mathrm{m}$ 는 담장에 수직인 변 두 개와 담장에 나란한 변 한 개에 쓰인다. 꽃밭의 넓이를 $S$ 라 한다.","확인":null,"스킬":"C7"},{"제목":"완전제곱 꼴로 고치기","힌트":"$S$ 를 $-2(x-p)^2+q$ 꼴로 바꾸면?","식":["$S=-2x^2+16x$","$S=-2(x^2-8x+16)+32$","$S=-2(x-4)^2+32$"],"설명":"$x^2$ 의 계수 $-2$ 로 묶은 뒤 $x$ 의 계수의 절반의 제곱 $16$ 을 더하고 빼서 완전제곱식을 만든다.","확인":null,"스킬":"A6","고비":true},{"제목":"넓이가 최대일 때의 $x$","힌트":"$-2(x-4)^2$ 의 값은 언제 가장 커질까?","식":["$-2(x-4)^2\\le0$","$x=4$"],"설명":"$-2(x-4)^2$ 은 $0$ 이하이므로 $x=4$ 일 때 $S$ 가 최대값 $32$ 가 된다. $0<x<8$ 이므로 조건에 맞고, 선지 ③ 이다.","확인":"4","스킬":"A6"}],"fb":"fig/ns/"},"ns-12843b75883b":{"길":"$\\overline{EB}=\\overline{BC}=t$ 로 놓고 두 점 $\\mathrm{B}$, $\\mathrm{D}$ 의 좌표를 $t$ 로 나타내 곡선에 넣는다","단계":[{"제목":"점 $\\mathrm{B}$ 의 좌표","힌트":"$\\overline{EB}=\\overline{BC}=t$ 로 놓으면 점 $\\mathrm{B}$ 의 좌표는?","식":["$\\mathrm{B}(t,\\ t^2)$"],"설명":"점 $\\mathrm{E}$ 는 $y$ 축 위에 있고 $\\overline{EB}$ 는 $x$ 축에 평행하므로 점 $\\mathrm{B}$ 의 $x$ 좌표는 $t$ 이다. 점 $\\mathrm{B}$ 는 $y=x^2$ 위의 점이므로 $y$ 좌표는 $t^2$ 이다.","확인":null,"스킬":"S4"},{"제목":"점 $\\mathrm{D}$ 의 좌표","힌트":"정사각형의 한 변이 $t$ 이고 각 변이 축에 평행하다. 점 $\\\\mathrm{D}$ 의 좌표를 $t$ 로 나타내면?","식":["$\\mathrm{C}(2t,\\ t^2)$","$\\mathrm{D}(2t,\\ t^2+t)$"],"설명":"점 $\\mathrm{C}$ 는 점 $\\mathrm{B}$ 에서 오른쪽으로 $t$ 만큼 간 점이다. 점 $\\mathrm{D}$ 는 점 $\\mathrm{C}$ 에서 위로 $t$ 만큼 간 점이다.","확인":null,"스킬":"S4","고비":true},{"제목":"곡선 위의 점이라는 조건","힌트":"점 $\\mathrm{D}$ 도 $y=x^2$ 위에 있다는 조건을 식으로 쓰면?","식":["$(2t)^2=t^2+t$","$3t^2=t$","$t(3t-1)=0$","$t=\\frac{1}{3}$"],"설명":"$t>0$ 이므로 $t=0$ 은 버리고 $t=\\frac{1}{3}$ 이다.","확인":"1/3","스킬":"S4"},{"제목":"정사각형의 둘레","힌트":"한 변이 $t$ 인 정사각형의 둘레는?","식":["$4t=\\frac{4}{3}$"],"설명":"정사각형의 둘레는 한 변의 $4$ 배이므로 $\\frac{4}{3}$ 이고, 선지 ① 이다.","확인":"4/3","스킬":"S4"}],"fb":"fig/ns/"},"ns-12fab7c3ff5f":{"길":"한쪽 포물선을 평행이동하면 색칠한 부분이 직사각형이 됨을 이용해 넓이를 구한다","단계":[{"제목":"두 포물선의 꼭짓점","힌트":"두 식을 $y=(x-p)^2+q$ 꼴로 바꾸면 꼭짓점의 좌표는?","식":["$y=x^2-2x-3=(x-1)^2-4$","$y=x^2-6x+5=(x-3)^2-4$","$\\mathrm{P}(1,\\ -4)$","$\\mathrm{Q}(3,\\ -4)$"],"설명":"완전제곱식으로 고치면 꼭짓점이 바로 보인다.","확인":null,"스킬":"G4"},{"제목":"두 포물선 사이의 이동 관계","힌트":"첫째 포물선을 어느 방향으로 얼마만큼 옮기면 둘째 포물선과 겹칠까?","식":["$(x-1)^2-4\\ \\to\\ (x-3)^2-4$","$\\overline{\\mathrm{PQ}}=2$"],"설명":"두 식은 $x$ 의 값에서 $1$ 과 $3$ 만 다르다. 첫째 포물선을 $x$ 축 방향으로 $2$ 만큼 평행이동하면 둘째 포물선과 같다.","확인":null,"스킬":"G4","고비":true},{"제목":"색칠한 부분을 직사각형으로 바꾸기","힌트":"같은 높이에서 두 포물선 사이의 가로 거리는 얼마이고, 높이의 범위는 어디서 어디까지일까?","식":["$\\overline{\\mathrm{PQ}}=2$","$0-(-4)=4$"],"설명":"색칠한 부분은 $x$ 축, 선분 $\\mathrm{PQ}$ 와 두 포물선으로 둘러싸인다. 어느 높이에서도 두 포물선 사이의 가로 거리가 $2$ 이므로 첫째 포물선 쪽 조각을 $2$ 만큼 옮기면 가로 $2$, 세로 $4$ 인 직사각형이 된다.","확인":null,"스킬":"S12"},{"제목":"넓이 계산","힌트":"가로 $2$, 세로 $4$ 인 직사각형의 넓이는?","식":["$2\\times4=8$"],"설명":"평행이동해도 넓이는 변하지 않으므로 색칠한 부분의 넓이는 $8$ 이고, 선지 ③ 이다.","확인":"8","스킬":"S12"}],"fb":"fig/ns/"},"ns-1353fc397121":{"길":"그래프에서 $a$, $b$, $c$ 의 부호를 읽고 $x=1$, $x=-2$ 일 때의 함숫값 부호와 보기를 맞춰 본다","단계":[{"제목":"$a$ 와 $c$ 의 부호","힌트":"그래프의 볼록한 방향과 $y$ 절편은 각각 어떤 계수의 부호를 알려 줄까?","식":["$-a>0$","$a<0$","$c>0$"],"설명":"그래프가 아래로 볼록하므로 $x^2$ 의 계수 $-a$ 가 양수이다. $y$ 축과 원점 위쪽에서 만나므로 $y$ 절편 $c$ 가 양수이다.","확인":null,"스킬":"G6"},{"제목":"축의 위치로 $b$ 의 부호 구하기","힌트":"$y=-ax^2-bx+c$ 의 축의 방정식을 $a$, $b$ 로 나타내고 그림의 축 위치와 비교하면?","식":["$y=-a\\left(x+\\frac{b}{2a}\\right)^2+\\cdots$","$x=-\\frac{b}{2a}<0$","$\\frac{b}{2a}>0$","$b<0$"],"설명":"그림에서 꼭짓점이 $y$ 축 왼쪽에 있으므로 축의 $x$ 좌표가 음수이다. $a<0$ 이므로 $b$ 도 음수이다.","확인":null,"스킬":"G6","고비":true},{"제목":"보기 ①, ② 확인","힌트":"세 계수의 부호로 $ab$ 와 $ac$ 의 부호를 구하면?","식":["$ab>0$","$ac<0$"],"설명":"$a<0$, $b<0$ 이므로 $ab>0$ 이고, $a<0$, $c>0$ 이므로 $ac<0$ 이다. ① 과 ② 는 옳다.","확인":null,"스킬":"G6"},{"제목":"보기 ③, ④, ⑤ 확인","힌트":"$x=1$ 과 $x=-2$ 를 $y=-ax^2-bx+c$ 에 넣은 값은 각각 보기의 어느 식일까? 그림에서 그 부호는?","식":["$-a-b+c>0$","$-4a+2b+c>0$","$a+b-c<0$"],"설명":"$x=1$ 일 때 $y=-a-b+c$, $x=-2$ 일 때 $y=-4a+2b+c$ 이다. 그림에서 $x=1$ 과 $x=-2$ 는 $x$ 축과의 두 교점 바깥에 있어 $y>0$ 이므로 ④, ⑤ 는 옳다. ③ 의 $a+b-c$ 는 ④ 의 값에 $-1$ 을 곱한 값이므로 음수이다. 따라서 옳지 않은 것은 ③ 이다.","확인":null,"스킬":"G6"}],"fb":"fig/ns/"},"ns-361f1721b80a":{"길":"그래프에서 $a$, $c$ 의 부호를 읽고, 보기의 식을 특정한 $x$ 의 함숫값으로 바꾸어 부호를 판정한다","단계":[{"제목":"$a$ 와 $c$ 의 부호","힌트":"그래프의 볼록한 방향과 $y$ 절편으로 알 수 있는 것은?","식":["$a<0$","$c>0$","$ac<0$"],"설명":"위로 볼록하므로 $a<0$ 이고 $y$ 절편이 양수이므로 $c>0$ 이다. 따라서 ① 은 옳지 않다.","확인":null,"스킬":"G6"},{"제목":"보기의 식을 함숫값으로 바꾸기","힌트":"$x=1$, $-1$, $\\frac{1}{2}$, $-\\frac{1}{2}$ 를 $y=ax^2+bx+c$ 에 넣으면 보기의 어느 식과 맞을까?","식":["$x=1\\ \\Rightarrow\\ a+b+c$","$x=-1\\ \\Rightarrow\\ a-b+c$","$4\\left(\\frac{a}{4}+\\frac{b}{2}+c\\right)=a+2b+4c$","$4\\left(\\frac{a}{4}-\\frac{b}{2}+c\\right)=a-2b+4c$"],"설명":"④ 의 $a+2b+4c$ 는 $x=\\frac{1}{2}$ 일 때의 $y$ 값의 $4$ 배이고, ⑤ 의 $a-2b+4c$ 는 $x=-\\frac{1}{2}$ 일 때의 $y$ 값의 $4$ 배이다.","확인":null,"스킬":"G6","고비":true},{"제목":"그림에서 부호 읽기","힌트":"$x=1$, $-1$, $\\frac{1}{2}$, $-\\frac{1}{2}$ 는 $x$ 축과 만나는 두 점 사이에 있을까, 바깥에 있을까?","식":["$a+b+c<0$","$a-b+c<0$","$a+2b+4c<0$","$a-2b+4c>0$"],"설명":"그림에서 $x=1$, $x=-1$, $x=\\frac{1}{2}$ 은 두 교점의 바깥쪽에 있어 $y<0$ 이고, $x=-\\frac{1}{2}$ 은 두 교점 사이에 있어 $y>0$ 이다. 따라서 ② 와 ③ 은 옳지 않고 ④ 는 옳으며 ⑤ 는 옳지 않다.","확인":null,"스킬":"G6"}],"fb":"fig/ns/"},"ns-3f7885488c11":{"길":"처음 그래프에서 $a$, $b$, $c$ 의 부호를 읽고 새 이차함수의 계수 부호로 볼록한 방향, 축, $y$ 절편을 정한다","단계":[{"제목":"처음 그래프에서 부호 읽기","힌트":"그래프의 볼록한 방향, $y$ 절편, 축의 위치는 각각 어떤 부호를 알려 줄까?","식":["$a<0$","$c>0$","$-\\frac{b}{2a}<0$","$b<0$"],"설명":"위로 볼록하므로 $a<0$, $y$ 절편이 양수이므로 $c>0$ 이다. 축이 $y$ 축 왼쪽에 있어 $-\\frac{b}{2a}<0$ 이고 $a<0$ 이므로 $b<0$ 이다.","확인":null,"스킬":"G6"},{"제목":"새 이차함수의 계수 부호","힌트":"$a<0$, $b<0$, $c>0$ 일 때 $ab$, $bc$, $ac$ 의 부호는?","식":["$ab>0$","$bc<0$","$ac<0$"],"설명":"음수와 음수의 곱은 양수, 음수와 양수의 곱은 음수이다.","확인":null,"스킬":"G6","고비":true},{"제목":"개형 정하기","힌트":"새 함수 $y=abx^2+bcx+ac$ 에서 $x^2$ 의 계수, $y$ 절편, 축의 위치는 각각 어떻게 될까?","식":["$ab>0$","$ac<0$","$-\\frac{bc}{2ab}=-\\frac{c}{2a}>0$"],"설명":"$ab>0$ 이므로 아래로 볼록하고, $y$ 절편 $ac$ 가 음수이므로 원점 아래에서 $y$ 축과 만난다. 축은 $-\\frac{c}{2a}$ 이고 $c>0$, $a<0$ 이므로 양수여서 $y$ 축 오른쪽에 있다. 이 조건에 맞는 그래프는 ① 이다.","확인":null,"스킬":"G6"}],"fb":"fig/ns/"},"ns-549855284823":{"길":"직선의 높이를 $k$ 로 두고 $A$, $B$ 의 $x$좌표를 $a$ 로 나타내 선분의 비 조건에 넣는다","단계":[{"제목":"두 포물선과 직선의 교점","힌트":"직선 $l$ 을 $y=-k$ $(k>0)$ 로 놓으면 $B$ 와 $A$ 의 $x$좌표는 어떻게 쓸까?","식":["$-2x^2=-k$","$ax^2=-k$"],"설명":"그림에서 $A$ 는 $B$ 보다 왼쪽에 있다. $B$ 는 $y=-2x^2$ 위의 점이므로 $x$좌표가 $-\\sqrt{\\frac{k}{2}}$ 이고, $A$ 는 $y=ax^2$ 위의 점이므로 $x$좌표가 $-\\sqrt{-\\frac{k}{a}}$ 이다. 그림에서 두 그래프가 모두 위로 볼록하므로 $a<0$ 이다.","확인":null,"스킬":"S4"},{"제목":"선분의 길이를 $a$ 와 $k$ 로 나타내기","힌트":"$\\overline{BC}$ 와 $\\overline{AB}$ 를 $x$좌표의 차로 쓰면?","식":["$\\overline{BC}=\\sqrt{\\frac{k}{2}}$","$\\overline{AB}=\\sqrt{-\\frac{k}{a}}-\\sqrt{\\frac{k}{2}}$"],"설명":"$C$ 는 $y$축 위의 점이라 $x$좌표가 $0$ 이다. 같은 직선 $l$ 위의 두 점 사이 거리는 $x$좌표의 차이다.","확인":null,"스킬":"S4"},{"제목":"비 조건을 식으로 옮기기","힌트":"$5\\overline{AB}=2\\overline{BC}$ 에 두 길이를 넣고 양변을 $\\sqrt{k}$ 로 나누면?","식":["$5\\left(\\sqrt{-\\frac{k}{a}}-\\sqrt{\\frac{k}{2}}\\right)=2\\sqrt{\\frac{k}{2}}$","$5\\sqrt{-\\frac{1}{a}}=7\\sqrt{\\frac{1}{2}}$"],"설명":"$k>0$ 이므로 양변을 $\\sqrt{k}$ 로 나누어 $k$ 를 없앤다. 우변은 $2\\sqrt{\\frac12}+5\\sqrt{\\frac12}$ 이다.","확인":null,"스킬":"S4","고비":true},{"제목":"$a$ 의 값 구하기","힌트":"양변을 제곱해 $a$ 를 구하면?","식":["$-\\frac{25}{a}=\\frac{49}{2}$","$a=-\\frac{50}{49}$"],"설명":"양변을 제곱하면 $-\\frac{25}{a}=\\frac{49}{2}$ 이다. $|a|<2$ 라서 $y=ax^2$ 이 $y=-2x^2$ 보다 폭이 넓고, $A$ 가 $B$ 보다 왼쪽이라는 그림과 맞는다. 선지 ① 이다.","확인":"-50/49","스킬":"S4"}],"fb":"fig/ns/"},"ns-6df54432dcd9":{"길":"두 포물선이 $x=-3$ 에 대칭인 점을 이용해 정사각형을 그 점 중심에 놓고 한 변을 $2t$ 로 둔다","단계":[{"제목":"정사각형의 위치와 꼭짓점의 좌표","힌트":"두 그래프가 $x$축과 만나는 점으로 대칭의 중심을 찾고, 한 변을 $2t$ 로 두면 $B$ 의 좌표는?","식":["$x(x+6)=0$","$B(-3+t,\\ t)$"],"설명":"$y=\\frac18x(x+6)$ 은 $x=0$, $x=-6$ 에서 $x$축과 만나므로 두 그래프는 $x$축 위의 점 $(-3,\\ 0)$ 에 대해 대칭이다. 둘러싸인 부분과 정사각형도 이 점이 중심이므로 한 변을 $2t$ $(t>0)$ 로 두면 $B$ 는 $(-3+t,\\ t)$ 이다.","확인":null,"스킬":"G11","고비":true},{"제목":"꼭짓점을 포물선에 대입","힌트":"$B$ 는 위쪽 포물선 $y=-\\frac18x(x+6)$ 위에 있다. 좌표를 넣으면?","식":["$t=-\\frac18(t-3)(t+3)$","$8t=9-t^2$"],"설명":"$x=-3+t$ 이면 $x+6=3+t$ 이다. 곱 $(t-3)(t+3)$ 을 전개한 $t^2-9$ 에 부호를 붙여 정리한다.","확인":null,"스킬":"S4"},{"제목":"$t$ 의 이차방정식 풀기","힌트":"$t>0$ 인 근을 구하면?","식":["$t^2+8t-9=0$","$(t+9)(t-1)=0$","$t=1$"],"설명":"인수분해하면 $t=-9$ 또는 $t=1$ 이고, $t>0$ 이므로 $t=1$ 이다.","확인":"1","스킬":"S4"},{"제목":"정사각형의 넓이","힌트":"한 변의 길이 $2t$ 로 넓이를 구하면?","식":["$(2t)^2=2^2=4$"],"설명":"한 변이 $2$ 이므로 넓이는 $4$ 이고, 선지 ③ 이다.","확인":"4","스킬":"S4"}],"fb":"fig/ns/"},"ns-71fb7fcd394f":{"길":"그래프의 축에 대칭인 두 점의 가로를 $2t$ 로 두고 세로를 $t$ 의 식으로 나타내 합을 완전제곱꼴로 만든다","단계":[{"제목":"축과 두 점의 $x$좌표","힌트":"그래프의 대칭축은 어디이고, 가로를 $2t$ 로 두면 $A$, $D$ 의 $x$좌표는?","식":["$y=-(x+4)^2+16$","$A$ 의 $x$좌표 $-4-t$","$D$ 의 $x$좌표 $-4+t$"],"설명":"완전제곱꼴로 고치면 꼭짓점이 $(-4,\\ 16)$ 이라 대칭축은 $x=-4$ 이다. $A$, $D$ 는 같은 높이의 점이라 축에서 같은 거리에 있다. $\\overline{AD}=2t$ 로 두면 $A$, $D$ 의 $x$좌표는 $-4\\mp t$ 이고, $x$축 위쪽이므로 $0<t<4$ 이다.","확인":null,"스킬":"G11","고비":true},{"제목":"세로 길이를 $t$ 로 나타내기","힌트":"$D$ 의 $y$좌표를 $t$ 로 쓰면?","식":["$y=-(-4+t)^2-8(-4+t)$","$y=16-t^2$"],"설명":"$\\overline{CD}$ 는 $D$ 의 $y$좌표와 같다.","확인":null,"스킬":"G11"},{"제목":"가로와 세로의 합","힌트":"$2t+(16-t^2)$ 을 완전제곱꼴로 고치면?","식":["$2t+16-t^2=-(t-1)^2+17$"],"설명":"$t^2$ 의 계수가 $-1$ 이므로 위로 볼록한 이차식이다.","확인":null,"스킬":"G7"},{"제목":"범위 안의 최댓값","힌트":"$0<t<4$ 에서 $t$ 가 어떤 값일 때 합이 가장 클까?","식":["$t=1$ 일 때 $17$"],"설명":"꼭짓점의 $t=1$ 이 $0<t<4$ 안에 있으므로 최댓값이다. 선지 ② 이다.","확인":"17","스킬":"G7"}],"fb":"fig/ns/"},"ns-757012c8e3af":{"길":"직선에서 계수의 부호를 읽고 꼭짓점의 위치와 볼록한 방향으로 지나는 사분면을 판단한다","단계":[{"제목":"직선에서 $a$, $b$ 의 부호","힌트":"그래프의 기울기와 $y$절편의 부호는?","식":["$a>0$","$b<0$"],"설명":"그래프가 오른쪽 위로 향하므로 기울기 $a$ 는 양수이고, $y$축과 음의 부분에서 만나므로 $b$ 는 음수이다.","확인":null,"스킬":"G4"},{"제목":"꼭짓점의 위치","힌트":"$y=-(x+a)^2+b$ 의 꼭짓점과 볼록한 방향은?","식":["$(-a,\\ b)$"],"설명":"꼭짓점은 $(-a,\\ b)$ 이고 $x^2$ 의 계수가 $-1$ 이므로 위로 볼록하다. $a>0$, $b<0$ 이므로 꼭짓점이 제3사분면에 있다.","확인":null,"스킬":"G4","고비":true},{"제목":"지나는 사분면","힌트":"위로 볼록하고 최댓값이 음수인 그래프는 $x$축과 만날까?","식":["$y\\le b<0$"],"설명":"최댓값이 $b<0$ 이므로 그래프 전체가 $x$축 아래에 있다. 꼭짓점이 $y$축 왼쪽에 있고 그래프는 양쪽으로 한없이 내려가므로 제3, 4사분면을 지난다. 선지 ② 이다.","확인":null,"스킬":"G4"}],"fb":"fig/ns/"},"ns-7ff7a151b50d":{"길":"계수의 부호를 읽은 뒤 보기를 특정한 $x$ 의 함숫값 부호로 바꿔 그림과 맞춰 본다","단계":[{"제목":"그래프에서 $a$, $b$, $c$ 의 부호","힌트":"볼록한 방향, $y$절편, 대칭축의 위치에서 각 문자의 부호는?","식":["$a>0$","$c>0$","$b<0$"],"설명":"위로 볼록하므로 $-a<0$ 에서 $a>0$ 이다. $y$절편 $-3c$ 가 음수이므로 $c>0$ 이다. 대칭축은 $x=\\frac{b}{a}$ 이고 $y$축 왼쪽에 있으므로 $\\frac{b}{a}<0$ 이고, $a>0$ 이므로 $b<0$ 이다.","확인":null,"스킬":"G6"},{"제목":"보기를 함숫값으로 바꾸기","힌트":"$f(x)=-ax^2+2bx-3c$ 에서 $f(-1)$ 과 $f(2)$ 를 $a$, $b$, $c$ 로 나타내면?","식":["$f(-1)=-a-2b-3c$","$f(2)=-4a+4b-3c$"],"설명":"보기 다의 $a+2b+3c$ 는 $-f(-1)$ 이고, 보기 라의 $4a-4b+3c$ 는 $-f(2)$ 이다.","확인":null,"스킬":"G6","고비":true},{"제목":"그림에서 함숫값의 부호 읽기","힌트":"$x=-1$ 과 $x=2$ 에서 그래프는 $x$축 위에 있을까, 아래에 있을까?","식":["$f(-1)>0$","$f(2)<0$"],"설명":"점선이 $x=-1$ 에서 그래프까지 올라가므로 $f(-1)>0$ 이다. 오른쪽 $x$절편은 $-1$ 과 $0$ 사이이고 $x=2$ 는 그보다 오른쪽이므로 $f(2)<0$ 이다.","확인":null,"스킬":"G6"},{"제목":"보기 판정","힌트":"가, 나, 다, 라가 각각 위의 부호와 맞는지 확인하면?","식":["$b<0$","$ac>0$","$a+2b+3c<0$","$4a-4b>-3c$"],"설명":"가는 $b<0$ 이므로 참이다. 나는 $a>0$, $c>0$ 이므로 참이다. 다는 $f(-1)>0$ 에서 $-a-2b-3c>0$, 곧 $a+2b+3c<0$ 이므로 참이다. 라는 $f(2)<0$ 에서 $-4a+4b-3c<0$, 곧 $4a-4b>-3c$ 이므로 참이다. 네 개 모두 옳으므로 선지 ⑤ 이다.","확인":null,"스킬":"G6"}],"fb":"fig/ns/"},"ns-804a61763dff":{"길":"꼭짓점과 교점을 구한 뒤, 한 꼭짓점을 지나 넓이를 이등분하는 직선은 마주 보는 변의 중점을 지난다는 점을 쓴다","단계":[{"제목":"세 점의 좌표","힌트":"식을 인수분해하면 $x$축과의 교점은, 완전제곱꼴로 고치면 꼭짓점은?","식":["$y=-(x+5)(x-1)$","$y=-(x+2)^2+9$","$A(-2,\\ 9)$, $B(-5,\\ 0)$, $C(1,\\ 0)$"],"설명":"그림에서 $B$ 가 $C$ 보다 왼쪽에 있으므로 $B(-5,\\ 0)$, $C(1,\\ 0)$ 이다.","확인":null,"스킬":"S12"},{"제목":"넓이를 이등분하는 점","힌트":"$B$ 를 지나는 직선이 $\\overline{AC}$ 와 만나는 점을 $M$ 이라 할 때, $M$ 은 어디에 있어야 할까?","식":["$M\\left(\\frac{-2+1}{2},\\ \\frac{9+0}{2}\\right)=\\left(-\\frac12,\\ \\frac92\\right)$"],"설명":"$\\triangle ABM$ 과 $\\triangle MBC$ 는 꼭짓점 $B$ 에서 $\\overline{AC}$ 까지의 높이가 같다. 밑변 $\\overline{AM}$ 과 $\\overline{MC}$ 의 길이가 같아야 넓이가 같으므로 $M$ 은 $\\overline{AC}$ 의 중점이다.","확인":null,"스킬":"S12","고비":true},{"제목":"직선의 방정식","힌트":"$B(-5,\\ 0)$ 과 $M$ 을 지나는 직선의 기울기와 식은?","식":["$\\frac{\\frac92-0}{-\\frac12-(-5)}=1$","$y=x+5$"],"설명":"기울기가 $1$ 이고 $B(-5,\\ 0)$ 을 지나므로 $y=x+5$ 이다. 선지 ② 이다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-8c0bbb7dfe4c":{"길":"직선 위의 점 $A$ 의 좌표를 한 문자로 놓고 직사각형의 넓이를 이차식으로 쓴 뒤 완전제곱꼴로 고친다","단계":[{"제목":"직선의 식과 점 $A$ 의 좌표","힌트":"두 점을 지나는 직선의 식을 구하고, $A$ 의 $x$좌표를 $-t$ 로 두면 $y$좌표는?","식":["$y=\\frac23x+2$","$A\\left(-t,\\ -\\frac23t+2\\right)$","$0<t<3$"],"설명":"$(0,\\ 2)$, $(-3,\\ 0)$ 을 지나므로 기울기가 $\\frac{2}{3}$ 이고 $y$절편이 $2$ 이다. $A$ 가 제2사분면 위의 점이므로 $x$좌표 $-t$ 는 $-3$ 과 $0$ 사이이다.","확인":null,"스킬":"G7"},{"제목":"직사각형의 넓이 식","힌트":"$\\square ABOC$ 의 가로와 세로를 $t$ 로 나타내면?","식":["$\\overline{BO}=t$","$\\overline{AB}=-\\frac23t+2$","$S=t\\left(-\\frac23t+2\\right)$"],"설명":"$B$, $C$ 가 수선의 발이므로 $\\square ABOC$ 는 직사각형이다. 가로 $\\overline{BO}$ 는 $A$ 의 $x$좌표의 절댓값이고, 세로 $\\overline{AB}$ 는 $A$ 의 $y$좌표이다.","확인":null,"스킬":"C7","고비":true},{"제목":"완전제곱꼴로 고치기","힌트":"$S=-\\frac23t^2+2t$ 를 $a(t-p)^2+q$ 꼴로 고치면?","식":["$S=-\\frac23\\left(t-\\frac32\\right)^2+\\frac32$"],"설명":"$t^2$ 의 계수가 음수이므로 위로 볼록하고, 꼭짓점의 $t$ 에서 최댓값을 가진다.","확인":null,"스킬":"G7"},{"제목":"범위 안의 최댓값","힌트":"꼭짓점의 $t$ 값은 $0<t<3$ 안에 있을까?","식":["$t=\\frac32$ 일 때 $S=\\frac32$"],"설명":"$\\frac32$ 은 $0<t<3$ 안에 있으므로 최댓값은 $\\frac32$ 이다. 선지 ① 이다.","확인":"3/2","스킬":"G7"}],"fb":"fig/ns/"},"ns-927cdc093b33":{"길":"$y$축 대칭인 두 포물선 위의 네 점을 $x=\\pm p$ 로 놓고 변의 비를 $p$ 의 식으로 옮긴다","단계":[{"제목":"네 점의 좌표 놓기","힌트":"$\\overline{AD}$ 가 $x$축에 평행하고 두 포물선이 $y$축에 대칭이면 $A$, $D$, $B$ 의 좌표는?","식":["$A\\left(-p,\\ \\frac12p^2\\right)$","$D\\left(p,\\ \\frac12p^2\\right)$","$B\\left(-p,\\ -p^2\\right)$"],"설명":"$p>0$ 으로 둔다. $A$, $D$ 는 $y$좌표가 같고 $y$축에 대칭이므로 $x$좌표가 $\\mp p$ 이다. $\\overline{AB}$ 는 $y$축에 평행하므로 $B$ 의 $x$좌표는 $A$ 와 같고, $B$ 는 $y=-x^2$ 위의 점이다.","확인":null,"스킬":"S4","고비":true},{"제목":"두 변의 길이","힌트":"$\\overline{AD}$ 와 $\\overline{AB}$ 를 $p$ 로 나타내면?","식":["$\\overline{AD}=2p$","$\\overline{AB}=\\frac12p^2-(-p^2)=\\frac32p^2$"],"설명":"$\\overline{AD}$ 는 두 점의 $x$좌표의 차이고, $\\overline{AB}$ 는 $y$좌표의 차이다.","확인":null,"스킬":"S4"},{"제목":"비례식으로 $p$ 구하기","힌트":"$\\overline{AD}:\\overline{AB}=4:3$ 에서 $p$ 의 값은?","식":["$2p:\\frac32p^2=4:3$","$6p=6p^2$","$p=1$"],"설명":"외항의 곱과 내항의 곱이 같으므로 $3\\times2p=4\\times\\frac32p^2$ 이다. $p>0$ 이므로 양변을 $6p$ 로 나눈다.","확인":"1","스킬":"S4"},{"제목":"직사각형의 넓이","힌트":"$p=1$ 일 때 가로와 세로를 곱하면?","식":["$2\\times\\frac32=3$"],"설명":"가로 $\\overline{AD}=2$, 세로 $\\overline{AB}=\\frac32$ 이므로 넓이는 $3$ 이고, 선지 ② 이다.","확인":"3","스킬":"S4"}],"fb":"fig/ns/"},"ns-a5d134366426":{"길":"그림의 두 $x$절편과 $y$절편으로 $a$, $b$, $c$ 를 서로 이어 놓고 보기를 하나씩 확인한다","단계":[{"제목":"두 근으로 식 쓰기","힌트":"$x$축과 $-3$, $1$ 에서 만나고 위로 볼록한 포물선의 식을 $a$ 로 쓰면?","식":["$y=-a(x+3)(x-1)$","$y=-ax^2-2ax+3a$"],"설명":"위로 볼록하므로 $a>0$ 이다. 주어진 식 $y=-ax^2+2bx+c$ 와 이 식의 계수를 비교하는 것이 다음 단계이다.","확인":null,"스킬":"G6","고비":true},{"제목":"$b$, $c$ 를 $a$ 로 나타내기","힌트":"$x$ 의 계수와 상수항을 비교하면 $b$ 와 $c$ 는?","식":["$2b=-2a$","$c=3a$"],"설명":"$x$ 의 계수에서 $2b=-2a$, 곧 $b=-a$ 이다. 상수항에서 $c=3a$ 이다.","확인":null,"스킬":"G6"},{"제목":"$y$절편으로 값 확정","힌트":"그래프가 $y$축과 만나는 점으로 $c$ 와 $a$, $b$ 를 구하면?","식":["$c=4$","$a=\\frac43$","$b=-\\frac43$"],"설명":"$y$절편이 $c=4$ 이고 $c=3a$ 이므로 $a=\\frac43$ 이며 $b=-a=-\\frac43$ 이다.","확인":"4/3","스킬":"G6"},{"제목":"보기 대입","힌트":"각 보기에 $a$, $b$, $c$ 를 넣어 성립하는 것은?","식":["$\\frac{b}{a}=-1$","$9a-6b=20$","$2b+c=\\frac43$","$a+2b=-\\frac43$","$ac=\\frac{16}{3}$"],"설명":"① $\\frac{b}{a}=-1<0$ 이다. ② $9a-6b=12+8=20\\ne c$ 이다. ③ $2b+c=-\\frac83+4=\\frac43=a$ 로 성립한다. ④ $a+2b=-\\frac43<c$ 라서 $c<a+2b$ 가 아니다. ⑤ $ac>0$ 이다. 성립하는 것은 ③ 이다.","확인":null,"스킬":"G6"}],"fb":"fig/ns/"},"ns-bb3c3511551f":{"길":"철망이 쓰이는 곳을 세로 $3$ 줄과 가로 $1$ 줄로 세어 길이 조건을 식으로 옮긴 뒤 넓이의 최댓값을 구한다","단계":[{"제목":"철망 길이 조건","힌트":"세로 한 줄의 길이를 $x\\,\\mathrm{m}$ 라 하면, 담장 쪽에는 철망이 필요 없으므로 가로의 길이는?","식":["$3x+w=24$","$w=24-3x$","$0<x<8$"],"설명":"철망이 쓰이는 곳은 세로 $3$ 줄과 아래쪽 가로 한 줄이다. 가로를 $w\\,\\mathrm{m}$ 라 두고 철망의 길이가 $24\\,\\mathrm{m}$ 라는 조건을 쓴다. $w>0$ 이므로 $x<8$ 이다.","확인":null,"스킬":"C7","고비":true},{"제목":"두 우리의 넓이의 합","힌트":"두 우리를 합친 직사각형의 가로와 세로로 넓이를 쓰면?","식":["$S=x(24-3x)$","$S=-3x^2+24x$"],"설명":"두 우리의 넓이의 합은 가로 $24-3x$, 세로 $x$ 인 큰 직사각형의 넓이와 같다.","확인":null,"스킬":"C7"},{"제목":"완전제곱꼴로 고치기","힌트":"$S=-3x^2+24x$ 를 $a(x-p)^2+q$ 꼴로 고치면?","식":["$S=-3(x-4)^2+48$"],"설명":"$x^2$ 의 계수가 음수이므로 꼭짓점에서 최댓값을 가진다.","확인":null,"스킬":"G7"},{"제목":"범위 안의 최댓값","힌트":"꼭짓점의 $x$ 는 $0<x<8$ 안에 있을까?","식":["$x=4$ 일 때 $S=48$"],"설명":"$x=4$ 는 범위 안에 있으므로 넓이의 합의 최댓값은 $48\\,\\mathrm{m}^2$ 이고, 선지 ⑤ 이다.","확인":"48","스킬":"G7"}],"fb":"fig/ns/"},"ns-cd72b9545bd1":{"길":"선분의 비를 $x$좌표의 차의 비로 옮기고 대칭축으로 두 근을 잡아 $k$ 와 삼각형의 밑변, 높이를 구한다","단계":[{"제목":"대칭축과 꼭짓점","힌트":"식을 완전제곱꼴로 고치면 대칭축은?","식":["$y=-\\frac12(x-1)^2+\\frac{1+k}{2}$","$A\\left(1,\\ \\frac{1+k}{2}\\right)$"],"설명":"$-\\frac12x^2+x=-\\frac12(x-1)^2+\\frac12$ 이므로 꼭짓점의 $x$좌표는 $1$, 대칭축은 $x=1$ 이다.","확인":null,"스킬":"G11"},{"제목":"$B$ 의 $x$좌표","힌트":"$\\overline{AD}:\\overline{BD}=1:3$ 이면 $A$, $D$, $B$ 의 $x$좌표의 차는 어떤 비일까?","식":["$(1-0):(0-x_B)=1:3$","$x_B=-3$"],"설명":"$A$, $D$, $B$ 는 한 직선 위에 있으므로 선분의 길이의 비는 $x$좌표의 차의 비와 같다. $D$ 는 $y$축 위의 점이라 $x$좌표가 $0$ 이다.","확인":"-3","스킬":"G10","고비":true},{"제목":"$C$ 의 $x$좌표","힌트":"$B$, $C$ 는 대칭축에 대칭이다. $C$ 의 $x$좌표는?","식":["$\\frac{-3+x_C}{2}=1$","$x_C=5$"],"설명":"두 근의 중점이 대칭축 위에 있으므로 중점의 $x$좌표가 $1$ 이다.","확인":"5","스킬":"G11"},{"제목":"$k$ 의 값","힌트":"두 근이 $-3$, $5$ 이면 식을 인수분해꼴로 쓰고 상수항을 비교하면?","식":["$y=-\\frac12(x+3)(x-5)$","$y=-\\frac12x^2+x+\\frac{15}{2}$","$\\frac12k=\\frac{15}{2}$"],"설명":"$x^2$ 의 계수가 $-\\frac12$ 이므로 인수분해꼴 앞에 $-\\frac12$ 를 붙인다. 상수항을 비교해 $k$ 를 구한다.","확인":"15","스킬":"G10"},{"제목":"삼각형의 넓이","힌트":"밑변 $\\overline{BC}$ 와 높이로 넓이를 구하면?","식":["$\\overline{BC}=5-(-3)=8$","$A(1,\\ 8)$","$\\frac12\\times8\\times8=32$"],"설명":"$k=15$ 이므로 $A$ 의 $y$좌표는 $\\frac{1+15}{2}=8$ 이다. 높이는 $8$ 이고 선지 ⑤ 이다.","확인":"32","스킬":"G10"}],"fb":"fig/ns/"},"ns-d859f2d2a389":{"길":"그래프에서 $a$, $b$, $c$ 의 부호를 읽어 직선의 기울기와 $y$절편의 부호로 바꾼다","단계":[{"제목":"$a$, $c$ 의 부호","힌트":"볼록한 방향과 $y$절편으로 알 수 있는 것은?","식":["$-a>0$","$-c<0$"],"설명":"아래로 볼록하므로 $x^2$ 의 계수 $-a$ 가 양수이고 $a<0$ 이다. $y$절편 $-c$ 가 음수이므로 $c>0$ 이다.","확인":null,"스킬":"G9"},{"제목":"$b$ 의 부호","힌트":"꼭짓점이 $y$축의 어느 쪽에 있는지로 $b$ 의 부호는?","식":["$x=\\frac{b}{2a}<0$","$b>0$"],"설명":"대칭축 $x=\\frac{b}{2a}$ 가 $y$축 왼쪽에 있으므로 $\\frac{b}{2a}<0$ 이고, $a<0$ 이므로 $b>0$ 이다.","확인":null,"스킬":"G9"},{"제목":"직선의 기울기와 $y$절편의 부호","힌트":"$c-a$ 와 $-ab$ 의 부호는?","식":["$c-a>0$","$-ab>0$"],"설명":"$c>0$, $a<0$ 이므로 $c-a>0$ 이다. $a<0<b$ 이므로 $ab<0$, 곧 $-ab>0$ 이다.","확인":null,"스킬":"G4","고비":true},{"제목":"지나지 않는 사분면","힌트":"기울기와 $y$절편이 모두 양수인 직선은 어느 사분면을 지날까?","식":["$y=(c-a)x-ab$"],"설명":"기울기와 $y$절편이 모두 양수이므로 오른쪽 위로 향하며 $y$축의 양의 부분을 지난다. 제1, 2, 3사분면을 지나므로 지나지 않는 사분면은 제4사분면이고, 선지 ④ 이다.","확인":null,"스킬":"G4"}],"fb":"fig/ns/"},"ns-df00e4c37432":{"길":"직선의 두 절편에서 $a$, $b$ 를 읽은 뒤 이차함수를 완전제곱꼴로 고쳐 꼭짓점을 구한다","단계":[{"제목":"그래프에서 $a$, $b$ 읽기","힌트":"$(-2,\\ 0)$, $(0,\\ -3)$ 을 지나는 직선의 기울기와 $y$절편은?","식":["$a=\\frac{-3-0}{0-(-2)}=-\\frac32$","$b=-3$"],"설명":"기울기 $a$ 는 $x$ 의 증가량에 대한 $y$ 의 증가량의 비이고, $y$절편이 $b$ 이다.","확인":null,"스킬":"G9"},{"제목":"이차함수의 식","힌트":"$a$, $b$ 를 $y=-2ax^2+bx+1$ 에 넣으면?","식":["$y=-2\\times\\left(-\\frac32\\right)x^2+(-3)x+1$","$y=3x^2-3x+1$"],"설명":"$-2a=3$ 이므로 $x^2$ 의 계수가 $3$ 이다.","확인":null,"스킬":"A6"},{"제목":"꼭짓점의 좌표","힌트":"$3x^2-3x+1$ 을 완전제곱꼴로 고치면?","식":["$y=3\\left(x^2-x\\right)+1$","$y=3\\left(x-\\frac12\\right)^2+\\frac14$"],"설명":"$x^2-x$ 에 $\\frac14$ 을 더하고 빼서 완전제곱식을 만든다. 꼭짓점은 $\\left(\\frac12,\\ \\frac14\\right)$ 이고, 선지 ① 이다.","확인":null,"스킬":"A6","고비":true}],"fb":"fig/ns/"},"ns-df0c0ed11e9d":{"길":"폭과 대칭으로 $a$, $b$, $c$, $d$ 의 부호와 서로의 관계를 정리한 뒤 보기를 하나씩 가린다","단계":[{"제목":"계수의 부호","힌트":"아래로 볼록한 그래프와 위로 볼록한 그래프에서 이차항 계수의 부호는?","식":["$a>0$, $b>0$","$c<0$, $d<0$"],"설명":"$y=ax^2$, $y=bx^2$ 은 아래로 볼록하므로 계수가 양수이다. $y=cx^2$, $y=dx^2$ 은 위로 볼록하므로 계수가 음수이다.","확인":null,"스킬":"G4"},{"제목":"계수끼리의 관계","힌트":"폭이 좁은 쪽의 계수가 절댓값이 더 크고, $x$축에 대칭인 그래프는 계수의 부호만 바뀐다. 이 둘로 $a$, $b$, $c$, $d$ 를 이으면?","식":["$a>b>0$","$c=-b$","$d=-a$"],"설명":"$y=ax^2$ 이 $y=bx^2$ 보다 폭이 좁으므로 $a>b$ 이다. $y=bx^2$ 과 $y=cx^2$ 이 $x$축에 대칭이므로 $c=-b$ 이고, $y=ax^2$ 과 $y=dx^2$ 이 대칭이므로 $d=-a$ 이다.","확인":null,"스킬":"G4","고비":true},{"제목":"보기 판정","힌트":"각 보기에 $c=-b$, $d=-a$ 를 넣어 보면?","식":["$a+b+c+d=a+b-b-a=0$","$\\sqrt{(d-b)^2}=|d-b|=b-d$","$d=-a<-b=c$","$abcd=a^2b^2>0$","$a\\ne d$"],"설명":"㈀ 참이다. ㈁ $d<0<b$ 라서 $d-b<0$ 이므로 값이 $b-d$ 이고 $d-b$ 가 아니다. ㈂ 참이다. ㈃ 참이다. ㈄ $a>0>d$ 라서 $a\\ne d$ 이므로 거짓이다. 옳은 것은 ㈀, ㈂, ㈃ 이고 선지 ② 이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-e41420422193":{"길":"점 $P$ 의 좌표를 한 문자로 놓고 직사각형의 넓이를 이차식으로 쓴 뒤 완전제곱꼴로 고쳐 최댓값과 그때의 점을 구한다","단계":[{"제목":"점 $P$ 의 좌표","힌트":"$P$ 의 $x$좌표를 $-t$ 로 두면 $y$좌표는?","식":["$P\\left(-t,\\ \\frac12t-2\\right)$","$0<t<4$"],"설명":"$P$ 는 제3사분면 위의 점이므로 $-t<0$ 이고 $\\frac12t-2<0$ 에서 $t<4$ 이다.","확인":null,"스킬":"C7"},{"제목":"직사각형의 넓이 식","힌트":"$\\overline{OQ}$ 와 $\\overline{OR}$ 를 $t$ 로 나타내면?","식":["$\\overline{OQ}=t$","$\\overline{OR}=2-\\frac12t$","$S=t\\left(2-\\frac12t\\right)$"],"설명":"$Q$, $R$ 은 수선의 발이므로 $\\overline{OQ}$ 는 $P$ 의 $x$좌표의 절댓값, $\\overline{OR}$ 는 $y$좌표의 절댓값이다.","확인":null,"스킬":"C7","고비":true},{"제목":"완전제곱꼴로 고치기","힌트":"$S=-\\frac12t^2+2t$ 를 $a(t-p)^2+q$ 꼴로 고치면?","식":["$S=-\\frac12(t-2)^2+2$"],"설명":"$t^2$ 의 계수가 음수이므로 꼭짓점에서 최댓값을 가진다. $t=2$ 는 $0<t<4$ 안에 있으므로 최댓값은 $2$ 이다.","확인":"2","스킬":"G7"},{"제목":"그때의 점 $P$ 의 좌표","힌트":"$t=2$ 일 때 $P$ 의 좌표는?","식":["$P(-2,\\ -1)$"],"설명":"$x=-2$ 이고 $y=\\frac12\\times2-2=-1$ 이다. 넓이의 최댓값 $2$ 와 점 $P(-2,\\ -1)$ 은 선지 ④ 이다.","확인":null,"스킬":"G7"}],"fb":"fig/ns/"},"ns-e9bee22776a4":{"길":"선분의 비를 $x$좌표의 차의 비로 옮기고 대칭축으로 두 근을 잡아 $k$ 와 삼각형의 밑변, 높이를 구한다","단계":[{"제목":"대칭축과 꼭짓점","힌트":"식을 완전제곱꼴로 고치면 꼭짓점은?","식":["$y=-(x-1)^2+1+k$","$A(1,\\ 1+k)$"],"설명":"꼭짓점의 $x$좌표가 $1$ 이므로 대칭축은 $x=1$ 이다.","확인":null,"스킬":"G11"},{"제목":"$B$ 의 $x$좌표","힌트":"$\\overline{AD}:\\overline{DB}=1:3$ 이면 $A$, $D$, $B$ 의 $x$좌표의 차는 어떤 비일까?","식":["$(1-0):(0-x_B)=1:3$","$x_B=-3$"],"설명":"$A$, $D$, $B$ 는 한 직선 위에 있으므로 선분의 길이의 비는 $x$좌표의 차의 비와 같다. $D$ 는 $y$축 위의 점이라 $x$좌표가 $0$ 이다.","확인":"-3","스킬":"G10","고비":true},{"제목":"$C$ 의 $x$좌표","힌트":"$B$, $C$ 는 대칭축에 대칭이다. $C$ 의 $x$좌표는?","식":["$\\frac{-3+x_C}{2}=1$","$x_C=5$"],"설명":"두 근의 중점이 대칭축 위에 있으므로 중점의 $x$좌표가 $1$ 이다.","확인":"5","스킬":"G11"},{"제목":"$k$ 의 값","힌트":"두 근이 $-3$, $5$ 이면 식을 인수분해꼴로 쓰고 상수항을 비교하면?","식":["$y=-(x+3)(x-5)$","$y=-x^2+2x+15$"],"설명":"$x^2$ 의 계수가 $-1$ 이므로 인수분해꼴 앞에 $-1$ 을 붙인다. 상수항이 $k$ 이다.","확인":"15","스킬":"G10"},{"제목":"삼각형의 넓이","힌트":"밑변 $\\overline{BC}$ 와 높이로 넓이를 구하면?","식":["$\\overline{BC}=8$","$A(1,\\ 16)$","$\\frac12\\times8\\times16=64$"],"설명":"$k=15$ 이므로 $A$ 의 $y$좌표는 $1+15=16$ 이다. 높이는 $16$ 이고 선지 ② 이다.","확인":"64","스킬":"G10"}],"fb":"fig/ns/"},"ns-ff9338120783":{"길":"교점의 $x$좌표가 방정식 $ax^2-bx-c=0$ 의 두 근임을 이용해 인수분해꼴로 쓰고 계수를 비교한다","단계":[{"제목":"교점의 $x$좌표는 방정식의 근","힌트":"교점에서는 두 식의 $y$ 값이 같다. 어떤 방정식의 해일까?","식":["$ax^2=bx+c$","$ax^2-bx-c=0$"],"설명":"교점의 $x$좌표 $4$, $-2$ 가 이 이차방정식의 두 근이다.","확인":null,"스킬":"G1","고비":true},{"제목":"인수분해꼴로 쓰기","힌트":"근이 $4$, $-2$ 이고 $x^2$ 의 계수가 $a$ 인 이차식은?","식":["$ax^2-bx-c=a(x-4)(x+2)$","$ax^2-bx-c=ax^2-2ax-8a$"],"설명":"두 근을 알면 이차식을 $a(x-4)(x+2)$ 로 쓸 수 있다.","확인":null,"스킬":"G1"},{"제목":"계수 비교","힌트":"$x$ 의 계수와 상수항을 비교하면 $b$, $c$ 는?","식":["$-b=-2a$","$-c=-8a$","$b=2a$, $c=8a$"],"설명":"양변이 같은 이차식이므로 같은 차수의 계수가 같다.","확인":null,"스킬":"G1"},{"제목":"$c$ 는 $b$ 의 몇 배","힌트":"$\\frac{c}{b}$ 를 구하면?","식":["$\\frac{c}{b}=\\frac{8a}{2a}=4$"],"설명":"$a>0$ 이므로 약분할 수 있다. $c$ 는 $b$ 의 $4$ 배이고 선지 ⑤ 이다.","확인":"4","스킬":"G1"}],"fb":"fig/ns/"},"ns-01092a816e3a":{"길":"직각삼각형의 한 변을 연장해 이등변삼각형을 만들고, 외각의 성질로 $\\frac{A}{2}$ 를 직각삼각형의 한 각으로 만든다","단계":[{"제목":"세 변의 길이","힌트":"$\\cos A=\\frac{12}{13}$ 이 되도록 $\\angle C=90^\\circ$ 인 직각삼각형 $ABC$ 를 잡으면 $\\overline{BC}$ 는?","식":["$\\overline{AB}=13$, $\\overline{AC}=12$","$\\overline{BC}=\\sqrt{13^2-12^2}=5$"],"설명":"$\\cos A=\\frac{\\overline{AC}}{\\overline{AB}}$ 이므로 $\\overline{AB}=13$, $\\overline{AC}=12$ 로 잡는다. 나머지 변은 피타고라스 정리로 구한다.","확인":"5","스킬":"S3"},{"제목":"반각을 만드는 보조선","힌트":"$\\overline{CA}$ 를 $A$ 쪽으로 연장해 $\\overline{AD}=\\overline{AB}$ 인 점 $D$ 를 잡으면 $\\angle D$ 와 $\\angle A$ 사이에는 어떤 관계가 있을까?","식":["$\\overline{AD}=\\overline{AB}=13$","$\\angle BAC=2\\angle D$"],"설명":"$\\triangle ABD$ 는 $\\overline{AB}=\\overline{AD}$ 인 이등변삼각형이므로 $\\angle D=\\angle ABD$ 이다. $\\angle BAC$ 는 $\\triangle ABD$ 의 꼭짓점 $A$ 에서의 외각이므로 두 밑각의 합 $2\\angle D$ 와 같다(삼각형의 외각).","확인":null,"스킬":"S2","고비":true},{"제목":"큰 직각삼각형의 변","힌트":"$\\triangle BCD$ 에서 $\\overline{CD}$ 의 길이는?","식":["$\\overline{CD}=12+13=25$","$\\overline{BC}=5$"],"설명":"$D$ 는 $\\overline{CA}$ 의 연장선 위에 있으므로 $\\angle C=90^\\circ$ 인 직각삼각형 $BCD$ 가 만들어진다.","확인":"25","스킬":"S6"},{"제목":"$\\tan\\frac{A}{2}$ 의 값","힌트":"$\\angle D=\\frac{A}{2}$ 이므로 $\\tan D$ 를 구하면?","식":["$\\tan\\frac{A}{2}=\\tan D=\\frac{5}{25}=\\frac15$"],"설명":"$\\tan D=\\frac{\\overline{BC}}{\\overline{CD}}$ 이다. 선지 ④ 이다.","확인":"1/5","스킬":"S6"}],"fb":"fig/ns/"},"ns-0196fbdd1b62":{"길":"한 꼭짓점에서 마주 보는 변에 수선을 내려 특수각 직각삼각형 둘로 나누고 삼각비로 길이를 구한다","단계":[{"제목":"수선의 길이","힌트":"$B$ 에서 $\\overline{AC}$ 에 내린 수선의 발을 $H$ 라 하면 $\\triangle BCH$ 에서 $\\overline{BH}$ 는?","식":["$\\overline{BH}=4\\sqrt6\\sin45^\\circ=4\\sqrt3$","$\\overline{CH}=4\\sqrt6\\cos45^\\circ=4\\sqrt3$"],"설명":"점 $H$ 는 $B$ 에서 $\\overline{AC}$ 에 내린 수선의 발이다. $\\triangle BCH$ 는 $\\angle C=45^\\circ$ 인 직각삼각형이다.","확인":null,"스킬":"S2","고비":true},{"제목":"$\\overline{AH}$ 의 길이","힌트":"$\\angle A$ 는 몇 도이고 $\\triangle ABH$ 에서 $\\overline{AH}$ 는?","식":["$\\angle A=180^\\circ-75^\\circ-45^\\circ=60^\\circ$","$\\overline{AH}=\\frac{4\\sqrt3}{\\tan60^\\circ}=4$"],"설명":"삼각형의 내각의 합이 $180^\\circ$ 이다. $\\triangle ABH$ 는 $\\angle A=60^\\circ$ 인 직각삼각형이므로 $\\tan60^\\circ=\\frac{\\overline{BH}}{\\overline{AH}}$ 이다.","확인":"4","스킬":"S6"},{"제목":"$\\overline{AC}$ 의 길이","힌트":"$H$ 는 $\\overline{AC}$ 위에 있다. $\\overline{AC}$ 는?","식":["$\\overline{AC}=\\overline{AH}+\\overline{CH}=4+4\\sqrt3$"],"설명":"$\\angle A$, $\\angle C$ 가 모두 예각이므로 $H$ 는 $A$ 와 $C$ 사이에 있다.","확인":null,"스킬":"S6"},{"제목":"땅의 넓이","힌트":"밑변 $\\overline{AC}$, 높이 $\\overline{BH}$ 로 넓이를 구하면?","식":["$\\frac12\\times(4+4\\sqrt3)\\times4\\sqrt3=24+8\\sqrt3$"],"설명":"$\\frac12\\times4\\sqrt3\\times(4+4\\sqrt3)=2\\sqrt3(4+4\\sqrt3)=8\\sqrt3+24$ 이고 선지 ④ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-022261891ec8":{"길":"각을 따라가 직사각형의 변과 $15^\\circ$, $75^\\circ$ 가 있는 직각삼각형의 변을 구한 뒤 보기를 하나씩 계산한다","단계":[{"제목":"각의 크기","힌트":"$\\angle CAB$ 를 구하고 $\\angle DAB$ 는 몇 도인지 정하면?","식":["$\\angle CAB=30^\\circ$","$\\angle DAB=90^\\circ-45^\\circ-30^\\circ=15^\\circ$","$\\angle ABD=75^\\circ$"],"설명":"$\\triangle ABC$ 는 $\\angle C=90^\\circ$, $\\angle B=60^\\circ$ 이므로 $\\angle CAB=30^\\circ$ 이다. $\\angle DAF=90^\\circ$ 에서 $\\angle FAC$ 와 $\\angle CAB$ 를 뺀 것이 $\\angle DAB$ 이다. $\\triangle ABD$ 의 내각의 합으로 $\\angle ABD=75^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"직사각형 안의 변의 길이","힌트":"$\\overline{BC}$, $\\overline{AC}$ 를 구하고, 직각이등변삼각형인 $\\triangle AFC$, $\\triangle BCE$ 의 변은?","식":["$\\overline{BC}=1$, $\\overline{AC}=\\sqrt3$","$\\overline{AF}=\\overline{FC}=\\frac{\\sqrt6}{2}$","$\\overline{BE}=\\overline{CE}=\\frac{\\sqrt2}{2}$"],"설명":"빗변이 $2$ 이고 $\\angle B=60^\\circ$ 이므로 $\\overline{BC}=2\\cos60^\\circ=1$, $\\overline{AC}=2\\sin60^\\circ=\\sqrt3$ 이다. $\\triangle AFC$ 는 $\\angle F=90^\\circ$, $\\angle FAC=45^\\circ$ 인 직각이등변삼각형이다. $\\angle CBE=180^\\circ-75^\\circ-60^\\circ=45^\\circ$ 라서 $\\triangle BCE$ 도 직각이등변삼각형이다.","확인":null,"스킬":"S6","고비":true},{"제목":"보기 ①, ② 확인","힌트":"$\\square ADEF$ 의 가로와 세로, 두 삼각형의 넓이는?","식":["$\\square ADEF=\\frac{\\sqrt6}{2}\\times\\left(\\frac{\\sqrt6}{2}+\\frac{\\sqrt2}{2}\\right)=\\frac{3+\\sqrt3}{2}$","$\\triangle AFC+\\triangle BCE=\\frac34+\\frac14=1$"],"설명":"$\\overline{DE}=\\overline{AF}=\\frac{\\sqrt6}{2}$ 이고 $\\overline{AD}=\\overline{FC}+\\overline{CE}=\\frac{\\sqrt6+\\sqrt2}{2}$ 이다. 두 보기 모두 옳다.","확인":null,"스킬":"S6"},{"제목":"보기 ④, ⑤ 확인","힌트":"$\\triangle ABD$ 의 세 변으로 $\\sin$, $\\cos$ 값을 구하면?","식":["$\\overline{DB}=\\frac{\\sqrt6-\\sqrt2}{2}$, $\\overline{AD}=\\frac{\\sqrt6+\\sqrt2}{2}$, $\\overline{AB}=2$","$\\sin15^\\circ+\\sin75^\\circ=\\frac{\\sqrt6-\\sqrt2}{4}+\\frac{\\sqrt6+\\sqrt2}{4}=\\frac{\\sqrt6}{2}$","$\\cos15^\\circ+\\cos75^\\circ=\\frac{\\sqrt6+\\sqrt2}{4}+\\frac{\\sqrt6-\\sqrt2}{4}=\\frac{\\sqrt6}{2}$"],"설명":"$\\overline{DB}=\\overline{DE}-\\overline{BE}$ 이다. $\\sin15^\\circ=\\frac{\\overline{DB}}{\\overline{AB}}$, $\\sin75^\\circ=\\frac{\\overline{AD}}{\\overline{AB}}$ 이고 코사인은 이 둘이 서로 바뀐다. 두 보기 모두 옳다.","확인":null,"스킬":"S6"},{"제목":"보기 ③ 확인","힌트":"$\\tan15^\\circ$ 와 $\\tan75^\\circ$ 의 합은?","식":["$\\tan15^\\circ=\\frac{\\overline{DB}}{\\overline{AD}}=2-\\sqrt3$","$\\tan75^\\circ=\\frac{\\overline{AD}}{\\overline{DB}}=2+\\sqrt3$","$\\tan15^\\circ+\\tan75^\\circ=4$"],"설명":"합이 $4$ 이고 $2\\sqrt3$ 이 아니므로 ③ 이 옳지 않다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-1b6c526e94cf":{"길":"$\\overline{AC}$ 를 먼저 구한 뒤 직각삼각형 $ACD$ 에서 $\\tan 30^\\circ$ 로 $\\overline{AD}$ 를 잡는다","단계":[{"제목":"직각삼각형 $ABC$ 에서 $\\overline{AC}$","힌트":"$\\angle B=45^\\circ$ 인 직각삼각형 $ABC$ 에서 빗변이 $4\\sqrt{2}$ 일 때 $\\overline{AC}$ 는 어떤 삼각비로 구할까?","식":["$\\overline{AC}=4\\sqrt{2}\\times\\sin 45^\\circ=4\\sqrt{2}\\times\\frac{\\sqrt{2}}{2}=4$"],"설명":"$\\overline{AC}\\perp\\overline{BC}$ 이므로 $\\angle ACB=90^\\circ$ 이고, $\\overline{AC}$ 는 $\\angle B$ 의 대변이다.","확인":"4","스킬":"S6","고비":true},{"제목":"직각삼각형 $ACD$ 에서 $\\overline{AD}$","힌트":"그림에서 $\\angle CAD=90^\\circ$ 이다. $\\overline{AC}$ 와 $\\overline{AD}$ 를 잇는 삼각비는 무엇일까?","식":["$\\tan 30^\\circ=\\frac{\\overline{AD}}{\\overline{AC}}$","$x=4\\times\\frac{\\sqrt{3}}{3}=\\frac{4\\sqrt{3}}{3}$"],"설명":"$\\angle DCA=30^\\circ$ 의 대변이 $\\overline{AD}$, 밑변이 $\\overline{AC}$ 이므로 $\\overline{AD}=\\overline{AC}\\tan 30^\\circ$ 이다. 선지 ③ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-21561031fd90":{"길":"$A$ 에서 $\\overline{BC}$ 에 수선을 내려 $\\sin B$, $\\cos B$, $\\sin C$, $\\cos C$ 를 구한다","단계":[{"제목":"수선의 발까지의 거리","힌트":"$A$ 에서 $\\overline{BC}$ 에 수선을 내리면 직각삼각형 두 개가 생긴다. 두 삼각형의 높이가 같다는 조건으로 식을 세우면?","식":["$\\overline{AH}^2=5^2-h^2=(4\\sqrt{2})^2-(7-h)^2$","$25-h^2=32-49+14h-h^2$","$h=3$"],"설명":"$A$ 에서 $\\overline{BC}$ 에 내린 수선의 발을 $H$ 라 하고 $\\overline{BH}=h$ 로 놓는다. $\\overline{CH}=7-h$ 이고, 직각삼각형 $ABH$, $ACH$ 에서 피타고라스 정리로 $\\overline{AH}^2$ 을 각각 쓴다.","확인":"3","스킬":"S2","고비":true},{"제목":"높이 $\\overline{AH}$ 와 $\\overline{CH}$","힌트":"$\\overline{BH}$ 를 알면 $\\overline{AH}$, $\\overline{CH}$ 는 각각 얼마일까?","식":["$\\overline{AH}=\\sqrt{5^2-3^2}=4$","$\\overline{CH}=7-3=4$"],"설명":"직각삼각형 $ABH$ 에서 $\\overline{AH}$ 를 구하고, $\\overline{CH}=\\overline{BC}-\\overline{BH}$ 이다.","확인":"4","스킬":"S3"},{"제목":"네 삼각비 값","힌트":"$\\angle B$, $\\angle C$ 의 사인과 코사인을 직각삼각형 $ABH$, $ACH$ 의 변으로 읽으면?","식":["$\\sin B=\\frac{4}{5},\\ \\cos B=\\frac{3}{5}$","$\\sin C=\\frac{4}{4\\sqrt{2}}=\\frac{\\sqrt{2}}{2},\\ \\cos C=\\frac{4}{4\\sqrt{2}}=\\frac{\\sqrt{2}}{2}$"],"설명":"$\\overline{AB}=5$, $\\overline{AC}=4\\sqrt{2}$ 가 각각 빗변이다.","확인":null,"스킬":"S6"},{"제목":"분수의 값","힌트":"구한 값을 주어진 식에 넣으면?","식":["$\\frac{\\frac{\\sqrt{2}}{2}\\times\\frac{\\sqrt{2}}{2}}{\\frac{4}{5}\\times\\frac{3}{5}}=\\frac{\\frac{1}{2}}{\\frac{12}{25}}=\\frac{25}{24}$"],"설명":"분자는 $\\frac{1}{2}$, 분모는 $\\frac{12}{25}$ 이므로 값은 $\\frac{25}{24}$ 이고, 선지 ③ 이다.","확인":"25/24","스킬":"S6"}],"fb":"fig/ns/"},"ns-30f52e595973":{"길":"직각삼각형 $BFH$ 의 세 변 $1$, $\\sqrt{2}$, $\\sqrt{3}$ 에서 $\\sin x$, $\\cos x$ 를 읽는다","단계":[{"제목":"직각삼각형 $BFH$ 의 세 변","힌트":"$\\angle x$ 를 한 각으로 갖는 직각삼각형은 어느 것이고, 그 세 변은 얼마일까?","식":["$\\overline{BF}=1$","$\\overline{FH}=\\sqrt{2}$","$\\overline{BH}=\\sqrt{1^2+(\\sqrt{2})^2}=\\sqrt{3}$"],"설명":"$\\overline{BF}$ 는 밑면에 수직이므로 $\\angle BFH=90^\\circ$ 이다. $\\overline{FH}$ 는 밑면인 정사각형의 대각선이고, $\\overline{BH}$ 는 직각삼각형 $BFH$ 의 빗변이다.","확인":null,"스킬":"S11","고비":true},{"제목":"$\\sin x$ 와 $\\cos x$","힌트":"$\\angle x=\\angle BHF$ 에서 높이, 밑변, 빗변은 각각 어느 변일까?","식":["$\\sin x=\\frac{\\overline{BF}}{\\overline{BH}}=\\frac{1}{\\sqrt{3}}=\\frac{\\sqrt{3}}{3}$","$\\cos x=\\frac{\\overline{FH}}{\\overline{BH}}=\\frac{\\sqrt{2}}{\\sqrt{3}}=\\frac{\\sqrt{6}}{3}$"],"설명":"$\\overline{BF}$ 가 $\\angle x$ 의 대변, $\\overline{FH}$ 가 밑변이다.","확인":null,"스킬":"S6"},{"제목":"두 값의 차","힌트":"두 값을 뺀 결과는?","식":["$\\sin x-\\cos x=\\frac{\\sqrt{3}-\\sqrt{6}}{3}$"],"설명":"분모가 같으므로 분자끼리 뺀다. 선지 ⑤ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-324d8024e4ed":{"길":"탑의 높이를 $h$ 로 두고 $\\overline{AD}-\\overline{BD}=50$ 에 삼각비를 쓴다","단계":[{"제목":"$\\overline{AD}$, $\\overline{BD}$ 를 $h$ 로","힌트":"탑의 높이를 $h$ 라 하면 두 직각삼각형에서 $\\overline{AD}$, $\\overline{BD}$ 는 $h$ 로 어떻게 나타날까?","식":["$\\overline{AD}=\\frac{h}{\\tan 30^\\circ}=\\sqrt{3}\\,h$","$\\overline{BD}=\\frac{h}{\\tan 45^\\circ}=h$"],"설명":"$\\overline{CD}=h$ 로 놓는다. 직각삼각형 $ACD$ 에서 $\\angle A=30^\\circ$, 직각삼각형 $BCD$ 에서 $\\angle CBD=45^\\circ$ 이다.","확인":null,"스킬":"S6","고비":true},{"제목":"$h$ 에 대한 식","힌트":"$\\overline{AB}=50$ 을 $h$ 의 식으로 나타내면?","식":["$\\sqrt{3}\\,h-h=50$","$h=\\frac{50}{\\sqrt{3}-1}$"],"설명":"$\\overline{AB}=\\overline{AD}-\\overline{BD}$ 이다.","확인":null,"스킬":"S6"},{"제목":"분모의 유리화","힌트":"분모에 근호가 있으므로 분모를 어떻게 바꿀까?","식":["$h=\\frac{50(\\sqrt{3}+1)}{(\\sqrt{3}-1)(\\sqrt{3}+1)}=25(1+\\sqrt{3})$"],"설명":"분모와 분자에 $\\sqrt{3}+1$ 을 곱한다. 선지 ② 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-3fb19f9ed933":{"길":"좌표로 삼각형 $ABC$ 의 넓이를 구해 $\\sin B$ 를 찾고 $\\cos B$ 를 잇는다","단계":[{"제목":"두 변의 길이","힌트":"$B$ 에서 $A$, $C$ 까지의 가로·세로 거리로 $\\overline{BA}$, $\\overline{BC}$ 를 구하면?","식":["$\\overline{BA}=\\sqrt{8^2+4^2}=4\\sqrt{5}$","$\\overline{BC}=\\sqrt{4^2+3^2}=5$"],"설명":"$B(-2,\\ 2)$ 에서 $A(6,\\ 6)$ 까지 가로 $8$, 세로 $4$ 이고, $C(2,\\ -1)$ 까지 가로 $4$, 세로 $3$ 이다. 피타고라스 정리를 쓴다.","확인":null,"스킬":"S4"},{"제목":"삼각형 $ABC$ 의 넓이","힌트":"세 점을 모두 둘러싸는 직사각형에서 남는 직각삼각형 세 개를 빼면?","식":["$8\\times 7=56$","$\\frac{1}{2}\\times4\\times3+\\frac{1}{2}\\times4\\times7+\\frac{1}{2}\\times8\\times4=36$","$56-36=20$"],"설명":"$x$ 좌표는 $-2$ 에서 $6$ 까지, $y$ 좌표는 $-1$ 에서 $6$ 까지이므로 둘러싸는 직사각형은 가로 $8$, 세로 $7$ 이다. 빼는 세 직각삼각형의 직각을 낀 두 변은 각각 $(4,\\ 3)$, $(4,\\ 7)$, $(8,\\ 4)$ 이다.","확인":"20","스킬":"S8","고비":true},{"제목":"$\\sin B$","힌트":"넓이를 두 변과 끼인각 $B$ 로 쓰면 $\\sin B$ 는?","식":["$\\frac{1}{2}\\times4\\sqrt{5}\\times5\\times\\sin B=20$","$\\sin B=\\frac{2}{\\sqrt{5}}=\\frac{2\\sqrt{5}}{5}$"],"설명":"$10\\sqrt{5}\\sin B=20$ 에서 $\\sin B$ 를 구한다.","확인":null,"스킬":"S6"},{"제목":"$\\cos B$","힌트":"$\\sin^2B+\\cos^2B=1$ 에서 $\\cos B$ 는? 그림에서 $\\angle B$ 는 예각이다.","식":["$\\cos^2B=1-\\frac{4}{5}=\\frac{1}{5}$","$\\cos B=\\frac{\\sqrt{5}}{5}$"],"설명":"$\\angle B$ 가 예각이므로 $\\cos B>0$ 이다.","확인":null,"스킬":"S6"},{"제목":"합","힌트":"두 값을 더하면?","식":["$\\sin x^\\circ+\\cos x^\\circ=\\frac{2\\sqrt{5}}{5}+\\frac{\\sqrt{5}}{5}=\\frac{3\\sqrt{5}}{5}$"],"설명":"$x=\\angle ABC$ 이므로 위에서 구한 값을 더한다. 선지 ④ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-4149c6e90258":{"길":"직각삼각형 $ABC$ 에서 $\\overline{BC}$ 를 구해 직각삼각형 $DBC$ 로 옮긴다","단계":[{"제목":"$\\overline{BC}$ 의 길이","힌트":"직각삼각형 $ABC$ 에서 $\\overline{AB}$ 와 $\\overline{BC}$ 를 잇는 삼각비는?","식":["$\\tan 60^\\circ=\\frac{\\overline{BC}}{8}$","$\\overline{BC}=8\\sqrt{3}$"],"설명":"$\\angle ABC=90^\\circ$, $\\angle A=60^\\circ$ 이므로 $\\overline{BC}$ 는 $\\angle A$ 의 대변이고 $\\overline{AB}$ 는 밑변이다.","확인":null,"스킬":"S6","고비":true},{"제목":"$\\overline{BD}$ 의 길이","힌트":"직각삼각형 $DBC$ 에서 $\\overline{BC}$ 는 $\\angle D$ 의 대변이고 $\\overline{BD}$ 는 빗변이다. 어떤 삼각비를 쓸까?","식":["$\\sin 45^\\circ=\\frac{8\\sqrt{3}}{\\overline{BD}}$","$\\overline{BD}=8\\sqrt{3}\\times\\sqrt{2}=8\\sqrt{6}$"],"설명":"$\\angle DCB=90^\\circ$ 이다. 선지 ③ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-6645283864f1":{"길":"공통각으로 닮음을 찾아 BD 를 구하고 넓이의 비로 삼각형 BCD 의 넓이를 구한다","단계":[{"제목":"닮은 두 삼각형 찾기","힌트":"$\\triangle \\mathrm{ACD}$ 와 $\\triangle \\mathrm{ABC}$ 에서 크기가 같은 두 각은 어느 것인가?","식":["$\\angle \\mathrm{A}$ 는 공통","$\\angle \\mathrm{ACD}=\\angle \\mathrm{ABC}=30^{\\circ}$","$\\triangle \\mathrm{ACD}\\sim\\triangle \\mathrm{ABC}$ (AA 닮음)"],"설명":"두 쌍의 대응각의 크기가 각각 같으므로 닮음이다. 대응 순서는 $\\mathrm{A}\\to\\mathrm{A}$, $\\mathrm{C}\\to\\mathrm{B}$, $\\mathrm{D}\\to\\mathrm{C}$ 이다.","확인":null,"스킬":"S1","고비":true},{"제목":"$\\overline{\\mathrm{AD}}$ 와 $\\overline{\\mathrm{BD}}$ 의 길이","힌트":"대응변의 비 $\\overline{\\mathrm{AC}}:\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AD}}:\\overline{\\mathrm{AC}}$ 에서 $\\overline{\\mathrm{AD}}$ 는?","식":["$6:8=\\overline{\\mathrm{AD}}:6$ 에서 $\\overline{\\mathrm{AD}}=\\frac{36}{8}=\\frac{9}{2}$","$\\overline{\\mathrm{BD}}=\\overline{\\mathrm{AB}}-\\overline{\\mathrm{AD}}=8-\\frac{9}{2}=\\frac{7}{2}$"],"설명":"닮은 도형에서 대응변의 길이의 비는 같으므로 비례식을 세운다.","확인":"7/2","스킬":"S1"},{"제목":"$\\triangle \\mathrm{ABC}$ 의 넓이","힌트":"두 변 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{BC}}$ 와 끼인각 $\\angle \\mathrm{B}$ 로 넓이를 쓰면?","식":["$\\triangle \\mathrm{ABC}=\\frac{1}{2}\\times 8\\times 9\\times\\sin 30^{\\circ}=\\frac{1}{2}\\times 8\\times 9\\times\\frac{1}{2}=18$"],"설명":"두 변과 그 끼인각을 알 때 삼각형의 넓이는 $\\frac{1}{2}ab\\sin\\theta$ 이다. $\\theta$ 는 끼인각이다.","확인":"18","스킬":"S6"},{"제목":"$\\triangle \\mathrm{BCD}$ 의 넓이","힌트":"꼭짓점 C 가 같아 높이가 같은 두 삼각형의 넓이의 비는 무엇의 비와 같은가?","식":["$\\triangle \\mathrm{BCD}:\\triangle \\mathrm{ABC}=\\overline{\\mathrm{BD}}:\\overline{\\mathrm{AB}}=\\frac{7}{2}:8=7:16$","$\\triangle \\mathrm{BCD}=18\\times\\frac{7}{16}=\\frac{63}{8}$"],"설명":"높이가 같은 두 삼각형의 넓이의 비는 밑변의 길이의 비와 같다.","확인":"63/8","스킬":"S8"}]},"ns-76606369551f":{"길":"$2\\sin A=\\cos A$ 를 두 변의 비 $1:2$ 로 바꾸고 피타고라스로 길이를 구한다","단계":[{"제목":"두 변의 비","힌트":"$\\overline{AB}$ 가 지름이면 $\\angle C$ 는 몇 도일까? $\\sin A$, $\\cos A$ 를 변으로 나타내면?","식":["$2\\times\\frac{\\overline{BC}}{10}=\\frac{\\overline{AC}}{10}$","$\\overline{AC}=2\\overline{BC}$"],"설명":"반원에 대한 원주각이므로 $\\angle C=90^\\circ$ 이다. 빗변이 $\\overline{AB}=10$ 이므로 $\\sin A=\\frac{\\overline{BC}}{10}$, $\\cos A=\\frac{\\overline{AC}}{10}$ 이다.","확인":null,"스킬":"S6","고비":true},{"제목":"$\\overline{BC}$ 의 제곱","힌트":"$\\overline{BC}=a$ 라 하면 피타고라스 정리는 어떤 식이 될까?","식":["$a^2+(2a)^2=10^2$","$a^2=20$"],"설명":"$\\overline{AC}=2a$ 이다.","확인":null,"스킬":"S3"},{"제목":"삼각형의 넓이","힌트":"두 변이 $a$, $2a$ 인 직각삼각형의 넓이는?","식":["$\\frac{1}{2}\\times a\\times2a=a^2=20$"],"설명":"밑변과 높이가 각각 $\\overline{BC}$, $\\overline{AC}$ 이다. 선지 ① 이다.","확인":"20","스킬":"S6"}],"fb":"fig/ns/"},"ns-79a0d57440d8":{"길":"$P$ 에서 $\\overline{BQ}$ 에 수선을 내려 $\\sin x$ 를 만든다","단계":[{"제목":"점 $F$ 에서 $Q$ 까지","힌트":"$\\overline{FQ}$ 는 밑면의 어느 직각삼각형의 빗변일까?","식":["$\\overline{FQ}=\\sqrt{2^2+1^2}=\\sqrt{5}$"],"설명":"한 모서리가 $2$ 이므로 $\\overline{BP}=\\overline{PF}=1$, $\\overline{GQ}=1$ 이다. 밑면의 직각삼각형 $FGQ$ 에서 $\\overline{FG}=2$, $\\overline{GQ}=1$ 이다.","확인":null,"스킬":"S11"},{"제목":"$\\overline{BQ}$ 와 $\\overline{PQ}$","힌트":"$\\overline{BF}$, $\\overline{PF}$ 는 밑면에 수직이다. 이 점을 이용해 $\\overline{BQ}$, $\\overline{PQ}$ 를 구하면?","식":["$\\overline{BQ}=\\sqrt{\\overline{FQ}^2+2^2}=3$","$\\overline{PQ}=\\sqrt{\\overline{FQ}^2+1^2}=\\sqrt{6}$"],"설명":"직각삼각형 $BFQ$, $PFQ$ 에서 피타고라스 정리를 쓴다. 삼각형 $BPQ$ 의 세 변은 $\\overline{BP}=1$, $\\overline{BQ}=3$, $\\overline{PQ}=\\sqrt{6}$ 이다.","확인":null,"스킬":"S3"},{"제목":"수선으로 만든 길이","힌트":"삼각형 $BPQ$ 는 직각삼각형이 아니다. $P$ 에서 $\\overline{BQ}$ 에 수선을 내리고 그 두 조각을 문자로 놓으면 어떤 식이 나올까?","식":["$\\overline{PK}^2=6-q^2=1-(3-q)^2$","$6-q^2=1-9+6q-q^2$","$q=\\frac{7}{3}$"],"설명":"$P$ 에서 $\\overline{BQ}$ 에 내린 수선의 발을 $K$ 라 하고 $\\overline{QK}=q$ 로 놓는다. $\\overline{BK}=3-q$ 이고, 직각삼각형 $PQK$, $PBK$ 에서 $\\overline{PK}^2$ 을 각각 쓴다.","확인":null,"스킬":"S2","고비":true},{"제목":"$\\sin x$","힌트":"$\\overline{PK}$ 를 구한 뒤 $\\sin x$ 는 어느 두 변의 비일까?","식":["$\\overline{PK}^2=6-\\frac{49}{9}=\\frac{5}{9}$","$\\sin x=\\frac{\\overline{PK}}{\\overline{PQ}}=\\frac{\\sqrt{5}}{3\\sqrt{6}}=\\frac{\\sqrt{30}}{18}$"],"설명":"$x=\\angle PQK$ 이다. 선지 ④ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-7e224eaaf449":{"길":"$\\tan A$ 가 $1$ 보다 큰 것으로 근호 안의 부호를 정한다","단계":[{"제목":"$\\tan A$ 와 $1$ 의 크기","힌트":"$45^\\circ<A<90^\\circ$ 에서 $\\tan A$ 는 $\\tan 45^\\circ$ 보다 클까, 작을까?","식":["$\\tan A>\\tan 45^\\circ=1$"],"설명":"$0^\\circ$ 에서 $90^\\circ$ 사이에서는 각이 커질수록 $\\tan$ 값이 커진다.","확인":null,"스킬":"S6","고비":true},{"제목":"근호 벗기기","힌트":"$\\sqrt{x^2}=|x|$ 임을 쓰려면 근호 안의 식의 부호는?","식":["$\\sqrt{(\\tan A+1)^2}=\\tan A+1$","$\\sqrt{(1-\\tan A)^2}=|1-\\tan A|=\\tan A-1$"],"설명":"$\\tan A+1>0$ 이고 $1-\\tan A<0$ 이므로 두 번째는 부호를 바꿔서 벗긴다.","확인":null,"스킬":"C2"},{"제목":"합","힌트":"두 식을 더하면?","식":["$(\\tan A+1)+(\\tan A-1)=2\\tan A$"],"설명":"선지 ⑤ 이다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-8d6555386e7e":{"길":"$\\triangle BMC$ 의 세 변을 구하고 $B$ 에서 $\\overline{MC}$ 에 수선을 내려 $\\tan x$ 를 잡는다","단계":[{"제목":"$\\triangle BMC$ 의 세 변","힌트":"한 모서리를 $2$ 로 놓으면 $\\overline{BM}$, $\\overline{CM}$ 은 정삼각형의 무엇일까?","식":["$\\overline{BM}=\\overline{CM}=\\sqrt{2^2-1^2}=\\sqrt{3}$","$\\overline{BC}=2$"],"설명":"정사면체의 면은 모두 합동인 정삼각형이다. $M$ 이 $\\overline{AD}$ 의 중점이므로 $\\overline{BM}$, $\\overline{CM}$ 은 각각 정삼각형 $ABD$, $ACD$ 의 높이이다.","확인":null,"스킬":"S11"},{"제목":"$M$ 에서 $\\overline{BC}$ 에 내린 수선","힌트":"$\\triangle BMC$ 는 이등변삼각형이다. $\\overline{BC}$ 의 중점을 $N$ 이라 하면 $\\overline{MN}$ 은?","식":["$\\overline{MN}=\\sqrt{(\\sqrt{3})^2-1^2}=\\sqrt{2}$","$\\triangle BMC=\\frac{1}{2}\\times2\\times\\sqrt{2}=\\sqrt{2}$"],"설명":"이등변삼각형의 꼭짓점에서 밑변에 내린 수선은 밑변을 수직이등분한다. 그래서 $\\overline{BN}=1$ 이다.","확인":null,"스킬":"S2","고비":true},{"제목":"$B$ 에서 $\\overline{MC}$ 에 내린 수선","힌트":"넓이를 다른 밑변으로 한 번 더 쓰면 높이는?","식":["$\\frac{1}{2}\\times\\sqrt{3}\\times\\overline{BK}=\\sqrt{2}$","$\\overline{BK}=\\frac{2\\sqrt{2}}{\\sqrt{3}}=\\frac{2\\sqrt{6}}{3}$"],"설명":"$B$ 에서 $\\overline{MC}$ 에 내린 수선의 발을 $K$ 라 한다. 밑변을 $\\overline{MC}$ 로 보면 높이가 $\\overline{BK}$ 이다.","확인":null,"스킬":"S8"},{"제목":"$\\tan x$","힌트":"직각삼각형 $BMK$ 에서 $\\overline{MK}$ 를 구해 $\\tan x$ 를 읽으면?","식":["$\\overline{MK}=\\sqrt{(\\sqrt{3})^2-\\frac{8}{3}}=\\frac{\\sqrt{3}}{3}$","$\\tan x=\\frac{\\overline{BK}}{\\overline{MK}}=\\frac{\\frac{2\\sqrt{6}}{3}}{\\frac{\\sqrt{3}}{3}}=2\\sqrt{2}$"],"설명":"$x=\\angle BMK$ 이다. 선지 ③ 이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-920fc05c78e8":{"길":"$D$ 에서 직선 $AC$ 에 수선을 내려 $\\tan x$ 를 직각삼각형으로 읽는다","단계":[{"제목":"$\\overline{AB}$ 와 $\\overline{AC}$","힌트":"$\\overline{BC}=3$, $\\overline{CD}=2$ 로 놓으면 $\\overline{AB}$, $\\overline{AC}$ 는?","식":["$\\overline{AB}=\\frac{3}{\\tan 60^\\circ}=\\sqrt{3}$","$\\overline{AC}=\\sqrt{(\\sqrt{3})^2+3^2}=2\\sqrt{3}$"],"설명":"$\\overline{BC}:\\overline{CD}=3:2$ 이므로 비례상수를 $1$ 로 잡아도 $\\tan x$ 의 값은 변하지 않는다.","확인":null,"스킬":"S6"},{"제목":"수선과 같은 각","힌트":"$D$ 에서 직선 $AC$ 에 수선을 내리면 $C$ 에서 생기는 각은 어느 각과 같을까?","식":["$\\angle ACB=90^\\circ-60^\\circ=30^\\circ$","$\\angle DCH=\\angle ACB=30^\\circ$"],"설명":"$D$ 에서 직선 $AC$ 에 내린 수선의 발을 $H$ 라 하면 $H$ 는 $\\overline{AC}$ 의 연장선 위에 있고, $\\angle DCH$ 와 $\\angle ACB$ 는 맞꼭지각이다.","확인":null,"스킬":"S10","고비":true},{"제목":"$\\overline{DH}$ 와 $\\overline{CH}$","힌트":"직각삼각형 $DCH$ 에서 빗변이 $2$ 일 때 두 변은?","식":["$\\overline{DH}=2\\sin 30^\\circ=1$","$\\overline{CH}=2\\cos 30^\\circ=\\sqrt{3}$"],"설명":"$\\angle DCH=30^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"$\\tan x$","힌트":"직각삼각형 $AHD$ 에서 $\\angle DAH=x$ 이다. $\\overline{AH}$ 는 얼마일까?","식":["$\\overline{AH}=\\overline{AC}+\\overline{CH}=3\\sqrt{3}$","$\\tan x=\\frac{\\overline{DH}}{\\overline{AH}}=\\frac{1}{3\\sqrt{3}}=\\frac{\\sqrt{3}}{9}$"],"설명":"$H$ 가 직선 $AC$ 위에 있으므로 $\\angle DAH=\\angle DAC=x$ 이다. 선지 ① 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-a6cda9db3b06":{"길":"$\\angle DBP=45^\\circ$, $\\angle D=60^\\circ$ 를 찾아 $P$ 에서 $\\overline{BD}$ 에 수선을 긋고 높이를 구한다","단계":[{"제목":"$\\triangle PDB$ 의 두 각","힌트":"두 정삼각형의 한 각이 $60^\\circ$ 이고 $\\angle EBC=45^\\circ$ 이면 $\\angle DBP$ 는 몇 도일까?","식":["$\\angle ABE=60^\\circ-45^\\circ=15^\\circ$","$\\angle DBP=60^\\circ-15^\\circ=45^\\circ$","$\\angle D=60^\\circ$"],"설명":"두 정삼각형을 $ABC$, $DBE$ 라 하면 $\\angle ABC=\\angle DBE=60^\\circ$ 이고 $\\overline{BD}=4$ 이다. $\\angle DBP$ 는 $\\angle DBE$ 에서 $\\angle ABE$ 를 뺀 각이다.","확인":null,"스킬":"S10","고비":true},{"제목":"높이로 두 조각 나타내기","힌트":"$P$ 에서 $\\overline{BD}$ 에 수선을 내려 높이를 $h$ 로 놓으면 $\\overline{BH}$, $\\overline{DH}$ 는?","식":["$\\overline{BH}=\\frac{h}{\\tan 45^\\circ}=h$","$\\overline{DH}=\\frac{h}{\\tan 60^\\circ}=\\frac{h}{\\sqrt{3}}$"],"설명":"$P$ 에서 $\\overline{BD}$ 에 내린 수선의 발을 $H$ 라 하고 $\\overline{PH}=h$ 로 놓는다. 두 직각삼각형 $PBH$, $PDH$ 의 각은 $45^\\circ$, $60^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"$h$ 의 값","힌트":"$\\overline{BH}+\\overline{DH}=\\overline{BD}$ 에서 $h$ 는?","식":["$h+\\frac{h}{\\sqrt{3}}=4$","$h=\\frac{4\\sqrt{3}}{\\sqrt{3}+1}=6-2\\sqrt{3}$"],"설명":"분모를 유리화하면 $\\frac{4\\sqrt{3}(\\sqrt{3}-1)}{2}=2\\sqrt{3}(\\sqrt{3}-1)$ 이다.","확인":null,"스킬":"S6"},{"제목":"넓이","힌트":"밑변을 $\\overline{BD}$ 로 하면 $\\triangle PDB$ 의 넓이는?","식":["$\\frac{1}{2}\\times4\\times(6-2\\sqrt{3})=12-4\\sqrt{3}$"],"설명":"선지 ② 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-afb1a188d4d4":{"길":"$\\angle ADE=15^\\circ$ 를 찾고 $\\overline{AD}$ 와 $\\overline{DE}$ 를 구해 코사인으로 잇는다","단계":[{"제목":"삼각형 $DEF$ 의 변","힌트":"직각삼각형 $DEF$ 에서 $\\overline{DF}=\\sqrt{6}$, $\\angle D=30^\\circ$ 이면 $\\overline{EF}$, $\\overline{DE}$ 는?","식":["$\\overline{EF}=\\sqrt{6}\\tan 30^\\circ=\\sqrt{2}$","$\\overline{DE}=\\frac{\\sqrt{6}}{\\cos 30^\\circ}=2\\sqrt{2}$"],"설명":"$\\angle DFE=90^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"$15^\\circ$ 인 각 찾기","힌트":"$A$, $E$, $B$ 가 한 직선 위에 있음을 이용해 $\\angle AED$ 를 구하면?","식":["$\\angle FED=90^\\circ-30^\\circ=60^\\circ$","$\\angle AED=180^\\circ-45^\\circ-60^\\circ=75^\\circ$","$\\angle ADE=90^\\circ-75^\\circ=15^\\circ$"],"설명":"직사각형의 $\\angle A=90^\\circ$ 이므로 직각삼각형 $ADE$ 에서 $\\angle ADE$ 는 $\\angle AED$ 의 여각이다. 그러면 $\\cos 15^\\circ=\\frac{\\overline{AD}}{\\overline{DE}}$ 이다.","확인":null,"스킬":"S10","고비":true},{"제목":"$\\overline{AD}$ 의 길이","힌트":"$\\overline{AD}=\\overline{BC}$ 이고 $\\overline{BC}=\\overline{BF}+\\overline{FC}$ 이다. 각 조각은?","식":["$\\overline{BF}=\\sqrt{2}\\sin 45^\\circ=1$","$\\angle DFC=180^\\circ-90^\\circ-45^\\circ=45^\\circ$","$\\overline{FC}=\\sqrt{6}\\cos 45^\\circ=\\sqrt{3}$","$\\overline{AD}=1+\\sqrt{3}$"],"설명":"직각삼각형 $BEF$ 에서 $\\angle BEF=45^\\circ$ 이므로 $\\angle BFE=45^\\circ$ 이고, 직선 $BC$ 위에서 $\\angle DFC=180^\\circ-\\angle BFE-\\angle DFE$ 이다.","확인":null,"스킬":"S6"},{"제목":"$\\cos 15^\\circ$","힌트":"$\\overline{AD}$ 와 $\\overline{DE}$ 의 비는?","식":["$\\cos 15^\\circ=\\frac{1+\\sqrt{3}}{2\\sqrt{2}}=\\frac{\\sqrt{2}+\\sqrt{6}}{4}$"],"설명":"분모를 유리화한다. 선지 ① 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-b394329407cd":{"길":"각 직각삼각형에서 코사인으로 다음 빗변을 차례로 구해 $\\triangle OEF$ 의 두 변을 잡는다","단계":[{"제목":"$\\overline{OB}$ 와 $\\overline{OC}$","힌트":"직각삼각형 $OAB$ 에서 $\\overline{OB}$ 는? 그 값이 다음 삼각형의 빗변이 된다.","식":["$\\overline{OB}=\\frac{1}{\\sin 30^\\circ}=2$","$\\overline{OC}=2\\cos 45^\\circ=\\sqrt{2}$"],"설명":"$\\overline{OB}$ 는 직각삼각형 $OBC$ 의 빗변이다.","확인":null,"스킬":"S6","고비":true},{"제목":"$\\overline{OD}$ 와 $\\overline{OE}$","힌트":"같은 방법으로 빗변을 이어 가면?","식":["$\\overline{OD}=\\sqrt{2}\\cos 30^\\circ=\\frac{\\sqrt{6}}{2}$","$\\overline{OE}=\\frac{\\sqrt{6}}{2}\\cos 45^\\circ=\\frac{\\sqrt{3}}{2}$"],"설명":"$\\overline{OC}$ 는 직각삼각형 $OCD$ 의 빗변, $\\overline{OD}$ 는 직각삼각형 $ODE$ 의 빗변이다.","확인":null,"스킬":"S6"},{"제목":"삼각형 $OEF$ 의 두 변","힌트":"직각삼각형 $OEF$ 에서 빗변이 $\\overline{OE}$ 일 때 $\\overline{EF}$, $\\overline{OF}$ 는?","식":["$\\overline{EF}=\\frac{\\sqrt{3}}{2}\\sin 30^\\circ=\\frac{\\sqrt{3}}{4}$","$\\overline{OF}=\\frac{\\sqrt{3}}{2}\\cos 30^\\circ=\\frac{3}{4}$"],"설명":"$\\angle EOF=30^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"넓이","힌트":"두 변의 곱의 절반은?","식":["$\\frac{1}{2}\\times\\frac{3}{4}\\times\\frac{\\sqrt{3}}{4}=\\frac{3\\sqrt{3}}{32}$"],"설명":"선지 ③ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-ca20b333896a":{"길":"지름의 원주각과 수선으로 닮음을 만들어 $\\overline{CD}$ 를 구하고 $\\cos x$ 를 읽는다","단계":[{"제목":"$\\overline{CD}$ 의 길이","힌트":"$\\overline{BD}=k$ 라 하면 $\\overline{AD}=4k$ 이다. 닮은 두 삼각형에서 $\\overline{CD}$ 는?","식":["$\\overline{AD}:\\overline{CD}=\\overline{CD}:\\overline{BD}$","$\\overline{CD}^2=4k\\times k=4k^2$","$\\overline{CD}=2k$"],"설명":"$\\overline{AB}$ 가 지름이므로 $\\angle ACB=90^\\circ$ 이다. $\\angle A+\\angle ACD=90^\\circ$ 이고 $\\angle BCD+\\angle ACD=90^\\circ$ 이므로 $\\angle A=\\angle BCD$ 이다. 그래서 $\\triangle ACD$ 와 $\\triangle CBD$ 는 두 각이 같아 닮음이다.","확인":null,"스킬":"S3","고비":true},{"제목":"$\\overline{BC}$ 의 길이","힌트":"직각삼각형 $CBD$ 에서 $\\overline{BC}$ 는?","식":["$\\overline{BC}=\\sqrt{(2k)^2+k^2}=\\sqrt{5}\\,k$"],"설명":"$\\angle CDB=90^\\circ$ 이다.","확인":null,"스킬":"S3"},{"제목":"$\\cos x$","힌트":"$x=\\angle BCD$ 에서 이웃한 변과 빗변의 비는?","식":["$\\cos x=\\frac{\\overline{CD}}{\\overline{BC}}=\\frac{2k}{\\sqrt{5}\\,k}=\\frac{2\\sqrt{5}}{5}$"],"설명":"선지 ④ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-d865f1e7a4b5":{"길":"끼인각 $B$ 가 그대로이므로 두 삼각형의 넓이를 사인으로 쓰고 비를 잡는다","단계":[{"제목":"두 넓이식","힌트":"$\\angle B$ 는 두 삼각형에 공통이다. 두 변과 끼인각으로 각 넓이를 나타내면?","식":["$S=\\frac{1}{2}ac\\sin B$","$S'=\\frac{1}{2}\\times1.3c\\times0.8a\\times\\sin B$"],"설명":"$\\overline{AB}=c$, $\\overline{BC}=a$ 라 하면 $\\overline{A'B}=1.3c$, $\\overline{BC'}=0.8a$ 이다.","확인":null,"스킬":"S6","고비":true},{"제목":"넓이의 비","힌트":"두 식을 나누면 어떤 값만 남을까?","식":["$\\frac{S'}{S}=1.3\\times0.8=1.04$"],"설명":"$\\frac{1}{2}ac\\sin B$ 가 약분된다. 선지 ③ 이다.","확인":"1.04","스킬":"S6"}],"fb":"fig/ns/"},"ns-dbac863cd1ba":{"길":"세 변을 구하고 정사각형에서 세 직각삼각형을 빼 넓이로 $\\sin x$ 를 찾는다","단계":[{"제목":"두 변의 길이","힌트":"$M$ 이 $A$ 쪽에 있을 때 $\\overline{MD}$, $\\overline{DQ}$ 는 각각 어느 직각삼각형의 빗변일까?","식":["$\\overline{MD}=\\sqrt{6^2+2^2}=2\\sqrt{10}$","$\\overline{DQ}=\\sqrt{6^2+3^2}=3\\sqrt{5}$"],"설명":"$M$, $N$ 이 $\\overline{AB}$ 를 삼등분하므로 $\\overline{AM}=2$, $\\overline{MB}=4$ 이고, $Q$ 가 $\\overline{BC}$ 의 중점이므로 $\\overline{BQ}=\\overline{QC}=3$ 이다. 직각삼각형 $AMD$, $DCQ$ 에서 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"},{"제목":"$\\triangle MDQ$ 의 넓이","힌트":"정사각형에서 $\\triangle MDQ$ 밖의 세 직각삼각형을 빼면?","식":["$\\triangle AMD=\\frac{1}{2}\\times2\\times6=6$","$\\triangle MBQ=\\frac{1}{2}\\times4\\times3=6$","$\\triangle DQC=\\frac{1}{2}\\times3\\times6=9$","$\\triangle MDQ=36-6-6-9=15$"],"설명":"정사각형의 넓이는 $36$ 이다.","확인":"15","스킬":"S2","고비":true},{"제목":"$\\sin x^\\circ$","힌트":"$\\triangle MDQ$ 의 넓이를 두 변과 끼인각 $x$ 로 쓰면?","식":["$\\frac{1}{2}\\times2\\sqrt{10}\\times3\\sqrt{5}\\times\\sin x^\\circ=15$","$15\\sqrt{2}\\sin x^\\circ=15$","$\\sin x^\\circ=\\frac{\\sqrt{2}}{2}$"],"설명":"$2\\sqrt{10}\\times3\\sqrt{5}=6\\sqrt{50}=30\\sqrt{2}$ 이다.","확인":null,"스킬":"S6"},{"제목":"$x$ 의 값","힌트":"$\\sin x^\\circ=\\frac{\\sqrt{2}}{2}$ 인 예각은?","식":["$x=45$"],"설명":"$x$ 는 직각 $\\angle ADC$ 의 일부이므로 $0<x<90$ 이고, 그 범위에서 $\\sin x^\\circ=\\frac{\\sqrt{2}}{2}$ 인 각은 $45^\\circ$ 이다. 선지 ④ 이다.","확인":"45","스킬":"S6"}],"fb":"fig/ns/"},"ns-e0ecfd1d1244":{"길":"$\\overline{BC}$, $\\overline{AC}$, $\\overline{DE}$, $\\overline{CE}$ 를 삼각비로 나타내 사다리꼴의 넓이를 쓴다","단계":[{"제목":"$\\overline{BC}$ 와 $\\overline{AC}$","힌트":"직각삼각형 $ABC$ 에서 $\\overline{AB}=1$ 이면 $\\overline{BC}$, $\\overline{AC}$ 는?","식":["$\\overline{BC}=\\sin x^\\circ$","$\\overline{AC}=\\cos x^\\circ$"],"설명":"$\\overline{AB}$ 는 사분원의 반지름이므로 $1$ 이다. $\\overline{AE}$ 도 반지름이므로 $1$ 이다.","확인":null,"스킬":"S6"},{"제목":"$\\overline{DE}$ 와 $\\overline{CE}$","힌트":"직각삼각형 $ADE$ 에서 $\\overline{AE}=1$ 이면 $\\overline{DE}$ 는? $\\overline{CE}$ 는 $\\overline{AE}$ 와 $\\overline{AC}$ 의 차이다.","식":["$\\overline{DE}=\\overline{AE}\\times\\tan x^\\circ=\\tan x^\\circ$","$\\overline{CE}=1-\\cos x^\\circ$"],"설명":"$\\angle DAE=\\angle BAC=x^\\circ$ 이다.","확인":null,"스킬":"S6"},{"제목":"사다리꼴의 넓이","힌트":"$\\overline{BC}$ 와 $\\overline{DE}$ 는 둘 다 $\\overline{AE}$ 에 수직이다. 색칠한 부분은 어떤 도형일까?","식":["$\\frac{1}{2}(\\overline{BC}+\\overline{DE})\\times\\overline{CE}$","$=\\frac{1}{2}(\\sin x^\\circ+\\tan x^\\circ)(1-\\cos x^\\circ)$"],"설명":"$\\overline{BC}\\parallel\\overline{DE}$ 이므로 색칠한 부분은 윗변 $\\overline{BC}$, 아랫변 $\\overline{DE}$, 높이 $\\overline{CE}$ 인 사다리꼴이다. 선지 ③ 이다.","확인":null,"스킬":"S12","고비":true}],"fb":"fig/ns/"},"ns-ebeafc3cd9e6":{"길":"$\\angle DAE$ 가 $\\angle C$ 와 같음을 찾아 직각삼각형 $ADC$ 의 $\\tan C$ 로 바꾼다","단계":[{"제목":"$\\overline{AD}$ 의 길이","힌트":"직각삼각형 $ABC$ 에서 $\\overline{AD}\\perp\\overline{BC}$ 이면 $\\overline{AD}^2$ 은 어떤 두 선분의 곱일까?","식":["$\\overline{AD}^2=\\overline{BD}\\times\\overline{CD}=5\\times4=20$","$\\overline{AD}=2\\sqrt{5}$"],"설명":"$\\triangle DBA\\sim\\triangle DAC$ 이므로 $\\overline{BD}:\\overline{AD}=\\overline{AD}:\\overline{CD}$ 이다.","확인":null,"스킬":"S3"},{"제목":"$x$ 와 같은 각","힌트":"$E$ 는 $\\overline{AB}$ 위의 점이다. $\\angle B$ 를 기준으로 $\\angle BAD$ 와 같은 각을 찾으면?","식":["$\\angle BAD=90^\\circ-\\angle B=\\angle C$","$\\angle DAE=\\angle BAD=\\angle C$"],"설명":"직각삼각형 $ABD$ 에서 $\\angle B+\\angle BAD=90^\\circ$ 이고, 직각삼각형 $ABC$ 에서 $\\angle B+\\angle C=90^\\circ$ 이다.","확인":null,"스킬":"S10","고비":true},{"제목":"$\\tan C$","힌트":"직각삼각형 $ADC$ 에서 $\\angle C$ 의 대변과 밑변의 비는?","식":["$\\tan x=\\tan C=\\frac{\\overline{AD}}{\\overline{CD}}=\\frac{2\\sqrt{5}}{4}=\\frac{\\sqrt{5}}{2}$"],"설명":"$\\angle ADC=90^\\circ$ 이다. 선지 ③ 이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-0deb7fedaf38":{"길":"같은 호의 원주각으로 $\\triangle ACP\\sim\\triangle ABC$ 를 찾아 $\\overline{AB}$ 를 구한 뒤 현의 곱을 쓴다","단계":[{"제목":"닮은 삼각형","힌트":"$\\overset{\\frown}{AC}=\\overset{\\frown}{AD}$ 에서 $\\angle ACD$ 와 같은 각은 무엇일까? 그 각과 같은 원주각은?","식":["$\\angle ACD=\\angle ADC=\\angle ABC$","$\\triangle ACP\\sim\\triangle ABC$"],"설명":"길이가 같은 호에 대한 원주각은 같으므로 $\\angle ACD=\\angle ADC$ 이다. $\\angle ADC$ 와 $\\angle ABC$ 는 호 $AC$ 에 대한 원주각이라 같다. $\\triangle ACP$ 와 $\\triangle ABC$ 는 $\\angle A$ 가 공통이고 $\\angle ACP=\\angle ABC$ 이므로 AA 닮음이다.","확인":null,"스킬":"S5","고비":true},{"제목":"$\\overline{AB}$ 와 $\\overline{PB}$","힌트":"닮음비로 $\\overline{AB}$ 를 구하면?","식":["$\\overline{AC}:\\overline{AB}=\\overline{AP}:\\overline{AC}$","$8^2=7\\times\\overline{AB}$","$\\overline{AB}=\\frac{64}{7}$","$\\overline{PB}=\\frac{64}{7}-7=\\frac{15}{7}$"],"설명":"$\\overline{PB}=\\overline{AB}-\\overline{AP}$ 이다.","확인":null,"스킬":"S1"},{"제목":"현의 곱","힌트":"한 원에서 두 현이 점 $P$ 에서 만날 때 선분 길이의 곱 사이에는 어떤 관계가 있을까?","식":["$\\overline{PC}\\times\\overline{PD}=\\overline{PA}\\times\\overline{PB}=7\\times\\frac{15}{7}=15$"],"설명":"원의 두 현 $AB$, $CD$ 가 점 $P$ 에서 만나면 $\\overline{PA}\\times\\overline{PB}=\\overline{PC}\\times\\overline{PD}$ 이다. 선지 ④ 이다.","확인":"15","스킬":"S5"}],"fb":"fig/ns/"},"ns-15bb994e0a15":{"길":"두 접선의 길이가 같음으로 원점에서 접점까지의 거리를 구하고, 30°·60°·90° 삼각형의 변의 비로 좌표를 읽는다","단계":[{"제목":"접선 길이와 이등분선","힌트":"점 $O$ 에서 원 $A$ 에 그은 두 접선 $OB$, $OC$ 의 길이는 어떤 관계인가?","식":["$\\overline{OB}=\\overline{OC}$","$\\angle AOB=\\angle AOC$"],"설명":"원 밖의 한 점에서 원에 그은 두 접선의 길이는 같으므로 $\\overline{OB}=\\overline{OC}$ 이다. $\\triangle AOB$ 와 $\\triangle AOC$ 는 $\\angle B=\\angle C=90^{\\circ}$, 빗변 $OA$ 가 공통, $\\overline{AB}=\\overline{AC}$ (반지름) 이므로 RHS 합동이다. 따라서 $\\overline{OA}$ 는 $\\angle BOC=60^{\\circ}$ 를 이등분하여 $\\angle AOB=30^{\\circ}$ 이다.","확인":null,"스킬":"S5","고비":true},{"제목":"$\\overline{OB}$ 의 길이","힌트":"$\\triangle AOB$ 의 세 변의 길이의 비는 어떻게 되는가?","식":["$\\overline{AB}:\\overline{OB}=1:\\sqrt{3}$","$\\overline{OB}=4\\sqrt{3}$"],"설명":"$\\triangle AOB$ 는 $\\angle B=90^{\\circ}$, $\\angle AOB=30^{\\circ}$ 이므로 세 변의 길이의 비가 $1:\\sqrt{3}:2$ 이다. $\\overline{AB}=4$ 이므로 $\\overline{OB}=4\\sqrt{3}$ 이고, $\\overline{OC}$ 도 같은 길이이다.","확인":null,"스킬":"S10"},{"제목":"점 $C$ 의 좌표","힌트":"$C$ 에서 $x$축에 수선을 내리면 어떤 직각삼각형이 생기는가?","식":["$\\overline{OH}=2\\sqrt{3}$","$\\overline{CH}=6$"],"설명":"$C$ 에서 $x$축에 내린 수선의 발을 $H$ 라 하자. $\\triangle OCH$ 는 $\\angle COH=60^{\\circ}$, $\\angle CHO=90^{\\circ}$ 이므로 세 변의 길이의 비가 $1:\\sqrt{3}:2$ 이다. $\\overline{OC}=4\\sqrt{3}$ 에서 $\\overline{OH}=2\\sqrt{3}$, $\\overline{CH}=6$ 이므로 $C$ 의 좌표는 $(2\\sqrt{3},\\,6)$ 이다.","확인":null,"스킬":"S10"}],"fb":"fig/ns/"},"ns-2092e720d670":{"길":"삼각형의 외각으로 원주각 하나를 더 구한 뒤, 호의 길이가 원주각에 정비례함을 쓴다","단계":[{"제목":"$\\angle CAB$ 의 크기","힌트":"$\\angle BPC$ 는 $\\triangle APC$ 에서 어떤 각인가?","식":["$\\angle BPC=\\angle PAC+\\angle ACP$"],"설명":"점 $P$ 가 선분 $AB$ 위에 있으므로 $\\angle BPC$ 는 $\\triangle APC$ 의 꼭짓점 $P$ 에서의 외각이다. 삼각형의 외각은 이웃하지 않는 두 내각의 합과 같으므로 $\\angle CAB=\\angle BPC-\\angle ACP$ 이다.","확인":"50","스킬":"S10","고비":true},{"제목":"호의 길이의 비","힌트":"한 원에서 원주각과 호의 길이는 어떤 관계인가?","식":["$\\overset{\\frown}{BC}:\\overset{\\frown}{AD}=\\angle CAB:\\angle ACD$","$10:\\overset{\\frown}{AD}=50:20$"],"설명":"한 원에서 호의 길이는 그 호에 대한 원주각의 크기에 정비례한다. $\\overset{\\frown}{BC}$ 에 대한 원주각은 $\\angle CAB$, $\\overset{\\frown}{AD}$ 에 대한 원주각은 $\\angle ACD$ 이다.","확인":null,"스킬":"S5"},{"제목":"$\\overset{\\frown}{AD}$ 의 길이","힌트":"비례식을 풀면 $\\overset{\\frown}{AD}$ 는 얼마인가?","식":["$50\\times\\overset{\\frown}{AD}=10\\times20$"],"설명":"비례식의 내항의 곱과 외항의 곱이 같으므로 $50\\times\\overset{\\frown}{AD}=200$ 이다. 따라서 $\\overset{\\frown}{AD}=4\\,\\mathrm{cm}$ 이다.","확인":"4","스킬":"S5"}],"fb":"fig/ns/"},"ns-2d0c37b6e472":{"길":"길이가 같은 현은 중심에서의 거리가 같음을 써서 밑변과 높이를 구한다","단계":[{"제목":"$\\overline{CD}$ 와 중심 사이의 거리","힌트":"길이가 같은 두 현은 중심에서 어떤 거리에 있는가?","식":["$\\overline{AB}=\\overline{CD}$","$\\overline{OM}=\\overline{ON}$"],"설명":"$O$ 에서 $\\overline{CD}$ 에 내린 수선의 발을 $N$ 이라 하자. 한 원에서 길이가 같은 두 현은 중심으로부터 같은 거리에 있으므로 $\\overline{ON}=\\overline{OM}$ 이다.","확인":"9","스킬":"S5","고비":true},{"제목":"$\\overline{CD}$ 의 길이","힌트":"$\\triangle OND$ 에서 $\\overline{ND}$ 는 얼마인가?","식":["$\\overline{ND}=\\sqrt{15^{2}-9^{2}}$","$\\overline{CD}=2\\overline{ND}$"],"설명":"$\\triangle OND$ 는 $\\angle N=90^{\\circ}$ 이므로 피타고라스 정리에서 $\\overline{ND}=12$ 이다. 원의 중심에서 현에 내린 수선은 현을 이등분하므로 $\\overline{CD}=2\\overline{ND}=24$ 이다.","확인":"24","스킬":"S3"},{"제목":"$\\triangle OCD$ 의 넓이","힌트":"밑변을 $\\overline{CD}$ 로 보면 높이는 얼마인가?","식":["$\\frac{1}{2}\\times24\\times9$"],"설명":"밑변이 $\\overline{CD}=24$, 높이가 $\\overline{ON}=9$ 이므로 넓이는 $\\frac{1}{2}\\times24\\times9=108\\,\\mathrm{cm}^{2}$ 이다.","확인":"108","스킬":"S5"}],"fb":"fig/ns/"},"ns-2dc6c4349e4d":{"길":"반지름을 문자로 놓고 직각삼각형에서 피타고라스 정리로 식을 세운다","단계":[{"제목":"$\\overline{OM}$ 을 문자로 나타내기","힌트":"반지름을 $r$ 로 놓으면 $\\overline{OM}$ 은 어떻게 나타나는가?","식":["$\\overline{OB}=\\overline{OC}=r$","$\\overline{OM}=r-1$"],"설명":"원 $O$ 의 반지름을 $r$ 라 하면 $\\overline{OB}=\\overline{OC}=r$ 이다. 세 점 $O$, $M$, $C$ 가 한 직선 위에 있고 $\\overline{CM}=1$ 이므로 $\\overline{OM}=r-1$ 이다.","확인":null,"스킬":"S5","고비":true},{"제목":"피타고라스 정리로 식 세우기","힌트":"$\\triangle OMB$ 에서 세 변 사이에 어떤 식이 성립하는가?","식":["$r^{2}=(r-1)^{2}+5^{2}$","$2r=26$"],"설명":"원의 중심에서 현에 내린 수선은 현을 이등분하므로 $\\overline{MB}=\\overline{AM}=5$ 이다. $\\triangle OMB$ 는 $\\angle M=90^{\\circ}$ 이므로 $r^{2}=(r-1)^{2}+25$ 이고, 정리하면 $2r=26$ 에서 $r=13$ 이다.","확인":"13","스킬":"S3"},{"제목":"원의 넓이","힌트":"반지름을 알면 원의 넓이는 얼마인가?","식":["$\\pi\\times13^{2}$"],"설명":"원의 넓이는 $\\pi r^{2}=169\\pi\\,\\mathrm{cm}^{2}$ 이다.","확인":"169","스킬":"S5"}],"fb":"fig/ns/"},"ns-30f666b77e38":{"길":"공통접선의 교점에서 두 접선의 길이가 같음을 이용해 이등변삼각형 둘을 만들고 각의 합을 세운다","단계":[{"제목":"접선의 길이가 같은 변","힌트":"점 $D$ 에서 각 원에 그은 두 접선의 길이는 어떤 관계인가?","식":["$\\overline{DA}=\\overline{DC}$","$\\overline{DB}=\\overline{DC}$"],"설명":"점 $D$ 는 $\\overline{AB}$ 위의 점이고 $\\overline{CD}$ 는 두 원이 만나는 점 $C$ 에서의 공통접선 위에 있다. 점 $D$ 에서 원 $O$ 에 그은 두 접선 $DA$, $DC$ 의 길이가 같고, 원 $O'$ 에 그은 두 접선 $DB$, $DC$ 의 길이도 같다.","확인":null,"스킬":"S5","고비":true},{"제목":"이등변삼각형의 밑각","힌트":"$\\triangle DAC$ 와 $\\triangle DBC$ 는 각각 어떤 삼각형인가?","식":["$\\angle DCA=\\angle DAC=40^{\\circ}$","$\\angle DCB=\\angle DBC=x$"],"설명":"$\\overline{DA}=\\overline{DC}$ 인 이등변삼각형 $DAC$ 의 밑각은 같으므로 $\\angle DCA=40^{\\circ}$ 이다. $\\angle CBD=x$ 라 하면 $\\overline{DB}=\\overline{DC}$ 인 이등변삼각형 $DBC$ 에서 $\\angle DCB=x$ 이다.","확인":null,"스킬":"S10"},{"제목":"삼각형의 내각의 합","힌트":"$\\triangle ABC$ 의 세 내각의 합으로 어떤 식을 세울 수 있는가?","식":["$40^{\\circ}+(40^{\\circ}+x)+x=180^{\\circ}$","$2x=100^{\\circ}$"],"설명":"$\\angle ACB=\\angle DCA+\\angle DCB=40^{\\circ}+x$ 이다. $\\triangle ABC$ 의 내각의 합이 $180^{\\circ}$ 이므로 $2x=100^{\\circ}$ 에서 $x=50^{\\circ}$ 이다.","확인":"50","스킬":"S10"}],"fb":"fig/ns/"},"ns-31e26848f6b1":{"길":"엇각으로 $\\angle\\mathrm{ABC}$ 를 알아내고 두 이등변삼각형의 밑각의 합으로 $x$ 에 대한 방정식을 세운다","단계":[{"제목":"엇각으로 $\\angle\\mathrm{ABC}$ 구하기","힌트":"$\\overline{\\mathrm{AB}}\\parallel\\overline{\\mathrm{CD}}$ 일 때 $\\angle\\mathrm{BCD}$ 와 크기가 같은 각은 무엇인가?","식":["$\\angle\\mathrm{ABC}=\\angle\\mathrm{BCD}=101^{\\circ}$"],"설명":"직선 $\\mathrm{BC}$ 가 평행한 두 직선 $\\mathrm{AB}$, $\\mathrm{CD}$ 와 만날 때 엇각의 크기는 같다.","확인":null,"스킬":"S10","고비":true},{"제목":"$\\angle\\mathrm{OBC}$ 를 $x$ 로 나타내기","힌트":"$\\overline{\\mathrm{OB}}=\\overline{\\mathrm{OC}}$ 인 $\\triangle\\mathrm{OBC}$ 에서 크기가 같은 두 각은 무엇인가?","식":["$\\angle\\mathrm{OBC}=\\angle\\mathrm{OCB}=(2x-1)^{\\circ}$"],"설명":"$\\overline{\\mathrm{OB}}$, $\\overline{\\mathrm{OC}}$ 는 원의 반지름이므로 $\\triangle\\mathrm{OBC}$ 는 이등변삼각형이다.","확인":null,"스킬":"S10"},{"제목":"$\\angle\\mathrm{OBA}$ 를 $x$ 로 나타내기","힌트":"$\\triangle\\mathrm{OAB}$ 에서 꼭지각이 $(3x-5)^{\\circ}$ 일 때 밑각 $\\angle\\mathrm{OBA}$ 는 얼마인가?","식":["$\\angle\\mathrm{OBA}=\\frac{180^{\\circ}-(3x-5)^{\\circ}}{2}=\\left(\\frac{185-3x}{2}\\right)^{\\circ}$"],"설명":"$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}$ 인 이등변삼각형이므로 밑각의 크기는 $180^{\\circ}$ 에서 꼭지각의 크기를 뺀 값의 절반이다.","확인":null,"스킬":"S10"},{"제목":"$\\angle\\mathrm{ABC}$ 로 방정식 세우기","힌트":"$\\angle\\mathrm{ABC}$ 는 $\\angle\\mathrm{OBA}$ 와 어느 각의 합인가?","식":["$\\angle\\mathrm{ABC}=\\angle\\mathrm{OBA}+\\angle\\mathrm{OBC}$","$\\frac{185-3x}{2}+(2x-1)=101$","$x+183=202$, $x=19$"],"설명":"점 $\\mathrm{O}$ 가 $\\angle\\mathrm{ABC}$ 의 안쪽에 있으므로 두 각의 합이 $\\angle\\mathrm{ABC}$ 이다. 양변에 $2$ 를 곱해 분모를 없앤다.","확인":"19","스킬":"S10"}]},"ns-3259d806af40":{"길":"접선의 길이가 같음으로 빗변 CD 를 구하고, 꼭짓점에서 수선을 내려 AB 를 구한다","단계":[{"제목":"$\\overline{CD}$ 의 길이","힌트":"점 $D$, $C$ 에서 반원에 그은 접선의 길이는 각각 어떤 관계인가?","식":["$\\overline{DE}=\\overline{DA}=8$","$\\overline{CE}=\\overline{CB}=4$"],"설명":"점 $E$ 는 $\\overline{CD}$ 와 반원의 접점이다. 한 점에서 원에 그은 두 접선의 길이는 같으므로 $\\overline{DE}=\\overline{DA}$, $\\overline{CE}=\\overline{CB}$ 이다. 따라서 $\\overline{CD}=8+4=12$ 이다.","확인":"12","스킬":"S5","고비":true},{"제목":"보조선과 직각삼각형","힌트":"$C$ 에서 $\\overline{AD}$ 에 수선을 그으면 어떤 직각삼각형이 생기는가?","식":["$\\overline{DH}=8-4$"],"설명":"$C$ 에서 $\\overline{AD}$ 에 내린 수선의 발을 $H$ 라 하자. $\\overline{AD}$, $\\overline{BC}$ 는 모두 지름 $AB$ 에 수직이므로 $\\square ABCH$ 는 직사각형이다. $\\overline{AH}=\\overline{BC}=4$ 이므로 $\\overline{DH}=4$ 이고, $\\triangle CHD$ 는 빗변이 $\\overline{CD}=12$ 인 직각삼각형이다.","확인":"4","스킬":"S2"},{"제목":"$\\overline{AB}$ 의 길이","힌트":"$\\triangle CHD$ 에서 $\\overline{CH}$ 는 얼마인가?","식":["$\\overline{CH}=\\sqrt{12^{2}-4^{2}}$","$\\overline{AB}=\\overline{CH}=8\\sqrt{2}$"],"설명":"피타고라스 정리에서 $\\overline{CH}=\\sqrt{144-16}=8\\sqrt{2}$ 이다. $\\overline{AB}=\\overline{CH}$ 이므로 $\\overline{AB}=8\\sqrt{2}\\,\\mathrm{cm}$ 이다.","확인":null,"스킬":"S3"},{"제목":"$\\square ABCD$ 의 둘레","힌트":"네 변의 길이를 모두 더하면 얼마인가?","식":["$8+8\\sqrt{2}+4+12$"],"설명":"둘레는 $\\overline{AB}+\\overline{BC}+\\overline{CD}+\\overline{DA}=8\\sqrt{2}+4+12+8=24+8\\sqrt{2}\\,\\mathrm{cm}$ 이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-3fa75cef9d31":{"길":"지름의 원주각으로 직각삼각형을 찾고, E 가 BD 의 중점임을 이용한다","단계":[{"제목":"지름이 만드는 직각","힌트":"$\\overline{AB}$ 가 지름일 때 $\\angle ACB$ 는 몇 도인가?","식":["$\\angle ACB=90^{\\circ}$","$\\angle BCD=90^{\\circ}$"],"설명":"지름에 대한 원주각은 $90^{\\circ}$ 이므로 $\\angle ACB=90^{\\circ}$ 이다. 세 점 $A$, $C$, $D$ 가 한 직선 위에 있으므로 $\\angle BCD=90^{\\circ}$ 이다. 또 $\\overline{BD}$ 가 점 $B$ 에서의 접선이므로 $\\angle ABD=90^{\\circ}$ 이다.","확인":"90","스킬":"S5"},{"제목":"$\\overline{BD}$ 의 길이","힌트":"$\\triangle DBC$ 와 $\\triangle DAB$ 사이에 닮음 관계가 있는가?","식":["$\\triangle DBC\\sim\\triangle DAB$","$\\overline{DB}^{2}=\\overline{DC}\\times\\overline{DA}$"],"설명":"$\\triangle DBC$ 와 $\\triangle DAB$ 는 $\\angle D$ 가 공통이고 $\\angle DCB=\\angle DBA=90^{\\circ}$ 이므로 AA 닮음이다. $\\overline{DB}:\\overline{DC}=\\overline{DA}:\\overline{DB}$ 에서 $\\overline{DB}^{2}=1\\times3$ 이므로 $\\overline{DB}=\\sqrt{3}$ 이다.","확인":null,"스킬":"S1"},{"제목":"점 $E$ 의 위치","힌트":"$\\overline{EB}$, $\\overline{EC}$, $\\overline{ED}$ 의 길이는 어떤 관계인가?","식":["$\\overline{EB}=\\overline{EC}$","$\\angle ECD=\\angle EDC$","$\\overline{EC}=\\overline{ED}$"],"설명":"점 $E$ 에서 원에 그은 두 접선의 길이는 같으므로 $\\overline{EB}=\\overline{EC}$ 이다. $\\angle ECB=\\angle EBC$ 이고 $\\angle ECB+\\angle ECD=90^{\\circ}$, $\\angle EBC+\\angle EDC=90^{\\circ}$ 이므로 $\\angle ECD=\\angle EDC$ 이다. 따라서 $\\overline{EC}=\\overline{ED}$ 이고 $E$ 는 $\\overline{BD}$ 의 중점이다.","확인":null,"스킬":"S2","고비":true},{"제목":"$\\overline{CE}$ 의 길이","힌트":"$E$ 가 $\\overline{BD}$ 의 중점이면 $\\overline{CE}$ 는 $\\overline{BD}$ 의 몇 분의 몇인가?","식":["$\\overline{CE}=\\frac{1}{2}\\overline{BD}$"],"설명":"$\\overline{CE}=\\overline{BE}=\\overline{DE}$ 이므로 $\\overline{CE}=\\frac{1}{2}\\overline{BD}=\\frac{\\sqrt{3}}{2}$ 이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-40fb96bfc1f3":{"길":"두 현이 만나는 점에서 선분의 곱이 같음을 반지름 r 로 세워 풀고 넓이를 구한다","단계":[{"제목":"$\\overline{PA}$, $\\overline{PB}$ 를 문자로","힌트":"반지름을 $r$ 로 놓으면 $\\overline{PA}$, $\\overline{PB}$ 는 어떻게 나타나는가?","식":["$\\overline{PA}=r-4$","$\\overline{PB}=r+4$"],"설명":"원 $O$ 의 반지름을 $r$ 라 하면 $\\overline{OA}=\\overline{OB}=r$ 이다. 그림에서 점 $P$ 는 $O$ 와 $A$ 사이에 있으므로 $\\overline{PA}=r-4$, $\\overline{PB}=r+4$ 이다.","확인":null,"스킬":"S1"},{"제목":"선분의 곱 관계","힌트":"$\\triangle PAC$ 와 $\\triangle PDB$ 사이에 어떤 닮음 관계가 있는가?","식":["$\\triangle PAC\\sim\\triangle PDB$","$\\overline{PA}\\cdot\\overline{PB}=\\overline{PC}\\cdot\\overline{PD}$","$(r-4)(r+4)=8\\times7$"],"설명":"$\\angle PAC=\\angle PDB$ (호 $BC$ 에 대한 원주각), $\\angle APC=\\angle DPB$ (맞꼭지각) 이므로 AA 닮음이다. $\\overline{PA}:\\overline{PD}=\\overline{PC}:\\overline{PB}$ 에서 $\\overline{PA}\\cdot\\overline{PB}=\\overline{PC}\\cdot\\overline{PD}$ 이므로 $(r-4)(r+4)=8\\times7$ 이다.","확인":null,"스킬":"S5","고비":true},{"제목":"$r^{2}$ 의 값","힌트":"식을 전개하면 $r^{2}$ 는 얼마인가?","식":["$r^{2}-16=56$"],"설명":"$(r-4)(r+4)=r^{2}-16$ 이므로 $r^{2}-16=56$ 에서 $r^{2}=72$ 이다.","확인":"72","스킬":"S1"},{"제목":"원의 넓이","힌트":"원의 넓이는 $r^{2}$ 로 바로 구할 수 있는가?","식":["$\\pi r^{2}=72\\pi$"],"설명":"원의 넓이는 $\\pi r^{2}=72\\pi\\,\\mathrm{cm}^{2}$ 이다. $r$ 의 값을 따로 구할 필요가 없다.","확인":"72","스킬":"S1"}],"fb":"fig/ns/"},"ns-42b2a3088cb4":{"길":"호 AB 의 중심각으로 ∠ACB 를 구하고, 둔각 꼭짓점에서 수선을 내려 넓이를 계산한다","단계":[{"제목":"$\\angle ACB$ 의 크기","힌트":"점 $C$ 를 지나지 않는 쪽 호 $AB$ 의 중심각은 몇 도인가?","식":["$\\angle ACB=\\frac{1}{2}(360^{\\circ}-90^{\\circ})$"],"설명":"$\\angle AOB=90^{\\circ}$ 이므로 점 $C$ 가 없는 쪽 호 $AB$ 에 대한 중심각은 $360^{\\circ}-90^{\\circ}=270^{\\circ}$ 이다. 원주각은 중심각의 크기의 $\\frac{1}{2}$ 이므로 $\\angle ACB=135^{\\circ}$ 이다.","확인":"135","스킬":"S5"},{"제목":"보조선으로 직각삼각형 만들기","힌트":"둔각삼각형의 높이를 구하려면 어디에 수선을 내리는가?","식":["$\\angle ACH=180^{\\circ}-135^{\\circ}=45^{\\circ}$","$\\overline{AH}=\\overline{CH}=\\frac{3\\sqrt{2}}{2}$"],"설명":"$A$ 에서 $\\overline{BC}$ 의 연장선에 내린 수선의 발을 $H$ 라 하자. $\\angle ACH=45^{\\circ}$ 이므로 $\\triangle ACH$ 는 직각이등변삼각형이고 $\\overline{AC}=3$ 에서 $\\overline{AH}=\\overline{CH}=\\frac{3\\sqrt{2}}{2}$ 이다.","확인":null,"스킬":"S2","고비":true},{"제목":"$\\triangle ABC$ 의 넓이","힌트":"밑변을 $\\overline{BC}$ 로 보면 높이는 어느 선분인가?","식":["$\\frac{1}{2}\\times7\\times\\frac{3\\sqrt{2}}{2}$"],"설명":"밑변이 $\\overline{BC}=7$, 높이가 $\\overline{AH}=\\frac{3\\sqrt{2}}{2}$ 이므로 넓이는 $\\frac{1}{2}\\times7\\times\\frac{3\\sqrt{2}}{2}=\\frac{21\\sqrt{2}}{4}$ 이다.","확인":null,"스킬":"S2"}],"fb":"fig/ns/"},"ns-4f0c1a5cbb0d":{"길":"한 선분을 직각으로 보는 두 점이 같은 쪽에 있으면 네 점이 한 원 위에 있음을 이용해 사각형을 센다","단계":[{"제목":"직각 두 개로 원 찾기","힌트":"같은 선분을 직각으로 바라보는 두 점이 있으면 네 점은 어떤 관계인가?","식":["$\\angle XPY=\\angle XQY=90^{\\circ}$"],"설명":"선분 $XY$ 에 대하여 같은 쪽의 두 점 $P$, $Q$ 가 $\\angle XPY=\\angle XQY=90^{\\circ}$ 이면 네 점 $X$, $Y$, $P$, $Q$ 는 $XY$ 를 지름으로 하는 한 원 위에 있다. 이 사각형은 원에 내접한다.","확인":null,"스킬":"S15","고비":true},{"제목":"$H$ 를 지나지 않는 사각형","힌트":"세 변 $AB$, $BC$, $CA$ 를 각각 직각으로 보는 두 점은 어느 것인가?","식":["$\\angle AEB=\\angle AFB=90^{\\circ}$","$\\angle BDC=\\angle BFC=90^{\\circ}$","$\\angle ADC=\\angle AEC=90^{\\circ}$"],"설명":"$\\overline{AB}$ 를 직각으로 보는 점은 $E$, $F$ 이므로 $\\square ABEF$ 가 원에 내접한다. $\\overline{BC}$ 를 보는 점은 $D$, $F$ 이므로 $\\square BCFD$, $\\overline{AC}$ 를 보는 점은 $D$, $E$ 이므로 $\\square ACED$ 가 원에 내접한다. 모두 3개이다.","확인":"3","스킬":"S15"},{"제목":"$H$ 를 지나는 사각형","힌트":"선분 $BH$, $CH$, $AH$ 를 각각 직각으로 보는 두 점은 어느 것인가?","식":["$\\angle HDB=\\angle HEB=90^{\\circ}$","$\\angle HEC=\\angle HFC=90^{\\circ}$","$\\angle HDA=\\angle HFA=90^{\\circ}$"],"설명":"$\\overline{BH}$ 를 보는 점은 $D$, $E$ 이므로 $\\square BEHD$, $\\overline{CH}$ 를 보는 점은 $E$, $F$ 이므로 $\\square CFHE$, $\\overline{AH}$ 를 보는 점은 $D$, $F$ 이므로 $\\square ADHF$ 가 원에 내접한다. 모두 3개이다.","확인":"3","스킬":"S15"},{"제목":"내접하는 사각형의 개수","힌트":"두 경우를 합치면 모두 몇 개인가?","식":["$3+3$"],"설명":"$H$ 를 지나지 않는 것 3개와 지나는 것 3개를 더하면 원에 내접하는 사각형은 모두 6개이다.","확인":"6","스킬":"S15"}],"fb":"fig/ns/"},"ns-5036d26320c6":{"길":"접선과 현이 이루는 각, 이등변삼각형, 삼각형의 내각의 합, 내접사각형의 대각으로 네 사람의 말을 따진다","단계":[{"제목":"현희의 말","힌트":"접선과 현이 이루는 각 $\\angle DCP$ 는 어느 원주각과 같은가?","식":["$\\angle DCP=\\angle CAD$"],"설명":"접선과 현이 이루는 각의 크기는 그 각 안에 있는 호에 대한 원주각과 같다. 호 $CD$ 에 대하여 $\\angle DCP=\\angle CAD$ 이므로 현희의 말은 옳다.","확인":null,"스킬":"S5"},{"제목":"$\\angle CAD$ 의 크기","힌트":"$\\angle CAD=x$ 로 놓으면 $\\triangle ACP$ 의 세 각은 어떻게 나타나는가?","식":["$\\angle ACD=\\angle ADC=\\frac{180^{\\circ}-x}{2}$","$x+\\left(\\frac{180^{\\circ}-x}{2}+x\\right)+36^{\\circ}=180^{\\circ}$"],"설명":"$\\overline{AC}=\\overline{AD}$ 이므로 $\\angle ACD=\\angle ADC=\\frac{180^{\\circ}-x}{2}$ 이다. $\\angle ACP=\\angle ACD+\\angle DCP=\\frac{180^{\\circ}-x}{2}+x$ 이고, $\\triangle ACP$ 의 내각의 합에서 $\\frac{3}{2}x=54^{\\circ}$ 이므로 $x=36^{\\circ}$ 이다. $\\angle DCP=36^{\\circ}$ 이므로 영한의 말은 옳다.","확인":"36","스킬":"S10","고비":true},{"제목":"$\\angle ABC$ 의 크기","힌트":"원에 내접하는 사각형 $ABCD$ 에서 마주 보는 두 각의 합은 얼마인가?","식":["$\\angle ADC=\\frac{180^{\\circ}-36^{\\circ}}{2}=72^{\\circ}$","$\\angle ABC+\\angle ADC=180^{\\circ}$"],"설명":"$\\angle ADC=72^{\\circ}$ 이고 내접사각형의 대각의 합은 $180^{\\circ}$ 이므로 영란의 말은 옳고 $\\angle ABC=108^{\\circ}$ 이다. 민지가 말한 $144^{\\circ}$ 는 맞지 않으므로 옳지 않은 말을 한 사람은 민지이다.","확인":"108","스킬":"S5"}],"fb":"fig/ns/"},"ns-5da40dfbd99b":{"길":"같은 크기의 원주각이 같은 호를 만든다는 점에서 출발해 보기마다 각의 관계를 확인한다","단계":[{"제목":"같은 호와 같은 원주각","힌트":"세 원주각의 크기가 같으면 그 호들은 어떤 관계인가?","식":["$\\overset{\\frown}{BC}=\\overset{\\frown}{CD}=\\overset{\\frown}{DE}$","$\\angle BAC=\\angle CAD=\\angle DAE=\\angle CBD=\\angle BDC=\\angle CEB=\\angle DBE$"],"설명":"크기가 같은 원주각에 대한 호의 길이는 같으므로 $\\overset{\\frown}{BC}=\\overset{\\frown}{CD}=\\overset{\\frown}{DE}$ 이다. 이 세 호에 대한 원주각은 어느 점에서 보아도 모두 $\\angle BAC$ 와 크기가 같다. 이 크기를 $\\theta$ 라 하자.","확인":null,"스킬":"S5","고비":true},{"제목":"보기 1, 2 판정","힌트":"$\\angle JBE$ 와 $\\angle JEB$ 는 각각 어느 호에 대한 원주각인가?","식":["$\\angle JBE=\\angle DBE=\\theta$","$\\angle JEB=\\angle CEB=\\theta$","$\\angle EBD=\\angle BDC$"],"설명":"$J$ 는 $\\overline{BD}$ 와 $\\overline{CE}$ 의 교점이다. $\\angle JBE=\\angle JEB=\\theta$ 이므로 $\\triangle JBE$ 는 이등변삼각형이고 1번은 옳다. $\\angle EBD=\\angle BDC=\\theta$ 는 엇각이므로 $\\overline{BE}\\parallel\\overline{CD}$ 이다. 원에 내접하는 사다리꼴이고 $\\overline{BC}=\\overline{DE}$ 이므로 $\\square BCDE$ 는 등변사다리꼴이다. 2번도 옳다.","확인":null,"스킬":"S15"},{"제목":"보기 3 판정","힌트":"$\\square GCDH$ 가 등변사다리꼴이려면 어느 두 각이 같아야 하는가?","식":["$\\angle ACD=\\angle ADC$","$\\overset{\\frown}{AE}=\\overset{\\frown}{AB}$"],"설명":"$G$, $H$ 는 $\\overline{BE}$ 위의 점이므로 $\\overline{GH}\\parallel\\overline{CD}$ 이다. 등변사다리꼴이려면 $\\angle GCD=\\angle HDC$, 즉 $\\angle ACD=\\angle ADC$ 이어야 한다. $\\angle ACD$ 는 호 $AED$, $\\angle ADC$ 는 호 $ABC$ 에 대한 원주각이고 $\\overset{\\frown}{DE}=\\overset{\\frown}{BC}$ 이므로, 두 각이 같으려면 $\\overset{\\frown}{AE}=\\overset{\\frown}{AB}$ 이어야 한다. 이 조건이 주어지지 않았으므로 3번은 옳다고 할 수 없다.","확인":null,"스킬":"S15"},{"제목":"보기 4 판정","힌트":"직선 $BF$ 와 $\\overline{BG}$ 가 이루는 각은 어느 원주각과 같은가?","식":["$\\angle FBG=\\angle DBE=\\theta$","$\\angle BAG=\\theta$"],"설명":"$F$ 는 $\\overline{AC}$ 와 $\\overline{BD}$ 의 교점이므로 직선 $BF$ 는 직선 $BD$ 이다. $\\angle FBG=\\angle DBE=\\theta$ 이고 $\\triangle ABG$ 에서 현 $BG$ 에 대한 원주각 $\\angle BAG=\\theta$ 이다. 접선과 현이 이루는 각이 반대쪽 원주각과 같으므로 직선 $BF$ 는 $\\triangle ABG$ 의 외접원의 접선이다. 4번은 옳다.","확인":null,"스킬":"S5"},{"제목":"보기 5 판정","힌트":"직선 $DE$ 가 접선이면 $\\angle DEC$ 는 어느 각과 같아야 하는가?","식":["$\\angle DEC=\\theta$","$\\angle EAC=2\\theta$"],"설명":"직선 $DE$ 가 $\\triangle ACE$ 의 외접원의 접선이려면 $\\angle DEC=\\angle EAC$ 이어야 한다. 그런데 $\\angle DEC=\\theta$ 이고 $\\angle EAC=\\angle CAD+\\angle DAE=2\\theta$ 이므로 같지 않다. 5번은 옳지 않다. 따라서 옳은 것은 1번, 2번, 4번이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-611486cf2612":{"길":"원주각이 일정한 점의 자취가 두 원의 큰 쪽 호임을 알고 외접원의 반지름으로 길이를 구한다","단계":[{"제목":"점 $P$ 가 그리는 도형","힌트":"선분 $AB$ 를 같은 크기의 각으로 보는 점들은 어떤 도형 위에 있는가?","식":["$\\angle APB=45^{\\circ}$ (일정)"],"설명":"원주각의 크기가 일정하면 그 점들은 같은 원 위에 있다. $\\overline{AB}$ 의 양쪽에 각각 이런 원이 하나씩 생기고, 점 $P$ 는 각 원에서 $\\overline{AB}$ 에 대한 원주각이 $45^{\\circ}$ 인 쪽의 호 위에 있다. 이 호는 중심각이 $90^{\\circ}$ 인 쪽의 반대편인 큰 호이다.","확인":null,"스킬":"S15","고비":true},{"제목":"원의 반지름","힌트":"호 $AB$ 에 대한 중심각은 몇 도이고, 그때 반지름과 $\\overline{AB}$ 의 관계는?","식":["$\\angle AQB=2\\times45^{\\circ}=90^{\\circ}$","$\\overline{AB}=\\sqrt{2}\\,r$","$r=\\frac{5\\sqrt{2}}{2}$"],"설명":"한 원의 중심을 $Q$, 반지름을 $r$ 라 하자. 원주각이 $45^{\\circ}$ 이므로 호 $AB$ 에 대한 중심각은 $\\angle AQB=90^{\\circ}$ 이다. $\\triangle QAB$ 는 직각이등변삼각형이므로 $\\overline{AB}=\\sqrt{2}\\,r$ 이고, $\\overline{AB}=5$ 에서 $r=\\frac{5\\sqrt{2}}{2}$ 이다.","확인":null,"스킬":"S5"},{"제목":"도형의 둘레","힌트":"두 원의 큰 쪽 호는 각각 원 둘레의 몇 분의 몇인가?","식":["$2\\times\\frac{270}{360}\\times2\\pi r=3\\pi r$","$3\\pi\\times\\frac{5\\sqrt{2}}{2}$"],"설명":"두 원은 반지름이 같다. 점 $P$ 가 있는 큰 호의 중심각은 $360^{\\circ}-90^{\\circ}=270^{\\circ}$ 이므로 호의 길이는 원 둘레의 $\\frac{270}{360}=\\frac{3}{4}$ 이다. 도형의 둘레는 큰 호 두 개의 길이의 합이므로 $2\\times\\frac{3}{4}\\times2\\pi r=3\\pi r=\\frac{15\\sqrt{2}}{2}\\pi$ 이다.","확인":null,"스킬":"S15"}],"fb":"fig/ns/"},"ns-6ed7e1bf6b46":{"길":"수선의 발이 만드는 직각에서 숨은 원을 찾고, 닮음과 각의 관계로 다섯 보기를 가려낸다","단계":[{"제목":"보기 1 판정","힌트":"$\\overline{BC}$ 를 직각으로 바라보는 점은 어느 것인가?","식":["$\\angle BFC=\\angle BEC=90^{\\circ}$"],"설명":"$\\overline{CF}\\perp\\overline{AB}$, $\\overline{BE}\\perp\\overline{AC}$ 이므로 $\\angle BFC=\\angle BEC=90^{\\circ}$ 이다. 같은 쪽의 두 점 $F$, $E$ 가 $\\overline{BC}$ 를 직각으로 보므로 네 점 $F$, $B$, $C$, $E$ 는 $\\overline{BC}$ 를 지름으로 하는 원 위에 있다. 1번은 옳다.","확인":null,"스킬":"S15","고비":true},{"제목":"보기 2 판정","힌트":"$\\angle FAP$ 와 $\\angle PBD$ 는 각각 어느 직각삼각형의 한 각인가?","식":["$\\angle FAP=\\angle BAD=90^{\\circ}-\\angle B$","$\\angle PBD=\\angle EBC=90^{\\circ}-\\angle C$"],"설명":"$P$ 는 $\\overline{AD}$, $\\overline{BE}$ 위의 점이다. 직각삼각형 $ABD$ 에서 $\\angle FAP=90^{\\circ}-\\angle ABC$ 이고, 직각삼각형 $BEC$ 에서 $\\angle PBD=90^{\\circ}-\\angle ACB$ 이다. 두 각이 같으려면 $\\angle ABC=\\angle ACB$ 이어야 하는데 일반적으로 그렇지 않다. 2번은 옳지 않다.","확인":null,"스킬":"S10"},{"제목":"보기 3 판정","힌트":"$\\triangle BFP$ 와 $\\triangle BEA$ 에서 크기가 같은 두 각은 어느 것인가?","식":["$\\triangle BFP\\sim\\triangle BEA$","$\\overline{BF}:\\overline{BE}=\\overline{BP}:\\overline{BA}$"],"설명":"$\\angle B$ 가 공통이고 $\\angle BFP=\\angle BEA=90^{\\circ}$ 이므로 AA 닮음이다. $\\overline{BF}:\\overline{BE}=\\overline{BP}:\\overline{BA}$ 에서 $\\overline{BF}\\cdot\\overline{BA}=\\overline{BP}\\cdot\\overline{BE}$ 이다. 3번은 옳다.","확인":null,"스킬":"S1"},{"제목":"보기 4, 5 판정","힌트":"$\\triangle ABC$ 와 $\\triangle DEC$ 에서 공통인 각 외에 같은 각은 어느 것인가?","식":["$\\angle CDE=\\angle BAC$","$\\angle AFP=\\angle CFB=90^{\\circ}$, $\\angle FAP=\\angle FCB$"],"설명":"$\\angle ADB=\\angle AEB=90^{\\circ}$ 이므로 네 점 $A$, $B$, $D$, $E$ 는 한 원 위에 있고, 내접사각형의 한 외각은 이웃하지 않는 내각과 같아 $\\angle CDE=\\angle BAC$ 이다. $\\angle C$ 가 공통이므로 4번은 AA 닮음으로 옳다. 5번은 $\\angle AFP=\\angle CFB=90^{\\circ}$ 이고 $\\angle FAP=90^{\\circ}-\\angle B=\\angle FCB$ 이므로 AA 닮음으로 옳다. 따라서 옳지 않은 것은 2번이다.","확인":null,"스킬":"S10"}],"fb":"fig/ns/"},"ns-83f584542d4b":{"길":"이웃한 내접원이 닿는 점에서 접선 길이가 같음을 식으로 옮겨 PC, PE 를 차례로 구한다","단계":[{"제목":"$\\overline{PB}$ 위의 접점","힌트":"삼각형의 내접원에서 한 꼭짓점에서 접점까지의 거리는 세 변으로 어떻게 나타나는가?","식":["$\\overline{PT}=\\frac{a+\\overline{PB}-b}{2}$","$\\overline{PT}=\\frac{\\overline{PB}+\\overline{PC}-c}{2}$"],"설명":"원 $O_{1}$ 과 $O_{2}$ 는 $\\overline{PB}$ 의 반대쪽에 있으면서 서로 접하므로 $\\overline{PB}$ 위의 같은 점 $T$ 에서 접한다. 내접원에서 꼭짓점 $P$ 로부터 접점까지의 거리는 (꼭짓점에서 나가는 두 변의 합 $-$ 마주 보는 변) 의 $\\frac{1}{2}$ 이므로 $\\triangle PAB$ 와 $\\triangle PBC$ 에서 각각 위의 두 식이 성립한다.","확인":null,"스킬":"S5","고비":true},{"제목":"$\\overline{PC}$ 의 길이","힌트":"두 식의 값이 같다고 놓으면 $\\overline{PC}$ 는 어떻게 나타나는가?","식":["$a+\\overline{PB}-b=\\overline{PB}+\\overline{PC}-c$","$\\overline{PC}=a-b+c$"],"설명":"두 식이 같으므로 $a+\\overline{PB}-b=\\overline{PB}+\\overline{PC}-c$ 이다. 양변의 $\\overline{PB}$ 를 지우면 $\\overline{PC}=a-b+c$ 이다.","확인":null,"스킬":"S5"},{"제목":"$\\overline{PE}$ 와 $\\overline{PC}$ 의 관계","힌트":"$\\overline{PD}$ 위의 접점에서 같은 방법을 쓰면 어떤 식이 되는가?","식":["$\\frac{\\overline{PC}+\\overline{PD}-d}{2}=\\frac{\\overline{PD}+\\overline{PE}-e}{2}$","$\\overline{PE}=\\overline{PC}-d+e$"],"설명":"원 $O_{3}$ 과 $O_{4}$ 는 $\\overline{PD}$ 위의 한 점에서 접한다. $\\triangle PCD$ 와 $\\triangle PDE$ 에서 점 $P$ 로부터 그 접점까지의 거리를 각각 쓰면 위의 등식이 되고, 양변의 $\\overline{PD}$ 를 지우면 $\\overline{PE}=\\overline{PC}-d+e$ 이다.","확인":null,"스킬":"S5"},{"제목":"$\\overline{PE}$ 의 길이","힌트":"앞에서 구한 $\\overline{PC}$ 를 대입하면 $\\overline{PE}$ 는 어떻게 나타나는가?","식":["$\\overline{PE}=(a-b+c)-d+e$"],"설명":"$\\overline{PC}=a-b+c$ 를 대입하면 $\\overline{PE}=a-b+c-d+e$ 이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-8f022a8ced6d":{"길":"원 위의 점과 비교한 원주각의 크기로 한 점이 다른 원의 안에 있는지 밖에 있는지 판정한다","단계":[{"제목":"안쪽 점과 바깥쪽 점에서 본 각","힌트":"같은 쪽에서 선분 $AC$ 를 보면 원 안의 점과 원 밖의 점에서의 각은 원 위의 점에서의 각과 어떻게 다른가?","식":["$\\angle AEC>\\angle ADC$","$\\angle AFC<\\angle ADC$"],"설명":"그림에서 $D$, $E$, $F$ 는 직선 $AC$ 에 대해 같은 쪽에 있다. $D$ 는 원 $O$ 위, $E$ 는 안, $F$ 는 밖의 점이므로 같은 쪽에서 선분 $AC$ 를 보는 각은 원 위의 점보다 안의 점에서 크고 밖의 점에서 작다. 같은 이유로 선분 $AB$, $BC$ 에 대해서도 같은 쪽의 점끼리 이 크기 관계가 성립한다.","확인":null,"스킬":"S15","고비":true},{"제목":"보기 2 판정","힌트":"$\\angle ABC$ 와 $180^{\\circ}-\\angle AEC$ 의 크기를 비교하면?","식":["$\\angle ABC=180^{\\circ}-\\angle ADC$","$180^{\\circ}-\\angle ADC>180^{\\circ}-\\angle AEC$"],"설명":"$\\square ABCD$ 는 원 $O$ 에 내접하므로 $\\angle ABC=180^{\\circ}-\\angle ADC$ 이다. $\\angle AEC>\\angle ADC$ 이므로 $\\angle ABC>180^{\\circ}-\\angle AEC$ 이다. $B$ 와 $E$ 는 $\\overline{AC}$ 의 반대쪽에 있고, 세 점 $A$, $C$, $E$ 를 지나는 원에서 $E$ 의 반대쪽 호 위의 점은 각이 $180^{\\circ}-\\angle AEC$ 이다. $B$ 는 그보다 각이 크므로 이 원의 내부에 있다. 2번은 옳지 않다.","확인":null,"스킬":"S15"},{"제목":"보기 3 판정","힌트":"$\\angle ABC$ 와 $180^{\\circ}-\\angle AFC$ 의 크기를 비교하면?","식":["$\\angle AFC<\\angle ADC$","$\\angle ABC<180^{\\circ}-\\angle AFC$"],"설명":"$\\angle AFC<\\angle ADC$ 이므로 $180^{\\circ}-\\angle AFC>180^{\\circ}-\\angle ADC=\\angle ABC$ 이다. $B$ 는 세 점 $A$, $C$, $F$ 를 지나는 원의 반대쪽 호보다 각이 작으므로 그 원의 외부에 있다. 3번은 옳다.","확인":null,"스킬":"S15"},{"제목":"보기 1, 4, 5 판정","힌트":"$A$ 와 $F$ 는 $\\overline{BC}$ 에 대해 어느 쪽에 있는가?","식":["$\\angle BFC<\\angle BAC$","$\\angle AFB<\\angle ACB$","$\\angle BAE<\\angle BAD,\\ \\angle BCE<\\angle BCD$"],"설명":"$A$, $F$ 는 $\\overline{BC}$ 의 같은 쪽에 있고 $F$ 는 원 밖이므로 $\\angle BFC<\\angle BAC$ 이다. 그러므로 $A$ 는 세 점 $B$, $C$, $F$ 를 지나는 원의 내부에 있다. 1번은 옳다. $C$, $F$ 는 $\\overline{AB}$ 의 같은 쪽에 있고 $\\angle AFB<\\angle ACB$ 이므로 $C$ 는 세 점 $A$, $B$, $F$ 를 지나는 원의 내부에 있다. 4번은 옳다. $E$ 는 $\\square ABCD$ 의 내부에 있으므로 $\\angle BAE<\\angle BAD$, $\\angle BCE<\\angle BCD$ 이고 두 식을 더하면 $180^{\\circ}$ 보다 작다. 5번은 옳다. 따라서 옳지 않은 것은 2번이다.","확인":null,"스킬":"S15"}],"fb":"fig/ns/"},"ns-b5013f3dae77":{"길":"삼각형의 내각의 합과 원주각의 성질을 이어서 같은 호를 보는 다른 각으로 옮긴다","단계":[{"제목":"$\\triangle APE$ 의 두 내각의 합","힌트":"$\\angle APE=100^{\\circ}$ 일 때 $\\triangle APE$ 의 나머지 두 각의 합은 얼마인가?","식":["$\\angle PAE+\\angle PEA=180^{\\circ}-100^{\\circ}$"],"설명":"$P$ 는 $\\overline{AD}$, $\\overline{BE}$ 위의 점이므로 $\\angle PAE=\\angle DAE$, $\\angle PEA=\\angle BEA$ 이다. $\\triangle APE$ 의 내각의 합에서 $\\angle DAE+\\angle BEA=80^{\\circ}$ 이다.","확인":"80","스킬":"S10"},{"제목":"같은 호의 원주각","힌트":"$\\overset{\\frown}{AE}=\\overset{\\frown}{DE}$ 이면 어느 두 원주각이 같은가?","식":["$\\angle DAE=\\angle ADE$"],"설명":"길이가 같은 호에 대한 원주각은 같다. $\\angle ADE$ 는 호 $AE$ 에 대한 원주각, $\\angle DAE$ 는 호 $DE$ 에 대한 원주각이므로 $\\angle DAE=\\angle ADE$ 이다.","확인":null,"스킬":"S5","고비":true},{"제목":"$\\angle BDE$ 의 크기","힌트":"$\\angle BDE$ 를 $\\angle BDA$ 와 $\\angle ADE$ 로 나누면 각각 어느 각과 같은가?","식":["$\\angle BDA=\\angle BEA$","$\\angle BDE=\\angle BEA+\\angle DAE$"],"설명":"$\\angle BDA$ 와 $\\angle BEA$ 는 호 $AB$ 에 대한 원주각이므로 같다. $\\angle BDE=\\angle BDA+\\angle ADE=\\angle BEA+\\angle DAE$ 이고, 첫째 단계에서 이 합이 $80^{\\circ}$ 이므로 $\\angle BDE=80^{\\circ}$ 이다.","확인":"80","스킬":"S10"},{"제목":"$\\angle BCE$ 의 크기","힌트":"$\\angle BCE$ 와 $\\angle BDE$ 는 어느 호에 대한 원주각인가?","식":["$\\angle BCE=\\angle BDE$"],"설명":"$C$, $D$ 는 선분 $BE$ 의 같은 쪽에 있고 둘 다 호 $BE$ 에 대한 원주각이므로 $\\angle BCE=\\angle BDE=80^{\\circ}$ 이다.","확인":"80","스킬":"S5"}],"fb":"fig/ns/"},"ns-ba6378b2c823":{"길":"교점 각을 호의 합으로 바꾼 뒤 보기마다 호와 원주각으로 참거짓을 가른다","단계":[{"제목":"교점 각을 두 호의 합으로 바꾸기","힌트":"원 안에서 두 현이 만나 이루는 $\\angle APC$ 는 어떤 호들로 정해지는가?","식":["$\\angle APC=\\frac{1}{2}\\left(\\overset{\\frown}{AC}+\\overset{\\frown}{BD}\\right)$","$\\overset{\\frown}{AC}+\\overset{\\frown}{BD}=72^{\\circ}$"],"설명":"원 안에서 두 현이 만날 때 교각의 크기는 마주 보는 두 호의 크기의 합의 절반이다. $\\angle APC$ 가 가리키는 호는 $\\overset{\\frown}{AC}$ 와 $\\overset{\\frown}{BD}$ 이다.","확인":"72","스킬":"S5","고비":true},{"제목":"호 AE 의 크기와 ㉤, ㉢","힌트":"$\\overset{\\frown}{BD}=\\overset{\\frown}{CE}$ 를 쓰면 $\\overset{\\frown}{AE}$ 는 몇 도인가?","식":["$\\overset{\\frown}{AE}=\\overset{\\frown}{AC}+\\overset{\\frown}{CE}=\\overset{\\frown}{AC}+\\overset{\\frown}{BD}=72^{\\circ}$","$\\angle AOE=72^{\\circ},\\ \\angle ABE=36^{\\circ}$"],"설명":"호 AE 는 호 AC 와 호 CE 를 이은 것이다. 길이가 같은 두 호는 크기도 같으므로 $\\overset{\\frown}{CE}=\\overset{\\frown}{BD}$ 이다. 중심각은 호의 크기와 같고 원주각은 그 절반이므로 ㉤ 과 ㉢ 은 옳다.","확인":"72","스킬":"S5"},{"제목":"같은 크기의 호에 대한 원주각 ㉣","힌트":"$\\angle DCB$ 와 $\\angle CBE$ 는 각각 어느 호에 대한 원주각인가?","식":["$\\angle DCB=\\frac{1}{2}\\overset{\\frown}{BD}$","$\\angle CBE=\\frac{1}{2}\\overset{\\frown}{CE}$"],"설명":"$\\angle DCB$ 는 호 BD 에 대한 원주각이고 $\\angle CBE$ 는 호 CE 에 대한 원주각이다. 두 호의 크기가 같으므로 두 각도 같고 ㉣ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"삼각형 PBC 의 외각 ㉦","힌트":"$\\angle APC$ 는 삼각형 PBC 의 어느 두 내각과 관계가 있는가?","식":["$\\angle APC=\\angle PBC+\\angle PCB$"],"설명":"점 P 는 선분 AB 위에 있으므로 $\\angle PBC$ 는 $\\angle ABC$ 와 같다. 삼각형의 외각은 이웃하지 않는 두 내각의 합과 같으므로 $\\angle PCB+\\angle PBC=36^{\\circ}$ 이고 ㉦ 은 옳다.","확인":"36","스킬":"S10"},{"제목":"㉠, ㉡, ㉥ 이 항상 성립하는지 따지기","힌트":"$\\overset{\\frown}{BD}$ 의 크기는 정해지는가?","식":["$\\overset{\\frown}{AC}=72^{\\circ}-\\overset{\\frown}{BD}$"],"설명":"㉠ 은 $\\overset{\\frown}{AC}=36^{\\circ}$ 일 때, ㉡ 과 ㉥ 은 $\\overset{\\frown}{AC}=\\overset{\\frown}{BD}$ 일 때 성립한다. $\\overset{\\frown}{AC}+\\overset{\\frown}{BD}=72^{\\circ}$ 이므로 셋 모두 $\\overset{\\frown}{BD}=36^{\\circ}$ 일 때만 성립한다. 그런데 $\\overset{\\frown}{BD}$ 의 크기는 주어진 조건으로 정해지지 않는다. 예를 들어 $\\overset{\\frown}{BD}=30^{\\circ}$ 이면 $\\overset{\\frown}{AC}=42^{\\circ}$ 이어서 세 보기가 모두 틀린다.","확인":null,"스킬":"S5"},{"제목":"옳은 보기의 개수","힌트":"옳은 보기를 모두 세면 몇 개인가?","식":["$㉢,\\ ㉣,\\ ㉤,\\ ㉦$"],"설명":"옳은 보기는 ㉢, ㉣, ㉤, ㉦ 의 네 개이다.","확인":"4","스킬":"S5"}],"fb":"fig/ns/"},"ns-dee642c2f16b":{"길":"중심에서 보조선을 그어 공통접선 길이를 구하고, 직각삼각형 QAB 에 피타고라스 정리를 쓴다","단계":[{"제목":"두 원의 중심 사이의 거리","힌트":"점 P 에서 외접하는 두 원의 중심 사이의 거리는 반지름과 어떤 관계인가?","식":["$OO'=12+4$"],"설명":"두 원이 점 P 에서 외접하면 중심 O, O' 와 접점 P 는 한 직선 위에 있다. 따라서 중심 사이의 거리는 두 반지름의 합이다.","확인":"16","스킬":"S2"},{"제목":"O' 에서 OA 에 내린 수선","힌트":"O' 에서 OA 에 수선을 그으면 어떤 직각삼각형이 생기는가?","식":["$OH=OA-O'B=12-4$"],"설명":"O' 에서 선분 OA 에 내린 수선의 발을 H 라 한다. 접선은 접점을 지나는 반지름과 수직이므로 $OA\\perp AB$, $O'B\\perp AB$ 이다. 사각형 HABO' 은 직사각형이어서 $HA=O'B=4$ 이고 $OH=8$ 이다.","확인":"8","스킬":"S2","고비":true},{"제목":"공통접선 AB 의 길이","힌트":"직각삼각형 OHO' 에서 $O'H$ 는 얼마인가?","식":["$O'H^2=16^2-8^2=192$","$AB=O'H=8\\sqrt{3}$"],"설명":"삼각형 OHO' 은 $\\angle OHO'=90^{\\circ}$ 인 직각삼각형이므로 피타고라스 정리로 $O'H$ 를 구한다. 직사각형의 마주 보는 변이므로 $AB=O'H$ 이다.","확인":null,"스킬":"S3"},{"제목":"직각삼각형 QAB 에서 QB","힌트":"$\\angle QAB$ 는 몇 도이고, 빗변은 어느 변인가?","식":["$AQ=2\\times12=24$","$QB^2=24^2+(8\\sqrt{3})^2=768$","$QB=16\\sqrt{3}$"],"설명":"AQ 는 원 O 의 지름이고 $OA\\perp AB$ 이므로 $\\angle QAB=90^{\\circ}$ 이다. QB 는 직각삼각형 QAB 의 빗변이므로 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-eedab814da9e":{"길":"접선의 길이가 같다는 성질로 QR 과 둘레를 PA 와 QR 로 나타낸다","단계":[{"제목":"한 점에서 그은 두 접선의 길이","힌트":"원 밖의 한 점 P 에서 그은 두 접선의 길이 사이에는 어떤 관계가 있는가?","식":["$\\overline{PA}=\\overline{PB}$"],"설명":"원 밖의 한 점에서 그 원에 그은 두 접선의 길이는 같다. 따라서 a 는 옳다.","확인":null,"스킬":"S5"},{"제목":"QR 을 접선의 길이로 나타내기","힌트":"점 Q 와 R 에서 그은 접선의 길이를 쓰면 QR 은 무엇의 합인가?","식":["$\\overline{QT}=\\overline{QA},\\ \\overline{RT}=\\overline{RB}$","$\\overline{QR}=\\overline{QT}+\\overline{TR}=\\overline{AQ}+\\overline{BR}$"],"설명":"점 Q 에서 원에 그은 두 접선은 QA 와 QT 이므로 길이가 같다. 점 R 에서도 $\\overline{RT}=\\overline{RB}$ 이다. T 는 선분 QR 위에 있으므로 점 T 가 안쪽에 있든 바깥쪽에 있든 b 는 옳다.","확인":null,"스킬":"S5"},{"제목":"T 가 안쪽일 때의 둘레","힌트":"$\\overline{PQ}+\\overline{AQ}$ 는 어느 선분의 길이와 같은가?","식":["$x=\\overline{PQ}+\\overline{QR}+\\overline{PR}$","$=\\overline{PQ}+\\overline{AQ}+\\overline{PR}+\\overline{BR}$","$=\\overline{PA}+\\overline{PB}=2\\overline{PA}$"],"설명":"T 가 삼각형 PAB 의 안쪽에 있으면 Q, R 는 각각 선분 PA, PB 위에 있다. 그래서 $\\overline{PQ}+\\overline{QA}=\\overline{PA}$, $\\overline{PR}+\\overline{RB}=\\overline{PB}$ 이다. c 는 옳다.","확인":null,"스킬":"S5"},{"제목":"T 가 바깥쪽일 때의 둘레","힌트":"Q, R 는 선분 PA, PB 의 어느 쪽에 놓이는가?","식":["$\\overline{PQ}=\\overline{PA}+\\overline{AQ},\\ \\overline{PR}=\\overline{PB}+\\overline{BR}$","$y=\\overline{PA}+\\overline{PB}+(\\overline{AQ}+\\overline{BR})+\\overline{QR}$","$=2\\overline{PA}+2\\overline{QR}$"],"설명":"T 가 삼각형 PAB 의 바깥쪽에 있으면 Q, R 는 A, B 보다 먼 쪽, 곧 PA, PB 의 연장선 위에 있다. $\\overline{AQ}+\\overline{BR}=\\overline{QR}$ 이므로 $y=2\\overline{PA}+2\\overline{QR}$ 이고 d 는 틀리다.","확인":null,"스킬":"S5","고비":true},{"제목":"옳은 보기 고르기","힌트":"a, b, c, d 중 옳은 것은 어느 것인가?","식":["$a,\\ b,\\ c$"],"설명":"a, b, c 가 옳고 d 가 틀리므로 답은 a, b, c 이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-0dab2b284fe9":{"길":"분산 식을 거꾸로 써서 제곱의 합을 구하고, 바른 값으로 고쳐 분산을 다시 구한다","단계":[{"제목":"처음 자료의 제곱의 합","힌트":"분산을 제곱의 평균과 평균의 제곱으로 쓰면 제곱의 합은 얼마인가?","식":["$\\frac{x_1^2+x_2^2+x_3^2+x_4^2+x_5^2}{5}-10^2=2^2$","$x_1^2+x_2^2+x_3^2+x_4^2+x_5^2=520$"],"설명":"분산은 (제곱의 평균)에서 (평균)의 제곱을 뺀 값이다. 처음 입력한 다섯 값을 $x_1,\\ \\cdots,\\ x_5$ 라 하고 표준편차가 $2$ 이므로 분산은 $4$ 이다.","확인":"520","스킬":"C5","고비":true},{"제목":"바른 자료의 합과 평균","힌트":"잘못 입력된 두 값을 실제 값으로 바꾸면 합은 얼마나 달라지는가?","식":["$5\\times10=50$","$50-(9+11)+(12+13)=55$","$55\\div5=11$"],"설명":"처음 합은 평균 $10$ 에 $5$ 명을 곱한 $50$ 이다. 입력된 $9,\\ 11$ 을 빼고 실제 값 $12,\\ 13$ 을 더한다.","확인":"11","스킬":"C5"},{"제목":"바른 자료의 제곱의 합","힌트":"제곱의 합에서도 같은 두 값만 바꾸면 얼마가 되는가?","식":["$520-(9^2+11^2)+(12^2+13^2)$","$=520-202+313=631$"],"설명":"바뀌는 두 값의 제곱만 빼고 더한다.","확인":"631","스킬":"C5"},{"제목":"실제 분산과 표준편차","힌트":"바른 제곱의 합과 평균으로 분산을 구하면 얼마인가?","식":["$\\frac{631}{5}-11^2=126.2-121=5.2$","$\\sqrt{5.2}$"],"설명":"실제 분산은 $5.2$ 이므로 표준편차는 $\\sqrt{5.2}$ 시간이다.","확인":"5.2","스킬":"C5"}],"fb":"fig/ns/"},"ns-2f6523839077":{"길":"꺾은선그래프에서 인원수를 읽어 반별 중앙값과 최빈값을 구하고 보기를 판정한다","단계":[{"제목":"그래프에서 도수 읽기","힌트":"각 반에서 횟수별 인원은 몇 명인가?","식":["$(1):\\ 2,\\ 3,\\ 4,\\ 2,\\ 1$","$(2):\\ 0,\\ 2,\\ 3,\\ 5,\\ 2$","$(3):\\ 0,\\ 1,\\ 3,\\ 4,\\ 3$"],"설명":"각 줄은 $1$회부터 $5$회까지의 인원이다. 인원 합은 (1)반 $12$명, (2)반 $12$명, (3)반 $11$명이다.","확인":null,"스킬":"C3"},{"제목":"반별 중앙값","힌트":"인원이 $12$명이면 중앙값은 몇 번째와 몇 번째 값으로 정하는가?","식":["$(1):\\ 3,\\ (2):\\ 4,\\ (3):\\ 4$"],"설명":"$12$명인 반은 $6$번째와 $7$번째 값의 평균이고, $11$명인 (3)반은 $6$번째 값이다. 작은 값부터 세면 (1)반은 두 값이 모두 $3$회, (2)반은 모두 $4$회, (3)반의 $6$번째 값은 $4$회이다.","확인":null,"스킬":"C3","고비":true},{"제목":"최빈값과 보기 판정","힌트":"(2)반에서 인원이 가장 많은 횟수는 몇 회인가?","식":["$(2)\\ \\text{최빈값}=4$"],"설명":"(2)반은 $4$회가 $5$명으로 가장 많아 최빈값이 $4$회이다. 그래서 ㄴ 은 옳다. (1)반의 중앙값 $3$회가 가장 작으므로 ㄱ 도 옳다. (2)반과 (3)반의 중앙값이 $4$회로 같아 (3)반이 가장 크다고 할 수 없으므로 ㄷ 은 틀리다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-4cf3c9e27133":{"길":"꺾은선그래프에서 인원수를 읽어 반별 중앙값, 최빈값, 평균을 구하고 보기를 판정한다","단계":[{"제목":"그래프에서 도수 읽기","힌트":"각 반에서 점수별 인원은 몇 명인가?","식":["$(1):\\ 2,\\ 3,\\ 4,\\ 2,\\ 1$","$(2):\\ 0,\\ 1,\\ 3,\\ 5,\\ 2$","$(3):\\ 0,\\ 2,\\ 3,\\ 4,\\ 3$"],"설명":"각 줄은 $1$점부터 $5$점까지의 인원이다. 인원 합은 (1)반 $12$명, (2)반 $11$명, (3)반 $12$명이다.","확인":null,"스킬":"C3"},{"제목":"반별 중앙값으로 ㄱ 판정","힌트":"인원이 짝수인 반과 홀수인 반은 중앙값을 어떻게 정하는가?","식":["$(1):\\ 3,\\ (2):\\ 4,\\ (3):\\ 4$"],"설명":"$12$명인 반은 $6$번째와 $7$번째 값의 평균, $11$명인 (2)반은 $6$번째 값이다. 작은 값부터 세면 (1)반은 $3$점, (2)반은 $4$점, (3)반은 $4$점이다. (1)반이 가장 작으므로 ㄱ 은 옳다.","확인":null,"스킬":"C3","고비":true},{"제목":"(3)반의 최빈값 ㄴ","힌트":"(3)반에서 인원이 가장 많은 점수는 몇 점인가?","식":["$(3):\\ 4\\text{점}\\ 4\\text{명}$"],"설명":"(3)반은 $4$점이 $4$명으로 가장 많아 최빈값이 $4$점이다. ㄴ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"(2)반의 평균 ㄷ","힌트":"(2)반의 점수 합을 인원 수로 나누면 중앙값과 같은가?","식":["$\\frac{2\\times1+3\\times3+4\\times5+5\\times2}{11}=\\frac{41}{11}$"],"설명":"평균은 $\\frac{41}{11}$ 점이고 중앙값은 $4$점이므로 같지 않다. ㄷ 은 틀리다. 따라서 옳은 것은 ㄱ, ㄴ 이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-a800cf9e35ff":{"길":"도수와 편차로 분산식을 세워 $a^2$, $b^2$ 을 구한 뒤 곱한다","단계":[{"제목":"두 자료의 평균","힌트":"도수가 좌우 대칭인 자료의 평균은 어디에 놓이는가?","식":["$A:\\ 3a$","$B:\\ 2b$"],"설명":"A 는 $2a,\\ 3a,\\ 4a$ 의 도수가 $1,\\ 3,\\ 1$ 이고 B 는 $b,\\ 2b,\\ 3b$ 의 도수가 $4,\\ 2,\\ 4$ 이다. 둘 다 가운데 값을 중심으로 좌우 대칭이므로 평균은 가운데 변량이다.","확인":null,"스킬":"A8"},{"제목":"A 의 분산으로 $a^2$ 구하기","힌트":"A 의 분산을 $a$ 로 나타내고 표준편차 조건과 맞추면 어떤 식이 되는가?","식":["$\\frac{(-a)^2\\times1+0^2\\times3+a^2\\times1}{5}=5$","$a^2=\\frac{25}{2}$"],"설명":"A 의 도수 합은 $5$ 이다. 편차는 $-a,\\ 0,\\ a$ 이고 표준편차가 $\\sqrt{5}$ 이므로 분산은 $5$ 이다.","확인":"25/2","스킬":"C7","고비":true},{"제목":"B 의 분산으로 $b^2$ 구하기","힌트":"B 의 분산을 $b$ 로 나타내고 표준편차 조건과 맞추면 어떤 식이 되는가?","식":["$\\frac{(-b)^2\\times4+0^2\\times2+b^2\\times4}{10}=8$","$b^2=10$"],"설명":"B 의 도수 합은 $10$ 이고 편차는 $-b,\\ 0,\\ b$ 이다. 표준편차가 $\\sqrt{8}$ 이므로 분산은 $8$ 이다.","확인":"10","스킬":"C7"},{"제목":"$ab$ 의 값","힌트":"$a>0,\\ b>0$ 일 때 $ab$ 와 $a^2b^2$ 은 어떤 관계인가?","식":["$(ab)^2=\\frac{25}{2}\\times10=125$","$ab=5\\sqrt{5}$"],"설명":"$a,\\ b$ 가 양수이므로 $ab$ 는 $a^2b^2$ 의 양의 제곱근이다.","확인":null,"스킬":"A8"}],"fb":"fig/ns/"},"ns-d463244fdd30":{"길":"세 자료의 평균이 같음을 확인하고 분산을 각각 구해 크기를 비교한다","단계":[{"제목":"세 자료의 평균","힌트":"각 자료의 변량과 도수는 무엇이고 평균은 얼마인가?","식":["$A:\\ 4,5,6\\ \\text{각}\\ 3\\text{개}$","$B:\\ 2\\ (3),\\ 5\\ (2),\\ 8\\ (3)$","$C:\\ 4\\ (2),\\ 5\\ (3),\\ 6\\ (2)$"],"설명":"세 자료 모두 $5$ 를 중심으로 좌우 대칭이다. 평균은 B 가 $\\frac{6+10+24}{8}=5$ 이고 A, C 도 $5$ 이다. 따라서 평균이 가장 높다는 ① 과 B 의 평균이 가장 작다는 ③ 은 틀리다.","확인":"5","스킬":"C3"},{"제목":"세 자료의 분산","힌트":"편차의 제곱의 합을 도수의 합으로 나누면 각 분산은 얼마인가?","식":["$A:\\ \\frac{1\\times3+0+1\\times3}{9}=\\frac{2}{3}$","$B:\\ \\frac{9\\times3+0+9\\times3}{8}=\\frac{27}{4}$","$C:\\ \\frac{1\\times2+0+1\\times2}{7}=\\frac{4}{7}$"],"설명":"평균이 모두 $5$ 이므로 편차는 변량에서 $5$ 를 뺀 값이다.","확인":null,"스킬":"C3","고비":true},{"제목":"분산의 크기 비교","힌트":"$\\frac{2}{3},\\ \\frac{27}{4},\\ \\frac{4}{7}$ 중 가장 작은 것은?","식":["$\\frac{4}{7}<\\frac{2}{3}<\\frac{27}{4}$"],"설명":"C 의 분산이 가장 작다. B 의 분산이 가장 크므로 표준편차도 B 가 가장 크다. ② 는 틀리고 A 와 C 중 C 의 분산이 더 작으므로 ⑤ 도 틀린다. 옳은 것은 ④ 이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-efc68f4aaf91":{"길":"꺾은선그래프에서 도수를 읽어 평균, 중앙값, 분산을 구하고 보기를 판별한다","단계":[{"제목":"그래프에서 도수 읽기","힌트":"A 제품과 B 제품은 각 점수에서 몇 명이 평가했는가?","식":["$A\\ (6\\sim10\\text{점}):\\ 1,\\ 2,\\ 4,\\ 2,\\ 1$","$B\\ (6\\sim9\\text{점}):\\ 2,\\ 4,\\ 3,\\ 1$"],"설명":"두 제품 모두 평가단 $10$ 명의 평점이다. A 는 $6$점부터 $10$점까지, B 는 $6$점부터 $9$점까지의 인원이다.","확인":null,"스킬":"C3"},{"제목":"평균으로 ㄴ 판별","힌트":"각 제품의 점수 합을 $10$ 으로 나누면 평균은 얼마인가?","식":["$A:\\ \\frac{6+14+32+18+10}{10}=8$","$B:\\ \\frac{12+28+24+9}{10}=7.3$"],"설명":"A 의 평균이 B 의 평균보다 크므로 ㄴ 은 옳다.","확인":"8","스킬":"C3","고비":true},{"제목":"중앙값으로 ㄷ 판별","힌트":"$10$ 명의 중앙값은 몇 번째와 몇 번째 값의 평균인가?","식":["$A:\\ 8,\\ B:\\ 7$"],"설명":"중앙값은 $5$번째와 $6$번째 값의 평균이다. 작은 값부터 세면 A 의 두 값은 모두 $8$점, B 의 두 값은 모두 $7$점이다. A 의 중앙값이 더 크므로 ㄷ 은 틀리다.","확인":null,"스킬":"C3"},{"제목":"분산으로 ㄱ 판별","힌트":"더 고르다는 것은 분산이 더 작다는 뜻이다. 두 분산은 각각 얼마인가?","식":["$A:\\ \\frac{4\\times1+1\\times2+0+1\\times2+4\\times1}{10}=1.2$","$B:\\ \\frac{1.69\\times2+0.09\\times4+0.49\\times3+2.89\\times1}{10}=0.81$"],"설명":"B 의 분산이 더 작으므로 B 의 평점이 더 고르다. ㄱ 은 틀리고 옳은 것은 ㄴ 뿐이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"}});
